	LeftElbow = { r15 = { "LeftLowerArm", "LeftElbow" } },
	RightKnee = { r15 = { "RightLowerLeg", "RightKnee" }, knee = true },
	LeftKnee = { r15 = { "LeftLowerLeg", "LeftKnee" }, knee = true },
