	Hips = { r15 = { "LowerTorso", "Root" }, waist = true },
	Neck = { r15 = { "Head", "Neck" }, r6 = { "Torso", "Neck" }, waist = true },
	RightWrist = { r15 = { "RightHand", "RightWrist" }, side = 1 },
	LeftWrist = { r15 = { "LeftHand", "LeftWrist" }, side = -1 },
