local function chargeFist(char, root, time, scale)
	local fist = newPart(Vector3.one * 0.4, CFrame.new(handPos(char, true)), Color3.fromRGB(255, 190, 90), Enum.Material.Neon, Enum.PartType.Ball)
	local core = newPart(Vector3.one * 0.2, CFrame.new(handPos(char, true)), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
	local light = Instance.new("PointLight")
	light.Color = Color3.fromRGB(255, 200, 120)
	light.Range = 16
	light.Brightness = 4
	light.Parent = fist
	tween(fist, time, { Size = Vector3.one * 3.2 * scale })
	tween(core, time, { Size = Vector3.one * 2 * scale })
	local t0 = os.clock()
	while os.clock() - t0 < time and root.Parent do
