-- R special: power up into muscle form / deflate back to true form
local TRANSFORM_DARK = Color3.fromRGB(70, 50, 82)
local TRANSFORM_LIGHT = Color3.fromRGB(138, 82, 112)

-- A voice line (Config.Voice[name]) from someone: the clip you uploaded if
-- the line has an Id, else Roblox's text-to-speech reads it. Louder the
-- closer your camera is; nothing past Range.
-- (round 76) part: a part, or a point. beatAt: seconds from now the line's
-- beat should land on - a clip (from the sound folders: VFX.VC) is lined up
-- to it; text-to-speech just waits for it.
function VFX.Voice(name, part, beatAt)
	local line = Config.Voice and Config.Voice[name]
	local cam = workspace.CurrentCamera
	if not line or not part or not cam then
		return
	end
	if VFX.VC and VFX.VC.has(line) then
		return VFX.VC.play(name, part, beatAt)
	end
	if beatAt and beatAt > 0 then
		task.delay(beatAt, VFX.Voice, name, part)
		return
	end
	local at = typeof(part) == "Vector3" and part or part.Position
	local range = line.Range or 140
	local dist = (cam.CFrame.Position - at).Magnitude
	if dist > range then
		return
	end
	local volume = (line.Volume or 2) * ((Config.Audio and Config.Audio.VoiceVolume) or 1)
		* math.clamp(1 - (dist - range * 0.4) / (range * 0.6), 0, 1)
	if not line.Text then
		return
	end
	-- (the audio API: speech -> wire -> your speakers; pcall: an older
	-- client without it just stays quiet)
	pcall(function()
		local tts = Instance.new("AudioTextToSpeech")
		tts.Name = "Voice_" .. name
		tts.Text = line.Text
		tts.VoiceId = line.VoiceId or "5"
		tts.Pitch = line.Pitch or 0
		tts.Speed = line.Speed or 1
		tts.Volume = volume
		local out = Instance.new("AudioDeviceOutput")
		out.Parent = tts
		local wire = Instance.new("Wire")
		wire.SourceInstance = tts
		wire.TargetInstance = out
		wire.Parent = tts
		tts.Parent = SoundService
		tts:Play()
		Debris:AddItem(tts, 6)
	end)
end

-- (round 76) VOICE CLIPS: the lines in the sound folders in Workspace (see
-- Config.Voice), each one lined up on the moment of the move it belongs to
do
	local VC = { shapes = {}, measuring = {} }
	VFX.VC = VC

	-- the clip a line plays, and how loud: the Sound of that name in its
	-- folder in Workspace if it's there (whatever's in the folder plays),
	-- else the line's own Id
	function VC.source(line)
		local id, vol = line.Id, line.Volume or 0.5
		local ok, snd = pcall(function()
			local f = line.Folder and workspace:FindFirstChild(line.Folder)
			return f and f:FindFirstChild(line.Sound or "")
		end)
		if ok and snd and snd:IsA("Sound") then
			local sid = snd.SoundId
			if type(sid) == "string" and sid ~= "" then
				id = sid
			end
			vol = snd.Volume
		end
		return id, vol
	end

	-- does the line play a clip (rather than text-to-speech)?
	function VC.has(line)
		return line ~= nil and (line.Folder ~= nil or (type(line.Id) == "string" and line.Id ~= ""))
	end

	-- the shape of the speech in a clip, from its loudness over time
	-- (samples: { { seconds into it, level }, ... } in order): First, where
	-- the speech starts; Beat, where its loudest word starts; Cut, where the
	-- phrase that word is in starts (after the last pause before it - nil if
	-- there isn't one); End, where it's over
	function VC.shape(samples)
		local n = #samples
		if n < 10 then
			return nil
		end
		-- (decibels, if that's what the analyser gives: back to a level)
		local dB = false
		for _, sm in samples do
			if sm[2] < 0 then
				dB = true
				break
			end
		end
		local lv = table.create(n, 0)
		for i = 1, n do
			local v = samples[i][2]
			lv[i] = dB and 10 ^ (v / 20) or v
		end
		-- smoothed over a few frames
		local env = table.create(n, 0)
		for i = 1, n do
			local sum, c = 0, 0
			for j = math.max(1, i - 2), math.min(n, i + 2) do
				sum += lv[j]
				c += 1
			end
			env[i] = sum / c
		end
		local peak, at = 0, 1
		for i = 1, n do
			if env[i] > peak then
				peak, at = env[i], i
			end
		end
		if peak <= 1e-5 then
			return nil
		end
		local first, last
		for i = 1, n do
			if env[i] > peak * 0.1 then
				first = first or samples[i][1]
				last = samples[i][1]
			end
		end
		-- the loudest word: back from the peak while it stays loud
		local b = at
		while b > 1 and env[b - 1] > peak * 0.3 and samples[at][1] - samples[b - 1][1] < 0.8 do
			b -= 1
		end
		-- the phrase it's in: back to the last pause (quiet for 0.1s+) - no
		-- further back than 1.5s before the word (a pause before that isn't
		-- this phrase's: no cut)
		local cut, quiet, after = nil, 0, nil
		for i = b - 1, 1, -1 do
			if samples[b][1] - samples[i][1] > 1.5 then
				break
			end
			if lv[i] < peak * 0.12 then
				after = after or samples[i + 1][1]
				quiet += samples[i + 1][1] - samples[i][1]
				if quiet >= 0.1 then
					cut = after
					break
				end
			else
				quiet, after = 0, nil
			end
		end
		return { First = first, Beat = samples[b][1], Cut = cut, End = last, Peak = samples[at][1] }
	end

	-- measure a clip on this machine, once: the audio API plays it into an
	-- analyser (and through a fader at 0, so nobody hears it) and its
	-- loudness is read every frame. Anything missing: the config's numbers.
	function VC.measure(id)
		if type(id) ~= "string" or id == "" or VC.shapes[id] ~= nil or VC.measuring[id] then
			return
		end
		local okc, client = pcall(function()
			return RunService:IsClient()
		end)
		if not okc or not client then
			return
		end
		VC.measuring[id] = true
		task.spawn(function()
			local holder
			local ok, shape = pcall(function()
				holder = Instance.new("Folder")
				holder.Name = "VoiceMeasure"
				local player = Instance.new("AudioPlayer")
				if not pcall(function()
					player.AssetId = id
				end) then
					player.Asset = Content.fromUri(id)
				end
				if typeof(player.TimeLength) ~= "number" then
					return nil
				end
				local analyzer = Instance.new("AudioAnalyzer")
				local fader = Instance.new("AudioFader")
				fader.Volume = 0
				local out = Instance.new("AudioDeviceOutput")
				for _, x in { player, analyzer, fader, out } do
					x.Parent = holder
				end
				for _, pair in { { player, analyzer }, { player, fader }, { fader, out } } do
					local w = Instance.new("Wire")
					w.SourceInstance = pair[1]
					w.TargetInstance = pair[2]
					w.Parent = holder
				end
				holder.Parent = SoundService
				local t0 = os.clock()
				while not player.IsReady and os.clock() - t0 < 20 do
					task.wait(0.1)
				end
				local length = player.TimeLength
				if not player.IsReady or length <= 0 then
					return nil
				end
				player:Play()
				local samples = {}
				local s0 = os.clock()
				while os.clock() - s0 < length + 1.5 do
					RunService.Heartbeat:Wait()
					if player.IsPlaying then
						table.insert(samples, { player.TimePosition, analyzer.RmsLevel })
					elseif os.clock() - s0 > 0.3 then
						break
					end
				end
				local sh = VC.shape(samples)
				if sh then
					sh.Length = length
				end
				return sh
			end)
			if holder then
				holder:Destroy()
			end
			VC.shapes[id] = (ok and shape) or false
			VC.measuring[id] = nil
		end)
	end

	-- where a clip starts, how long to wait first, and where it stops, for its
	-- beat to land beatAt seconds from now (nil: from the top of the speech)
	function VC.plan(line, shape, beatAt)
		shape = shape or {}
		local first = math.max((shape.First or line.First or 0) - 0.04, 0)
		local beat = shape.Beat or line.Beat
		local start, wait = first, 0
		if beatAt and beat then
			local lead = beat - first
			if lead <= beatAt then
				wait = beatAt - lead
			else
				-- (it'd land late from the top: skip in, at most MaxCut of it)
				start = math.max(first, math.min(beat - beatAt, first + (line.MaxCut or 0)))
			end
		end
		local stop = line.Trim and (shape.Cut or line.Cut) or nil
		if stop and stop < start + 0.4 then
			stop = nil
		end
		return start, wait, stop
	end

	-- a line (Config.Voice name) from `where` (a part, or a point), louder the
	-- closer your camera is - nothing past its Range. beatAt: seconds from
	-- now its beat should land on
	function VC.play(name, where, beatAt)
		local line = Config.Voice and Config.Voice[name]
		local cam = workspace.CurrentCamera
		local at = typeof(where) == "Vector3" and where or (typeof(where) == "Instance" and where:IsA("BasePart") and where.Position) or nil
		if not line or not at or not cam then
			return nil
		end
		local id, vol = VC.source(line)
		if type(id) ~= "string" or id == "" then
			return nil
		end
		VC.measure(id)
		local range = line.Range or 160
		local dist = (cam.CFrame.Position - at).Magnitude
		if dist > range then
			return nil
		end
		local near = math.clamp(1 - (dist - range * 0.4) / (range * 0.6), 0, 1)
		local shape = VC.shapes[id] or nil
		local start, wait, stop = VC.plan(line, shape, beatAt)
		local s = Instance.new("Sound")
		s.Name = "Voice_" .. name
		s.SoundId = id
		s.Volume = math.clamp((vol or 0.5) * (line.Gain or 2) * near * ((Config.Audio and Config.Audio.VoiceVolume) or 1), 0, 10)
		s.SoundGroup = SoundService:FindFirstChild("QuirkSFX")
		s.Parent = SoundService
		Debris:AddItem(s, wait + math.max(((shape and shape.Length) or line.Length or 10) - start, 1) + 0.5)
		task.delay(wait, function()
			if not s.Parent then
				return
			end
			local t0 = os.clock()
			s.TimePosition = start
			s:Play()
			if start > 0 and not s.IsLoaded then
				-- (still downloading: it'd start from the top once it loads)
				s.Loaded:Once(function()
					s.TimePosition = start + (os.clock() - t0)
				end)
			end
			if stop then
				-- trimmed: out just before the last phrase
				task.delay(math.max(stop - start - 0.05, 0), function()
					if s.Parent then
						tween(s, 0.1, { Volume = 0 })
						task.delay(0.11, function()
							pcall(function()
								s:Stop()
							end)
						end)
					end
				end)
			end
		end)
		return s
	end

	-- the lines that go off as a move does (Config.VoiceCues.Moves) - only
	-- for players (a training dummy's counter stance says nothing)
	function VC.onPlay(effectId, char)
		local cues = Config.VoiceCues and Config.VoiceCues.Moves
		local list = cues and cues[effectId]
		if not list or typeof(char) ~= "Instance" or not Players:GetPlayerFromCharacter(char) then
			return
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		if root then
			for _, name in list do
				VFX.Voice(name, root)
			end
		end
	end

	-- every clip downloaded (and measured) up front, on players' machines
	task.spawn(function()
		local okc, client = pcall(function()
			return RunService:IsClient()
		end)
		if not okc or not client then
			return
		end
		pcall(function()
			if not game:IsLoaded() then
				game.Loaded:Wait()
			end
		end)
		local list = {}
		for _, line in Config.Voice or {} do
			if VC.has(line) then
				local id = VC.source(line)
				if type(id) == "string" and id ~= "" then
					local s = Instance.new("Sound")
					s.SoundId = id
					table.insert(list, s)
					VC.measure(id)
				end
			end
		end
		-- (round 77) and every sound layer that starts at its peak
		for _, cue in Config.Sounds or {} do
			if type(cue) == "table" then
				for _, layer in ipairs(cue.Id ~= nil and { cue } or cue) do
					if type(layer) == "table" and layer.Peak then
						for _, take in ipairs(type(layer.Id) == "table" and layer.Id or { layer.Id }) do
							VC.measure(type(take) == "table" and take.Id or take)
						end
					end
				end
			end
		end
		pcall(function()
			game:GetService("ContentProvider"):PreloadAsync(list)
		end)
	end)
end

-- (round 76) an emote's song: a Sound called after the emote (its Name or
-- Id) in a folder called Emotes in Workspace - or right in Workspace, or in a
-- folder of that name - else its Song id, else its FallbackSong. Returns the
-- id, the volume and where to start, or nil.
function VFX.EmoteSong(entry)
	local function find(container)
		if not container then
			return nil
		end
		for _, key in { entry.Name, entry.Id } do
			local s = type(key) == "string" and container:FindFirstChild(key)
			if s then
				if s:IsA("Sound") then
					return s
				end
				local inner = s:FindFirstChildWhichIsA("Sound")
				if inner then
					return inner
				end
			end
		end
		return nil
	end
	local ok, snd = pcall(function()
		return find(workspace:FindFirstChild("Emotes")) or find(workspace)
	end)
	if ok and snd and type(snd.SoundId) == "string" and snd.SoundId ~= "" then
		return snd.SoundId, math.clamp(snd.Volume * 1.6, 0, 3), entry.SongStart or 0
	end
	if type(entry.Song) == "string" and entry.Song ~= "" then
		return entry.Song, entry.Volume or 0.8, entry.SongStart or 0
	end
	if type(entry.FallbackSong) == "string" and entry.FallbackSong ~= "" then
		return entry.FallbackSong, entry.FallbackVolume or 0.7, entry.FallbackStart or 0
	end
	return nil
end

-- A comic speech bubble over someone's head (everyone sees it)
function VFX.SpeechBubble(char, text, life)
	local head = char and (char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart"))
	if not head or not text then
		return
	end
	local bb = Instance.new("BillboardGui")
	bb.Name = "SpeechBubble"
	bb.Adornee = head
	bb.Size = UDim2.fromOffset(260, 70)
	bb.StudsOffsetWorldSpace = Vector3.new(0, 4.5, 0)
	bb.AlwaysOnTop = true
	bb.MaxDistance = 160
	bb.LightInfluence = 0
	bb.Parent = folder
	local bubble = Instance.new("TextLabel")
	bubble.AnchorPoint = Vector2.new(0.5, 0.5)
	bubble.Position = UDim2.fromScale(0.5, 0.5)
	bubble.Size = UDim2.fromScale(0.2, 0.2)
	bubble.BackgroundColor3 = Color3.new(1, 1, 1)
	bubble.Font = Enum.Font.Bangers
	bubble.TextScaled = true
	bubble.TextColor3 = Color3.fromRGB(20, 20, 30)
	bubble.Text = text
	bubble.Parent = bb
	local c = Instance.new("UICorner")
	c.CornerRadius = UDim.new(0.3, 0)
	c.Parent = bubble
	local st = Instance.new("UIStroke")
	st.Thickness = 3
	st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	st.Parent = bubble
	local pad = Instance.new("UIPadding")
	pad.PaddingLeft = UDim.new(0.08, 0)
	pad.PaddingRight = UDim.new(0.08, 0)
	pad.PaddingTop = UDim.new(0.1, 0)
	pad.PaddingBottom = UDim.new(0.1, 0)
	pad.Parent = bubble
	tween(bubble, 0.18, { Size = UDim2.fromScale(1, 1) }, Enum.EasingStyle.Back)
	task.delay(life or 1.8, function()
		tween(bubble, 0.2, { Size = UDim2.fromScale(0.1, 0.1), TextTransparency = 1, BackgroundTransparency = 1 })
		tween(st, 0.2, { Transparency = 1 })
		task.wait(0.22)
		bb:Destroy()
	end)
end

-- (round 73) THE TRANSFORMATION'S BODY: hunched over clenched fists,
-- shaking with it and rising as he grows (timed to Presence.BurstAt); then out
-- of the steam arms flung wide, chest out - and into the flex
do
	local P = (Config.Quirks.OneForAll and Config.Quirks.OneForAll.Special or {}).Presence or {}
	local burstAt = P.BurstAt or 1.35
	local m = { { pose = {
		Waist = { -26, 0, 0 }, Neck = { 26, 0, 0 }, RightArm = { 26, 0, -16 }, LeftArm = { 26, 0, -16 }, RightElbow = 100, LeftElbow = 100,
		RightLeg = 14, LeftLeg = -8, RightKnee = 30, LeftKnee = 20, Crouch = 0.6,
	}, t = 0.22, hold = 0.04, style = Enum.EasingStyle.Sine }, recover = 0.3 }
	local shakes = 12
	local each = math.max(burstAt - 0.3, 0.3) / shakes
	for k = 1, shakes do
		local s = k % 2 == 0 and 1 or -1
		local up = k / shakes
		table.insert(m, { pose = {
			Waist = { -26 + 18 * up, 3 * s, 3 * s }, Neck = { 26 - 22 * up, 0, 4 * s }, RightArm = { 26 - 6 * up, 0, -16 + 30 * up }, LeftArm = { 26 - 6 * up, 0, -16 + 30 * up },
			RightElbow = 100, LeftElbow = 100, RightLeg = 14, LeftLeg = -8, RightKnee = 30 - 12 * up, LeftKnee = 20 - 8 * up, Crouch = 0.6 * (1 - up * 0.6),
		}, t = each * 0.45, hold = each * 0.55 })
	end
	MOTIONS.MightBuild = m
	MOTIONS.MightReveal = {
		{ pose = {
			Waist = { 16, 0, 0 }, Neck = { -20, 0, 0 }, RightArm = { 30, 0, 82 }, LeftArm = { 30, 0, 82 }, RightElbow = 10, LeftElbow = 10,
			RightLeg = { 0, 0, 12 }, LeftLeg = { 0, 0, 12 },
		}, t = 0.06, hold = 0.45, style = Enum.EasingStyle.Back },
		{ pose = {
			RightArm = { 100, 0, 70 }, RightElbow = 125, LeftArm = { 100, 0, 70 }, LeftElbow = 125, Waist = { 10, 0, 0 }, Neck = { -12, 0, 0 },
			RightLeg = { 0, 0, 10 }, LeftLeg = { 0, 0, 10 },
		}, t = 0.14, hold = 0.9, style = Enum.EasingStyle.Back },
		recover = 0.4,
	}
end

function Effects.MuscleForm(char, data)
	local root = charParts(char)
	if not root then
		return
	end
	local g = groundPoint(root.Position)
	if data.Alt then
		-- (round 73) THE TRANSFORMATION. The weak man powers up in heartbeats:
		-- hunched, fists clenched, shaking with it - a dark silhouette in a
		-- gold outline, gold lightning crawling over him, the wind sucked in
		-- to him, the street cracking and the rubble lifting. Each heartbeat
		-- (Presence.Pulses) he grows a step (the server scales him) and steam
		-- jets out of him; the steam closes in round him with a gold light
		-- burning inside it - and he BURSTS out (BurstAt) in the costume, the
		-- bangs sprung up, his face in shadow but for the eyes: "I AM HERE!"
		-- He's steaming for a while after. (His presence: anyone close froze
		-- - the server holds them - and the burst throws them back.)
		local P = (Config.Quirks.OneForAll and Config.Quirks.OneForAll.Special or {}).Presence or {}
		local burstAt = P.BurstAt or 1.35
		local pulses = P.Pulses or {}
		local t0 = os.clock()
		local function upTo(t)
			local w = t - (os.clock() - t0)
			if w > 0 then
				task.wait(w)
			end
			return root.Parent ~= nil
		end
		local near = nearCamera(root.Position, 70)
		local me = Players.LocalPlayer
		local mine = me ~= nil and me.Character == char
		VFX.Motion(char, "MightBuild")
		VFX.PlaySound("MuscleRumble", g, 1)
		-- (round 76) "I AM HERE!" from the All Might folder, started so its
		-- last, loudest word lands on the burst
		VFX.Voice("IAmHere", root, burstAt)
		VFX.PlaySound("Wind", g, 0.6)
		VFX.ShakeAt(g, 0.7, 60, burstAt)
		if near then
			VFX.Hooks.Dim(0.45, burstAt + 0.2)
		end
		if mine then
			VFX.Hooks.Letterbox(true, "ALL MIGHT", "ONE FOR ALL", GOLD)
			task.delay(burstAt + 1.2, function()
				VFX.Hooks.Letterbox(false)
			end)
		end
		-- a dark figure in a gold outline
		local aura = Instance.new("Highlight")
		aura.Name = "MightAura"
		aura.FillColor = Color3.fromRGB(12, 10, 18)
		aura.FillTransparency = 0.55
		aura.OutlineColor = GOLD
		aura.OutlineTransparency = 0.1
		aura.DepthMode = Enum.HighlightDepthMode.Occluded
		aura.Adornee = char
		aura.Parent = folder
		tween(aura, burstAt * 0.8, { FillTransparency = 0.25 }, Enum.EasingStyle.Sine)
		cleanup(aura, burstAt + 0.4)
		-- a gold light building inside him
		local core = newPart(Vector3.one * 0.2, root.CFrame, GOLD, Enum.Material.Neon, Enum.PartType.Ball)
		core.Transparency = 1
		local glow = Instance.new("PointLight")
		glow.Color = GOLD
		glow.Range = 18
		glow.Brightness = 0
		glow.Parent = core
		tween(glow, burstAt, { Brightness = 7 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		cleanup(core, burstAt + 0.5)
		-- the ground gives under him: dark cracks racing out from his feet
		local CRACK = Color3.fromRGB(26, 22, 26)
		for i = 1, 11 do
			local a = i / 11 * math.pi * 2 + rand(-0.2, 0.2)
			task.spawn(function()
				local prev = g + UP * 0.08
				for k = 1, 5 do
					local bend = a + rand(-0.35, 0.35)
					local nextP = groundPoint(g + Vector3.new(math.cos(bend), 0, math.sin(bend)) * (k * 2.6 + rand(0, 1))) + UP * 0.08
					local len = (nextP - prev).Magnitude
					local seg = newPart(Vector3.new(0.4 - k * 0.05, 0.1, 0.1), CFrame.lookAt(prev, nextP) * CFrame.new(0, 0, -0.05), CRACK, Enum.Material.Slate)
					tween(seg, 0.14, { Size = Vector3.new(0.4 - k * 0.05, 0.1, len), CFrame = CFrame.lookAt((prev + nextP) / 2, nextP) })
					tween(seg, 1.5, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 3.5)
					cleanup(seg, 5.1)
					prev = nextP
					task.wait(burstAt / 6)
				end
			end)
		end
		-- ...and the rubble lifts off the street round him, hanging in the air
		local rubble = {}
		local floor = groundRay(root.Position, 40)
		local stone = floor and floor.Instance:IsA("BasePart") and not floor.Instance:IsA("Terrain") and floor.Instance.Color
			or Color3.fromRGB(120, 110, 105)
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2 + rand(-0.25, 0.25)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local at = groundPoint(g + out * rand(4.5, 11)) + UP * 0.3
			local sz = rand(0.5, 1.4)
			local rock = newPart(Vector3.new(sz, sz * rand(0.5, 0.9), sz * rand(0.7, 1.2)), CFrame.new(at) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), stone:Lerp(Color3.new(), rand(0.05, 0.3)), Enum.Material.Slate)
			tween(rock, burstAt * 0.9, { CFrame = CFrame.new(at + UP * rand(1.5, 5)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Sine, nil, i * 0.03)
			rubble[i] = { Part = rock, Out = out }
			cleanup(rock, burstAt + 1.7)
		end
		-- all through it: the wind sucked in to him, gold lightning crawling
		-- over him, dark pressure rising off him
		task.spawn(function()
			while os.clock() - t0 < burstAt - 0.05 and root.Parent do
				local c = root.Position
				for _ = 1, 3 do
					local a = rand(0, math.pi * 2)
					local out = Vector3.new(math.cos(a), rand(-0.1, 0.35), math.sin(a)).Unit
					streaks(c + out * 16, -out, 2, 1, 4, 12, WIND, 0.3)
				end
				bolt(c + UP * rand(-1, 2), 2.4, GOLD)
				if rng:NextNumber() < 0.5 then
					bolt(c + UP * rand(-1, 2), 2.4, Color3.new(1, 1, 1))
				end
				streaks(g, UP, 2, 3, 5, 14, TRANSFORM_DARK, 0.4)
				task.wait(0.1)
			end
		end)
		-- THE HEARTBEATS: each one he grows (the server scales him), a ring of
		-- pressure off him, steam jetting out of him, the flash of the outline
		for i, pulse in pulses do
			if not upTo(pulse[1]) then
				return
			end
			local c = root.Position
			local gg = groundPoint(c)
			VFX.PlaySound("MuscleThump", gg, 0.75 + 0.15 * i)
			billboardRing(c, 2 + i, 14 + i * 6, TRANSFORM_LIGHT, 10, 0.25)
			billboardRing(c, 2, 10 + i * 4, GOLD, 6, 0.2)
			shockDisc(gg + UP * 0.3, UP, 2, 12 + i * 7, 0.3, TRANSFORM_LIGHT)
			dustPuffs(gg, 0.8 + i * 0.2, 4, Color3.fromRGB(206, 196, 186), 0.7, true)
			for _, limbName in { "Torso", "Right Arm", "Left Arm", "UpperTorso", "RightUpperArm", "LeftUpperArm" } do
				local limb = char:FindFirstChild(limbName)
				if limb and limb:IsA("BasePart") then
					local out = (limb.Position - c)
					out = Vector3.new(out.X, 0, out.Z)
					out = (out.Magnitude > 0.1 and out.Unit or root.CFrame.LookVector) + UP * 0.5
					celPuff(folder, limb.Position, limb.Position + out * rand(3, 5), rand(1.6, 2.6), Color3.fromRGB(206, 206, 214), STEAM, 0.18, 0.55)
				end
			end
			aura.FillTransparency = 0.05
			tween(aura, 0.22, { FillTransparency = 0.45 - i * 0.08 })
			VFX.ShakeAt(gg, 0.6 + 0.5 * i, 70, 0.3)
			if near then
				VFX.Hooks.Flash(Color3.fromRGB(255, 236, 170), 0.08)
			end
		end
		-- the steam closes in round him, a gold light burning inside it
		if not upTo(burstAt - 0.32) then
			return
		end
		smokeEngulf(char, root, Color3.fromRGB(190, 190, 200), STEAM, 0.32, 7) -- (white steam: the classic)
		VFX.PlaySound("Wind", g, 0.9)
		if not upTo(burstAt - 0.1) then
			return
		end
		VFX.PlaySound("MuscleThump", g, 1.3)
		billboardRing(root.Position, 3, 18, TRANSFORM_DARK, 10, 0.2)
		if nearCamera(root.Position, 45) then
			VFX.Hooks.Flash(Color3.new(0, 0, 0), 0.1)
		end
		if not upTo(burstAt) then
			return
		end
		-- THE BURST
		aura:Destroy()
		g = groundPoint(root.Position)
		VFX.Motion(char, "MightReveal")
		billboardRing(root.Position, 4, 40, GOLD, 10, 0.4)
		billboardRing(root.Position, 2, 26, Color3.new(1, 1, 1), 0, 0.22, true)
		shockDisc(g + UP * 0.4, UP, 4, 70, 0.5, GOLD)
		shockDisc(g + UP * 1.2, UP, 4, 48, 0.38, WIND)
		shockDisc(root.Position, UP, 6, 36, 0.3, Color3.new(1, 1, 1))
		streaks(root.Position, UP, 30, 5, 12, 50, GOLD, 0.5)
		for k = 0, 11 do
			local a = k / 12 * math.pi * 2
			streaks(root.Position, Vector3.new(math.cos(a), 0.15, math.sin(a)), 2, 1.5, 8, 30, WIND, 0.35)
		end
		for i = 1, 12 do
			local a = i / 12 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0.2, math.sin(a))
			celPuff(folder, root.Position, root.Position + out * 14, rand(4, 6.5), i % 3 == 0 and TRANSFORM_DARK or Color3.fromRGB(200, 200, 208), i % 3 == 0 and TRANSFORM_LIGHT or STEAM, 0.2, 0.5)
		end
		-- steam: a column boiling up off him and a ring rolling out at his feet
		for k = 1, 8 do
			celPuff(folder, root.Position, root.Position + UP * (k * 2.4) + Vector3.new(rand(-1.5, 1.5), 0, rand(-1.5, 1.5)), rand(3.5, 6), Color3.fromRGB(206, 206, 214), STEAM, 0.25, 1, k * 0.03)
		end
		for i = 1, 16 do
			local a = i / 16 * math.pi * 2
			celPuff(folder, g + UP, g + UP * 1.5 + Vector3.new(math.cos(a), 0, math.sin(a)) * 15, rand(3, 5), Color3.fromRGB(206, 206, 214), STEAM, 0.3, 0.8)
		end
		-- the rubble blasted away
		for _, r in rubble do
			if r.Part.Parent then
				local dest = r.Part.Position + r.Out * rand(16, 28) + UP * rand(2, 8)
				tween(r.Part, 0.45, { CFrame = CFrame.new(dest) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Transparency = 1 })
			end
		end
		rocks(g, 1.6, 10)
		groundMark(g, 9, Color3.fromRGB(38, 32, 34), 6)
		dustPuffs(g, 1.8, 10, Color3.fromRGB(206, 196, 186), 1.2, true)
		if nearCamera(root.Position, 60) then
			VFX.ImpactFrame(0.07)
			task.delay(0.07, function()
				VFX.Hooks.Flash(Color3.fromRGB(255, 240, 190), 0.28)
			end)
		end
		VFX.PlaySound("Transform", g, 1)
		VFX.ShakeAt(g, 3.2, 120, 0.6)
		-- the face in shadow, only the eyes burning through it
		local head = char:FindFirstChild("Head")
		if head and head:IsA("BasePart") then
			local v = (head:IsA("MeshPart") or not head:FindFirstChildOfClass("SpecialMesh")) and head.Size or Vector3.one * head.Size.Y * 1.2
			local shade = Instance.new("Highlight")
			shade.Name = "HeroShadow"
			shade.FillColor = Color3.new(0, 0, 0)
			shade.FillTransparency = 0.22
			shade.OutlineTransparency = 1
			shade.DepthMode = Enum.HighlightDepthMode.Occluded
			shade.Adornee = head
			shade.Parent = folder
			local eyes = {}
			for _, side in { -1, 1 } do
				local eye = newPart(Vector3.new(v.X * 0.17, v.Y * 0.08, 0.12), head.CFrame, Color3.fromRGB(150, 225, 255), Enum.Material.Neon)
				local w = Instance.new("Weld")
				w.Part0 = head
				w.Part1 = eye
				w.C0 = CFrame.new(side * v.X * 0.19, v.Y * 0.08, -v.Z * 0.47) * CFrame.Angles(0, 0, math.rad(side * 10))
				w.Parent = eye
				eye.Anchored = false
				eye.Massless = true
				table.insert(eyes, eye)
			end
			local eyeGlow = Instance.new("PointLight")
			eyeGlow.Color = Color3.fromRGB(150, 225, 255)
			eyeGlow.Range = 5
			eyeGlow.Brightness = 2.5
			eyeGlow.Parent = eyes[1]
			task.delay(2.8, function()
				tween(shade, 0.8, { FillTransparency = 1 })
				tween(eyeGlow, 0.8, { Brightness = 0 })
				for _, eye in eyes do
					tween(eye, 0.8, { Transparency = 1 })
				end
			end)
			cleanup(shade, 3.7)
			for _, eye in eyes do
				cleanup(eye, 3.7)
			end
		end
		-- "I AM HERE!" - the entrance line, as he bursts out of the steam
		-- (round 76: it was started at the beginning, so "HERE!" is now)
		local line = Config.Voice and Config.Voice.IAmHere
		VFX.SpeechBubble(char, line and line.Bubble or "I AM HERE!", 1.8)
		VFX.PlaySound("IAmHere", g, 1)
		-- and he's steaming for a while after
		task.spawn(function()
			local s0 = os.clock()
			while os.clock() - s0 < 2.6 and root.Parent do
				local limb = char:FindFirstChild(rng:NextNumber() < 0.5 and "Right Arm" or "Left Arm") or char:FindFirstChild("Torso") or root
				if limb:IsA("BasePart") then
					local p = limb.Position + Vector3.new(rand(-0.6, 0.6), rand(0, 1), rand(-0.6, 0.6))
					celPuff(folder, p, p + UP * rand(2, 3.5), rand(0.9, 1.5), Color3.fromRGB(214, 214, 222), STEAM, 0.2, 0.7)
				end
				task.wait(0.16)
			end
		end)
	else
		-- the classic deflate: a huge puff of steam
		smokeEngulf(char, root, Color3.fromRGB(196, 196, 204), STEAM, 0.5, 5)
		shockDisc(root.Position, UP, 2, 16, 0.3, STEAM)
		VFX.PlaySound("Wind", root.Position, 0.5)
		VFX.ShakeAt(root.Position, 0.5, 30, 0.15)
	end
end

-- Caught in All Might's presence as he powers up (sent to the one frozen):
-- the screen darkens round you and the word says what your legs already know
function Effects.Terrified(_, data)
	VFX.Hooks.Callout("TERRIFIED", Color3.fromRGB(150, 225, 255))
	VFX.Hooks.Dim(0.3, 0.6)
	local from = typeof(data.From) == "Instance" and data.From:FindFirstChild("HumanoidRootPart")
	if from then
		VFX.ShakeAt(from.Position, 0.9, 40, 0.6)
	end
end

-- Super leap (All Might passive): jump again in mid-air to launch
function Effects.SuperLeap(char, _data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	VFX.Pose(char, "Skydive", 1.4)
	local pos = root.Position - UP * 2.5
	shockDisc(pos, UP, 3, 26, 0.35, WIND)
	billboardRing(pos, 3, 18, Color3.new(1, 1, 1), 6, 0.3)
	dustPuffs(pos, 1.2, 6, Color3.fromRGB(206, 196, 186), 0.9, true)
	streaks(pos, -UP, 14, 3, 8, 20, WIND, 0.3)
	local stopTrail = addTrail(root, WIND, 0.35, 2.5)
	if isLocal then
		VFX.Hooks.SpeedLines(1.2)
	end
	VFX.PlaySound("Leap", pos, 1)
	task.delay(1.2, function()
		stopTrail(0)
	end)
end

-- Server: the landing slam after a super leap
function Effects.SuperLand(char, data)
	local root = charParts(char)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and groundPoint(root.Position))
	if not pos then
		return
	end
	if root then
		VFX.Pose(char, "Land", 0.45)
	end
	shockDisc(pos + UP * 0.5, UP, 4, 44, 0.45, WIND)
	billboardRing(pos + UP, 4, 30, Color3.new(1, 1, 1), 8, 0.35)
	for i = 1, 10 do
		local a = i / 10 * math.pi * 2
		dustPuffs(pos + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(5, 10), 1.4, 2, Color3.fromRGB(206, 196, 186), 1.2, true)
	end
	rocks(pos, 1.8, 10)
	groundMark(pos, 7, Color3.fromRGB(52, 46, 44), 6)
	VFX.PlaySound("Smash", pos, 0.9)
	VFX.ShakeAt(pos, 2.2, 110, 0.4)
end

-- HALF-COLD ----------------------------------------------------------------

function Effects.IceSpike(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
	end
	VFX.Pose(char, "Ground", 0.45)
	task.wait(0.12)
	if not root.Parent then
		return
	end
	local model, origin = spikeLayout("IceSpike", data, root, d)
	frostMist(origin + d * 20, 0.8, 6)
	VFX.PlaySound("Ice", origin, 0.8)
	VFX.ShakeAt(origin, 0.8, 60, 0.25)
	task.wait((ability and ability.IceDuration) or 3)
	shatter(model, 40)
end

function Effects.FrostBurst(char, data, _isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	VFX.Pose(char, "Ground", 0.4)
	task.wait(0.15)
	if not root.Parent then
		return
	end
	local model, origin = spikeLayout("FrostBurst", data, root, flatten(data.Dir, root))
	shockDisc(origin + Vector3.new(0, 0.5, 0), UP, 4, 36, 0.4, ICE_TIP)
	frostMist(origin, 1.2, 10)
	VFX.PlaySound("Ice", origin, 0.9)
	VFX.ShakeAt(origin, 1.2, 70, 0.3)
	task.wait((ability and ability.IceDuration) or 3)
	shatter(model, 50)
end

-- HEAVEN-PIERCING ICE WALL (ult): the stomp, then a glacier from his foot
-- that fans out across the street and climbs past the rooftops into the
-- sky as it runs out ahead of him. Frost races along the street ahead of
-- it, the air goes cold and blue, the spire at the far end punches a hole
-- through the clouds, and snow drifts down off it while it stands.
function Effects.IceWall(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
		VFX.Hooks.Dim(0.35, 0.55)
	end
	cinematicFor(char, "IceWall", isLocal, (ability and ability.Name) or "HEAVEN-PIERCING ICE WALL", ICE_TIP)
	VFX.Motion(char, "IceWall")
	local g0 = groundPoint(root.Position)
	frostMist(g0 + d * 2, 0.6, 4)
	-- the stomp freezes the street: frost cracks race out ahead, fanning wide
	local HV = SpikeLayouts.HEAVEN or {}
	local L, H, W = HV.Length or 200, HV.Height or 330, HV.Width or 170
	local right = d:Cross(UP)
	for lane = -3, 3 do
		task.spawn(function()
			local prev = g0 + d * 2
			for k = 1, 12 do
				local s = k / 12 * L
				local spread = 7 + s * (W / 2 - 7) / L
				local nextP = groundPoint(g0 + d * s + right * (lane / 3) * spread * 0.9 + right * rand(-4, 4)) + UP * 0.25
				local seg = newPart(Vector3.new(0.35, 0.12, (nextP - prev).Magnitude), CFrame.lookAt((prev + nextP) / 2, nextP), Color3.fromRGB(150, 225, 255), Enum.Material.Neon)
				seg.Transparency = 0.15
				tween(seg, 1.4, { Transparency = 1, Color = Color3.fromRGB(230, 248, 255) }, Enum.EasingStyle.Quad, nil, 0.9)
				cleanup(seg, 2.5)
				prev = nextP
				task.wait(L / 12 / 260)
			end
		end)
	end
	task.wait(0.55)
	if not root.Parent then
		return
	end
	local model, origin = spikeLayout("IceWall", data, root, d, Color3.fromRGB(36, 84, 116))
	-- the air goes cold: everything nearby tints icy blue for a moment
	if nearCamera(origin + d * L * 0.5, L * 1.6) then
		local tint = Instance.new("ColorCorrectionEffect")
		tint.Name = "IceWallTint"
		tint.TintColor = Color3.fromRGB(200, 232, 255)
		tint.Saturation = -0.15
		tint.Brightness = 0.05
		tint.Parent = game:GetService("Lighting")
		tween(tint, 2.6, { TintColor = Color3.new(1, 1, 1), Saturation = 0, Brightness = 0 }, Enum.EasingStyle.Sine, nil, 1)
		cleanup(tint, 3.8)
	end
	-- a wall of freezing mist rolling along its base, the whole width
	for s = 10, L, 14 do
		task.delay(s / 160, function()
			local spread = 7 + s * (W / 2 - 7) / L
			for _ = 1, 2 do
				frostMist(origin + d * s + right * rand(-spread, spread) + Vector3.new(0, rand(4, 30), 0), 2.6, 4)
			end
			VFX.ShakeAt(origin + d * s, 1.6, 150, 0.2)
		end)
	end
	-- the spire breaks the clouds: a ring of cloud blown out round its tip,
	-- light pouring down through the hole, a shock ring across the sky
	task.delay(L / 160 + 0.25, function()
		local peak = origin + d * L * 0.95 + UP * H * 0.92
		shockDisc(peak, UP, 20, 260, 1.4, Color3.fromRGB(240, 248, 255))
		billboardRing(peak, 20, 220, Color3.fromRGB(235, 246, 255), 14, 0.9)
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local puff = newPart(Vector3.new(16, 8, 16), CFrame.new(peak + out * 30), Color3.fromRGB(245, 250, 255), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.25
			tween(puff, 2.4, { Size = Vector3.new(60, 18, 60), CFrame = CFrame.new(peak + out * rand(110, 150) + UP * rand(-6, 10)), Transparency = 1 }, Enum.EasingStyle.Quad)
			cleanup(puff, 2.5)
		end
		for _ = 1, 7 do
			local from = peak + UP * 120 + Vector3.new(rand(-30, 30), 0, rand(-30, 30))
			local to = origin + d * L * rand(0.5, 1) + right * rand(-W / 3, W / 3)
			local shaft = newPart(Vector3.new(rand(3, 7), rand(3, 7), (to - from).Magnitude), CFrame.lookAt((from + to) / 2, to), Color3.fromRGB(230, 244, 255), Enum.Material.Neon)
			shaft.Transparency = 1
			tween(shaft, 0.35, { Transparency = 0.7 })
			tween(shaft, 1.6, { Transparency = 1 }, Enum.EasingStyle.Sine, nil, 0.6)
			cleanup(shaft, 2.4)
		end
		frostMist(peak, 4, 12)
		sparks(peak, 5, ICE_TIP, Color3.fromRGB(120, 200, 255), 80)
		VFX.PlaySound("IceWallRise", peak, 1)
	end)
	-- snow drifting down off it for as long as it stands
	local duration = (ability and ability.IceDuration) or 9
	do
		local center = origin + d * L * 0.55 + UP * H * 0.55
		local holder = newPart(Vector3.new(W * 0.8, 4, L * 0.9), CFrame.lookAt(center, center + d), Color3.new(), nil, nil)
		holder.Transparency = 1
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		pe.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(190, 230, 255))
		pe.LightEmission = 0.6
		pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.2), NumberSequenceKeypoint.new(1, 0.4) })
		pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.15, 0.2), NumberSequenceKeypoint.new(1, 1) })
		pe.Speed = NumberRange.new(4, 10)
		pe.Lifetime = NumberRange.new(5, 8)
		pe.Acceleration = Vector3.new(0, -9, 0)
		pe.SpreadAngle = Vector2.new(60, 60)
		pe.EmissionDirection = Enum.NormalId.Bottom
		pe.Rate = 90
		pe.Shape = Enum.ParticleEmitterShape.Box
		pe.Parent = holder
		task.delay(duration, function()
			pe.Enabled = false
		end)
		cleanup(holder, duration + 8.5)
	end
	sparks(origin + d * 20, 2, ICE_TIP, Color3.fromRGB(120, 200, 255), 60)
	VFX.PlaySound("IceWallRise", origin + d * 20, 1.3)
	VFX.ShakeAt(origin, 3.2, 260, 0.9)
	task.wait(duration)
	shatter(model, 260)
end

-- Server-driven: encase a target in ice
local iceBlocks = setmetatable({}, { __mode = "k" }) -- [someone frozen] = the block of ice round them

function Effects.Freeze(_, data)
	local target = data.Target
	local root = target and target:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end
	local model = outlineModel(ICE_OUTLINE)
	local block = newPart(Vector3.new(1, 1, 1), root.CFrame, ICE_MID, Enum.Material.Ice, nil, model)
	block.Transparency = 0.25 -- (you can just make out who's inside)
	block.Reflectance = 0.08
	tween(block, 0.15, { Size = Vector3.new(5.5, 7.5, 5.5) }, Enum.EasingStyle.Back)
	local entry = { model = model }
	iceBlocks[target] = entry
	task.wait(data.Duration or 2)
	if not entry.gone then
		entry.gone = true
		shatter(model, 12)
	end
	if iceBlocks[target] == entry then
		iceBlocks[target] = nil
	end
end

-- their ice breaks early (a Glacier Breaker punch shatters it)
function Effects.Thaw(_, data)
	local target = typeof(data.Target) == "Instance" and data.Target or nil
	local entry = target and iceBlocks[target]
	if not entry or entry.gone then
		return
	end
	entry.gone = true
	iceBlocks[target] = nil
	shatter(entry.model, 24)
	local root = target:FindFirstChild("HumanoidRootPart")
	if root then
		frostMist(root.Position, 0.9, 6)
		VFX.PlaySound("Ice", root.Position, 1.1)
	end
end

-- HALF-HOT (fire side) ----------------------------------------------------

---------------------------------------------------------------------------
-- Real fire: layered particles on Roblox's own flame texture. A white-hot
-- core at the base, the flame body cooling from yellow to orange to deep red
-- as it climbs and thins out, dark smoke rolling off the top, embers drifting
-- away, and a warm light that flickers with it. (Config.Assets.FireTexture
-- swaps the texture, e.g. for a flipbook flame from the Creator Store.)
---------------------------------------------------------------------------
local Flame = {}
do
	local TEX = (Config.Assets and Config.Assets.FireTexture) or "rbxasset://textures/particles/fire_main.dds"
	local SMOKE = (Config.Assets and Config.Assets.SmokeTexture) or "rbxasset://textures/particles/smoke_main.dds"
	local EMBER = "rbxasset://textures/particles/sparkles_main.dds"
	local NS, NK = NumberSequence.new, NumberSequenceKeypoint.new
	local CK = ColorSequenceKeypoint.new
	-- hottest (white-yellow) where it's born, cooling to deep red as it rises
	local BODY = ColorSequence.new({
		CK(0, Color3.fromRGB(255, 240, 190)),
		CK(0.15, Color3.fromRGB(255, 200, 90)),
		CK(0.4, Color3.fromRGB(255, 130, 36)),
		CK(0.7, Color3.fromRGB(226, 64, 20)),
		CK(1, Color3.fromRGB(120, 30, 14)),
	})
	local CORE = ColorSequence.new(Color3.fromRGB(255, 255, 236), Color3.fromRGB(255, 214, 120))
	local SOOT = ColorSequence.new(Color3.fromRGB(70, 60, 56), Color3.fromRGB(36, 33, 33))
	local SPARK = ColorSequence.new(Color3.fromRGB(255, 226, 120), Color3.fromRGB(255, 90, 24))
	local LIGHT = Color3.fromRGB(255, 150, 60)
	local SPIN = NumberRange.new(0, 360)

	local function emitter(parent, props)
		local pe = Instance.new("ParticleEmitter")
		for k, v in props do
			pe[k] = v
		end
		pe.Parent = parent
		return pe
	end

	local function holderAt(cf, size)
		local h = newPart(size or Vector3.one * 0.2, cf, Color3.new(), nil, nil, folder)
		h.Transparency = 1
		return h
	end

	-- Every emitter a fire needs, on `parent` (a part: flames rise out of its
	-- whole volume). s = roughly how tall the flames stand, in studs.
	-- opts: Rate (multiplier, 0 = bursts only), Shape, Smoke = false
	function Flame.emitters(parent, s, opts)
		opts = opts or {}
		local rate = opts.Rate or 1
		local shape = opts.Shape or Enum.ParticleEmitterShape.Box
		local set = {}
		set.body = emitter(parent, {
			Name = "FlameBody", Texture = TEX, Color = BODY, LightEmission = 1, LightInfluence = 0,
			Size = NS({ NK(0, s * 0.3), NK(0.25, s * 0.5), NK(0.7, s * 0.34), NK(1, s * 0.05) }),
			Transparency = NS({ NK(0, 1), NK(0.08, 0.2), NK(0.55, 0.4), NK(1, 1) }),
			Lifetime = NumberRange.new(0.4, 0.75), Speed = NumberRange.new(s * 0.5, s * 1.2),
			Acceleration = Vector3.new(0, s * 4, 0), Drag = 2.5,
			Rotation = SPIN, RotSpeed = NumberRange.new(-140, 140), SpreadAngle = Vector2.new(18, 18),
			Shape = shape, Rate = 28 * rate, ZOffset = 0.5,
		})
		set.core = emitter(parent, {
			Name = "FlameCore", Texture = TEX, Color = CORE, LightEmission = 1, LightInfluence = 0,
			Size = NS({ NK(0, s * 0.18), NK(0.5, s * 0.22), NK(1, 0) }),
			Transparency = NS({ NK(0, 0.9), NK(0.15, 0.1), NK(1, 1) }),
			Lifetime = NumberRange.new(0.18, 0.35), Speed = NumberRange.new(s * 0.4, s * 0.9),
			Acceleration = Vector3.new(0, s * 3, 0), Drag = 2,
			Rotation = SPIN, RotSpeed = NumberRange.new(-90, 90), SpreadAngle = Vector2.new(10, 10),
			Shape = shape, Rate = 20 * rate, ZOffset = 1,
		})
		if opts.Smoke ~= false then
			-- born with the flames but only shows once they've burnt out above
			set.smoke = emitter(parent, {
				Name = "FlameSmoke", Texture = SMOKE, Color = SOOT, LightInfluence = 0.3,
				Size = NS({ NK(0, s * 0.3), NK(1, s * 1.1) }),
				Transparency = NS({ NK(0, 1), NK(0.25, 0.55), NK(1, 1) }),
				Lifetime = NumberRange.new(1.2, 2.2), Speed = NumberRange.new(s * 0.6, s * 1.2),
				Acceleration = Vector3.new(0, s * 1.2, 0), Drag = 1.2,
				Rotation = SPIN, RotSpeed = NumberRange.new(-30, 30), SpreadAngle = Vector2.new(20, 20),
				Shape = shape, Rate = 6 * rate, ZOffset = -1,
			})
		end
		set.embers = emitter(parent, {
			Name = "FlameEmbers", Texture = EMBER, Color = SPARK, LightEmission = 1, LightInfluence = 0,
			Size = NS({ NK(0, 0.22), NK(1, 0) }),
			Lifetime = NumberRange.new(0.6, 1.4), Speed = NumberRange.new(s * 0.8, s * 2),
			Acceleration = Vector3.new(0, s * 1.5, 0), Drag = 1.5, SpreadAngle = Vector2.new(50, 50),
			Shape = shape, Rate = 8 * rate,
		})
		return set
	end

	local function stopSet(set, smokeLinger)
		for key, pe in set do
			if key == "smoke" then
				task.delay(smokeLinger or 0.3, function()
					pe.Enabled = false
				end)
			else
				pe.Enabled = false
			end
		end
	end

	-- A warm light that flickers like fire (and fades over its last quarter).
	-- Returns the light and a function that puts it out.
	function Flame.light(parent, range, brightness, duration)
		local light = Instance.new("PointLight")
		light.Color = LIGHT
		light.Range = math.min(range, 60)
		light.Brightness = brightness
		light.Parent = parent
		local lit = true
		task.spawn(function()
			local t0 = os.clock()
			while lit and light.Parent and os.clock() - t0 < duration do
				local left = 1 - (os.clock() - t0) / duration
				light.Brightness = brightness * (0.7 + rng:NextNumber() * 0.6) * math.min(1, left * 4)
				light.Range = math.min(range * (0.88 + rng:NextNumber() * 0.24), 60)
				task.wait(0.05)
			end
			if lit then
				light.Enabled = false
			end
		end)
		return light, function()
			lit = false
			light:Destroy()
		end
	end

	-- Fire burning on the ground at pos for `duration`, then dying down
	function Flame.spot(pos, s, duration, width)
		local w = width or s * 0.5
		local h = holderAt(CFrame.new(pos), Vector3.new(w, 0.2, w))
		local set = Flame.emitters(h, s)
		Flame.light(h, s * 3.5, 1.6, duration + 0.3)
		task.delay(duration, function()
			stopSet(set)
		end)
		cleanup(h, duration + 2.6)
		return h
	end

	-- One whoomp: a fireball blooms out of pos and rolls upward into smoke
	function Flame.burst(pos, s, amount)
		local h = holderAt(CFrame.new(pos), Vector3.one * s * 0.3)
		local set = Flame.emitters(h, s, { Rate = 0, Shape = Enum.ParticleEmitterShape.Sphere })
		set.body.Speed = NumberRange.new(s * 1.2, s * 2.6)
		set.body.Drag = 4
		set.core.Speed = NumberRange.new(s * 0.6, s * 1.4)
		amount = amount or 14
		set.body:Emit(amount)
		set.core:Emit(math.ceil(amount * 0.6))
		set.smoke:Emit(math.ceil(amount * 0.35))
		set.embers:Emit(math.ceil(amount * 0.6))
		Flame.light(h, s * 5, 3, 0.5)
		cleanup(h, 2.6)
	end

	-- Set a body part burning until the returned function is called
	function Flame.attach(part, s, rate)
		local set = Flame.emitters(part, s, { Rate = rate or 1 })
		local _, putOut = Flame.light(part, s * 4, 1.4, 600)
		return function()
			stopSet(set)
			for _, pe in set do
				cleanup(pe, 2.5)
			end
			putOut()
		end
	end

	-- A roaring column of fire `height` studs tall
	function Flame.column(base, height, radius, duration)
		local h = holderAt(CFrame.new(base + UP), Vector3.new(radius * 1.4, 1, radius * 1.4))
		local up = height * 2.3 -- what drag leaves of this reaches the top
		local set = {
			body = emitter(h, {
				Texture = TEX, Color = BODY, LightEmission = 1, LightInfluence = 0,
				Size = NS({ NK(0, radius * 1.1), NK(0.4, radius * 1.35), NK(1, radius * 0.4) }),
				Transparency = NS({ NK(0, 0.8), NK(0.1, 0.1), NK(0.65, 0.3), NK(1, 1) }),
				Lifetime = NumberRange.new(0.5, 0.8), Speed = NumberRange.new(up * 0.8, up), Drag = 1.6,
				Acceleration = Vector3.new(0, 20, 0), Rotation = SPIN, RotSpeed = NumberRange.new(-160, 160),
				SpreadAngle = Vector2.new(6, 6), Rate = 130, ZOffset = 0.5,
			}),
			core = emitter(h, {
				Texture = TEX, Color = CORE, LightEmission = 1, LightInfluence = 0,
				Size = NS({ NK(0, radius * 0.7), NK(1, 0) }),
				Transparency = NS({ NK(0, 0.6), NK(0.2, 0.05), NK(1, 1) }),
				Lifetime = NumberRange.new(0.3, 0.45), Speed = NumberRange.new(up * 0.7, up * 0.9), Drag = 1.6,
				Rotation = SPIN, RotSpeed = NumberRange.new(-120, 120), SpreadAngle = Vector2.new(4, 4), Rate = 80, ZOffset = 1,
			}),
			embers = emitter(h, {
				Texture = EMBER, Color = SPARK, LightEmission = 1, LightInfluence = 0,
				Size = NS({ NK(0, 0.35), NK(1, 0) }),
				Lifetime = NumberRange.new(0.8, 1.6), Speed = NumberRange.new(up * 0.4, up * 0.7), Drag = 1.2,
				Acceleration = Vector3.new(0, 6, 0), SpreadAngle = Vector2.new(30, 30), Rate = 45,
			}),
		}
		local top = holderAt(CFrame.new(base + UP * height * 0.9), Vector3.new(radius * 2, 2, radius * 2))
		set.smoke = emitter(top, {
			Texture = SMOKE, Color = SOOT, LightInfluence = 0.3,
			Size = NS({ NK(0, radius * 1.5), NK(1, radius * 4) }),
			Transparency = NS({ NK(0, 0.9), NK(0.2, 0.45), NK(1, 1) }),
			Lifetime = NumberRange.new(1.4, 2.4), Speed = NumberRange.new(6, 14), Drag = 0.8,
			Rotation = SPIN, RotSpeed = NumberRange.new(-25, 25), SpreadAngle = Vector2.new(60, 60), Rate = 26, ZOffset = -1,
		})
		Flame.light(h, height * 1.2, 5, duration + 0.4)
		task.delay(duration, function()
			stopSet(set, 0.4)
		end)
		cleanup(h, duration + 2.6)
		cleanup(top, duration + 3)
	end

	-- Flamethrower out of the left hand along d, reaching `reach` studs.
	-- Blocks for `duration`; returns roughly where the flames ended up.
	function Flame.stream(char, root, d, duration, reach)
		local hand = handPos(char, false)
		local h = holderAt(CFrame.lookAt(hand, hand + d))
		local speed = reach * 2.6 -- drag 2.4 leaves ~reach of travel
		local jet = emitter(h, {
			Name = "FlameJet", Texture = TEX, Color = BODY, LightEmission = 1, LightInfluence = 0,
			Size = NS({ NK(0, 0.8), NK(0.3, reach * 0.09), NK(0.75, reach * 0.16), NK(1, reach * 0.1) }),
			Transparency = NS({ NK(0, 0.5), NK(0.1, 0.1), NK(0.7, 0.35), NK(1, 1) }),
			Lifetime = NumberRange.new(0.45, 0.6), Speed = NumberRange.new(speed * 0.85, speed), Drag = 2.4,
			Acceleration = Vector3.new(0, 14, 0), Rotation = SPIN, RotSpeed = NumberRange.new(-200, 200),
			SpreadAngle = Vector2.new(6, 6), EmissionDirection = Enum.NormalId.Front, Rate = 160, ZOffset = 0.5,
		})
		local core = emitter(h, {
			Name = "FlameJetCore", Texture = TEX, Color = CORE, LightEmission = 1, LightInfluence = 0,
			Size = NS({ NK(0, 0.5), NK(0.4, 2.2), NK(1, 0) }),
			Transparency = NS({ NK(0, 0.3), NK(1, 1) }),
			Lifetime = NumberRange.new(0.15, 0.25), Speed = NumberRange.new(speed * 0.85, speed), Drag = 2.4,
			Rotation = SPIN, SpreadAngle = Vector2.new(3, 3), EmissionDirection = Enum.NormalId.Front, Rate = 90, ZOffset = 1,
		})
		local smoke = emitter(h, {
			Name = "FlameJetSmoke", Texture = SMOKE, Color = SOOT, LightInfluence = 0.3,
			Size = NS({ NK(0, 2), NK(1, reach * 0.25) }),
			Transparency = NS({ NK(0, 1), NK(0.35, 0.6), NK(1, 1) }),
			Lifetime = NumberRange.new(0.9, 1.3), Speed = NumberRange.new(speed * 0.6, speed * 0.75), Drag = 2.4,
			Acceleration = Vector3.new(0, 10, 0), Rotation = SPIN, RotSpeed = NumberRange.new(-40, 40),
			SpreadAngle = Vector2.new(8, 8), EmissionDirection = Enum.NormalId.Front, Rate = 30, ZOffset = -1,
		})
		local sparks = emitter(h, {
			Name = "FlameJetEmbers", Texture = EMBER, Color = SPARK, LightEmission = 1, LightInfluence = 0,
			Size = NS({ NK(0, 0.3), NK(1, 0) }),
			Lifetime = NumberRange.new(0.5, 1), Speed = NumberRange.new(speed * 0.5, speed * 0.9), Drag = 2,
			Acceleration = Vector3.new(0, 8, 0), SpreadAngle = Vector2.new(14, 14), EmissionDirection = Enum.NormalId.Front, Rate = 40,
		})
		Flame.light(h, 26, 3.2, duration + 0.25)
		local t0 = os.clock()
		local n = 0
		while os.clock() - t0 < duration and root.Parent do
			hand = handPos(char, false)
			h.CFrame = CFrame.lookAt(hand + d * 0.8, hand + d * 2)
			n += 1
			if n % 4 == 0 then
				-- whatever the flames lick keeps burning for a moment
				local p = groundPoint(hand + d * rand(reach * 0.35, reach * 0.9))
				Flame.spot(p, rand(3, 5), rand(0.6, 1.1), 2.5)
				groundMark(p, rand(1.5, 2.5), Color3.fromRGB(40, 28, 24), 3)
			end
			task.wait(0.03)
		end
		jet.Enabled = false
		core.Enabled = false
		sparks.Enabled = false
		task.delay(0.25, function()
			smoke.Enabled = false
		end)
		cleanup(h, 1.8)
		return root.Position + d * (reach * 0.85)
	end
end

do -- TODOROKI's close-range moves (one table: the local limit)
	local TD = {}

	-- a slab of ice rising out of the street, facing `d`
	function TD.slab(parent, center, d, size, time)
		local p = newPart(Vector3.new(size.X, 0.2, size.Z), CFrame.lookAt(center - UP * size.Y / 2, center - UP * size.Y / 2 + d), ICE_MID, Enum.Material.Ice, nil, parent)
		tween(p, time, { Size = size, CFrame = CFrame.lookAt(center, center + d) }, Enum.EasingStyle.Back)
		IceKit.solidAfter(p, time + 0.02)
		return p
	end

	-- GLACIER BREAKER, part 1: the frost-fisted punch
	function Effects.GlacierBreaker(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			dash(root, d * 50, 0.12)
		end
		VFX.Motion(char, "M1Brawler4")
		frostMist(handPos(char, true), 0.4, 3)
		VFX.PlaySound("HeavySwing", root.Position, 1)
	end

	-- GLACIER BREAKER, part 2 (the server says who): a wall of ice erupts
	-- behind them and they're pinned to it, frozen in... then he stomps and
	-- a pillar of ice bursts up under them and the wall shatters
	function Effects.GlacierPin(char, data)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not root or not target then
			if root then
				frostMist(root.Position + root.CFrame.LookVector * 4, 0.5, 3) -- (a punch into thin air)
			end
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local wallAt = typeof(data.Pos) == "Vector3" and data.Pos or (root.Position + d * 7.5)
		local g = groundPoint(wallAt)
		local model = outlineModel(ICE_OUTLINE)
		-- the wall, and the ice that grows over them where they hit it
		TD.slab(model, g + UP * 5 + d * 0.5, d, Vector3.new(12, 11, 2.6), 0.12)
		for _ = 1, 6 do
			local p = g + UP * rand(1, 8) + d:Cross(UP) * rand(-5, 5)
			local sp = newPart(Vector3.one * rand(1.5, 3), CFrame.new(p) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), ICE_TIP, Enum.Material.Ice, nil, model)
			sp.Transparency = 0.1
		end
		local tr = target:FindFirstChild("HumanoidRootPart")
		if tr then
			local shell = newPart(Vector3.new(1, 1, 1), tr.CFrame, ICE_MID, Enum.Material.Ice, nil, model)
			shell.Transparency = 0.35
			tween(shell, 0.12, { Size = Vector3.new(4.6, 6.4, 3.4) }, Enum.EasingStyle.Back)
		end
		VFX.Pose(char, "PunchR", 0.3)
		VFX.PlaySound("Ice", wallAt, 1)
		VFX.PlaySound("HeavyHit", wallAt, 0.9)
		VFX.ShakeAt(wallAt, data.Shatter and 2 or 1.4, 60, 0.2)
		if data.Shatter and tr then
			-- (their ice shattered by the punch: a burst of shards off them)
			shockDisc(tr.Position, d, 2, 12, 0.25, ICE_TIP)
			frostMist(tr.Position, 1, 6)
			if nearCamera(tr.Position, 60) then
				VFX.ImpactFrame(0.05)
			end
		end
		task.wait(data.Time or 0.55)
		if not root.Parent then
			shatter(model, 30)
			return
		end
		-- the stomp... and the pillar
		VFX.Pose(char, "Stomp", 0.4)
		local base = groundPoint(tr and tr.Position or wallAt - d * 2)
		local pillar = outlineModel(ICE_OUTLINE)
		local set = makeSpike(pillar, base - UP * 2, (UP * 3 + d).Unit, 22, 6, true)
		growSpikes({ { set = set, delay = 0 } }, 0.12)
		shockDisc(base + UP * 0.5, UP, 3, 24, 0.3, ICE_TIP)
		frostMist(base, 1.2, 8)
		VFX.PlaySound("IceWallRise", base, 0.9)
		VFX.ShakeAt(base, 2, 90, 0.35)
		task.wait(0.1)
		shatter(model, 40)
		task.wait(2)
		shatter(pillar, 30)
	end

	-- ICE SLIDER: a ramp of ice shoots out along the aim, he skates up it
	-- and flies off the lip at the end
	function Effects.IceSlider(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		local range = ability.Range or 70
		local ride = ability.RideTime or 0.75
		local rise = 16
		local g = groundPoint(root.Position)
		local model = outlineModel(ICE_OUTLINE)
		-- the ramp: a run of slabs climbing away from him, a spike or two on each side
		local step = 6
		local right = d:Cross(UP)
		local function surface(s)
			local k = math.clamp(s / range, 0, 1)
			return g + d * s + UP * (rise * k * k)
		end
		for s = 0, range, step do
			local a, b = surface(s), surface(s + step)
			local mid = (a + b) / 2 - UP * 1
			local slab = newPart(Vector3.new(0.4, 2, 0.4), CFrame.lookAt(mid, mid + (b - a)), ICE_MID, Enum.Material.Ice, nil, model)
			tween(slab, 0.12, { Size = Vector3.new(7, 2, (b - a).Magnitude + 0.4) }, Enum.EasingStyle.Quad, nil, s / range * ride * 0.8)
			IceKit.solidAfter(slab, s / range * ride * 0.8 + 0.14)
			if s % 18 == 0 then
				for side = -1, 1, 2 do
					local set = makeSpike(model, a + right * side * 3.8 - UP * 1, (UP + right * side * 0.4).Unit, rand(4, 7), 1.6, false)
					set(1)
				end
			end
		end
		VFX.Pose(char, "Skate", ride + 0.2)
		VFX.PlaySound("Ice", root.Position, 1)
		local stopTrail = addTrail(root, ICE_TIP, 0.3, 2)
		if isLocal and hum then
			face(root, d)
			VFX.Fly(char, root, hum, ride, function(a)
				local p = surface(range * a) + UP * 3
				return CFrame.lookAt(p, p + d)
			end)
			task.delay(ride, function()
				if root.Parent then
					launch(root, hum, d * 60 + UP * 55)
				end
			end)
		end
		local t0 = os.clock()
		while os.clock() - t0 < ride and root.Parent do
			frostMist(root.Position - UP * 2, 0.4, 2)
			task.wait(0.08)
		end
		stopTrail(0)
		task.wait(3)
		shatter(model, 40)
	end

	-- JET KINDLING, part 1: flames jet out of his elbow and rocket him along
	-- the aim, his left fist gone white-hot (canon: his flames compressed to a
	-- single white-hot point)
	function Effects.JetKindling(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if data.Air and typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 then
			-- (the server's same clamp: steep enough to dive on someone)
			local a = data.Dir.Unit
			local flat = Vector3.new(a.X, 0, a.Z)
			d = ((flat.Magnitude > 0.05 and flat.Unit or d) + UP * math.clamp(a.Y, -0.9, 0.45)).Unit
		end
		local time = ability.DashTime or 0.32
		if isLocal then
			face(root, flatten(d, root))
			Flame.jet = Flame.jet or setmetatable({}, { __mode = "k" })
			Flame.jet[char] = dash(root, d * (ability.DashSpeed or 125), time)
		end
		VFX.Pose(char, "RushBack", time + 0.05)
		VFX.PlaySound("JetKindling", root.Position, 1)
		local fist = newPart(Vector3.one * 1.3, CFrame.new(handPos(char, false)), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		fist.Transparency = 0.1
		local stopTrail = addTrail(root, FIRE[2], 0.3, 2.4)
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent and fist.Parent do
			local hand = handPos(char, false)
			fist.CFrame = CFrame.new(hand)
			-- the jet, roaring out behind his elbow
			Flame.burst(hand - d * 3, 1.2, 4)
			task.wait(0.04)
		end
		stopTrail(0)
		tween(fist, 0.15, { Size = Vector3.one * 0.2, Transparency = 1 })
		cleanup(fist, 0.2)
	end

	-- JET KINDLING, part 2 (the server: the fist landed - or went off at the
	-- end of the jet): a white-hot flash, and a violent explosion of flame
	-- bursting out of his arm, on through them
	function Effects.JetKindlingHit(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		if Flame.jet and Flame.jet[char] then
			Flame.jet[char]() -- (his jet stops on them)
			Flame.jet[char] = nil
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or flatten(root.CFrame.LookVector, root)
		local at = typeof(data.At) == "Vector3" and data.At or root.Position + d * 4
		VFX.Pose(char, "PunchL", 0.45)
		local flash = newPart(Vector3.one * 2, CFrame.new(at), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(flash, 0.22, { Size = Vector3.one * 11, Transparency = 1 })
		cleanup(flash, 0.25)
		billboardRing(at, 2, 20, Color3.new(1, 1, 1), 6, 0.25)
		shockDisc(at, d, 3, 24, 0.3, FIRE[2], 10)
		sparks(at, 1.6)
		-- the blast rolling on out of his arm
		for k = 1, 7 do
			task.delay(k * 0.025, function()
				Flame.burst(at + d * (k * 3.2) + Vector3.new(rand(-1, 1), rand(-1, 1), rand(-1, 1)), 1.8 + k * 0.35, 8)
			end)
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		if tr then
			local stop = Flame.attach(tr, 1.8, 1.4)
			task.delay(1.6, stop)
		end
		if nearCamera(at, 70) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 240, 210), 0.15)
		end
		VFX.PlaySound("JetKindlingBlast", at, 1)
		VFX.ShakeAt(at, 2.2, 100, 0.35)
	end
end

function Effects.Flashfire(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
	end
	VFX.Pose(char, "PunchL", 0.6)
	task.wait(0.1)
	if not root.Parent then
		return
	end
	VFX.PlaySound("Fire", root.Position, 0.8)
	local tip = Flame.stream(char, root, d, 0.45, 42)
	Flame.burst(tip + UP * 2, 5, 10)
	sparks(tip, 1.3)
end

function Effects.FlamePillar(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
	end
	-- same range clamp + ground snap the server uses
	local aim = typeof(data.Pos) == "Vector3" and data.Pos or root.Position + d * 30
	local range = ability and ability.Range or 70
	local flat = Vector3.new(aim.X - root.Position.X, 0, aim.Z - root.Position.Z)
	if flat.Magnitude > range then
		flat = flat.Unit * range
	end
	local xz = root.Position + flat
	local hit = groundRay(Vector3.new(xz.X, root.Position.Y + 22, xz.Z), 90)
	local target = hit and hit.Position or Vector3.new(xz.X, root.Position.Y - 3, xz.Z)

	VFX.Pose(char, "FireRaise", 0.5)
	-- telegraph: glowing ring + licks of flame
	local ring = newPart(
		Vector3.new(0.2, 2, 2),
		CFrame.new(target + Vector3.new(0, 0.12, 0)) * CFrame.Angles(0, 0, math.rad(90)),
		FIRE[3],
		Enum.Material.Neon,
		Enum.PartType.Cylinder
	)
	ring.Transparency = 0.45
	tween(ring, 0.38, { Size = Vector3.new(0.2, 18, 18) }, Enum.EasingStyle.Back)
	cleanup(ring, 0.45)
	-- the ground under them starts to smoulder
	for _ = 1, 5 do
		Flame.spot(target + Vector3.new(rand(-6, 6), 0.2, rand(-6, 6)), rand(2, 3.5), 0.45, 2)
	end
	task.wait(0.42)
	if not root.Parent then
		return
	end
	VFX.Pose(char, "PunchL", 0.3)

	-- the pillar: a roaring column of fire, then the ground keeps burning
	Flame.column(target, 46, 5.5, 0.6)
	Flame.burst(target + UP * 2, 9, 24)
	for i = 1, 6 do
		local a = i / 6 * math.pi * 2
		Flame.spot(target + Vector3.new(math.cos(a) * 5, 0.2, math.sin(a) * 5), rand(3, 5), rand(1, 1.6), 3)
	end
	billboardRing(target + UP * 3, 4, 34, Color3.fromRGB(255, 238, 60), 10, 0.35)
	billboardRing(target + UP * 3, 6, 42, Color3.fromRGB(255, 80, 30), 6, 0.45)
	emberCloud(target + UP * 20, 12, 1.2, 70)
	shockDisc(target + UP * 0.4, UP, 4, 32, 0.35, FIRE[2])
	sparks(target + UP * 10, 2)
	rocks(target, 1.5, 8)
	groundMark(target, 6, Color3.fromRGB(34, 26, 24), 5)
	VFX.PlaySound("Explosion", target, 1)
	VFX.ShakeAt(target, 2, 110, 0.4)
end

-- Flashfreeze Heatwave: ice wall, fire straight into it, flash-heated air blast.
-- opts scales it up for the ult version.
local function heatwaveCore(char, data, isLocal, opts)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
		VFX.Hooks.Dim(0.5, opts.DimTime)
	end
	-- 1) right side: ice mound in front
	VFX.Pose(char, "Ground", 0.7)
	frostMist(groundPoint(root.Position) + d * 2, 0.6, 4)
	task.wait(opts.IceWait)
	if not root.Parent then
		return
	end
	local ice, origin = spikeLayout(opts.Layout, data, root, d, Color3.fromRGB(36, 84, 116))
	frostMist(origin + d * (opts.BlastOffset - 2), 1.4 * opts.Scale, 6)
	VFX.PlaySound("Ice", origin, 1)
	VFX.ShakeAt(origin, 1.5 * opts.Scale, 100, 0.3)
	task.wait(0.35)
	if not root.Parent then
		shatter(ice, 60)
		return
	end
	-- 2) left side: flame straight into the ice
	VFX.Pose(char, "PunchL", 0.6)
	VFX.PlaySound("Fire", root.Position, 1)
	Flame.stream(char, root, d, opts.StreamTime, opts.StreamLength)
	-- 3) flash-heated air explodes
	local center = origin + d * opts.BlastOffset + UP * (7 * opts.Scale)
	shatter(ice, 120)
	toonExplosion(center, opts.BlastScale, { SmokeLife = 3 })
	for i = 1, 6 do
		task.delay(i * 0.03, function()
			shockDisc(center - d * 8, d, 12 * opts.Scale, 52 * opts.Scale, 0.55, Color3.fromRGB(255, 236, 200), 70 * opts.Scale)
		end)
	end
	streaks(center, d, 40, 12 * opts.Scale, 18, 140 * opts.Scale, FIRE[1], 0.45)
	if nearCamera(center, 130 * opts.Scale) then
		VFX.Hooks.Flash(Color3.fromRGB(255, 226, 180), 0.35)
	end
	VFX.ShakeAt(center, 4 * opts.Scale, 220 * opts.Scale, 0.8)
end

function Effects.Heatwave(char, data, isLocal)
	heatwaveCore(char, data, isLocal, {
		Layout = "Heatwave", IceWait = 0.4, StreamTime = 0.4, StreamLength = 26,
		BlastOffset = 18, BlastScale = 3.4, Scale = 1, DimTime = 1.1,
	})
end

-- Server-driven: target is on fire (flames climbing off the body)
local burnFx = setmetatable({}, { __mode = "k" }) -- [target] = token
function Effects.Burn(_, data)
	local target = data.Target
	local root = target and target:FindFirstChild("HumanoidRootPart")
	local torso = target and (target:FindFirstChild("UpperTorso") or target:FindFirstChild("Torso"))
	if not root or not torso then
		return
	end
	local token = (burnFx[target] or 0) + 1
	burnFx[target] = token
	if (data.Pal == "hell" or data.Pal == "blue") and VFX.BLAZE then
		local f = VFX.BLAZE.onPart(torso, CFrame.new(0, -0.4, 0), 4.2, data.Pal, { Width = 2.4, Tongues = 5, Volume = 0.8, Light = 10 })
		local legs = target:FindFirstChild("LowerTorso") or target:FindFirstChild("Left Leg")
		local f2 = legs and VFX.BLAZE.onPart(legs, CFrame.new(0, -0.3, 0), 2.2, data.Pal, { Width = 1.2, Tongues = 2, Volume = 0.4 })
		local t0 = os.clock()
		while os.clock() - t0 < (data.Duration or 1.5) and root.Parent and burnFx[target] == token do
			task.wait(0.1)
		end
		f.kill(0.4)
		if f2 then
			f2.kill(0.4)
		end
		return
	end
	local stops = { Flame.attach(torso, 3.2) }
	local legs = target:FindFirstChild("LowerTorso") or target:FindFirstChild("Left Leg")
	if legs then
		table.insert(stops, Flame.attach(legs, 2.2, 0.6))
	end
	local t0 = os.clock()
	while os.clock() - t0 < (data.Duration or 1.5) and root.Parent and burnFx[target] == token do
		task.wait(0.1)
	end
	for _, stop in stops do
		stop()
	end
	if burnFx[target] == token then
		burnFx[target] = nil
	end
end

-- R special: swap between ice (right) and fire (left)
function Effects.SideSwap(char, data)
	local root = charParts(char)
	if not root then
		return
	end
	VFX.Pose(char, "Blast", 0.25)
	local g = groundPoint(root.Position)
	VFX.PlaySound("SideSwap", g, 1)
	if data.Alt then
		-- a ring of fire whooshes up around him
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			Flame.burst(g + out * rand(4, 7) + UP * 1.5, rand(4, 5.5), 8)
			Flame.spot(g + out * rand(5, 8) + UP * 0.2, rand(2.5, 3.5), 0.8, 2)
		end
		shockDisc(g + UP * 0.4, UP, 3, 26, 0.35, FIRE[2])
		sparks(root.Position, 1)
		VFX.PlaySound("Fire", g, 0.7)
	else
		local model = outlineModel(ICE_OUTLINE)
		local list = {}
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local dir = (UP * 1.4 + out + rng:NextUnitVector() * 0.2).Unit
			table.insert(list, { set = makeSpike(model, g + out * 4 - UP, dir, rand(3, 5), 1.2, false), delay = i * 0.01 })
		end
		growSpikes(list, 0.12)
		frostMist(g, 0.8, 6)
		shockDisc(g + UP * 0.4, UP, 3, 26, 0.35, ICE_TIP)
		sparks(root.Position, 1, ICE_TIP, Color3.fromRGB(120, 200, 255), 20)
		VFX.PlaySound("Ice", g, 0.7)
		task.delay(0.8, function()
			shatter(model, 20)
		end)
	end
	VFX.ShakeAt(g, 0.6, 40, 0.2)
end

-- ENGINE --------------------------------------------------------------------

local function calves(char)
	local out = {}
	for _, names in { { "RightLowerLeg", "Right Leg" }, { "LeftLowerLeg", "Left Leg" } } do
		local leg = limb(char, names[1], names[2])
		if leg then
			table.insert(out, leg)
		end
	end
	return out
end

local function legTrails(char, duration, color)
	local stops = {}
	for _, names in { { "RightFoot", "Right Leg" }, { "LeftFoot", "Left Leg" } } do
		local foot = limb(char, names[1], names[2])
		if foot then
			table.insert(stops, addTrail(foot, color, 0.35, 1.2))
		end
	end
	for _, stop in stops do
		stop(duration)
	end
end

local function armTrails(char, duration, color)
	local stops = {}
	for _, names in { { "RightHand", "Right Arm" }, { "LeftHand", "Left Arm" } } do
		local hand = limb(char, names[1], names[2])
		if hand then
			table.insert(stops, addTrail(hand, color, 0.3, 1))
		end
	end
	for _, stop in stops do
		stop(duration)
	end
end

-- Blue exhaust flames out of the calf pipes for `duration` seconds
local function exhaust(char, duration, intensity)
	local legs = calves(char)
	local root = char:FindFirstChild("HumanoidRootPart")
	if #legs == 0 or not root then
		return
	end
	local isR15 = char:FindFirstChild("UpperTorso") ~= nil
	task.spawn(function()
		local t0 = os.clock()
		while os.clock() - t0 < duration and root.Parent do
			local back = -root.CFrame.LookVector
			for _, leg in legs do
				local y = isR15 and leg.Size.Y * 0.08 or -leg.Size.Y * 0.22
				local from = (leg.CFrame * CFrame.new(0, y, leg.Size.Z / 2 + 0.9)).Position
				local s = rand(0.9, 1.5) * intensity
				local color = rng:NextNumber() < 0.4 and EXHAUST_CORE or EXHAUST
				local p = newPart(Vector3.one * s * 0.5, CFrame.new(from), color, Enum.Material.Neon, Enum.PartType.Ball)
				tween(p, 0.18, {
					CFrame = CFrame.new(from + back * rand(3, 6) * intensity + Vector3.new(0, rand(0, 1), 0)),
					Size = Vector3.one * 0.1,
					Transparency = 0.6,
				})
				cleanup(p, 0.2)
			end
			task.wait(0.03)
		end
	end)
end

-- Neon ghost of the character's body (speed afterimage)
local function afterimage(char, color, life)
	for _, part in char:GetChildren() do
		if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 then
			local ghost = part:Clone()
			if ghost then
				ghost:ClearAllChildren()
				if ghost:IsA("MeshPart") then
					ghost.TextureID = ""
				end
				ghost.Anchored = true
				ghost.CanCollide = false
				ghost.CanQuery = false
				ghost.CanTouch = false
				ghost.CastShadow = false
				ghost.Massless = true
				ghost.Material = Enum.Material.Neon
				ghost.Color = color
				ghost.Transparency = 0.45
				ghost.CFrame = part.CFrame
				ghost.Parent = folder
				tween(ghost, life, { Transparency = 1 })
				cleanup(ghost, life + 0.05)
			end
		end
	end
end

do -- IIDA's kicks (one table: the local limit)
	local IR = { charging = setmetatable({}, { __mode = "k" }) } -- [char] = the rev-up running

	-- a dash that follows where YOUR camera looks the whole way (your own
	-- machine flies you): turn the camera mid-dash and the dash turns with it
	function IR.steer(root, speed, duration, fallback)
		local att = Instance.new("Attachment")
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 6000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		local function heading()
			local cam = workspace.CurrentCamera
			local look = cam and Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z)
			if look and look.Magnitude > 0.05 then
				return look.Unit
			end
			return fallback
		end
		lv.VectorVelocity = heading() * speed
		lv.Parent = root
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if os.clock() - t0 > duration or not lv.Parent then
				conn:Disconnect()
				return
			end
			local h = heading()
			lv.VectorVelocity = h * speed
			face(root, h)
		end)
		cleanup(lv, duration)
		cleanup(att, duration)
	end

	-- RECIPRO SPIN: a whirling roundhouse, two turns, engines roaring
	function Effects.SpinKick(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		VFX.Motion(char, "SpinKick")
		exhaust(char, 0.5, 1.4)
		legTrails(char, 0.5, EXHAUST)
		VFX.PlaySound("Engine", root.Position, 0.8)
		if isLocal then
			task.spawn(function()
				local t0 = os.clock()
				local last = t0
				while os.clock() - t0 < 0.44 and root.Parent do
					local now = os.clock()
					root.CFrame = root.CFrame * CFrame.Angles(0, -(now - last) * 28, 0)
					last = now
					task.wait()
				end
				if root.Parent then
					face(root, d)
				end
			end)
		end
		for i = 1, 2 do
			task.delay(0.1 + (i - 1) * 0.22, function()
				if not root.Parent then
					return
				end
				local p = root.Position - UP * 0.5
				moonArc(CFrame.new(p) * CFrame.Angles(math.rad(90), rand(0, 6), 0), 7 + i * 2, EXHAUST, 330)
				moonArc(CFrame.new(p) * CFrame.Angles(math.rad(90), rand(0, 6), 0), 6 + i * 2, WIND, 300)
				shockDisc(p, UP, 3, 14 + i * 6, 0.3, EXHAUST)
				VFX.PlaySound("Kick", p, i == 2 and 1.2 or 0.8)
				VFX.ShakeAt(p, 0.8 * i, 50, 0.15)
			end)
		end
	end

	-- ENGINE GATLING: a blur of kicks, then the heel comes down
	function Effects.EngineGatling(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		exhaust(char, 0.8, 1.2)
		task.wait(0.08)
		for i = 1, ability.Hits or 8 do
			if not root.Parent then
				return
			end
			VFX.Pose(char, i % 2 == 1 and "Kick" or "KickLeft", 0.08)
			local p = root.Position + d * 4 + Vector3.new(rand(-1.5, 1.5), rand(-1, 2), rand(-1.5, 1.5))
			shockDisc(p, d, 1, 5, 0.12, WIND, 2)
			streaks(p - d, d, 3, 1, 3, 6, EXHAUST_CORE, 0.1)
			if i % 2 == 0 then
				afterimage(char, EXHAUST, 0.15)
			end
			VFX.PlaySound("Hit", p, 0.5)
			task.wait(ability.Interval or 0.07)
		end
		-- the heel, straight down
		VFX.Motion(char, "AxeKick")
		task.wait(0.12)
		if not root.Parent then
			return
		end
		local g = groundPoint(root.Position + d * 4)
		shockDisc(g + UP * 0.4, UP, 3, 26, 0.35, EXHAUST)
		streaks(g + UP * 6, -UP, 8, 1.5, 6, 8, WIND, 0.25)
		dustPuffs(g, 1.2, 7, Color3.fromRGB(205, 196, 190), 1, true)
		rocks(g, 1.1, 8)
		VFX.PlaySound("Downslam", g, 1)
		VFX.ShakeAt(g, 1.8, 70, 0.3)
	end

	-- RECIPRO BURST (held): the engines rev harder the longer it's held, a
	-- flash at each new gear, until he lets go
	function Effects.ReciproBurst(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local spec = ability.Hold or {}
		local token = {}
		IR.charging[char] = token
		VFX.Pose(char, "Rev", (spec.Max or 1.6) + 0.5)
		VFX.PlaySound("ReciproRev", root.Position, 0.8)
		if isLocal then
			VFX.Hooks.Dim(0.2, spec.Max or 1.6)
		end
		local t0 = os.clock()
		local level = 1
		while IR.charging[char] == token and root.Parent and os.clock() - t0 < (spec.Max or 1.6) + 0.5 do
			local now = os.clock() - t0
			local reached = 1
			for i, t in spec.Levels or {} do
				if now >= t then
					reached = i + 1
				end
			end
			if reached > level then
				level = reached
				billboardRing(root.Position, 2, 10 + level * 5, level == 3 and Color3.new(1, 1, 1) or EXHAUST, 6, 0.3)
				sparks(root.Position - UP * 2, 0.5 * level, EXHAUST_CORE, EXHAUST, 10 * level)
				VFX.PlaySound("ReciproRev", root.Position, 0.6 + 0.3 * level)
			end
			exhaust(char, 0.06, 0.8 + 0.5 * level)
			if level >= 2 and rng:NextNumber() < 0.3 then
				dustPuffs(groundPoint(root.Position) - flatten(root.CFrame.LookVector, root) * 2, 0.5, 2, Color3.fromRGB(205, 196, 190), 0.5, false)
			end
			task.wait(0.06)
		end
		if IR.charging[char] == token then
			IR.charging[char] = nil
		end
	end

	-- ...he let go: one dash strike per gear, each one following where he
	-- looks (on his own screen); the last is the hardest, gear 3's breaks
	-- the sound barrier
	function Effects.ReciproBurstRelease(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		IR.charging[char] = nil
		ability = ability or Config.FindAbilityById("ReciproBurst") or {}
		local level = math.clamp(tonumber(data.Level) or 1, 1, 3)
		local dashTime = ability.DashTime or 0.18
		local fallback = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
		for i = 1, level do
			if not root.Parent then
				return
			end
			local last = i == level
			VFX.Pose(char, last and "Kick" or (i % 2 == 1 and "KickLeft" or "Kick"), dashTime + 0.05)
			if isLocal then
				IR.steer(root, ability.DashSpeed or 160, dashTime, fallback)
			end
			VFX.PlaySound("Engine", root.Position, 0.8)
			local stopTrail = addTrail(root, EXHAUST, 0.3, 2.4)
			local t0 = os.clock()
			while os.clock() - t0 < dashTime and root.Parent do
				afterimage(char, EXHAUST, 0.25)
				streaks(root.Position, -flatten(root.CFrame.LookVector, root), 2, 2, 5, 10, WIND, 0.2)
				task.wait(0.045)
			end
			stopTrail(0)
			if not root.Parent then
				return
			end
			local d = flatten(root.CFrame.LookVector, root)
			local p = root.Position + d * 3
			shockDisc(p, d, 3, last and 18 + level * 6 or 12, 0.3, EXHAUST)
			moonArc(CFrame.lookAt(p, p + d), last and 6 or 4.5, EXHAUST, 200)
			VFX.PlaySound(last and "ReciproBoom" or "Kick", p, last and 1 or 0.8)
			if last and level == 3 then
				-- the sound barrier
				billboardRing(p, 4, 46, Color3.new(1, 1, 1), 10, 0.35)
				shockDisc(p, d, 8, 50, 0.45, WIND, 25)
				if isLocal then
					VFX.ImpactFrame(0.08)
				end
			end
			VFX.ShakeAt(p, last and 1.2 + level * 0.5 or 0.8, 70, 0.25)
			if not last then
				task.wait(0.08)
			end
		end
	end

	-- (round 75) R: RECIPRO EXTEND. The mufflers slide out of his calves
	-- (white-hot at the ends), he drops into a sprinter's start with the
	-- engines screaming - and goes, one rocket of a kick down the aim; the
	-- one he meets rides his leg along, then the engines fire again
	POSES.SprinterStart = {
		Crouch = 0.8, Waist = { -38, 0, 0 }, Neck = { 26, 0, 0 },
		RightArm = { -45, 0, 12 }, LeftArm = { 55, 0, -8 }, RightElbow = 30, LeftElbow = 40,
		RightLeg = { -38, 0, 6 }, LeftLeg = { 48, 0, 4 }, RightKnee = 30, LeftKnee = 90,
	}
	POSES.ExtendKick = {
		Waist = { 8, 0, -10 }, Neck = { -6, 0, 8 }, RightLeg = { 92, 0, 6 }, LeftLeg = { -24, 0, 4 }, LeftKnee = 60,
		RightArm = { -30, 0, 30 }, LeftArm = { 40, 0, 20 },
	}
	IR.pipes = setmetatable({}, { __mode = "k" })
	function IR.extendPipes(char, life)
		local token = {}
		IR.pipes[char] = token
		local list = {}
		for _, name in { "Right Leg", "Left Leg", "RightLowerLeg", "LeftLowerLeg" } do
			local leg = char:FindFirstChild(name)
			if leg then
				for k = -1, 1, 2 do
					local off = CFrame.new(k * 0.26, -0.15, 0.55)
					local pipe = newPart(Vector3.new(0.26, 0.26, 0.4), leg.CFrame * off, Color3.fromRGB(190, 200, 214), Enum.Material.Metal)
					local tip = newPart(Vector3.new(0.32, 0.32, 0.14), leg.CFrame * off, Color3.fromRGB(150, 215, 255), Enum.Material.Neon)
					table.insert(list, { leg = leg, off = off, pipe = pipe, tip = tip })
				end
			end
		end
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < life and IR.pipes[char] == token and char.Parent do
				local k = math.clamp((os.clock() - t0) / 0.25, 0, 1) -- (they slide out)
				for _, e in list do
					if e.leg.Parent then
						local len = 0.4 + 1.5 * k
						e.pipe.Size = Vector3.new(0.26, 0.26, len)
						e.pipe.CFrame = e.leg.CFrame * e.off * CFrame.new(0, 0, len / 2)
						e.tip.CFrame = e.leg.CFrame * e.off * CFrame.new(0, 0, len + 0.07)
					end
				end
				task.wait()
			end
			for _, e in list do
				e.pipe:Destroy()
				e.tip:Destroy()
			end
		end)
		return list
	end
	function IR.pipeExhaust(list, scale)
		for _, e in list do
			if e.tip.Parent then
				local back = (e.tip.CFrame * CFrame.new(0, 0, 1)).Position
				shockDisc(e.tip.Position, (back - e.tip.Position).Unit, 0.3, 2 * scale, 0.18, EXHAUST)
				sparks(e.tip.Position, 0.25 * scale, Color3.new(1, 1, 1), EXHAUST, 2)
			end
		end
	end
	function Effects.ReciproExtend(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("ReciproExtend") or {}
		local startup = ability.Startup or 0.45
		local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Callout("RECIPRO... EXTEND!!", Color3.fromRGB(150, 215, 255))
		end
		local list = IR.extendPipes(char, startup + (ability.Range or 95) / (ability.Speed or 175) + (ability.Carry or 0.4) + 0.8)
		VFX.Pose(char, "SprinterStart", startup + 0.05)
		VFX.PlaySound("ReciproRev", root.Position, 1)
		local t0 = os.clock()
		while os.clock() - t0 < startup and root.Parent do
			IR.pipeExhaust(list, 1 + (os.clock() - t0) / startup)
			task.wait(0.06)
		end
	end
	function Effects.ReciproExtendGo(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
		local time = tonumber(data.Time) or 0.5
		local speed = tonumber(data.Speed) or 175
		local mine = isLocal or (Players.LocalPlayer and Players.LocalPlayer.Character == char)
		if mine then
			IR.steer(root, speed, time, d)
			VFX.Hooks.SpeedLines(time + 0.3)
		end
		VFX.Pose(char, "ExtendKick", time + 0.1)
		local g = groundPoint(root.Position)
		shockDisc(root.Position - d * 2, -d, 2, 16, 0.3, EXHAUST, 4)
		billboardRing(root.Position - d * 2, 2, 14, Color3.new(1, 1, 1), 5, 0.25)
		dustPuffs(g, 1, 5, Color3.fromRGB(206, 196, 186), 0.8, false)
		VFX.PlaySound("ReciproBoom", root.Position, 1)
		local stopTrail = addTrail(root, EXHAUST, 0.45, 3)
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent do
			afterimage(char, EXHAUST, 0.25)
			streaks(root.Position, -d, 3, 2, 6, 14, WIND, 0.2)
			task.wait(0.04)
		end
		stopTrail(0)
	end
	-- the kick lands: he carries them along on it
	function Effects.ReciproExtendHit(char, data, isLocal)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
		local carry = tonumber(data.Carry) or 0.4
		local mine = isLocal or (Players.LocalPlayer and Players.LocalPlayer.Character == char)
		if mine then
			IR.steer(root, tonumber(data.Speed) or 120, carry, d)
		end
		local pos = troot and troot.Position or root.Position + d * 3
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		if mine or me == target then
			VFX.ImpactFrame(0.08)
		end
		shockDisc(pos, d, 2, 14, 0.25, Color3.new(1, 1, 1), 3)
		sparks(pos, 1, Color3.new(1, 1, 1), EXHAUST, 18)
		VFX.PlaySound("HeavyHit", pos, 1)
		VFX.ShakeAt(pos, 1.6, 70, 0.3)
		VFX.Pose(char, "ExtendKick", carry + 0.1)
		local t0 = os.clock()
		while os.clock() - t0 < carry and root.Parent do
			streaks(root.Position + d * 2, -d, 3, 2, 6, 12, EXHAUST, 0.2)
			task.wait(0.05)
		end
	end
	-- the engines fire again: off they go
	function Effects.ReciproExtendLaunch(char, data)
		local root = charParts(char)
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or (root and root.CFrame.LookVector) or Vector3.new(0, 0, -1)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
		if not pos then
			return
		end
		if root then
			VFX.Motion(char, "StLouis")
		end
		shockDisc(pos, d, 3, 30, 0.4, EXHAUST, 10)
		billboardRing(pos, 3, 36, Color3.new(1, 1, 1), 9, 0.35)
		moonArc(CFrame.lookAt(pos, pos + d), 6, EXHAUST, 220)
		streaks(pos, d, 18, 3, 10, 34, WIND, 0.35)
		VFX.PlaySound("ReciproBoom", pos, 1.2)
		VFX.PlaySound("SonicBoom", pos, 0.8)
		VFX.ShakeAt(pos, 2.4, 110, 0.4)
		if nearCamera(pos, 80) then
			VFX.Hooks.Flash(Color3.fromRGB(210, 235, 255), 0.2)
		end
	end
	-- nobody there: a long skid, sparks off his heels
	function Effects.ReciproExtendWhiff(char)
		local root = charParts(char)
		if not root then
			return
		end
		IR.pipes[char] = nil
		VFX.Pose(char, "Land", 0.4)
		local g = groundPoint(root.Position)
		dustPuffs(g, 1.2, 6, Color3.fromRGB(206, 196, 186), 0.9, true)
		sparks(g + UP * 0.3, 0.6, Color3.new(1, 1, 1), EXHAUST, 12)
		VFX.PlaySound("Skid", g, 1)
	end

	-- a held move that never went: the rev-up just stops
	function Effects.HoldCancel(char)
		IR.charging[char] = nil
		VFX.coloradoCharge[char] = nil -- (round 75: Colorado's crouch)
		VFX.ReleasePose(char)
		if VFX.NukeDrop then
			VFX.NukeDrop(char) -- (the NUKE too: knocked out holding it)
		end
		if VFX.SEDrop then
			VFX.SEDrop(char) -- (and Suneater's Plasma Cannon)
		end
		if VFX.FaJinDrop then
			VFX.FaJinDrop(char) -- (and Deku's Fa Jin wind-up)
		end
	end

	-- SKYWARD KICK: a leg straight up, and he hops up after them
	function Effects.SkywardKick(char, data, isLocal)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "Skyward")
		exhaust(char, 0.4, 1.3)
		task.wait(0.14)
		if not root.Parent then
			return
		end
		local p = root.Position + d * 3 + UP * 2
		shockDisc(p, UP, 2, 16, 0.3, EXHAUST, 10)
		streaks(p, UP, 10, 1.5, 7, 18, WIND, 0.3)
		moonArc(CFrame.lookAt(p, p + UP) * CFrame.Angles(0, math.rad(90), 0), 5, EXHAUST, 180)
		VFX.PlaySound("Uppercut", p, 1)
		VFX.ShakeAt(p, 1, 50, 0.2)
		if isLocal and hum then
			task.delay(0.08, function()
				if root.Parent then
					launch(root, hum, UP * 85 + d * 6)
				end
			end)
		end
	end
end

function Effects.ReciproTurbo(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	local right = d:Cross(UP)
	if isLocal then
		face(root, d)
		VFX.Hooks.Dim(0.55, 0.9)
	end
	VFX.Pose(char, "Rev", 0.45)
	exhaust(char, 1.3, 2)
	VFX.PlaySound("Engine", root.Position, 1.2)
	-- rev up: electric-blue crackle around the calves
	local t0 = os.clock()
	while os.clock() - t0 < 0.45 and root.Parent do
		for _, leg in calves(char) do
			bolt(leg.Position, 1.5, EXHAUST)
		end
		task.wait(0.05)
	end
	if not root.Parent then
		return
	end
	dustPuffs(groundPoint(root.Position), 1.2, 8, Color3.fromRGB(205, 196, 190), 1, true)
	shockDisc(root.Position, d, 4, 24, 0.3, EXHAUST)
	local stopTrail = addTrail(root, EXHAUST, 0.35, 3)
	legTrails(char, 0.7, EXHAUST)
	-- zig-zag blur rush (5 legs x 0.11s)
	for i = 1, 5 do
		if not root.Parent then
			break
		end
		local side = (i % 2 == 0) and 1 or -1
		local v = i == 5 and d or (d + right * side * 0.45).Unit
		if isLocal then
			face(root, v)
			dash(root, v * 200, 0.11)
		end
		VFX.Pose(char, i % 2 == 0 and "Kick" or "Rev", 0.12)
		afterimage(char, EXHAUST, 0.35)
		streaks(root.Position, -v, 4, 2, 6, 12, WIND, 0.2)
		task.wait(0.055)
		afterimage(char, EXHAUST_CORE, 0.3)
		task.wait(0.055)
	end
	stopTrail(0)
	if not root.Parent then
		return
	end
	if isLocal then
		face(root, d)
	end
	-- flurry (timed with the server's extra hits)
	for _ = 1, 2 do
		task.wait(0.09)
		local p = root.Position + d * 3 + rng:NextUnitVector() * 2
		moonArc(CFrame.lookAt(p, p + d) * CFrame.Angles(0, 0, rand(0, 6)), 3.5, EXHAUST, 160)
		shockDisc(p, d, 1, 8, 0.15, WIND)
	end
	task.wait(0.12)
	VFX.Pose(char, "Kick", 0.5)
	local p = root.Position + d * 4
	if nearCamera(p, 110) then
		VFX.Hooks.Flash(Color3.fromRGB(215, 235, 255), 0.25)
	end
	for i = 1, 4 do
		task.delay(i * 0.03, function()
			shockDisc(p, d, 6, 30, 0.45, WIND, 50)
		end)
	end
	moonArc(CFrame.lookAt(p, p + d), 8, EXHAUST, 220)
	streaks(p, d, 30, 6, 14, 90, EXHAUST_CORE, 0.35)
	VFX.PlaySound("Kick", p, 1.2)
	VFX.ShakeAt(p, 3, 160, 0.5)
end

---------------------------------------------------------------------------
-- Shared helpers for the new moves
---------------------------------------------------------------------------

-- (one palette table for the beam / Limitless colours: Luau's local limit)
local PAL = {
	AP_CORE = Color3.fromRGB(255, 252, 226),
	PHOSPHOR_CORE = Color3.fromRGB(255, 255, 255),
	PHOSPHOR_GLOW = Color3.fromRGB(160, 170, 255),
}

-- 3D aim (beams can shoot up at rooftops)
local function aimDir(data, root)
	local v = data.Dir
	if typeof(v) ~= "Vector3" or v.Magnitude < 0.05 then
		return root.CFrame.LookVector
	end
	return v.Unit
end

-- Aim point snapped to the ground within range (same maths as the server)
local function aimGround(root, data, range)
	local d = flatten(data.Dir, root)
	local aim = typeof(data.Pos) == "Vector3" and data.Pos or root.Position + d * 30
	local flat = Vector3.new(aim.X - root.Position.X, 0, aim.Z - root.Position.Z)
	if flat.Magnitude > range then
		flat = flat.Unit * range
	end
	local xz = root.Position + flat
	local hit = groundRay(Vector3.new(xz.X, root.Position.Y + 22, xz.Z), 90)
	return hit and hit.Position or Vector3.new(xz.X, root.Position.Y - 3, xz.Z)
end

-- NUKE (the PLUS ULTRA dev kit's V)
do
	-- NUKE: he summons a sun-sized bomb over his head. It keeps growing while
	-- he holds it (the street around him is pulled up toward it), then he
	-- throws it at wherever he's aiming and it goes off like a small sun.
	-- (packed into one table: this block is close to Luau's local limit)
	local NK = { ROCK = Color3.fromRGB(96, 88, 84), holds = {} } -- holds: [char] = the bomb over their head

	-- the blast itself, where it lands. Everything scales with ability.Radius;
	-- the ground wave rolls out at WaveSpeed so what you see reach you is
	-- what hits you.
	function NK.detonate(center, lifted, ability)
		local R = ability.Radius or 200
		local wave = math.max(ability.WaveSpeed or 420, 1)
		local S = R / 72 -- (the old blast was 72 studs)
		local ground = groundPoint(center)
		local cam = workspace.CurrentCamera
		local myDist = cam and (cam.Focus.Position - center).Magnitude or math.huge
		if myDist < R * 4.5 then
			VFX.ImpactFrame(0.3)
		end
		if myDist < R * 6 then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), myDist < R and 1.6 or 1)
			-- the whole sky burns orange for a while after the flash
			local lighting = game:GetService("Lighting")
			local tint = Instance.new("ColorCorrectionEffect")
			tint.Name = "NukeTint"
			tint.TintColor = Color3.fromRGB(255, 186, 130)
			tint.Brightness = 0.15
			tint.Contrast = 0.15
			tint.Parent = lighting
			tween(tint, 6, { TintColor = Color3.new(1, 1, 1), Brightness = 0, Contrast = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.6)
			cleanup(tint, 6.8)
		end
		-- the fireball: a white-hot core inside yellow and red shells
		for i, spec in {
			{ Color3.new(1, 1, 1), 0, 120 * S, 0.3, 1.1 },
			{ BLAST_YELLOW, 0.3, 150 * S, 0.42, 1.5 },
			{ FIRE[4], 0.5, 185 * S, 0.55, 1.7 },
		} do
			local ball = newPart(Vector3.one * 8, CFrame.new(center), spec[1], Enum.Material.Neon, Enum.PartType.Ball)
			ball.Transparency = spec[2]
			tween(ball, spec[4], { Size = Vector3.one * spec[3] })
			tween(ball, spec[5], { Size = Vector3.one * spec[3] * 1.1, Transparency = 1 }, nil, nil, spec[4])
			cleanup(ball, spec[4] + spec[5] + 0.1)
			if i == 1 then
				local light = Instance.new("PointLight")
				light.Range = 60
				light.Brightness = 20
				light.Color = Color3.fromRGB(255, 226, 150)
				light.Parent = ball
			end
		end
		billboardRing(center, 10, 170 * S, Color3.new(1, 1, 1), 0, 0.35, true)
		billboardRing(center, 20, 360 * S, BLAST_YELLOW, 26, 1.1)
		billboardRing(center, 30, 460 * S, FIRE[4], 18, 1.4)
		toonExplosion(center, 10 * math.sqrt(S), { SmokeLife = 7 })
		-- everything it pulled in gets thrown back out
		for _, p in lifted do
			if p.Parent then
				local out = p.Position - center
				out = Vector3.new(out.X, 0, out.Z)
				out = (out.Magnitude > 0.1 and out.Unit or rng:NextUnitVector()) * rand(70, 140) + UP * rand(15, 50)
				tween(p, 0.9, { CFrame = CFrame.new(p.Position + out) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), Transparency = 1 })
				cleanup(p, 0.95)
			end
		end
		-- THE BLAST WAVE, along the ground at WaveSpeed: a ring of air you can
		-- see, a wall of dust riding it, and the shake arrives with it
		local reach = R * 1.15
		for i = 1, 3 do
			task.delay((i - 1) * 0.08, function()
				local disc = newPart(Vector3.new(0.6, 30, 30), CFrame.new(ground + UP * (1 + i * 2)) * CFrame.Angles(0, 0, math.rad(90)), i == 2 and FIRE[2] or WIND, Enum.Material.ForceField, Enum.PartType.Cylinder)
				tween(disc, reach / wave, { Size = Vector3.new(0.6, reach * 2, reach * 2) }, Enum.EasingStyle.Linear)
				tween(disc, 0.5, { Transparency = 1 }, nil, nil, reach / wave - 0.2)
				cleanup(disc, reach / wave + 0.4)
			end)
		end
		for _, r in { 0.12, 0.25, 0.4, 0.57, 0.76, 0.95 } do
			local rad = r * R
			local count = math.clamp(math.floor(rad / 9), 10, 26)
			for k = 1, count do
				local a = k / count * math.pi * 2 + r * 3
				local at = ground + Vector3.new(math.cos(a), 0, math.sin(a)) * rad
				task.delay(rad / wave + rand(0, 0.05), function()
					dustPuffs(at, 2.2 + S, 2, Color3.fromRGB(206, 196, 186), 2.6, false)
				end)
			end
		end
		if cam then
			local d = (cam.Focus.Position - ground).Magnitude
			task.delay(math.min(d, reach) / wave, function()
				VFX.Shake(math.clamp(9 * (1 - d / (R * 6)), 1.2, 9), 2)
			end)
			-- the sound gets to you a moment after the light does
			task.delay(math.min(d / 1100, 2), function()
				VFX.PlaySound("NukeBoom", center, 1.7)
			end)
		end
		-- the condensation ring, high up around the stem
		task.delay(0.3, function()
			shockDisc(ground + UP * 45 * S, UP, 30 * S, 220 * S, 2.4, WIND)
		end)
		-- secondary blasts ringing the crater, then an outer ring of whoomps
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			local rad = 0.5 * R
			task.delay(rad / wave + i * 0.03, function()
				toonExplosion(ground + Vector3.new(math.cos(a) * rad, 3, math.sin(a) * rad), 2.6 * math.sqrt(S), { NoScorch = true })
			end)
		end
		for i = 1, 12 do
			local a = i / 12 * math.pi * 2 + 0.3
			local rad = 0.8 * R
			task.delay(rad / wave + i * 0.03, function()
				Flame.burst(ground + Vector3.new(math.cos(a) * rad, 2, math.sin(a) * rad), 6 * math.sqrt(S), 12)
			end)
		end
		-- the column: real fire roaring up the middle while the smoke stem and
		-- the mushroom cap build over it
		Flame.column(ground, 70 * S, 9 * S, 3)
		local cloud = outlineModel(Color3.fromRGB(58, 50, 46))
		local stemTop = 110 * S
		for i = 1, 18 do
			local jitter = Vector3.new(rand(-3, 3), 0, rand(-3, 3)) * S
			celPuff(cloud, ground, ground + UP * (i / 18 * stemTop) + jitter, rand(14, 20) * S * (1 - i / 40), SMOKE_DARK, SMOKE_LIGHT, 1, 8, i * 0.05)
		end
		for k = 1, 24 do
			local a = k / 24 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local at = ground + UP * (stemTop + rand(-6, 8) * S) + out * rand(18, 42) * S
			celPuff(cloud, ground + UP * stemTop * 0.9, at, rand(18, 28) * S, SMOKE_DARK, SMOKE_LIGHT, 1.3, 8, 0.6 + k * 0.02)
			if k % 3 == 0 then
				-- the cap still glowing from inside before it cools to smoke
				celPuff(cloud, ground + UP * stemTop * 0.9, at - out * 6 * S, rand(12, 18) * S, FIRE[4], FIRE[2], 0.9, 1.2, 0.6 + k * 0.02)
			end
		end
		cleanup(cloud, 11)
		-- embers raining back down, fires left burning across the crater
		emberCloud(ground + UP * 50 * S, 70 * S, 7, 400)
		for _ = 1, 18 do
			local a, r = rand(0, math.pi * 2), rand(8, 0.6 * R)
			local spot = groundPoint(ground + Vector3.new(math.cos(a) * r, 6, math.sin(a) * r))
			task.delay(r / wave + rand(0.2, 0.8), function()
				Flame.spot(spot, rand(3, 5), rand(4, 7))
			end)
		end
		rocks(ground, 4 * math.sqrt(S), 60)
		groundMark(ground, 0.62 * R, Color3.fromRGB(30, 24, 22), 20)
	end

	-- let go of a bomb that was never thrown (he was knocked out holding it)
	function NK.drop(char)
		local hold = NK.holds[char]
		if not hold then
			return
		end
		NK.holds[char] = nil
		hold.over = true
		VFX.ReleasePose(char) -- (arms down)
		for _, p in { hold.core, hold.shell, hold.halo } do
			if p.Parent then
				tween(p, 0.35, { Size = Vector3.one * 0.5, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(p, 0.4)
			end
		end
		for _, p in hold.lifted do
			if p.Parent then
				p.Anchored = false
				p.CanCollide = false
				tween(p, 0.6, { Transparency = 1 })
				cleanup(p, 0.7)
			end
		end
		if hold.core.Parent then
			smokeBurst(hold.core.Position, SMOKE_LIGHT, 6, 8, 1, 14)
		end
	end

	-- G / the key: SUMMON. The bomb forms over his head and grows for as long
	-- as he holds it (MaxCharge at most)
	function Effects.Nuke(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local maxCharge = (ability.Hold and ability.Hold.Max) or ability.MaxCharge or 3
		local size = ability.BombSize or 40
		NK.drop(char)
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.35, 0.8)
		end
		VFX.Pose(char, "ArmsUp", maxCharge + 1.5)
		VFX.PlaySound("NukeCharge", root.Position, 1.2)
		local base = groundPoint(root.Position)
		toonExplosion(base, 1.6, { NoDebris = true })
		shockDisc(base + UP * 0.4, UP, 4, 40, 0.5, WIND)
		-- a white-hot core inside a yellow shell, a red glow round it
		local at = CFrame.new(root.Position + UP * 8)
		local hold = {
			start = os.clock(),
			core = newPart(Vector3.one, at, Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball),
			shell = newPart(Vector3.one, at, BLAST_YELLOW, Enum.Material.Neon, Enum.PartType.Ball),
			halo = newPart(Vector3.one, at, FIRE[4], Enum.Material.Neon, Enum.PartType.Ball),
			lifted = {},
			pos = at.Position,
			diameter = 1,
		}
		hold.core.Name = "NukeCore"
		hold.shell.Transparency = 0.25
		hold.halo.Transparency = 0.6
		local light = Instance.new("PointLight")
		light.Range = 60
		light.Brightness = 10
		light.Color = Color3.fromRGB(255, 214, 130)
		light.Parent = hold.core
		NK.holds[char] = hold
		local lastPulse, lastRock = 0, 0
		while not hold.over and root.Parent and os.clock() - hold.start < maxCharge + 1.5 do
			local now = os.clock()
			local k = math.min((now - hold.start) / maxCharge, 1)
			local diameter = size * (0.12 + 0.88 * k)
			local pos = root.Position + UP * (5 + diameter * 0.55)
			hold.pos, hold.diameter = pos, diameter
			hold.core.Size = Vector3.one * diameter * 0.55
			hold.shell.Size = Vector3.one * diameter
			hold.halo.Size = Vector3.one * diameter * 1.35
			hold.core.CFrame = CFrame.new(pos)
			hold.shell.CFrame = CFrame.new(pos)
			hold.halo.CFrame = CFrame.new(pos)
			if rng:NextNumber() < 0.6 then
				bolt(pos, diameter * 0.6, FIRE[1])
			end
			-- energy sucked in from all around
			for _ = 1, 1 + math.floor(k * 3) do
				local from = pos + rng:NextUnitVector() * rand(diameter, diameter * 2.5)
				local seg = newPart(Vector3.new(0.5, 0.5, 6), CFrame.lookAt(from, pos), FIRE[rng:NextInteger(1, 3)], Enum.Material.Neon)
				tween(seg, 0.25, { CFrame = CFrame.lookAt(pos, pos + (pos - from)), Size = Vector3.new(0.1, 0.1, 2), Transparency = 0.6 })
				cleanup(seg, 0.3)
			end
			-- pulses that come faster as it grows
			if now - lastPulse > 0.3 - 0.2 * k then
				lastPulse = now
				billboardRing(pos, diameter * 2.2, diameter * 0.6, BLAST_YELLOW, 8, 0.22)
				VFX.PlaySound("NukePulse", pos, 0.5 + k * 0.5)
				VFX.ShakeAt(pos, 0.5 + k * 2.2, 120 + diameter * 4, 0.14)
			end
			-- the street tears loose and floats up toward it
			if now - lastRock > 0.06 and #hold.lifted < 30 then
				lastRock = now
				local a, r = rand(0, math.pi * 2), rand(6, 14 + diameter * 0.5)
				local spot = groundPoint(root.Position + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r))
				local s = rand(0.8, 2.2)
				local chunk = newPart(Vector3.new(s, s * 0.6, s * rand(0.8, 1.3)), CFrame.new(spot) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), NK.ROCK:Lerp(Color3.new(), rand(0, 0.3)), Enum.Material.Slate)
				tween(chunk, 1.6, { CFrame = CFrame.new(spot + UP * rand(6, 16)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Sine)
				cleanup(chunk, maxCharge + 4)
				table.insert(hold.lifted, chunk)
			end
			task.wait(0.03)
		end
		if not hold.over then
			NK.drop(char) -- (never thrown: it fizzles)
		end
	end

	-- the throw: the bomb arcs to where he aimed and goes off there. His own
	-- screen plays it the moment he throws (data.Pos = his aim); everyone
	-- else gets the server's landing spot (data.Target)
	function Effects.NukeThrow(char, data, _isLocal, ability)
		local root = charParts(char)
		ability = ability or Config.FindAbilityById("Nuke") or {}
		local hold = NK.holds[char]
		local target = typeof(data.Target) == "Vector3" and data.Target or (root and aimGround(root, data, ability.Range or 300))
		if not target then
			NK.drop(char)
			return
		end
		if hold then
			NK.holds[char] = nil
			hold.over = true
		end
		local scale = tonumber(data.Scale) or 1
		local diameter = (ability.BombSize or 40) * scale
		local from = typeof(data.From) == "Vector3" and data.From or (hold and hold.pos) or (root and root.Position + UP * (5 + diameter * 0.55)) or target + UP * 60
		if hold then
			from = hold.pos
		end
		local core = hold and hold.core or newPart(Vector3.one * diameter * 0.55, CFrame.new(from), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		local shell = hold and hold.shell or newPart(Vector3.one * diameter, CFrame.new(from), BLAST_YELLOW, Enum.Material.Neon, Enum.PartType.Ball)
		local halo = hold and hold.halo or newPart(Vector3.one * diameter * 1.35, CFrame.new(from), FIRE[4], Enum.Material.Neon, Enum.PartType.Ball)
		if hold then
			-- (it swells to its full thrown size as it leaves his hands)
			tween(core, 0.3, { Size = Vector3.one * diameter * 0.55 })
			tween(shell, 0.3, { Size = Vector3.one * diameter })
			tween(halo, 0.3, { Size = Vector3.one * diameter * 1.35 })
			for _, p in hold.lifted do
				if p.Parent then
					p.Anchored = false -- (what it was holding up falls)
					p.CanCollide = false
					tween(p, 1, { Transparency = 1 }, nil, nil, 0.4)
					cleanup(p, 1.5)
				end
			end
		end
		if char.Parent then
			VFX.Pose(char, "Throw", 0.6)
		end
		VFX.PlaySound("BombThrow", from, 1.2)
		VFX.PlaySound("Leap", from, 1)
		local stopTrail = addTrail(shell, FIRE[3], 0.5, math.min(diameter * 0.5, 20))
		local flight = math.clamp((target - from).Magnitude / 200, 0.5, 1.6)
		local lift = math.min((target - from).Magnitude * 0.25, 90)
		local t0 = os.clock()
		while os.clock() - t0 < flight do
			local t = (os.clock() - t0) / flight
			local p = from:Lerp(target + UP * 6, t) + UP * lift * 4 * t * (1 - t)
			core.CFrame, shell.CFrame, halo.CFrame = CFrame.new(p), CFrame.new(p), CFrame.new(p)
			task.wait()
		end
		stopTrail(0)
		core:Destroy()
		shell:Destroy()
		halo:Destroy()
		NK.detonate(target + UP * 6, {}, {
			Radius = (ability.Radius or 260) * scale,
			WaveSpeed = ability.WaveSpeed or 480,
		})
	end

	VFX.NukeDetonate = NK.detonate -- (Iida's prank goes off the same way)

	-- the server: he was knocked out holding it
	function Effects.NukeFizzle(char)
		NK.drop(char)
	end
	VFX.NukeDrop = NK.drop

	-- his own key came up: the throw, sized by how long he held it (the same
	-- maths as the server)
	function Effects.NukeRelease(char, data, isLocal, ability)
		ability = ability or Config.FindAbilityById("Nuke") or {}
		local hold = NK.holds[char]
		local maxCharge = (ability.Hold and ability.Hold.Max) or ability.MaxCharge or 3
		local minCharge = ability.MinCharge or 0.6
		local held = hold and (os.clock() - hold.start) or 0
		local k = math.clamp((held - minCharge) / math.max(maxCharge - minCharge, 0.1), 0, 1)
		local minScale = ability.MinScale or 0.7
		Effects.NukeThrow(char, { Dir = data.Dir, Pos = data.Pos, Scale = minScale + (1 - minScale) * k }, isLocal, ability)
	end

end

-- Straight glowing beam: flares out, then thins away
local function beam(a, b, radius, core, glow, life)
	local len = math.max((b - a).Magnitude, 0.1)
	local cf = CFrame.lookAt((a + b) / 2, b) * CFrame.Angles(0, math.rad(90), 0)
	local outer = newPart(Vector3.new(len, radius * 0.6, radius * 0.6), cf, glow, Enum.Material.Neon, Enum.PartType.Cylinder)
	outer.Transparency = 0.4
	local inner = newPart(Vector3.new(len, radius * 0.3, radius * 0.3), cf, core, Enum.Material.Neon, Enum.PartType.Cylinder)
	tween(outer, 0.05, { Size = Vector3.new(len, radius * 2.6, radius * 2.6) })
	tween(inner, 0.05, { Size = Vector3.new(len, radius, radius) })
	tween(outer, life, { Size = Vector3.new(len, 0.05, 0.05), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.05)
	tween(inner, life, { Size = Vector3.new(len, 0.05, 0.05) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.05)
	cleanup(outer, life + 0.1)
	cleanup(inner, life + 0.1)
end

local function firstHit(from, dir, maxLen)
	rayParams.FilterDescendantsInstances = characterList()
	local hit = workspace:Raycast(from, dir * maxLen, rayParams)
	return hit and hit.Position or nil
end

local function fireball(from, to, time, size)
	local p = newPart(Vector3.one * size, CFrame.new(from), FIRE[2], Enum.Material.Neon, Enum.PartType.Ball)
	local stop = addTrail(p, FIRE[3], 0.2, size)
	tween(p, time, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Linear)
	task.delay(time, function()
		stop(0)
		p.Transparency = 1
	end)
	cleanup(p, time + 0.5)
end

---------------------------------------------------------------------------
-- EXPLOSION (later seasons)
---------------------------------------------------------------------------

-- AP Shot: pinpoint, armour-piercing explosion beam from the palm
do -- EXPLOSION: its helpers stay local to this block (Luau allows 200 locals per scope)
	local function apShot(char, dir, right, scale)
		local from = handPos(char, right) + dir
		local to = from + dir * 160
		beam(from, to, 0.9 * scale, PAL.AP_CORE, FIRE[2], 0.3)
		billboardRing(from, 2 * scale, 12 * scale, Color3.fromRGB(255, 238, 60), 8, 0.25)
		for i = 1, 5 do
			task.delay(i * 0.015, function()
				shockDisc(from + dir * (i * 7), dir, 3 * scale, 0.4, 0.22, FIRE[1], 8)
			end)
		end
		toonExplosion(from, 0.5 * scale, { NoDebris = true, NoScorch = true, NoEmbers = true })
		local hitPos = firstHit(from, dir, 160)
		if hitPos then
			toonExplosion(hitPos, 1.2 * scale, { NoScorch = true })
		end
		VFX.PlaySound("Beam", from, 0.9)
		VFX.ShakeAt(from, 0.9 * scale, 60, 0.2)
	end

	function Effects.APShot(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		-- straight out on the ground; anywhere below him in the air
		ability = ability or {}
		local dir = Config.AimedDirection(aimDir(data, root), root.CFrame.LookVector, data.Air and ability.AirAim or ability.Aim)
		if isLocal then
			face(root, dir)
			if data.Air and hum then
				-- the recoil kicks him up and back
				task.delay(0.18, function()
					if root.Parent then
						launch(root, hum, -dir * 55 + UP * 35)
					end
				end)
			end
		end
		VFX.Pose(char, "APShot", 0.5)
		local hand = handPos(char, true)
		shockDisc(hand + dir, dir, 5, 0.6, 0.18, FIRE[2])
		local glow = newPart(Vector3.one * 0.3, CFrame.new(hand), PAL.AP_CORE, Enum.Material.Neon, Enum.PartType.Ball)
		tween(glow, 0.18, { Size = Vector3.one * 1.8 })
		cleanup(glow, 0.2)
		sparks(hand, 0.5)
		task.wait(0.18)
		if root.Parent then
			apShot(char, dir, true, 1.9)
		end
	end

	function Effects.AutoCannon(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local dir = aimDir(data, root)
		if isLocal then
			face(root, dir)
		end
		if not isLocal then
			return -- (everyone else sees each shot as the server fires it: AutoCannonShot)
		end
		task.wait(0.12)
		for i = 1, (ability and ability.Shots) or 6 do
			if not root.Parent then
				return
			end
			-- he keeps aiming while he fires: each shot goes where you aim now
			local live = VFX.Hooks.Aim and VFX.Hooks.Aim()
			if typeof(live) == "Vector3" and live.Magnitude > 0.01 then
				dir = live.Unit
				face(root, dir)
			end
			local right = i % 2 == 1
			VFX.Pose(char, right and "PunchR" or "PunchL", 0.12)
			apShot(char, dir, right, 1.3)
			task.wait(0.15)
		end
	end

	-- (one shot of someone else's Auto-Cannon, wherever they aimed it)
	function Effects.AutoCannonShot(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local dir = aimDir(data, root)
		local right = (tonumber(data.Index) or 1) % 2 == 1
		VFX.Pose(char, right and "PunchR" or "PunchL", 0.12)
		apShot(char, dir, right, 1.3)
	end

	function Effects.StunGrenade(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "Clap", 0.45)
		sparks(handPos(char, true), 0.6, Color3.new(1, 1, 1), FIRE[1], 12)
		task.wait(0.25)
		if not root.Parent then
			return
		end
		local pos = root.Position
		local ball = newPart(Vector3.one * 2, CFrame.new(pos), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(ball, 0.12, { Size = Vector3.one * 68 })
		tween(ball, 0.4, { Transparency = 1, Size = Vector3.one * 76 }, nil, nil, 0.12)
		cleanup(ball, 0.6)
		local light = Instance.new("PointLight")
		light.Range = 60
		light.Brightness = 10
		light.Parent = ball
		shockDisc(pos, UP, 8, 92, 0.45, Color3.new(1, 1, 1))
		billboardRing(pos, 6, 70, Color3.new(1, 1, 1), 10, 0.4)
		sparks(pos, 2.5, Color3.new(1, 1, 1), FIRE[1], 70)
		toonExplosion(pos, 1, { NoDebris = true, NoScorch = true })
		if not isLocal and nearCamera(pos, 30) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.5)
		end
		VFX.PlaySound("Grenade", pos, 1)
		VFX.ShakeAt(pos, 1.5, 70, 0.3)
	end

	-- Server tells a player they were caught in a Stun Grenade without their
	-- guard up: white-out, a ringing in the ears, and it only slowly clears
	function Effects.Blind(_, data)
		local duration = data.Duration or 2.6
		if VFX.Hooks.Blind then
			VFX.Hooks.Blind(duration)
		else
			VFX.Hooks.Flash(Color3.new(1, 1, 1), duration)
		end
		local cam = workspace.CurrentCamera
		VFX.PlaySound("Ringing", cam and cam.Focus.Position or Vector3.zero, 1)
	end

	function Effects.Cluster(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local target = aimGround(root, data, (ability and ability.Range) or 90)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.5, 1.9)
			launch(root, hum, d * 25 + Vector3.new(0, 105, 0))
		end
		VFX.Pose(char, "ArmsUp", 0.35)
		toonExplosion(groundPoint(root.Position), 1.3, { NoDebris = true })
		task.wait(0.35)
		-- rain a cluster of explosive shots around the target (same seeded ring as the server)
		local ring = Random.new(typeof(data.Seed) == "number" and data.Seed or 1)
		local offset = ring:NextNumber(0, math.pi * 2)
		for i = 1, 8 do
			if not root.Parent then
				return
			end
			local a = offset + i / 8 * math.pi * 2
			local r = 11 + (i % 2) * 12
			local p = target + Vector3.new(math.cos(a) * r, 2, math.sin(a) * r)
			local right = i % 2 == 0
			VFX.Pose(char, right and "PunchR" or "PunchL", 0.1)
			fireball(handPos(char, right), p, 0.15, 2.2)
			task.delay(0.15, function()
				toonExplosion(p, 2.2, { SmokeLife = 1.8 })
			end)
			task.wait(0.075)
		end
		task.wait(0.1)
		if not root.Parent then
			return
		end
		-- dive in with a Howitzer spin
		VFX.Pose(char, "ArmsUp", 1)
		local cancelDive
		if isLocal then
			local dv = (target + UP * 2) - root.Position
			cancelDive = dash(root, (dv.Magnitude > 1 and dv.Unit or -UP) * 190, 0.7)
		end
		local model = outlineModel(FLAME_OUTLINE)
		local t0 = os.clock()
		repeat
			local t = os.clock() - t0
			for k = 0, 1 do
				local a = t * 30 + k * math.pi
				local p = root.Position + Vector3.new(math.cos(a) * 3.5, 0, math.sin(a) * 3.5)
				local puff = newPart(Vector3.one * 2.6, CFrame.new(p), FIRE[rng:NextInteger(2, 4)], Enum.Material.Neon, Enum.PartType.Ball, model)
				tween(puff, 0.25, { Size = Vector3.one * 0.1 })
			end
			task.wait(0.03)
		until not root.Parent or os.clock() - t0 > 0.65 or (os.clock() - t0 > 0.05 and isGrounded(root))
		cleanup(model, 0.4)
		if cancelDive then
			cancelDive()
		end
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position) + UP * 3
		toonExplosion(center, 6.6, { SmokeLife = 4.5 })
		shockDisc(center, UP, 12, 170, 0.65, FIRE[2])
		shockDisc(center + UP * 2, UP, 10, 120, 0.5, Color3.new(1, 1, 1))
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			task.delay(0.1 + i * 0.04, function()
				toonExplosion(center + Vector3.new(math.cos(a) * 30, 0, math.sin(a) * 30), 2.4, { NoScorch = true })
			end)
		end
		if nearCamera(center, 140) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.4)
		end
		VFX.ShakeAt(center, 5, 260, 1)
	end

	-- (Bakugo's newer moves share one table: this block is close to Luau's
	-- local limit)
	local BK = {}

	-- a blast right off the palm: the flash, the fire, a puff of smoke, sparks
	function BK.palm(pos, dir, scale)
		toonExplosion(pos + dir * 0.8 * scale, 0.7 * scale, { NoDebris = true, NoScorch = true, NoEmbers = scale < 1.2, SmokeLife = 0.7 })
		sparks(pos, 0.5 * scale, Color3.new(1, 1, 1), FIRE[1], math.floor(8 * scale))
		shockDisc(pos + dir * 0.5, dir, 0.6 * scale, 5 * scale, 0.14, FIRE[2], 2 * scale)
	end
	VFX.PalmBlast = BK.palm

	-- his own machine flies his body along a path (path(a) -> CFrame, a from
	-- 0 to 1); returns a stop function
	function BK.fly(char, root, hum, duration, path)
		local t0 = os.clock()
		local last = root.CFrame
		local conn
		local function stop()
			if conn then
				conn:Disconnect()
				conn = nil
				if hum and hum.Parent then
					hum.PlatformStand = false
					hum.AutoRotate = true
				end
			end
		end
		if hum then
			hum.PlatformStand = true
			hum.AutoRotate = false
		end
		conn = RunService.RenderStepped:Connect(function(dt)
			local a = math.clamp((os.clock() - t0) / duration, 0, 1)
			if not root.Parent or (hum and hum.Health <= 0) or char:GetAttribute("Ragdolled") then
				stop()
				return
			end
			local cf = path(a)
			root.CFrame = cf
			root.AssemblyLinearVelocity = (cf.Position - last.Position) / math.max(tonumber(dt) or 1 / 60, 1 / 240)
			last = cf
			if a >= 1 then
				stop()
			end
		end)
		return stop
	end
	VFX.Fly = BK.fly

	-- ERUPTION ORBIT, part 1: palm to the street, it erupts in front of him,
	-- and he blasts off after whoever it threw up (in the air: just the
	-- palms flaring - he goes straight for them)
	function Effects.BlastOrbit(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		if data.Air then
			VFX.Pose(char, "Blast", 0.3)
			BK.palm(handPos(char, true), d, 1.2)
			BK.palm(handPos(char, false), d, 1.2)
			VFX.PlaySound("Explosion", root.Position, 0.8)
			return
		end
		VFX.Motion(char, "EruptionSlam")
		sparks(handPos(char, true), 0.6, Color3.new(1, 1, 1), FIRE[1], 10)
		task.wait(0.28)
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position + d * (((ability and ability.Range) or 16) * 0.55))
		-- the street erupts: a column of fire out of the ground
		toonExplosion(center + UP * 2, 2.6, { SmokeLife = 2 })
		for i = 1, 5 do
			task.delay(i * 0.04, function()
				toonExplosion(center + UP * (3 + i * 4) + Vector3.new(rand(-1.5, 1.5), 0, rand(-1.5, 1.5)), 1.5 - i * 0.14, { NoDebris = true, NoScorch = true })
			end)
		end
		shockDisc(center + UP * 0.5, UP, 4, 40, 0.4, FIRE[2])
		rocks(center, 1.4, 14)
		groundMark(center, 8, Color3.fromRGB(40, 32, 30), 10)
		VFX.PlaySound("BigExplosion", center, 0.9)
		VFX.ShakeAt(center, 2.5, 90, 0.35)
		-- and he blasts off the street after them
		BK.palm(handPos(char, true), -UP, 1.4)
		BK.palm(handPos(char, false), -UP, 1.4)
		VFX.Pose(char, "BlastUp", 0.45)
		if isLocal and hum then
			launch(root, hum, UP * 105 + d * 12)
		end
	end

	-- ERUPTION ORBIT, part 2 (the server caught someone): he circles them,
	-- blasting from every side, then the last blast from above drives them
	-- into the street
	function Effects.BlastOrbitCatch(char, data)
		local root, hum = charParts(char)
		local targets = data.Targets or {}
		if not root or #targets == 0 or typeof(data.Center) ~= "Vector3" then
			return
		end
		local center = data.Center
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		local radius = 9
		local circle, total = 0.62, 0.88
		local rel = Vector3.new(root.Position.X - center.X, 0, root.Position.Z - center.Z)
		local start = rel.Magnitude > 0.5 and math.atan2(rel.Z, rel.X) or math.atan2(-d.Z, -d.X)
		local function around(k)
			local ang = start + k * math.pi * 3
			return center + Vector3.new(math.cos(ang) * radius, math.sin(k * math.pi) * 3, math.sin(ang) * radius)
		end
		if me and me.Character == char then
			BK.fly(char, root, hum, total, function(a)
				if a < circle / total then
					local p = around(a / (circle / total))
					return CFrame.lookAt(p, Vector3.new(center.X, p.Y, center.Z))
				end
				-- up over them, looking down
				local k = (a - circle / total) / (1 - circle / total)
				local from = around(1)
				local p = from:Lerp(center + UP * 9 - d * 0.5, 1 - (1 - k) ^ 2)
				return CFrame.lookAt(p, center + d * 0.5)
			end)
		end
		local stopTrail = addTrail(root, FIRE[3], 0.3, 2.4)
		for i = 1, 3 do
			task.delay(0.2 * i, function()
				if not root.Parent then
					return
				end
				local p = root.Position
				local toward = (center - p).Magnitude > 0.5 and (center - p).Unit or d
				VFX.Pose(char, i % 2 == 1 and "PunchR" or "PunchL", 0.15)
				BK.palm(handPos(char, i % 2 == 1), toward, 1.4)
				toonExplosion(center - toward * 1.5, 1.7, { NoDebris = true, NoScorch = true })
				VFX.PlaySound("Explosion", center, 0.9)
				VFX.ShakeAt(center, 1.2, 60, 0.15)
			end)
		end
		task.delay(total, function()
			stopTrail(0)
			if not root.Parent then
				return
			end
			-- the last one, from above, straight down
			VFX.Pose(char, "Blast", 0.45)
			BK.palm(handPos(char, true), -UP, 2)
			BK.palm(handPos(char, false), -UP, 2)
			toonExplosion(center + UP * 2, 3, { NoDebris = true })
			shockDisc(center, -UP, 3, 26, 0.3, FIRE[2], 6)
			streaks(center + UP * 3, -UP, 10, 2, 8, 14, FIRE[1], 0.3)
			VFX.PlaySound("BigExplosion", center, 1)
			VFX.ShakeAt(center, 2.5, 100, 0.3)
			-- ...and they hit the street
			task.delay(0.22, function()
				local g = groundPoint(center)
				shockDisc(g + UP * 0.4, UP, 3, 34, 0.4, WIND)
				dustPuffs(g, 1.6, 8, Color3.fromRGB(205, 196, 190), 1.1, true)
				rocks(g, 1.3, 12)
				groundMark(g, 7, Color3.fromRGB(46, 40, 38), 12)
				VFX.PlaySound("Downslam", g, 1)
			end)
		end)
	end

	-- SCORCHED EARTH, part 1: the lunge for their face
	function Effects.ScorchedEarth(char, data, isLocal)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			if hum and not data.Air then
				dash(root, d * 40, 0.1)
			end
		end
		VFX.Pose(char, "Grab", 0.35)
		BK.palm(handPos(char, false), -d, 0.8) -- (the other hand fires him forward)
		sparks(handPos(char, true), 0.5, Color3.new(1, 1, 1), FIRE[1], 8)
	end

	-- SCORCHED EARTH, part 2 (the server says whether he caught them): he
	-- rockets forward with them held out in front, their back ploughing the
	-- street, and blows up in their face (in the air: straight down)
	function Effects.ScorchedEarthCatch(char, data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("ScorchedEarth") or {}
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		if not target then
			smokeBurst(handPos(char, true), SMOKE_LIGHT, 3, 3, 0.6, 3) -- (caught nothing)
			return
		end
		local me = Players.LocalPlayer
		local dragTime = ability.DragTime or 0.7
		local speed = ability.DragSpeed or 75
		local go = data.Air and (d * 0.35 - UP).Unit or d
		if me and me.Character == char then
			dash(root, go * speed, dragTime)
		end
		VFX.Pose(char, "Grab", dragTime + 0.1)
		VFX.PlaySound("Leap", root.Position, 1)
		local stopTrail = addTrail(root, FIRE[3], 0.35, 2.8)
		local t0 = os.clock()
		while os.clock() - t0 < dragTime and root.Parent do
			-- the free hand blasting behind him, sparks off the street
			toonExplosion(handPos(char, false) - go * 2, 1, { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.8 })
			local tr = target:FindFirstChild("HumanoidRootPart")
			if tr and not data.Air then
				local g = groundPoint(tr.Position)
				sparks(g + UP * 0.3, 0.7, Color3.new(1, 1, 1), FIRE[1], 6)
				groundMark(g, 2.5, Color3.fromRGB(40, 32, 30), 8)
			end
			task.wait(0.06)
		end
		stopTrail(0)
		if not root.Parent then
			return
		end
		-- point blank, in their face
		local tr = target:FindFirstChild("HumanoidRootPart")
		local at = tr and tr.Position or (root.Position + go * 3)
		VFX.Pose(char, "Blast", 0.4)
		toonExplosion(at, data.Air and 4 or 3.4, { SmokeLife = 2.4 })
		shockDisc(at, data.Air and UP or d, 4, 40, 0.35, FIRE[2], 4)
		if data.Air then
			rocks(groundPoint(at), 1.4, 14)
			groundMark(groundPoint(at), 9, Color3.fromRGB(40, 32, 30), 14)
		end
		if nearCamera(at, 40) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.2)
		end
		VFX.ShakeAt(at, 3, 120, 0.4)
	end

	-- EXPLOSIVE SPEED (the ult's 4): "Explosive Speed: Cluster", chapter 406 -
	-- the beads of nitro sweat in his palms run through his whole body and
	-- pop. A sprinter's crouch with sparks crackling all over him; a blur
	-- straight down the street; time slowing right down as his palm comes up
	-- to their face; and the Explosion point blank (chapter 405, his opening
	-- shot at All For One).
	POSES.BlitzCrouch = {
		Hips = { 0, 0, 0, 0, -1.3, -0.2 }, Waist = { -32, 0, 0 }, Neck = { 26, 0, 0 },
		LeftLeg = 72, LeftKnee = 100, RightLeg = -18, RightKnee = 112,
		RightArm = { 28, 0, 14 }, RightElbow = 10, RightWrist = { -60, 0, 0 }, LeftArm = { 28, 0, 14 }, LeftElbow = 10, LeftWrist = { -60, 0, 0 },
	}
	-- the blitz: his body flat out face down (the server tips him), head up
	-- looking where he's going, arms swept back along his sides with the palms
	-- blasting behind him, legs straight back - a missile
	POSES.BlitzFly = {
		Neck = { 62, 0, 0 }, Waist = { 10, 0, 0 },
		RightArm = { -18, 0, 14 }, RightElbow = 6, RightWrist = { 70, 0, 0 }, LeftArm = { -18, 0, 14 }, LeftElbow = 6, LeftWrist = { 70, 0, 0 },
		RightLeg = -6, LeftLeg = -12, RightKnee = 6, LeftKnee = 14,
	}
	POSES.BlitzPalm = {
		RightArm = { 90, 0, 0 }, RightElbow = 4, RightWrist = { -55, 0, 0 }, LeftArm = { -35, 0, 24 }, LeftElbow = 30,
		Waist = { -10, 24, 0 }, Neck = { -2, -14, 0 }, RightLeg = -22, LeftLeg = 38, LeftKnee = 42, RightKnee = 12,
	}
	MOTIONS.BlitzCrouch = {
		{ pose = "BlitzCrouch", t = 0.16, hold = 0.2, style = SNAP },
		-- (coiled tighter as the beads build)
		{ pose = { Hips = { 0, 0, 0, 0, -1.45, -0.3 }, Waist = { -38, 0, 0 }, Neck = { 30, 0, 0 }, LeftLeg = 78, LeftKnee = 110, RightLeg = -22, RightKnee = 118,
			RightArm = { 32, 0, 16 }, RightElbow = 14, RightWrist = { -65, 0, 0 }, LeftArm = { 32, 0, 16 }, LeftElbow = 14, LeftWrist = { -65, 0, 0 } }, t = 0.3, hold = 0.2, style = Enum.EasingStyle.Sine },
		recover = 0.1,
	}
	MOTIONS.BlitzReach = { { pose = "BlitzPalm", t = 0.62, hold = 0.2, style = Enum.EasingStyle.Sine }, recover = 0.25 }
	-- the catch (chapter 406): he flips over as he reaches them - tucked for
	-- an instant, then upside down face to face (the server turns his body
	-- over), legs flung out above him, the free arm thrown wide, and his palm
	-- coming up flat into their face as time crawls
	POSES.BlitzFlipTuck = {
		Waist = { 30, 0, 0 }, Neck = { 20, 0, 0 },
		RightArm = { 60, 0, 20 }, RightElbow = 80, LeftArm = { 60, 0, 20 }, LeftElbow = 80,
		RightLeg = 80, RightKnee = 110, LeftLeg = 70, LeftKnee = 100,
	}
	POSES.BlitzFlip = {
		-- (upside down, his shoulders sit a stud over their face: the arm angles
		-- "up" past level, and in, to put the palm square on it)
		RightArm = { 135, 20, 20 }, RightElbow = 4, RightWrist = { -65, 0, 0 }, LeftArm = { -30, 0, 60 }, LeftElbow = 35,
		Waist = { -12, 26, 0 }, Neck = { -6, -16, 0 }, RightLeg = -34, RightKnee = 48, LeftLeg = 52, LeftKnee = 86,
	}
	MOTIONS.BlitzFlip = {
		{ pose = "BlitzFlipTuck", t = 0.1, hold = 0.04, style = SNAP },
		{ pose = "BlitzFlip", t = 0.7, hold = 1.6, style = Enum.EasingStyle.Sine },
		recover = 0.25,
	}
	BK.blitz = setmetatable({}, { __mode = "k" }) -- [char] = the blitz going

	-- one bead of sweat popping somewhere on him: a tiny star of light
	function BK.bead(char)
		local limbs = {}
		for _, p in char:GetChildren() do
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
				table.insert(limbs, p)
			end
		end
		local limb = limbs[rng:NextInteger(1, math.max(#limbs, 1))]
		if not limb then
			return
		end
		local off = Vector3.new(rand(-0.5, 0.5) * limb.Size.X, rand(-0.5, 0.5) * limb.Size.Y, rand(-0.5, 0.5) * limb.Size.Z)
		local pos = limb.CFrame:PointToWorldSpace(off)
		local c = ({ Color3.new(1, 1, 1), FIRE[1], FIRE[2] })[rng:NextInteger(1, 3)]
		local star = newPart(Vector3.one * 0.12, CFrame.new(pos) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), c, Enum.Material.Neon)
		local s = rand(0.35, 0.7)
		tween(star, 0.05, { Size = Vector3.new(s, s * 0.25, s) })
		task.delay(0.05, function()
			tween(star, 0.1, { Size = Vector3.one * 0.05, Transparency = 1 })
		end)
		cleanup(star, 0.18)
	end

	-- slow motion for everyone near it: the colour drains, the world blurs and
	-- the camera leans in - snapped back by the blast
	function BK.slowMo(pos, time)
		if not nearCamera(pos, 90) then
			return nil
		end
		local lighting = game:GetService("Lighting")
		local cc = Instance.new("ColorCorrectionEffect")
		cc.Name = "BlitzSlowMo"
		cc.Parent = lighting
		local blur = Instance.new("BlurEffect")
		blur.Name = "BlitzSlowMo"
		blur.Size = 0
		blur.Parent = lighting
		tween(cc, 0.2, { Saturation = -0.65, Contrast = 0.25, TintColor = Color3.fromRGB(255, 238, 214) })
		tween(blur, 0.2, { Size = 5 })
		local cam = workspace.CurrentCamera
		local fov = cam and cam.FieldOfView
		if cam and not VFX.InOwnCinematic() then
			tween(cam, time, { FieldOfView = fov - 12 }, Enum.EasingStyle.Sine)
		end
		local done = false
		return function()
			if done then
				return
			end
			done = true
			cc:Destroy()
			blur:Destroy()
			if cam and fov and not VFX.InOwnCinematic() then
				tween(cam, 0.25, { FieldOfView = fov }, Enum.EasingStyle.Quad)
			end
		end
	end

	VFX.SlowMoScreen = BK.slowMo

	-- one of the little explosions off him in the slow motion: a bead of nitro
	-- going pop - slowly, with time all but stopped
	function BK.pop(pos, size, slow)
		local life = 0.3 + (slow or 0) * 0.3
		local outer = newPart(Vector3.one * size * 0.3, CFrame.new(pos), FIRE[3], Enum.Material.Neon, Enum.PartType.Ball)
		outer.Transparency = 0.1
		local core = newPart(Vector3.one * size * 0.2, CFrame.new(pos), FIRE[1], Enum.Material.Neon, Enum.PartType.Ball)
		tween(outer, life, { Size = Vector3.one * size * 1.5, Transparency = 1 })
		tween(core, life * 0.7, { Size = Vector3.one * size * 0.9, Transparency = 1 })
		cleanup(outer, life + 0.05)
		cleanup(core, life + 0.05)
		for _ = 1, 3 do
			local dir = rng:NextUnitVector()
			local shard = newPart(Vector3.new(0.08, 0.08, rand(0.3, 0.6)), CFrame.lookAt(pos, pos + dir), FIRE[2], Enum.Material.Neon)
			tween(shard, life, { CFrame = CFrame.lookAt(pos + dir * size * 1.6, pos + dir * size * 3), Transparency = 1 })
			cleanup(shard, life + 0.05)
		end
	end

	-- a star of light twinkling in the air (the panels are full of them)
	function BK.star(pos, size, slow)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos), FIRE[1])
		anchor.Transparency = 1
		anchor.Name = "Star"
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(size, size) -- (studs)
		bb.LightInfluence = 0
		bb.Adornee = anchor
		bb.Parent = anchor
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBlack
		label.TextScaled = true
		label.Text = "★"
		label.TextColor3 = rng:NextNumber() < 0.7 and Color3.fromRGB(255, 228, 90) or Color3.new(1, 1, 1)
		label.TextTransparency = 1
		label.Parent = bb
		local life = 0.35 + (slow or 0) * 0.35
		tween(label, life * 0.3, { TextTransparency = 0 })
		tween(label, life * 0.5, { TextTransparency = 1 }, nil, nil, life * 0.5)
		tween(anchor, life, { CFrame = CFrame.new(pos + UP * rand(0.2, 0.8)) }, Enum.EasingStyle.Linear)
		cleanup(anchor, life + 0.05)
	end

	-- EXPLOSIVE SPEED (round 64: back, as Dynamight's R, and better looking).
	-- The crouch: the street cracking under his feet and grit lifting off it
	-- while the beads pop and both palms swell white-hot; the launch: both
	-- palms blasting behind him, a sonic boom and the street going off down
	-- the lane behind him; the catch: time crawling, a flare swelling in his
	-- palm and heat rippling off it; then the Explosion, layered, and the
	-- one it hits trailing fire.
	-- the street splitting under him as the pressure builds (grows over time)
	function BK.cracks(pos, d, time)
		local g = groundPoint(pos)
		for i = 1, 7 do
			local a = (i / 7) * math.pi * 2 + rand(-0.3, 0.3)
			local dir = (CFrame.fromAxisAngle(UP, a):VectorToWorldSpace(d) * Vector3.new(1, 0, 1))
			dir = dir.Magnitude > 0.1 and dir.Unit or d
			local len = rand(2.4, 4.6)
			local crack = newPart(Vector3.new(rand(0.12, 0.22), 0.06, 0.1), CFrame.lookAt(g + UP * 0.04, g + UP * 0.04 + dir), Color3.fromRGB(34, 26, 24), Enum.Material.SmoothPlastic)
			crack.Name = "BlitzCrack"
			tween(crack, time, { Size = Vector3.new(crack.Size.X, 0.06, len), CFrame = CFrame.lookAt(g + UP * 0.04 + dir * len / 2, g + UP * 0.04 + dir * (len / 2 + 1)) }, Enum.EasingStyle.Quad)
			tween(crack, 0.6, { Transparency = 1 }, nil, nil, time + 1.4)
			cleanup(crack, time + 2.1)
			-- (glowing in the seam as it opens)
			local seam = newPart(Vector3.new(0.05, 0.07, 0.1), crack.CFrame, FIRE[1], Enum.Material.Neon)
			tween(seam, time, { Size = Vector3.new(0.05, 0.07, len * 0.8), CFrame = CFrame.lookAt(g + UP * 0.05 + dir * len * 0.4, g + UP * 0.05 + dir * (len * 0.4 + 1)) }, Enum.EasingStyle.Quad)
			tween(seam, 0.4, { Transparency = 1 }, nil, nil, time)
			cleanup(seam, time + 0.45)
		end
		-- grit lifting off the street round his feet, hanging in the air
		for _ = 1, 9 do
			local at = g + Vector3.new(rand(-2.6, 2.6), 0.15, rand(-2.6, 2.6))
			local chip = newPart(Vector3.one * rand(0.16, 0.34), CFrame.new(at) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Color3.fromRGB(96, 90, 86), Enum.Material.Slate)
			chip.Name = "BlitzGrit"
			tween(chip, time, { CFrame = CFrame.new(at + UP * rand(0.6, 1.6)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Sine)
			tween(chip, 0.25, { Transparency = 1 }, nil, nil, time)
			cleanup(chip, time + 0.3)
		end
	end

	-- the launch: both palms blasting behind him, a sonic boom off the front
	-- of him, the street torn up where he stood
	function BK.launch(char, from, d)
		for _, right in { true, false } do
			local hp = handPos(char, right)
			toonExplosion(hp - d * 1.1, 1.1, { NoDebris = true, NoScorch = true, SmokeLife = 0.8 })
		end
		for i = 0, 2 do
			task.delay(i * 0.035, function()
				shockDisc(from + UP * 1.2 + d * (2 + i * 3), d, 2 + i, 9 + i * 4, 0.22, Color3.new(1, 1, 1))
			end)
		end
		local g = groundPoint(from)
		groundMark(g, 3, Color3.fromRGB(38, 30, 28), 8)
		rocks(g, 1, 7)
		local right = d:Cross(UP)
		right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
		dustPuffs(g + right * 2, 1, 4, Color3.fromRGB(200, 190, 175), 0.8, true)
		dustPuffs(g - right * 2, 1, 4, Color3.fromRGB(200, 190, 175), 0.8, true)
	end

	-- the lane: a burning streak along it, and the street going off behind
	-- him, blast after blast, chasing him down it
	function BK.lane(from, d, length, speed)
		local mid = from + d * length / 2 + UP * 0.9
		local streak = newPart(Vector3.new(0.9, 0.9, math.max(length, 1)), CFrame.lookAt(mid, mid + d), FIRE[1]:Lerp(Color3.new(1, 1, 1), 0.45), Enum.Material.Neon)
		streak.Name = "BlitzStreak"
		streak.Transparency = 0.15
		tween(streak, 0.4, { Size = Vector3.new(0.05, 0.05, math.max(length, 1)), Transparency = 1 }, Enum.EasingStyle.Quad, nil, 0.05)
		cleanup(streak, 0.5)
		local time = length / math.max(speed or 300, 1)
		for s = 3, length, 4 do
			local at = from + d * s
			task.delay(time * (s / math.max(length, 1)) + 0.05 + s * 0.004, function()
				local g = groundPoint(at)
				toonExplosion(g + UP * 0.7 + Vector3.new(rand(-0.5, 0.5), 0, rand(-0.5, 0.5)), rand(0.55, 0.85), { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.7 })
				groundMark(g, 1.4, Color3.fromRGB(40, 32, 30), 6)
			end)
		end
	end

	-- a flare in his palm, swelling as time crawls (a four-point star of
	-- light and a hot core); follows the hand; returns a stop function
	function BK.flare(char, time)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(handPos(char, true)), FIRE[1])
		anchor.Transparency = 1
		anchor.Name = "BlitzFlare"
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(1, 1)
		bb.LightInfluence = 0
		bb.Adornee = anchor
		bb.Parent = anchor
		local bars = {}
		for k = 1, 4 do
			local bar = Instance.new("Frame")
			bar.AnchorPoint = Vector2.new(0.5, 0.5)
			bar.Position = UDim2.fromScale(0.5, 0.5)
			bar.Size = UDim2.fromScale(k <= 2 and 1 or 0.6, k <= 2 and 0.06 or 0.04)
			bar.Rotation = ({ 0, 90, 45, 135 })[k]
			bar.BackgroundColor3 = k <= 2 and Color3.new(1, 1, 1) or Color3.fromRGB(255, 214, 120)
			bar.BorderSizePixel = 0
			bar.Parent = bb
			local g = Instance.new("UIGradient")
			g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1) })
			g.Parent = bar
			table.insert(bars, bar)
		end
		local core = Instance.new("Frame")
		core.AnchorPoint = Vector2.new(0.5, 0.5)
		core.Position = UDim2.fromScale(0.5, 0.5)
		core.Size = UDim2.fromScale(0.28, 0.28)
		core.BackgroundColor3 = Color3.fromRGB(255, 248, 225)
		core.BorderSizePixel = 0
		core.Parent = bb
		local round = Instance.new("UICorner")
		round.CornerRadius = UDim.new(0.5, 0)
		round.Parent = core
		local t0 = os.clock()
		local alive = true
		task.spawn(function()
			while alive and char.Parent and os.clock() - t0 < time + 0.2 do
				local k = math.clamp((os.clock() - t0) / time, 0, 1)
				anchor.CFrame = CFrame.new(handPos(char, true))
				local size = 1 + 7 * k * k
				bb.Size = UDim2.fromScale(size, size)
				for i, bar in bars do
					bar.Rotation = ({ 0, 90, 45, 135 })[i] + k * 25
				end
				task.wait()
			end
			pcall(function()
				anchor:Destroy()
			end)
		end)
		return function()
			alive = false
		end
	end

	function Effects.ExplosiveSpeed(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("ExplosiveSpeed") or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local st = { dead = false }
		BK.blitz[char] = st
		local windUp = ability.WindUp or 0.6
		VFX.MuteGait(char, windUp + 1.2) -- (nothing fighting the crouch or the flight)
		VFX.Motion(char, "BlitzCrouch")
		-- (round 76) "I'M THE FINAL BOSS, GOT IT?" (trimmed before "...ALL FOR ONE!!")
		VFX.Voice("FinalBoss", root)
		VFX.PlaySound("BlitzCharge", root.Position, 1)
		dustPuffs(groundPoint(root.Position), 0.6, 3, Color3.fromRGB(200, 190, 175), 0.6, false)
		BK.cracks(root.Position, d, windUp)
		if isLocal then
			VFX.ShakeAt(root.Position, 0.8, 40, windUp)
		end
		-- the beads popping all over him, quicker and quicker, and both palms
		-- swelling white-hot
		local glows = {}
		for _, right in { true, false } do
			local glow = newPart(Vector3.one * 0.3, CFrame.new(handPos(char, right)), Color3.fromRGB(255, 236, 190), Enum.Material.Neon, Enum.PartType.Ball)
			glow.Name = "BlitzPalmGlow"
			glow.Transparency = 0.25
			glows[right] = glow
		end
		task.spawn(function()
			local t0 = os.clock()
			while not st.dead and char.Parent and os.clock() - t0 < windUp do
				local k = (os.clock() - t0) / windUp
				for _ = 1, 1 + math.floor(k * 4) do
					BK.bead(char)
				end
				if rng:NextNumber() < 0.25 + k * 0.5 then
					sparks(handPos(char, rng:NextNumber() < 0.5), 0.3 + 0.3 * k, Color3.new(1, 1, 1), FIRE[1], 3)
				end
				for right, glow in glows do
					glow.CFrame = CFrame.new(handPos(char, right))
					glow.Size = Vector3.one * (0.3 + 1.1 * k)
				end
				task.wait(0.035)
			end
			for _, glow in glows do
				glow:Destroy()
			end
			if not st.dead and char.Parent then
				-- (the last crackle: both palms blaze)
				BK.palm(handPos(char, true), -d, 0.8)
				BK.palm(handPos(char, false), -d, 0.8)
			end
		end)
	end

	-- the blitz: gone in a crack of blasts, down the street
	function Effects.ExplosiveSpeedGo(char, data, isLocal)
		local root = charParts(char)
		local st = BK.blitz[char] or { dead = false }
		BK.blitz[char] = st
		if not root or st.dead then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local length = tonumber(data.Length) or 60
		local speed = math.max(tonumber(data.Speed) or 230, 1)
		local time = length / speed
		VFX.PlaySound("BlitzGo", from, 1.1)
		BK.launch(char, from, d)
		toonExplosion(from - d * 1.5, 1.6, { NoDebris = true, SmokeLife = 1.2 })
		billboardRing(from + UP, 2, 14, FIRE[2], 5, 0.25)
		BK.lane(from, d, length, data.Blink and 1e6 or speed)
		if data.Blink then
			-- someone was in the lane: he's simply THERE - a line of afterimages
			-- where he was, the street going off under it
			VFX.MuteGait(char, 1.4)
			VFX.Pose(char, "BlitzFly", 0.08) -- (the frame he arrives in: still flying)
			streaks(from + UP * 1.5, d, 14, 1.4, 10, length, Color3.new(1, 1, 1), 0.3)
			for s = 0, length, 2.5 do
				local k = s / math.max(length, 1)
				local at = from + d * s + UP * 0.3
				local ghost = newPart(Vector3.new(1.7, 1, 4.6), CFrame.lookAt(at, at + d), FIRE[1]:Lerp(Color3.new(1, 1, 1), k * 0.6), Enum.Material.Neon)
				ghost.Transparency = 0.4 + k * 0.25
				tween(ghost, 0.2 + k * 0.12, { Transparency = 1, Size = Vector3.new(0.5, 0.3, 4.6) })
				cleanup(ghost, 0.35 + k * 0.12)
			end
			if isLocal then
				VFX.Hooks.SpeedLines(0.3)
			end
			if nearCamera(from + d * length, 60) then
				VFX.ImpactFrame(0.06)
			end
			return
		end
		VFX.MuteGait(char, time + 0.4)
		VFX.Pose(char, "BlitzFly", time + 0.1)
		streaks(from + UP * 1.5, d, 10, 1.2, 8, length, Color3.new(1, 1, 1), time + 0.2)
		if isLocal then
			VFX.Hooks.SpeedLines(time + 0.2)
		end
		st.stopTrail = addTrail(root, FIRE[2], 0.35, 3)
		task.spawn(function()
			local t0 = os.clock()
			local flip = false
			while not st.dead and root.Parent and os.clock() - t0 < time + 0.15 do
				-- (the palms blasting behind him, left and right in turn)
				flip = not flip
				local hp = handPos(char, flip)
				toonExplosion(hp - d * 1.2 + Vector3.new(rand(-0.3, 0.3), rand(-0.3, 0.3), rand(-0.3, 0.3)), 0.6, { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.5 })
				BK.bead(char)
				afterimage(char, FIRE[1], 0.22)
				task.wait(0.04)
			end
			if st.stopTrail then
				st.stopTrail(0.15)
				st.stopTrail = nil
			end
		end)
	end

	-- caught face to face: time crawls while his palm comes up to their face
	function Effects.ExplosiveSpeedCatch(char, data)
		local root = charParts(char)
		local st = BK.blitz[char] or { dead = false }
		BK.blitz[char] = st
		if not root then
			return
		end
		local face = typeof(data.Pos) == "Vector3" and data.Pos or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local time = tonumber(data.Time) or 0.75
		if st.stopTrail then
			st.stopTrail(0)
			st.stopTrail = nil
		end
		st.dead = true -- (the blitz is over)
		VFX.MuteGait(char, time + 0.6)
		VFX.Motion(char, "BlitzFlip")
		VFX.PlaySound("BlitzSlow", face, 1)
		st.endSlow = BK.slowMo(face, time)
		st.endFlare = BK.flare(char, time)
		local lp = Players.LocalPlayer
		local me = lp and lp.Character
		if me and (me == char or me == data.Target) then
			VFX.Hooks.SpeedLines(time) -- (the panel's focus lines, on the two of them)
		end
		-- the little explosions popping all round him as time crawls, the
		-- stars of light thrown off them, heat rippling off his palm
		task.spawn(function()
			local t0 = os.clock()
			local nextRipple = 0
			while os.clock() - t0 < time and char.Parent and BK.blitz[char] == st do
				local k = (os.clock() - t0) / time
				local near = rng:NextNumber() < 0.55 and handPos(char, rng:NextNumber() < 0.7) or root.Position
				BK.pop(near + rng:NextUnitVector() * rand(0.8, 3.2), rand(0.4, 0.9) * (0.8 + k * 0.6), time)
				if rng:NextNumber() < 0.8 then
					BK.star(face + Vector3.new(rand(-6, 6), rand(-2.5, 5), rand(-6, 6)), rand(0.5, 1.4), time)
				end
				if os.clock() - t0 >= nextRipple then
					nextRipple = os.clock() - t0 + 0.26
					local hp = handPos(char, true)
					local ring = shockDisc(hp, d, 0.6, 3.4 + 2 * k, 0.55, FIRE[1]:Lerp(Color3.new(1, 1, 1), 0.5))
					ring.Name = "BlitzRipple"
				end
				task.wait(0.045)
			end
		end)
		-- the sparks off his run, drifting as if time had all but stopped
		for _ = 1, 26 do
			local p = face + Vector3.new(rand(-4, 4), rand(-2.5, 3), rand(-4, 4))
			local c = ({ Color3.new(1, 1, 1), FIRE[1], FIRE[2] })[rng:NextInteger(1, 3)]
			local mote = newPart(Vector3.one * rand(0.12, 0.3), CFrame.new(p) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), c, Enum.Material.Neon)
			tween(mote, time + 0.1, { CFrame = mote.CFrame + Vector3.new(rand(-0.4, 0.4), rand(0.1, 0.6), rand(-0.4, 0.4)) }, Enum.EasingStyle.Linear)
			cleanup(mote, time + 0.12)
		end
		-- the palm heating up: a white-hot glow swelling at his hand
		local glow = newPart(Vector3.one * 0.3, CFrame.new(handPos(char, true)), Color3.fromRGB(255, 244, 214), Enum.Material.Neon, Enum.PartType.Ball)
		glow.Transparency = 0.2
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local k = math.clamp((os.clock() - t0) / time, 0, 1)
			if not char.Parent or k >= 1 then
				conn:Disconnect()
				glow:Destroy()
				return
			end
			glow.Size = Vector3.one * (0.3 + 1.8 * k * k)
			glow.CFrame = CFrame.new(handPos(char, true))
		end)
	end

	-- the Explosion, point blank: a white flash, a star of light, the
	-- fireball driven through them and on down the street, the ground ring,
	-- a column of smoke - and the one it hits goes flying trailing fire
	function Effects.ExplosiveSpeedBlast(char, data)
		local st = BK.blitz[char]
		if st then
			if st.endSlow then
				st.endSlow()
			end
			if st.endFlare then
				st.endFlare()
			end
			BK.blitz[char] = nil
		end
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not at then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
		VFX.Pose(char, "Blast", 0.45)
		local flash = newPart(Vector3.one * 2, CFrame.new(at + d * 1.5), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		flash.Name = "BlitzFlash"
		tween(flash, 0.1, { Size = Vector3.one * 15 }, Enum.EasingStyle.Quad)
		tween(flash, 0.18, { Transparency = 1, Size = Vector3.one * 18 }, nil, nil, 0.1)
		cleanup(flash, 0.3)
		VFX.HitStar(at + d * 1.2, 14, FIRE[1])
		toonExplosion(at + d * 1.5, 4.6, { SmokeLife = 2.8 })
		for i, far in { 7, 12, 17 } do
			task.delay(0.05 * i, function()
				toonExplosion(at + d * far + UP * (i * 0.4), 3.2 - i * 0.5, { NoDebris = true, SmokeLife = 1.9 - i * 0.2 })
			end)
		end
		shockDisc(at, d, 4, 48, 0.35, FIRE[2], 8)
		shockDisc(groundPoint(at) + UP * 0.3, UP, 4, 40, 0.45, Color3.new(1, 1, 1))
		billboardRing(at, 4, 42, FIRE[1], 10, 0.35)
		streaks(at, d, 16, 0.5, 11, 34, FIRE[1], 0.32)
		sparks(at + d * 2, 1.6, Color3.new(1, 1, 1), FIRE[1], 16)
		rocks(groundPoint(at + d * 3), 1.4, 14)
		groundMark(groundPoint(at + d * 3), 7, Color3.fromRGB(40, 32, 30), 10)
		task.delay(0.2, function()
			smokeBurst(at + UP * 2.5, SMOKE_LIGHT, 4, 3, 2.2, 4)
		end)
		VFX.PlaySound("BigExplosion", at, 1.15)
		if nearCamera(at, 60) then
			VFX.ImpactFrame(0.1)
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.25)
		end
		VFX.ShakeAt(at, 4.5, 170, 0.55)
		-- the one it hit: flying off trailing fire, popping as they go
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if troot then
			local stop = addTrail(troot, FIRE[2], 0.35, 2.2)
			stop(0.9)
			task.spawn(function()
				local t0 = os.clock()
				while troot.Parent and os.clock() - t0 < 0.6 do
					toonExplosion(troot.Position + rng:NextUnitVector() * 0.8, 0.5, { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.5 })
					task.wait(0.08)
				end
			end)
		end
	end

	-- nobody in the lane: he skids to a stop at the end of it
	function Effects.ExplosiveSpeedWhiff(char, data)
		local st = BK.blitz[char]
		if st then
			st.dead = true
			if st.stopTrail then
				st.stopTrail(0.1)
			end
			BK.blitz[char] = nil
		end
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not at then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
		local g = groundPoint(at)
		local right = d:Cross(UP)
		right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
		-- (two skid marks behind his feet, sparks off the soles)
		for _, side in { 0.5, -0.5 } do
			local mid = g + right * side - d * 2.5 + UP * 0.04
			local skid = newPart(Vector3.new(0.35, 0.05, 5), CFrame.lookAt(mid, mid + d), Color3.fromRGB(34, 28, 26), Enum.Material.SmoothPlastic)
			skid.Name = "BlitzSkid"
			tween(skid, 0.8, { Transparency = 1 }, nil, nil, 3)
			cleanup(skid, 3.9)
		end
		sparks(g + UP * 0.3, 0.8, Color3.new(1, 1, 1), FIRE[1], 8)
		dustPuffs(g, 1, 5, Color3.fromRGB(200, 190, 175), 0.9, true)
		smokeBurst(at, SMOKE_LIGHT, 3, 3, 0.6, 3)
		VFX.Pose(char, "Land", 0.35)
	end

	function Effects.ExplosiveSpeedCancel(char)
		local st = BK.blitz[char]
		if st then
			st.dead = true
			if st.stopTrail then
				st.stopTrail(0)
			end
			if st.endSlow then
				st.endSlow()
			end
			if st.endFlare then
				st.endFlare()
			end
			BK.blitz[char] = nil
		end
		VFX.ReleasePose(char, 0.2)
	end

	-- FULL-BODY CLUSTER (round 63): his last stand against Shigaraki
	-- (chapter 362). The beads of sweat he's stored can't stay in his palms
	-- any more and burst out all over him: explosions off every limb, bigger
	-- and bigger. (BK.cluster[char]: where he last was - the afterimage trail)
	BK.cluster = setmetatable({}, { __mode = "k" })
	-- an explosion off every limb, scaled
	function BK.fullBody(char, scale)
		for _, name in { "Right Arm", "Left Arm", "Right Leg", "Left Leg", "Torso", "RightUpperArm", "LeftUpperArm", "RightUpperLeg", "LeftUpperLeg", "UpperTorso" } do
			local p = char:FindFirstChild(name)
			if p and p:IsA("BasePart") then
				local off = name:find("Torso") and -p.CFrame.LookVector * 0.8 or -p.CFrame.UpVector * 0.6
				toonExplosion(p.Position + off, scale * (name:find("Torso") and 1.25 or 0.8), { NoDebris = true, NoScorch = true, NoEmbers = scale < 0.9, SmokeLife = 0.5 })
			end
		end
	end
	-- the white void (his own screen): All Might's vestige, and the card he
	-- always wanted signed
	function BK.whiteVoid(time)
		local lp = game:GetService("Players").LocalPlayer
		local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return
		end
		local gui = Instance.new("ScreenGui")
		gui.Name = "WhiteVoid"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.DisplayOrder = 12
		local white = Instance.new("Frame")
		white.Size = UDim2.fromScale(1, 1)
		white.BackgroundColor3 = Color3.fromRGB(252, 250, 244)
		white.BackgroundTransparency = 1
		white.BorderSizePixel = 0
		white.Parent = gui
		-- his silhouette far off in the white, and the words
		local figure = Instance.new("TextLabel")
		figure.AnchorPoint = Vector2.new(0.5, 1)
		figure.Position = UDim2.fromScale(0.5, 0.62)
		figure.Size = UDim2.fromScale(0.2, 0.34)
		figure.BackgroundTransparency = 1
		figure.Font = Enum.Font.GothamBlack
		figure.TextScaled = true
		figure.Text = "V"
		figure.TextColor3 = Color3.fromRGB(214, 196, 140)
		figure.TextTransparency = 1
		figure.Parent = white
		local line = Instance.new("TextLabel")
		line.AnchorPoint = Vector2.new(0.5, 0)
		line.Position = UDim2.fromScale(0.5, 0.7)
		line.Size = UDim2.fromScale(0.8, 0.06)
		line.BackgroundTransparency = 1
		line.Font = Enum.Font.GothamMedium
		line.TextScaled = true
		line.Text = "...I always wanted you to sign my card."
		line.TextColor3 = Color3.fromRGB(70, 66, 60)
		line.TextTransparency = 1
		line.Parent = white
		gui.Parent = pg
		tween(white, math.min(0.2, time * 0.3), { BackgroundTransparency = 0.04 })
		tween(figure, time * 0.5, { TextTransparency = 0.55 }, Enum.EasingStyle.Sine, nil, time * 0.15)
		tween(line, time * 0.4, { TextTransparency = 0 }, Enum.EasingStyle.Sine, nil, time * 0.25)
		-- (cut back to the fight on the blast)
		task.delay(time, function()
			tween(white, 0.35, { BackgroundTransparency = 1 })
			tween(figure, 0.2, { TextTransparency = 1 })
			tween(line, 0.3, { TextTransparency = 1 })
			task.delay(0.4, function()
				gui:Destroy()
			end)
		end)
	end
	-- the All Might card: it slips out of his pocket and flutters down
	function BK.card(pos)
		local g = groundPoint(pos)
		local card = newPart(Vector3.new(0.9, 1.3, 0.04), CFrame.new(pos) * CFrame.Angles(rand(-0.4, 0.4), rand(0, 6), rand(-0.4, 0.4)),
			Color3.fromRGB(230, 206, 120), Enum.Material.SmoothPlastic)
		card.Name = "AllMightCard"
		for _, faceId in { Enum.NormalId.Front, Enum.NormalId.Back } do
			local sg = Instance.new("SurfaceGui")
			sg.Face = faceId
			sg.CanvasSize = Vector2.new(90, 130)
			sg.LightInfluence = 0.4
			sg.Parent = card
			local art = Instance.new("Frame")
			art.Position = UDim2.fromOffset(6, 6)
			art.Size = UDim2.new(1, -12, 1, -12)
			art.BackgroundColor3 = Color3.fromRGB(40, 70, 170)
			art.BorderSizePixel = 0
			art.Parent = sg
			local grad = Instance.new("UIGradient")
			grad.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(150, 150, 150))
			grad.Rotation = 90
			grad.Parent = art
			local label = Instance.new("TextLabel")
			label.Size = UDim2.fromScale(1, 0.3)
			label.Position = UDim2.fromScale(0, 0.68)
			label.BackgroundTransparency = 1
			label.Font = Enum.Font.GothamBlack
			label.TextScaled = true
			label.Text = faceId == Enum.NormalId.Front and "ALL MIGHT" or "PLUS ULTRA"
			label.TextColor3 = Color3.fromRGB(255, 226, 90)
			label.Parent = art
			local smile = Instance.new("TextLabel")
			smile.Size = UDim2.fromScale(1, 0.6)
			smile.Position = UDim2.fromScale(0, 0.06)
			smile.BackgroundTransparency = 1
			smile.Font = Enum.Font.GothamBlack
			smile.TextScaled = true
			smile.Text = faceId == Enum.NormalId.Front and "V" or "★"
			smile.TextColor3 = Color3.fromRGB(255, 244, 200)
			smile.Parent = art
		end
		-- down it drifts, rocking from side to side
		local steps = 8
		local fall = math.max(pos.Y - g.Y - 0.1, 0.5)
		for i = 1, steps do
			local k = i / steps
			local at = Vector3.new(pos.X + math.sin(k * 7) * 0.9, pos.Y - fall * k, pos.Z + math.cos(k * 5) * 0.5)
			local rot = i == steps and CFrame.Angles(0, rand(0, 6), 0) * CFrame.Angles(math.rad(90), 0, 0) or CFrame.Angles(math.sin(k * 9) * 0.7, k * 3, math.cos(k * 7) * 0.6)
			tween(card, 0.2, { CFrame = CFrame.new(at) * rot }, Enum.EasingStyle.Sine, nil, (i - 1) * 0.2)
		end
		tween(card, 0.6, { Transparency = 1 }, nil, nil, steps * 0.2 + 4)
		cleanup(card, steps * 0.2 + 4.7)
	end

	-- his walk at them: beaten half to death and calm, the beads popping off
	-- him all the way, steam coming off him
	function Effects.FullBodyCluster(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("FullBodyCluster") or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local walk = ability.WalkTime or 0.9
		local st = { dead = false }
		BK.cluster[char] = st
		VFX.MuteGait(char, walk + 0.2)
		if not VFX.Clip(char, "LastStandWalk") then
			VFX.Motion(char, "Awaken")
		end
		VFX.SpeechBubble(char, ability.Say or "IZUKU... YOU'VE GOTTA WIN.", walk + 0.5)
		VFX.PlaySound("BlitzCharge", root.Position, 0.8)
		task.spawn(function()
			local t0 = os.clock()
			while not st.dead and char.Parent and os.clock() - t0 < walk do
				local k = (os.clock() - t0) / walk
				for _ = 1, 1 + math.floor(k * 3) do
					BK.bead(char)
				end
				if rng:NextNumber() < 0.3 + 0.4 * k then
					BK.pop(root.Position + rng:NextUnitVector() * rand(0.8, 1.8), rand(0.3, 0.6) * (0.7 + k), 0)
				end
				if rng:NextNumber() < 0.25 then
					smokeBurst(root.Position + UP * rand(0, 1.5), SMOKE_LIGHT, 0.6, 0.8, 0.5, 1)
				end
				task.wait(0.05)
			end
		end)
	end

	-- gone - and in their face: the palm lets off a mass of stored Cluster
	function Effects.FullBodyClusterBlink(char, data)
		local root = charParts(char)
		local st = BK.cluster[char] or { dead = false }
		BK.cluster[char] = st
		if not root then
			return
		end
		st.dead = true
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local to = typeof(data.To) == "Vector3" and data.To or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		st.last = to
		VFX.MuteGait(char, 3)
		afterimage(char, FIRE[1], 0.3)
		toonExplosion(from - d * 1.2, 1.1, { NoDebris = true, SmokeLife = 0.8 })
		streaks(from + UP, (to - from).Magnitude > 0.1 and (to - from).Unit or d, 12, 1.2, 8, (to - from).Magnitude, Color3.new(1, 1, 1), 0.25)
		VFX.PlaySound("BlitzGo", from, 1)
		if not VFX.Clip(char, "ClusterPalm") then
			VFX.Pose(char, "Blast", 0.3)
		end
		local faceAt = to + d * 2.6 + UP * 1.3
		task.delay(0.06, function()
			for i = 1, 7 do
				task.delay(i * 0.022, function()
					toonExplosion(faceAt + Vector3.new(rand(-1, 1), rand(-0.8, 1), rand(-1, 1)), rand(0.5, 0.8), { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.6 })
				end)
			end
			BK.palm(handPos(char, true), d, 1.4)
			VFX.PlaySound("PalmPop", faceAt, 1.1)
			VFX.PlaySound("Explosion", faceAt, 0.9)
			if nearCamera(faceAt, 60) then
				VFX.ImpactFrame(0.05)
			end
			VFX.ShakeAt(faceAt, 2, 90, 0.25)
		end)
	end

	-- all round them: from every side, explosions off his whole body, each
	-- bigger and quicker than the last
	function Effects.FullBodyClusterHit(char, data)
		local root = charParts(char)
		local st = BK.cluster[char] or { dead = true }
		BK.cluster[char] = st
		if not root then
			return
		end
		local spot = typeof(data.Pos) == "Vector3" and data.Pos or root.Position
		local at = typeof(data.At) == "Vector3" and data.At or spot
		local level = tonumber(data.Level) or 1
		local k = level / math.max(tonumber(data.Of) or 5, 1)
		if st.last then
			local v = spot - st.last
			if v.Magnitude > 0.5 then
				streaks(st.last + UP * 0.5, v.Unit, 6, 0.8, 5, v.Magnitude, FIRE[1]:Lerp(Color3.new(1, 1, 1), 0.5), 0.18)
			end
		end
		st.last = spot
		afterimage(char, FIRE[1]:Lerp(Color3.new(1, 1, 1), k * 0.5), 0.2)
		local clips = { "ClusterStrikeA", "ClusterStrikeB", "ClusterStrikeC" }
		if not VFX.Clip(char, clips[(level - 1) % 3 + 1]) then
			VFX.Pose(char, "Blast", 0.2)
		end
		BK.fullBody(char, 0.45 + 0.4 * k)
		task.delay(0.03, function()
			local toward = (at - spot).Magnitude > 0.1 and (at - spot).Unit or UP
			toonExplosion(at - toward * 0.6, 1 + 1.3 * k, { NoDebris = k < 0.6, SmokeLife = 0.9 + k })
			shockDisc(at, toward, 1, 10 + 12 * k, 0.2, FIRE[2], 2)
			for _ = 1, 2 + level do
				BK.star(at + Vector3.new(rand(-4, 4), rand(-2, 4), rand(-4, 4)), rand(0.5, 1.2), 0)
			end
			VFX.PlaySound(k > 0.7 and "BigExplosion" or "Explosion", at, 0.8 + 0.3 * k)
			VFX.ShakeAt(at, 1.5 + 2 * k, 100, 0.2)
			if k > 0.75 and nearCamera(at, 60) then
				VFX.ImpactFrame(0.04)
			end
		end)
	end

	-- the white void (his own screen) as both palms fill with all he has
	function Effects.FullBodyClusterVoid(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 0.7
		if not VFX.Clip(char, "ClusterCharge") then
			VFX.Pose(char, "PunchCharge", time)
		end
		VFX.PlaySound("BlastCharge", root.Position, 1)
		local lp = game:GetService("Players").LocalPlayer
		if lp and lp.Character == char then
			BK.whiteVoid(time)
		end
		-- (everyone else: the beads going off all over him, the palms blazing)
		task.spawn(function()
			local t0 = os.clock()
			while char.Parent and os.clock() - t0 < time do
				BK.bead(char)
				BK.bead(char)
				if rng:NextNumber() < 0.5 then
					sparks(handPos(char, rng:NextNumber() < 0.5), 0.5, Color3.new(1, 1, 1), FIRE[1], 4)
				end
				task.wait(0.04)
			end
		end)
	end

	-- everything he has left, point blank - and the card floats down
	function Effects.FullBodyClusterFinal(char, data)
		local root = charParts(char)
		BK.cluster[char] = nil
		if not root then
			return
		end
		local at = typeof(data.Pos) == "Vector3" and data.Pos or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		if not VFX.Clip(char, "ClusterFinal") then
			VFX.Pose(char, "Blast", 0.45)
		end
		BK.fullBody(char, 1.1)
		toonExplosion(at + d * 1.5, 5, { SmokeLife = 2.8 })
		task.delay(0.07, function()
			toonExplosion(at + d * 8, 3.4, { NoDebris = true, SmokeLife = 2 })
		end)
		task.delay(0.14, function()
			toonExplosion(at + d * 13 + UP * 2, 2.4, { NoDebris = true, SmokeLife = 1.6 })
		end)
		shockDisc(at, d, 4, 54, 0.4, FIRE[2], 8)
		shockDisc(groundPoint(at) + UP * 0.3, UP, 4, 40, 0.45, Color3.new(1, 1, 1))
		billboardRing(at, 4, 46, FIRE[1], 12, 0.4)
		streaks(at, d, 18, 0.6, 12, 36, FIRE[1], 0.35)
		rocks(groundPoint(at + d * 3), 1.4, 14)
		groundMark(groundPoint(at + d * 3), 8, Color3.fromRGB(40, 32, 30), 10)
		VFX.PlaySound("BigExplosion", at, 1.2)
		VFX.PlaySound("MegaBoom", at, 0.7)
		if nearCamera(at, 70) then
			VFX.ImpactFrame(0.12)
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.3)
		end
		VFX.ShakeAt(at, 5, 180, 0.6)
		task.delay(0.35, function()
			if root.Parent then
				BK.card(root.Position + UP * 1.2)
			end
		end)
	end

	-- nobody in reach: he blasts off down the aim into one explosion
	function Effects.FullBodyClusterWhiff(char, data)
		local root = charParts(char)
		local st = BK.cluster[char]
		if st then
			st.dead = true
		end
		BK.cluster[char] = nil
		if not root then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local len = tonumber(data.Length) or 16
		afterimage(char, FIRE[1], 0.3)
		toonExplosion(from - d * 1.2, 1.2, { NoDebris = true, SmokeLife = 0.9 })
		streaks(from + UP, d, 10, 1.2, 8, len, Color3.new(1, 1, 1), 0.25)
		VFX.PlaySound("BlitzGo", from, 1)
		task.delay(0.08, function()
			if not VFX.Clip(char, "ClusterPalm") then
				VFX.Pose(char, "Blast", 0.35)
			end
			BK.fullBody(char, 0.7)
			toonExplosion(from + d * (len + 2.5), 2.4, { SmokeLife = 1.4 })
			VFX.PlaySound("Explosion", from + d * len, 1)
			VFX.ShakeAt(from + d * len, 2.5, 110, 0.3)
		end)
	end

	function Effects.FullBodyClusterCancel(char)
		local st = BK.cluster[char]
		if st then
			st.dead = true
		end
		BK.cluster[char] = nil
		VFX.ReleasePose(char, 0.2)
	end

	-- HOWITZER IMPACT (ult): up into the sky on a column of blasts, then he
	-- spins into a tornado of explosions and crashes down on the aim point -
	-- one enormous blast, a ring of explosions round the crater
	function Effects.Howitzer(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local target = aimGround(root, data, ability.Range or 120)
		local d = flatten(target - root.Position, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.35, 1.4)
			launch(root, hum, UP * 120 + d * 20)
		end
		cinematicFor(char, "Howitzer", isLocal, ability.Name or "HOWITZER IMPACT", FIRE[2])
		VFX.Motion(char, "Howitzer")
		VFX.PlaySound("HowitzerSpin", root.Position, 1.2)
		VFX.PlaySound("BlastCharge", root.Position, 0.9)
		BK.palm(handPos(char, true), -UP, 1.6)
		BK.palm(handPos(char, false), -UP, 1.6)
		-- the climb, then the spin: a two-tone fire tornado round him
		local model = outlineModel(FLAME_OUTLINE)
		local function spin(t)
			for k = 0, 2 do
				local a = t * 26 + k * (math.pi * 2 / 3)
				local r = 3.5 + math.min(t, 1) * 4
				local p = root.Position + Vector3.new(math.cos(a) * r, -2 + math.sin(t * 9) * 1.5 + k, math.sin(a) * r)
				local puff = newPart(Vector3.one * 3.4, CFrame.new(p), FIRE[rng:NextInteger(1, 4)], Enum.Material.Neon, Enum.PartType.Ball, model)
				tween(puff, 0.3, { Size = Vector3.one * 0.1 })
			end
		end
		local t0 = os.clock()
		while os.clock() - t0 < 0.95 and root.Parent do
			spin(os.clock() - t0)
			task.wait(0.03)
		end
		if not root.Parent then
			cleanup(model, 0.3)
			return
		end
		-- the dive
		local v = target - root.Position
		local flight = math.clamp(v.Magnitude / 220, 0.25, 0.7)
		if isLocal then
			dash(root, (v.Magnitude > 1 and v.Unit or -UP) * math.max(v.Magnitude / flight, 60), flight)
		end
		t0 = os.clock()
		while os.clock() - t0 < flight and root.Parent do
			spin(1 + os.clock() - t0)
			task.wait(0.03)
		end
		cleanup(model, 0.5)
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position) + UP * 3
		local R = ability.Radius or 44
		VFX.ImpactFrame(0.12)
		toonExplosion(center, 7.5, { SmokeLife = 5 })
		task.delay(0.08, function()
			toonExplosion(center + UP * 8, 5, { NoDebris = true, SmokeLife = 4 })
		end)
		shockDisc(center, UP, 12, R * 4.2, 0.6, FIRE[2])
		shockDisc(center + UP * 2, UP, 10, R * 3, 0.5, Color3.new(1, 1, 1))
		billboardRing(center + UP * 4, 8, R * 3.4, BLAST_YELLOW, 14, 0.5)
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			task.delay(0.1 + i * 0.05, function()
				toonExplosion(center + Vector3.new(math.cos(a) * R * 0.8, 0, math.sin(a) * R * 0.8), 2.8, { NoScorch = true })
			end)
		end
		rocks(center, 3, 40)
		groundMark(center, R * 0.8, Color3.fromRGB(34, 28, 26), 20)
		emberCloud(center + UP * 10, R * 0.8, 3, 120)
		VFX.PlaySound("MegaBoom", center, 1.3)
		if nearCamera(center, R * 3) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.5)
		end
		VFX.ShakeAt(center, 6, R * 7, 1.1)
	end

end

