-- ONE FOR ALL
---------------------------------------------------------------------------

do -- ALL MIGHT's grapples, counter and weather (one table: the local limit)
	local AM = {}

	-- a golden ghost of him in his prime, flaring over his body
	function AM.ghost(char, life)
		local model = outlineModel(Color3.fromRGB(120, 70, 10))
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 then
				local g = newPart(part.Size * 1.35, part.CFrame, GOLD, Enum.Material.Neon, nil, model)
				g.Transparency = 0.35
				tween(g, life, { Size = part.Size * 1.8, Transparency = 1 })
			end
		end
		cleanup(model, life + 0.1)
	end

	-- HERO'S COUNTER: the stance - planted, arms crossed, waiting for it
	function Effects.HeroCounter(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local window = (ability and ability.Window) or 0.9
		VFX.Pose(char, "CounterStance", window)
		billboardRing(root.Position, 2, 10, GOLD, 4, 0.3)
		VFX.PlaySound("GuardUp", root.Position, 1)
		if isLocal then
			VFX.Hooks.Dim(0.2, window)
		end
		local t0 = os.clock()
		while os.clock() - t0 < window and root.Parent and char:GetAttribute("Countering") ~= false do
			if rng:NextNumber() < 0.4 then
				sparks(root.Position + Vector3.new(rand(-1.5, 1.5), rand(-1, 2), rand(-1.5, 1.5)), 0.3, Color3.new(1, 1, 1), GOLD, 2)
			end
			task.wait(0.06)
		end
	end

	-- ...and it caught something: the Symbol of Peace, for one punch
	function Effects.HeroCounterHit(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local d = flatten(tr and (tr.Position - root.Position) or root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		if me and me.Character == char then
			face(root, d)
			VFX.ImpactFrame(0.1)
		end
		AM.ghost(char, 0.5)
		VFX.Motion(char, "DetroitSmash")
		VFX.PlaySound("Parry", root.Position, 1)
		sparks(root.Position + d * 2, 1, Color3.new(1, 1, 1), GOLD, 20)
		task.wait(0.14)
		if not root.Parent then
			return
		end
		local origin = root.Position + d * 3 + UP
		windBlast(origin, d, 1.3)
		for i = 1, 4 do
			task.delay(i * 0.03, function()
				shockDisc(origin, d, 7, 32, 0.45, WIND, 60)
			end)
		end
		billboardRing(origin, 3, 26, GOLD, 8, 0.3)
		VFX.PlaySound("MightImpact", origin, 1)
		VFX.ShakeAt(origin, 3, 150, 0.5)
		if nearCamera(origin, 60) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
		end
	end

	-- BACKDROP DRIVER, part 1: he lunges to wrap them up
	function Effects.BackdropDriver(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			dash(root, d * 45, 0.12)
		end
		VFX.Pose(char, "BearHug", 0.3)
		VFX.PlaySound("Swing", root.Position, 1)
	end

	-- BACKDROP DRIVER, part 2 (the server says he caught them): the arch, the
	-- leap back, and the street behind him caves in
	function Effects.BackdropCatch(char, data, _isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("BackdropDriver") or {}
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not target then
			VFX.Pose(char, "Stagger", 0.3) -- (grabbed thin air)
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		local over = ability.OverTime or 0.55
		VFX.Motion(char, "Suplex")
		VFX.PlaySound("Leap", root.Position, 1)
		if me and me.Character == char and hum then
			launch(root, hum, -d * 10 + UP * 22)
		end
		local stopTrail = addTrail(root, GOLD, 0.3, 2.4)
		task.wait(over)
		stopTrail(0)
		if not root.Parent then
			return
		end
		local impact = groundPoint(root.Position - d * 3.5)
		local R = ability.Crater or 16
		VFX.ImpactFrame(0.08)
		shockDisc(impact + UP * 0.4, UP, 6, R * 4, 0.5, WIND)
		shockDisc(impact + UP * 0.6, UP, 4, R * 2.6, 0.4, GOLD)
		billboardRing(impact + UP, 3, R * 2.5, Color3.new(1, 1, 1), 8, 0.3)
		dustPuffs(impact, 2.4, 12, Color3.fromRGB(206, 196, 186), 1.4, true)
		rocks(impact, 2.4, 22)
		groundMark(impact, R * 0.7, Color3.fromRGB(52, 46, 44), 14)
		VFX.PlaySound("MightImpact", impact, 1)
		VFX.PlaySound("Downslam", impact, 1)
		VFX.ShakeAt(impact, 4, 160, 0.6)
	end

	-- WEATHER CHANGER (ult V): the uppercut at the sky, the updraft that
	-- sucks everyone up, the clouds torn open overhead, then the rain of it
	function Effects.WeatherChanger(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local R = ability.Radius or 45
		local hang = ability.HangTime or 1.1
		if isLocal then
			VFX.Hooks.Dim(0.3, 1.2)
		end
		VFX.Motion(char, "SkyUppercut")
		VFX.PlaySound("DetroitCharge", root.Position, 1.2)
		chargeFist(char, root, 0.45, 1.3)
		if not root.Parent then
			return
		end
		local g = groundPoint(root.Position)
		AM.ghost(char, 0.4)
		VFX.PlaySound("MightImpact", root.Position, 1.2)
		VFX.PlaySound("Wind", root.Position, 1.2)
		if nearCamera(root.Position, 90) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
		end
		-- the updraft: a column of wind roaring up off the street
		for i = 1, 6 do
			task.delay(i * 0.05, function()
				shockDisc(g + UP * (i * 6), UP, R * 0.6, R * 1.6, 0.5, WIND, 40)
			end)
		end
		for _ = 1, 3 do
			streaks(g + UP * 2, UP, 24, R * 0.5, 16, 140, WIND, 0.6)
		end
		dustPuffs(g, 2.6, 14, Color3.fromRGB(206, 196, 186), 1.5, true)
		rocks(g, 2.6, 24)
		-- the clouds split open overhead
		local sky = g + UP * 110
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local puff = newPart(Vector3.one * 26, CFrame.new(sky + out * 10), Color3.fromRGB(236, 238, 244), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.25
			tween(puff, 1.2, { CFrame = CFrame.new(sky + out * (R * 2.2)), Size = Vector3.one * 44 }, Enum.EasingStyle.Quad)
			tween(puff, 1.6, { Transparency = 1 }, nil, nil, hang + 0.8)
			cleanup(puff, hang + 2.6)
		end
		billboardRing(sky, 10, R * 4, Color3.new(1, 1, 1), 10, 0.8)
		VFX.ShakeAt(g, 4, 200, 0.8)
		-- ...then it all comes back down: rain, and the crash
		task.delay(hang, function()
			local t0 = os.clock()
			while os.clock() - t0 < 1.6 do
				for _ = 1, 6 do
					local from = g + Vector3.new(rand(-R, R), rand(60, 90), rand(-R, R))
					local drop = newPart(Vector3.new(0.15, 4, 0.15), CFrame.new(from), Color3.fromRGB(190, 210, 240), Enum.Material.Glass)
					drop.Transparency = 0.4
					tween(drop, 0.5, { CFrame = CFrame.new(from - UP * 70) }, Enum.EasingStyle.Linear)
					cleanup(drop, 0.55)
				end
				task.wait(0.05)
			end
		end)
		task.delay(hang + 0.35, function()
			shockDisc(g + UP * 0.5, UP, 6, R * 3, 0.5, WIND)
			VFX.PlaySound("Downslam", g, 1.2)
			VFX.ShakeAt(g, 3.5, 200, 0.6)
		end)
	end
end

function Effects.PlusUltraRush(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	local right = d:Cross(UP)
	if isLocal then
		face(root, d)
		dash(root, d * 80, 0.15)
	end
	task.wait(0.2)
	local hits = (ability and ability.Hits) or 12
	for k = 1, hits do
		if not root.Parent then
			return
		end
		VFX.Pose(char, k % 2 == 0 and "PunchL" or "PunchR", 0.08)
		local p = root.Position + d * 4.5 + right * rand(-2.2, 2.2) + UP * rand(-1, 2)
		local fist = newPart(Vector3.one * 1.5, CFrame.new(p), k % 3 == 0 and GOLD or Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(fist, 0.06, { Size = Vector3.one * 4.5 })
		tween(fist, 0.1, { Size = Vector3.one * 5, Transparency = 1 }, nil, nil, 0.06)
		cleanup(fist, 0.2)
		shockDisc(p, d, 2, 9, 0.16, WIND, 10)
		streaks(p, d, 3, 1, 4, 10, WIND, 0.12)
		VFX.ShakeAt(p, 0.6, 50, 0.08)
		task.wait(0.1)
	end
	task.wait(0.05)
	if not root.Parent then
		return
	end
	-- final PLUS ULTRA punch
	VFX.Pose(char, "PunchR", 0.5)
	local origin = root.Position + d * 4 + UP
	if nearCamera(origin, 90) then
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
	end
	for i = 1, 6 do
		task.delay(i * 0.03, function()
			shockDisc(origin, d, 8, 34, 0.45, WIND, 60)
		end)
	end
	shockDisc(origin, d, 4, 26, 0.25, GOLD)
	windBlast(origin, d, 1.8)
	VFX.PlaySound("MightSmash", origin, 1.2)
	VFX.ShakeAt(origin, 3, 160, 0.5)
end

function Effects.TexasSmashMax(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
		VFX.Hooks.Dim(0.5, 0.6)
	end
	VFX.Pose(char, "Kneel", 0.35)
	task.spawn(function()
		local t0 = os.clock()
		while os.clock() - t0 < 0.35 and root.Parent do
			local hand = handPos(char, true)
			bolt(hand, 2, GOLD)
			shockDisc(hand, d, 9, 1, 0.12, WIND)
			task.wait(0.05)
		end
	end)
	chargeFist(char, root, 0.35, 1.6)
	if not root.Parent then
		return
	end
	VFX.Pose(char, "PunchR", 0.6)
	local origin = root.Position + d * 4 + UP
	if nearCamera(origin, 140) then
		VFX.ImpactFrame(0.1)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.35)
	end
	windBlast(origin, d, 2.6)
	for i = 1, 10 do
		task.delay(i * 0.03, function()
			shockDisc(origin, d, 16, 62, 0.6, WIND, 135)
		end)
	end
	shockDisc(origin, d, 6, 40, 0.28, GOLD)
	streaks(origin, d, 70, 15, 22, 230, WIND, 0.5)
	-- corkscrew of wind around the blast
	for i = 1, 40 do
		task.delay(i * 0.012, function()
			local a = i * 0.55
			local basis = CFrame.lookAt(origin, origin + d)
			local p = origin + d * (i * 3) + basis.RightVector * math.cos(a) * 9 + basis.UpVector * math.sin(a) * 9
			local seg = newPart(Vector3.new(0.45, 0.45, 8), CFrame.lookAt(p, p + d), WIND, Enum.Material.Neon)
			tween(seg, 0.4, { Transparency = 1, CFrame = CFrame.lookAt(p + d * 20, p + d * 21) })
			cleanup(seg, 0.45)
		end)
	end
	for s = 12, 130, 12 do
		task.delay(s / 260, function()
			local p = groundPoint(origin + d * s + d:Cross(UP) * rand(-8, 8))
			dustPuffs(p, 2 + s / 60, 4, Color3.fromRGB(206, 196, 186), 1.4, true)
			if s % 36 == 0 then
				rocks(p, 1.6, 6)
			end
		end)
	end
	VFX.PlaySound("MightSmash", origin, 1.2)
	VFX.ShakeAt(origin, 4.5, 240, 0.8)
end

---------------------------------------------------------------------------
-- HALF-COLD HALF-HOT: Phosphor
---------------------------------------------------------------------------

function Effects.Phosphor(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local dir = aimDir(data, root)
	if isLocal then
		face(root, dir)
		VFX.Hooks.Dim(0.4, 0.8)
	end
	VFX.Pose(char, "PunchL", 0.8)
	local glow = newPart(Vector3.one * 0.4, CFrame.new(handPos(char, false)), PAL.PHOSPHOR_CORE, Enum.Material.Neon, Enum.PartType.Ball)
	tween(glow, 0.3, { Size = Vector3.one * 3 })
	cleanup(glow, 0.32)
	local t0 = os.clock()
	while os.clock() - t0 < 0.3 and root.Parent do
		local hand = handPos(char, false)
		glow.CFrame = CFrame.new(hand)
		shockDisc(hand, dir, 7, 1, 0.12, PAL.PHOSPHOR_GLOW)
		sparks(hand, 0.4, PAL.PHOSPHOR_CORE, PAL.PHOSPHOR_GLOW, 5)
		task.wait(0.05)
	end
	if not root.Parent then
		return
	end
	local from = handPos(char, false) + dir
	local to = from + dir * 110
	beam(from, to, 2.2, PAL.PHOSPHOR_CORE, PAL.PHOSPHOR_GLOW, 0.5)
	beam(from, to, 3.4, FIRE[2], FIRE[4], 0.4)
	for i = 1, 9 do
		local p = from + dir * (i * 12)
		task.delay(i * 0.012, function()
			Flame.burst(p, rand(4, 6), 8)
		end)
	end
	for i = 1, 6 do
		task.delay(i * 0.02, function()
			shockDisc(from + dir * (i * 16), dir, 9, 3, 0.25, PAL.PHOSPHOR_GLOW)
		end)
	end
	local hitPos = firstHit(from, dir, 110)
	if hitPos then
		toonExplosion(hitPos, 1.8)
	end
	if nearCamera(from, 60) then
		VFX.Hooks.Flash(Color3.fromRGB(235, 230, 255), 0.25)
	end
	VFX.PlaySound("Fire", from, 1.2)
	VFX.ShakeAt(from, 2.2, 120, 0.4)
end

function Effects.GlacialField(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	if isLocal then
		VFX.Hooks.Dim(0.35, 0.7)
	end
	VFX.Pose(char, "Ground", 0.8)
	task.wait(0.2)
	if not root.Parent then
		return
	end
	local g = groundPoint(root.Position)
	-- ice floods the ground in a huge circle
	local disk = newPart(
		Vector3.new(0.4, 4, 4),
		CFrame.new(g + UP * 0.15) * CFrame.Angles(0, 0, math.rad(90)),
		ICE_MID,
		Enum.Material.Glass,
		Enum.PartType.Cylinder
	)
	disk.Transparency = 0.25
	tween(disk, 0.45, { Size = Vector3.new(0.4, 84, 84) })
	local model = spikeLayout("GlacialField", data, root, flatten(data.Dir, root))
	for r = 10, 40, 10 do
		task.delay(r / 90, function()
			for _ = 1, 5 do
				local a = rand(0, math.pi * 2)
				frostMist(g + Vector3.new(math.cos(a) * r, 1, math.sin(a) * r), 1.4, 2)
			end
		end)
	end
	shockDisc(g + UP * 0.5, UP, 6, 86, 0.5, ICE_TIP)
	sparks(g + UP * 2, 2.5, ICE_TIP, Color3.fromRGB(120, 200, 255), 70)
	VFX.PlaySound("Ice", g, 1.2)
	VFX.ShakeAt(g, 2.8, 160, 0.5)
	task.wait((ability and ability.IceDuration) or 5)
	shatter(model, 120)
	tween(disk, 0.6, { Transparency = 1 })
	cleanup(disk, 0.65)
end

function Effects.HeatwaveMax(char, data, isLocal, ability)
	cinematicFor(char, "HeatwaveMax", isLocal, ability and ability.Name or "FLASHFREEZE HEATWAVE", Color3.fromRGB(255, 150, 90))
	heatwaveCore(char, data, isLocal, {
		Layout = "HeatwaveMax", IceWait = 0.45, StreamTime = 0.45, StreamLength = 42,
		BlastOffset = 30, BlastScale = 5.2, Scale = 1.6, DimTime = 1.4,
	})
end

---------------------------------------------------------------------------
-- ENGINE
---------------------------------------------------------------------------

do -- ENGINE: its helpers stay local to this block (Luau allows 200 locals per scope)
	local function straightCharge(char, root, d, isLocal, revTime, speed, chargeTime, intensity)
		VFX.Pose(char, "Rev", revTime)
		exhaust(char, revTime + chargeTime + 0.1, intensity)
		VFX.PlaySound("Engine", root.Position, 1)
		dustPuffs(groundPoint(root.Position) - d * 2, 0.9, 6, Color3.fromRGB(205, 196, 190), 0.8, false)
		local t0 = os.clock()
		while os.clock() - t0 < revTime and root.Parent do
			for _, leg in calves(char) do
				bolt(leg.Position, 1.5, EXHAUST)
			end
			task.wait(0.05)
		end
		if not root.Parent then
			return false
		end
		if isLocal then
			dash(root, d * speed, chargeTime)
		end
		VFX.Pose(char, "Kick", chargeTime + 0.2)
		shockDisc(root.Position, d, 4, 22, 0.3, EXHAUST)
		local stopTrail = addTrail(root, EXHAUST, 0.4, 3)
		legTrails(char, chargeTime + 0.1, EXHAUST)
		local c0 = os.clock()
		while os.clock() - c0 < chargeTime and root.Parent do
			afterimage(char, EXHAUST, 0.3)
			streaks(root.Position + d * 2, -d, 3, 2.5, 6, 14, WIND, 0.2)
			task.wait(0.03)
		end
		stopTrail(0)
		return root.Parent ~= nil
	end

	-- Picks the closest enemy in front and blinks into them
	local function turboTarget(root, d, range)
		local best, bestDist
		local candidates = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character and plr.Character ~= root.Parent then
				table.insert(candidates, plr.Character)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		if dummies then
			for _, m in dummies:GetChildren() do
				table.insert(candidates, m)
			end
		end
		for _, m in candidates do
			local r = m:FindFirstChild("HumanoidRootPart")
			local h = m:FindFirstChildOfClass("Humanoid")
			if r and h and h.Health > 0 then
				local v = r.Position - root.Position
				local dist = v.Magnitude
				if dist < range and dist > 1 and flatten(v, root):Dot(d) > 0.3 and (not bestDist or dist < bestDist) then
					best, bestDist = r, dist
				end
			end
		end
		return best, bestDist
	end

	function Effects.TurboKick(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			local target, dist = turboTarget(root, d, (ability and ability.Range) or 50)
			if target then
				local v = (target.Position - root.Position).Unit
				face(root, v)
				dash(root, v * 260, math.clamp((dist - 3) / 260, 0.05, 0.25))
			else
				face(root, d)
				dash(root, d * 260, 0.12)
			end
		end
		VFX.Pose(char, "Kick", 0.3)
		exhaust(char, 0.3, 1.8)
		for _ = 1, 4 do
			if not root.Parent then
				return
			end
			afterimage(char, EXHAUST, 0.25)
			task.wait(0.04)
		end
		if root.Parent then
			local p = root.Position + root.CFrame.LookVector * 3
			moonArc(root.CFrame * CFrame.new(0, -0.5, -1) * CFrame.Angles(0, 0, math.rad(90)), 5, EXHAUST, 220)
			shockDisc(p, root.CFrame.LookVector, 2, 14, 0.2, WIND)
			VFX.PlaySound("Kick", p, 0.8)
			VFX.ShakeAt(p, 0.8, 40, 0.12)
		end
	end

	function Effects.ReciproMax(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		cinematicFor(char, "ReciproMax", isLocal, ability and ability.Name or "RECIPRO", EXHAUST)
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.6, 1.3)
		end
		-- blue flame pillars roaring out of the pipes while he revs
		for i = 1, 8 do
			task.delay(i * 0.07, function()
				if root.Parent then
					local p = root.Position - d * 3
					local pillar = newPart(Vector3.new(1.5, 1.5, 6), CFrame.lookAt(p, p - d + UP * 0.4), EXHAUST_CORE, Enum.Material.Neon, Enum.PartType.Ball)
					tween(pillar, 0.25, { Size = Vector3.new(0.2, 0.2, 14), Transparency = 1 })
					cleanup(pillar, 0.3)
				end
			end)
		end
		if not straightCharge(char, root, d, isLocal, 0.6, 320, 0.5, 3) then
			return
		end
		local p = root.Position + d * 5
		if nearCamera(p, 140) then
			VFX.Hooks.Flash(Color3.fromRGB(215, 235, 255), 0.35)
		end
		shockDisc(p, UP, 8, 100, 0.6, EXHAUST)
		for i = 1, 5 do
			task.delay(i * 0.03, function()
				shockDisc(p, d, 10, 44, 0.5, WIND, 70)
			end)
		end
		moonArc(CFrame.lookAt(p, p + d), 12, EXHAUST, 230)
		streaks(p, d, 60, 10, 18, 160, EXHAUST_CORE, 0.45)
		dustPuffs(groundPoint(p), 2.4, 10, Color3.fromRGB(205, 196, 190), 1.5, true)
		rocks(p, 2.4, 14)
		VFX.PlaySound("Kick", p, 1.3)
		VFX.ShakeAt(p, 4, 220, 0.7)
	end
end

---------------------------------------------------------------------------
-- MOVEMENT: quirk-flavoured dashes
---------------------------------------------------------------------------

-- Per-quirk extras registered further down (quirks added later in the file)
local QUIRK_FX = { Dash = {}, Ult = {} }

function Effects.Dash(char, data)
	local root = charParts(char)
	if not root then
		return
	end
	local dir = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or root.CFrame.LookVector
	local kind = data.Kind or "Front"
	if kind == "Side" then
		kind = "Right"
	elseif kind == "Chase" then
		kind = "Front" -- (round 65: JJS's anti-run dash - a front dash without the punch)
	end
	VFX.DashMotion(char, "Dash" .. kind)
	local g = groundPoint(root.Position)
	local grounded = (root.Position - g).Magnitude < 5
	local DUST = Color3.fromRGB(205, 196, 190)
	if grounded then
		-- kicked-up dust where they pushed off (a ring for the hop's takeoff)
		dustPuffs(g - dir * 1.5, kind == "Back" and 1 or 0.8, kind == "Back" and 6 or 4, DUST, 0.7, false)
		if kind == "Front" then
			shockDisc(g + UP * 0.4, UP, 2, 12, 0.25, WIND)
		end
	end
	streaks(root.Position, -dir, 8, 1.5, 6, 12, WIND, 0.22)
	-- afterimages strung along the path
	local ghost = (data.Quirk == "OneForAll" and GOLD) or (data.Quirk == "FullCowl" and Color3.fromRGB(120, 255, 160))
		or (data.Quirk == "Engine" and EXHAUST) or Color3.fromRGB(225, 235, 255)
	-- (the back dash: a ghost at every beat of the flip, a quick string of
	-- them through the twist, one on his hands and one as he lands - round 66)
	local B = Config.Movement.BackDashBeats or { Twist = 0.3, Hands = 0.52, Land = 0.74 }
	local beats = kind == "Back" and { 0, 0.07, 0.14, 0.2, B.Twist + 0.01, B.Twist + 0.045, B.Twist + 0.08, B.Twist + 0.11, B.Hands, B.Land }
		or { 0, 0.06, 0.12 }
	for _, at in beats do
		task.delay(at, function()
			if root.Parent then
				afterimage(char, ghost, 0.22)
			end
		end)
	end
	if kind == "Back" then
		-- (round 66) the twist: rings of wind round him as he spins
		for k = 0, 1 do
			task.delay(B.Twist + k * 0.07, function()
				if root.Parent then
					shockDisc(root.Position, dir, 1.5, 7, 0.2, WIND, 4)
					if k == 0 then
						VFX.PlaySound("BackTwist", root.Position, 0.7)
					end
				end
			end)
		end
		-- (round 65) his hands hit the street in the handstand
		task.delay(B.Hands, function()
			if not root.Parent then
				return
			end
			local plant = groundPoint(root.Position)
			if (root.Position - plant).Magnitude < 5 then
				dustPuffs(plant, 0.55, 3, DUST, 0.5, false)
				shockDisc(plant + UP * 0.3, UP, 1, 5, 0.18, WIND)
				VFX.PlaySound("PkRoll", plant, 0.45)
			end
		end)
	end
	-- the skid when a sidestep stops, the landing when the hop comes down
	task.delay(kind == "Back" and B.Land or 0.2, function()
		if not root.Parent then
			return
		end
		local land = groundPoint(root.Position)
		if (root.Position - land).Magnitude < 5 then
			dustPuffs(land + dir * 1.5, kind == "Back" and 1.1 or 0.7, kind == "Back" and 5 or 3, DUST, 0.6, false)
			if kind == "Back" then
				-- (round 66) the superhero landing: a thud, a ring along the street
				shockDisc(land + UP * 0.3, UP, 2, 14, 0.3, WIND)
				dustPuffs(land, 1.4, 6, DUST, 0.8, false)
				VFX.PlaySound("HeroLand", land, 0.8)
				VFX.ShakeAt(land, 0.5, 18, 0.12)
			elseif kind ~= "Front" then
				VFX.PlaySound("Skid", land, 0.6)
			end
		end
	end)
	local quirk = data.Quirk
	if quirk == "Explosion" then
		for k = 0, 1 do
			task.delay(k * 0.06, function()
				if root.Parent then
					toonExplosion(root.Position - dir * 3, 0.9, { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.6 })
				end
			end)
		end
		legTrails(char, 0.25, FIRE[3])
	elseif quirk == "OneForAll" then
		shockDisc(root.Position - dir * 2, -dir, 2, 12, 0.25, WIND, 6)
		for _ = 1, 3 do
			bolt(root.Position, 2.5, GOLD)
		end
		legTrails(char, 0.25, GOLD)
	elseif quirk == "HalfCold" then
		if data.Alt then
			for k = 1, 4 do
				Flame.spot(g + UP * 0.2 - dir * k * 2, rand(2.5, 3.5), 0.3, 1.5)
			end
		else
			local model = outlineModel(ICE_OUTLINE)
			local list = {}
			for k = 1, 6 do
				local base = g + dir * (k * 2.2) + dir:Cross(UP) * rand(-1, 1) - UP * 0.4
				table.insert(list, { set = makeSpike(model, base, (UP + rng:NextUnitVector() * 0.3).Unit, rand(1.5, 3), 0.9, false), delay = k * 0.03 })
			end
			growSpikes(list, 0.1)
			task.delay(0.8, function()
				shatter(model, 12)
			end)
		end
		legTrails(char, 0.25, data.Alt and FIRE[3] or ICE_TIP)
	elseif quirk == "Engine" then
		exhaust(char, 0.25, 1.4)
		afterimage(char, EXHAUST, 0.25)
		legTrails(char, 0.25, EXHAUST)
	elseif quirk == "Decay" then
		afterimage(char, Color3.fromRGB(150, 140, 142), 0.3)
		dustPuffs(root.Position - dir * 2, 0.8, 4, Color3.fromRGB(150, 140, 142), 0.9, Color3.fromRGB(70, 60, 66))
		legTrails(char, 0.25, Color3.fromRGB(214, 62, 66))
	elseif QUIRK_FX.Dash[quirk or ""] then
		QUIRK_FX.Dash[quirk](char, root, dir, data)
	else
		legTrails(char, kind == "Back" and 0.85 or 0.25, WIND)
	end
	VFX.PlaySound("Dash", root.Position, 0.5)
end

-- Getting up off the street after a ragdoll: a hand down, a knee under
-- him, up onto his feet and a shake of the head (instead of popping upright)
MOTIONS.GetUp = {
