}
POSES.RainDownLeft = {
	Hips = { 18, 14, 0 }, Waist = { -28, -24, 0 }, Neck = { 14, 18, 0 },
	LeftArm = { 38, 0, -8 }, LeftElbow = 2, RightArm = { 45, 0, 25 }, RightElbow = 110,
