	{ pose = { Hips = { -8, 18, 0 }, Waist = { 10, 10, 0 }, RightLeg = 125, RightKnee = 3, LeftLeg = -18, LeftKnee = 20, RightArm = { -20, 0, 25 }, LeftArm = { 35, 0, 35 } }, t = 0.07, hold = 0.08, style = SNAP },
	recover = 0.12,
