end -- Deku presentation

---------------------------------------------------------------------------
-- DEKU: INFINITE 100% - the end of the Overhaul fight (ep. 76). Eri rides on
-- his back, bound to him with Mirio's red cape, her horn glowing as she
-- heals him, and his lightning burns cyan. The kick blasts them skyward in
-- white arcs of wind; he's up after them, and the barrage is the anime's: a
-- sky full of huge fists - flat gold, magenta glowing round them - slamming
-- in from every side, bits flying off them. Then one giant fist, and he
-- hurls them down into the street.
-- (Its own function: the module's top level is near Luau's register limit.)
---------------------------------------------------------------------------
do
	local function setupInfinite()
		local CYAN, CYAN_HOT = Color3.fromRGB(70, 222, 255), Color3.fromRGB(214, 250, 255)
		local GOLD, AMBER, MAGENTA = Color3.fromRGB(255, 212, 80), Color3.fromRGB(255, 150, 44), Color3.fromRGB(255, 62, 196)
		local WHITE = Color3.fromRGB(250, 255, 255)
		local DUST = Color3.fromRGB(204, 200, 190)
		local states = setmetatable({}, { __mode = "k" })

		local function ballPart(size, cf, color, material, parent)
			local p = newPart(size, cf, color, material or Enum.Material.SmoothPlastic, nil, parent)
			local mesh = Instance.new("SpecialMesh")
			mesh.MeshType = Enum.MeshType.Sphere
			mesh.Parent = p
			return p
		end

		-- Eri, riding on his back: the cape wrapped round both of them
		local function eriOn(char)
			local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
			if not torso then
				return nil
			end
			local k = torso.Size.X / 2
			local model = Instance.new("Model")
			model.Name = "EriRide"
			model.Parent = folder
			local SKIN, HAIR = Color3.fromRGB(252, 224, 204), Color3.fromRGB(232, 234, 242)
			local DRESS, CAPE = Color3.fromRGB(242, 238, 230), Color3.fromRGB(208, 30, 40)
			local function stick(p)
				p.Anchored = false
				p.Massless = true
				p.CanCollide = false
				local w = Instance.new("WeldConstraint")
				w.Part0 = torso
				w.Part1 = p
				w.Parent = p
				return p
			end
			local function blob(size, pos, color, material)
				return stick(ballPart(size * k, torso.CFrame * CFrame.new(pos * k), color, material, model))
			end
			local function limbRod(a, b, thick, color)
				local mid = (a + b) / 2 * k
				local p = newPart(Vector3.new(thick * k, thick * k, (b - a).Magnitude * k + thick * k * 0.6), torso.CFrame * CFrame.lookAt(mid, b * k), color, Enum.Material.SmoothPlastic, nil, model)
				return stick(p)
			end
			blob(Vector3.new(0.95, 1.15, 0.72), Vector3.new(0.1, 0.35, 0.92), DRESS)
			blob(Vector3.new(0.8, 0.8, 0.8), Vector3.new(0.38, 1.28, 0.82), SKIN)
			-- her long silver-white hair, falling down her back
			blob(Vector3.new(1.05, 1.6, 0.7), Vector3.new(0.32, 0.82, 1.18), HAIR)
			blob(Vector3.new(0.9, 0.5, 0.88), Vector3.new(0.38, 1.52, 0.86), HAIR)
			blob(Vector3.new(0.3, 1.05, 0.3), Vector3.new(0.78, 0.92, 0.78), HAIR)
			-- her horn, glowing while her quirk runs
			local horn = blob(Vector3.new(0.14, 0.44, 0.14), Vector3.new(0.6, 1.78, 0.72), Color3.fromRGB(255, 238, 170), Enum.Material.Neon)
			local light = Instance.new("PointLight")
			light.Color = Color3.fromRGB(255, 230, 150)
			light.Range = 8
			light.Brightness = 1.5
			light.Parent = horn
			-- arms round his neck, legs round his waist
			for _, side in { 1, -1 } do
				limbRod(Vector3.new(side * 0.42 + 0.1, 0.78, 0.82), Vector3.new(side * 0.52, 0.92, -0.22), 0.22, SKIN)
				limbRod(Vector3.new(side * 0.28 + 0.1, -0.12, 0.92), Vector3.new(side * 0.9, -0.42, 0.32), 0.25, SKIN)
			end
			-- Mirio's cape binding them: round his chest and her back, the rest flying
			stick(newPart(Vector3.new(2.14, 0.36, 1.95) * k, torso.CFrame * CFrame.new(Vector3.new(0, 0.12, 0.46) * k), CAPE, Enum.Material.Fabric, nil, model))
			local tail = newPart(Vector3.new(1.5, 1.9, 0.08) * k, torso.CFrame * CFrame.new(Vector3.new(0, -0.7, 1.55) * k) * CFrame.Angles(math.rad(-28), 0, 0), CAPE, Enum.Material.Fabric, nil, model)
			stick(tail)
			return model
		end
		local function eriOff(model, after)
			if not model then
				return
			end
			task.delay(after or 0, function()
				for _, p in model:GetDescendants() do
					if p:IsA("BasePart") then
						tween(p, 0.3, { Transparency = 1 })
					end
				end
				cleanup(model, 0.35)
			end)
		end

		-- a curve of white wind: tapered segments along points
		local function windArc(points, width, color, life)
			local model = Instance.new("Model")
			model.Name = "InfiniteWind"
			model.Parent = folder
			for i = 1, #points - 1 do
				local a, b = points[i], points[i + 1]
				local taper = math.sin(math.pi * (i - 0.5) / (#points - 1))
				local thick = math.max(0.04, width * taper)
				local seg = newPart(Vector3.new(thick, thick, (b - a).Magnitude + 0.05), CFrame.lookAt((a + b) / 2, b), color, Enum.Material.Neon, nil, model)
				seg.Transparency = 0.1
				tween(seg, life, { Transparency = 1, Size = Vector3.new(0.02, 0.02, seg.Size.Z) })
			end
			cleanup(model, life + 0.05)
		end
		-- rings of wind round an axis (the anime's white arcs off the kick)
		local function windRings(center, axis, radius, count, life)
			local basis = CFrame.lookAt(center, center + axis)
			for n = 1, count do
				local r = radius * (0.55 + n * 0.3)
				local start = rand(0, math.pi * 2)
				local pts = {}
				for i = 0, 12 do
					local a = start + i / 12 * math.pi * 1.3
					table.insert(pts, basis:PointToWorldSpace(Vector3.new(math.cos(a) * r, math.sin(a) * r, -n * 1.4)))
				end
				windArc(pts, 0.5 + n * 0.08, WHITE, life + n * 0.04)
			end
		end

		-- one fist of the barrage: a clenched fist on a forearm in the anime's
		-- flat gold (amber knuckles), magenta glowing round it. -Z punches.
		local function fist(cf, scale, fill, shade, glow)
			local model = Instance.new("Model")
			model.Name = "InfiniteFist"
			model.Parent = folder
			local parts, rels = {}, {}
			local function bit(size, pos, color, round, rot)
				local rel = CFrame.new(pos * scale) * (rot or CFrame.new())
				local p = round and ballPart(size * scale, cf * rel, color, Enum.Material.Neon, model)
					or newPart(size * scale, cf * rel, color, Enum.Material.Neon, nil, model)
				table.insert(parts, p)
				table.insert(rels, rel)
				return p
			end
			bit(Vector3.new(1.25, 1.05, 1), Vector3.zero, fill)
			bit(Vector3.new(1.25, 0.62, 0.56), Vector3.new(0, -0.12, -0.62), fill)
			for i = 0, 3 do
				bit(Vector3.new(0.34, 0.38, 0.4), Vector3.new(-0.46 + i * 0.307, 0.26, -0.56), shade, true)
			end
			bit(Vector3.new(0.42, 0.4, 0.82), Vector3.new(0.66, -0.2, -0.3), shade, true, CFrame.Angles(0, math.rad(-18), 0))
			bit(Vector3.new(0.95, 0.88, 2.3), Vector3.new(0, -0.02, 1.45), fill, true)
			local halo = bit(Vector3.new(1.75, 1.55, 3.1), Vector3.new(0, 0, 0.6), glow, true)
			halo.Transparency = 0.74
			return model, parts, rels
		end
		-- a fist flying in from `from` and slamming into `at`, then gone
		local function throwFist(from, at, scale, fill, shade, glow, time)
			local d = (at - from).Unit
			local stopAt = at - d * 1.2 * scale
			local model, parts, rels = fist(CFrame.lookAt(from, from + d), scale, fill, shade, glow)
			cleanup(model, time + 0.2)
			task.spawn(function()
				local t0 = os.clock()
				local cfs = table.create(#parts)
				while model.Parent do
					local a = math.clamp((os.clock() - t0) / time, 0, 1)
					local pos = from:Lerp(stopAt, 1 - (1 - a) ^ 2)
					local base = CFrame.lookAt(pos, pos + d)
					for i, rel in rels do
						cfs[i] = base * rel
					end
					local ok = pcall(function()
						workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
					end)
					if not ok then
						for i, part in parts do
							part.CFrame = cfs[i]
						end
					end
					if a >= 1 then
						break
					end
					RunService.Heartbeat:Wait()
				end
				for _, p in parts do
					if p.Parent then
						tween(p, 0.12, { Transparency = 1 })
					end
				end
			end)
		end
		-- a white flash blooming at a point
		local function flash(pos, from, to, time, color)
			local f = ballPart(Vector3.one * from, CFrame.new(pos), color or WHITE, Enum.Material.Neon)
			f.Transparency = 0.1
			tween(f, time, { Size = Vector3.one * to, Transparency = 1 })
			cleanup(f, time + 0.05)
		end

		local function clear(char, release)
			local st = states[char]
			if not st then
				return
			end
			states[char] = nil
			st.dead = true
			if st.backdrop then
				tween(st.backdrop, 0.2, { Transparency = 1 })
				cleanup(st.backdrop, 0.25)
			end
			eriOff(st.eri, release and 0 or 0.6)
			for _, stop in st.stops do
				stop(0)
			end
			if release then
				VFX.ReleasePose(char, 0.08)
			end
		end
		local function crackle(char, st)
			task.spawn(function()
				while states[char] == st and not st.dead do
					local root = char:FindFirstChild("HumanoidRootPart")
					if not root or os.clock() - st.t0 > (st.limit or 3) then
						clear(char, true)
						break
					end
					bolt(root.Position + rng:NextUnitVector() * rand(0.5, 1.8), rand(1, 1.8), rng:NextNumber() < 0.6 and CYAN or CYAN_HOT)
					task.wait(0.11)
				end
			end)
		end

		function Effects.FistRain(char, data, isLocal)
			local root = charParts(char)
			if not root then
				return
			end
			clear(char, false)
			local d = flatten(data.Dir, root)
			local st = { t0 = os.clock(), stops = {}, dead = false, lastIndex = 0, hits = 14 }
			states[char] = st
			st.eri = eriOn(char)
			crackle(char, st)
			if isLocal then
				face(root, d)
				dash(root, d * 28, 0.16)
			end
			VFX.Motion(char, "RainLaunch")
			for _ = 1, 5 do
				bolt(root.Position + rng:NextUnitVector() * 2, 2.6, CYAN)
			end
			table.insert(st.stops, addTrail(limb(char, "RightFoot", "Right Leg") or root, CYAN, 0.14, 0.6))
			VFX.PlaySound("Dash", root.Position, 0.7)
			task.wait(0.18)
			if states[char] ~= st then
				return
			end
			windArc({
				root.Position + d * 1 + UP * -0.5,
				root.Position + d * 3 + UP * 1.2 + d:Cross(UP) * 1.5,
				root.Position + d * 4.5 + UP * 3.2,
				root.Position + d * 3.5 + UP * 5.2 - d:Cross(UP) * 1.2,
			}, 0.4, WHITE, 0.2)
			VFX.PlaySound("Kick", root.Position + d * 3, 0.9)
			-- (a whiff: Eri lets go again soon after)
			task.delay(0.45, function()
				if states[char] == st and not st.caught then
					clear(char, true)
				end
			end)
		end

		function Effects.FistRainCatch(char, data)
			local st = states[char]
			local target = typeof(data.Target) == "Instance" and data.Target
			local troot = target and target:FindFirstChild("HumanoidRootPart")
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if not troot or not root then
				return
			end
			if not st then
				st = { t0 = os.clock(), stops = {}, dead = false, lastIndex = 0 }
				states[char] = st
				crackle(char, st)
			end
			st.caught = true
			-- (the safety net: long enough for the whole storm from the catch on)
			st.t0 = os.clock()
			st.limit = (tonumber(data.RiseTime) or 0.3) + (tonumber(data.Barrage) or 0.9) + (tonumber(data.RainTime) or 0.6) + 1.5
			st.target = troot
			st.root = root
			st.hits = data.Hits or 14
			st.at = typeof(data.At) == "Vector3" and data.At or troot.Position
			-- the kick lands: a boom, white arcs of wind, the street kicked up
			local d = flatten(troot.Position - root.Position, root)
			shockDisc(troot.Position, d, 1, 14, 0.24, WHITE)
			windRings(troot.Position, (UP * 0.8 + d).Unit, 3, 3, 0.3)
			sparks(troot.Position, 0.6, WHITE, CYAN, 14)
			rocks(troot.Position, 1.4, 9)
			dustPuffs(troot.Position - UP * 2, 1.4, 5, DUST, 0.8, false)
			VFX.PlaySound("HeavyHit", troot.Position, 1)
			VFX.ShakeAt(troot.Position, 1.6, 90, 0.25)
			if nearCamera(troot.Position, 90) then
				VFX.ImpactFrame(0.08)
			end
			-- up they go, and he goes after them
			table.insert(st.stops, addTrail(troot, WHITE, 0.3, 2.4))
			table.insert(st.stops, addTrail(root, CYAN, 0.25, 1.6))
			VFX.Pose(char, "RainHover", (data.RiseTime or 0.3) + 0.1)
			if data.Air then
				streaks(troot.Position, UP, 8, 0.35, 5, 14, WHITE, 0.25)
				-- the sky behind them goes magenta for the barrage (the anime's cut)
				task.delay((data.RiseTime or 0.3) * 0.8, function()
					if states[char] ~= st or st.dead then
						return
					end
					local bg = ballPart(Vector3.one * 4, CFrame.new(st.at), MAGENTA, Enum.Material.Neon)
					bg.Name = "InfiniteBackdrop"
					bg.Transparency = 1
					st.backdrop = bg
					tween(bg, 0.12, { Size = Vector3.one * 14, Transparency = 0.88 })
				end)
			end
			-- the camera (his, and theirs): up after them into the sky, in close
			-- as his punches speed up, back over the fists raining down, and
			-- out wide for the blast
			local me = Players.LocalPlayer and Players.LocalPlayer.Character
			if me and (me == char or me == target) then
				local start = root.Position
				local D = math.max(Vector3.new(st.at.X - start.X, 0, st.at.Z - start.Z).Magnitude, 3)
				local lift = math.max(st.at.Y - start.Y, 0)
				local rise, barrage, rain = tonumber(data.RiseTime) or 0.3, tonumber(data.Barrage) or 0.9, tonumber(data.RainTime) or 0.6
				local high, close = V(9, math.max(lift - 2, 1), -D + 12), V(0, lift + 1, -D + 3)
				st.cine = VFX.Cinematic(char, {
					{ T = rise + 0.15, From = { V(5, 1, 5), V(0, 2, -D * 0.6) }, To = { high, close }, Fov = { 70, 62 }, Style = Enum.EasingStyle.Quad },
					{ T = math.max(barrage - 0.15, 0.3), From = { high, close }, To = { V(5, lift + 0.8, -D + 7.5), close }, Fov = { 62, 44 }, Style = Enum.EasingStyle.Quad },
					{ T = 0.1 + rain, Cut = true, From = { V(12, lift + 12, -D + 14), V(0, lift * 0.5, -D) }, To = { V(16, lift + 16, -D + 20), V(0, 1, -D) }, Fov = { 66, 72 } },
					{ T = 1, Cut = true, From = { V(18, 4, -D + 22), V(0, 3, -D) }, To = { V(24, 8, -D + 30), V(0, 6, -D) }, Fov = { 70, 80 } },
				}, { Title = "INFINITE 100%", Color = CYAN, Own = me == char, Face = st.at })
			end
		end

		function Effects.FistRainStrike(char, data)
			local st = states[char]
			if not st or st.dead or not st.root or not st.root.Parent or not st.target or not st.target.Parent then
				return
			end
			local index = math.clamp(tonumber(data.Index) or st.lastIndex + 1, 1, st.hits or 14)
			if index <= st.lastIndex then
				return
			end
			st.lastIndex = index
			local at = typeof(data.Pos) == "Vector3" and data.Pos or st.target.Position
			local d = (at - st.root.Position)
			d = d.Magnitude > 0.1 and d.Unit or st.root.CFrame.LookVector
			local right = d:Cross(UP)
			right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
			local up = right:Cross(d)
			VFX.Pose(char, index % 2 == 0 and "PunchL" or "PunchR", 0.07)
			if index >= 8 then
				afterimage(char, CYAN, 0.12) -- (his arms a blur)
			end
			if index == 6 and Players.LocalPlayer and char == Players.LocalPlayer.Character then
				VFX.Hooks.SpeedLines(1)
			end
			-- fists slam in from anywhere in front of him: more of them, and
			-- faster, the further into the storm he gets
			local speed = math.max(0.045, 0.085 - index * 0.0025)
			for n = 1, math.min(1 + index // 4, 4) do
				local a = rand(0, math.pi * 2)
				local spread = rand(0.3, 1.3)
				local dirIn = (d + (right * math.cos(a) + up * math.sin(a)) * spread).Unit
				local scale = rand(1.3, 2)
				local from = at - dirIn * rand(7, 10) * scale * 0.6
				throwFist(from, at, scale, GOLD, (n + index) % 2 == 0 and AMBER or Color3.fromRGB(255, 236, 150), MAGENTA, speed)
			end
			task.delay(speed, function()
				if states[char] ~= st then
					return
				end
				flash(at, 1.4, 4.5 + index * 0.12, 0.1, index % 3 == 0 and CYAN_HOT or WHITE)
				shockDisc(at, -d, 0.5, 5 + index * 0.18, 0.13, WHITE)
				if index % 2 == 0 then
					sparks(at, 0.35, GOLD, MAGENTA, 7)
					VFX.PlaySound(index % 4 == 0 and "HeavyHit" or "Hit", at, 0.75)
				end
				if index % 3 == 0 then
					-- bits of them flying off
					local body = st.target.Parent
					local torso = body and (body:FindFirstChild("Torso") or body:FindFirstChild("UpperTorso"))
					local c = torso and torso.Color or DUST
					for _ = 1, 3 do
						local chunk = newPart(Vector3.one * rand(0.35, 0.7), CFrame.new(at) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), c:Lerp(Color3.new(0, 0, 0), 0.2), Enum.Material.Slate)
						local out = (d + rng:NextUnitVector() * 0.9).Unit
						tween(chunk, 0.45, { CFrame = CFrame.new(at + out * rand(6, 11) - UP * rand(1, 4)), Size = Vector3.one * 0.1 }, Enum.EasingStyle.Quad)
						cleanup(chunk, 0.5)
					end
				end
				VFX.ShakeAt(at, 0.45, 70, 0.08)
			end)
		end

		-- ...then the fists come RAINING down: off him and out of the sky, onto
		-- them as they drop and all over the street under them
		function Effects.FistRainFall(char, data)
			local st = states[char]
			local target = typeof(data.Target) == "Instance" and data.Target
			local troot = target and target:FindFirstChild("HumanoidRootPart")
			local from = typeof(data.From) == "Vector3" and data.From
			local pos = typeof(data.Pos) == "Vector3" and data.Pos
			if not troot or not from or not pos then
				return
			end
			local time = tonumber(data.Time) or 0.6
			local hits = tonumber(data.Hits) or 4
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if st and st.backdrop then
				tween(st.backdrop, 0.15, { Transparency = 1 })
				cleanup(st.backdrop, 0.2)
				st.backdrop = nil
			end
			if char and char.Parent then
				VFX.Pose(char, "RainHammer", time + 0.1)
			end
			local victimEnd = pos + UP * 3
			local stopTrail = addTrail(troot, WHITE, 0.3, 3)
			streaks(from, -UP, 10, 0.7, 8, math.max((from - pos).Magnitude, 4), WHITE, time)
			VFX.PlaySound("Wind", from, 0.9)
			local LIGHT = Color3.fromRGB(255, 236, 150)
			task.spawn(function()
				local t0 = os.clock()
				local landed, n = 0, 0
				while os.clock() - t0 < time and troot.Parent do
					local a = math.clamp((os.clock() - t0) / time, 0, 1)
					local vpos = from:Lerp(victimEnd, a * a)
					local deku = root and root.Parent and root.Position or from + UP * 6
					n += 1
					-- one onto them, thrown down off his fists...
					local onThem = vpos + rng:NextUnitVector() * 1.2
					local src = deku + UP * rand(2, 5) + rng:NextUnitVector() * rand(2, 6)
					throwFist(src, onThem, rand(1.4, 2.1), GOLD, n % 2 == 0 and AMBER or LIGHT, MAGENTA, 0.09)
					task.delay(0.09, function()
						flash(onThem, 1, 4, 0.08, n % 3 == 0 and CYAN_HOT or WHITE)
					end)
					-- ...and one out of the sky onto the street round them
					local ang, r = rand(0, math.pi * 2), rand(3, 14)
					local ground = groundPoint(pos + Vector3.new(math.cos(ang) * r, 4, math.sin(ang) * r))
					local sky = ground + UP * rand(18, 26) + Vector3.new(rand(-5, 5), 0, rand(-5, 5))
					throwFist(sky, ground + UP * 0.8, rand(1.6, 2.6), GOLD, n % 2 == 1 and AMBER or LIGHT, MAGENTA, 0.11)
					task.delay(0.11, function()
						shockDisc(ground + UP * 0.2, UP, 1, 8, 0.2, WHITE)
						dustPuffs(ground, 0.6, 2, DUST, 0.6, false)
						if n % 3 == 0 then
							rocks(ground, 0.6, 3)
						end
					end)
					-- the heavy ones: a bigger fist square on them each time it hurts
					while landed < hits and a >= (landed + 0.5) / hits do
						landed += 1
						local at = vpos
						throwFist(deku + UP * 3, at, 2.8, GOLD, AMBER, MAGENTA, 0.08)
						task.delay(0.08, function()
							flash(at, 2, 8, 0.12, CYAN_HOT)
							shockDisc(at, UP, 1, 10, 0.16, WHITE)
							sparks(at, 0.6, WHITE, GOLD, 10)
							VFX.PlaySound("HeavyHit", at, 0.9)
							VFX.ShakeAt(at, 0.9, 90, 0.12)
						end)
					end
					if n % 2 == 0 then
						VFX.PlaySound("Hit", vpos, 0.6)
					end
					task.wait(0.035)
				end
				stopTrail(0.1)
			end)
		end

		-- ...the last and biggest fist drives them into the street, and it
		-- all goes off
		function Effects.FistRainFinish(char, data)
			local pos = typeof(data.Pos) == "Vector3" and data.Pos
			local st = states[char]
			if not pos then
				clear(char, true)
				return
			end
			local eri = st and st.eri
			if st then
				st.eri = nil
			end
			clear(char, false)
			eriOff(eri, 1.2)
			if char and char.Parent then
				VFX.Pose(char, "RainDrive", 0.35)
			end
			local hitAt = pos + UP * 2.5
			throwFist(hitAt + UP * 16 + rng:NextUnitVector() * 2, hitAt, 4.6, CYAN_HOT, WHITE, CYAN, 0.07)
			task.delay(0.07, function()
				-- the fireball
				flash(pos + UP * 3, 4, 30, 0.28, WHITE)
				local ball = ballPart(Vector3.one * 6, CFrame.new(pos + UP * 3), GOLD, Enum.Material.Neon)
				ball.Transparency = 0.1
				tween(ball, 0.5, { Size = Vector3.one * 36, Transparency = 1 }, Enum.EasingStyle.Quad)
				cleanup(ball, 0.55)
				local core = ballPart(Vector3.one * 4, CFrame.new(pos + UP * 3), CYAN_HOT, Enum.Material.Neon)
				core.Transparency = 0.05
				tween(core, 0.32, { Size = Vector3.one * 22, Transparency = 1 }, Enum.EasingStyle.Quad)
				cleanup(core, 0.36)
				-- the dome of dust rolling out
				local dome = ballPart(Vector3.new(10, 6, 10), CFrame.new(pos), DUST)
				dome.Transparency = 0.25
				tween(dome, 1, { Size = Vector3.new(50, 24, 50), Transparency = 1 }, Enum.EasingStyle.Quad)
				cleanup(dome, 1.05)
				-- rings, and a pillar of light
				shockDisc(pos + UP * 0.3, UP, 2, 64, 0.5, WHITE)
				shockDisc(pos + UP * 0.5, UP, 1, 42, 0.42, CYAN)
				shockDisc(pos + UP * 0.7, UP, 1, 30, 0.36, GOLD)
				billboardRing(pos + UP * 3, 6, 72, WHITE, 12, 0.45)
				local column = newPart(Vector3.new(12, 6, 6), CFrame.new(pos + UP * 6) * CFrame.Angles(0, 0, math.rad(90)), WHITE, Enum.Material.Neon, Enum.PartType.Cylinder)
				column.Transparency = 0.3
				tween(column, 0.45, { Size = Vector3.new(70, 30, 30), CFrame = CFrame.new(pos + UP * 30) * CFrame.Angles(0, 0, math.rad(90)), Transparency = 1 })
				cleanup(column, 0.5)
				-- the street goes up
				rocks(pos, 2.4, 20)
				dustPuffs(pos, 2.4, 12, DUST, 1.6, true)
				groundMark(pos, 14, Color3.fromRGB(44, 40, 40), 6)
				sparks(pos + UP, 1.4, WHITE, GOLD, 40)
				streaks(pos + UP * 2, UP, 14, 0.9, 9, 30, WHITE, 0.3)
				for i = 1, 10 do
					local a = i / 10 * math.pi * 2
					local out = Vector3.new(math.cos(a), 0, math.sin(a))
					celPuff(folder, pos + out * 6 + UP, pos + out * rand(16, 24) + UP * rand(2, 8), rand(6, 10), DUST, Color3.new(1, 1, 1), 0.4, 1.4, i * 0.02)
				end
				for i = 1, 5 do
					celPuff(folder, pos + UP * 2, pos + UP * rand(18, 30) + Vector3.new(rand(-4, 4), 0, rand(-4, 4)), rand(8, 12), Color3.fromRGB(96, 88, 84), AMBER, 0.5, 1.6, 0.08 + i * 0.05)
				end
				for _ = 1, 8 do
					bolt(pos + UP * rand(1, 6) + Vector3.new(rand(-8, 8), 0, rand(-8, 8)), rand(3, 5), CYAN)
				end
				VFX.PlaySound("BigExplosion", pos, 1.2)
				VFX.PlaySound("USSImpact", pos, 1)
				if nearCamera(pos, 160) then
					VFX.ImpactFrame(0.14)
					VFX.Hooks.Flash(Color3.fromRGB(255, 246, 220), 0.25)
				end
				VFX.ShakeAt(pos, 3.2, 160, 0.55)
			end)
		end

		function Effects.FistRainCancel(char)
			local st = states[char]
			if st and st.cine then
				VFX.CancelCinematic()
			end
			clear(char, true)
		end
	end
	setupInfinite()
end


---------------------------------------------------------------------------
-- LIMITLESS
---------------------------------------------------------------------------

-- R: Infinity on (the shimmer itself is drawn by the aura loop)
do -- LIMITLESS: its helpers stay local to this block (Luau allows 200 locals per scope)
	function Effects.Infinity(char)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "HandSign", 0.5)
		billboardRing(root.Position, 2, 16, PAL.BLUE_CORE, 5, 0.35)
		shockDisc(root.Position, UP, 2, 14, 0.3, PAL.BLUE_CORE)
		VFX.PlaySound("InfinityOn", root.Position, 1)
	end

	-- Server: a hit slowed to nothing just short of him
	function Effects.InfinityStop(_, data)
		local target = data.Target
		local root = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or (root.Position + root.CFrame.LookVector * 5)
		local v = from - root.Position
		local d = v.Magnitude > 0.1 and v.Unit or root.CFrame.LookVector
		local at = root.Position + d * 3
		local disc = newPart(Vector3.new(0.3, 1, 1), CFrame.lookAt(at, at + d) * CFrame.Angles(0, math.pi / 2, 0), PAL.BLUE_CORE, Enum.Material.ForceField, Enum.PartType.Cylinder)
		tween(disc, 0.25, { Size = Vector3.new(0.3, 7, 7), Transparency = 1 })
		cleanup(disc, 0.3)
		billboardRing(at, 0.5, 5, PAL.BLUE_CORE, 3, 0.25)
		VFX.PlaySound("InfinityStop", at, 0.8)
	end

	-- the orb helper: a glowing core inside a see-through shell, with a light
	local function orb(pos, size, core, glow)
		local model = Instance.new("Model")
		model.Name = "Orb"
		model.Parent = folder
		local inner = newPart(Vector3.one * 0.2, CFrame.new(pos), core, Enum.Material.Neon, Enum.PartType.Ball, model)
		local outer = newPart(Vector3.one * 0.2, CFrame.new(pos), glow, Enum.Material.ForceField, Enum.PartType.Ball, model)
		tween(inner, 0.15, { Size = Vector3.one * size * 0.55 })
		tween(outer, 0.15, { Size = Vector3.one * size * 1.3 })
		local light = Instance.new("PointLight")
		light.Color = glow
		light.Range = size * 5
		light.Brightness = 3
		light.Parent = inner
		return model, inner, outer
	end

	-- Blue: an attraction point. Rubble, dust and wind stream INTO it.
	local function blueEffect(char, data, isLocal, ability, lift, windup, big)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "Point")
		local center = aimGround(root, data, (ability and ability.Range) or 70) + UP * lift
		local radius = (ability and ability.Radius) or 24
		local duration = (ability and ability.Duration) or 1.8
		task.wait(windup)
		if not root.Parent then
			return
		end
		local model, inner, outer = orb(center, big and 7 or 4.5, PAL.BLUE_CORE, PAL.BLUE_GLOW)
		VFX.PlaySound("Blue", center, big and 1.3 or 1)
		local g = groundPoint(center)
		local t0 = os.clock()
		while os.clock() - t0 < duration do
			local t = os.clock() - t0
			inner.CFrame = CFrame.new(center) * CFrame.Angles(t * 3, t * 5, 0)
			outer.CFrame = CFrame.new(center) * CFrame.Angles(0, -t * 4, t * 2)
			-- rings and wind collapsing inward
			billboardRing(center, radius * 1.4, 1, PAL.BLUE_GLOW, 5, 0.3)
			for _ = 1, big and 4 or 2 do
				local p = center + rng:NextUnitVector() * radius * rand(0.6, 1)
				local s = newPart(Vector3.new(0.2, 0.2, rand(3, 6)), CFrame.lookAt(p, center), PAL.BLUE_CORE, Enum.Material.Neon)
				tween(s, 0.22, { CFrame = CFrame.lookAt(center, center + (center - p)), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(s, 0.25)
			end
			-- chunks of the street pulled up into it
			if rng:NextNumber() < (big and 0.7 or 0.4) then
				local from = g + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * radius
				local chunk = newPart(Vector3.new(rand(0.8, 2), rand(0.6, 1.4), rand(0.8, 2)), CFrame.new(from) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), Color3.fromRGB(120, 112, 108), Enum.Material.Slate)
				tween(chunk, 0.45, { CFrame = CFrame.new(center) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), Size = chunk.Size * 0.3 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(chunk, 0.5)
			end
			task.wait(0.08)
		end
		-- the point collapses
		tween(inner, 0.12, { Size = Vector3.one * 0.1 })
		tween(outer, 0.12, { Size = Vector3.one * 0.1, Transparency = 1 })
		cleanup(model, 0.2)
		shockDisc(center, UP, 2, big and 30 or 18, 0.3, PAL.BLUE_CORE)
		billboardRing(center, 1, big and 28 or 16, PAL.BLUE_GLOW, 6, 0.25)
		VFX.ShakeAt(center, big and 2.5 or 1.4, 90, 0.3)
	end

	function Effects.LapseBlue(char, data, isLocal, ability)
		blueEffect(char, data, isLocal, ability, 6, 0.25, false)
	end

	function Effects.BlueMax(char, data, isLocal, ability)
		blueEffect(char, data, isLocal, ability, 10, 0.35, true)
	end

	-- Red: charged at the fingertip, flicked forward, bursts on contact
	local redShots = setmetatable({}, { __mode = "k" }) -- [character] = the orb in flight
	local function redEffect(char, data, isLocal, ability, windup, speed, big)
		local root = charParts(char)
		if not root then
			return
		end
		local d = aimDir(data, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "Point")
		local t0 = os.clock()
		VFX.PlaySound("RedCharge", root.Position, 1)
		local model, inner, outer = orb(handPos(char, true) + d, big and 2.4 or 1.6, PAL.RED_CORE, PAL.RED_GLOW)
		while os.clock() - t0 < windup and root.Parent do
			local p = handPos(char, true) + d * 1.2
			inner.CFrame = CFrame.new(p)
			outer.CFrame = CFrame.new(p)
			if rng:NextNumber() < 0.5 then
				billboardRing(p, 0.5, big and 6 or 4, PAL.RED_GLOW, 3, 0.15)
			end
			task.wait(1 / 60)
		end
		if not root.Parent then
			model:Destroy()
			return
		end
		local from = handPos(char, true) + d * 1.2
		local length = (ability and ability.Range) or 80
		local hit = firstHit(from, d, length)
		local to = hit or (from + d * length)
		local travel = (to - from).Magnitude / speed
		redShots[char] = model
		local stopTrail = addTrail(inner, PAL.RED_GLOW, 0.2, big and 2 or 1.3)
		tween(inner, travel, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Linear)
		tween(outer, travel, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Linear)
		streaks(from, d, 8, 0.6, 6, math.min(40, (to - from).Magnitude), PAL.RED_GLOW, 0.25)
		task.delay(travel + 0.6, function()
			stopTrail()
			if model.Parent then
				model:Destroy()
			end
		end)
	end

	function Effects.ReversalRed(char, data, isLocal, ability)
		redEffect(char, data, isLocal, ability, 0.3, 260, false)
	end

	function Effects.RedMax(char, data, isLocal, ability)
		redEffect(char, data, isLocal, ability, 0.45, 220, true)
	end

	-- Server: where Red burst (everyone blows away from here)
	function Effects.RedBurst(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local shot = char and redShots[char]
		if shot then
			redShots[char] = nil
			shot:Destroy()
		end
		local radius = data.Radius or 20
		local big = radius >= 30
		local ball = newPart(Vector3.one * 2, CFrame.new(pos), PAL.RED_CORE, Enum.Material.Neon, Enum.PartType.Ball)
		tween(ball, 0.1, { Size = Vector3.one * radius * 1.1 })
		tween(ball, 0.3, { Size = Vector3.one * radius * 1.4, Transparency = 1, Color = PAL.RED_GLOW }, nil, nil, 0.1)
		cleanup(ball, 0.45)
		for i = 1, 3 do
			task.delay(i * 0.04, function()
				shockDisc(pos, UP, 4, radius * 3, 0.4, i == 2 and PAL.RED_GLOW or Color3.new(1, 1, 1))
			end)
		end
		billboardRing(pos, 3, radius * 2.6, PAL.RED_GLOW, 10, 0.35)
		for _ = 1, big and 36 or 22 do
			local dir = rng:NextUnitVector()
			streaks(pos + dir * 2, dir, 1, 0, rand(4, 8), radius * 2, PAL.RED_CORE, 0.35)
		end
		dustPuffs(groundPoint(pos), radius / 12, 10, Color3.fromRGB(206, 196, 186), 1.2, true)
		rocks(pos, radius / 12, big and 14 or 8)
		if big then
			VFX.ImpactFrame(0.1)
		end
		if nearCamera(pos, radius * 3) then
			VFX.Hooks.Flash(PAL.RED_CORE, 0.2)
		end
		VFX.PlaySound("Red", pos, big and 1.3 or 1)
		VFX.ShakeAt(pos, big and 3.5 or 2.2, radius * 6, 0.45)
	end

	-- Hollow Purple: Blue (left) + Red (right) = imaginary mass, erasing a line
	local function purpleEffect(char, data, isLocal, ability, key, windup, speed)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.55, windup)
		end
		cinematicFor(char, key, isLocal, (ability and ability.Name) or "HOLLOW PURPLE", PAL.PURPLE_GLOW)
		VFX.Motion(char, "Purple")
		VFX.PlaySound("PurpleCharge", root.Position, 1)
		local radius = (ability and ability.Radius) or 10
		local blueModel, blueIn, blueOut = orb(handPos(char, false), 2, PAL.BLUE_CORE, PAL.BLUE_GLOW)
		local redModel, redIn, redOut
		local t0 = os.clock()
		local mergeAt = windup * 0.62
		local mergePoint
		while os.clock() - t0 < windup and root.Parent do
			local t = os.clock() - t0
			local left, right = handPos(char, false), handPos(char, true)
			if t > windup * 0.3 and not redModel then
				redModel, redIn, redOut = orb(right, 2, PAL.RED_CORE, PAL.RED_GLOW)
			end
			if t < mergeAt then
				blueIn.CFrame, blueOut.CFrame = CFrame.new(left), CFrame.new(left)
				if redModel then
					redIn.CFrame, redOut.CFrame = CFrame.new(right), CFrame.new(right)
				end
			else
				-- the two collide in front of him and become one
				mergePoint = mergePoint or (root.Position + d * 3 + UP * 1.5)
				local k = math.clamp((t - mergeAt) / 0.15, 0, 1)
				blueIn.CFrame = CFrame.new(left:Lerp(mergePoint, k))
				blueOut.CFrame = blueIn.CFrame
				if redModel then
					redIn.CFrame = CFrame.new(right:Lerp(mergePoint, k))
					redOut.CFrame = redIn.CFrame
				end
			end
			if rng:NextNumber() < 0.3 then
				bolt(root.Position + UP, 3, PAL.PURPLE_GLOW)
			end
			task.wait(1 / 60)
		end
		blueModel:Destroy()
		if redModel then
			redModel:Destroy()
		end
		if not root.Parent then
			return
		end
		local length = (ability and ability.Range) or 220
		local origin = root.Position + UP * 2 + d * 3
		local finish = origin + d * length
		local travel = length / speed
		VFX.ImpactFrame(0.12)
		if nearCamera(origin, 120) then
			VFX.Hooks.Flash(PAL.PURPLE_CORE, 0.3)
		end
		VFX.PlaySound("Purple", origin, 1.3)
		VFX.ShakeAt(origin, 4, 240, 0.8)
		local model, inner, outer = orb(origin, radius * 2, PAL.PURPLE_CORE, PAL.PURPLE_GLOW)
		tween(inner, 0.2, { Size = Vector3.one * radius * 1.2 })
		tween(outer, 0.2, { Size = Vector3.one * radius * 2.2 })
		tween(inner, travel, { CFrame = CFrame.new(finish) }, Enum.EasingStyle.Linear, nil, 0.05)
		tween(outer, travel, { CFrame = CFrame.new(finish) }, Enum.EasingStyle.Linear, nil, 0.05)
		local stopTrail = addTrail(inner, PAL.PURPLE_GLOW, 0.5, radius * 1.4)
		local s0 = os.clock()
		while os.clock() - s0 < travel + 0.05 do
			local p = inner.Position
			bolt(p, radius, PAL.PURPLE_GLOW)
			bolt(p, radius * 0.8, PAL.PURPLE_CORE)
			streaks(p, d, 3, radius * 0.6, 8, 20, PAL.PURPLE_CORE, 0.3)
			groundMark(p, radius * 0.9, Color3.fromRGB(46, 24, 70), 8)
			task.wait(0.06)
		end
		stopTrail()
		tween(inner, 0.2, { Size = Vector3.one * 0.1 })
		tween(outer, 0.2, { Size = Vector3.one * 0.1, Transparency = 1 })
		cleanup(model, 0.25)
		billboardRing(finish, radius, radius * 4, PAL.PURPLE_GLOW, 10, 0.4)
	end

	function Effects.HollowPurple(char, data, isLocal, ability)
		purpleEffect(char, data, isLocal, ability, "HollowPurple", 1.25, 170)
	end

	function Effects.PurpleMax(char, data, isLocal, ability)
		purpleEffect(char, data, isLocal, ability, "PurpleMax", 1.7, 210)
	end

	-- V: step through space to the aim point
	local function blinkDestination(root, from, data, range)
		local aim = typeof(data.Pos) == "Vector3" and data.Pos or (from + root.CFrame.LookVector * range)
		local flat = Vector3.new(aim.X - from.X, 0, aim.Z - from.Z)
		if flat.Magnitude < 1 then
			flat = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
		end
		local dist = math.min(flat.Magnitude, range)
		local d = flat.Unit
		local wall = firstHit(from, d, dist + 3)
		if wall then
			dist = math.max(0, (wall - from).Magnitude - 3)
		end
		return from + d * dist, d
	end

	function Effects.Blink(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local range = (ability and ability.Range) or 45
		local from = typeof(data.Origin) == "Vector3" and data.Origin or root.Position
		local dest, d = blinkDestination(root, from, data, range)
		VFX.Pose(char, "BlinkSign", 0.3)
		afterimage(char, PAL.BLUE_CORE, 0.35)
		billboardRing(from, 3, 1, PAL.BLUE_GLOW, 5, 0.2)
		if isLocal then
			root.CFrame = CFrame.lookAt(dest, dest + d)
			root.AssemblyLinearVelocity = Vector3.zero
		end
		billboardRing(dest, 1, 8, PAL.BLUE_CORE, 5, 0.25)
		shockDisc(dest, UP, 1, 8, 0.2, PAL.BLUE_CORE)
		VFX.PlaySound("Blink", dest, 1)
	end

	-- Server: Domain Expansion. A dome of void closes over the arena: black
	-- panels (they read from inside too), stars, and streams of information.
	function Effects.Domain(char, data)
		local center = typeof(data.Pos) == "Vector3" and data.Pos
		if not center then
			return
		end
		local radius = data.Radius or 60
		local duration = data.Duration or 25
		local g = groundPoint(center)
		local old = char and activeDomains[char]
		if old and old.Model.Parent then
			old.Model:Destroy()
		end
		local model = Instance.new("Model")
		model.Name = "UnlimitedVoid"
		model.Parent = folder
		local LON, LAT = 14, 6
		for i = 0, LON - 1 do
			for j = 0, LAT - 1 do
				local lon = (i + 0.5) / LON * math.pi * 2
				local lat = (j + 0.5) / LAT * (math.pi / 2)
				local dir = Vector3.new(math.cos(lat) * math.cos(lon), math.sin(lat), math.cos(lat) * math.sin(lon))
				local w = 2 * math.pi * radius * math.cos(lat) / LON * 1.18 + 1
				local h = (math.pi / 2) * radius / LAT * 1.18 + 1
				local p = newPart(Vector3.new(1, 1, 0.6), CFrame.lookAt(g + dir * 2, g), PAL.VOID_DARK, Enum.Material.SmoothPlastic, nil, model)
				p.Transparency = 0.05
				tween(p, 0.9, { CFrame = CFrame.lookAt(g + dir * radius, g), Size = Vector3.new(w, h, 0.6) }, Enum.EasingStyle.Quart, nil, (j / LAT) * 0.15)
			end
		end
		local cap = newPart(Vector3.new(0.6, 2, 2), CFrame.new(g + UP * 2) * CFrame.Angles(0, 0, math.pi / 2), PAL.VOID_DARK, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder, model)
		tween(cap, 0.9, { CFrame = CFrame.new(g + UP * radius * 0.99) * CFrame.Angles(0, 0, math.pi / 2), Size = Vector3.new(0.6, radius * 0.5, radius * 0.5) }, Enum.EasingStyle.Quart, nil, 0.15)
		-- the rim where the void meets the street
		local rim = newPart(Vector3.new(0.4, 2, 2), CFrame.new(g + UP * 0.1) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(190, 170, 255), Enum.Material.Neon, Enum.PartType.Cylinder, model)
		rim.Transparency = 0.4
		tween(rim, 0.9, { Size = Vector3.new(0.4, radius * 2, radius * 2) }, Enum.EasingStyle.Quart)
		-- stars
		for k = 1, 150 do
			local dir = rng:NextUnitVector()
			dir = Vector3.new(dir.X, math.abs(dir.Y), dir.Z)
			local star = newPart(Vector3.one * rand(0.25, 0.9), CFrame.new(g + UP * 2), k % 5 == 0 and Color3.fromRGB(170, 190, 255) or Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball, model)
			tween(star, rand(0.6, 1.2), { CFrame = CFrame.new(g + dir * radius * rand(0.5, 0.96)) }, Enum.EasingStyle.Quart)
		end
		-- nebula
		for k = 1, 5 do
			local dir = rng:NextUnitVector()
			dir = Vector3.new(dir.X, math.abs(dir.Y) * 0.6 + 0.2, dir.Z).Unit
			local neb = newPart(Vector3.one, CFrame.new(g + dir * radius * 0.6), k % 2 == 0 and PAL.PURPLE_GLOW or PAL.BLUE_GLOW, Enum.Material.ForceField, Enum.PartType.Ball, model)
			tween(neb, 1.2, { Size = Vector3.one * radius * rand(0.35, 0.6) })
		end
		activeDomains[char or model] = { Center = g, Radius = radius, Model = model }
		VFX.PlaySound("Domain", g, 1.2)
		if nearCamera(g, radius) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.35)
		end
		-- streams of information shooting across the inside
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < duration and model.Parent do
				local a = g + rng:NextUnitVector() * radius * 0.8
				local b = g + rng:NextUnitVector() * radius * 0.8
				a = Vector3.new(a.X, math.max(a.Y, g.Y + 2), a.Z)
				b = Vector3.new(b.X, math.max(b.Y, g.Y + 2), b.Z)
				local seg = newPart(Vector3.new(0.12, 0.12, 6), CFrame.lookAt(a, b), rng:NextNumber() < 0.5 and Color3.new(1, 1, 1) or Color3.fromRGB(170, 190, 255), Enum.Material.Neon, nil, model)
				tween(seg, 0.5, { CFrame = CFrame.lookAt(b, b + (b - a)), Transparency = 1 }, Enum.EasingStyle.Linear)
				cleanup(seg, 0.55)
				task.wait(0.06)
			end
		end)
		cleanup(model, duration + 3)
	end

	-- Server: the domain collapses
	function Effects.DomainEnd(char)
		local key = char
		local dom = key and activeDomains[key]
		if not dom then
			return
		end
		activeDomains[key] = nil
		local g = dom.Center
		for _, p in dom.Model:GetDescendants() do
			if p:IsA("BasePart") then
				tween(p, 0.5, { CFrame = CFrame.new(g + UP * 2), Size = Vector3.one * 0.2, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
		end
		task.delay(0.55, function()
			dom.Model:Destroy()
		end)
		shockDisc(g + UP, UP, 4, dom.Radius * 1.5, 0.5, Color3.new(1, 1, 1))
		VFX.PlaySound("InfinityStop", g, 1.2)
	end

	-- dashes + awakenings for the two new quirks
	QUIRK_FX.Dash.FullCowl = function(char, root, dir)
		legTrails(char, 0.25, COWL_GREEN)
		if cowlLevel(char) > 0 then
			afterimage(char, COWL_GREEN, 0.25)
			for _ = 1, 3 do
				bolt(root.Position - dir * 2, 2.5, COWL_GREEN)
			end
			shockDisc(root.Position - dir * 2, -dir, 2, 10, 0.2, COWL_CORE, 5)
		end
	end
	QUIRK_FX.Dash.Limitless = function(char, root, dir)
		afterimage(char, PAL.BLUE_CORE, 0.3)
		billboardRing(root.Position - dir * 2, 2, 7, PAL.BLUE_GLOW, 4, 0.2)
	end
	QUIRK_FX.Ult.FullCowl = function(_, root, g)
		-- 100%: the lightning goes everywhere and the ground splits under him
		cowlBurst(root.Position, 7, 0.9, 5)
		for i = 1, 5 do
			task.delay(i * 0.07, function()
				shockDisc(g + UP * (0.5 + i), UP, 6, 70, 0.5, i % 2 == 0 and COWL_GREEN or WIND)
			end)
		end
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			local dir = Vector3.new(math.cos(a), 0, math.sin(a))
			local from, to = g + dir * 2, g + dir * rand(14, 24)
			local seg = newPart(Vector3.new(0.4, 0.14, (to - from).Magnitude), CFrame.lookAt((from + to) / 2 + UP * 0.08, to + UP * 0.08), COWL_GREEN, Enum.Material.Neon)
			tween(seg, 1.2, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 1.5)
			cleanup(seg, 2.8)
		end
		billboardRing(root.Position, 4, 44, COWL_GREEN, 12, 0.45)
	end
	QUIRK_FX.Ult.Limitless = function(_, root, g)
		-- the hand sign; the domain itself is drawn when the server expands it
		billboardRing(root.Position + UP, 2, 30, PAL.BLUE_CORE, 8, 0.5)
		for i = 1, 3 do
			task.delay(i * 0.1, function()
				shockDisc(g + UP * i, UP, 4, 60, 0.6, i == 2 and PAL.PURPLE_GLOW or PAL.BLUE_CORE)
			end)
		end
	end

	-- Server: you were caught inside. Everything, all at once, forever.
	function Effects.VoidOverload(_, data)
		local duration = data.Duration or 4
		VFX.Hooks.Dim(0.6, duration)
		VFX.Hooks.Callout("INFINITE INFORMATION", Color3.fromRGB(190, 170, 255))
		for i = 1, 10 do
			task.delay(i * 0.11, function()
				VFX.Hooks.Flash(i % 2 == 0 and Color3.new(1, 1, 1) or Color3.fromRGB(20, 16, 40), 0.08)
			end)
		end
	end
end

---------------------------------------------------------------------------
-- OVERHAUL (Kai Chisaki). Whatever he touches cracks red, bursts apart and
-- snaps back together - or comes back as spikes and walls of stone.
---------------------------------------------------------------------------
local Overhaul = {}
do
	local RED = Color3.fromRGB(230, 36, 58)
	local RED_HOT = Color3.fromRGB(255, 140, 150)
	local STONE = { Color3.fromRGB(126, 116, 108), Color3.fromRGB(102, 95, 90), Color3.fromRGB(148, 138, 126) }
	local DUST = Color3.fromRGB(170, 160, 150)
	Overhaul.RED = RED

	POSES.OverhaulTouch = {
		RightArm = { 88, 0, -6 }, RightElbow = 10, LeftArm = { 15, 0, 12 }, LeftElbow = 60,
		Waist = { -10, 24, 0 }, Neck = { -4, -10, 0 }, RightLeg = -18, LeftLeg = 25, LeftKnee = 30,
	}
	-- a palm flat on the ground
	POSES.OverhaulGround = {
		RightArm = { 55, 0, -8 }, LeftArm = { 20, 0, 20 }, RightElbow = 10, LeftElbow = 40, Waist = { -38, 8, 0 }, Neck = { 18, 0, 0 },
		Hips = { 0, 0, 0, 0, -0.9, 0 }, RightLeg = 55, LeftLeg = -15, RightKnee = 90, LeftKnee = 70,
	}
	-- both hands to his own chest (Restore)
	POSES.OverhaulSelf = { RightArm = { 60, 0, -40 }, LeftArm = { 60, 0, -40 }, RightElbow = 100, LeftElbow = 100, Neck = { -18, 0, 0 }, Waist = { 6, 0, 0 } }
	-- pulling the glove off with his teeth... er, his other hand
	POSES.OverhaulGlove = { RightArm = { 70, 0, -30 }, RightElbow = 80, LeftArm = { 55, 0, -25 }, LeftElbow = 95, Neck = { -12, 10, 0 }, Waist = { 4, -10, 0 } }
	MOTIONS.OverhaulTouch = { mute = 0.4, { pose = "OverhaulTouch", t = 0.06, hold = 0.32 }, recover = 0.2 }
	MOTIONS.OverhaulSlam = { { pose = "OverhaulGround", t = 0.12, hold = 0.4 }, recover = 0.25 }
	MOTIONS.OverhaulGloves = { { pose = "OverhaulGlove", t = 0.15, hold = 0.4 }, { pose = "OverhaulGround", t = 0.15, hold = 1.2 }, recover = 0.3 }

	-- Red crackle crawling over a body: the first instant of Overhaul
	local function crackle(char, duration)
		local parts = {}
		for _, p in char:GetChildren() do
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" then
				table.insert(parts, p)
			end
		end
		if #parts == 0 then
			return
		end
		local hl = Instance.new("Highlight")
		hl.FillColor = RED
		hl.FillTransparency = 0.7
		hl.OutlineColor = RED_HOT
		hl.OutlineTransparency = 0
		hl.DepthMode = Enum.HighlightDepthMode.Occluded
		hl.Adornee = char
		hl.Parent = folder
		tween(hl, duration, { FillTransparency = 0.25 })
		cleanup(hl, duration + 0.05)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < duration and char.Parent do
				local p = parts[rng:NextInteger(1, #parts)]
				if p.Parent then
					bolt(p.Position, math.max(p.Size.Magnitude * 0.35, 0.8), rng:NextNumber() < 0.5 and RED or RED_HOT)
				end
				task.wait(0.03)
			end
		end)
	end
	Overhaul.crackle = crackle

	-- Disassembly: the body bursts into blocks that fly apart and snap back
	-- together (the body itself vanishes for that instant)
	local function burstApart(char, spread, hold)
		local center = char:FindFirstChild("HumanoidRootPart")
		if not center then
			return
		end
		spread = spread or 4
		hold = hold or 0.12
		hideCharacter(char, 0.16 + hold + 0.18)
		for _, p in char:GetChildren() do
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
				for _ = 1, math.clamp(math.floor(p.Size.Magnitude * 1.4), 3, 7) do
					local s = math.max(math.min(p.Size.X, p.Size.Y, p.Size.Z) * rand(0.35, 0.6), 0.25)
					local home = p.CFrame * CFrame.new(rand(-0.4, 0.4) * p.Size.X, rand(-0.4, 0.4) * p.Size.Y, rand(-0.4, 0.4) * p.Size.Z)
					local cube = newPart(Vector3.one * s, home, p.Color:Lerp(RED, rand(0.15, 0.5)), Enum.Material.SmoothPlastic)
					local out = home.Position - center.Position
					out = ((out.Magnitude > 0.1 and out.Unit or rng:NextUnitVector()) + rng:NextUnitVector() * 0.5).Unit
					tween(cube, 0.16, { CFrame = CFrame.new(home.Position + out * spread * rand(0.6, 1.2)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) })
					tween(cube, 0.18, { CFrame = home }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.16 + hold)
					cleanup(cube, 0.16 + hold + 0.2)
				end
			end
		end
	end
	Overhaul.burstApart = burstApart

	-- A jagged stone spike growing out of `base` along dir, with the red seam
	-- where it was put together. (round 75) Sharper: four faceted segments,
	-- each turned 45 degrees on the one below, narrowing to a needle point; a
	-- collar of broken street heaved up round its foot; the seam red-hot,
	-- then cooling. Returns a grower for growSpikes.
	local SEGS = { { from = 0, len = 0.5, thick = 1 }, { from = 0.42, len = 0.32, thick = 0.66 }, { from = 0.68, len = 0.22, thick = 0.38 }, { from = 0.86, len = 0.16, thick = 0.14 } }
	local function stoneSpike(model, base, dir, length, thick)
		local up = dir.Unit
		local ref = math.abs(up.Y) < 0.95 and UP or Vector3.new(1, 0, 0)
		local right = ref:Cross(up).Unit
		local rot = CFrame.fromMatrix(Vector3.zero, right, up) * CFrame.Angles(0, rand(0, math.pi), 0)
		local parts, rots = {}, {}
		for i in SEGS do
			rots[i] = rot * CFrame.Angles(rand(-0.06, 0.06), math.rad(45) * i, rand(-0.06, 0.06))
			parts[i] = newPart(Vector3.new(0.1, 0.05, 0.1), CFrame.new(base) * rots[i], STONE[rng:NextInteger(1, 3)], Enum.Material.Slate, nil, model)
		end
		local seam = newPart(Vector3.new(0.1, 0.05, 0.1), CFrame.new(base) * rot, RED_HOT, Enum.Material.Neon, nil, model)
		seam.Transparency = 0.1
		tween(seam, 0.35, { Color = RED }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, 0.15)
		tween(seam, 0.8, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.6)
		-- the street it broke through, heaved up round its foot
		local fwd = up:Cross(right)
		local chunks = {}
		for k = 1, 2 do
			local a = k * math.pi + rand(-0.6, 0.6)
			local c = newPart(Vector3.one * 0.05, CFrame.new(base + (right * math.cos(a) + fwd * math.sin(a)) * thick * 0.75) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), STONE[rng:NextInteger(1, 3)], Enum.Material.Slate, nil, model)
			chunks[k] = { part = c, size = Vector3.new(rand(0.5, 0.9), rand(0.3, 0.6), rand(0.5, 0.9)) * thick }
		end
		local sparked = false
		return function(alpha)
			for i, seg in SEGS do
				local l = math.max(length * seg.len * alpha, 0.05)
				parts[i].Size = Vector3.new(thick * seg.thick, l, thick * seg.thick)
				parts[i].CFrame = CFrame.new(base + up * (length * seg.from * alpha + l / 2)) * rots[i]
			end
			local l1 = math.max(length * 0.6 * alpha, 0.05)
			seam.Size = Vector3.new(thick * 0.08, l1, thick * 1.04)
			seam.CFrame = CFrame.new(base + up * (l1 / 2)) * rot
			local k = math.min(alpha * 3, 1)
			for _, c in chunks do
				c.part.Size = c.size * math.max(k, 0.05)
			end
			if not sparked and alpha > 0.05 then
				sparked = true
				if rng:NextNumber() < 0.25 then
					sparks(base, 0.35, RED_HOT, RED, 3)
				end
			end
		end
	end
	Overhaul.stoneSpike = stoneSpike

	-- A slab of stone folding up out of the street (a prison wall)
	local function stoneWall(model, base, out, height, width, thick)
		local cf0 = CFrame.lookAt(base, base + out)
		local slab = newPart(Vector3.new(width, 0.1, thick), cf0, STONE[rng:NextInteger(1, 3)], Enum.Material.Slate, nil, model)
		local seam = newPart(Vector3.new(width, 0.1, thick), cf0, RED, Enum.Material.Neon, nil, model)
		tween(seam, 0.9, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.4)
		return function(alpha)
			local h = math.max(height * alpha, 0.1)
			slab.Size = Vector3.new(width, h, thick)
			slab.CFrame = cf0 * CFrame.new(0, h / 2, 0)
			seam.Size = Vector3.new(width * 1.01, 0.3, thick * 1.04)
			seam.CFrame = cf0 * CFrame.new(0, h * 0.55, 0)
		end
	end

	-- A red crack racing along the ground from a to b: jagged, glowing, fading
	local function groundCrack(a, b, width, life)
		local span = b - a
		local dist = span.Magnitude
		if dist < 1 then
			return
		end
		local side = span:Cross(UP)
		side = side.Magnitude > 0.01 and side.Unit or Vector3.new(1, 0, 0)
		local n = math.clamp(math.floor(dist / 4), 2, 24)
		local prev = a
		for i = 1, n do
			local k = i / n
			local p = groundPoint(a + span * k + side * (i < n and rand(-1, 1) * width * 2.5 or 0) + UP * 3)
			local from, to = prev, p
			task.delay(k * math.min(dist / 120, 0.5), function()
				local len = (to - from).Magnitude
				if len < 0.05 then
					return
				end
				local seg = newPart(Vector3.new(width, 0.12, len + width), CFrame.lookAt((from + to) / 2 + UP * 0.08, to + UP * 0.08), RED, Enum.Material.Neon)
				tween(seg, 0.5, { Transparency = 1, Size = Vector3.new(width * 0.3, 0.1, len) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, life)
				cleanup(seg, life + 0.55)
			end)
			prev = p
		end
	end
	Overhaul.groundCrack = groundCrack

	-- Take a spike model apart again: chunks tumble off and the rest fades
	local function crumble(model, delayTime)
		task.delay(delayTime or 0, function()
			if not model.Parent then
				return
			end
			local count = 0
			local center
			for _, p in model:GetDescendants() do
				if p:IsA("BasePart") then
					center = center or p.Position
					if count < 24 and p.Size.Magnitude > 2 then
						count += 1
						local s = math.clamp(p.Size.X * rand(0.3, 0.6), 0.5, 3)
						local chunk = Instance.new("Part")
						chunk.Size = Vector3.new(s, s * rand(0.7, 1.4), s * rand(0.6, 1))
						chunk.Color = p.Color
						chunk.Material = Enum.Material.Slate
						chunk.CanQuery = false
						chunk.CanTouch = false
						chunk.CastShadow = false
						chunk.CFrame = p.CFrame * CFrame.new(0, rand(-0.4, 0.4) * p.Size.Y, 0) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6))
						chunk.Parent = folder
						chunk.AssemblyLinearVelocity = rng:NextUnitVector() * rand(5, 14) + UP * 8
						tween(chunk, 0.5, { Size = Vector3.one * 0.05, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.9)
						cleanup(chunk, 1.5)
					end
					tween(p, 0.35, { Transparency = 1, Size = p.Size * 0.6 })
				end
			end
			if center then
				dustPuffs(center, 1.4, 5, DUST, 1, false)
				VFX.PlaySound("Crumble", center, 0.6)
			end
			cleanup(model, 0.4)
		end)
	end
	Overhaul.crumble = crumble

	local function newModel(name)
		local m = Instance.new("Model")
		m.Name = name
		m.Parent = folder
		return m
	end
	Overhaul.newModel = newModel

	-- Lunge with a bare hand
	function Effects.Disassemble(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			dash(root, d * 95, 0.35)
		end
		VFX.Motion(char, "OverhaulTouch")
		local hand = limb(char, "RightHand", "Right Arm")
		local stopTrail = hand and addTrail(hand, RED, 0.2, 1)
		afterimage(char, Color3.fromRGB(150, 40, 56), 0.25)
		VFX.PlaySound("Dash", root.Position, 0.7)
		local t0 = os.clock()
		while os.clock() - t0 < 0.35 and root.Parent do
			bolt(handPos(char, true), 1.2, RED)
			task.wait(0.05)
		end
		if stopTrail then
			stopTrail(0)
		end
	end

	-- Server: the touch landed. They crack red, come apart... and snap back
	function Effects.Disassembled(_, data)
		local target = data.Target
		local root = target and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		crackle(target, 0.35)
		VFX.PlaySound("Disassemble", root.Position, 1)
		task.wait(0.35)
		if not target.Parent then
			return
		end
		burstApart(target, 4.5, 0.1)
		billboardRing(root.Position, 2, 14, RED, 5, 0.3)
		sparks(root.Position, 1, RED_HOT, RED, 25)
		VFX.Hitstop(target, 0.08)
		task.wait(0.28)
		VFX.PlaySound("Reassemble", root.Position, 0.8)
	end

	-- Palm on the ground: the crack races ahead and the street erupts into spikes
	-- PILLAR RISE (V): the street under him is rebuilt as a pillar that throws
	-- him up, spikes bursting out round its foot
	function Effects.PillarRise(char, _data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local base = groundPoint(root.Position)
		local model = outlineModel(Color3.fromRGB(40, 20, 20))
		local list = { { set = stoneSpike(model, base - UP * 2, UP, 24, 6), delay = 0 } }
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			table.insert(list, { set = stoneSpike(model, base + out * rand(4, 8) - UP, (UP + out * 0.8).Unit, rand(5, 9), 1.8), delay = 0.05 })
		end
		growSpikes(list, 0.18)
		VFX.Pose(char, "ArmsUp", 0.5)
		VFX.PlaySound("SpikeErupt", base, 1)
		dustPuffs(base, 1.2, 8, Color3.fromRGB(150, 140, 130), 1, true)
		VFX.ShakeAt(base, 1.6, 70, 0.3)
		if isLocal and hum then
			launch(root, hum, UP * (ability.Lift or 95))
		end
		cleanup(model, 4)
	end

	-- SPIKE FAN: three cracks race out from his palm in a fan and the street
	-- erupts into three short lines of spikes
	-- (round 75) red cracks spidering across a wall face from `at`
	function Overhaul.wallCracks(at, normal, count)
		local wr = normal:Cross(UP)
		wr = wr.Magnitude > 0.05 and wr.Unit or Vector3.new(1, 0, 0)
		for k = 1, count do
			local a = k / count * math.pi * 2 + rand(-0.3, 0.3)
			local dir = wr * math.cos(a) + UP * math.sin(a)
			local len = rand(2.5, 5.5)
			local from = at + normal * 0.08
			local seg = newPart(Vector3.new(0.3, 0.3, len), CFrame.lookAt(from + dir * len / 2, from + dir * len), RED, Enum.Material.Neon)
			tween(seg, 0.6, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.5)
			cleanup(seg, 1.2)
		end
		return wr
	end
	-- the lane's run into a wall: its spikes burst back out of the wall
	function Overhaul.wallBurst(model, list, hit, delay)
		local n = hit.Normal
		local wr = n:Cross(UP)
		wr = wr.Magnitude > 0.05 and wr.Unit or Vector3.new(1, 0, 0)
		for k = 1, 5 do
			local base = hit.Position + wr * rand(-3, 3) + UP * rand(-2.5, 4)
			local dirS = (n * 1.4 + wr * rand(-0.5, 0.5) + UP * rand(-0.1, 0.5)).Unit
			table.insert(list, { set = stoneSpike(model, base - n * 0.6, dirS, rand(6, 11), rand(1.3, 2.1)), delay = delay + k * 0.012 })
		end
		task.delay(delay, function()
			Overhaul.wallCracks(hit.Position, n, 7)
			rocks(hit.Position + n, 0.9, 5)
			dustPuffs(hit.Position + n, 1, 4, DUST, 0.9, false)
			sparks(hit.Position + n * 0.5, 0.8, RED_HOT, RED, 12)
			VFX.PlaySound("Crumble", hit.Position, 0.8)
		end)
	end

	-- SPIKE FAN: the palm slams down and three lines of spikes fan out. (round
	-- 75) A lane that runs into a building bursts out of its wall; one that
	-- runs off a roof jets out of the side of the building below the lip,
	-- longer and longer, reaching out over the drop along the line
	function Effects.SpikeRush(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "OverhaulSlam")
		local origin = typeof(data.Origin) == "Vector3" and data.Origin or root.Position
		crackle(char, 0.25)
		task.wait(0.25)
		if not root.Parent then
			return
		end
		local range = ability.Range or 40
		local lanes = ability.Lanes or 3
		local spread = math.rad(ability.Spread or 26)
		local start = groundPoint(origin + d * 3)
		local model = newModel("SpikeRush")
		local list = {}
		-- the palm: a red ring across the street
		shockDisc(start + UP * 0.3, UP, 2, 14, 0.3, RED)
		sparks(start + UP * 0.5, 0.8, RED_HOT, RED, 10)
		for i = 1, lanes do
			local a = (i - (lanes + 1) / 2) * spread
			local c, sn = math.cos(a), math.sin(a)
			local ld = Vector3.new(d.X * c - d.Z * sn, 0, d.X * sn + d.Z * c).Unit
			local right = ld:Cross(UP)
			rayParams.FilterDescendantsInstances = characterList()
			local wall = workspace:Raycast(start + UP * 3, ld * range, rayParams)
			if wall and math.abs(wall.Normal.Y) >= 0.6 then
				wall = nil
			end
			local stop = wall and (wall.Position - (start + UP * 3)).Magnitude
			local side -- (off a roof: the side of the building it went over)
			local lastGround = start -- (the crack runs as far as there's street - or roof - under it)
			local step = 0
			for dist = 0, range, 5 do
				local delay = step * 0.03
				if stop and dist > stop then
					Overhaul.wallBurst(model, list, wall, delay)
					break
				end
				local here = start + ld * dist
				rayParams.FilterDescendantsInstances = characterList()
				local below = workspace:Raycast(here + UP * 3, Vector3.new(0, -12, 0), rayParams)
				if below then
					-- the street (or the roof): up out of it
					local p = below.Position
					lastGround = p
					for _ = 1, 2 do
						local dirS = (UP * 1.6 + ld * rand(0.2, 0.7) + right * rand(-0.3, 0.3)).Unit
						local size = 0.75 + dist / range * 0.45
						table.insert(list, { set = stoneSpike(model, p + right * rand(-2.2, 2.2) - ld * rand(0, 2) - UP * 0.8, dirS, rand(6, 10) * size, rand(1.3, 2.2) * size), delay = delay })
					end
					if step % 3 == 0 then
						task.delay(delay, function()
							dustPuffs(p, 0.9, 2, DUST, 0.8, false)
							bolt(p + UP * 0.6, 1.4, RED)
						end)
					end
				else
					-- over the edge: out of the side of the building
					if side == nil then
						local probe = workspace:Raycast(here - UP * 2.5, -ld * (dist + 2), rayParams)
						side = probe and math.abs(probe.Normal.Y) < 0.6 and probe or false
						if side then
							local at = side.Position
							task.delay(delay, function()
								Overhaul.wallCracks(at, side.Normal, 6)
								sparks(at, 0.8, RED_HOT, RED, 10)
							end)
						end
					end
					if side then
						for _ = 1, 2 do
							local base = side.Position + right * rand(-2.2, 2.2) - UP * rand(0.5, 5)
							local reach = here + UP * rand(0.5, 3.5) + right * rand(-1.5, 1.5)
							local span = reach - base
							if span.Magnitude > 1 then
								table.insert(list, { set = stoneSpike(model, base - side.Normal * 0.6, span.Unit, span.Magnitude + 2, rand(1.4, 2.2) * (0.8 + span.Magnitude / range * 0.6)), delay = delay })
							end
						end
						if step % 2 == 0 then
							local at = side.Position - UP * 3
							task.delay(delay, function()
								rocks(at + side.Normal, 0.6, 2)
								dustPuffs(at + side.Normal, 0.8, 2, DUST, 0.8, false)
							end)
						end
					else
						-- nothing to come out of: up from whatever's far below, as tall as it takes
						local p = groundPoint(here)
						for _ = 1, 2 do
							local dirS = (UP * 1.6 + ld * rand(0.2, 0.7) + right * rand(-0.3, 0.3)).Unit
							table.insert(list, { set = stoneSpike(model, p + right * rand(-2.2, 2.2) - UP * 0.8, dirS, math.clamp(here.Y - p.Y + 4, 6, 30), rand(1.6, 2.4)), delay = delay })
						end
					end
				end
				step += 1
			end
			groundCrack(groundPoint(origin), lastGround, 0.4, 1.1)
		end
		growSpikes(list, 0.12)
		VFX.PlaySound("SpikeErupt", start + d * range * 0.3, 1)
		VFX.ShakeAt(start + d * range * 0.5, 1.6, 110, 0.45)
		crumble(model, 2.4)
	end

	-- The ground around the aim folds up into walls, then spikes stab inward
	function Effects.SpikePrison(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "OverhaulSlam")
		local center = aimGround(root, data, (ability and ability.Range) or 60)
		local radius = (ability and ability.Radius) or 12
		groundCrack(groundPoint(root.Position), center, 0.4, 0.9)
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			groundCrack(center, center + Vector3.new(math.cos(a), 0, math.sin(a)) * radius * 1.1, 0.35, 0.9)
		end
		task.wait(0.3)
		if not root.Parent then
			return
		end
		local model = newModel("SpikePrison")
		local walls = {}
		local width = radius * 2 * math.sin(math.pi / 12) + 1.5
		for i = 1, 12 do
			local a = i / 12 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			table.insert(walls, { set = stoneWall(model, groundPoint(center + out * radius) - UP, out, rand(9, 11), width, 2.2), delay = i * 0.01 })
		end
		growSpikes(walls, 0.18)
		dustPuffs(center, 2, 8, DUST, 1.2, false)
		VFX.PlaySound("SpikeErupt", center, 1.2)
		VFX.ShakeAt(center, 1.4, 100, 0.4)
		task.wait(0.6)
		local spikes = {}
		for i = 1, 14 do
			local a = (i + 0.5) / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local base = groundPoint(center + out * (radius - 1)) + UP * rand(1, 5)
			table.insert(spikes, { set = stoneSpike(model, base, (-out + UP * rand(0.1, 0.5)).Unit, radius * rand(0.8, 1.05), rand(1.2, 2)), delay = rand(0, 0.06) })
		end
		growSpikes(spikes, 0.1)
		sparks(center + UP * 3, 1.4, RED_HOT, RED, 30)
		VFX.PlaySound("Disassemble", center, 1)
		crumble(model, 1.8)
	end

	-- R: he takes himself apart and rebuilds his body whole
	function Effects.Restore(char, _, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "OverhaulSelf", 0.7)
		crackle(char, 0.35)
		VFX.PlaySound("Restore", root.Position, 1)
		task.wait(0.35)
		if not char.Parent then
			return
		end
		burstApart(char, 3.5, 0.08)
		billboardRing(root.Position, 2, 12, RED, 5, 0.3)
		task.wait(0.3)
		shockDisc(root.Position, UP, 2, 14, 0.3, RED_HOT)
		sparks(root.Position, 0.8, Color3.fromRGB(255, 240, 240), RED_HOT, 20)
		if isLocal then
			VFX.Hooks.Callout("RESTORED", RED_HOT)
		end
	end

	-- Fused: pillars of stone burst out of the ground one after another
	function Effects.PillarBarrage(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "OverhaulSlam")
		local origin = typeof(data.Origin) == "Vector3" and data.Origin or root.Position
		local hits = (ability and ability.Hits) or 6
		local range = (ability and ability.Range) or 90
		groundCrack(groundPoint(origin), groundPoint(origin + d * range), 0.6, 1.6)
		task.wait(0.3)
		local model = newModel("PillarBarrage")
		for i = 1, hits do
			if not root.Parent then
				break
			end
			local p = groundPoint(origin + d * (10 + (i - 1) * (range - 10) / math.max(hits - 1, 1)))
			local side = d:Cross(UP)
			local final = i == hits
			local list = { { set = stoneSpike(model, p - UP * 3 - d * 3, (UP * 2.2 + d * 0.9).Unit, final and 42 or rand(26, 34), final and 9 or rand(5.5, 7)), delay = 0 } }
			for _ = 1, final and 7 or 4 do
				local off = side * rand(final and -8 or -5, final and 8 or 5) - d * rand(0, 4)
				table.insert(list, { set = stoneSpike(model, p + off - UP, (UP * 2 + d * rand(0.3, 0.8) + side * rand(-0.5, 0.5)).Unit, final and rand(11, 18) or rand(8, 14), final and rand(2.5, 3.5) or rand(1.8, 2.8)), delay = rand(0, 0.05) })
			end
			growSpikes(list, 0.1)
			rocks(p, final and 2.2 or 1.6, final and 16 or 10)
			dustPuffs(p, 2, final and 9 or 5, DUST, 1.2, false)
			shockDisc(p + UP * 0.5, UP, final and 6 or 4, final and 34 or 22, 0.3, final and RED_HOT or DUST)
			VFX.PlaySound("SpikeErupt", p, final and 1.2 or 1)
			VFX.ShakeAt(p, final and 2.8 or 1.8, final and 160 or 120, 0.3)
			task.wait(0.12)
		end
		crumble(model, 2.2)
	end

	-- Fused hands rake through the air. The server confirms which targets
	-- they caught before any client draws the arms attached to a victim.
	function Effects.MassGrasp(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local k = VFX.KaijuOf and VFX.KaijuOf(char)
		if k then
			k.graspAt = os.clock()
		else
			VFX.Motion(char, "OverhaulTouch")
		end
		if isLocal then
			face(root, d)
		end
		local start = groundPoint(root.Position)
		local right = d:Cross(UP)
		local range = (ability and ability.Range) or 55
		for i = -2, 2 do
			local finish = groundPoint(root.Position + d * range + right * i * 7)
			groundCrack(start, finish, 0.45, 0.65)
		end
		crackle(char, 0.3)
		VFX.PlaySound("UltOverhaul", root.Position, 0.65)
	end

	function Effects.MassGraspCatch(char, data)
		local root = char and char:FindFirstChild("HumanoidRootPart")
		local targets = type(data.Targets) == "table" and data.Targets or {}
		if not root then
			return
		end
		for i, target in targets do
			local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
			if troot then
				local fromFn = function()
					if not char.Parent then
						return nil
					end
					local k = VFX.KaijuOf and VFX.KaijuOf(char)
					if k and k.body then
						return (k.body * CFrame.new((i - 2) * 7, 30, 2)).Position
					end
					return handPos(char, i % 2 == 0)
				end
				tendril(fromFn, function()
					return troot.Parent and troot.Position + UP * 1.5 or nil
				end, 0.78, {
					Color = Color3.fromRGB(135, 46, 58), OutlineColor = RED,
					Thick = 1.15, Segments = 9, Wave = 0.7, Grow = 0.15,
				})
				billboardRing(troot.Position, 2, 10, RED, 6, 0.25)
				sparks(troot.Position, 1, RED_HOT, RED, 12)
				task.delay(0.57, function()
					if not troot.Parent then
						return
					end
					local p = groundPoint(troot.Position)
					shockDisc(p + UP * 0.4, UP, 3, 23, 0.3, RED)
					rocks(p, 1.4, 8)
					dustPuffs(p, 1, 5, DUST, 0.9, false)
					VFX.PlaySound("KaijuSlam", p, 0.8)
					VFX.ShakeAt(p, 1.5, 90, 0.3)
				end)
			end
		end
	end

	-- The cinematic: the block cracks red, comes apart... and is rebuilt as
	-- a forest of spikes (the server's timeline: 1.1s windup, 0.5s of the
	-- block coming apart, then the spikes at ~1.9s)
	SHOTS.TotalOverhaul = {
		{ T = 0.5, From = { V(-2.5, 1.6, -4.5), V(0, 1.4, 0) }, To = { V(-1.8, 1.7, -3.6), V(0, 1.5, 0) }, Fov = { 50, 40 } },
		{ T = 0.6, Cut = true, From = { V(0, 7, -5), V(0, -2.5, -1.5) }, To = { V(0, 5.5, -4), V(0, -2.5, -1) }, Fov = { 60, 55 } },
		{ T = 2.4, Cut = true, From = { V(0, 25, 40), V(0, 0, -10) }, To = { V(0, 110, 130), V(0, 0, -15) }, Fov = { 65, 78 }, Style = Enum.EasingStyle.Quad },
	}
	function Effects.TotalOverhaul(char, _, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		cinematicFor(char, "TotalOverhaul", isLocal, (ability and ability.Name) or "TOTAL OVERHAUL", RED)
		if isLocal then
			VFX.Hooks.Dim(0.55, 2.4)
		end
		VFX.Motion(char, "OverhaulGloves")
		crackle(char, 1)
		VFX.PlaySound("UltOverhaul", root.Position, 0.8)
		task.wait(1.1)
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position)
		local radius = (ability and ability.Radius) or 85
		-- the cracks race across the whole block...
		for i = 1, 24 do
			local a = i / 24 * math.pi * 2 + rand(-0.1, 0.1)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			groundCrack(center, center + out * radius * rand(0.8, 1.05), 0.8, 2.2)
		end
		shockDisc(center + UP * 0.5, UP, 4, radius * 2, 0.6, RED)
		VFX.PlaySound("TotalOverhaul", center, 1)
		-- ...everything in it comes apart (the server carves the map in waves)...
		for step = 1, 5 do
			task.delay(step * 0.1, function()
				local r = radius * step / 5
				for _ = 1, 8 do
					local a = rand(0, math.pi * 2)
					local p = groundPoint(center + Vector3.new(math.cos(a), 0, math.sin(a)) * r * rand(0.6, 1))
					sparks(p + UP * 2, 1.2, RED_HOT, RED, 12)
					dustPuffs(p, 2, 2, DUST, 1.4, false)
				end
			end)
		end
		task.wait(0.8)
		if not root.Parent then
			return
		end
		-- ...and comes back as a forest of spikes
		if nearCamera(center, 250) then
			VFX.ImpactFrame(0.16)
			VFX.Hooks.Flash(RED_HOT, 0.4)
		end
		local model = newModel("TotalOverhaul")
		local list = {}
		for _ = 1, 55 do
			local r = radius * math.sqrt(rng:NextNumber())
			if r > 6 then
				local a = rand(0, math.pi * 2)
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				local base = groundPoint(center + out * r) - UP * 2
				table.insert(list, {
					set = stoneSpike(model, base, (UP * 2 + out * rand(0.2, 0.9) + rng:NextUnitVector() * 0.2).Unit, rand(18, 42), rand(3.5, 6.5)),
					delay = r / radius * 0.3,
				})
			end
		end
		growSpikes(list, 0.18)
		VFX.PlaySound("SpikeErupt", center, 1.4)
		VFX.ShakeAt(center, 5, 300, 1.2)
		crumble(model, 5)
	end

	-- Awakening: he fuses - the body comes apart and rebuilds itself bigger
	QUIRK_FX.Ult.Overhaul = function(char, root, g)
		crackle(char, 0.5)
		task.delay(0.35, function()
			if char.Parent then
				burstApart(char, 6, 0.2)
			end
		end)
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			groundCrack(g, g + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(14, 22), 0.5, 1.2)
		end
		rocks(g, 1.6, 12)
		dustPuffs(root.Position, 1.6, 8, DUST, 1.2, false)
	end

	-- Dash: red crackle trailing off his hands and feet
	QUIRK_FX.Dash.Overhaul = function(char, root, dir)
		legTrails(char, 0.25, RED)
		for _ = 1, 3 do
			bolt(root.Position - dir * 2, 2, RED)
		end
	end
end


---------------------------------------------------------------------------
-- OVERHAUL: FUSION - KATSUKAME. The end of the Deku fight (ch. 157 / ep. 76):
-- he takes Katsukame and the street apart and puts them back together as a
-- towering construct of salmon stone-flesh cracked dark red. The whole front
-- of it is a gaping maw - Katsukame's black plague mask capping the upper jaw,
-- jagged rock teeth along the lower one, and Kai himself fused into the
-- throat from the waist down, arms spread. It walks on huge clawed hands, and
-- ghoulishly long arms with grasping hands writhe out of its back.
-- Every client builds and animates it around him; his real body is hidden
-- for as long as it lasts (the server makes it invisible for everyone).
-- (Set up inside its own function: Luau gives each function 200 local
-- registers, and this module's top level has nearly used its share.)
---------------------------------------------------------------------------
do
	local function setupKaiju()
		-- the anime's colours: salmon stone-flesh plates over deep red cracks
		local PLATE = { Color3.fromRGB(228, 122, 124), Color3.fromRGB(214, 106, 112), Color3.fromRGB(236, 136, 134) }
		local FLESH = Color3.fromRGB(126, 38, 50) -- (the dark between and under the plates)
		local THROAT = Color3.fromRGB(30, 6, 10)
		local RIB, RIB_DARK = Color3.fromRGB(206, 58, 70), Color3.fromRGB(98, 18, 28)
		local TOOTH = Color3.fromRGB(232, 128, 128)
		local CLAW = Color3.fromRGB(34, 10, 16)
		local RED_EYE = Color3.fromRGB(255, 40, 52)
		local MASK = Color3.fromRGB(26, 24, 30)
		local MASK_LINE = Color3.fromRGB(200, 36, 50)
		local GOLD = Color3.fromRGB(214, 172, 74)
		local RED = Overhaul.RED
		local RED_HOT = Color3.fromRGB(255, 140, 150)
		local DUST = Color3.fromRGB(190, 180, 170)
		local RISE = 1.6 -- seconds to put itself together (the server's timeline)
		local FORM_AT = 0.45 -- when his body comes apart
		local SLAM = 0.62 -- one arm slam; the hand lands at 0.55 of it
		local kaijus = setmetatable({}, { __mode = "k" }) -- [character] = the live kaiju

		local function ball(model, size, color, material)
			local p = newPart(size, CFrame.new(), color, material or Enum.Material.SmoothPlastic, nil, model)
			local mesh = Instance.new("SpecialMesh")
			mesh.MeshType = Enum.MeshType.Sphere
			mesh.Parent = p
			return p
		end
		local function block(model, size, color, material)
			return newPart(size, CFrame.new(), color, material or Enum.Material.Slate, nil, model)
		end
		local function wedge(model, size, color)
			local p = Instance.new("WedgePart")
			p.Anchored = true
			p.CanCollide = false
			p.CanQuery = false
			p.CanTouch = false
			p.Size = size
			p.Color = color
			p.Material = Enum.Material.Slate
			p.Parent = model
			return p
		end
		-- a CFrame at the middle of a..b with its X axis along the bone
		local function between(a, b)
			local x = b - a
			local len = x.Magnitude
			x = len > 1e-4 and x / len or Vector3.new(1, 0, 0)
			local ref = math.abs(x.Y) < 0.95 and UP or Vector3.new(0, 0, 1)
			local z = x:Cross(ref).Unit
			return CFrame.fromMatrix((a + b) / 2, x, z:Cross(x))
		end
		-- a CFrame at pos looking along dir (-Z), steady even straight up or down
		local function aim(pos, dir)
			local d = dir.Magnitude > 1e-4 and dir.Unit or Vector3.new(0, 0, -1)
			local up = math.abs(d.Y) < 0.96 and UP or Vector3.new(0, 0, 1)
			local right = d:Cross(up).Unit
			return CFrame.fromMatrix(pos, right, right:Cross(d))
		end
		-- two-bone IK: where the joint goes between a and the target, bending toward pole
		local function ik(a, target, l1, l2, pole)
			local d = target - a
			local dist = math.clamp(d.Magnitude, math.abs(l1 - l2) + 0.05, l1 + l2 - 0.05)
			local dir = d.Magnitude > 1e-4 and d.Unit or UP
			local cosA = math.clamp((l1 * l1 + dist * dist - l2 * l2) / (2 * l1 * dist), -1, 1)
			local bend = pole - dir * pole:Dot(dir)
			bend = bend.Magnitude > 1e-3 and bend.Unit or Vector3.new(0, 0, 1)
			return a + dir * (cosA * l1) + bend * (math.sqrt(1 - cosA * cosA) * l1), a + dir * dist
		end
		local function lerpAngle(a, b, t)
			local diff = (b - a + math.pi) % (2 * math.pi) - math.pi
			return a + diff * t
		end

		-- a clawed hand: palm, long fingers and a thumb, dark claws. Its frame's
		-- -Z runs along the fingers and -Y out of the palm; side = which hand
		local FINGERS = {
			[5] = { { -1.25, -2.9, 0.2 }, { -0.42, -3.2, 0.07 }, { 0.42, -3.2, -0.07 }, { 1.25, -2.9, -0.2 }, { -1.8, -0.9, 1, true } },
			[4] = { { -1, -2.9, 0.18 }, { 0, -3.2, 0 }, { 1, -2.9, -0.18 }, { -1.6, -0.9, 1, true } },
		}
		local function newHand(model, s, count, side, jointed)
			local h = { s = s, palm = ball(model, Vector3.new(3.8, 1.6, 3.8) * s, PLATE[2]), fingers = {} }
			for _, f in FINGERS[count] do
				local x, yaw, thumb = f[1], f[3], f[4] == true
				if thumb then
					x, yaw = x * side, yaw * side -- the thumb sits on the inside of each hand
				end
				local w = thumb and 1.05 or 0.9
				table.insert(h.fingers, {
					x = x,
					z = f[2],
					yaw = yaw,
					l1 = thumb and 2.2 or 2.8,
					l2 = jointed and (thumb and 1.6 or 2.3) or nil,
					seg1 = ball(model, Vector3.new(w, w * 0.85, 3.1) * s, PLATE[1]),
					seg2 = jointed and ball(model, Vector3.new(w * 0.85, w * 0.72, 2.6) * s, PLATE[3]) or nil,
					claw = ball(model, Vector3.new(w * 0.62, w * 0.5, 2) * s, CLAW),
				})
			end
			return h
		end

		local function build(char)
			local model = Instance.new("Model")
			model.Name = "Kaiju"
			model.Parent = folder
			local hl = Instance.new("Highlight") -- the anime's ink outline
			hl.FillTransparency = 1
			hl.OutlineColor = Color3.fromRGB(28, 6, 10)
			hl.OutlineTransparency = 0.05
			hl.DepthMode = Enum.HighlightDepthMode.Occluded
			hl.Adornee = model
			hl.Parent = model
			local k = {
				char = char,
				model = model,
				fixed = {},
				jaw = {},
				arms = {},
				legs = {},
				limbs = {},
				slam = {},
				slamHit = {},
				from = {},
				t0 = os.clock(),
				phase = 0,
			}
			-- same seed on every client: everyone sees the same monster
			local rs = Random.new(157)
			local function fixed(part, cf, list)
				part.CastShadow = true
				table.insert(list or k.fixed, { part = part, cf = cf })
			end
			-- stone-flesh slabs laid over an ellipsoid (centre c, radii r), the
			-- dark cracks showing between them; keep(p) can skip spots
			local function coat(c, r, count, size, keep, list)
				local golden = math.pi * (3 - math.sqrt(5))
				for i = 0, count - 1 do
					local y = 1 - (i + 0.5) / count * 2
					local ring = math.sqrt(1 - y * y)
					local unit = Vector3.new(math.cos(golden * i) * ring, y, math.sin(golden * i) * ring)
					local p = c + unit * r
					if not keep or keep(p) then
						local n = Vector3.new(unit.X / r.X, unit.Y / r.Y, unit.Z / r.Z).Unit
						local t = n:Cross(math.abs(n.Y) < 0.9 and UP or Vector3.new(1, 0, 0)).Unit
						local w, d = size * rs:NextNumber(0.85, 1.2), size * rs:NextNumber(0.7, 1.05)
						local cf = CFrame.fromMatrix(p - n * 0.05, t, n)
							* CFrame.Angles(rs:NextNumber(-0.1, 0.1), rs:NextNumber(0, math.pi), rs:NextNumber(-0.1, 0.1))
						fixed(block(model, Vector3.new(w, rs:NextNumber(1, 1.6), d), PLATE[rs:NextInteger(1, 3)]), cf, list)
					end
				end
			end
			-- a jagged rock spike: two wedges back to back make a blade with a sharp
			-- ridge, its base sunk into the flesh at pos, pointing along tilt's +Y
			local function spike(pos, height, thick, tilt, color, list)
				local base = CFrame.new(pos) * tilt * CFrame.Angles(0, rs:NextNumber(-0.4, 0.4), 0)
				local w = thick * 2.2
				color = color or PLATE[1]
				fixed(wedge(model, Vector3.new(thick * 0.9, height, w / 2), color), base * CFrame.new(0, height * 0.4, -w / 4), list)
				fixed(
					wedge(model, Vector3.new(thick * 0.9, height, w / 2), color),
					base * CFrame.new(0, height * 0.4, w / 4) * CFrame.Angles(0, math.pi, 0),
					list
				)
			end
			local function shape(c, size, color, list)
				fixed(ball(model, size, color or FLESH), CFrame.new(c), list)
			end
			-- a limb bone: a dark core with salmon rock plates over its top and
			-- sides - the underside stays in shadow, like the anime's cel shading
			local function bone(len, thick)
				local b = { core = ball(model, Vector3.new(len + thick * 0.5, thick, thick), FLESH), plates = {} }
				local n = math.max(2, math.floor(len / (thick * 0.85) + 0.5))
				for i = 1, n do
					for j = -1, 1, 2 do
						local rel = CFrame.new(((i - 0.5) / n - 0.5) * len * 0.95, 0, 0)
							* CFrame.Angles(j * rs:NextNumber(0.2, 1), 0, 0)
							* CFrame.new(0, thick * 0.36, 0)
							* CFrame.Angles(rs:NextNumber(-0.2, 0.2), rs:NextNumber(-0.25, 0.25), rs:NextNumber(-0.12, 0.12))
						local size = Vector3.new(len / n * rs:NextNumber(0.95, 1.3), thick * rs:NextNumber(0.28, 0.4), thick * rs:NextNumber(0.42, 0.62))
						table.insert(b.plates, { part = block(model, size, PLATE[rs:NextInteger(1, 3)]), rel = rel })
					end
				end
				return b
			end
			k.bone = bone

			-- (local space: -Z forward, +Y up, the origin on the ground under him)
			-- the hunched mass behind the maw, rock spines down its back
			shape(Vector3.new(0, 29, 9), Vector3.new(32, 26, 26))
			shape(Vector3.new(0, 23, 21), Vector3.new(24, 18, 18))
			coat(Vector3.new(0, 29, 9), Vector3.new(16, 13, 13), 46, 7, function(p)
				return p.Y > 25 and p.Z > -2
			end)
			coat(Vector3.new(0, 23, 21), Vector3.new(12, 9, 9), 16, 6, function(p)
				return p.Y > 21 and p.Z > 19
			end)
			for i = 0, 7 do
				local z = 0 + i * 3.6
				local y = 43 - ((z - 12) / 11) ^ 2 * 5
				spike(Vector3.new(0, y, z), rs:NextNumber(7, 11), 2.6, CFrame.Angles(math.rad(28 + i * 5), 0, rs:NextNumber(-0.2, 0.2)))
				if i % 2 == 0 and i < 7 then
					for _, side in { 1, -1 } do
						spike(Vector3.new(side * 7.5, y - 3, z + 1), rs:NextNumber(4.5, 7), 2.1, CFrame.Angles(math.rad(35), 0, math.rad(-side * 40)))
					end
				end
			end

			-- the maw: the whole front of it. A dark throat with red ribs raying
			-- out of it (and a red glow down in it), framed by thick cheeks
			local MOUTH = Vector3.new(0, 27, -4.5)
			shape(MOUTH + Vector3.new(0, 0, 2), Vector3.new(24, 22, 3), THROAT)
			for i = 1, 22 do
				local a = i / 22 * math.pi * 2
				local dir = Vector3.new(math.cos(a), math.sin(a), 0)
				local len = 5.8 + (i % 2) * 2.2
				fixed(
					block(model, Vector3.new(0.9, len, 0.35), i % 2 == 0 and RIB or RIB_DARK, Enum.Material.SmoothPlastic),
					CFrame.fromMatrix(MOUTH + Vector3.new(0, 0, 0.45) + dir * (2.4 + len / 2), Vector3.new(-dir.Y, dir.X, 0), dir)
						* CFrame.Angles(math.rad(-10), 0, 0)
				)
			end
			local glow = newPart(Vector3.one * 0.4, CFrame.new(), RED, Enum.Material.Neon, nil, model)
			glow.Transparency = 1
			fixed(glow, CFrame.new(MOUTH + Vector3.new(0, 0, -3)))
			local light = Instance.new("PointLight")
			light.Color = Color3.fromRGB(255, 50, 60)
			light.Range = 26
			light.Brightness = 3
			light.Parent = glow
			for _, side in { 1, -1 } do
				shape(Vector3.new(side * 12.5, 27, -6), Vector3.new(8, 24, 13))
				coat(Vector3.new(side * 12.5, 27, -6), Vector3.new(4, 12, 6.5), 12, 4.6, function(p)
					return p.X * side > 12.8 or p.Z < -11
				end)
			end
			-- the upper jaw: a thick overhang over the mouth, jutting forward to
			-- Katsukame's mask, jagged teeth hanging off its underside
			shape(Vector3.new(0, 39, -6), Vector3.new(28, 9, 15))
			shape(Vector3.new(0, 38, -14.5), Vector3.new(17, 7.5, 12))
			shape(Vector3.new(0, 37, -21), Vector3.new(11, 6.5, 8))
			coat(Vector3.new(0, 39, -6), Vector3.new(14, 4.5, 7.5), 18, 5.2, function(p)
				return p.Y > 38.5
			end)
			coat(Vector3.new(0, 38, -14.5), Vector3.new(8.5, 3.75, 6), 11, 4.2, function(p)
				return p.Y > 37.5
			end)
			coat(Vector3.new(0, 37, -21), Vector3.new(5.5, 3.25, 4), 7, 3.4, function(p)
				return p.Y > 36.6
			end)
			for _, t in { { 9.5, -6 }, { 8, -10.5 }, { 6.4, -15 }, { 4.4, -19.5 } } do
				for _, side in { 1, -1 } do
					spike(
						Vector3.new(side * t[1], 34.6, t[2]),
						rs:NextNumber(4.5, 6.2),
						1.5,
						CFrame.Angles(math.rad(180 + rs:NextNumber(-12, 12)), 0, math.rad(side * rs:NextNumber(0, 12))),
						TOOTH
					)
				end
			end
			-- Katsukame's plague mask: black, a hooked beak, white eyes ringed red,
			-- red lines swirling over it, a gold band where it meets the flesh
			fixed(
				newPart(Vector3.new(1.4, 8.4, 8.4), CFrame.new(), GOLD, Enum.Material.Metal, Enum.PartType.Cylinder, model),
				CFrame.new(0, 37.1, -24.2) * CFrame.Angles(0, math.rad(90), 0)
			)
			local dome, domeR = Vector3.new(0, 37.3, -27.4), Vector3.new(4.2, 4, 4.3)
			fixed(ball(model, domeR * 2, MASK), CFrame.new(dome))
			fixed(ball(model, Vector3.new(4.4, 4, 8.2), MASK), CFrame.new(0, 34.6, -31.3) * CFrame.Angles(math.rad(-52), 0, 0))
			fixed(ball(model, Vector3.new(2.8, 2.6, 5.2), MASK), CFrame.new(0, 30.8, -33.6) * CFrame.Angles(math.rad(-80), 0, 0))
			fixed(ball(model, Vector3.new(1.6, 1.5, 3), MASK), CFrame.new(0, 28.4, -33.4) * CFrame.Angles(math.rad(-110), 0, 0))
			-- a point on the mask's dome, in the direction d from its middle
			local function onMask(d, lift)
				local s = 1 / math.sqrt((d.X / domeR.X) ^ 2 + (d.Y / domeR.Y) ^ 2 + (d.Z / domeR.Z) ^ 2)
				return dome + d * s + d.Unit * (lift or 0)
			end
			local function maskLine(dirs, thick)
				for i = 1, #dirs - 1 do
					local a, b = onMask(dirs[i], 0.05), onMask(dirs[i + 1], 0.05)
					fixed(ball(model, Vector3.new((b - a).Magnitude + thick, thick, thick), MASK_LINE), between(a, b))
				end
			end
			for _, side in { 1, -1 } do
				local look = Vector3.new(side, 0.3, -0.7)
				local eye = onMask(look, 0)
				fixed(ball(model, Vector3.new(2.9, 3.4, 0.7), MASK_LINE), aim(eye, look))
				fixed(ball(model, Vector3.new(2.2, 2.8, 0.8), Color3.fromRGB(242, 240, 232)), aim(eye + look.Unit * 0.12, look))
				-- (a pinprick of red for a pupil: it glows)
				fixed(ball(model, Vector3.new(0.8, 0.8, 0.5), RED_EYE, Enum.Material.Neon), aim(eye + look.Unit * 0.44, look))
				maskLine({
					Vector3.new(side, -0.3, 0.45),
					Vector3.new(side, -0.6, 0),
					Vector3.new(side, -0.45, -0.5),
					Vector3.new(side * 0.8, 0, -0.9),
				}, 0.45)
			end
			maskLine({ Vector3.new(0, 1, 0.7), Vector3.new(0, 1, 0), Vector3.new(0, 1, -0.7), Vector3.new(0, 0.5, -1) }, 0.45)

			-- the lower jaw (hinged: see update), a row of tall rock teeth along it
			local function jawShape(c, size)
				fixed(ball(model, size, FLESH), CFrame.new(c), k.jaw)
			end
			jawShape(Vector3.new(0, 16, -9), Vector3.new(21, 7, 16))
			jawShape(Vector3.new(0, 16.4, -18), Vector3.new(14, 6, 11))
			jawShape(Vector3.new(0, 16.6, -24), Vector3.new(9, 5, 7))
			coat(Vector3.new(0, 16, -9), Vector3.new(10.5, 3.5, 8), 14, 5, function(p)
				return p.Y < 17 or p.Z < -14
			end, k.jaw)
			coat(Vector3.new(0, 16.4, -18), Vector3.new(7, 3, 5.5), 9, 4.2, function(p)
				return p.Y < 17 or p.Z < -21
			end, k.jaw)
			for _, t in { { 9, -4.5 }, { 8.6, -8.5 }, { 7.8, -12.5 }, { 6.6, -16.5 }, { 5, -20.5 }, { 2.8, -24 } } do
				for _, side in { 1, -1 } do
					spike(
						Vector3.new(side * t[1], 18.4, t[2]),
						rs:NextNumber(7, 10.5),
						2.1,
						CFrame.Angles(math.rad(rs:NextNumber(-26, -6)), 0, math.rad(-side * rs:NextNumber(8, 24))),
						TOOTH,
						k.jaw
					)
				end
			end

			-- Kai, fused into the throat from the waist down, arms spread
			local skin = Color3.fromRGB(236, 198, 162)
			local coatGreen = Color3.fromRGB(74, 102, 64)
			local lean = CFrame.Angles(math.rad(10), 0, 0)
			local KAI = Vector3.new(0, 4.6, 0.6) -- (from where he was drawn at first)
			local function kai(size, cf, color, material)
				fixed(ball(model, size, color, material), CFrame.new(KAI) * cf)
			end
			kai(Vector3.new(3.6, 2.2, 2.8), CFrame.new(0, 19.2, -6.4), FLESH)
			fixed(block(model, Vector3.new(2.6, 2.6, 1.3), coatGreen, Enum.Material.Fabric), CFrame.new(KAI) * CFrame.new(0, 20.9, -7.1) * lean)
			fixed(block(model, Vector3.new(1.1, 2.4, 0.2), Color3.fromRGB(30, 30, 36), Enum.Material.Fabric), CFrame.new(KAI) * CFrame.new(0, 20.9, -7.85) * lean)
			for i = 0, 6 do
				local a = math.rad(-90 + i * 30)
				kai(
					Vector3.new(1.3, 0.95, 1.3),
					CFrame.new(math.sin(a) * 1.45, 22.3 + (i % 2) * 0.12, -7.1 - math.cos(a) * 0.65),
					Color3.fromRGB(124 + (i % 2) * 10, 70, 170),
					Enum.Material.Fabric
				)
			end
			kai(Vector3.new(1.55, 1.7, 1.55), CFrame.new(0, 23.4, -7.4), skin)
			kai(Vector3.new(1.7, 0.95, 1.7), CFrame.new(0, 24.05, -7.25), Color3.fromRGB(56, 38, 44))
			kai(Vector3.new(1.1, 0.72, 0.8), CFrame.new(0, 22.95, -8.1), Color3.fromRGB(176, 34, 46))
			kai(Vector3.new(0.34, 0.76, 0.84), CFrame.new(0, 22.95, -8.18), GOLD, Enum.Material.Metal)
			for _, side in { 1, -1 } do
				local sh = Vector3.new(side * 1.5, 21.9, -7.2)
				local el = Vector3.new(side * 3.2, 21.2, -7.8)
				local wr = Vector3.new(side * 4.8, 20.5, -8.5)
				fixed(ball(model, Vector3.new((el - sh).Magnitude + 0.8, 1, 1), coatGreen, Enum.Material.Fabric), CFrame.new(KAI) * between(sh, el))
				fixed(ball(model, Vector3.new((wr - el).Magnitude + 0.6, 0.72, 0.72), skin), CFrame.new(KAI) * between(el, wr))
				kai(Vector3.new(1, 0.5, 1.1), CFrame.new(wr + Vector3.new(side * 0.45, -0.1, -0.2)), skin)
				-- flesh running out of his wrists into the walls of the maw
				local into = Vector3.new(side * 9.4, 20.8, -7.4)
				fixed(ball(model, Vector3.new((into - wr).Magnitude + 1, 0.9, 0.9), FLESH), CFrame.new(KAI) * between(wr, into))
			end

			-- the two huge arms it walks on (and slams with), gorilla-like
			for _, side in { 1, -1 } do
				table.insert(k.arms, {
					side = side,
					upper = bone(18.5, 7.2),
					fore = bone(18.5, 6.2),
					elbow = ball(model, Vector3.one * 7, FLESH),
					hand = newHand(model, 2.1, 5, side, true),
				})
				shape(Vector3.new(side * 15, 31, -1), Vector3.new(11, 11, 11))
				coat(Vector3.new(side * 15, 31, -1), Vector3.new(5.5, 5.5, 5.5), 9, 4.4, function(p)
					return p.Y > 30 or p.X * side > 16.5
				end)
			end
			-- two thick hind legs bearing its back end
			for _, side in { 1, -1 } do
				table.insert(k.legs, {
					side = side,
					thigh = bone(11.5, 6.6),
					shin = bone(11.5, 5.6),
					knee = ball(model, Vector3.one * 6.2, FLESH),
					hand = newHand(model, 1.7, 4, side, true),
					planted = true,
				})
			end
			-- four long arms out of its back: three bones and a grasping hand each
			for _, side in { 1, -1 } do
				for n = 1, 2 do
					table.insert(k.limbs, {
						side = side,
						root = Vector3.new(side * (5 + n * 2.5), 42 - n * 3, 7 + n * 7),
						spread = (n - 1.5) * 0.9,
						speed = 0.75 + n * 0.3,
						seed = n * 1.7 + (side == 1 and 0 or 2.3),
						l = { 14, 13, 11 },
						segs = { bone(14, 3.6), bone(13, 3), bone(11, 2.4) },
						joints = { ball(model, Vector3.one * 3.6, FLESH), ball(model, Vector3.one * 3, FLESH) },
						hand = newHand(model, 1.25, 4, side, true),
					})
				end
			end
			for _, d in model:GetChildren() do
				if d:IsA("BasePart") then
					d.CastShadow = true
				end
			end
			return k
		end

		local parts, cfs = {}, {}
		-- queue a part's frame for the bulk move. While it puts itself together
		-- each piece flies up out of the street into place (lower ones first).
		local function push(k, part, cf)
			if k.assembling then
				local f = k.from[part]
				if not f then
					local rel = k.body:ToObjectSpace(cf)
					local a = rand(0, math.pi * 2)
					local r = rand(6, 30)
					f = {
						delay = FORM_AT + math.clamp(rel.Y / 42, 0, 1) * 0.45 + rand(0, 0.1),
						off = part.Size.Magnitude > 12 and CFrame.new(0, -rel.Y - part.Size.Y, 0) * rel
							or CFrame.new(math.cos(a) * r, -7, math.sin(a) * r) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)),
					}
					k.from[part] = f
				end
				local a = math.clamp((k.since - f.delay) / 0.6, 0, 1)
				if a < 1 then
					cf = (k.body * f.off):Lerp(cf, 1 - (1 - a) ^ 3)
				end
			end
			table.insert(parts, part)
			table.insert(cfs, cf)
		end

		local function pushBone(k, b, cf)
			push(k, b.core, cf)
			for _, pl in b.plates do
				push(k, pl.part, cf * pl.rel)
			end
		end

		local function poseHand(k, h, cf, curl)
			local s = h.s
			push(k, h.palm, cf * CFrame.new(0, 0, -1.6 * s))
			for _, f in h.fingers do
				local c = cf * CFrame.new(f.x * s, 0, f.z * s) * CFrame.Angles(0, f.yaw, 0) * CFrame.Angles(-(0.12 + curl * 0.7), 0, 0)
				push(k, f.seg1, c * CFrame.new(0, 0, -f.l1 * s / 2))
				c *= CFrame.new(0, 0, -f.l1 * s)
				if f.seg2 then
					c *= CFrame.Angles(-(0.2 + curl * 0.8), 0, 0)
					push(k, f.seg2, c * CFrame.new(0, 0, -f.l2 * s / 2))
					c *= CFrame.new(0, 0, -f.l2 * s)
				end
				c *= CFrame.Angles(-(0.3 + curl * 0.5), 0, 0)
				push(k, f.claw, c * CFrame.new(0, 0, -0.85 * s))
			end
		end

		-- where a hand lands, in its local space (right arm = +X): the server's slam point
		local function slamPoint(side)
			return Vector3.new(side * 5, 1.5, -20)
		end

		local function update(k, dt, now)
			local root = k.char:FindFirstChild("HumanoidRootPart")
			if not root then
				return
			end
			local v = root.AssemblyLinearVelocity
			local speed = Vector3.new(v.X, 0, v.Z).Magnitude
			local stride = math.min(speed / 12, 1)
			local look = root.CFrame.LookVector
			local yaw = math.atan2(-look.X, -look.Z)
			k.yaw = k.yaw and lerpAngle(k.yaw, yaw, 1 - math.exp(-dt * 4)) or yaw
			k.phase += dt * math.max(speed, 0) / 8
			k.since = now - k.t0
			k.assembling = not k.risen and k.since < RISE + 0.2
			local rise = k.risen and 1 or math.clamp(k.since / RISE, 0, 1)
			local ease = 1 - (1 - rise) ^ 3
			-- the roar: it rears back with its jaws wide
			local roar = k.roarAt and math.clamp((now - k.roarAt) / 1.3, 0, 1) or 1
			local roarK = math.sin(roar * math.pi)
			local graspK = k.graspAt and math.sin(math.clamp((now - k.graspAt) / 0.85, 0, 1) * math.pi) or 0
			local slamK = 0
			for i = 1, 2 do
				if k.slam[i] then
					slamK = math.max(slamK, math.sin(math.clamp((now - k.slam[i]) / SLAM, 0, 1) * math.pi))
				end
			end
			local bob = math.abs(math.sin(k.phase)) * 0.9 * stride + math.sin(now * 1.3) * 0.35
			local hips = CFrame.new(0, 16, 20)
			local body = CFrame.new(groundPoint(root.Position))
				* CFrame.Angles(0, k.yaw, 0)
				* CFrame.new(0, -6 * (1 - ease) + bob, 0)
				* hips
				* CFrame.Angles(math.rad(12) * roarK - math.rad(4) * slamK - 0.03 * stride, 0, math.sin(k.phase) * 0.035 * stride)
				* hips:Inverse()
			k.body = body
			table.clear(parts)
			table.clear(cfs)
			for _, f in k.fixed do
				push(k, f.part, body * f.cf)
			end
			-- the jaw hangs open, breathing; wide for the roar and the slams
			local open = 0.14 + math.sin(now * 1.7) * 0.05 + roarK * 0.42 + slamK * 0.2 + graspK * 0.18
			local hinge = CFrame.new(0, 17.5, -1)
			local jaw = body * hinge * CFrame.Angles(-open, 0, 0) * hinge:Inverse()
			for _, f in k.jaw do
				push(k, f.part, jaw * f.cf)
			end
			-- hind arms: stepping in time with the stride
			for _, leg in k.legs do
				local off = leg.side == 1 and 0 or math.pi
				local lift = math.max(0, math.cos(k.phase + off)) * 2.6 * stride
				local foot = Vector3.new(leg.side * 12, 2.2 + lift, 24 - math.sin(k.phase + off) * 4.5 * stride)
				local hip = Vector3.new(leg.side * 10, 17, 21)
				local knee, ft = ik(hip, foot, 11.5, 11.5, Vector3.new(0, 0.3, 1))
				pushBone(k, leg.thigh, body * between(hip, knee))
				pushBone(k, leg.shin, body * between(knee, ft))
				push(k, leg.knee, body * CFrame.new(knee))
				poseHand(k, leg.hand, body * aim(ft, Vector3.new(leg.side * 0.5, -0.35, -1)), 0.35 + lift * 0.1)
				-- a footfall shakes the street
				local planted = lift < 0.05
				if planted and not leg.planted and rise >= 1 and stride > 0.3 then
					local w = (body * CFrame.new(ft)).Position
					dustPuffs(w, 1.4, 2, DUST, 0.8, false)
					VFX.PlaySound("KaijuStep", w, 0.7)
					VFX.ShakeAt(w, 0.8, 90, 0.2)
				end
				leg.planted = planted
			end
			-- the front arms: walking on their palms, or a slam
			for i, arm in k.arms do
				local off = arm.side == 1 and math.pi or 0 -- opposite the hind arm on that side
				local lift = math.max(0, math.cos(k.phase + off)) * 3.2 * stride
				local hand = Vector3.new(arm.side * 19, 3.4 + lift, -19 - math.sin(k.phase + off) * 5.5 * stride)
				local handDir = Vector3.new(arm.side * 0.35, -0.4, -1)
				local curl = 0.3 + lift * 0.08
				local started = k.slam[i]
				if started then
					local a = (now - started) / SLAM
					local up = Vector3.new(arm.side * 11, 52, -8)
					local down = slamPoint(arm.side) + Vector3.new(0, 1.6, 0)
					if a >= 1 then
						k.slam[i] = nil
					elseif a < 0.45 then
						local t = 1 - (1 - a / 0.45) ^ 2
						hand = hand:Lerp(up, t)
						handDir = handDir:Lerp(Vector3.new(0, 1, -0.4), t)
						curl = 0.3 + t * 0.55
					elseif a < 0.55 then
						local t = (a - 0.45) / 0.1
						hand = up:Lerp(down, t)
						handDir = Vector3.new(0, 1, -0.4):Lerp(Vector3.new(arm.side * 0.2, -0.5, -1), t)
						curl = 0.85 - t * 0.7
					elseif a < 0.8 then
						hand = down
						handDir = Vector3.new(arm.side * 0.2, -0.5, -1)
						curl = 0.15
					else
						local t = (a - 0.8) / 0.2
						hand = down:Lerp(hand, t)
						handDir = Vector3.new(arm.side * 0.2, -0.5, -1):Lerp(handDir, t)
					end
					if a >= 0.55 and not k.slamHit[i] then
						k.slamHit[i] = true
						local w = (body * CFrame.new(slamPoint(arm.side))).Position
						shockDisc(w + UP * 0.5, UP, 6, 46, 0.4, DUST)
						rocks(w, 2.2, 14)
						dustPuffs(w, 2.4, 6, DUST, 1.3, false)
						groundMark(w, 9, Color3.fromRGB(52, 46, 44), 6)
						sparks(w + UP * 2, 1.4, RED_HOT, RED, 20)
						VFX.PlaySound("KaijuSlam", w, 1)
						VFX.ShakeAt(w, 3, 160, 0.5)
					end
				end
				local shoulder = Vector3.new(arm.side * 15, 31, -1)
				local elbow, h = ik(shoulder, hand, 18.5, 18.5, Vector3.new(arm.side * 1, 0.25, 0.3))
				pushBone(k, arm.upper, body * between(shoulder, elbow))
				pushBone(k, arm.fore, body * between(elbow, h))
				push(k, arm.elbow, body * CFrame.new(elbow))
				poseHand(k, arm.hand, body * aim(h, handDir), curl)
			end
			-- the long arms out of its back: writhing, groping at the air ahead
			for _, limb in k.limbs do
				local t = now * limb.speed + limb.seed
				local out = Vector3.new(limb.side * math.cos(limb.spread), 0, math.sin(limb.spread))
				local reach = math.max(math.max(0, math.sin(t * 0.6)) * (0.5 + roarK * 0.5), graspK)
				local d1 = (out * 0.5 + UP * (0.85 + math.sin(t) * 0.15) + Vector3.new(0, 0, 0.2 - reach * 0.5)).Unit
				local d2 = (out * 0.8 + UP * (0.2 + math.sin(t * 1.3) * 0.25) + Vector3.new(0, 0, -0.3 - reach * 0.6)).Unit
				local d3 = (out * 0.3 + UP * (-0.7 + math.cos(t * 0.9) * 0.3) + Vector3.new(0, 0, -0.5 - reach * 0.5)).Unit
				local p0 = limb.root
				local p1 = p0 + d1 * limb.l[1]
				local p2 = p1 + d2 * limb.l[2]
				local p3 = p2 + d3 * limb.l[3]
				pushBone(k, limb.segs[1], body * between(p0, p1))
				pushBone(k, limb.segs[2], body * between(p1, p2))
				pushBone(k, limb.segs[3], body * between(p2, p3))
				push(k, limb.joints[1], body * CFrame.new(p1))
				push(k, limb.joints[2], body * CFrame.new(p2))
				poseHand(k, limb.hand, body * aim(p3, d3), 0.35 + (math.sin(t * 2.1) * 0.5 + 0.5) * 0.55)
			end
			-- red crackle racing over it while it puts itself together
			if k.assembling and k.since > FORM_AT and #parts > 0 and now - (k.lastBolt or 0) > 0.035 then
				k.lastBolt = now
				bolt(cfs[rng:NextInteger(1, #parts)].Position, 3, rng:NextNumber() < 0.5 and RED or RED_HOT)
			end
			local ok = pcall(function()
				workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
			end)
			if not ok then
				for i, part in parts do
					part.CFrame = cfs[i]
				end
			end
		end

		-- his own body stays hidden inside it. (The server makes it invisible for
		-- everyone; this covers the moment before that arrives, and the local
		-- camera, which resets LocalTransparencyModifier on its own character.)
		local function setHidden(k, hidden)
			if hidden then
				if not k.hideList or os.clock() - (k.hideListAt or 0) > 0.5 then
					k.hideList = {}
					k.hideListAt = os.clock()
					for _, d in k.char:GetDescendants() do
						if d:IsA("BasePart") or d:IsA("Decal") then
							table.insert(k.hideList, d)
						end
					end
				end
				for _, d in k.hideList do
					d.LocalTransparencyModifier = 1
				end
			elseif k.hideList then
				for _, d in k.hideList do
					if d.Parent then
						d.LocalTransparencyModifier = 0
					end
				end
				k.hideList = nil
			end
		end

		-- the local player's camera pulls back to take in the whole monster
		local camSaved
		local function pullCamera(char, on)
			local me = Players.LocalPlayer
			local hum = char:FindFirstChildOfClass("Humanoid")
			if not me or me.Character ~= char or not hum then
				return
			end
			if on and not camSaved then
				camSaved = { Min = me.CameraMinZoomDistance, Max = me.CameraMaxZoomDistance, Offset = hum.CameraOffset }
				me.CameraMaxZoomDistance = math.max(camSaved.Max, 180)
				me.CameraMinZoomDistance = 75
				hum.CameraOffset = Vector3.new(9, 24, 0)
			elseif not on and camSaved then
				me.CameraMinZoomDistance = camSaved.Min
				me.CameraMaxZoomDistance = camSaved.Max
				hum.CameraOffset = camSaved.Offset
				camSaved = nil
			end
		end

		-- his body comes apart into red-edged blocks that pour down into the street
		local function dissolve(char)
			local root = char:FindFirstChild("HumanoidRootPart")
			if not root then
				return
			end
			local g = groundPoint(root.Position)
			for _, p in char:GetChildren() do
				if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
					for _ = 1, math.clamp(math.floor(p.Size.Magnitude * 1.5), 3, 8) do
						local s = math.max(math.min(p.Size.X, p.Size.Y, p.Size.Z) * rand(0.35, 0.6), 0.25)
						local home = p.CFrame * CFrame.new(rand(-0.4, 0.4) * p.Size.X, rand(-0.4, 0.4) * p.Size.Y, rand(-0.4, 0.4) * p.Size.Z)
						local cube = newPart(Vector3.one * s, home, p.Color:Lerp(RED, rand(0.2, 0.6)), Enum.Material.SmoothPlastic)
						local out = home.Position - root.Position
						out = ((out.Magnitude > 0.1 and out.Unit or rng:NextUnitVector()) + rng:NextUnitVector() * 0.5).Unit
						tween(cube, 0.2, { CFrame = CFrame.new(home.Position + out * rand(2, 5) + UP * rand(0, 2)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) })
						tween(
							cube,
							0.45,
							{ CFrame = CFrame.new(g + Vector3.new(out.X, 0, out.Z) * rand(4, 12) - UP * 3), Size = Vector3.one * 0.2 },
							Enum.EasingStyle.Quad,
							Enum.EasingDirection.In,
							0.22
						)
						cleanup(cube, 0.75)
					end
				end
			end
			sparks(root.Position, 1.2, RED_HOT, RED, 18)
		end

		local function finish(k)
			if k.done then
				return
			end
			k.done = true
			if kaijus[k.char] == k then
				kaijus[k.char] = nil
			end
			k.conn:Disconnect()
			if k.char.Parent then
				setHidden(k, false)
				pullCamera(k.char, false)
			end
			-- it all comes apart again: red crackle over the mass, the pieces fall
			-- away, and he pulls himself back together where he stood
			for _, f in k.fixed do
				if rng:NextNumber() < 0.12 and f.part.Parent then
					bolt(f.part.CFrame.Position, 4, RED)
				end
			end
			local root = k.char:FindFirstChild("HumanoidRootPart")
			if root then
				dustPuffs(root.Position + UP * 10, 3, 10, DUST, 1.6, false)
				rocks(groundPoint(root.Position), 2.5, 20)
				VFX.PlaySound("KaijuCollapse", root.Position + UP * 15, 1)
				VFX.PlaySound("Reassemble", root.Position, 1)
				local hum = k.char:FindFirstChildOfClass("Humanoid")
				if hum and hum.Health > 0 then
					Overhaul.burstApart(k.char, 5, 0.18)
				end
			end
			Overhaul.crumble(k.model, 0)
		end

		-- start (or, for someone who joined late, pop in already put together)
		local function start(char, risen, duration)
			if kaijus[char] then
				finish(kaijus[char])
			end
			local k = build(char)
			k.risen = risen
			k.duration = duration or 14
			k.roarAt = not risen and k.t0 + RISE + 0.1 or nil
			k.hidden = risen
			kaijus[char] = k
			local sawForm = false
			k.conn = RunService.RenderStepped:Connect(function(dt)
				local now = os.clock()
				local hum = char:FindFirstChildOfClass("Humanoid")
				local up = char:GetAttribute("Kaiju") == true
				sawForm = sawForm or up
				local expired = now - k.t0 > (risen and 0 or RISE) + k.duration + 3
				local dropped = (sawForm and not up) or (not sawForm and now - k.t0 > RISE + 2.5 and not risen)
				if not char.Parent or not hum or hum.Health <= 0 or expired or dropped then
					finish(k)
					return
				end
				if k.hidden then
					setHidden(k, true)
				end
				update(k, dt, now)
			end)
			if risen then
				pullCamera(char, true)
			else
				task.delay(FORM_AT, function()
					if not k.done and char.Parent then
						dissolve(char)
						k.hidden = true
						setHidden(k, true)
						pullCamera(char, true)
					end
				end)
			end
			return k
		end

		SHOTS.Kaiju = {
			{
				T = 0.55,
				From = { V(0, 7, -5), V(0, -2.5, -1.5) },
				To = { V(0, 5.5, -4), V(0, -2.5, -1) },
				Fov = { 60, 55 },
			},
			{
				T = 1.3,
				Cut = true,
				From = { V(12, 3, -62), V(0, 12, -6) },
				To = { V(16, 5, -72), V(0, 26, -10) },
				Fov = { 70, 76 },
				Style = Enum.EasingStyle.Quad,
			},
			{
				T = 1.5,
				Cut = true,
				From = { V(-56, 16, -60), V(0, 24, -12) },
				To = { V(-68, 24, -72), V(0, 26, -12) },
				Fov = { 70, 70 },
			},
		}

		function Effects.Kaiju(char, _, isLocal, ability)
			local root = charParts(char)
			if not root then
				return
			end
			cinematicFor(char, "Kaiju", isLocal, (ability and ability.Name) or "FUSION: KATSUKAME", RED)
			if isLocal then
				VFX.Hooks.Dim(0.55, 2.6)
			end
			VFX.Motion(char, "OverhaulSlam")
			Overhaul.crackle(char, FORM_AT)
			local g = groundPoint(root.Position)
			VFX.PlaySound("KaijuFuse", root.Position, 1)
			start(char, false, ability and ability.Duration)
			task.wait(FORM_AT)
			if not root.Parent then
				return
			end
			-- the street splits and pours up into it
			for i = 1, 14 do
				local a = i / 14 * math.pi * 2
				Overhaul.groundCrack(g, g + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(20, 34), 0.7, 2)
			end
			rocks(g, 2.5, 18)
			dustPuffs(g, 3, 10, DUST, 1.8, false)
			VFX.PlaySound("KaijuRise", g, 1)
			VFX.ShakeAt(g, 2.5, 220, RISE)
			task.wait(RISE - FORM_AT + 0.1)
			if not root.Parent then
				return
			end
			-- it's whole: the roar
			shockDisc(g + UP * 1, UP, 10, 90, 0.6, DUST)
			shockDisc(g + UP * 20, UP, 8, 70, 0.5, RED)
			if nearCamera(g, 150) then
				VFX.ImpactFrame(0.14)
				VFX.Hooks.Flash(Color3.fromRGB(255, 200, 200), 0.3)
			end
			VFX.PlaySound("KaijuRoar", g + UP * 24, 1)
			VFX.ShakeAt(g, 4.5, 260, 0.9)
		end

		-- Server: the form ended (time up / the ult ran out)
		function Effects.KaijuEnd(char)
			local k = kaijus[char]
			if k then
				finish(k)
			end
		end

		-- M1 while a kaiju: one arm comes down. Returns true when it handled it.
		function VFX.KaijuSlam(char, data)
			local k = kaijus[char]
			if not k then
				return false
			end
			local i = ((data.Count or 1) % 2 == 1) and 1 or 2
			k.slam[i] = os.clock()
			k.slamHit[i] = false
			local root = char:FindFirstChild("HumanoidRootPart")
			if root then
				VFX.PlaySound("KaijuSwing", root.Position + UP * 30, 1)
			end
			return true
		end

		function VFX.KaijuOf(char)
			return kaijus[char]
		end

		-- someone already in kaiju form when we arrived (or out of range when it rose)
		local lastScan = 0
		RunService.Heartbeat:Connect(function()
			local now = os.clock()
			if now - lastScan < 0.5 then
				return
			end
			lastScan = now
			for _, plr in Players:GetPlayers() do
				local char = plr.Character
				if char and char:GetAttribute("Kaiju") == true and not kaijus[char] then
					start(char, true, (Config.FindAbilityById("Kaiju") or {}).Duration)
				end
			end
		end)
	end
	setupKaiju()
end

---------------------------------------------------------------------------
-- FINISHERS: the attacker's signature execution on someone at their last
-- sliver of health. The server holds both still for `Time` seconds, then the
-- KO and the launch (the body flies off ragdolled). Everyone sees this; the
-- attacker gets the cinematic, the victim a cut toward whoever got them.
---------------------------------------------------------------------------
do
	local STYLES = (Config.Finishers and Config.Finishers.Styles) or {}
	local FINISH_RED = Color3.fromRGB(255, 90, 70)
	local DECAY_RED = Color3.fromRGB(214, 62, 66)
	local ASH = Color3.fromRGB(150, 140, 142)

	POSES.FinishUppercut = { RightArm = { 165, 0, 10 }, RightElbow = 20, LeftArm = { 20, 0, 15 }, LeftElbow = 60, Waist = { 14, 25, 0 }, Neck = { 20, 0, 0 } }
	POSES.FinishAxe = { RightLeg = { 150, 0, 0 }, LeftLeg = -20, Waist = { 20, 0, 0 }, RightArm = { -40, 0, 30 }, LeftArm = { 60, 0, 30 } }
	POSES.FinishAxeDown = { RightLeg = 40, LeftLeg = -30, LeftKnee = 40, Waist = { -26, 0, 0 }, RightArm = { -30, 0, 35 }, LeftArm = { 30, 0, 35 } }

	-- (char, root, target, troot, d, time): play out and land the blow at `time`
	local FX = {}

	function FX.Default(char, _, _, troot, d, time)
		VFX.Pose(char, "PunchCharge", time)
		task.delay(time - 0.12, function()
			VFX.Pose(char, "PunchR", 0.5)
		end)
		task.delay(time, function()
			windBlast(troot.Position, d, 1.2)
			shockDisc(troot.Position, d, 3, 18, 0.3, WIND)
		end)
	end

	-- palms on them, crackling, then everything at point blank
	function FX.Explosion(char, _, _, troot, d, time)
		VFX.Pose(char, "Blast", time + 0.2)
		local t0 = os.clock()
		while os.clock() - t0 < time and char.Parent do
			sparks(handPos(char, true), 0.5, nil, nil, 6)
			sparks(handPos(char, false), 0.5, nil, nil, 6)
			if rng:NextNumber() < 0.25 then
				VFX.PlaySound("Spark", troot.Position, 0.5)
			end
			task.wait(0.08)
		end
		toonExplosion(troot.Position + d * 1.5, 2.6)
		VFX.PlaySound("BigExplosion", troot.Position, 1)
	end

	-- the fist swells gold, then an uppercut into the sky
	function FX.OneForAll(char, _, _, troot, _, time)
		VFX.Pose(char, "PunchCharge", time)
		local unswell = swell(char, { { "RightUpperArm", "Right Arm" }, { "RightLowerArm", "" }, { "RightHand", "" } }, GOLD, 1.3)
		VFX.PlaySound("DetroitCharge", troot.Position, 0.8)
		local t0 = os.clock()
		while os.clock() - t0 < time - 0.1 and char.Parent do
			bolt(handPos(char, true), 2.2, GOLD)
			task.wait(0.05)
		end
		VFX.Pose(char, "FinishUppercut", 0.6)
		task.wait(0.1)
		unswell(0.4)
		windBlast(troot.Position, UP, 2)
		streaks(troot.Position, UP, 30, 6, 16, 80, WIND, 0.4)
		shockDisc(troot.Position, UP, 4, 40, 0.4, GOLD)
		VFX.PlaySound("DetroitImpact", troot.Position, 1)
	end

	-- Full Cowl flares, the leg goes up... and the heel comes down (Manchester)
	function FX.FullCowl(char, _, _, troot, _, time)
		VFX.Pose(char, "FinishAxe", time)
		local t0 = os.clock()
		while os.clock() - t0 < time - 0.1 and char.Parent do
			bolt(handPos(char, true), 2, COWL_GREEN)
			bolt(troot.Position + UP * 3, 2.5, COWL_GREEN)
			task.wait(0.06)
		end
		VFX.Pose(char, "FinishAxeDown", 0.6)
		task.wait(0.1)
		local g = groundPoint(troot.Position)
		shockDisc(g + UP * 0.5, UP, 3, 30, 0.35, COWL_GREEN)
		rocks(g, 1.4, 10)
		groundMark(g, 6, Color3.fromRGB(52, 46, 44), 5)
		VFX.PlaySound("Smash", g, 1)
	end

	-- right side freezes them solid, left side flash-fires the ice apart
	function FX.HalfCold(char, root, target, troot, d, time)
		VFX.Pose(char, "PunchR", 0.5)
		task.spawn(Effects.Freeze, nil, { Target = target, Duration = time - 0.3 })
		VFX.PlaySound("Ice", troot.Position, 0.9)
		task.wait(time - 0.45)
		if not char.Parent then
			return
		end
		VFX.Pose(char, "PunchL", 0.7)
		VFX.PlaySound("Fire", root.Position, 1)
		Flame.stream(char, root, d, 0.4, 14)
		Flame.burst(troot.Position, 8, 26)
		dustPuffs(troot.Position, 1.6, 8, STEAM, 1.4, true)
	end

	-- the engines scream, then a spinning kick
	function FX.Engine(char, _, _, troot, d, time)
		VFX.Pose(char, "Rev", time)
		task.spawn(exhaust, char, time, 2)
		VFX.PlaySound("ReciproRev", troot.Position, 1)
		task.wait(time - 0.12)
		VFX.Pose(char, "Kick", 0.5)
		task.wait(0.12)
		streaks(troot.Position, d, 20, 3, 12, 50, EXHAUST, 0.3)
		shockDisc(troot.Position, d, 3, 20, 0.3, EXHAUST)
		VFX.PlaySound("ReciproBoom", troot.Position, 1)
	end

	-- five fingers on them: red cracks spread, and they crumble to ash
	function FX.Decay(char, _, _, troot, _, time)
		VFX.Pose(char, "PunchR", time)
		VFX.PlaySound("DecayGrasp", troot.Position, 1)
		local t0 = os.clock()
		while os.clock() - t0 < time and char.Parent do
			bolt(troot.Position + rng:NextUnitVector() * 1.2, 2, DECAY_RED)
			if rng:NextNumber() < 0.4 then
				dustPuffs(troot.Position - UP * 2, 0.6, 1, ASH, 1, false)
			end
			task.wait(0.06)
		end
		dustPuffs(troot.Position, 2, 10, ASH, 1.8, false)
		VFX.PlaySound("Crumble", troot.Position, 1)
	end

	-- a finger to their chest: Red, point blank
	function FX.Limitless(char, _, _, troot, d, time)
		VFX.Pose(char, "APShot", time + 0.2)
		VFX.PlaySound("RedCharge", troot.Position, 1)
		local orb = newPart(Vector3.one * 0.3, CFrame.new(handPos(char, true)), PAL.RED_CORE, Enum.Material.Neon, Enum.PartType.Ball)
		local glow = newPart(Vector3.one * 0.6, CFrame.new(handPos(char, true)), PAL.RED_GLOW, Enum.Material.Neon, Enum.PartType.Ball)
		glow.Transparency = 0.5
		tween(orb, time, { Size = Vector3.one * 1.6 })
		tween(glow, time, { Size = Vector3.one * 3.4 })
		local t0 = os.clock()
		while os.clock() - t0 < time and char.Parent do
			local p = handPos(char, true) + d
			orb.CFrame = CFrame.new(p)
			glow.CFrame = CFrame.new(p)
			task.wait(1 / 60)
		end
		orb:Destroy()
		glow:Destroy()
		shockDisc(troot.Position, d, 2, 40, 0.35, PAL.RED_GLOW)
		billboardRing(troot.Position, 3, 30, PAL.RED_GLOW, 8, 0.35)
		streaks(troot.Position, d, 24, 4, 14, 70, PAL.RED_CORE, 0.35)
		VFX.PlaySound("Red", troot.Position, 1)
	end

	-- a bare hand on them: they crack red and come apart... and the street
	-- spears them into the sky
	function FX.Overhaul(char, _, target, troot, _, time)
		VFX.Pose(char, "OverhaulTouch", time)
		Overhaul.crackle(target, time * 0.6)
		VFX.PlaySound("Disassemble", troot.Position, 1)
		task.wait(time * 0.6)
		Overhaul.burstApart(target, 3, time * 0.25)
		task.wait(time * 0.4)
		local g = groundPoint(troot.Position)
		local model = Overhaul.newModel("FinisherSpikes")
		local list = {}
		for i = 1, 6 do
			local a = i / 6 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			table.insert(list, { set = Overhaul.stoneSpike(model, g + out * 2.2 - UP, (UP * 3 - out).Unit, rand(9, 13), rand(1.4, 2)), delay = rand(0, 0.04) })
		end
		growSpikes(list, 0.08)
		VFX.PlaySound("SpikeErupt", g, 1)
		Overhaul.crumble(model, 1.6)
	end

	-- Suneater: the crab claw closes on them, and a tentacle hurls them away
	function FX.Manifest(char, _, _, troot, d, time)
		local SE = VFX.SE
		VFX.Pose(char, "ClawHold", time)
		local close = SE and SE.claw(char, 1.2, time + 0.3)
		if close then
			close(0.1, false)
		end
		VFX.PlaySound("Manifest", troot.Position, 1)
		task.wait(time * 0.3)
		for _ = 1, 2 do
			if close then
				close(0.06, true)
			end
			VFX.PlaySound("ClawCrush", troot.Position, 1)
			sparks(troot.Position, 0.8, Color3.fromRGB(250, 236, 220), Color3.fromRGB(214, 84, 44), 10)
			task.wait(time * 0.2)
			if close then
				close(0.06, false)
			end
		end
		if SE and troot.Parent then
			local tent = SE.tentacle(0.9, 10)
			tent.set(handPos(char, false), troot.Position + d * 2, 2, 0.3)
			tent.fade(0.4)
		end
	end

	-- Kamui Woods: a branch round them, the cage closes, and it crushes
	function FX.Compress(char, _, target, troot, d, time)
		VFX.MC.finisher(char, target, troot, d, time)
	end
	function FX.Creation(char, _, target, troot, d, time)
		VFX.YM.finisher(char, target, troot, d, time)
	end
	function FX.Double(char, _, target, troot, d, time)
		VFX.TW.finisher(char, target, troot, d, time) -- (round 69: Twice)
	end
	-- (round 74) Prime Deku: gone, and behind them - the kick
	function FX.PrimeDeku(char, _, _, troot, d, time)
		afterimage(char, COWL_GREEN, 0.4)
		VFX.Pose(char, "FlashKickWind", time)
		local t0 = os.clock()
		while os.clock() - t0 < time - 0.1 and char.Parent do
			bolt(troot.Position + UP, 3, COWL_GREEN)
			bolt(handPos(char, true), 1.6, COWL_CORE)
			task.wait(0.06)
		end
		VFX.Pose(char, "FlashKick", 0.6)
		shockDisc(troot.Position, d, 3, 30, 0.35, COWL_GREEN, 8)
		sparks(troot.Position, 1.4, Color3.new(1, 1, 1), COWL_GREEN, 30)
		VFX.PlaySound("FlashKick", troot.Position, 1)
	end
	-- Prime All Might: the golden uppercut into the sky
	function FX.PrimeMight(char, root, target, troot, d, time)
		FX.OneForAll(char, root, target, troot, d, time)
	end
	-- DIO: The World's rush, then MUDA!
	function FX.TheWorld(char, _, _, troot, d, time)
		local CDV = VFX.CDV
		local st = CDV and CDV.act(char, "barrage", time)
		if st then
			CDV.shout(st, "MUDA MUDA MUDA!", 7, time)
		end
		VFX.Pose(char, "StandUser", time)
		local t0 = os.clock()
		while os.clock() - t0 < time - 0.1 and troot.Parent do
			sparks(troot.Position + Vector3.new(rand(-1, 1), rand(-0.5, 1.5), rand(-1, 1)), 0.5, Color3.new(1, 1, 1), GOLD, 4)
			VFX.PlaySound("Dora", troot.Position, 0.5)
			task.wait(0.08)
		end
		if st then
			CDV.act(char, "punchR", 0.5)
			CDV.shout(st, "MUDA!!", 6, 0.8)
		end
		shockDisc(troot.Position, d, 2, 20, 0.3, WIND, 6)
		VFX.PlaySound("DoraFinish", troot.Position, 1)
	end
	function FX.Electrification(char, _, target, troot, d, time)
		VFX.DK.finisher(char, target, troot, d, time)
	end
	function FX.Hellflame(char, _, target, troot, d, time)
		VFX.HF.finisher(char, target, troot, d, time)
	end
	function FX.Blueflame(char, _, target, troot, d, time)
		VFX.HF.dabiFinisher(char, target, troot, d, time)
	end
	function FX.Arbor(char, _, target, troot, _, time)
		local KW = VFX.KW
		VFX.Pose(char, "BranchCast", time)
		if not KW then
			return
		end
		local arm = KW.reach(char, 0.7, 12, troot.Position, 1, 0.12)
		arm.target = target
		arm.life = time
		local cage = KW.cage(target, time)
		VFX.PlaySound("WoodBind", troot.Position, 1)
		task.wait(time * 0.75)
		if cage then
			cage.crush()
		end
		if troot.Parent then
			KW.splinters(troot.Position, 1.4, 14)
			VFX.PlaySound("TrunkSlam", troot.Position, 0.9)
		end
	end

	SHOTS.Finisher = {
		{ T = 0.55, From = { V(4.5, 1.6, -2), V(0, 1.4, -2.5) }, To = { V(3.6, 1.2, -1.2), V(0, 1.3, -2.5) }, Fov = { 55, 45 } },
		{ T = 1.6, Cut = true, From = { V(-7, 3, 3), V(0, 2, -5) }, To = { V(-11, 5, 6), V(0, 4, -12) }, Fov = { 62, 74 } },
	}

	function Effects.Finisher(char, data)
		local root = charParts(char)
		local target = data.Target
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		if not root or not troot then
			return
		end
		local style = (type(data.Style) == "string" and STYLES[data.Style] and FX[data.Style]) and data.Style or "Default"
		local conf = STYLES[style] or STYLES.Default or {}
		local time = type(data.Time) == "number" and data.Time or conf.Time or 1.1
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or root.CFrame.LookVector
		local quirk = Config.Quirks[data.Style or ""]
		local color = quirk and quirk.Color or FINISH_RED
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		if me == char then
			VFX.Cinematic(char, SHOTS.Finisher, { Title = conf.Name or "FINISH", Color = color, Own = true })
		elseif me == target then
			VFX.Cinematic(target, witnessShots(5), { Title = conf.Name or "FINISH", Color = color, Face = root.Position })
		end
		VFX.MuteGait(char, time + 0.3)
		VFX.MuteGait(target, time)
		VFX.Pose(target, "Stagger", time) -- dazed, swaying on their feet
		task.spawn(FX[style], char, root, target, troot, d, time)
		task.wait(time)
		if not troot.Parent then
			return
		end
		if me == char or me == target or nearCamera(troot.Position, 60) then
			VFX.ImpactFrame(0.14)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
		end
		VFX.PlaySound("Finisher", troot.Position, 1)
		VFX.ShakeAt(troot.Position, 3, 120, 0.5)
		billboardRing(troot.Position, 3, 26, color, 8, 0.35)
		if me == char then
			VFX.Hooks.Callout("FINISHED!", FINISH_RED)
		end
	end

	-- Server: the finished body is launched. A streak of wind behind it, a
	-- burst of air (and dust off the street) where it left
	function Effects.FinisherLaunch(body, data)
		local root = body and body:FindFirstChild("HumanoidRootPart")
		local v = data and data.Velocity
		if not root or typeof(v) ~= "Vector3" or v.Magnitude < 1 then
			return
		end
		local dir = v.Unit
		local from = root.Position
		local torso = body:FindFirstChild("UpperTorso") or body:FindFirstChild("Torso") or root
		addTrail(torso, WIND, 0.35, 2.4)(1.3)
		shockDisc(from, dir, 3, 24, 0.3, WIND)
		billboardRing(from, 2, 18, WIND, 6, 0.3)
		dustPuffs(groundPoint(from), 1.6, 6, Color3.fromRGB(190, 180, 170), 1.2, false)
		VFX.PlaySound("FinisherLaunch", from, 1)
		VFX.ShakeAt(from, 2, 100, 0.4)
	end
end

---------------------------------------------------------------------------
-- Shop items, the PLUS ULTRA dev kit, and the dev toys
---------------------------------------------------------------------------

-- (in a function of its own: this module is close to Luau's 200-local limit)
local function addItemEffects()
	local SODA_BLUE = Color3.fromRGB(70, 200, 255)
	local HEAL_GREEN = Color3.fromRGB(110, 255, 140)
	local HAIR_GOLD = Color3.fromRGB(252, 218, 84)
	local TRIGGER_RED = Color3.fromRGB(235, 40, 60)
	local SCARF_WHITE = Color3.fromRGB(226, 226, 216)
	local ERASE_RED = Color3.fromRGB(255, 40, 40)
	local GRAPE = Color3.fromRGB(120, 44, 170)
	local ZERO_PINK = Color3.fromRGB(255, 150, 190)
	local WARP_DARK = Color3.fromRGB(40, 16, 60)
	local WARP_MIST = Color3.fromRGB(96, 50, 130)
	local REWIND_GOLD = Color3.fromRGB(255, 230, 150)
	local STAR_BLUE = Color3.fromRGB(80, 140, 255)
	local MONEY_GREEN = Color3.fromRGB(96, 190, 96)

	local function isMine(char)
		local me = Players.LocalPlayer
		return me ~= nil and char ~= nil and me.Character == char
	end

	-- a floating "+40" (heals, bucks)
	local function floatText(pos, text, color)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos), color)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(120, 40)
		bb.AlwaysOnTop = true
		bb.LightInfluence = 0
		bb.Adornee = anchor
		bb.Parent = anchor
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.Bangers
		label.TextScaled = true
		label.TextColor3 = color
		label.TextStrokeTransparency = 0
		label.Text = text
		label.Parent = bb
		tween(anchor, 1.1, { CFrame = CFrame.new(pos + UP * 4) })
		tween(label, 0.4, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, 0.8)
		cleanup(anchor, 1.3)
	end

	-- a glow that follows a character for a while (Trigger, Zero Gravity)
	local function aura(char, color, duration, rate, speed)
		local torso = limb(char, "UpperTorso", "Torso")
		if not torso then
			return
		end
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		pe.Color = ColorSequence.new(color, Color3.new(1, 1, 1))
		pe.LightEmission = 1
		pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.6), NumberSequenceKeypoint.new(1, 0) })
		pe.Speed = NumberRange.new(speed or 2, (speed or 2) * 2)
		pe.Lifetime = NumberRange.new(0.5, 1)
		pe.SpreadAngle = Vector2.new(180, 180)
		pe.Acceleration = Vector3.new(0, 6, 0)
		pe.Rate = rate or 30
		pe.Parent = torso
		local light = Instance.new("PointLight")
		light.Color = color
		light.Range = 10
		light.Brightness = 1.5
		light.Parent = torso
		task.delay(duration, function()
			pe.Enabled = false
			tween(light, 0.3, { Brightness = 0 })
			task.wait(1.1)
			pe:Destroy()
			light:Destroy()
		end)
	end

	---------------------------------------------------------------------------
	-- Items
	---------------------------------------------------------------------------

	function Effects.Soda(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "Drink", 0.55)
		local hand = limb(char, "RightHand", "Right Arm")
		local can = newPart(Vector3.new(0.9, 0.5, 0.5), CFrame.new(handPos(char, true)), SODA_BLUE, Enum.Material.Metal, Enum.PartType.Cylinder)
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < 0.6 and can.Parent and hand and hand.Parent do
				can.CFrame = hand.CFrame * CFrame.new(0, -hand.Size.Y / 2 - 0.1, -0.3) * CFrame.Angles(0, 0, math.rad(90))
				task.wait()
			end
			can:Destroy()
		end)
		VFX.PlaySound("Soda", root.Position, 1)
		task.wait(0.45)
		if root.Parent then
			sparks(root.Position, 0.35, HEAL_GREEN, Color3.new(1, 1, 1), 18)
			floatText(root.Position + UP * 3, "+" .. tostring(data.Heal or 40), HEAL_GREEN)
		end
	end

	-- the rifle comes up while scoped in
	function Effects.Scope(char, data)
		if data.On then
			VFX.Pose(char, "Aim", -1)
			VFX.PlaySound("SniperScope", nil, 1)
		else
			VFX.ReleasePose(char, 0.2)
		end
	end

	function Effects.SniperShot(char, data)
		local from, to = data.From, data.To
		if typeof(from) ~= "Vector3" or typeof(to) ~= "Vector3" then
			return
		end
		local rifle = char and char:FindFirstChild("HeroSniper")
		local muzzle = from
		if rifle then
			for _, p in rifle:GetChildren() do
				if p:IsA("BasePart") and p.Shape == Enum.PartType.Cylinder and p.Size.X > 2 then
					muzzle = (p.CFrame * CFrame.new(-p.Size.X / 2, 0, 0)).Position
				end
			end
		end
		local flash = newPart(Vector3.one * 0.6, CFrame.new(muzzle), Color3.fromRGB(255, 230, 150), Enum.Material.Neon, Enum.PartType.Ball)
		tween(flash, 0.08, { Size = Vector3.one * 2.4, Transparency = 1 })
		cleanup(flash, 0.12)
		beam(muzzle, to, 0.28, Color3.new(1, 1, 1), Color3.fromRGB(255, 220, 140), 0.25)
		sparks(to, 0.4, Color3.new(1, 1, 1), Color3.fromRGB(255, 200, 120), 14)
		if not data.Target then
			dustPuffs(to, 0.35, 3, Color3.fromRGB(190, 180, 170), 0.6, false)
		else
			VFX.PlaySound("SniperHit", to, 1)
		end
		VFX.PlaySound("SniperShot", muzzle, 1)
		VFX.ShakeAt(muzzle, 1.2, 40, 0.15)
		if isMine(char) and data.Headshot then
			VFX.Hooks.Callout("HEADSHOT!", Color3.fromRGB(255, 90, 70))
		end
	end

	local liveBombs = {}

	function Effects.BombThrow(char, data)
		local from, vel, g = data.From, data.Vel, data.Gravity or workspace.Gravity
		if typeof(from) ~= "Vector3" or typeof(vel) ~= "Vector3" then
			return
		end
		VFX.Pose(char, "Throw", 0.3)
		VFX.PlaySound("BombThrow", from, 1)
		local land, landT = data.Land or from, data.LandTime or 1
		local bomb = newPart(Vector3.one * 1.4, CFrame.new(from), Color3.fromRGB(28, 28, 32), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
		local fuse = newPart(Vector3.new(0.25, 0.5, 0.25), CFrame.new(from), Color3.fromRGB(150, 120, 90))
		local stop = addTrail(bomb, Color3.fromRGB(255, 160, 60), 0.2, 0.5)
		local light = Instance.new("PointLight")
		light.Color = Color3.fromRGB(255, 80, 40)
		light.Range = 8
		light.Parent = bomb
		table.insert(liveBombs, bomb)
		local t0 = os.clock()
		local boomAt = landT + (data.Fuse or 0.7)
		while bomb.Parent do
			local t = os.clock() - t0
			if t >= boomAt + 0.3 then
				break
			end
			local p = t < landT and (from + vel * t - UP * (0.5 * g * t * t)) or land
			bomb.CFrame = CFrame.new(p) * CFrame.Angles(t * 9, t * 5, 0)
			fuse.CFrame = bomb.CFrame * CFrame.new(0, 0.85, 0)
			if rng:NextNumber() < 0.4 then
				sparks(fuse.Position + UP * 0.3, 0.12, Color3.new(1, 1, 1), Color3.fromRGB(255, 180, 60), 2)
			end
			-- blinks faster and faster once it's stuck
			bomb.Color = (t > landT and (t * (4 + 10 * (t - landT))) % 1 < 0.5) and Color3.fromRGB(230, 40, 30) or Color3.fromRGB(28, 28, 32)
			task.wait()
		end
		stop()
		local i = table.find(liveBombs, bomb)
		if i then
			table.remove(liveBombs, i)
		end
		bomb:Destroy()
		fuse:Destroy()
	end

	function Effects.BombBoom(_, data)
		local pos = data.Pos
		if typeof(pos) ~= "Vector3" then
			return
		end
		-- the bomb that's sitting there goes up with it
		for _, bomb in table.clone(liveBombs) do
			if (bomb.Position - pos).Magnitude < 6 then
				bomb:Destroy()
			end
		end
		toonExplosion(pos, math.max((data.Radius or 16) / 7, 1.4))
		VFX.PlaySound("BombBoom", pos, 1)
		VFX.ShakeAt(pos, 3, 120, 0.45)
	end

	-- the hair's one Detroit Smash: a smaller cousin of the real thing
	function Effects.HairSmash(char, data)
		local root = charParts(char)
