		chargeFist(char, root, 0.4, 1.2)
		if not root.Parent then
			return
		end
		local origin = root.Position + d * 3 + UP
		if nearCamera(origin, 90) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
		end
		windBlast(origin, d, 2)
		for i = 1, 6 do
			task.delay(i * 0.03, function()
				shockDisc(origin, d, 10, 44, 0.55, WIND, 100)
			end)
		end
		for s = 10, 100, 15 do
			task.delay(s / 240, function()
				local p = groundPoint(origin + d * s + d:Cross(UP) * rand(-6, 6))
				dustPuffs(p, 1.6 + s / 70, 4, Color3.fromRGB(206, 196, 186), 1.2, true)
				if s % 30 == 10 then
					rocks(p, 1.4, 4)
				end
			end)
