				RightLeg = -10, LeftLeg = 12, RightKnee = 6, LeftKnee = 22, Hips = { 0, 0, 0, 0, -0.1, 0 },
			},
			t = 0.17, hold = 0.06, style = Enum.EasingStyle.Sine,
		},
	}, 7)
	MOTIONS.EmoteFlex = {
		{ pose = { RightArm = { 100, 0, 70 }, RightElbow = 125, LeftArm = { 100, 0, 70 }, LeftElbow = 125, Waist = { 10, 0, 0 }, Neck = { -12, 0, 0 }, RightLeg = 8, LeftLeg = -8 }, t = 0.14, hold = 0.5, style = Enum.EasingStyle.Back },
		{ pose = { RightArm = { 104, 0, 76 }, RightElbow = 132, LeftArm = { 104, 0, 76 }, LeftElbow = 132, Waist = { 14, 0, 0 }, Neck = { -16, 0, 0 }, RightLeg = 8, LeftLeg = -8 }, t = 0.1, hold = 0.35 },
		{ pose = { RightArm = { 100, 0, 70 }, RightElbow = 125, LeftArm = { 100, 0, 70 }, LeftElbow = 125, Waist = { 10, 0, 0 }, Neck = { -12, 0, 0 }, RightLeg = 8, LeftLeg = -8 }, t = 0.1, hold = 0.6 },
		recover = 0.35,
	}
	MOTIONS.EmoteBow = {
		{ pose = { Waist = { -48, 0, 0 }, Neck = { 12, 0, 0 }, RightArm = { 6, 0, -4 }, LeftArm = { 6, 0, -4 } }, t = 0.35, hold = 0.7, style = Enum.EasingStyle.Sine },
		recover = 0.45,
	}
	MOTIONS.EmoteTaunt = looped({
		{ pose = { LeftArm = { 80, 0, -8 }, LeftElbow = 15, RightArm = { -20, 0, 30 }, RightElbow = 80, Waist = { -4, -20, 0 }, Neck = { 0, 14, 0 } }, t = 0.12, hold = 0.06 },
		{ pose = { LeftArm = { 84, 0, -8 }, LeftElbow = 85, RightArm = { -20, 0, 30 }, RightElbow = 80, Waist = { -4, -20, 0 }, Neck = { 0, 14, 0 } }, t = 0.12, hold = 0.06 },
	}, 4)

	-- THE JIGGY (was DAD MODE): 32 beats of dad dancing, each move on the beat (Bpm)
	do
		local B = 60 / 128
		local function beat(pose, beats, style)
			return { pose = pose, t = math.min(0.12, B * beats * 0.4), hold = B * beats - math.min(0.12, B * beats * 0.4), style = style or SNAP }
		end
		local m = { recover = 0.45 }
		local function add(step)
			table.insert(m, step)
		end
		-- 1-8: the disco point - up to the sky, down to the floor, hips popping
		local up = {
			RightArm = { 165, 0, -20 }, RightElbow = 0, LeftArm = { 10, 0, 30 }, LeftElbow = 10, Waist = { 6, -18, 10 },
			Hips = { 0, 0, 0, 0.25, 0, 0 }, RightLeg = 10, LeftLeg = -6, LeftKnee = 20, Neck = { -22, -15, 0 },
		}
		local down = {
			RightArm = { -35, 0, 40 }, RightElbow = 0, LeftArm = { 10, 0, 30 }, LeftElbow = 10, Waist = { -8, 18, -10 },
			Hips = { 0, 0, 0, -0.25, 0, 0 }, RightKnee = 25, LeftKnee = 8, Neck = { 18, 15, 0 },
		}
		for _ = 1, 4 do
			add(beat(up, 1))
			add(beat(down, 1))
		end
		-- 9-16: the sprinkler - tick, tick, tick... and whoosh back
		for _ = 1, 2 do
			for k = 1, 3 do
				add(beat({
					LeftArm = { 165, 0, -40 }, LeftElbow = 130, RightArm = { 90, 0, 0 }, RightElbow = 0,
					Waist = { 0, -15 * k, 0 }, Hips = { 0, -6 * k, 0, 0, -0.15, 0 }, RightKnee = 15, LeftKnee = 15, Neck = { 0, -8 * k, 0 },
				}, 1))
			end
			add(beat({
				LeftArm = { 165, 0, -40 }, LeftElbow = 130, RightArm = { 90, 0, 0 }, RightElbow = 0,
				Waist = { 0, 32, 0 }, Hips = { 0, 12, 0, 0, -0.15, 0 }, RightKnee = 15, LeftKnee = 15, Neck = { 0, 20, 0 },
			}, 1, Enum.EasingStyle.Back))
		end
		-- 17-24: the lawnmower - pull the cord (nothing), PULL (it starts), mow
		local crouch = { Waist = { -50, 10, 0 }, RightArm = { 40, 0, 10 }, RightElbow = 10, LeftArm = { 20, 0, 20 }, Neck = { 25, 0, 0 }, RightKnee = 30, LeftKnee = 30, Hips = { 0, 0, 0, 0, -0.4, 0 } }
		add(beat(crouch, 1))
		add(beat({ Waist = { 8, -22, 0 }, RightArm = { 150, 0, 30 }, RightElbow = 30, LeftArm = { 40, 0, 20 }, Neck = { -10, 0, 0 } }, 1))
		add(beat(crouch, 1))
		add(beat({ Waist = { 14, -30, 0 }, RightArm = { 172, 0, 40 }, RightElbow = 0, LeftArm = { 60, 0, 30 }, Neck = { -24, 0, 0 }, Hips = { 0, 0, 0, 0, 0.35, 0 } }, 1, Enum.EasingStyle.Back))
		for k = 1, 4 do
			local s = k % 2 == 0 and 1 or -1
			add(beat({
				RightArm = { 62, 0, 0 }, LeftArm = { 62, 0, 0 }, RightElbow = 30, LeftElbow = 30, Waist = { -15, 4 * s, 0 },
				RightLeg = 22 * s, LeftLeg = -22 * s, RightKnee = s > 0 and 30 or 8, LeftKnee = s > 0 and 8 or 30, Neck = { 6, 0, 0 },
			}, 1))
		end
		-- 25-30: the floss, double time
		for k = 1, 12 do
			local s = k % 2 == 0 and 1 or -1
			-- (both arms swung out to one side - one in front, one behind - the
			-- hips thrown the other way)
			add(beat({
				RightArm = { -35 * s, 0, s > 0 and 55 or -45 }, LeftArm = { 35 * s, 0, s > 0 and -45 or 55 }, RightElbow = 0, LeftElbow = 0,
				Hips = { 0, 10 * s, 0, -0.45 * s, 0, 0 }, Waist = { 0, -10 * s, 4 * s }, RightKnee = 14, LeftKnee = 14,
			}, 0.5))
		end
		-- 31-32: DAB
		add(beat({
			Neck = { -30, 34, 0 }, LeftArm = { 100, 0, -52 }, LeftElbow = 125, RightArm = { 30, 0, 128 }, RightElbow = 0,
			Waist = { -14, 24, 0 }, RightLeg = -8, LeftLeg = 12, LeftKnee = 14,
		}, 2, Enum.EasingStyle.Back))
		MOTIONS.EmoteDadMode = m
	end

	-- the party round a Party emote: a light-up dance floor under him, a disco
	-- ball over his head throwing coloured beams, notes floating off him, the
	-- song (heard nearby) and confetti on the last two beats. Returns stop().
	local function party(root, entry, total)
		local bpm, offset = entry.Bpm or 120, entry.Offset or 0
		local beatLen = 60 / bpm
		local colors = {
			Color3.fromRGB(255, 64, 160), Color3.fromRGB(64, 200, 255), Color3.fromRGB(255, 220, 60),
			Color3.fromRGB(120, 255, 110), Color3.fromRGB(190, 110, 255), Color3.fromRGB(255, 130, 50),
		}
		local g = groundPoint(root.Position)
		local parts = {}
		local tiles = {}
		for x = -1, 1 do
			for z = -1, 1 do
				local tile = newPart(Vector3.new(1.9, 0.12, 1.9), CFrame.new(g + Vector3.new(x * 2, 0.07, z * 2)), colors[1], Enum.Material.Neon)
				tile.Transparency = 0.15
				table.insert(tiles, { part = tile, i = (x + 1) + (z + 1) * 3 })
				table.insert(parts, tile)
			end
		end
		local ballAt = root.Position + UP * 6.5
		local ball = newPart(Vector3.one * 1.8, CFrame.new(ballAt), Color3.fromRGB(215, 220, 230), Enum.Material.Foil, Enum.PartType.Ball)
		ball.Reflectance = 0.6
		local cord = newPart(Vector3.new(0.06, 3, 0.06), CFrame.new(ballAt + UP * 2.4), Color3.fromRGB(40, 40, 44))
		table.insert(parts, ball)
		table.insert(parts, cord)
		local light = Instance.new("PointLight")
		light.Range = 16
		light.Brightness = 3
		light.Color = colors[2]
		light.Parent = ball
		local beams = {}
		for k = 1, 4 do
			local beam = newPart(Vector3.new(0.14, 0.14, 7), CFrame.new(ballAt), colors[k], Enum.Material.Neon)
			beam.Transparency = 0.35
			beams[k] = beam
			table.insert(parts, beam)
		end
		local sound = Instance.new("Sound")
		sound.Name = "PartySong"
		local songId, songVolume = VFX.EmoteSong(entry)
		sound.SoundId = songId or ((Config.Music and Config.Music.Disco) or "")
		sound.Volume = songVolume or 0.8
		sound.RollOffMode = Enum.RollOffMode.InverseTapered
		sound.RollOffMinDistance = 12
		sound.RollOffMaxDistance = 90
		sound.Parent = root
		pcall(function()
			sound:Play()
		end)
		local t0 = os.clock()
		local lastBeat = -1
		local confetti = false
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			local b = math.floor((t - offset) / beatLen)
			local spin = t * 2.2
			ball.CFrame = CFrame.new(ballAt) * CFrame.Angles(0, spin, 0)
			for k, beam in beams do
				local a = spin + k * math.pi / 2
				local dir = Vector3.new(math.cos(a) * 0.8, -0.6, math.sin(a) * 0.8).Unit
				beam.CFrame = CFrame.lookAt(ballAt + dir * 4.4, ballAt + dir * 9)
			end
			if b ~= lastBeat and b >= 0 then
				lastBeat = b
				-- the floor lights up on the beat: a checkerboard, flipping, new colours
				for _, tile in tiles do
					local on = (tile.i + b) % 2 == 0
					tile.part.Color = colors[(tile.i + b) % #colors + 1]
					tile.part.Transparency = on and 0.05 or 0.6
				end
				light.Color = colors[b % #colors + 1]
				for k, beam in beams do
					beam.Color = colors[(b + k) % #colors + 1]
				end
				-- a note floating up off him
				local noteAnchor = newPart(Vector3.one * 0.1, CFrame.new(root.Position + UP * 2.5 + Vector3.new(rand(-1.5, 1.5), 0, rand(-1.5, 1.5))), Color3.new(), nil)
				noteAnchor.Transparency = 1
				local bb = Instance.new("BillboardGui")
				bb.Size = UDim2.fromOffset(40, 40)
				bb.AlwaysOnTop = false
				bb.MaxDistance = 90
				bb.Parent = noteAnchor
				local label = Instance.new("TextLabel")
				label.Size = UDim2.fromScale(1, 1)
				label.BackgroundTransparency = 1
				label.Text = b % 2 == 0 and "♪" or "♫"
				label.TextScaled = true
				label.Font = Enum.Font.GothamBlack
				label.TextColor3 = colors[b % #colors + 1]
				label.TextStrokeTransparency = 0
				label.Parent = bb
				tween(noteAnchor, beatLen * 3, { CFrame = noteAnchor.CFrame + UP * 4 + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) }, Enum.EasingStyle.Sine)
				tween(label, beatLen * 3, { TextTransparency = 1, TextStrokeTransparency = 1 })
				cleanup(noteAnchor, beatLen * 3 + 0.05)
				-- (the dab: confetti everywhere)
				if not confetti and b >= 30 then
					confetti = true
					for _ = 1, 40 do
						local bit = newPart(Vector3.new(0.3, 0.05, 0.2), CFrame.new(root.Position + UP * 2) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), colors[rng:NextInteger(1, #colors)], Enum.Material.SmoothPlastic)
						local out = Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * rand(3, 7)
						tween(bit, 0.35, { CFrame = bit.CFrame + out + UP * rand(4, 8) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
						task.delay(0.35, function()
							tween(bit, 1.2, { CFrame = bit.CFrame * CFrame.Angles(rand(-3, 3), rand(-3, 3), rand(-3, 3)) - UP * 6, Transparency = 1 }, Enum.EasingStyle.Sine)
						end)
						cleanup(bit, 1.6)
					end
					VFX.PlaySound("Confetti", root.Position, 1)
				end
			end
			if t > total + 0.3 then
				conn:Disconnect()
			end
		end)
		local stopped = false
		return function()
			if stopped then
				return
			end
			stopped = true
			conn:Disconnect()
			tween(sound, 0.35, { Volume = 0 })
			task.delay(0.36, function()
				pcall(function()
					sound:Stop()
				end)
				sound:Destroy()
			end)
			for _, p in parts do
				tween(p, 0.3, { Transparency = 1 })
				cleanup(p, 0.35)
			end
		end
	end

	function Effects.Emote(char, data)
		local id = typeof(data.Id) == "string" and data.Id or ""
		local motion = MOTIONS["Emote" .. id]
		local root = charParts(char)
		if not motion or not root then
			return
		end
		VFX.Motion(char, "Emote" .. id)
		local token = poseTokens[char]
		local entry
		for _, e in Config.Emotes or {} do
			if e.Id == id then
				entry = e
				if e.Say then
					VFX.SpeechBubble(char, e.Say, 1.6)
				end
			end
		end
		local total = 0
		for _, step in ipairs(motion) do
			total += (step.t or 0.08) + (step.hold or 0)
		end
		local stop = entry and entry.Party and party(root, entry, total)
		local t0 = os.clock()
		while os.clock() - t0 < total do
			task.wait(0.05)
			if poseTokens[char] ~= token or not root.Parent then
				break -- (something else took the body over)
			end
			local v = root.AssemblyLinearVelocity
			if Vector3.new(v.X, 0, v.Z).Magnitude > 4 or math.abs(v.Y) > 12
				or char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") then
				VFX.ReleasePose(char, 0.15)
				break
			end
		end
		if stop then
			stop()
		end
	end
end

local TARGET_OWNED = { Hit = true, Guard = true, Parry = true, GuardBreak = true, Block = true }
-- effects that mean a fight is on (for the fighting-stance idle)
local COMBAT_FX = { Punch = true, Hit = true, Guard = true, Block = true, Parry = true, GuardBreak = true }

function VFX.Play(effectId, char, data, isLocal)
	local fn = Effects[effectId]
	if not fn then
		return
	end
	data = data or {}
	local owner = char
	if TARGET_OWNED[effectId] and typeof(data.Target) == "Instance" then
		owner = data.Target
	end
	if COMBAT_FX[effectId] and VFX.MarkCombat then
		-- they're fighting: their idle becomes a guard for a few seconds
		VFX.MarkCombat(char)
		if typeof(data.Target) == "Instance" then
			VFX.MarkCombat(data.Target)
		end
	end
	local info, window = animationFor(effectId, data)
	if info and owner and rigMatches(owner) and Players:GetPlayerFromCharacter(owner) then
		poseBlockedUntil[owner] = os.clock() + math.max(window, info.Length or 0)
		VFX.ReleasePose(owner, 0.1)
		local me = Players.LocalPlayer
		if me and me.Character == owner then
			VFX.PlayAnimation(owner, info)
		end
	end
	task.spawn(function()
		local ok, err = pcall(fn, char, data, isLocal, Config.FindAbilityById(effectId))
		if not ok then
			warn("[VFX] " .. tostring(effectId) .. " failed: " .. tostring(err))
		end
	end)
	-- (round 76) the voice lines that go with it (Config.VoiceCues.Moves)
	if VFX.VC then
		pcall(VFX.VC.onPlay, effectId, char)
	end
end

---------------------------------------------------------------------------
-- SWINGING (Kamui Woods' branches, Suneater's tentacle), the way Insomniac's
-- Spider-Man does it: the line goes out to something tall - either side of
-- the street, up ahead - but the swing itself keeps him on HIS line. The
-- anchor is brought round onto the way he's going and he pendulums along
-- it, so he travels straight down the street instead of being dragged at the
-- building. Momentum carries through (a swing into a swing only gets
-- faster); holding a direction bends the next swing towards it a little.
-- The swinger's own screen moves him (a LinearVelocity along the arc) and
-- lets go flying at the end; everyone else just sees the line.
---------------------------------------------------------------------------
do
	local SW = {
		active = setmetatable({}, { __mode = "k" }), -- [char] = the swing going
		carries = setmetatable({}, { __mode = "k" }), -- [char] = the fling after one
	}

	-- the way he's travelling: his momentum if he's moving (a swing out of a
	-- swing), else where he's looking; a held direction turns it a little
	-- (at most 40 degrees a swing), letting go of the stick keeps him straight
	local function travelDir(root, hum, fallback)
		local v = root.AssemblyLinearVelocity
		local flat = Vector3.new(v.X, 0, v.Z)
		local f = flat.Magnitude > 30 and flat.Unit or fallback
		local want = hum and hum.MoveDirection or Vector3.zero
		want = Vector3.new(want.X, 0, want.Z)
		if want.Magnitude > 0.1 then
			want = want.Unit
			local angle = math.acos(math.clamp(f:Dot(want), -1, 1))
			if angle > 1e-3 then
				local turned = f:Lerp(want, math.min(1, math.rad(40) / angle))
				f = turned.Magnitude > 1e-3 and turned.Unit or want
			end
		end
		return f
	end
	VFX.SwingDirection = travelDir

	-- something a line can hold on to: solid map, not an invisible wall, a
	-- walk-through prop or anyone's stuff (a ray goes on through those)
	local function solidHit(origin, ray, range, params)
		local dir = ray.Unit
		local from, left = origin, range
		for _ = 1, 4 do
			local hit = workspace:Raycast(from, dir * left, params)
			local part = hit and hit.Instance
			if not (part and part:IsA("BasePart") and (part.Transparency > 0.95 or not part.CanCollide)) then
				return hit
			end
			local gone = (hit.Position - from).Magnitude + 0.05
			from, left = from + dir * gone, left - gone
			if left <= 1 then
				return nil
			end
		end
		return nil
	end
	VFX.SwingHit = solidHit

	-- a point to swing from: something above his head, along his line and
	-- high - where he's aiming first (if that's up at something), else the
	-- best of a dense fan up, ahead and to either side (Config.SwingScore)
	function VFX.SwingAnchor(char, aim, range)
		local root, hum = charParts(char)
		if not root then
			return nil
		end
		range = range or 110
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = characterList()
		local origin = root.Position + UP * 2
		local look = travelDir(root, hum, flatten(typeof(aim) == "Vector3" and aim or root.CFrame.LookVector, root))
		local right = look:Cross(UP)
		local best, bestScore
		local function try(ray, bonus)
			local hit = solidHit(origin, ray, range, params)
			if hit and hit.Position.Y > root.Position.Y + 3 then
				local rel = hit.Position - root.Position
				local ahead = rel:Dot(look)
				if ahead > -4 then
					-- (off to the side is fine - the swing stays on his line - unless
					-- it's a long way off it)
					local score = Config.SwingScore(ahead, rel.Y, math.abs(rel:Dot(right))) + (bonus or 0)
					if not bestScore or score > bestScore then
						best, bestScore = hit.Position + hit.Normal * 0.3, score
					end
				end
			end
		end
		if typeof(aim) == "Vector3" and aim.Magnitude > 0.01 and aim.Unit.Y > 0.15 then
			try(aim, 25)
		end
		for _, pitch in Config.SwingFan.Pitches do
			for _, yaw in Config.SwingFan.Yaws do
				local a, p = math.rad(yaw), math.rad(pitch)
				local flat = look * math.cos(a) + right * math.sin(a)
				try(flat * math.cos(p) + UP * math.sin(p))
			end
		end
		return best
	end

	function VFX.Swinging(char)
		return SW.active[char] ~= nil
	end

	-- let go now (R again, another move, a knock, a dash) - and no carrying
	-- on the fling from the last one either
	function VFX.SwingRelease(char)
		local st = SW.active[char]
		if st then
			st.release = true
		end
		SW.carries[char] = nil
	end

	-- after letting go: the fling keeps its speed a while (`time`, easing off
	-- a little), so steering in the air bends it but can't eat it. It stops
	-- when he lands, hits a wall, swings again, gets hit or another move or
	-- a dash takes over.
	function SW.carry(char, root, hum, flatV, time)
		local c = {}
		SW.carries[char] = c
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = characterList()
		task.spawn(function()
			local t0 = os.clock()
			RunService.Heartbeat:Wait()
			while root.Parent and SW.carries[char] == c and not SW.active[char] do
				local t = os.clock() - t0
				if t > time or char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed") then
					break
				end
				if hum and hum.FloorMaterial ~= Enum.Material.Air then
					break
				end
				local want = flatV * (1 - 0.3 * t / time)
				local speed = want.Magnitude
				local v = root.AssemblyLinearVelocity
				local have = Vector3.new(v.X, 0, v.Z)
				local along = have:Dot(want.Unit)
				if along < speed then
					if workspace:Raycast(root.Position, want.Unit * math.max(speed * 0.08, 2.5), params) then
						break -- (a wall: he stops against it, not stuck to it)
					end
					-- (topped back up along the fling; the sideways part is the
					-- player steering, and it stays)
					root.AssemblyLinearVelocity = want + (have - want.Unit * along) + Vector3.new(0, v.Y, 0)
				end
				RunService.Heartbeat:Wait()
			end
			if SW.carries[char] == c then
				SW.carries[char] = nil
			end
		end)
		return c
	end
	VFX.SwingCarrying = function(char)
		return SW.carries[char] ~= nil
	end

	-- opts: Time (at most), Speed (along the arc), Exit (speed he lets go
	-- at), Lift (extra up on letting go), Carry (how long the fling keeps
	-- its speed), Range (longest line), OnEnd(). Only for your own
	-- character: it moves the body.
	function VFX.Swing(char, anchor, opts)
		opts = opts or {}
		local root, hum = charParts(char)
		if not root or typeof(anchor) ~= "Vector3" then
			return nil
		end
		local old = SW.active[char]
		if old then
			old.release = true
		end
		local st = { release = false }
		SW.active[char] = st
		SW.carries[char] = nil
		local cam = workspace.CurrentCamera
		local f = travelDir(root, hum, flatten(cam and cam.CFrame.LookVector or root.CFrame.LookVector, root))
		-- the anchor, brought round onto his line (always a little ahead of
		-- him: a swoop down and up, not a hop)
		local p0 = root.Position
		local rel = anchor - p0
		local height = math.max(rel.Y, 6)
		local ahead = rel:Dot(f)
		-- (caught on a wall across his way: the swing crests before it, and
		-- the glance off it at the end carries him on up it)
		local wallParams = RaycastParams.new()
		wallParams.FilterType = Enum.RaycastFilterType.Exclude
		wallParams.FilterDescendantsInstances = characterList()
		local caught = workspace:Raycast(p0 + UP * 2, rel + rel.Unit * 2, wallParams)
		if caught and caught.Normal:Dot(f) < -0.5 then
			ahead -= rel.Magnitude * 0.55
		end
		ahead = math.max(ahead, height * 0.35)
		local pivot = p0 + f * ahead + UP * height
		local r0 = p0 - pivot
		local L = math.clamp(r0.Magnitude, 6, opts.Range or 120)
		local th0 = math.clamp(math.atan2(r0:Dot(f), -r0.Y), -1.4, 0.3)
		-- (he lets go on the way up, about 40 degrees past the bottom: flying
		-- on down the street more than up into the sky)
		local th1 = math.clamp(-th0 * 0.55 + 0.25, 0.45, 0.8)
		-- (the bottom of the arc stays off the street)
		local floor = groundRay(pivot - UP * 2, 220)
		local lowest = pivot.Y - ((floor and floor.Position.Y or pivot.Y - 220) + 3.4)
		local Lb = math.min(L, math.max(lowest, 4))
		-- momentum: already going fast, he swings faster (and lets go faster)
		local v0 = root.AssemblyLinearVelocity
		local carried = math.max(v0:Dot(f), 0)
		local speed = math.max(opts.Speed or 85, carried * 1.08)
		local T = math.clamp(L * (th1 - th0) / speed, 0.5, opts.Time or 1.4)
		local exitSpeed = math.max(opts.Exit or 62, math.min(carried * 0.9, 120))
		local att = Instance.new("Attachment")
		att.Name = "SwingAttachment"
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 20000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.Parent = root
		cleanup(lv, T + 0.3)
		cleanup(att, T + 0.3)
		if hum then
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.Freefall)
			end)
		end
		face(root, f)
		local function at(t)
			local s = math.clamp(t / T, 0, 1)
			local e = (1 - math.cos(math.pi * s)) / 2
			local th = th0 + (th1 - th0) * e
			local len = L - (L - Lb) * math.clamp(1 - math.abs(th) / 1.3, 0, 1)
			return pivot + f * math.sin(th) * len - UP * math.cos(th) * len, th
		end
		-- (a wall in the way: he doesn't smack into it, he glances off along it)
		st.T = T
		st.Dir = f
		task.spawn(function()
			local t0 = os.clock()
			local wall
			while root.Parent and SW.active[char] == st and not st.release do
				if char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed") then
					break
				end
				local t = os.clock() - t0
				local p1 = at(t)
				local p2 = at(t + 1 / 60)
				local step = (p2 - p1) * 60
				if step.Magnitude > 1 then
					local hit = workspace:Raycast(root.Position, step * 0.1, wallParams)
					if hit and math.abs(hit.Normal.Y) < 0.6 then
						wall = hit.Normal
						break
					end
				end
				lv.VectorVelocity = step + (p1 - root.Position) * 10
				if t >= T then
					break
				end
				RunService.Heartbeat:Wait()
			end
			local _, th = at(math.min(os.clock() - t0, T))
			lv:Destroy()
			att:Destroy()
			local mine = SW.active[char] == st
			if mine then
				SW.active[char] = nil
			end
			-- let go, flying on along the swing (unless a new swing took over)
			if mine and root.Parent and not (char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed")) then
				local tangent = (f * math.cos(th) + UP * math.sin(th)).Unit
				local out = tangent * exitSpeed + UP * (6 + (opts.Lift or 0))
				if wall then
					-- (the speed he had into the wall carries him up it instead)
					local into = math.max(-out:Dot(wall), 0)
					out = out - wall * out:Dot(wall) + UP * into * 0.7 + wall * 6
				end
				root.AssemblyLinearVelocity = out
				if opts.Carry and not wall and not st.release then
					SW.carry(char, root, hum, Vector3.new(out.X, 0, out.Z), opts.Carry)
				end
			end
			if opts.OnEnd then
				opts.OnEnd()
			end
		end)
		return st
	end

	-- (round 60) THE ZIP (Spider-Man's web zip / point launch): something's
	-- caught hold of `anchor` and reels him in along a straight line to it -
	-- quick, and quicker as he goes - and he ends up ON it: over the lip onto
	-- the roof (opts.Ledge, or a roof it caught), clinging to the wall a
	-- moment (a wall lower down), or carried on (open air). JUMP on the way,
	-- or on the wall, and he doesn't stop there: POINT LAUNCH - flung up and
	-- on over it. opts: Normal (the face it caught), Ledge, Speed, Accel,
	-- MaxTime, Cling, LaunchUp, LaunchForward, OnLaunch(), OnEnd(launched).
	-- Only for your own character: it moves the body.
	function VFX.Zip(char, anchor, opts)
		opts = opts or {}
		local root, hum = charParts(char)
		if not root or typeof(anchor) ~= "Vector3" then
			return nil
		end
		local normal = typeof(opts.Normal) == "Vector3" and opts.Normal.Magnitude > 0.1 and opts.Normal.Unit or nil
		local wall = normal ~= nil and math.abs(normal.Y) < 0.6
		local roof = normal ~= nil and normal.Y >= 0.6
		local ledge = opts.Ledge == true or roof
		-- (where his body ends up: hanging off the face with his hand on the
		-- spot - just under the lip for a ledge - or standing on the roof)
		local stop
		if roof then
			stop = anchor + UP * 3
		elseif wall then
			stop = anchor + normal * 1.7 - UP * (ledge and 1.4 or 2)
		else
			stop = anchor - UP * 2
		end
		local line = stop - root.Position
		if line.Magnitude < 1.5 then
			return nil
		end
		local old = SW.active[char]
		if old then
			old.release = true
		end
		local st = { release = false, zip = true, launch = false }
		SW.active[char] = st
		SW.carries[char] = nil
		local dir = line.Unit
		local flat = Vector3.new(dir.X, 0, dir.Z)
		if flat.Magnitude < 0.1 then
			flat = wall and -Vector3.new(normal.X, 0, normal.Z) or Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
		end
		flat = flat.Unit
		st.Dir = flat
		local speed = opts.Speed or 150
		local start = math.clamp(root.AssemblyLinearVelocity:Dot(dir), 45, speed)
		local accel = math.max(opts.Accel or 0.18, 0.01)
		local maxT = opts.MaxTime or 1.4
		local att = Instance.new("Attachment")
		att.Name = "ZipAttachment"
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Name = "Zip"
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 30000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.VectorVelocity = dir * start
		lv.Parent = root
		cleanup(lv, maxT + 1.5)
		cleanup(att, maxT + 1.5)
		if hum then
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.Freefall)
			end)
		end
		face(root, flat)
		-- (a jump on the way: the point launch, as he gets there)
		local jumpConn = game:GetService("UserInputService").JumpRequest:Connect(function()
			st.launch = true
		end)
		local wallParams = RaycastParams.new()
		wallParams.FilterType = Enum.RaycastFilterType.Exclude
		wallParams.FilterDescendantsInstances = characterList()
		local function tied()
			return char:GetAttribute("Stunned") or char:GetAttribute("Ragdolled") or char:GetAttribute("Grabbed")
		end
		local function drop()
			if lv.Parent then
				lv:Destroy()
			end
			if att.Parent then
				att:Destroy()
			end
		end
		task.spawn(function()
			local t0 = os.clock()
			while root.Parent and SW.active[char] == st and not st.release and not tied() do
				local t = os.clock() - t0
				local left = stop - root.Position
				if left.Magnitude < 2.2 or left:Dot(dir) < 0 or t > maxT then
					break
				end
				local v = start + (speed - start) * math.clamp(t / accel, 0, 1)
				-- (anything solid in the way before the spot: he's there, against it)
				local ahead = math.min(v / 30 + 1.5, left.Magnitude - 0.5)
				if left.Magnitude > 4 and workspace:Raycast(root.Position, left.Unit * ahead, wallParams) then
					break
				end
				lv.VectorVelocity = left.Unit * v
				RunService.Heartbeat:Wait()
			end
			local ok = root.Parent and SW.active[char] == st and not st.release and not tied()
			if ok and st.launch then
				-- POINT LAUNCH: up and on, over it
				drop()
				SW.active[char] = nil
				local out = UP * (opts.LaunchUp or 88) + flat * (opts.LaunchForward or 58)
				root.AssemblyLinearVelocity = out
				SW.carry(char, root, hum, flat * (opts.LaunchForward or 58), 0.9)
				if opts.OnLaunch then
					opts.OnLaunch()
				end
			elseif ok and ledge then
				-- over the lip onto the roof
				local over = wall and -Vector3.new(normal.X, 0, normal.Z).Unit or flat
				lv.VectorVelocity = UP * 34 + over * 14
				task.wait(0.2)
				if lv.Parent then
					lv.VectorVelocity = over * 18
				end
				task.wait(0.08)
				drop()
				if root.Parent then
					root.AssemblyLinearVelocity = over * 10
				end
			elseif ok and wall then
				-- he clings to the wall a moment - a jump off it launches him
				local away = Vector3.new(normal.X, 0, normal.Z).Unit
				face(root, -away)
				lv.VectorVelocity = Vector3.zero
				st.clinging = true
				local t1 = os.clock()
				while os.clock() - t1 < (opts.Cling or 0.45) and not st.launch and SW.active[char] == st and not st.release and not tied() do
					RunService.Heartbeat:Wait()
				end
				st.clinging = false
				drop()
				if root.Parent and st.launch and not tied() then
					root.AssemblyLinearVelocity = UP * (opts.LaunchUp or 88) * 0.85 + away * 32
					if opts.OnLaunch then
						opts.OnLaunch()
					end
				elseif root.Parent then
					root.AssemblyLinearVelocity = away * 12 + UP * 6
				end
			else
				drop()
				if ok then
					-- (open air: carried on past it)
					root.AssemblyLinearVelocity = dir * 40 + UP * 10
					SW.carry(char, root, hum, flat * 40, 0.5)
				end
			end
			drop()
			if SW.active[char] == st then
				SW.active[char] = nil
			end
			jumpConn:Disconnect()
			if opts.OnEnd then
				opts.OnEnd(ok and st.launch)
			end
		end)
		return st
	end
	-- is he being zipped along right now? (a jump then is the point launch,
	-- not a wall hop)
	function VFX.Zipping(char)
		local st = SW.active[char]
		return st ~= nil and st.zip == true
	end
end

---------------------------------------------------------------------------
-- KAMUI WOODS (Shinji Nishiya): Arbor. Everything he grows is blocky timber
-- in the game's style: square branches in two browns (the grain shows as
-- the shades alternating), stubby twigs, plenty of square autumn-orange
-- leaves; cages of square bars; roots; stakes with wedge points and trunks
-- with bark stripes, sprouting leaves.
---------------------------------------------------------------------------
do
	local KW = {
		WOOD = Color3.fromRGB(150, 94, 52),
		DARK = Color3.fromRGB(104, 62, 34),
		LIGHT = Color3.fromRGB(190, 134, 82),
		LEAF = Color3.fromRGB(236, 128, 36), -- (autumn orange)
		LEAF_DARK = Color3.fromRGB(198, 84, 28),
		LEAF_GOLD = Color3.fromRGB(248, 178, 58),
		DUST = Color3.fromRGB(204, 196, 184),
		arms = setmetatable({}, { __mode = "k" }), -- [char] = the branch out of his arm
		cages = setmetatable({}, { __mode = "k" }), -- [target] = the cage round them
		states = setmetatable({}, { __mode = "k" }), -- [char] = the slingshot going
	}
	VFX.KW = KW

	-- the three leaf shades, turn and turn about (or at random)
	local LEAVES = { KW.LEAF, KW.LEAF_DARK, KW.LEAF_GOLD }
	function KW.leafColor(i)
		return LEAVES[i and (math.floor(i) % 3 + 1) or rng:NextInteger(1, 3)]
	end

	-- a square leaf (a thin tile)
	function KW.leafPart(size, cf, i)
		return newPart(Vector3.new(size, 0.08, size), cf, KW.leafColor(i), Enum.Material.Grass)
	end

	-- A branch: a chain of square wood segments tapering to the tip, the
	-- shades alternating, a twig off every third one and a leaf off every
	-- other one, sides alternating.
	-- b.set(from, to, bend, wiggle) redraws it; b.fade(time) makes it go.
	function KW.branch(thick, segs)
		segs = segs or 8
		local b = { parts = {}, twigs = {}, phase = rand(0, 6) }
		for i = 1, segs do
			b.parts[i] = newPart(Vector3.new(thick, thick, 0.2), CFrame.new(), i % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood)
			if i % 3 == 0 and i < segs then
				table.insert(b.twigs, { seg = i, side = (i % 2 == 0) and 1 or -1, part = newPart(Vector3.one * 0.2, CFrame.new(), KW.DARK, Enum.Material.Wood) })
			end
			if i % 2 == 0 and i < segs then
				table.insert(b.twigs, { seg = i, side = (i % 4 == 0) and -1 or 1, leaf = true, part = KW.leafPart(0.2, CFrame.new(), i) })
			end
		end
		local frames = {}
		function b.set(from, to, bend, wiggle)
			local span = to - from
			local len = span.Magnitude
			if len < 0.05 then
				return
			end
			local dir = span / len
			local ref = math.abs(dir.Y) < 0.9 and UP or Vector3.new(1, 0, 0)
			local side = dir:Cross(ref).Unit
			local up = side:Cross(dir).Unit
			local now = os.clock()
			local function at(k)
				local wave = math.sin(k * math.pi * 3 + now * 6 + b.phase) * (wiggle or 0.2) * k
				return from + span * k + up * math.sin(k * math.pi) * (bend or 0) + side * wave
			end
			local prev = at(0)
			for i, p in b.parts do
				local k = i / segs
				local nextP = at(k)
				local w = thick * (1 - 0.5 * (k - 1 / segs))
				local seg = nextP - prev
				local segLen = seg.Magnitude
				if segLen > 0.01 then
					local fwd = seg / segLen
					local top = up - fwd * up:Dot(fwd)
					top = top.Magnitude > 0.01 and top.Unit or side:Cross(fwd).Unit
					local cf = CFrame.fromMatrix((prev + nextP) / 2, fwd:Cross(top), top, -fwd)
					p.Size = Vector3.new(w, w, segLen + w * 0.1)
					p.CFrame = cf
					frames[i] = { cf = cf, w = w, len = segLen }
				end
				prev = nextP
			end
			for _, t in b.twigs do
				local f = frames[t.seg]
				if f then
					if t.leaf then
						local size = math.max(f.w * 1.25, 0.5)
						t.part.Size = Vector3.new(size, 0.08, size)
						t.part.CFrame = f.cf * CFrame.new(t.side * (f.w / 2 + size * 0.45), f.w * 0.3, 0) * CFrame.Angles(0, math.rad(45), math.rad(t.side * 24))
					else
						t.part.Size = Vector3.new(f.w * 0.4, f.w * 0.4, f.w * 1.6)
						t.part.CFrame = f.cf * CFrame.new(t.side * f.w * 0.55, 0, 0) * CFrame.Angles(0, math.rad(t.side * 50), 0) * CFrame.new(0, 0, -f.w * 0.5)
					end
				end
			end
		end
		function b.fade(time)
			for _, p in b.parts do
				tween(p, time or 0.2, { Transparency = 1, Size = p.Size * Vector3.new(0.3, 0.3, 1) })
				cleanup(p, (time or 0.2) + 0.05)
			end
			for _, t in b.twigs do
				tween(t.part, time or 0.2, { Transparency = 1 })
				cleanup(t.part, (time or 0.2) + 0.05)
			end
		end
		return b
	end

	-- a branch out of his arm toward `goal` (it grows there over reachTime)
	-- and holds on: to a spot, or to someone (arm.target) - until arm.life
	-- runs out or arm.retract is set (it shrinks back into his hand)
	function KW.reach(char, thick, segs, goal, bend, reachTime, right)
		local old = KW.arms[char]
		if old then
			old.done = true
		end
		local arm = { branch = KW.branch(thick, segs), goal = goal, bend = bend or 1, t0 = os.clock(), reachTime = reachTime or 0.14, life = 0.7, done = false }
		KW.arms[char] = arm
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - arm.t0
			local troot = arm.target and arm.target:FindFirstChild("HumanoidRootPart")
			if arm.done or not char.Parent or t > arm.life or (arm.target and not (troot and troot.Parent)) then
				conn:Disconnect()
				arm.branch.fade(0.2)
				if KW.arms[char] == arm then
					KW.arms[char] = nil
				end
				return
			end
			local from = handPos(char, right ~= false)
			local goalPos = troot and troot.Position or arm.goal
			local k = math.clamp(t / arm.reachTime, 0, 1)
			if arm.retract then
				k = 1 - math.clamp((os.clock() - arm.retract) / 0.15, 0, 1)
				if k <= 0 then
					arm.done = true
				end
			end
			arm.branch.set(from, from:Lerp(goalPos, k), arm.bend * (1 - k * 0.6), 0.15)
		end)
		return arm
	end

	-- the Lacquered Chain Prison: a blocky cage round someone - four corner
	-- posts and three square hoops of bars - tightening as it closes. It
	-- follows them; c.crush() splinters it apart, c.fade() just lets go.
	function KW.cage(target, duration)
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return nil
		end
		local old = KW.cages[target]
		if old then
			old.fade()
		end
		local c = { parts = {}, t0 = os.clock(), dead = false }
		KW.cages[target] = c
		local R, H = 2.1, 6.2
		local pieces = {}
		for i = 1, 4 do
			local a = (i - 0.5) / 4 * math.pi * 2
			table.insert(pieces, { kind = "post", a = a })
		end
		for h = 1, 3 do
			for i = 1, 4 do
				table.insert(pieces, { kind = "bar", h = h, a = i / 4 * math.pi * 2 })
			end
		end
		for i = 1, 4 do
			table.insert(pieces, { kind = "leaf", a = (i - 0.5) / 4 * math.pi * 2 })
		end
		for i, p in pieces do
			if p.kind == "leaf" then
				p.part = KW.leafPart(0.9, troot.CFrame, i)
			else
				p.part = newPart(Vector3.one * 0.4, troot.CFrame, i % 2 == 0 and KW.DARK or KW.WOOD, Enum.Material.Wood)
			end
			c.parts[i] = p.part
		end
		local function place()
			local k = math.clamp((os.clock() - c.t0) / 0.18, 0, 1)
			local r = R * (1.6 - 0.6 * k)
			local base = CFrame.new(troot.Position) * CFrame.Angles(0, (1 - k) * 0.8, 0)
			for _, p in pieces do
				if p.kind == "post" then
					local pos = Vector3.new(math.cos(p.a) * r * 1.1, 0, math.sin(p.a) * r * 1.1)
					p.part.Size = Vector3.new(0.5, H * k + 0.1, 0.5)
					p.part.CFrame = base * CFrame.new(pos + Vector3.new(0, -H / 2 + H * k / 2, 0)) * CFrame.Angles(0, -p.a, 0)
				elseif p.kind == "leaf" then
					-- (sprouting off the top of the post, tipped outward)
					local pos = Vector3.new(math.cos(p.a) * r * 1.25, -H / 2 + H * k + 0.1, math.sin(p.a) * r * 1.25)
					p.part.CFrame = base * CFrame.new(pos) * CFrame.Angles(0, -p.a, 0) * CFrame.Angles(0, 0, math.rad(-30)) * CFrame.Angles(0, math.rad(45), 0)
				else
					local y = -H / 2 + H * (p.h - 0.5) / 3
					local pos = Vector3.new(math.cos(p.a) * r, y, math.sin(p.a) * r)
					p.part.Size = Vector3.new(0.42, 0.42, r * 1.55)
					p.part.CFrame = base * CFrame.new(pos) * CFrame.Angles(0, -p.a, 0)
				end
			end
		end
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if c.dead or not troot.Parent or os.clock() - c.t0 > (duration or 1.6) + 0.5 then
				conn:Disconnect()
				if not c.dead then
					c.fade()
				end
				return
			end
			place()
		end)
		place()
		function c.fade()
			if c.dead then
				return
			end
			c.dead = true
			if KW.cages[target] == c then
				KW.cages[target] = nil
			end
			for _, part in c.parts do
				tween(part, 0.25, { Transparency = 1 })
				cleanup(part, 0.3)
			end
		end
		function c.crush()
			if c.dead then
				return
			end
			c.dead = true
			if KW.cages[target] == c then
				KW.cages[target] = nil
			end
			local center = troot.Position
			for _, part in c.parts do
				local out = (part.Position - center)
				out = out.Magnitude > 0.1 and out.Unit or rng:NextUnitVector()
				tween(part, 0.4, { CFrame = part.CFrame * CFrame.Angles(rand(-2, 2), rand(-2, 2), rand(-2, 2)) + out * rand(5, 9) - UP * rand(0, 3), Size = part.Size * 0.4, Transparency = 1 })
				cleanup(part, 0.45)
			end
			KW.splinters(center, 1.2, 12)
			VFX.PlaySound("WoodCrush", center, 1)
		end
		return c
	end

	-- wood chips flying off a point
	function KW.splinters(pos, scale, count)
		for _ = 1, count or 6 do
			local chip = newPart(Vector3.new(rand(0.15, 0.35), rand(0.1, 0.2), rand(0.4, 0.8)) * scale, CFrame.new(pos) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)),
				rng:NextNumber() < 0.5 and KW.WOOD or KW.LIGHT, Enum.Material.Wood)
			local out = rng:NextUnitVector()
			tween(chip, 0.45, { CFrame = CFrame.new(pos + out * rand(3, 7) * scale + UP * rand(0, 3)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Transparency = 1 }, Enum.EasingStyle.Quad)
			cleanup(chip, 0.5)
		end
	end

	-- a frame at `from` with its Y running towards `to` (straight up is fine:
	-- the look needs an up that isn't along it)
	function KW.upright(from, to)
		local d = to - from
		local up = (d.Magnitude < 1e-3 or math.abs(d.Unit.Y) > 0.98) and Vector3.new(0, 0, 1) or UP
		return CFrame.lookAt(from, d.Magnitude < 1e-3 and from + UP or to, up) * CFrame.Angles(math.rad(-90), 0, 0)
	end

	-- a stake bursting out of the street at `pos`: a square post with a
	-- wedge point, leaning along `lean`; sinks back after `life`
	function KW.stake(pos, height, width, lean, life)
		local g = groundPoint(pos + UP * 2)
		local dir = (UP + (lean or Vector3.zero)).Unit
		local topCF = KW.upright(g, g + dir) -- (Y along the stake)
		local post = newPart(Vector3.new(width, height, width), topCF * CFrame.new(0, -height / 2, 0), rng:NextNumber() < 0.5 and KW.WOOD or KW.DARK, Enum.Material.Wood)
		local tipH = width * 1.3
		local tips = {}
		for half = 0, 1 do
			local w = Instance.new("WedgePart")
			w.Anchored = true
			w.CanCollide = false
			w.CanQuery = false
			w.CanTouch = false
			w.CastShadow = false
			w.Size = Vector3.new(width, tipH, width / 2)
			w.Color = KW.LIGHT
			w.Material = Enum.Material.Wood
			w.CFrame = topCF * CFrame.new(0, -tipH / 2, 0)
			w.Parent = folder
			tips[half + 1] = { part = w, rel = CFrame.new(0, height + tipH / 2, (half == 0 and -1 or 1) * width / 4) * CFrame.Angles(0, half == 0 and 0 or math.pi, 0) }
		end
		-- (most sprout a sprig of leaves off one side, near the top)
		local sprig = {}
		if rng:NextNumber() < 0.7 then
			local side = rng:NextNumber() < 0.5 and 1 or -1
			local at = CFrame.new(side * width / 2, height * rand(0.55, 0.8), 0) * CFrame.Angles(0, rand(-0.6, 0.6), math.rad(-side * 55))
			for _, piece in KW.sprig(math.clamp(width * 0.8, 0.7, 1.3), rng:NextInteger(0, 2)) do
				piece.rel = at * piece.rel
				piece.part.CFrame = topCF * CFrame.new(0, -height, 0) * piece.rel
				table.insert(sprig, piece)
			end
		end
		-- (up out of the street)
		tween(post, 0.12, { CFrame = topCF * CFrame.new(0, height / 2, 0) }, Enum.EasingStyle.Back)
		for _, t in tips do
			tween(t.part, 0.12, { CFrame = topCF * t.rel }, Enum.EasingStyle.Back)
		end
		for _, piece in sprig do
			tween(piece.part, 0.12, { CFrame = topCF * piece.rel }, Enum.EasingStyle.Back)
		end
		dustPuffs(g, 0.4 + width * 0.12, 2, KW.DUST, 0.6, false)
		task.delay(life or 1.2, function()
			tween(post, 0.35, { CFrame = topCF * CFrame.new(0, -height / 2, 0), Transparency = 0.6 })
			cleanup(post, 0.4)
			for _, t in tips do
				tween(t.part, 0.35, { CFrame = topCF * CFrame.new(0, -tipH, 0), Transparency = 0.6 })
				cleanup(t.part, 0.4)
			end
			for _, piece in sprig do
				tween(piece.part, 0.35, { CFrame = topCF * CFrame.new(0, -height, 0) * piece.rel, Transparency = 1 })
				cleanup(piece.part, 0.4)
			end
		end)
		return post
	end

	-- a trunk growing out of the street from `base` up to `top`: square,
	-- bark stripes, a few stubby branches off it; gone after `life`
	function KW.trunk(base, top, thick, life, grow)
		local span = top - base
		local len = math.max(span.Magnitude, 1)
		local cf = KW.upright(base, top) -- (Y up the trunk)
		local parts = {}
		local main = newPart(Vector3.new(thick, 0.2, thick), cf, KW.WOOD, Enum.Material.Wood)
		table.insert(parts, { part = main, size = Vector3.new(thick, len, thick), rel = CFrame.new(0, len / 2, 0) })
		for i = -1, 1, 2 do
			local stripe = newPart(Vector3.new(thick * 0.18, 0.2, 0.1), cf, KW.DARK, Enum.Material.Wood)
			table.insert(parts, { part = stripe, size = Vector3.new(thick * 0.18, len * 0.9, 0.1), rel = CFrame.new(i * thick * 0.25, len / 2, -thick / 2 - 0.05) })
		end
		for i = 1, 3 do
			local y = len * (0.45 + i * 0.15)
			local a = i * 2.1
			local stub = newPart(Vector3.new(thick * 0.35, thick * 0.35, 0.2), cf, KW.DARK, Enum.Material.Wood)
			local stubLen = thick * 1.3
			local stubRel = CFrame.new(0, y, 0) * CFrame.Angles(0, a, 0) * CFrame.Angles(math.rad(35), 0, 0) * CFrame.new(0, 0, -thick / 2 - stubLen / 2)
			table.insert(parts, { part = stub, size = Vector3.new(thick * 0.35, thick * 0.35, stubLen), rel = stubRel })
			-- (a bunch of leaves on the end of each)
			for k = 1, 3 do
				local size = thick * rand(0.45, 0.6)
				local rel = stubRel * CFrame.new(0, 0, -stubLen / 2) * CFrame.Angles(0, 0, k * 2.1) * CFrame.new(0, thick * 0.2, 0) * CFrame.Angles(math.rad(20), math.rad(45), 0)
				table.insert(parts, { part = KW.leafPart(0.2, cf, i + k), size = Vector3.new(size, 0.1, size), rel = rel })
			end
		end
		-- (and a crown of them on top)
		for k = 1, 5 do
			local size = thick * rand(0.6, 0.85)
			local rel = CFrame.new(0, len, 0) * CFrame.Angles(0, k / 5 * math.pi * 2, 0) * CFrame.new(0, 0, -thick * 0.45) * CFrame.Angles(math.rad(-25), math.rad(45), 0)
			table.insert(parts, { part = KW.leafPart(0.2, cf, k), size = Vector3.new(size, 0.1, size), rel = rel })
		end
		local g = grow or 0.2
		for _, p in parts do
			p.part.CFrame = cf * CFrame.new(p.rel.Position.X, 0, p.rel.Position.Z)
			tween(p.part, g, { Size = p.size, CFrame = cf * p.rel }, Enum.EasingStyle.Back)
		end
		task.delay(life or 1.5, function()
			for _, p in parts do
				tween(p.part, 0.4, { Transparency = 1, Size = p.part.Size * Vector3.new(0.6, 1, 0.6) })
				cleanup(p.part, 0.45)
			end
		end)
		return main
	end

	-- a blocky canopy: a cluster of square leaf blocks round `pos`
	function KW.canopy(pos, size, life)
		for i = 1, 7 do
			local off = i == 1 and Vector3.zero or Vector3.new(rand(-1, 1), rand(-0.4, 0.6), rand(-1, 1)) * size * 0.5
			local s = size * rand(0.45, 0.7)
			local leaf = newPart(Vector3.new(s, s * 0.7, s), CFrame.new(pos + off) * CFrame.Angles(0, rand(0, 3), 0), KW.leafColor(i), Enum.Material.Grass)
			leaf.Size = Vector3.one * 0.2
			tween(leaf, 0.25, { Size = Vector3.new(s, s * 0.7, s) }, Enum.EasingStyle.Back)
			task.delay(life or 2, function()
				tween(leaf, 0.4, { Transparency = 1 })
				cleanup(leaf, 0.45)
			end)
		end
	end

	-- square leaves drifting down round a point, tumbling as they go
	function KW.leaves(pos, count, spread)
		for _ = 1, count or 4 do
			local from = pos + Vector3.new(rand(-1, 1), rand(0, 1), rand(-1, 1)) * (spread or 3)
			local leaf = KW.leafPart(rand(0.4, 0.6), CFrame.new(from) * CFrame.Angles(0, rand(0, 6), 0))
			local life = rand(1.1, 1.6)
			tween(leaf, life, { CFrame = CFrame.new(from - UP * rand(3, 7) + Vector3.new(rand(-2.5, 2.5), 0, rand(-2.5, 2.5))) * CFrame.Angles(rand(-1.2, 1.2), rand(0, 6), rand(-1.2, 1.2)), Transparency = 1 }, Enum.EasingStyle.Sine)
			cleanup(leaf, life + 0.05)
		end
	end

	-- a sprig: a stubby twig with a few leaves on it, in frame `cf` (the
	-- twig runs up its Y). Returns { part, rel } pieces for the caller to
	-- place (cf * rel) as whatever it's on moves.
	function KW.sprig(scale, seed)
		local pieces = {}
		local twigLen = 0.9 * scale
		table.insert(pieces, { part = newPart(Vector3.new(0.22, twigLen, 0.22) * Vector3.new(scale, 1, scale), CFrame.new(), KW.DARK, Enum.Material.Wood), rel = CFrame.new(0, twigLen / 2, 0) })
		for k = 1, 3 do
			local a = (k / 3) * math.pi * 2 + (seed or 0)
			local size = (0.55 + 0.1 * k) * scale
			local rel = CFrame.new(0, twigLen * (0.55 + 0.2 * k), 0) * CFrame.Angles(0, a, 0) * CFrame.new(0, 0, -size * 0.45) * CFrame.Angles(math.rad(-28), math.rad(45), 0)
			table.insert(pieces, { part = KW.leafPart(size, CFrame.new(), k + (seed or 0)), rel = rel })
		end
		return pieces
	end

