		billboardRing(root.Position + UP * 2, 1, 10, MC.ORANGE, 5, 0.25)
	end

	-- ULT: a slab of the city, taken and dropped out of the sky
	function Effects.CurtainSlab(char, data, isLocal)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not pos then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		local time = tonumber(data.Time) or 1
		if typeof(data.From) == "Vector3" then
			MC.suck(data.From, 9, MC.GLASS)
			local taken = MC.chunk(CFrame.new(data.From), 7, data.Color, data.Material)
			for _, e in taken.parts do
				tween(e.part, 0.3, { CFrame = CFrame.new(handPos(char, true)), Size = Vector3.one * 0.1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(e.part, 0.32)
			end
		end
		landingMarker(pos, time - 0.3)
		-- the slab out of the sky
		local slab = MC.chunk(CFrame.new(pos + UP * 70), 9, data.Color, data.Material)
		for _, e in slab.parts do
			local full = e.part.Size
			e.part.Size = full * 0.1
			tween(e.part, 0.12, { Size = full }, Enum.EasingStyle.Back)
		end
		VFX.PlaySound("Decompress", pos + UP * 30, 1.2)
		local t0 = os.clock()
		local fall = time - 0.35
		while os.clock() - t0 < fall and slab.parts[1].part.Parent do
			local s = math.clamp((os.clock() - t0) / fall, 0, 1)
			slab.set(CFrame.new(pos + UP * (70 * (1 - s * s) + 3)) * CFrame.Angles(0, s * 0.6, 0))
			task.wait()
		end
		MC.slab = slab
	end
	function Effects.CurtainDrop(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		if MC.slab then
			MC.slab.shatter()
			MC.slab = nil
		end
		dustPuffs(groundPoint(pos), 2.4, 12, Color3.fromRGB(200, 190, 175), 1.3, true)
		rocks(pos, 2, 18)
		shockDisc(pos + UP * 0.3, UP, 3, 40, 0.4, Color3.fromRGB(220, 210, 190), 6)
		billboardRing(pos + UP, 3, 34, MC.ORANGE, 8, 0.35)
		groundMark(groundPoint(pos + UP), 12, Color3.fromRGB(60, 56, 54), 10)
		VFX.PlaySound("RubbleLand", pos, 1.3)
		VFX.PlaySound("Decompress", pos, 1)
		VFX.ShakeAt(pos, 3, 140, 0.5)
		if nearCamera(pos, 90) then
			VFX.ImpactFrame(0.1)
		end
	end

	-- ULT: everyone round him into marbles in his hand, then the lot thrown
	function Effects.DisappearingGrab(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local held = tonumber(data.Held) or 1.2
