	-- a dash: a puff of smoke, a marble's glint
	QUIRK_FX.Dash.Compress = function(_char, root, dir)
		dustPuffs(root.Position - dir * 1.5, 0.6, 4, MC.SMOKE, 0.6, false)
		sparks(root.Position + UP, 0.4, WHITE, MC.GLASS, 4)
	end
	-- (round 75) stage lights: beams down out of the sky onto `pos`, a bright
	-- pool on the street round it
	function MC.spotlights(pos, time, count)
		count = count or 3
		local g = groundPoint(pos)
		for i = 1, count do
			local a = i / count * math.pi * 2 + rand(-0.3, 0.3)
			local src = g + Vector3.new(math.cos(a) * 34, 60, math.sin(a) * 34)
			local len = (src - g).Magnitude
			local beam = newPart(Vector3.new(len, 0.5, 0.5), CFrame.lookAt((src + g) / 2, g) * CFrame.Angles(0, math.rad(90), 0), Color3.fromRGB(255, 244, 214), Enum.Material.Neon, Enum.PartType.Cylinder)
			beam.Transparency = 0.82
			tween(beam, 0.25, { Size = Vector3.new(len, 7, 7) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(beam, 0.4, { Transparency = 1, Size = Vector3.new(len, 1, 1) }, nil, nil, math.max(time - 0.4, 0.2))
			cleanup(beam, time + 0.1)
		end
		local pool = newPart(Vector3.new(0.12, 10, 10), CFrame.new(g + UP * 0.08) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(255, 250, 230), Enum.Material.Neon, Enum.PartType.Cylinder)
		pool.Transparency = 0.6
		tween(pool, 0.4, { Transparency = 1 }, nil, nil, math.max(time - 0.4, 0.2))
		cleanup(pool, time + 0.1)
		VFX.PlaySound("CineCut", g, 0.5)
	end
	-- confetti: bright scraps burst up out of `pos` and flutter down
	MC.CONFETTI = { Color3.fromRGB(255, 80, 90), Color3.fromRGB(255, 210, 60), Color3.fromRGB(90, 200, 255), Color3.fromRGB(140, 255, 120), Color3.fromRGB(230, 120, 255), Color3.new(1, 1, 1) }
	function MC.confetti(pos, count, power)
		power = power or 1
		for _ = 1, count do
			local bit = newPart(Vector3.new(0.35, 0.05, 0.22) * rand(0.8, 1.3), CFrame.new(pos) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), MC.CONFETTI[rng:NextInteger(1, #MC.CONFETTI)], Enum.Material.SmoothPlastic)
			local out = (rng:NextUnitVector() * Vector3.new(1, 0, 1) + UP * rand(0.6, 1.4)) * rand(4, 9) * power
			local up = pos + out
			local down = up + Vector3.new(rand(-3, 3), -rand(6, 12) * power, rand(-3, 3))
			tween(bit, 0.35, { CFrame = CFrame.new(up) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(bit, 1.4, { CFrame = CFrame.new(down) * CFrame.Angles(rand(0, 12), rand(0, 12), rand(0, 12)), Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In, 0.35)
			cleanup(bit, 1.8)
		end
		VFX.PlaySound("Confetti", pos, 0.8)
	end
	-- while SHOWTIME lasts: the marbles in his pocket circle him
	MC.orbiting = setmetatable({}, { __mode = "k" })
	function MC.orbit(char)
		local root = charParts(char)
		if not root or MC.orbiting[char] then
			return
		end
		local token = {}
		MC.orbiting[char] = token
		local shown = {}
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local n = math.clamp(tonumber(char:GetAttribute("Marbles")) or 0, 0, 6)
			if MC.orbiting[char] ~= token or not root.Parent or (os.clock() - t0 > 0.5 and char:GetAttribute("UltActive") ~= true) then
				conn:Disconnect()
				if MC.orbiting[char] == token then
					MC.orbiting[char] = nil
				end
				for _, m in shown do
					m.gone(0.2)
				end
				return
			end
			while #shown < n do
				table.insert(shown, MC.marble(root.CFrame, 0.4, MC.ORANGE))
			end
			while #shown > n do
				table.remove(shown).gone(0.1)
			end
			local t = os.clock() - t0
			for i, m in shown do
				local a = t * 2.4 + i / #shown * math.pi * 2
				m.set(CFrame.new(root.Position + Vector3.new(math.cos(a) * 2.6, 0.4 + math.sin(t * 3 + i) * 0.5, math.sin(a) * 2.6)))
			end
		end)
	end

	-- SHOWTIME: (round 75) the bow, the spotlights come on, a burst of marbles
	-- and confetti; his pocket's marbles circle him while it lasts
	QUIRK_FX.Ult.Compress = function(char, root, g)
		VFX.Motion(char, "Showtime")
		billboardRing(root.Position + UP, 2, 34, MC.ORANGE, 7, 0.4)
		shockDisc(g + UP * 0.3, UP, 2, 30, 0.35, MC.GLASS, 5)
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0.4, math.sin(a))
			local m = MC.marble(CFrame.new(root.Position + UP), 0.45, i % 2 == 0 and MC.ORANGE or MC.GLASS)
			local to = root.Position + UP + out * rand(6, 10)
			tween(m.Ball, 0.5, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(m.Core, 0.5, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			task.delay(0.5, m.gone, 0.3)
		end
		MC.spotlights(root.Position, 2.2, 3)
		task.delay(0.5, function()
			if root.Parent then
				MC.confetti(root.Position + UP * 3, 40, 1.2)
			end
		end)
		sparks(root.Position + UP * 2, 1.4, WHITE, MC.ORANGE, 20)
		MC.orbit(char)
	end
	-- a marble back in his pocket (SHOWTIME's refill)
	function Effects.MarbleRefill(char)
		local root = charParts(char)
		if not root then
			return
		end
		local hand = handPos(char, true)
		MC.suck(hand, 1, MC.ORANGE)
		billboardRing(hand, 0.4, 4, MC.ORANGE, 2, 0.2)
		MC.orbit(char)
	end

	-- 4 in SHOWTIME: THE GRAND FINALE
	MC.finale = setmetatable({}, { __mode = "k" }) -- [char] = the bodies in his act
	POSES.JuggleR = { RightArm = { 150, 0, 14 }, RightElbow = 30, LeftArm = { 70, 0, 20 }, LeftElbow = 60, Waist = { 6, 0, 0 }, Neck = { 30, 0, 0 } }
	POSES.JuggleL = { LeftArm = { 150, 0, 14 }, LeftElbow = 30, RightArm = { 70, 0, 20 }, RightElbow = 60, Waist = { 6, 0, 0 }, Neck = { 30, 0, 0 } }
	SHOTS.GrandFinale = {
		{ T = 0.4, From = { V(3, 1.8, -6), V(0, 1.6, 0) }, To = { V(2.4, 1.7, -5), V(0, 1.6, 0) }, Fov = { 50, 44 } },
		-- low, looking up past him at what he's juggling
		{ T = 1.4, Cut = true, From = { V(-4, -1.5, -7), V(0, 5, 0) }, To = { V(-5, -1.2, -8), V(0, 5.5, 0) }, Fov = { 62, 58 } },
		-- the throw: up with them
		{ T = 0.6, Cut = true, From = { V(6, 2, -10), V(0, 8, 0) }, To = { V(8, 4, -14), V(0, 60, 0) }, Fov = { 62, 76 }, Style = Enum.EasingStyle.Quad },
		-- wide over the street as they all come back down
		{ T = 1.4, Cut = true, From = { V(0, 30, 44), V(0, 0, 0) }, To = { V(0, 24, 38), V(0, 0, 0) }, Fov = { 72, 70 } },
	}
	function Effects.GrandFinale(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Callout("AND NOW... THE GRAND FINALE!", MC.ORANGE)
		end
		cinematicFor(char, "GrandFinale", isLocal, (ability and ability.Name) or "THE GRAND FINALE", MC.ORANGE)
		VFX.Motion(char, "HatTip")
		MC.spotlights(root.Position, 3.6, 4)
		billboardRing(root.Position, 2, (ability and ability.Radius or 30) * 2, MC.ORANGE, 6, 0.4)
		shockDisc(groundPoint(root.Position) + UP * 0.3, UP, 2, (ability and ability.Radius or 30) * 2, 0.4, MC.GLASS)
		VFX.PlaySound("UltCompress", root.Position, 0.6)
	end
	-- Server: everyone round him, a marble in his hand; and the juggle
	function Effects.FinaleGrab(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local juggle = tonumber(data.Juggle) or 1.4
		local list = typeof(data.Targets) == "table" and data.Targets or {}
		MC.finale[char] = {}
		for _, target in list do
			local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
			if troot then
				table.insert(MC.finale[char], target)
				MC.suck(troot.Position + UP, 3, MC.GLASS)
				afterimage(target, MC.GLASS, 0.25)
				hideCharacter(target, juggle + 4)
				MC.ride(target, juggle + 0.15)
			end
		end
		if #list == 0 then
			sparks(root.Position + UP * 2, 0.6, WHITE, MC.GLASS, 6)
			return
		end
		-- one hand, then the other
		task.spawn(function()
			local t0, k = os.clock(), 0
			while os.clock() - t0 < juggle and root.Parent do
				k += 1
				VFX.Pose(char, k % 2 == 0 and "JuggleL" or "JuggleR", 0.2)
				sparks(handPos(char, k % 2 == 1) + UP * 0.5, 0.3, WHITE, MC.ORANGE, 2)
				task.wait(0.16)
			end
		end)
	end
	-- Server: up they all go
	function Effects.FinaleThrow(char, data)
		local root = charParts(char)
		if root then
			VFX.Pose(char, "Present", 0.5)
			streaks(root.Position + UP * 4, UP, 12, 2, 8, 30, MC.GLASS, 0.35)
			VFX.PlaySound("MarbleThrow", root.Position, 1)
			MC.confetti(root.Position + UP * 4, 20, 0.8)
		end
		for _, target in typeof(data.Targets) == "table" and data.Targets or {} do
			if typeof(target) == "Instance" then
				MC.ride(target, 0.6 + 0.1)
			end
		end
	end
	-- Server: and back down, full size, all at once (Spots: where)
	function Effects.FinaleDrop(char, data)
		local fall = tonumber(data.Fall) or 0.7
		local height = tonumber(data.Height) or 70
		local spots = typeof(data.Spots) == "table" and data.Spots or {}
		for _, spot in spots do
			if typeof(spot) == "Vector3" then
				landingMarker(spot, fall)
				-- a marble coming down out of the sky
				local m = MC.marble(CFrame.new(spot + UP * height), 0.7, MC.ORANGE)
				local stop = addTrail(m.Ball, MC.GLASS, 0.2, 0.5)
				task.spawn(function()
					local t0 = os.clock()
					while os.clock() - t0 < fall do
						m.set(CFrame.new((spot + UP * height):Lerp(spot, math.clamp((os.clock() - t0) / fall, 0, 1))))
						task.wait()
					end
					stop(0)
					m.gone(0.05)
					MC.decompress(spot, 2.4, nil, nil, UP)
					MC.confetti(spot + UP, 24, 1)
					sparks(spot + UP, 1, WHITE, MC.ORANGE, 12)
				end)
			end
		end
		local list = MC.finale[char] or {}
		MC.finale[char] = nil
		task.delay(fall, function()
			-- (them, back: the server's let them out)
			for _, target in list do
				if target.Parent then
					for _, dd in target:GetDescendants() do
						if dd:IsA("BasePart") or dd:IsA("Decal") then
							dd.LocalTransparencyModifier = 0
						end
					end
				end
			end
			local me = Players.LocalPlayer and Players.LocalPlayer.Character
			if me and spots[1] and nearCamera(spots[1], 90) then
				VFX.ImpactFrame(0.08)
			end
			if char and char.Parent then
				VFX.Pose(char, "Bow", 0.8)
			end
		end)
	end
	-- M1s: the cane
	function VFX.CompressPunch(_char, count, finisher, fist, look)
		sparks(fist, finisher and 0.8 or 0.4, WHITE, MC.ORANGE, finisher and 8 or 3)
		VFX.PlaySound(finisher and "CaneHit" or "Swish", fist, finisher and 1 or 0.6)
		if count == 4 or finisher then
			billboardRing(fist + look, 0.6, 6, MC.ORANGE, 3, 0.16)
		end
	end
	-- the finisher: they're a marble in his hand; a bow; flicked away
	function MC.finisher(char, target, troot, d, time)
		MC.suck(troot.Position + UP, 3, MC.GLASS)
		afterimage(target, MC.GLASS, 0.25)
		hideCharacter(target, time * 0.75)
		MC.ride(target, time * 0.8)
		VFX.Motion(char, "VanishingAct")
		VFX.PlaySound("Compress", troot.Position, 1)
		task.wait(time * 0.75)
		MC.unride(target)
		local pos = troot.Position
		billboardRing(pos, 0.5, 16, WHITE, 5, 0.22)
		shockDisc(pos + UP * 0.3, d, 2, 16, 0.28, MC.ORANGE, 4)
		rocks(pos, 0.9, 10)
		VFX.PlaySound("Decompress", pos, 1.1)
	end
	-- the KO burst: marbles everywhere, a piece of the street popping out
	function MC.burst(pos, dir)
		MC.decompress(pos, 3, STREET, Enum.Material.Concrete, dir)
		for i = 1, 10 do
			local m = MC.marble(CFrame.new(pos + UP), 0.4, i % 2 == 0 and MC.ORANGE or MC.GLASS)
			local to = pos + UP + rng:NextUnitVector() * rand(4, 9)
			tween(m.Ball, 0.45, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(m.Core, 0.45, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			task.delay(0.45, m.gone, 0.25)
		end
		billboardRing(pos + UP, 2, 24, MC.ORANGE, 6, 0.3)
	end
end

---------------------------------------------------------------------------
-- CHARGEBOLT (Denki Kaminari): Electrification. Yellow-white lightning off
-- his whole body, his Sharpshooting Gear's orange pointer discs, and the
-- bolts that go straight to them. And "wheeey".
---------------------------------------------------------------------------
do
	local DK = { YELLOW = Color3.fromRGB(255, 232, 80), BLUE = Color3.fromRGB(150, 220, 255), ORANGE = Color3.fromRGB(255, 120, 40), discs = {} }
	VFX.DK = DK
	local WHITE = Color3.new(1, 1, 1)

	POSES.Crackle = { RightArm = { 40, 0, 70 }, LeftArm = { 40, 0, 70 }, RightElbow = 60, LeftElbow = 60, Waist = { -14, 0, 0 }, Neck = { -20, 0, 0 }, RightLeg = -10, LeftLeg = 14, RightKnee = 20, LeftKnee = 26 }
	POSES.FingerGun = { RightArm = { 92, 0, 6 }, RightElbow = 4, LeftArm = { 20, 0, 20 }, Waist = { 4, -28, 0 }, Neck = { 0, 22, 0 }, RightLeg = -14, LeftLeg = 18, LeftKnee = 18 }
	POSES.ShooterAim = { RightArm = { 95, 0, 0 }, RightElbow = 8, LeftArm = { 75, 0, 10 }, LeftElbow = 90, Waist = { 2, -24, 0 }, Neck = { -4, 18, 0 } }
	POSES.GraspHold = { RightArm = { 85, 0, 10 }, RightElbow = 30, LeftArm = { 30, 0, 30 }, LeftElbow = 60, Waist = { 10, -12, 0 }, RightLeg = -16, LeftLeg = 22, LeftKnee = 22 }
	POSES.GraspSlam = { RightArm = { 20, 0, 15 }, RightElbow = 20, LeftArm = { 20, 0, 30 }, Waist = { 36, -10, 0 }, Neck = { 14, 0, 0 }, RightLeg = 30, RightKnee = 60, LeftLeg = -20, LeftKnee = 30, Hips = { 0, 0, 0, 0, -0.5, 0 } }
	POSES.WireDash = { RightArm = { -60, 0, 20 }, LeftArm = { -60, 0, 20 }, RightElbow = 40, LeftElbow = 40, Waist = { 28, 0, 0 }, Neck = { -18, 0, 0 }, RightLeg = -30, LeftLeg = 40, LeftKnee = 40 }
	-- the trap: wound back low, then flicked down onto the street in front
	POSES.TrapWind = { RightArm = { -30, 0, 30 }, RightElbow = 70, LeftArm = { 40, 0, 20 }, LeftElbow = 40, Waist = { 8, 24, 0 }, Neck = { 10, -14, 0 }, RightLeg = -12, LeftLeg = 26, LeftKnee = 40, RightKnee = 20, Crouch = 0.35 }
	POSES.TrapToss = { RightArm = { 70, 0, 4 }, RightElbow = 6, RightWrist = { -40, 0, 0 }, LeftArm = { -20, 0, 30 }, LeftElbow = 30, Waist = { 26, -18, 0 }, Neck = { 14, 10, 0 }, RightLeg = 24, RightKnee = 50, LeftLeg = -16, LeftKnee = 14, Crouch = 0.6 }
	-- the dive: head down, arms back, a bolt out of the sky
	POSES.ThunderDive = { RightArm = { -150, 0, 20 }, LeftArm = { -150, 0, 20 }, RightElbow = 10, LeftElbow = 10, Waist = { 30, 0, 0 }, Neck = { 30, 0, 0 }, RightLeg = -10, LeftLeg = 20, RightKnee = 30, LeftKnee = 50 }
	POSES.ThunderLand = { RightArm = { 30, 0, 60 }, LeftArm = { 30, 0, 60 }, RightElbow = 30, LeftElbow = 30, Waist = { 30, 0, 0 }, Neck = { -20, 0, 0 }, RightLeg = 40, RightKnee = 90, LeftLeg = -30, LeftKnee = 60, Crouch = 1 }
	POSES.Wheey = { RightArm = { 70, 0, 20 }, RightElbow = 30, RightWrist = { 0, 0, -40 }, LeftArm = { 8, 0, 25 }, Waist = { -6, 0, 10 }, Neck = { 12, 0, 18 }, RightKnee = 18, LeftKnee = 24, Hips = { 0, 0, 0, 0, -0.2, 0 } }
	POSES.Volts = { RightArm = { 175, 0, 35 }, LeftArm = { 175, 0, 35 }, RightElbow = 15, LeftElbow = 15, Waist = { -22, 0, 0 }, Neck = { -30, 0, 0 }, RightKnee = 22, LeftKnee = 22 }
	POSES.KO_Electrification = { RightArm = { 92, 0, 6 }, RightElbow = 4, RightWrist = { 0, 0, -50 }, LeftArm = { 15, 0, 20 }, Waist = { -6, -22, 0 }, Neck = { 6, 18, 8 }, RightLeg = -12, LeftLeg = 18, LeftKnee = 20 }

	MOTIONS.Discharge = { { pose = "Crackle", t = 0.14, hold = 0.35 }, recover = 0.3 }
	MOTIONS.DischargeLine = { { pose = "Crackle", t = 0.12, hold = 0.12 }, { pose = "Blast", t = 0.06, hold = 0.3, style = SNAP }, recover = 0.3 }
	MOTIONS.ElectricGrasp = { { pose = "GraspHold", t = 0.1, hold = 0.65 }, { pose = "GraspSlam", t = 0.08, hold = 0.25, style = SNAP }, recover = 0.3 }
	MOTIONS.ElectricGraspAir = { { pose = "GraspHold", t = 0.1, hold = 0.25 }, { pose = "ArmsUp", t = 0.1, hold = 0.3 }, { pose = "ShooterAim", t = 0.08, hold = 0.2, style = SNAP }, { pose = "BlastUp", t = 0.06, hold = 0.3, style = SNAP }, recover = 0.3 }
	MOTIONS.ZapTrap = { { pose = "TrapWind", t = 0.09, hold = 0.06 }, { pose = "TrapToss", t = 0.07, hold = 0.2, style = SNAP }, recover = 0.28 }
	MOTIONS.ThunderLand = { { pose = "ThunderLand", t = 0.05, hold = 0.25, style = SNAP }, recover = 0.35 }
	MOTIONS.StunBolt = { { pose = "FingerGun", t = 0.08, hold = 0.3, style = SNAP }, recover = 0.25 }
	MOTIONS.Pointer = { { pose = "ShooterAim", t = 0.07, hold = 0.22, style = SNAP }, recover = 0.2 }
	MOTIONS.Volts = { { pose = "Crackle", t = 0.2, hold = 0.3 }, { pose = "Volts", t = 0.12, hold = 0.6, style = SNAP }, recover = 0.35 }
	MOTIONS.Wheey = { { pose = "Wheey", t = 0.3, hold = 1.5 }, recover = 0.4 }

	-- LIGHTNING. A path from a to b by midpoint displacement: each halving
	-- kicks the middle out sideways, half as far each time, so it kinks and
	-- zigzags like the real thing instead of wobbling along a line.
	function DK.path(a, b, jag)
		local v = b - a
		local len = v.Magnitude
		local d = v.Unit
		local s1 = d:Cross(math.abs(d.Y) > 0.9 and Vector3.new(1, 0, 0) or UP).Unit
		local s2 = d:Cross(s1).Unit
		local amp = math.min(len * 0.16, (jag or 0.8) * 2.6)
		local pts = { a, b }
		for _ = 1, math.clamp(math.ceil(math.log(math.max(len, 2) / 1.6, 2)), 1, 4) do
			local out = { pts[1] }
			for i = 1, #pts - 1 do
				local p, q = pts[i], pts[i + 1]
				table.insert(out, (p + q) / 2 + s1 * rand(-amp, amp) + s2 * rand(-amp, amp))
				table.insert(out, q)
			end
			pts = out
			amp *= 0.55
		end
		return pts
	end
	-- lay a bolt's parts along a path (made as needed, reused on a re-strike)
	function DK.lay(layers, pts, thick)
		for i = 1, #pts - 1 do
			local p, q = pts[i], pts[i + 1]
			local len = (q - p).Magnitude + thick * 0.8
			local cf = CFrame.lookAt((p + q) / 2, q)
			for _, L in layers do
				local seg = L.parts[i]
				if not seg then
					seg = newPart(Vector3.new(L.w, L.w, len), cf, L.color, Enum.Material.Neon)
					seg.Transparency = L.t
					L.parts[i] = seg
				else
					seg.CFrame = cf
					seg.Size = Vector3.new(L.w, L.w, len)
				end
			end
		end
	end
	-- a bolt from a to b: a white-hot core in a glow of the colour (and a wide
	-- faint halo on the big ones), forks off it, re-striking along a new path
	-- a couple of times before it fades - lightning flickers - and a flash
	-- where it lands. Gone in `life`.
	function DK.zig(a, b, color, thick, life, jag)
		if (b - a).Magnitude < 0.5 then
			return
		end
		color = color or DK.YELLOW
		thick = thick or 0.3
		life = life or 0.3
		local layers = {
			{ w = thick * 0.55, color = WHITE, t = 0, parts = {} },
			{ w = thick * 1.9, color = color, t = 0.3, parts = {} },
		}
		if thick >= 0.4 then
			table.insert(layers, { w = thick * 4.5, color = color, t = 0.84, parts = {} })
		end
		local forks = {}
		for _ = 1, thick >= 0.3 and 2 or 1 do
			table.insert(forks, { w = thick * 0.3, color = WHITE, t = 0, parts = {} })
			table.insert(forks, { w = thick * 1.1, color = color, t = 0.4, parts = {} })
		end
		local function strike()
			local pts = DK.path(a, b, jag)
			DK.lay(layers, pts, thick)
			-- the forks: off a point along it, out at an angle, a third as long
			for f = 1, #forks / 2 do
				local k = math.clamp(math.floor(#pts * rand(0.2, 0.75)), 2, #pts - 1)
				local from = pts[k]
				local along = (pts[k + 1] - pts[k - 1]).Unit
				local out = (along + rng:NextUnitVector() * 0.9).Unit
				local fpts = DK.path(from, from + out * (b - a).Magnitude * rand(0.12, 0.3), (jag or 0.8) * 0.7)
				DK.lay({ forks[f * 2 - 1], forks[f * 2] }, fpts, thick * 0.4)
			end
		end
		strike()
		-- (where it lands: a flash with a light in it)
		local flash = newPart(Vector3.one * thick * 3, CFrame.new(b), WHITE, Enum.Material.Neon, Enum.PartType.Ball)
		flash.Transparency = 0.1
		local light = Instance.new("PointLight")
		light.Color = color
		light.Range = 8 + thick * 16
		light.Brightness = 3
		light.Parent = flash
		tween(flash, life * 0.7, { Size = Vector3.one * thick * 7, Transparency = 1 })
		tween(light, life * 0.7, { Brightness = 0 })
		cleanup(flash, life * 0.7 + 0.05)
		task.spawn(function()
			local restrikes = life > 0.18 and 2 or 1
			for r = 1, restrikes do
				task.wait(life * 0.22)
				-- a blink dark, then the new path
				for _, L in layers do
					for _, seg in L.parts do
						seg.Transparency = 0.7
					end
				end
				task.wait(0.02)
				strike()
				for _, L in layers do
					for _, seg in L.parts do
						seg.Transparency = L.t + r * 0.05
					end
				end
			end
			local rest = math.max(life - life * 0.22 * restrikes - 0.04, 0.05)
			for _, set in { layers, forks } do
				for _, L in set do
					for _, seg in L.parts do
						tween(seg, rest, { Transparency = 1, Size = Vector3.new(seg.Size.X * 0.3, seg.Size.Y * 0.3, seg.Size.Z) })
						cleanup(seg, rest + 0.05)
					end
				end
			end
		end)
	end
	-- a little arc crawling over something: a short hop, core and glow, gone
	-- in a blink
	function DK.arc(a, b, color, thick)
		local pts = DK.path(a, b, 0.35)
		for i = 1, #pts - 1 do
			local p, q = pts[i], pts[i + 1]
			local cf = CFrame.lookAt((p + q) / 2, q)
			local len = (q - p).Magnitude + 0.05
			local core = newPart(Vector3.new((thick or 0.08), (thick or 0.08), len), cf, WHITE, Enum.Material.Neon)
			local glow = newPart(Vector3.new((thick or 0.08) * 3, (thick or 0.08) * 3, len), cf, color or DK.YELLOW, Enum.Material.Neon)
			glow.Transparency = 0.45
			cleanup(core, 0.07)
			cleanup(glow, 0.09)
		end
	end
	-- static all over someone for `time`: arcs jumping limb to limb, off the
	-- hands and the top of the head, and a flickering light on them
	function DK.crackleOn(char, time, color)
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local limbs = {}
		for _, n in { "Head", "Torso", "UpperTorso", "Right Arm", "Left Arm", "RightHand", "LeftHand", "Right Leg", "Left Leg", "RightLowerLeg", "LeftLowerLeg" } do
			local p = char:FindFirstChild(n)
			if p and p:IsA("BasePart") then
				table.insert(limbs, p)
			end
		end
		local light = Instance.new("PointLight")
		light.Color = color or DK.YELLOW
		light.Range = 10
		light.Brightness = 0
		light.Parent = root
		cleanup(light, time + 0.1)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < time and root.Parent do
				local a = limbs[rng:NextInteger(1, math.max(#limbs, 1))]
				local b = limbs[rng:NextInteger(1, math.max(#limbs, 1))]
				local pa = a and a.CFrame * Vector3.new(rand(-0.5, 0.5), rand(-0.9, 0.9), rand(-0.5, 0.5)) or root.Position
				local pb = b and b ~= a and b.CFrame * Vector3.new(rand(-0.5, 0.5), rand(-0.9, 0.9), rand(-0.5, 0.5)) or pa + rng:NextUnitVector() * rand(1, 2)
				DK.arc(pa, pb, color or DK.YELLOW, 0.07)
				if rng:NextNumber() < 0.45 then
					local hand = handPos(char, rng:NextNumber() < 0.5)
					DK.arc(hand, hand + rng:NextUnitVector() * rand(1, 2.2), WHITE, 0.06)
				end
				light.Brightness = rand(0.5, 2.5)
				task.wait(0.05)
			end
			light.Brightness = 0
		end)
	end
	-- an electric burst at a point: a flash, sparks, a ring, forks out of it
	function DK.zap(pos, scale, color)
		scale = scale or 1
		sparks(pos, scale, WHITE, color or DK.YELLOW, math.floor(8 * scale))
		billboardRing(pos, 0.5, 8 * scale, WHITE, 4, 0.16)
		for _ = 1, 3 do
			DK.arc(pos, pos + rng:NextUnitVector() * rand(1.2, 2.4) * scale, color or DK.YELLOW, 0.08 + 0.03 * scale)
		end
		local flash = newPart(Vector3.one * scale, CFrame.new(pos), WHITE, Enum.Material.Neon, Enum.PartType.Ball)
		flash.Transparency = 0.15
		tween(flash, 0.14, { Size = Vector3.one * scale * 3.5, Transparency = 1 })
		cleanup(flash, 0.16)
	end
	-- a pointer disc: orange, glowing, on a person (riding their chest) or a spot
	function DK.disc(id, target, pos, normal, life)
		DK.gone(id)
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		local function onBody()
			return troot.CFrame * CFrame.new(0, 0.6, -1.1) * CFrame.Angles(0, math.rad(90), 0)
		end
		local cf = troot and onBody() or CFrame.lookAt(pos, pos + (typeof(normal) == "Vector3" and normal.Magnitude > 0.1 and normal or UP)) * CFrame.Angles(0, math.rad(90), 0)
		local disc = newPart(Vector3.new(0.12, 0.8, 0.8), cf, DK.ORANGE, Enum.Material.Neon, Enum.PartType.Cylinder)
		local ring = newPart(Vector3.new(0.06, 1.1, 1.1), cf, WHITE, Enum.Material.Neon, Enum.PartType.Cylinder)
		ring.Transparency = 0.5
		local light = Instance.new("PointLight")
		light.Color = DK.ORANGE
		light.Range = 6
		light.Brightness = 1.5
		light.Parent = disc
		local rec = { Disc = disc, Ring = ring, Target = target }
		DK.discs[id] = rec
		if troot then
			local conn
			conn = RunService.RenderStepped:Connect(function()
				if not disc.Parent or not troot.Parent or DK.discs[id] ~= rec then
					conn:Disconnect()
					return
				end
				local c = onBody()
				disc.CFrame = c
				ring.CFrame = c
			end)
		end
		-- (a blink every now and then: it's live)
		task.spawn(function()
			local t0 = os.clock()
			while DK.discs[id] == rec and disc.Parent and os.clock() - t0 < (life or 20) + 1 do
				ring.Transparency = 0.15
				task.wait(0.1)
				ring.Transparency = 0.6
				task.wait(0.7)
			end
		end)
		task.delay((life or 20) + 0.5, DK.gone, id)
	end
	function DK.gone(id)
		local rec = DK.discs[id]
		if not rec then
			return
		end
		DK.discs[id] = nil
		sparks(rec.Disc.Position, 0.5, WHITE, DK.ORANGE, 5)
		tween(rec.Disc, 0.2, { Transparency = 1 })
		tween(rec.Ring, 0.2, { Transparency = 1 })
		cleanup(rec.Disc, 0.25)
		cleanup(rec.Ring, 0.25)
	end

	-- R: the Shooter fires - a streak, and the disc sticks
	function Effects.PointerShot(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or root.Position + UP * 1.5
		local to = typeof(data.To) == "Vector3" and data.To or from + root.CFrame.LookVector * 30
		if isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "Pointer")
		VFX.PlaySound("PointerShot", from, 1)
		beam(from, to, 0.35, DK.ORANGE, DK.YELLOW, 0.14)
		sparks(from, 0.4, WHITE, DK.ORANGE, 4)
		local disc = newPart(Vector3.new(0.12, 0.7, 0.7), CFrame.lookAt(from, to) * CFrame.Angles(0, math.rad(90), 0), DK.ORANGE, Enum.Material.Neon, Enum.PartType.Cylinder)
		tween(disc, 0.08, { CFrame = CFrame.lookAt(to, to + (to - from)) * CFrame.Angles(0, math.rad(90), 0) }, Enum.EasingStyle.Linear)
		cleanup(disc, 0.1)
	end
	function Effects.PointerStick(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos and typeof(data.Target) ~= "Instance" then
			return
		end
		DK.disc(data.Id or 0, data.Target, pos or data.Target.HumanoidRootPart.Position, data.Normal, tonumber(data.Life) or 20)
		VFX.PlaySound("PointerStick", pos or data.Target.HumanoidRootPart.Position, 1)
	end
	function Effects.PointerGone(_char, data)
		DK.gone(data.Id or 0)
	end

	-- jolted: static all over them (the Poisoned pattern, in yellow)
	function Effects.Shocked(_, data)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return
		end
		local time = tonumber(data.Duration) or 1
		DK.crackleOn(target, time, DK.YELLOW)
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		pe.Color = ColorSequence.new(WHITE, DK.YELLOW)
		pe.LightEmission = 1
		pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.5), NumberSequenceKeypoint.new(1, 0) })
		pe.Speed = NumberRange.new(2, 5)
		pe.Lifetime = NumberRange.new(0.2, 0.4)
		pe.SpreadAngle = Vector2.new(180, 180)
		pe.Rate = 40
		pe.Parent = troot
		task.delay(time, function()
			pe.Enabled = false
		end)
		cleanup(pe, time + 0.6)
		VFX.PlaySound("StaticCrackle", troot.Position, 0.9)
	end

	-- the Sky Coffin's barrier: whatever touches it gets a jolt - a burst of
	-- gold lightning crawling over its face
	function Effects.BarrierZap(_, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local n = typeof(data.Normal) == "Vector3" and data.Normal or UP
		local gold = Color3.fromRGB(255, 214, 90)
		DK.zap(pos, 1.4, gold)
		-- (bolts out in every direction along the face, 4 to 9 studs)
		local t1 = math.abs(n.Y) > 0.9 and Vector3.new(1, 0, 0) or n:Cross(UP).Unit
		local t2 = n:Cross(t1).Unit
		for k = 1, 7 do
			local a = (k + rand(0, 0.7)) / 7 * math.pi * 2
			DK.zig(pos, pos + (t1 * math.cos(a) + t2 * math.sin(a)) * rand(4, 9), gold, 0.2, 0.3, 0.9)
		end
		VFX.PlaySound("StaticCrackle", pos, 1.1)
	end

	-- 1: a shock all round him
	function Effects.DischargeBurst(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local radius = tonumber(data.Radius) or 12
		if data.Air then
			-- (the dive's landing: the street takes it)
			local g = groundPoint(root.Position)
			rocks(g, 1.2, 12)
			dustPuffs(g, 1.6, 8, Color3.fromRGB(210, 200, 180), 1, true)
			shockDisc(g + UP * 0.3, UP, 3, radius * 2.4, 0.4, DK.YELLOW, 5)
			VFX.PlaySound("Thunderbolt", g, 1.1)
		else
			VFX.Motion(char, "Discharge")
			task.wait(0.2)
		end
		if not root.Parent then
			return
		end
		local c = root.Position + UP
		DK.crackleOn(char, 0.5, DK.YELLOW)
		for i = 1, 12 do
			local a = i / 12 * math.pi * 2
			local out = Vector3.new(math.cos(a), rand(-0.15, 0.3), math.sin(a)).Unit
			DK.zig(c, c + out * radius * rand(0.7, 1), DK.YELLOW, 0.22, 0.3, 1.1)
		end
		billboardRing(c, 2, radius * 2.2, DK.YELLOW, 6, 0.3)
		shockDisc(root.Position + UP * 0.3, UP, 2, radius * 2, 0.3, WHITE, 5)
		groundMark(groundPoint(root.Position), radius * 0.5, Color3.fromRGB(50, 44, 30), 6)
		VFX.PlaySound("Discharge", c, 1)
		VFX.ShakeAt(c, 1.2, 60, 0.2)
		if nearCamera(c, 50) then
			VFX.ImpactFrame(0.06)
		end
	end
	-- 1 (a pointer near): one line of it, to the pointer
	function Effects.DischargeLine(char, data, isLocal)
		local root = charParts(char)
		local from = typeof(data.From) == "Vector3" and data.From
		local to = typeof(data.To) == "Vector3" and data.To
		if not root or not from or not to then
			return
		end
		if isLocal then
			face(root, flatten(to - from, root))
		end
		VFX.Motion(char, "DischargeLine")
		DK.crackleOn(char, 0.4, DK.YELLOW)
		task.wait(0.18)
		if not root.Parent then
			return
		end
		for k = 1, 3 do
			DK.zig(from, to, k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.45 or 0.2, 0.32, k == 1 and 0.6 or 1.6)
		end
		-- sparks all down the line
		local d = (to - from).Unit
		for s = 3, (to - from).Magnitude, 4 do
			sparks(from + d * s, 0.5, WHITE, DK.YELLOW, 3)
		end
		DK.zap(to, 1.4, DK.YELLOW)
		VFX.PlaySound("Discharge", from, 1)
		VFX.PlaySound("ElectricZap", to, 1)
		if typeof(data.Target) == "Instance" and nearCamera(to, 50) then
			VFX.ImpactFrame(0.07)
		end
	end

	-- 2: the grab; the current; the slam (or thrown up, tagged, blasted)
	function Effects.ElectricGraspHold(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not target then
			sparks(handPos(char, true), 0.5, WHITE, DK.YELLOW, 5)
			VFX.PlaySound("ElectricZap", root.Position, 0.6)
			return
		end
		VFX.Motion(char, data.Air and "ElectricGraspAir" or "ElectricGrasp")
		DK.crackleOn(target, data.Air and 0.5 or 0.7, DK.YELLOW)
		DK.crackleOn(char, 0.4, DK.YELLOW)
		VFX.PlaySound("ElectricZap", root.Position + d * 2, 1)
		if data.Air then
			return
		end
		local troot = target:FindFirstChild("HumanoidRootPart")
		for _ = 1, 3 do
			task.wait(0.2)
			if troot and troot.Parent then
				DK.zap(troot.Position + UP, 0.6, DK.YELLOW)
			end
		end
	end
	function Effects.GraspSlam(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		dustPuffs(groundPoint(pos), 0.9, 5, Color3.fromRGB(200, 190, 175), 0.8, true)
		rocks(pos, 0.7, 6)
		shockDisc(pos + UP * 0.2, typeof(data.Dir) == "Vector3" and data.Dir or UP, 2, 14, 0.28, DK.YELLOW, 4)
		DK.zap(pos + UP, 1.2, DK.YELLOW)
		VFX.PlaySound("Discharge", pos, 0.9)
		VFX.ShakeAt(pos, 1, 50, 0.2)
	end
	function Effects.GraspBolt(_char, data)
		local from = typeof(data.From) == "Vector3" and data.From
		local to = typeof(data.To) == "Vector3" and data.To
		if not from or not to then
			return
		end
		for k = 1, 2 do
			DK.zig(from, to, k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.5 or 0.22, 0.3, k == 1 and 0.6 or 1.5)
		end
		DK.zap(to, 1.6, DK.YELLOW)
		VFX.PlaySound("Thunderbolt", to, 1)
		if nearCamera(to, 50) then
			VFX.ImpactFrame(0.07)
		end
	end

	-- 3: ZAP TRAPS. A little device on the street: a steel disc with a
	-- yellow-and-black hazard ring, four prongs and a copper coil with a lamp
	-- on top that starts blinking when it's armed. Now and then a spark jumps
	-- between the prongs. A faint ring on the street shows how close is too
	-- close. Near a pointer, a live wire hums between the coil and the pointer.
	DK.traps = {}
	DK.COPPER = Color3.fromRGB(190, 116, 56)
	DK.STEEL = Color3.fromRGB(70, 72, 80)
	function DK.trap(id, pos, arm, life, radius)
		DK.untrap(id, nil)
		local g = pos -- (the server's found the street for it)
		local base = CFrame.new(g)
		local parts = {}
		local function add(p)
			table.insert(parts, p)
			return p
		end
		local disc = add(newPart(Vector3.new(0.3, 2.6, 2.6), base * CFrame.new(0, 0.15, 0) * CFrame.Angles(0, 0, math.rad(90)), DK.STEEL, Enum.Material.Metal, Enum.PartType.Cylinder))
		local ring = add(newPart(Vector3.new(0.32, 3, 3), disc.CFrame * CFrame.new(-0.01, 0, 0), DK.YELLOW, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder))
		ring.Transparency = 0
		add(newPart(Vector3.new(0.34, 2.2, 2.2), disc.CFrame, Color3.fromRGB(24, 24, 28), Enum.Material.Metal, Enum.PartType.Cylinder))
		for k = 0, 7 do -- (the hazard stripes)
			local a = k / 8 * math.pi * 2
			local stripe = add(newPart(Vector3.new(0.36, 0.28, 0.5), base * CFrame.Angles(0, a, 0) * CFrame.new(0, 0.16, -1.3) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(20, 20, 20), Enum.Material.SmoothPlastic))
			stripe.CFrame = base * CFrame.Angles(0, a, 0) * CFrame.new(0, 0.17, -1.3)
			stripe.Size = Vector3.new(0.3, 0.33, 0.45)
		end
		local prongs = {}
		for k = 0, 3 do
			local a = k / 4 * math.pi * 2 + math.pi / 4
			local prong = add(newPart(Vector3.new(0.16, 0.7, 0.16), base * CFrame.Angles(0, a, 0) * CFrame.new(0, 0.6, -0.95) * CFrame.Angles(math.rad(-18), 0, 0), Color3.fromRGB(30, 30, 34), Enum.Material.Metal))
			table.insert(prongs, prong)
		end
		add(newPart(Vector3.new(0.7, 0.8, 0.8), base * CFrame.new(0, 0.6, 0) * CFrame.Angles(0, 0, math.rad(90)), DK.COPPER, Enum.Material.Metal, Enum.PartType.Cylinder))
		for k = 1, 3 do -- (the windings)
			add(newPart(Vector3.new(0.08, 0.9, 0.9), base * CFrame.new(0, 0.35 + k * 0.15, 0) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(120, 70, 30), Enum.Material.Metal, Enum.PartType.Cylinder))
		end
		local lamp = add(newPart(Vector3.one * 0.45, base * CFrame.new(0, 1.1, 0), Color3.fromRGB(90, 80, 40), Enum.Material.Glass, Enum.PartType.Ball))
		local glow = Instance.new("PointLight")
		glow.Color = DK.YELLOW
		glow.Range = 7
		glow.Brightness = 0
		glow.Parent = lamp
		local zone = add(newPart(Vector3.new(0.05, (radius or 5) * 2, (radius or 5) * 2), base * CFrame.new(0, 0.06, 0) * CFrame.Angles(0, 0, math.rad(90)), DK.YELLOW, Enum.Material.Neon, Enum.PartType.Cylinder))
		zone.Transparency = 1
		local rec = { parts = parts, lamp = lamp, glow = glow, zone = zone, prongs = prongs, pos = g, top = lamp.Position }
		DK.traps[id] = rec
		-- armed: the lamp lights, the zone shows faintly, and it hums
		task.spawn(function()
			task.wait(arm or 0.5)
			if DK.traps[id] ~= rec then
				return
			end
			rec.armed = true
			tween(zone, 0.3, { Transparency = 0.88 })
			sparks(rec.top, 0.4, WHITE, DK.YELLOW, 5)
			VFX.PlaySound("StaticCrackle", g, 0.5)
			local t0 = os.clock()
			while DK.traps[id] == rec and os.clock() - t0 < (life or 25) + 1 do
				lamp.Color = DK.YELLOW
				lamp.Material = Enum.Material.Neon
				glow.Brightness = 2
				task.wait(0.12)
				if DK.traps[id] ~= rec then
					break
				end
				lamp.Color = Color3.fromRGB(90, 80, 40)
				lamp.Material = Enum.Material.Glass
				glow.Brightness = 0.4
				if rng:NextNumber() < 0.6 then
					local p1 = prongs[rng:NextInteger(1, 4)]
					local p2 = prongs[rng:NextInteger(1, 4)]
					if p1 ~= p2 then
						DK.arc(p1.Position + UP * 0.3, p2.Position + UP * 0.3, DK.YELLOW, 0.05)
					end
					DK.arc(rec.top, rec.top + UP * rand(0.6, 1.2) + rng:NextUnitVector() * 0.4, WHITE, 0.05)
				end
				task.wait(rand(0.35, 0.6))
			end
		end)
		task.delay((life or 25) + 1.5, DK.untrap, id, nil)
		return rec
	end
	-- a live wire from the trap's coil to a pointer (a person or a spot)
	function DK.wire(id, target)
		local rec = DK.traps[id]
		if not rec then
			return
		end
		rec.wireTo = target
		task.spawn(function()
			while DK.traps[id] == rec and rec.wireTo == target do
				local to = typeof(target) == "Vector3" and target
					or (typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart") and target.HumanoidRootPart.Position)
				if not to then
					break
				end
				-- a thin crackling line with a sag to it, redrawn every beat
				local a = rec.top
				local mid = (a + to) / 2 - UP * math.min((to - a).Magnitude * 0.05, 1.5)
				DK.arc(a, mid, DK.YELLOW, 0.06)
				DK.arc(mid, to, DK.YELLOW, 0.06)
				task.wait(0.08)
			end
		end)
	end
	function DK.untrap(id, how)
		local rec = DK.traps[id]
		if not rec then
			return
		end
		DK.traps[id] = nil
		rec.wireTo = nil
		if how == "Expired" or how == "Replaced" then
			sparks(rec.top, 0.5, WHITE, DK.YELLOW, 5)
			VFX.PlaySound("ElectricZap", rec.pos, 0.4)
		end
		for _, p in rec.parts do
			tween(p, 0.25, { Transparency = 1 })
			cleanup(p, 0.3)
		end
	end
	function Effects.ZapTrapSet(char, data, isLocal)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not pos then
			return
		end
		-- (round 59) nobody but him can see it: on anyone else's screen there's
		-- nothing there until it goes off
		local me = Players.LocalPlayer
		if not (me and char == me.Character) then
			return
		end
		if isLocal then
			face(root, flatten(pos - root.Position, root))
		end
		-- tossed out of his hand onto the street
		local hand = handPos(char, true)
		local toss = newPart(Vector3.new(0.3, 1.4, 1.4), CFrame.new(hand), DK.STEEL, Enum.Material.Metal, Enum.PartType.Cylinder)
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < 0.18 do
				local k = (os.clock() - t0) / 0.18
				toss.CFrame = CFrame.new(hand:Lerp(pos, k) + UP * math.sin(k * math.pi) * 2) * CFrame.Angles(k * 9, 0, math.rad(90))
				task.wait()
			end
			toss:Destroy()
			if data.Id then
				DK.trap(data.Id, pos, math.max((tonumber(data.Arm) or 0.5) - 0.18, 0), tonumber(data.Life) or 25, nil)
				DK.fenceLoop() -- (round 68)
				if data.WireTo then
					DK.wire(data.Id, data.WireTo)
					VFX.PlaySound("StaticCrackle", pos, 0.8)
				end
			end
			sparks(pos + UP * 0.4, 0.6, WHITE, DK.YELLOW, 6)
			dustPuffs(pos, 0.4, 3, Color3.fromRGB(200, 190, 175), 0.4, false)
			VFX.PlaySound("PointerStick", pos, 1.2)
		end)
		VFX.PlaySound("Swish", root.Position, 0.6)
	end
	-- stepped on: it goes up through them
	function Effects.ZapTrapSnap(_char, data)
		local rec = data.Id and DK.traps[data.Id]
		local pos = rec and rec.top or (typeof(data.Pos) == "Vector3" and data.Pos + UP)
		if not pos then
			return
		end
		DK.untrap(data.Id, "Snap")
		for _, target in type(data.Targets) == "table" and data.Targets or {} do
			local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
			if troot then
				for k = 1, 2 do
					DK.zig(pos, troot.Position + UP * rand(-0.5, 1.5), k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.35 or 0.18, 0.35, 0.6)
				end
				DK.zap(troot.Position + UP, 1.1, DK.YELLOW)
			end
		end
		for k = 1, 5 do
			local a = k / 5 * math.pi * 2
			DK.zig(pos, pos + Vector3.new(math.cos(a) * 3, rand(1.5, 4), math.sin(a) * 3), DK.YELLOW, 0.2, 0.25, 0.5)
		end
		shockDisc(pos - UP * 0.8, UP, 1, 12, 0.25, DK.YELLOW, 4)
		billboardRing(pos, 1, 12, WHITE, 5, 0.2)
		groundMark(pos - UP, 2.5, Color3.fromRGB(50, 44, 30), 6)
		VFX.PlaySound("ElectricZap", pos, 1.2)
		VFX.PlaySound("Discharge", pos, 0.7)
		VFX.ShakeAt(pos, 0.8, 40, 0.15)
		if nearCamera(pos, 30) then
			VFX.ImpactFrame(0.05)
		end
	end
	function Effects.ZapTrapGone(_char, data)
		if data.How ~= "Snap" and data.How ~= "Overload" then
			DK.untrap(data.Id, data.How)
		end
	end
	function Effects.ZapTrapWireJolt(_char, data)
		local rec = data.Id and DK.traps[data.Id]
		local troot = typeof(data.Target) == "Instance" and data.Target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return
		end
		if rec then
			DK.zig(rec.top, troot.Position, DK.YELLOW, 0.22, 0.2, 0.4)
		end
		DK.zap(troot.Position + UP, 0.9, DK.YELLOW)
		VFX.PlaySound("ElectricZap", troot.Position, 0.9)
	end
	function Effects.ZapTrapWireCut(_char, data)
		local rec = data.Id and DK.traps[data.Id]
		if rec then
			rec.wireTo = nil
			sparks(rec.top, 0.6, WHITE, DK.YELLOW, 8)
			VFX.PlaySound("ElectricZap", rec.pos, 0.6)
		end
	end
	-- a Stun Bolt into a trap: it overloads
	-- (round 68) THE FENCE between his armed traps (Config: FenceRange): a
	-- faint crackle only he can see - his traps are only on his screen -
	-- redrawn while two or more are armed; when someone runs through it the
	-- whole span flares up on everyone's (Effects.ZapTrapFenceJolt)
	function DK.fenceLoop()
		if DK.fencing then
			return
		end
		DK.fencing = true
		task.spawn(function()
			local range = 40
			for _, a in (Config.Quirks.Electrification or {}).Abilities or {} do
				if a.Id == "ZapTrap" then
					range = a.FenceRange or range
				end
			end
			while next(DK.traps) ~= nil do
				local armed = {}
				for _, rec in DK.traps do
					if rec.armed then
						table.insert(armed, rec)
					end
				end
				for i = 1, #armed - 1 do
					for j = i + 1, #armed do
						local a, b = armed[i].top, armed[j].top
						local across = Vector3.new(b.X - a.X, 0, b.Z - a.Z).Magnitude
						if across > 0.5 and across <= range then
							DK.arc(a - UP * 0.35, b - UP * 0.35, DK.YELLOW, 0.035)
						end
					end
				end
				task.wait(0.1)
			end
			DK.fencing = false
		end)
	end
	function Effects.ZapTrapFenceJolt(_char, data)
		local pa = typeof(data.PA) == "Vector3" and data.PA
		local pb = typeof(data.PB) == "Vector3" and data.PB
		if not pa or not pb then
			return
		end
		-- it was there all along: the whole span flares
		DK.zig(pa + UP * 1.2, pb + UP * 1.2, DK.YELLOW, 0.2, 0.25, 0.6)
		DK.zig(pa + UP * 2.4, pb + UP * 2.4, DK.BLUE, 0.1, 0.2, 0.6)
		local at = typeof(data.Pos) == "Vector3" and data.Pos or (pa + pb) / 2
		local target = data.Target
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		if troot then
			DK.zig(at + UP * 1.2, troot.Position, DK.YELLOW, 0.22, 0.3, 0.5)
			DK.zap(troot.Position + UP, 1, DK.YELLOW)
		end
		VFX.PlaySound("ElectricZap", at, 1)
		VFX.ShakeAt(at, 0.5, 30, 0.12)
	end
	function Effects.ZapTrapOverload(_char, data)
		local rec = data.Id and DK.traps[data.Id]
		local pos = rec and rec.top or (typeof(data.Pos) == "Vector3" and data.Pos + UP)
		if not pos then
			return
		end
		DK.untrap(data.Id, "Overload")
		local radius = tonumber(data.Radius) or 14
		local flash = newPart(Vector3.one * 2, CFrame.new(pos), WHITE, Enum.Material.Neon, Enum.PartType.Ball)
		tween(flash, 0.3, { Size = Vector3.one * radius * 1.2, Transparency = 1 })
		cleanup(flash, 0.32)
		for k = 1, 12 do
			local a = k / 12 * math.pi * 2
			DK.zig(pos, pos + Vector3.new(math.cos(a), rand(-0.1, 0.5), math.sin(a)).Unit * radius * rand(0.7, 1), k % 2 == 0 and DK.YELLOW or DK.BLUE, 0.3, 0.35, 1)
		end
		DK.zig(pos, pos + UP * 18, WHITE, 0.5, 0.4, 1.4)
		shockDisc(pos - UP * 0.6, UP, 2, radius * 2, 0.35, WHITE, 6)
		billboardRing(pos, 2, radius * 2.4, DK.YELLOW, 7, 0.3)
		rocks(pos, 0.8, 8)
		groundMark(pos - UP, radius * 0.4, Color3.fromRGB(50, 44, 30), 8)
		VFX.PlaySound("Thunderbolt", pos, 1.2)
		VFX.PlaySound("Discharge", pos, 1)
		VFX.ShakeAt(pos, 2, 90, 0.35)
		if nearCamera(pos, 60) then
			VFX.ImpactFrame(0.08)
		end
	end

	-- 1 in the air: THUNDER DIVE - down out of the sky as a bolt
	function Effects.ThunderDive(char, data)
		local root = charParts(char)
		local from = typeof(data.From) == "Vector3" and data.From
		local to = typeof(data.To) == "Vector3" and data.To
		if not root or not from or not to then
			return
		end
		local time = tonumber(data.Time) or 0.2
		VFX.MuteGait(char, time + 0.5)
		VFX.Pose(char, "ThunderDive", 0.05)
		DK.crackleOn(char, time + 0.1, DK.YELLOW)
		for k = 1, 2 do
			DK.zig(from + UP * 6, to - UP * 2, k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.55 or 0.25, time + 0.25, k == 1 and 0.9 or 2)
		end
		local stop = addTrail(root, DK.YELLOW, 0.3, 2.5)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < time do
				afterimage(char, DK.YELLOW, 0.18)
				task.wait(0.03)
			end
			stop(0.1)
			VFX.Motion(char, "ThunderLand")
		end)
		VFX.PlaySound("Thunderbolt", from, 0.9)
	end

	-- 4: the finger gun: one bolt, and the jump
	function Effects.StunBoltHit(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local points = type(data.Points) == "table" and data.Points or {}
		sparks(handPos(char, true), 0.5, WHITE, DK.YELLOW, 5)
		VFX.PlaySound("ElectricZap", root.Position, 1)
		-- (Relay = the point it ricochets off: a pointer's ping, then each
		-- bounce a beat after the last, the way the server lands them)
		local relay = tonumber(data.Relay)
		for i = 1, #points - 1 do
			local a, b = points[i], points[i + 1]
			if typeof(a) == "Vector3" and typeof(b) == "Vector3" then
				local at = relay and i >= relay and (i - relay + 1) * 0.08 or (i - 1) * 0.1
				task.delay(at, function()
					DK.zig(a, b, i == 1 and DK.YELLOW or DK.BLUE, i == 1 and 0.34 or 0.26, 0.3, 0.9)
					DK.zap(b, (data.Hit or i > 1) and 1 or 0.4, DK.YELLOW)
					if relay and i == relay - 1 then
						-- off the pointer: a ping and a ring
						billboardRing(b, 0.5, 7, DK.ORANGE, 4, 0.18)
						VFX.PlaySound("PointerStick", b, 1.3)
					end
					if i > 1 then
						VFX.PlaySound("ElectricZap", b, 0.8)
					end
				end)
			end
		end
	end

	-- ULT: the works
	function Effects.IndiscriminateBoom(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local radius = tonumber(data.Radius) or 34
		local c = root.Position + UP
		-- the flash
		local flash = newPart(Vector3.one * 4, CFrame.new(c), WHITE, Enum.Material.Neon, Enum.PartType.Ball)
		flash.Transparency = 0.2
		tween(flash, 0.35, { Size = Vector3.one * radius * 0.8, Transparency = 1 })
		cleanup(flash, 0.4)
		for i = 1, 20 do
			local a = i / 20 * math.pi * 2
			local out = Vector3.new(math.cos(a), rand(-0.1, 0.5), math.sin(a)).Unit
			DK.zig(c, c + out * radius * rand(0.75, 1), i % 2 == 0 and DK.YELLOW or DK.BLUE, 0.35, 0.4, 1.6)
		end
		for k = 1, 3 do
			task.delay((k - 1) * 0.08, function()
				billboardRing(c, 2, radius * 2.2, k == 2 and WHITE or DK.YELLOW, 8, 0.4)
			end)
		end
		shockDisc(root.Position + UP * 0.3, UP, 3, radius * 2, 0.45, WHITE, 6)
		groundMark(groundPoint(root.Position), radius * 0.5, Color3.fromRGB(50, 44, 30), 10)
		dustPuffs(groundPoint(root.Position), 2, 10, Color3.fromRGB(210, 200, 180), 1.2, true)
		VFX.PlaySound("Thunderbolt", c, 1.3)
		VFX.PlaySound("Discharge", c, 1.2)
		VFX.ShakeAt(c, 3, 160, 0.5)
		if nearCamera(c, 100) then
			VFX.ImpactFrame(0.1)
		end
	end
	function Effects.LightningStrikes(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local spots = type(data.Spots) == "table" and data.Spots or {}
		for i, spot in spots do
			if typeof(spot) == "Vector3" then
				landingMarker(spot, 0.25 + (i - 1) * 0.12)
				task.delay(0.25 + (i - 1) * 0.12, function()
					for k = 1, 2 do
						DK.zig(spot + UP * 70, spot, k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.6 or 0.25, 0.35, k == 1 and 1 or 2.5)
					end
					DK.zap(spot + UP, 2, DK.YELLOW)
					local flash = newPart(Vector3.one * 2, CFrame.new(spot + UP), WHITE, Enum.Material.Neon, Enum.PartType.Ball)
					tween(flash, 0.25, { Size = Vector3.one * 14, Transparency = 1 })
					cleanup(flash, 0.3)
					rocks(spot, 0.9, 8)
					dustPuffs(spot, 1, 5, Color3.fromRGB(210, 200, 180), 0.9, true)
					groundMark(groundPoint(spot + UP), 4, Color3.fromRGB(50, 44, 30), 8)
					VFX.PlaySound("Thunderbolt", spot, 1.2)
					VFX.ShakeAt(spot, 1.6, 80, 0.3)
					if nearCamera(spot, 60) then
						VFX.ImpactFrame(0.07)
					end
				end)
			end
		end
	end
	function Effects.ChainBolts(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local points = type(data.Points) == "table" and data.Points or {}
		VFX.PlaySound("Discharge", root.Position, 1)
		for i = 1, #points - 1 do
			local a, b = points[i], points[i + 1]
			if typeof(a) == "Vector3" and typeof(b) == "Vector3" then
				task.delay((i - 1) * 0.09, function()
					for k = 1, 2 do
						DK.zig(a, b, k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.4 or 0.2, 0.3, k == 1 and 0.8 or 1.8)
					end
					DK.zap(b, 1.2, DK.YELLOW)
					VFX.PlaySound("ElectricZap", b, 0.9)
				end)
			end
		end
	end

	-- wheeey: thumbs up, a little static off his head, the word over him
	function Effects.Wheey(char, data)
		local root = charParts(char)
		local head = char and char:FindFirstChild("Head")
		if not root then
			return
		end
		local time = tonumber(data.Duration) or 2
		VFX.MuteGait(char, time)
		VFX.Motion(char, "Wheey")
		VFX.PlaySound("Wheey", root.Position, 1)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new((head or root).Position + UP * 2), WHITE, nil)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(150, 46)
		bb.AlwaysOnTop = true
		bb.MaxDistance = 120
		bb.LightInfluence = 0
		bb.Parent = anchor
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Text = "WHEEEY"
		label.TextScaled = true
		label.Font = Enum.Font.LuckiestGuy
		label.TextColor3 = DK.YELLOW
		label.TextStrokeTransparency = 0
		label.TextStrokeColor3 = Color3.new(0, 0, 0)
		label.Rotation = -8
		label.Parent = bb
		cleanup(anchor, time)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < time and root.Parent do
				anchor.CFrame = CFrame.new((head or root).Position + UP * (2 + math.sin(os.clock() * 5) * 0.15))
				label.Rotation = math.sin(os.clock() * 6) * 10
				if rng:NextNumber() < 0.35 then
					bolt((head or root).Position + UP * 0.6, 0.8, DK.YELLOW)
				end
				task.wait(0.05)
			end
		end)
	end


	-- the casts (played the moment a move's used, from the aim alone; the
	-- server's effects follow with what happened)
	function Effects.Pointer(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "Pointer")
	end
	function Effects.Discharge(char)
		VFX.Motion(char, "Discharge")
		DK.crackleOn(char, 0.35, DK.YELLOW)
		local root = charParts(char)
		if root then
			VFX.PlaySound("StaticCrackle", root.Position, 0.9)
		end
	end
	function Effects.ElectricGrasp(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "ElectricGrasp")
		DK.crackleOn(char, 0.3, DK.YELLOW)
	end
	function Effects.ZapTrap(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "ZapTrap")
		DK.crackleOn(char, 0.3, DK.YELLOW)
		if root then
			VFX.PlaySound("StaticCrackle", root.Position, 0.8)
		end
	end
	function Effects.StunBolt(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "StunBolt")
	end
	function Effects.IndiscriminateDischarge(char)
		VFX.Motion(char, "Volts")
		DK.crackleOn(char, 0.9, DK.YELLOW)
		local root = charParts(char)
		if root then
			VFX.PlaySound("StaticCrackle", root.Position, 1.2)
		end
	end
	function Effects.LightningRod(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "BlastUp", 0.6)
		DK.crackleOn(char, 0.5, DK.YELLOW)
	end
	function Effects.ChainLightning(char)
		VFX.Motion(char, "DischargeLine")
		DK.crackleOn(char, 0.4, DK.YELLOW)
	end
	-- a dash: a crackle and a streak
	QUIRK_FX.Dash.Electrification = function(char, root, dir)
		DK.crackleOn(char, 0.2, DK.YELLOW)
		DK.zig(root.Position - dir * 4 + UP, root.Position + UP, DK.YELLOW, 0.16, 0.2, 0.5)
		streaks(root.Position - dir + UP, dir, 6, 0.8, 5, 8, DK.YELLOW, 0.2)
		legTrails(char, 0.25, DK.YELLOW)
	end
	-- 1,300,000 VOLTS: a column of lightning up off him, rings, and static
	-- all over him for the whole ult
	QUIRK_FX.Ult.Electrification = function(char, root, g)
		VFX.Motion(char, "Volts")
		for k = 1, 3 do
			DK.zig(root.Position, root.Position + UP * 30 + rng:NextUnitVector() * 4, k == 2 and DK.BLUE or DK.YELLOW, 0.5, 0.6, 2)
		end
		billboardRing(root.Position + UP, 2, 30, DK.YELLOW, 7, 0.4)
		shockDisc(g + UP * 0.3, UP, 2, 26, 0.35, WHITE, 5)
		sparks(root.Position + UP * 2, 1.6, WHITE, DK.YELLOW, 24)
		-- (all through the ult: arcs crawling over him, now and then one
		-- cracking off into the street)
		task.spawn(function()
			while char.Parent and char:GetAttribute("UltActive") do
				DK.crackleOn(char, 0.3, rng:NextNumber() < 0.7 and DK.YELLOW or DK.BLUE)
				if rng:NextNumber() < 0.35 and root.Parent then
					local at = root.Position + UP * rand(0, 2)
					DK.zig(at, groundPoint(at + Vector3.new(rand(-5, 5), 0, rand(-5, 5))), DK.YELLOW, 0.14, 0.18, 0.5)
				end
				task.wait(0.3)
			end
		end)
	end
	-- M1s: every hit crackles
	function VFX.ElectrificationPunch(_char, count, finisher, fist, look)
		for _ = 1, finisher and 4 or 2 do
			DK.arc(fist, fist + (look * 0.6 + rng:NextUnitVector()).Unit * rand(1, finisher and 2.6 or 1.6), DK.YELLOW, 0.07)
		end
		sparks(fist, finisher and 0.9 or 0.4, WHITE, DK.YELLOW, finisher and 10 or 3)
		VFX.PlaySound("ElectricZap", fist, finisher and 1 or 0.55)
		if count == 4 or finisher then
			billboardRing(fist + look, 0.6, 8, DK.YELLOW, 4, 0.18)
		end
	end
	-- the finisher: a hand on them and everything he's got, point blank
	function DK.finisher(char, target, troot, _d, time)
		VFX.Pose(char, "GraspHold", time)
		DK.crackleOn(char, time, DK.YELLOW)
		DK.crackleOn(target, time, DK.YELLOW)
		VFX.PlaySound("StaticCrackle", troot.Position, 1)
		task.wait(time * 0.6)
		if not troot.Parent then
			return
		end
		for k = 1, 3 do
			DK.zig(handPos(char, true), troot.Position + UP, k == 2 and DK.BLUE or DK.YELLOW, 0.35, 0.35, 1.2)
		end
		DK.zap(troot.Position + UP, 1.8, DK.YELLOW)
		VFX.PlaySound("Discharge", troot.Position, 1.1)
	end
	-- the KO burst: a bolt from the sky and lightning everywhere
	function DK.burst(pos, dir)
		for k = 1, 2 do
			DK.zig(pos + UP * 50, pos + UP, k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.5 or 0.25, 0.4, 2)
		end
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			DK.zig(pos + UP, pos + UP + Vector3.new(math.cos(a), 0.3, math.sin(a)) * rand(6, 12), DK.YELLOW, 0.25, 0.35, 1.2)
		end
		shockDisc(pos, dir, 2, 30, 0.35, WHITE, 5)
		billboardRing(pos, 2, 26, DK.YELLOW, 6, 0.3)
		sparks(pos, 1.5, WHITE, DK.YELLOW, 20)
		VFX.PlaySound("Thunderbolt", pos, 1)
	end
end

---------------------------------------------------------------------------
-- PUPPETS: figures built out of parts - a torso, a head, two arms and two
-- legs, each a list of pieces - and posed every frame from a small pose
-- table. Best Jeanist on the Sky Coffin; All Might and All For One in the
-- sky. Per limb: { pitch (+ forward), yaw (+ inward), roll (+ outward),
-- bend } in degrees - bend folds the elbow / knee (pieces on "foreR" /
-- "shinR" etc. hang off it); head { pitch (+ up), yaw }; lean (+ back),
-- twist (+ left), roll (+ tips right).
---------------------------------------------------------------------------
do
	local PUP = { LIMBS = { "armR", "armL", "legR", "legL" } }
	VFX.PUP = PUP

	function PUP.new(name, scale, outline)
		local model = Instance.new("Model")
		model.Name = name
		model.Parent = folder
		local pp = { model = model, parts = {}, scale = scale or 1, frames = {} }
		if outline then
			local hl = Instance.new("Highlight")
			hl.FillTransparency = 1
			hl.OutlineColor = outline
			hl.OutlineTransparency = 0.2
			hl.DepthMode = Enum.HighlightDepthMode.Occluded
			hl.Adornee = model
			hl.Parent = model
			pp.highlight = hl
		end
		return pp
	end

	-- a piece on a limb (size and offset at scale 1)
	function PUP.part(pp, key, size, offset, color, material, shape)
		local s = pp.scale
		local p = newPart(size * s, CFrame.new(), color, material, shape, pp.model)
		table.insert(pp.parts, { part = p, key = key, offset = offset.Rotation + offset.Position * s })
		if key == "head" and not pp.head then
			pp.head = p
		end
		return p
	end

	function PUP.limb(pivot, spec, side)
		spec = spec or {}
		return pivot * CFrame.Angles(0, math.rad(side * (spec[2] or 0)), 0) * CFrame.Angles(0, 0, math.rad(side * (spec[3] or 0))) * CFrame.Angles(math.rad(spec[1] or 0), 0, 0)
	end

	-- cf: the middle of the torso
	function PUP.place(pp, cf, pose)
		local s = pp.scale
		local torso = cf * CFrame.Angles(0, 0, math.rad(-(pose.roll or 0))) * CFrame.Angles(math.rad(pose.lean or 0), math.rad(pose.twist or 0), 0)
		local head = pose.head or {}
		local f = pp.frames
		f.torso = torso
		f.head = torso * CFrame.new(0, s, 0) * CFrame.Angles(math.rad(head[1] or 0), math.rad(head[2] or 0), 0)
		f.armR = PUP.limb(torso * CFrame.new(1.5 * s, 0.5 * s, 0), pose.armR, 1)
		f.armL = PUP.limb(torso * CFrame.new(-1.5 * s, 0.5 * s, 0), pose.armL, -1)
		f.legR = PUP.limb(torso * CFrame.new(0.5 * s, -s, 0), pose.legR, 1)
		f.legL = PUP.limb(torso * CFrame.new(-0.5 * s, -s, 0), pose.legL, -1)
		-- elbows forward, knees back
		f.foreR = f.armR * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad((pose.armR or {})[4] or 0), 0, 0)
		f.foreL = f.armL * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad((pose.armL or {})[4] or 0), 0, 0)
		f.shinR = f.legR * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad(-((pose.legR or {})[4] or 0)), 0, 0)
		f.shinL = f.legL * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad(-((pose.legL or {})[4] or 0)), 0, 0)
		local parts, cfs = {}, {}
		for i, e in pp.parts do
			parts[i] = e.part
			cfs[i] = f[e.key] * e.offset
		end
		if not pcall(function()
			workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
		end) then
			for i, p in parts do
				p.CFrame = cfs[i]
			end
		end
	end

	-- the tip of an arm or leg (a fist, a foot)
	function PUP.tip(pp, key)
		if pp.jointed then
			local lower = key == "armR" and "foreR" or key == "armL" and "foreL" or key == "legR" and "shinR" or "shinL"
			return (pp.frames[lower] * CFrame.new(0, -pp.scale, 0)).Position
		end
		return (pp.frames[key] * CFrame.new(0, -1.5 * pp.scale, 0)).Position
	end

	-- a pose part-way from a to b
	function PUP.blend(a, b, k)
		local out = {}
		for _, key in { "armR", "armL", "legR", "legL", "head" } do
			local x, y = a[key] or {}, b[key] or {}
			out[key] = {}
			for i = 1, 4 do
				local u, v = x[i] or 0, y[i] or 0
				out[key][i] = u + (v - u) * k
			end
		end
		out.lean = (a.lean or 0) + ((b.lean or 0) - (a.lean or 0)) * k
		out.twist = (a.twist or 0) + ((b.twist or 0) - (a.twist or 0)) * k
		out.roll = (a.roll or 0) + ((b.roll or 0) - (a.roll or 0)) * k
		return out
	end

	-- 0 = gone, 1 = fully there (each piece keeps its own see-through-ness)
	function PUP.fade(pp, alpha)
		if pp.alpha == alpha then
			return
		end
		pp.alpha = alpha
		for _, e in pp.parts do
			if not e.nofade then
				e.base = e.base or e.part.Transparency
				e.part.Transparency = 1 - alpha * (1 - e.base)
			end
		end
		if pp.highlight then
			pp.highlight.OutlineTransparency = 1 - alpha * 0.8
		end
	end

	-- a shout over its head
	function PUP.say(pp, text, color, stroke, life, px, far)
		if not pp.head then
			return
		end
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(px or 260, math.floor((px or 260) * 0.24))
		bb.StudsOffsetWorldSpace = Vector3.new(0, 2.6 * pp.scale, 0)
		bb.LightInfluence = 0
		bb.MaxDistance = far or 400
		bb.Adornee = pp.head
		bb.Parent = pp.model
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.Font = Enum.Font.LuckiestGuy
		label.TextScaled = true
		label.Text = text
		label.TextColor3 = color
		label.TextStrokeColor3 = stroke
		label.TextStrokeTransparency = 0
		label.Rotation = rand(-5, 5)
		label.Parent = bb
		tween(label, life * 0.3, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, life * 0.7)
		cleanup(bb, life + 0.05)
	end
end

---------------------------------------------------------------------------
-- THE SKY COFFIN's floor defending itself against Decay (chapter 346): the
-- decay creeps over a plate, the plate's fired off into the sky and crumbles
-- to nothing - and BEST JEANIST rappels down out of the sky on a thread and
-- stitches the floor back together: denim fibers shoot from his fingers to
-- every empty socket, weave a mat across it, warp then weft, and it sets
-- hard into a new plate. When it's all mended he tugs his collar straight
-- and zips back up into the sky. (All for the eyes: nobody's hurt by it.)
---------------------------------------------------------------------------
do
	local ST = {
		LAWN = Color3.fromRGB(128, 166, 72),
		DECAYED = Color3.fromRGB(112, 100, 98),
		CRACK = Color3.fromRGB(36, 26, 30),
		DUST = Color3.fromRGB(150, 140, 142),
		SOCKET = Color3.fromRGB(28, 30, 34),
		DENIM = Color3.fromRGB(52, 78, 126),
		DENIM_LIGHT = Color3.fromRGB(116, 146, 196),
		JEANS = Color3.fromRGB(36, 54, 92),
		crew = {}, -- the Jeanists on duty
		snapAt = 0,
	}
	ST.POSES = {
		drop = { armR = { 172, 0, 4 }, armL = { 24, 0, 22 }, legR = { 12, 0, 4 }, legL = { -8, 0, 4 }, head = { -12, 0 } },
		land = { armR = { 56, -24, 44 }, armL = { 56, -24, 44 }, legR = { 42, 0, 12 }, legL = { -34, 0, 12 }, head = { 4, 0 }, lean = -20 },
		fibers = { armR = { 86, -26, 16 }, armL = { 86, -26, 16 }, legR = { 16, 0, 9 }, legL = { -12, 0, 9 }, head = { 2, 0 }, lean = 5 },
		collar = { armR = { 152, 50, 0 }, armL = { 12, 0, 8 }, legR = { 2, 0, 4 }, legL = { -2, 0, 4 }, head = { 10, -12 }, lean = 3 },
		zip = { armR = { 178, 0, 0 }, armL = { 176, 0, 0 }, legR = { -10, 0, 2 }, legL = { 10, 0, 2 }, head = { 18, 0 } },
	}

	-- the man himself: denim jacket and jeans, the high collar up over his
	-- mouth and nose, swept blond hair, a sharp stare
	function ST.jeanist()
		local PUP = VFX.PUP
		local pp = PUP.new("BestJeanist", 1.1, Color3.fromRGB(18, 24, 46))
		local D, DL, M = ST.DENIM, ST.DENIM_LIGHT, Enum.Material.Fabric
		local SKIN, HAIR = Color3.fromRGB(238, 200, 164), Color3.fromRGB(246, 222, 132)
		PUP.part(pp, "torso", Vector3.new(2, 2, 1), CFrame.new(), D, M)
		for side = -1, 1, 2 do
			PUP.part(pp, "torso", Vector3.new(0.08, 1.9, 0.05), CFrame.new(side * 0.18, 0, -0.52), DL, M)
			PUP.part(pp, "torso", Vector3.new(0.55, 0.42, 0.05), CFrame.new(side * 0.56, 0.42, -0.52), DL, M)
		end
		PUP.part(pp, "torso", Vector3.new(2.04, 0.26, 1.04), CFrame.new(0, -0.86, 0), Color3.fromRGB(96, 62, 36))
		PUP.part(pp, "torso", Vector3.new(0.42, 0.22, 0.08), CFrame.new(0, -0.86, -0.54), GOLD, Enum.Material.Metal)
		PUP.part(pp, "head", Vector3.new(1.1, 1.15, 1.1), CFrame.new(0, 0.62, 0), SKIN)
		PUP.part(pp, "head", Vector3.new(1.42, 0.95, 1.32), CFrame.new(0, 0.34, 0.02), D, M)
		PUP.part(pp, "head", Vector3.new(1.46, 0.1, 1.36), CFrame.new(0, 0.82, 0.02), DL, M)
		PUP.part(pp, "head", Vector3.new(1.2, 0.45, 1.2), CFrame.new(0, 1.3, 0.04), HAIR)
		PUP.part(pp, "head", Vector3.new(0.78, 0.55, 0.3), CFrame.new(-0.2, 1.1, -0.5) * CFrame.Angles(0, 0, math.rad(-18)), HAIR)
		PUP.part(pp, "head", Vector3.new(0.4, 0.5, 1.1), CFrame.new(0.5, 1.04, 0.05), HAIR)
		for side = -1, 1, 2 do
			PUP.part(pp, "head", Vector3.new(0.26, 0.07, 0.05), CFrame.new(side * 0.24, 0.94, -0.56), Color3.fromRGB(28, 32, 54))
		end
		for _, key in { "armR", "armL" } do
			PUP.part(pp, key, Vector3.new(1, 1.6, 1), CFrame.new(0, -0.3, 0), D, M)
			PUP.part(pp, key, Vector3.new(1.06, 0.26, 1.06), CFrame.new(0, -1.1, 0), DL, M)
			PUP.part(pp, key, Vector3.new(0.86, 0.5, 0.86), CFrame.new(0, -1.45, 0), SKIN)
		end
		for _, key in { "legR", "legL" } do
			PUP.part(pp, key, Vector3.new(1, 1.6, 1), CFrame.new(0, -0.8, 0), ST.JEANS, M)
			PUP.part(pp, key, Vector3.new(1.04, 0.5, 1.2), CFrame.new(0, -1.75, -0.08), Color3.fromRGB(58, 40, 30))
		end
		return pp
	end

	-- a thread: a strand of denim from his hand out to a point
	function ST.line(j, to, hand)
		local part = newPart(Vector3.new(0.14, 0.14, 1), CFrame.new(to), ST.DENIM_LIGHT, Enum.Material.Fabric)
		local line = { part = part, to = to, hand = hand, t0 = os.clock() }
		j.lines[line] = true
		return line
	end

	-- the Jeanist on duty near here (or a new one, rappelling in)
	function ST.jeanistFor(from, extent)
		local cfg = Config.SkyCoffin or {}
		local center = cfg.Center
		for _, j in ST.crew do
			if j.state ~= "leave" and (j.spot - from).Magnitude < 170 then
				return j
			end
		end
		if #ST.crew >= 3 then
			return ST.crew[#ST.crew]
		end
		local toMid = Vector3.new(center.X - from.X, 0, center.Z - from.Z)
		local dir = toMid.Magnitude > 5 and toMid.Unit or Vector3.new(1, 0, 0)
		local spot = from + dir * math.clamp(extent + 12, 30, 80)
		local flat = Vector3.new(spot.X - center.X, 0, spot.Z - center.Z)
		local LR = (cfg.Radius or 425) - 34
		if flat.Magnitude > LR then
			flat = flat.Unit * LR
		end
		spot = Vector3.new(center.X + flat.X, center.Y, center.Z + flat.Z)
		local s = 1.1
		local j = {
			pp = ST.jeanist(),
			spot = spot,
			stand = spot + UP * 3 * s,
			look = -dir,
			state = "enter",
			t0 = os.clock(),
			pose = ST.POSES.drop,
			queue = {},
			lines = {},
			active = 0,
			idleSince = nil,
		}
		j.sky = ST.line(j, j.stand + UP * 160, "armR")
		table.insert(ST.crew, j)
		VFX.PlaySound("Swish", spot, 1)
		return j
	end

	-- one socket stitched shut: a fiber out to it, the weave, the new plate
	function ST.stitch(j, job)
		j.active += 1
		local T, cf = job.T, job.cf
		local w = T - 0.3
		local hand = rng:NextNumber() < 0.5 and "armR" or "armL"
		local line = ST.line(j, cf.Position + UP * 0.25, hand)
		task.wait(0.2)
		local strips = {}
		if job.extra then
			-- warp, then weft, as fast as a sewing machine
			for pass = 1, 2 do
				for k = 1, 5 do
					local off = (k - 3) * w / 5
					local at = pass == 1 and CFrame.new(0, 0.2, off) or CFrame.new(off, 0.28, 0)
					local full = pass == 1 and Vector3.new(w, 0.1, 0.36) or Vector3.new(0.36, 0.1, w)
					local strip = newPart(pass == 1 and Vector3.new(0.2, 0.1, 0.36) or Vector3.new(0.36, 0.1, 0.2), cf * at, k % 2 == 0 and ST.DENIM_LIGHT or ST.DENIM, Enum.Material.Fabric)
					tween(strip, 0.1, { Size = full })
					table.insert(strips, strip)
					task.wait(0.03)
				end
			end
		else
			local mat = newPart(Vector3.new(0.3, 0.12, 0.3), cf * CFrame.new(0, 0.22, 0), ST.DENIM, Enum.Material.Fabric)
			tween(mat, 0.3, { Size = Vector3.new(w, 0.12, w) })
			table.insert(strips, mat)
			task.wait(0.3)
		end
		-- it sets hard into a new plate, and the lawn comes back over it
		local plate = newPart(Vector3.new(w, 0.3, w), cf * CFrame.new(0, 0.16, 0), ST.DENIM, Enum.Material.Fabric)
		plate.Transparency = 1
		tween(plate, 0.12, { Transparency = 0 })
		task.wait(0.12)
		if job.socket then
			job.socket:Destroy()
		end
		for _, strip in strips do
			strip:Destroy()
		end
		plate.Material = Enum.Material.Grass
		tween(plate, 0.35, { Color = ST.LAWN })
		if job.extra then
			for _, e in { { 0, w / 2, w, 0.25 }, { 0, -w / 2, w, 0.25 }, { w / 2, 0, 0.25, w }, { -w / 2, 0, 0.25, w } } do
				local edge = newPart(Vector3.new(e[3], 0.08, e[4]), cf * CFrame.new(e[1], 0.34, e[2]), ST.DENIM_LIGHT, Enum.Material.Neon)
				tween(edge, 0.35, { Transparency = 1 })
				cleanup(edge, 0.4)
			end
		end
		if os.clock() - ST.snapAt > 0.15 then
			ST.snapAt = os.clock()
			VFX.PlaySound("Snap", cf.Position, 0.7)
		end
		-- the fiber snaps back to his hand
		line.back = os.clock()
		tween(plate, 0.3, { Transparency = 1 }, nil, nil, 0.45)
		cleanup(plate, 0.8)
		task.wait(0.2)
		j.lines[line] = nil
		line.part:Destroy()
		j.active -= 1
	end

	-- one plate (cf: the middle of its top face, on the lawn)
	function ST.plate(cf, T, big, from, extent)
		local extra = not big or rng:NextNumber() < 0.35
		local top = newPart(Vector3.new(T - 0.3, 0.3, T - 0.3), cf * CFrame.new(0, 0.16, 0), ST.LAWN, Enum.Material.Grass)
		top.Name = "Plate"
		-- the decay creeps over it
		tween(top, 0.22, { Color = ST.DECAYED })
		local cracks = {}
		if extra then
			for _ = 1, 2 do
				local c = newPart(Vector3.new(T * rand(0.5, 0.9), 0.06, 0.2), cf * CFrame.new(rand(-T / 4, T / 4), 0.33, rand(-T / 4, T / 4)) * CFrame.Angles(0, rand(0, math.pi), 0), ST.CRACK, Enum.Material.Slate)
				c.Transparency = 1
				tween(c, 0.18, { Transparency = 0 })
				table.insert(cracks, c)
			end
		end
		task.wait(0.24)
		-- the socket it leaves, and the plate fired off: a slab spinning up into
		-- the sky, crumbling away as it goes
		local socket = newPart(Vector3.new(T - 0.2, 0.12, T - 0.2), cf * CFrame.new(0, 0.07, 0), ST.SOCKET, Enum.Material.Metal)
		socket.Name = "Socket"
		top.Material = Enum.Material.Slate
		top.Size = Vector3.new(T - 0.3, 1.6, T - 0.3)
		local height, life = rand(70, 150), rand(1.1, 1.6)
		local flyTo = cf * CFrame.new(rand(-6, 6), height, rand(-6, 6)) * CFrame.Angles(rand(-1.2, 1.2), rand(-2, 2), rand(-1.2, 1.2))
		tween(top, life, { CFrame = flyTo, Size = Vector3.new(T * 0.3, 0.5, T * 0.3), Transparency = 1 }, Enum.EasingStyle.Quad)
		cleanup(top, life + 0.05)
		cleanup(socket, 5) -- (in case nobody comes for it)
		for _, c in cracks do
			c:Destroy()
		end
		if extra then
			-- the launcher's kick out of the seams: chips of plate and decay dust
			for _ = 1, 3 do
				local chunk = newPart(Vector3.one * rand(0.6, 1.4), cf * CFrame.new(rand(-T / 2, T / 2), 0.6, rand(-T / 2, T / 2)), ST.DUST, Enum.Material.Slate)
				local t = rand(0.8, 1.3)
				tween(chunk, t, { CFrame = chunk.CFrame * CFrame.new(rand(-5, 5), rand(25, 70), rand(-5, 5)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Transparency = 1, Size = Vector3.one * 0.2 })
				cleanup(chunk, t + 0.05)
			end
		end
		-- and Best Jeanist sees to the hole
		local j = ST.jeanistFor(from, extent)
		table.insert(j.queue, { cf = cf, T = T, extra = extra, socket = socket, at = os.clock() + rand(0.2, 0.45) })
	end

	function ST.step(dt)
		local now = os.clock()
		local PUP = VFX.PUP
		local k = 1 - math.exp(-dt * 12)
		for i = #ST.crew, 1, -1 do
			local j = ST.crew[i]
			local t = now - j.t0
			local cf, target = nil, ST.POSES.fibers
			if j.state == "enter" then
				-- down the thread out of the sky, landing in a crouch
				local u = math.clamp(t / 0.55, 0, 1)
				local drop = (1 - u) ^ 2 * 120
				cf = CFrame.lookAt(j.stand + UP * drop, j.stand + UP * drop + j.look)
				target = ST.POSES.drop
				if u >= 1 then
					j.state, j.t0 = "work", now
					j.pose = ST.POSES.land
					j.sky.back = now
					shockDisc(j.spot + UP * 0.2, UP, 2, 14, 0.35, ST.DENIM_LIGHT, 0)
					dustPuffs(j.spot, 1, 6, ST.DUST, 0.6)
					PUP.say(j.pp, "FIBER MASTER!", ST.DENIM_LIGHT, Color3.fromRGB(14, 22, 48), 1.6)
					VFX.PlaySound("Scarf", j.spot, 1.1)
				end
			elseif j.state == "work" then
				local busy = j.active > 0 or #j.queue > 0
				-- turn to the holes he's working on
				local sum, n = Vector3.zero, 0
				for line in j.lines do
					if line ~= j.sky then
						sum += line.to
						n += 1
					end
				end
				if n > 0 then
					local d = Vector3.new(sum.X / n - j.stand.X, 0, sum.Z / n - j.stand.Z)
					if d.Magnitude > 1 then
						j.look = j.look:Lerp(d.Unit, k * 0.5)
					end
				end
				cf = CFrame.lookAt(j.stand, j.stand + j.look)
				local wiggle = math.sin(now * 18) * 6
				target = {
					armR = { 86 + wiggle, -26, 16 }, armL = { 86 - wiggle, -26, 16 },
					legR = ST.POSES.fibers.legR, legL = ST.POSES.fibers.legL, head = ST.POSES.fibers.head, lean = 5,
				}
				if t < 0.25 then
					target = ST.POSES.land
				end
				for q = #j.queue, 1, -1 do
					local job = j.queue[q]
					if now >= job.at and t >= 0.2 then
						table.remove(j.queue, q)
						task.spawn(ST.stitch, j, job)
					end
				end
				if busy then
					j.idleSince = nil
				elseif not j.idleSince then
					j.idleSince = now
				elseif now - j.idleSince > 0.6 then
					j.state, j.t0 = "leave", now
					PUP.say(j.pp, "A perfect fit.", ST.DENIM_LIGHT, Color3.fromRGB(14, 22, 48), 1.4)
				end
			elseif #j.queue > 0 and t < 0.7 then
				j.state, j.t0 = "work", now - 0.3 -- (more holes before he's gone: back to it)
				cf = CFrame.lookAt(j.stand, j.stand + j.look)
			else
				-- a tug at his collar, then back up his thread into the sky
				target = t < 0.7 and ST.POSES.collar or ST.POSES.zip
				local u = math.clamp((t - 0.7) / 0.5, 0, 1)
				cf = CFrame.lookAt(j.stand + UP * u * u * 140, j.stand + UP * u * u * 140 + j.look)
				if t >= 0.7 and not j.up then
					j.up = ST.line(j, j.stand + UP * 170, "armR")
					VFX.PlaySound("Swish", j.spot, 1)
				end
				PUP.fade(j.pp, 1 - math.clamp((t - 0.95) / 0.25, 0, 1))
				if t > 1.25 then
					for line in j.lines do
						line.part:Destroy()
					end
					j.pp.model:Destroy()
					table.remove(ST.crew, i)
					continue
				end
			end
			j.pose = PUP.blend(j.pose, target, k)
			PUP.place(j.pp, cf, j.pose)
			-- the fibers, from his hands out to their tips
			for line in j.lines do
				local hand = PUP.tip(j.pp, line.hand)
				local reach = line.back and 1 - math.clamp((now - line.back) / 0.18, 0, 1) or math.clamp((now - line.t0) / 0.18, 0, 1)
				local tip = hand:Lerp(line.to, reach)
				local len = (tip - hand).Magnitude
				line.part.Transparency = len < 0.2 and 1 or 0
				line.part.Size = Vector3.new(0.14, 0.14, math.max(len, 0.1))
				line.part.CFrame = CFrame.lookAt((hand + tip) / 2, tip + Vector3.new(0, 1e-3, 0))
			end
		end
	end
	RunService.RenderStepped:Connect(ST.step)

	function Effects.SkyTiles(_, data)
		local cfg = Config.SkyCoffin or {}
		local center = cfg.Center
		if not center or type(data.Tiles) ~= "table" then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or center
		if not nearCamera(from, 700) then
			return
		end
		local T = 12
		local big = #data.Tiles > 40
		local extent = 0
		local cfs = {}
		for _, t in data.Tiles do
			local ix, iz = tonumber(t[1]), tonumber(t[2])
			if ix and iz then
				local cf = CFrame.new(center + Vector3.new((ix + 0.5) * T, 0, (iz + 0.5) * T))
				extent = math.max(extent, (Vector3.new(cf.X - from.X, 0, cf.Z - from.Z)).Magnitude)
				table.insert(cfs, cf)
			end
		end
		extent = math.max(extent, math.min(tonumber(data.Reach) or 0, 160))
		local ground = Vector3.new(from.X, center.Y, from.Z)
		for _, cf in cfs do
			task.delay(rand(0, 0.08), ST.plate, cf, T, big, ground, extent)
		end
		VFX.PlaySound("Crumble", from, 1.1)
		task.delay(0.24, function()
			VFX.PlaySound("Leap", from, 0.9)
		end)
	end
end

---------------------------------------------------------------------------
-- ALL MIGHT vs ALL FOR ONE, in the sky. Every few minutes (Config.SkyBattle)
-- the two of them tear across the sky over wherever you are - the city or
-- the Sky Coffin - on everyone's screen at once. They fly: in on long arcs,
-- a loop chase, a corkscrew climb, weaving through Rivet Stab, a plummet and
-- back up. And they fight with elbows and knees: guards, jabs, hooks,
-- uppercuts, kicks, All For One's arm swelling to three times its size -
-- every hit a boom you feel, arriving late like thunder. Air Cannon punched
-- out of the air by a DETROIT SMASH; a clash that rings the clouds; CAROLINA
-- SMASH into the arm; "I AM HERE!" and a TEXAS SMASH; a warp gate at his
-- back; "GO BEYOND! PLUS ULTRA!" and the UNITED STATES OF SMASH that sends
-- him off over the horizon. Then All Might turns and points at you: "NEXT...
-- IT'S YOUR TURN." (Kamino, chapters 88-94.)
---------------------------------------------------------------------------
do
	local AB = {
		GOLD = Color3.fromRGB(246, 198, 52),
		BLUE = Color3.fromRGB(34, 72, 172),
		RED = Color3.fromRGB(204, 34, 46),
