		-- (round 54) held in the tendrils, kicking; flat out along the street,
		-- arms pumping, leaning into it; flat in the crater
		held = { armR = { 40, 0, 70, 40 }, armL = { 40, 0, 70, 40 }, legR = { 30, 0, 24, 60 }, legL = { -20, 0, 24, 40 }, head = { -24, 0 }, lean = 26, twist = 10 },
		sprint = { armR = { 64, 0, 10, 110 }, armL = { -54, 0, 10, 90 }, legR = { -54, 0, 4, 70 }, legL = { 54, 0, 4, 16 }, head = { 14, 0 }, lean = -42 },
		splat = { armR = { 100, 0, 80, 30 }, armL = { 100, 0, 80, 30 }, legR = { 10, 0, 30, 20 }, legL = { -10, 0, 30, 20 }, head = { -44, 0 }, lean = 88 },
		-- All For One's: the arm out taking hold, and the swing down
		grab = { armR = { 84, -18, 0, 10 }, armL = { 10, 0, 14, 30 }, legR = { 6, 0, 3, 10 }, legL = { -6, 0, 3, 10 }, lean = -8, twist = 22 },
		slam = { armR = { 168, 0, 24, 10 }, armL = { 40, 0, 20, 30 }, legR = { -20, 0, 4, 20 }, legL = { 20, 0, 4, 40 }, head = { -20, 0 }, lean = -58, twist = 30 },
	}
	AB.P = P
	VFX.AB = AB

	-- All Might in his prime: blue suit, red-and-white bands, gold gloves,
	-- boots and belt, the two famous bangs, the grin (jointed: elbows, knees)
	function AB.allMight()
		local PUP = VFX.PUP
		local pp = PUP.new("AllMight", 5, Color3.fromRGB(20, 20, 40))
		pp.jointed = true
		PUP.part(pp, "torso", Vector3.new(2.5, 2.1, 1.25), CFrame.new(), AB.BLUE)
		PUP.part(pp, "torso", Vector3.new(2.54, 0.3, 1.29), CFrame.new(0, 0.74, 0), AB.RED)
		PUP.part(pp, "torso", Vector3.new(2.54, 0.14, 1.29), CFrame.new(0, 0.52, 0), AB.WHITE)
		PUP.part(pp, "torso", Vector3.new(2.54, 0.28, 1.29), CFrame.new(0, -0.9, 0), AB.GOLD, Enum.Material.Metal)
		PUP.part(pp, "head", Vector3.new(1.15, 1.2, 1.15), CFrame.new(0, 0.62, 0), AB.SKIN)
		PUP.part(pp, "head", Vector3.new(1.25, 0.45, 1.25), CFrame.new(0, 1.25, 0.05), AB.HAIR)
		for side = -1, 1, 2 do
			PUP.part(pp, "head", Vector3.new(0.28, 1.7, 0.32), CFrame.new(side * 0.36, 1.92, -0.3) * CFrame.Angles(0, 0, math.rad(-side * 24)), AB.HAIR)
			PUP.part(pp, "head", Vector3.new(0.14, 0.14, 0.05), CFrame.new(side * 0.25, 0.86, -0.6), Color3.fromRGB(120, 200, 255), Enum.Material.Neon)
		end
		PUP.part(pp, "head", Vector3.new(1.02, 0.26, 0.05), CFrame.new(0, 0.86, -0.59), Color3.fromRGB(26, 34, 66))
		PUP.part(pp, "head", Vector3.new(0.72, 0.18, 0.05), CFrame.new(0, 0.38, -0.59), AB.WHITE)
		for _, k in { { "armR", "foreR" }, { "armL", "foreL" } } do
			PUP.part(pp, k[1], Vector3.new(1.15, 1.5, 1.15), CFrame.new(0, -0.25, 0), AB.BLUE)
			PUP.part(pp, k[1], Vector3.new(1.19, 0.22, 1.19), CFrame.new(0, 0.4, 0), AB.RED)
			PUP.part(pp, k[2], Vector3.new(1.12, 0.8, 1.12), CFrame.new(0, -0.35, 0), AB.GOLD)
			PUP.part(pp, k[2], Vector3.new(1.18, 0.5, 1.18), CFrame.new(0, -0.9, 0), AB.GOLD)
		end
		for _, k in { { "legR", "shinR" }, { "legL", "shinL" } } do
			PUP.part(pp, k[1], Vector3.new(1.08, 1.1, 1.08), CFrame.new(0, -0.5, 0), AB.BLUE)
			PUP.part(pp, k[1], Vector3.new(1.11, 0.2, 1.11), CFrame.new(0, -0.3, 0), AB.RED)
			PUP.part(pp, k[2], Vector3.new(1.1, 0.5, 1.1), CFrame.new(0, -0.25, 0), AB.BLUE)
			PUP.part(pp, k[2], Vector3.new(1.12, 0.6, 1.26), CFrame.new(0, -0.72, -0.08), AB.GOLD)
		end
		AB.trail(pp, AB.GOLD, AB.WHITE, 2.4)
		return pp
	end

	-- All For One at Kamino: the dark suit over a white shirt, the skull-like
	-- navy mask with its tubes, the life-support collar and its pipes - and
	-- the arm his quirks pump up to three times its size (hidden till then)
	function AB.allForOne()
		local PUP = VFX.PUP
		local pp = PUP.new("AllForOne", 5.2, Color3.fromRGB(90, 10, 40))
		pp.jointed = true
		PUP.part(pp, "torso", Vector3.new(2.3, 2.1, 1.15), CFrame.new(), AB.SUIT)
		PUP.part(pp, "torso", Vector3.new(0.6, 0.9, 0.05), CFrame.new(0, 0.5, -0.59), AB.WHITE)
		PUP.part(pp, "torso", Vector3.new(0.18, 0.72, 0.06), CFrame.new(0, 0.38, -0.62), Color3.fromRGB(110, 20, 40))
		PUP.part(pp, "torso", Vector3.new(2.1, 0.45, 1.6), CFrame.new(0, 1.12, 0), AB.PIPE, Enum.Material.Metal)
		for side = -1, 1, 2 do
			PUP.part(pp, "torso", Vector3.new(0.2, 0.9, 0.2), CFrame.new(side * 0.4, 0.6, -0.72), AB.PIPE, Enum.Material.Metal, Enum.PartType.Cylinder)
			PUP.part(pp, "torso", Vector3.new(0.2, 0.9, 0.2), CFrame.new(side * 0.4, 0.6, 0.72), AB.PIPE, Enum.Material.Metal, Enum.PartType.Cylinder)
		end
		PUP.part(pp, "head", Vector3.new(1.2, 1.3, 1.25), CFrame.new(0, 0.66, 0), AB.MASK, Enum.Material.Metal)
		PUP.part(pp, "head", Vector3.new(0.9, 0.42, 0.1), CFrame.new(0, 0.34, -0.64), Color3.fromRGB(44, 50, 78), Enum.Material.Metal)
		for side = -1, 1, 2 do
			PUP.part(pp, "head", Vector3.new(0.3, 0.2, 0.06), CFrame.new(side * 0.26, 0.86, -0.63), Color3.fromRGB(6, 6, 10))
			PUP.part(pp, "head", Vector3.new(0.2, 0.95, 0.2), CFrame.new(side * 0.32, 1.42, 0.26) * CFrame.Angles(math.rad(-35), 0, 0), AB.PIPE, Enum.Material.Metal)
		end
		PUP.part(pp, "head", Vector3.new(0.22, 1.05, 0.22), CFrame.new(0, 1.48, 0.36) * CFrame.Angles(math.rad(-40), 0, 0), AB.PIPE, Enum.Material.Metal)
		for _, k in { { "armR", "foreR" }, { "armL", "foreL" } } do
			PUP.part(pp, k[1], Vector3.new(1.08, 1.5, 1.08), CFrame.new(0, -0.25, 0), AB.SUIT)
			PUP.part(pp, k[2], Vector3.new(1.04, 0.8, 1.04), CFrame.new(0, -0.35, 0), AB.SUIT)
			PUP.part(pp, k[2], Vector3.new(0.86, 0.45, 0.86), CFrame.new(0, -0.85, 0), Color3.fromRGB(196, 186, 190))
		end
		for _, k in { { "legR", "shinR" }, { "legL", "shinL" } } do
			PUP.part(pp, k[1], Vector3.new(1.06, 1.1, 1.06), CFrame.new(0, -0.5, 0), AB.SUIT)
			PUP.part(pp, k[2], Vector3.new(1.04, 0.7, 1.04), CFrame.new(0, -0.35, 0), AB.SUIT)
			PUP.part(pp, k[2], Vector3.new(1.06, 0.36, 1.26), CFrame.new(0, -0.84, -0.08), Color3.fromRGB(10, 10, 14))
		end
		-- the pumped-up arm: swollen, dark red veins running down it
		pp.big = {}
		local function big(key, size, at, color, material)
			local p = PUP.part(pp, key, size, at, color, material)
			p.Transparency = 1
			pp.parts[#pp.parts].nofade = true
			table.insert(pp.big, { part = p, size = p.Size })
			p.Size = p.Size * 0.2
		end
		big("armR", Vector3.new(2.6, 2.2, 2.6), CFrame.new(0, -0.3, 0), Color3.fromRGB(60, 40, 48))
		big("foreR", Vector3.new(3.2, 3.2, 3.2), CFrame.new(0, -1.4, 0), Color3.fromRGB(64, 42, 50))
		big("foreR", Vector3.new(3.8, 2, 3.8), CFrame.new(0, -3.4, 0), Color3.fromRGB(70, 44, 52))
		for side = -1, 1, 2 do
			big("foreR", Vector3.new(0.2, 3, 0.2), CFrame.new(side * 1.62, -1.4, -0.4), AB.EVIL, Enum.Material.Neon)
			big("foreR", Vector3.new(0.2, 2.8, 0.2), CFrame.new(0.3, -1.5, side * 1.62), AB.EVIL, Enum.Material.Neon)
			big("armR", Vector3.new(0.18, 1.8, 0.18), CFrame.new(side * 1.3, -0.3, 0.2), AB.EVIL, Enum.Material.Neon)
		end
		AB.trail(pp, Color3.fromRGB(120, 40, 150), AB.DARK, 2.4)
		return pp
	end

	-- the arm swells up (or back down)
	function AB.arm(run, on)
		run.bigArm = on
		for _, b in run.afo.big do
			tween(b.part, on and 0.45 or 0.35, { Size = on and b.size or b.size * 0.2, Transparency = on and 0 or 1 }, on and Enum.EasingStyle.Back or Enum.EasingStyle.Quad)
		end
		if on then
			AB.boom(run, "MuscleRumble", 1.2)
		end
	end

	function AB.trail(pp, c0, c1, width)
		local torso = pp.parts[1].part
		local s = pp.scale
		local a0 = Instance.new("Attachment")
		a0.Position = Vector3.new(0, width * s / 2, 0)
		a0.Parent = torso
		local a1 = Instance.new("Attachment")
		a1.Position = Vector3.new(0, -width * s / 2, 0)
		a1.Parent = torso
		local tr = Instance.new("Trail")
		tr.Attachment0 = a0
		tr.Attachment1 = a1
		tr.Lifetime = 0.55
		tr.MinLength = 0.5
		tr.FaceCamera = true
		tr.LightEmission = 0.6
		tr.Color = ColorSequence.new(c0, c1)
		tr.Transparency = NumberSequence.new(0.2, 1)
		tr.Parent = torso
	end

	-- a flat sound that arrives late, the way thunder does - loud
	function AB.boom(run, name, volume)
		local cam = workspace.CurrentCamera
		local d = cam and (cam.CFrame.Position - run.S.Position).Magnitude or 400
		task.delay(math.min(d / 1100, 0.6), VFX.PlaySound, name, nil, volume * AB.LOUD)
	end

	function AB.flash(pos, size, color, life)
		local p = newPart(Vector3.one * size * 0.3, CFrame.new(pos), color, Enum.Material.Neon, Enum.PartType.Ball)
		tween(p, life, { Size = Vector3.one * size, Transparency = 1 })
		cleanup(p, life + 0.05)
	end

	-- a punch landing: the flash, rings, sparks, a shudder - and the boom
	function AB.hit(run, pos, size, color, dir)
		AB.flash(pos, 18 * size, AB.WHITE, 0.22)
		billboardRing(pos, 4, 60 * size, color or AB.WHITE, 5 + 2 * size, 0.3)
		sparks(pos, 1.2 * size + 0.8, AB.WHITE, color or AB.GOLD, math.floor(10 + 8 * size))
		if dir then
			shockDisc(pos, dir, 6, 26 * size, 0.3, WIND, 14 * size)
			streaks(pos, dir, 8, 0.35, 10 * size, 30 * size, WIND, 0.3)
		end
		AB.boom(run, size >= 2 and "DetroitImpact" or "HeavyHit", 0.9 + 0.3 * size)
		if size >= 2.5 then
			VFX.ImpactFrame(0.07)
		end
		if size >= 1.5 then
			AB.boom(run, "Smash", 0.5 + 0.3 * size)
			task.delay(0.3, VFX.Shake, 0.12 * size, 0.25)
		end
	end

	-- the clouds pushed out in a ring
	function AB.clouds(pos, count, radius, life)
		for i = 1, count do
			local a = i / count * math.pi * 2 + rand(-0.2, 0.2)
			local out = Vector3.new(math.cos(a), rand(-0.25, 0.25), math.sin(a))
			local puff = newPart(Vector3.one * rand(14, 26), CFrame.new(pos + out * 10), AB.WHITE, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.25
			tween(puff, life, { CFrame = CFrame.new(pos + out * radius), Size = puff.Size * 2.4, Transparency = 1 })
			cleanup(puff, life + 0.05)
		end
	end

	-- the sky lights up (or darkens) for a moment
	function AB.sky(run, brightness, tint, time)
		local cc = run.cc
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "SkyBattle"
			cc.Parent = game:GetService("Lighting")
			run.cc = cc
		end
		cc.Brightness = brightness
		cc.TintColor = tint or Color3.new(1, 1, 1)
		tween(cc, time, { Brightness = 0, TintColor = Color3.new(1, 1, 1) })
	end

	-- a shout, readable from the ground
	function AB.say(pp, text, big)
		local am = pp.model.Name == "AllMight"
		VFX.PUP.say(pp, text, am and AB.GOLD or AB.EVIL, am and Color3.fromRGB(70, 14, 10) or Color3.fromRGB(10, 4, 14), 2.6, big and 460 or 340, 4000)
	end

	-- a banner across the top of the screen
	function AB.banner(text, sub)
		local me = Players.LocalPlayer
		local gui = me and me:FindFirstChildOfClass("PlayerGui")
		if not gui then
			return
		end
		local sg = Instance.new("ScreenGui")
		sg.Name = "SkyBattleBanner"
		sg.ResetOnSpawn = false
		sg.IgnoreGuiInset = true
		sg.Parent = gui
		for i, line in { { text, 0.1, 0.065, AB.GOLD }, { sub, 0.168, 0.034, AB.WHITE } } do
			local label = Instance.new("TextLabel")
			label.Name = i == 1 and "Title" or "Sub"
			label.BackgroundTransparency = 1
			label.AnchorPoint = Vector2.new(0.5, 0)
			label.Position = UDim2.fromScale(0.5, line[2])
			label.Size = UDim2.fromScale(0.6, line[3])
			label.Font = Enum.Font.LuckiestGuy
			label.TextScaled = true
			label.Text = line[1]
			label.TextColor3 = line[4]
			label.TextStrokeColor3 = Color3.fromRGB(30, 12, 8)
			label.TextStrokeTransparency = 0
			label.TextTransparency = 1
			label.Parent = sg
			tween(label, 0.4, { TextTransparency = 0 })
			tween(label, 0.8, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, 3.4)
		end
		cleanup(sg, 4.4)
	end

	-- a warp gate: All For One's black goo, opening in mid-air
	function AB.gate(run, pos, life)
		local toYou = run.S:VectorToWorldSpace(Vector3.new(0, 0, 1))
		local disc = newPart(Vector3.new(0.6, 2, 2), CFrame.lookAt(pos, pos + toYou) * CFrame.Angles(0, math.pi / 2, 0), Color3.fromRGB(10, 4, 16), Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		tween(disc, 0.25, { Size = Vector3.new(0.6, 44, 44) }, Enum.EasingStyle.Back)
		tween(disc, 0.3, { Size = Vector3.new(0.6, 2, 2), Transparency = 1 }, nil, nil, life)
		cleanup(disc, life + 0.35)
		billboardRing(pos, 38, 50, Color3.fromRGB(130, 40, 170), 5, life)
		for _ = 1, 6 do
			local goo = newPart(Vector3.one * rand(3, 6), CFrame.new(pos + Vector3.new(rand(-14, 14), rand(-18, -8), rand(-4, 4))), Color3.fromRGB(12, 6, 18), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			tween(goo, life, { CFrame = goo.CFrame - UP * rand(20, 50), Size = Vector3.one * 0.5, Transparency = 1 })
			cleanup(goo, life + 0.05)
		end
		AB.boom(run, "WarpGate", 0.9)
	end

	-- a smear: the streak a fist leaves on the frame when it's too fast to draw
	function AB.smear(a, b, color, width)
		local v = b - a
		if v.Magnitude < 1 then
			return
		end
		local bar = newPart(Vector3.new(width or 3, width or 3, v.Magnitude + 4), CFrame.lookAt((a + b) / 2, b), color, Enum.Material.Neon)
		bar.Name = "Smear"
		bar.Transparency = 0.15
		tween(bar, 0.14, { Transparency = 1, Size = Vector3.new(0.3, 0.3, v.Magnitude + 4) })
		cleanup(bar, 0.16)
	end

	-- SPRING-LIKE LIMBS: black tendrils shoot out of his arm and take hold
	function AB.tendrils(run, from, to, count, life)
		local hold = newPart(Vector3.one * 0.2, CFrame.new(from), Color3.new(), nil, nil, folder)
		hold.Name = "Tendrils"
		hold.Transparency = 1
		for i = 1, count or 6 do
			local a0 = Instance.new("Attachment")
			a0.Parent = hold
			local a1 = Instance.new("Attachment")
			a1.CFrame = CFrame.new(to - from + rng:NextUnitVector() * rand(4, 9))
			a1.Parent = hold
			local b = Instance.new("Beam")
			b.Name = "Tendril"
			b.Attachment0, b.Attachment1 = a0, a1
			b.Color = ColorSequence.new(AB.DARK, AB.EVIL)
			b.Width0, b.Width1 = 2.6, 0.9
			b.Transparency = NumberSequence.new(0)
			b.LightEmission = 0.3
			b.LightInfluence = 0
			b.FaceCamera = true
			b.Segments = 14
			b.CurveSize0, b.CurveSize1 = rand(-30, 30), rand(-30, 30)
			b.ZOffset = i * 0.05
			b.Parent = hold
			tween(b, 0.2, { CurveSize0 = rand(-8, 8), CurveSize1 = rand(-8, 8) })
			tween(b, 0.15, { Width0 = 0, Width1 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, (life or 0.8) - 0.15)
		end
		cleanup(hold, (life or 0.8) + 0.1)
		AB.boom(run, "Rivet", 1)
	end

	-- hammered into the street: the crater, dust, slabs of it flung up, the
	-- frame going black and white
	function AB.crater(run, pos)
		AB.flash(pos, 44, AB.WHITE, 0.3)
		shockDisc(pos + UP * 2, UP, 10, 180, 0.5, WIND)
		billboardRing(pos + UP * 4, 10, 220, AB.WHITE, 9, 0.5)
		dustPuffs(pos, 5, 14, Color3.fromRGB(196, 190, 182), 1.5, true)
		for _ = 1, 14 do
			local s = rand(3, 8)
			local slab = newPart(Vector3.new(s, s * rand(0.3, 0.6), s * rand(0.6, 1.3)), CFrame.new(pos + Vector3.new(rand(-8, 8), 2, rand(-8, 8))) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Color3.fromRGB(92, 92, 98), Enum.Material.Slate)
			tween(slab, rand(0.9, 1.3), { CFrame = slab.CFrame * CFrame.Angles(rand(-3, 3), rand(-3, 3), 0) + Vector3.new(rand(-40, 40), rand(30, 70), rand(-40, 40)) }, Enum.EasingStyle.Quad)
			tween(slab, 0.4, { Transparency = 1 }, nil, nil, 1)
			cleanup(slab, 1.45)
		end
		VFX.ImpactFrame(0.09)
		AB.boom(run, "Downslam", 1.3)
		AB.boom(run, "BigExplosion", 1)
		task.delay(0.35, VFX.Shake, 0.7, 0.6)
	end

	-- the street glowing orange in a web of cracks (the shockwave reaching
	-- you), cooling to dark red
	function AB.lavaWeb(center, radius, life)
		local function at(v)
			return groundPoint(v + UP * 3) + UP * 0.12
		end
		local function bar(a, b)
			local v = b - a
			if v.Magnitude < 0.5 then
				return
			end
			local p = newPart(Vector3.new(0.4, 0.14, v.Magnitude), CFrame.lookAt((a + b) / 2, b), Color3.fromRGB(255, 176, 40), Enum.Material.Neon)
			p.Name = "LavaWeb"
			tween(p, life * 0.4, { Color = Color3.fromRGB(200, 40, 10) }, nil, nil, life * 0.3)
			tween(p, life * 0.3, { Transparency = 1 }, nil, nil, life * 0.7)
			cleanup(p, life + 0.05)
		end
		local g = at(center)
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2 + rand(-0.25, 0.25)
			local dir = Vector3.new(math.cos(a), 0, math.sin(a))
			local prev = g
			for s = 1, 4 do
				local nxt = at(g + dir * radius * s / 4 + Vector3.new(rand(-3, 3), 0, rand(-3, 3)))
				task.delay(s * 0.05, bar, prev, nxt)
				prev = nxt
			end
		end
		for ring, r in { radius * 0.35, radius * 0.72 } do
			local pts = {}
			for i = 1, 12 do
				local a = i / 12 * math.pi * 2
				pts[i] = at(g + Vector3.new(math.cos(a), 0, math.sin(a)) * r + Vector3.new(rand(-2, 2), 0, rand(-2, 2)))
			end
			for i = 1, 12 do
				task.delay(0.1 + ring * 0.08, bar, pts[i], pts[i % 12 + 1])
			end
		end
		local l = Instance.new("PointLight")
		l.Color = Color3.fromRGB(255, 140, 40)
		l.Range = math.min(radius * 1.5, 60)
		l.Brightness = 3
		local holder = newPart(Vector3.one * 0.2, CFrame.new(g + UP * 3), Color3.new(), nil, nil, folder)
		holder.Transparency = 1
		l.Parent = holder
		tween(l, life * 0.6, { Brightness = 0 }, nil, nil, life * 0.4)
		cleanup(holder, life + 0.05)
	end

	-- THE FIGHT, as keys in the stage's space (x across the sky, y up, z
	-- toward you): time, All Might's spot, All For One's spot, the poses
	-- they're heading into, and whether All Might turns to face you. The
	-- flight between keys follows a smooth curve through them.
	function AB.keys()
		local V = Vector3.new
		local far = V(820, 300, -900)
		local keys = {}
		local function k(t, a, f, pa, pf, you)
			table.insert(keys, { t, a, f, pa, pf, you })
		end
		-- in on long arcs
		k(0, V(-330, -60, -170), V(230, 190, -140), "fly", "smug")
		k(1.4, V(-220, -10, -90), V(170, 110, -100), "fly", "smug")
		k(2.6, V(-150, 22, -50), V(128, 60, -70), "fly", "smug")
		k(3.3, V(-126, 30, -44), V(126, 56, -70), "hover", "cannon")
		-- the Air Cannon: a barrel roll out of it, and the Detroit Smash back
		k(3.8, V(-112, 46, -40), V(124, 54, -70), "roll", "cannon")
		k(4.3, V(-104, 40, -36), V(122, 52, -68), "jabR", "smug")
		-- flat out across the sky: fist to fist
		k(5.1, V(-50, 42, -40), V(60, 46, -48), "flyFist", "guard")
		k(5.8, V(-15, 44, -40), V(15, 44, -40), "jabR", "jabR")
		k(6.4, V(-40, 50, -36), V(40, 40, -46), "guard", "guard")
		-- 7 - 11.4: blow for blow, spiralling up
		local moves = { { "jabR", "guard" }, { "guard", "jabL" }, { "hookL", "guard" }, { "guard", "hookR" }, { "kickR", "guard" }, { "guard", "jabR" }, { "uppercut", "guard" }, { "jabL", "hookL" }, { "hookR", "guard" }, { "guard", "kickR" }, { "jabR", "jabL" } }
		for i, m in moves do
			local t = 6.9 + i * 0.4
			local a = i * 0.7
			local c = V(math.sin(i * 0.4) * 10, 50 + i * 3.6, -40)
			local off = V(math.cos(a) * 16, math.sin(a * 0.6) * 4, math.sin(a) * 16)
			k(t, c - off, c + off, m[1], m[2])
		end
		-- the uppercut sends him up; the loop chase round the sky
		k(11.9, V(-10, 92, -40), V(8, 104, -40), "uppercut", "knocked")
		k(12.5, V(-6, 110, -40), V(30, 160, -60), "flyFist", "tumble")
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			local c = V(0, 110, -80)
			local r = 120
			local afo = c + V(math.sin(a) * r, math.cos(a) * r * 0.5, -math.cos(a) * r * 0.5)
			local am = c + V(math.sin(a - 0.5) * r, math.cos(a - 0.5) * r * 0.5, -math.cos(a - 0.5) * r * 0.5)
			k(12.5 + i * 0.36, am, afo, "fly", i % 3 == 0 and "cannon" or "fly")
		end
		-- SPRING-LIKE LIMBS: the arm shoots out and takes hold of him, swells
		-- up - and hammers him down into the street
		k(15.6, V(-40, 76, -44), V(44, 70, -44), "held", "grab")
		k(16.3, V(-36, 74, -46), V(40, 72, -44), "held", "grab")
		k(16.8, V(-70, 20, -50), V(20, 60, -46), "tumble", "slam")
		k(17.3, V(-120, -146, -70), V(0, 40, -50), "splat", "laugh")
		k(18.1, V(-120, -146, -70), V(0, 40, -50), "splat", "laugh")
		-- up out of the crater and flat out along the street, the dust
		-- behind him - and off it into the sky: "I AM HERE!"
		k(18.4, V(-110, -146, -70), V(0, 40, -50), "sprint", "cannon")
		k(19.2, V(-30, -146, -80), V(0, 40, -50), "sprint", "cannon")
		k(19.6, V(-80, -30, -100), V(10, 46, -50), "hover", "smug")
		k(20.8, V(-160, 30, -100), V(30, 66, -44), "windup", "smug")
		k(21.5, V(-150, 34, -96), V(34, 62, -44), "jabR", "smug")
		k(22.6, V(-130, 34, -90), V(210, 0, -110), "hover", "tumble")
		k(23.8, V(-110, 44, -80), V(160, 20, -80), "hover", "smug")
		-- RIVET STAB: he weaves through it, smashing spikes as he comes, and
		-- a CAROLINA SMASH through the last of them
		k(24.6, V(-96, 44, -74), V(130, 30, -70), "fly", "rivet")
		k(25.1, V(-70, 64, -66), V(128, 30, -70), "roll", "rivet")
		k(25.6, V(-40, 30, -60), V(126, 30, -70), "hookL", "rivet")
		k(26.1, V(0, 56, -58), V(124, 30, -68), "carolina", "smug")
		k(26.6, V(40, 40, -58), V(122, 30, -66), "flyFist", "gate")
		-- the warp gate: out of it right at his back, and down he goes
		k(27.3, V(60, 42, -56), V(80, 64, -52), "hover", "bigWind")
		k(27.8, V(58, 40, -56), V(66, 56, -54), "guard", "bigPunch")
		k(28.9, V(50, -70, -60), V(64, 60, -54), "tumble", "laugh")
		-- up again in a corkscrew
		for i = 1, 6 do
			local a = i * 1.1
			k(28.9 + i * 0.32, V(30 + math.cos(a) * 20, -70 + i * 26, -60 + math.sin(a) * 20), V(40, 110, -56), "flyFist", "guard")
		end
		-- blow for blow again, high up and faster
		local moves2 = { { "jabL", "guard" }, { "guard", "hookR" }, { "kickR", "guard" }, { "hookR", "hookL" }, { "uppercut", "guard" }, { "jabR", "backhand" } }
		for i, m in moves2 do
			local t = 31.2 + i * 0.32
			local a = i * 0.9
			local c = V(34, 118 + i * 2, -52)
			local off = V(math.cos(a) * 16, 0, math.sin(a) * 16)
			k(t, c - off, c + off, m[1], m[2])
		end
		-- the backhand sends him spinning off; a barrage of Air Cannons he
		-- rolls through
		k(33.9, V(-60, 90, -80), V(44, 124, -52), "tumble", "cannon")
		k(34.3, V(-72, 102, -78), V(44, 124, -52), "roll", "cannon")
		k(34.7, V(-56, 84, -70), V(44, 124, -52), "roll", "cannon")
		k(35.1, V(-50, 80, -70), V(46, 124, -52), "hover", "smug")
		-- GO BEYOND - PLUS ULTRA: both charging, then at each other
		k(36, V(-44, 80, -66), V(44, 128, -52), "charge", "bigWind")
		k(40, V(-44, 82, -66), V(44, 128, -52), "charge", "bigWind")
		k(40.9, V(-13, 106, -58), V(14, 116, -54), "flyFist", "bigPunch")
		k(41.4, V(-10, 110, -58), V(11, 112, -56), "uss", "bigPunch")
		-- UNITED STATES OF SMASH: over the horizon
		k(42.2, V(-8, 110, -58), far * 0.3, "follow", "tumble")
		k(45.2, V(-8, 104, -58), far, "hover", "tumble")
		k(46.2, V(-8, 104, -58), far, "point", "tumble", true)
		k(49.8, V(-8, 104, -58), far, "point", "tumble", true)
		k(50.6, V(-8, 108, -58), far, "victory", "tumble", true)
		k(52.4, V(-8, 380, -170), far, "fly", "tumble")
		table.sort(keys, function(a, b)
			return a[1] < b[1]
		end)
		return keys
	end

	-- what happens when, beyond the flying
	function AB.events()
		local E = {}
		local function at(t, fn)
			table.insert(E, { t, fn })
		end
		local function world(run, who)
			return run.S * (who == "am" and run.amAt or run.afoAt)
		end
		local function mid(run)
			return (VFX.PUP.tip(run.am, "armR") + VFX.PUP.tip(run.afo, "armR")) / 2
		end
		local function dirTo(run, a, b)
			local v = world(run, b) - world(run, a)
			return v.Magnitude > 0.1 and v.Unit or UP
		end
		local function cannon(run, scale)
			local from = VFX.PUP.tip(run.afo, "armR")
			local to = world(run, "am")
			local dir = (to - from).Unit
			local dist = (to - from).Magnitude
			for i = 0, 5 do
				task.delay(i * 0.05, shockDisc, from, dir, 10 * scale, 40 * scale, 0.55, WIND, dist * 0.9)
			end
			streaks(from, dir, math.floor(18 * scale), 0.25, 34, dist * 0.9, WIND, 0.5)
			AB.boom(run, "AirBullet", 1.2)
			AB.boom(run, "Wind", 0.9)
		end
		at(0.2, function(run)
			AB.banner("ALL MIGHT  vs  ALL FOR ONE", "look up!")
			AB.boom(run, "MuscleRumble", 1)
		end)
		at(1.6, function(run)
			AB.say(run.afo, "You've grown weak, All Might.")
		end)
		at(3.4, function(run)
			cannon(run, 1)
			AB.say(run.afo, "AIR CANNON.")
		end)
		at(4.3, function(run)
			local fist = VFX.PUP.tip(run.am, "armR")
			local dir = dirTo(run, "am", "afo")
			AB.hit(run, fist + dir * 20, 2, AB.WHITE, dir)
			streaks(fist, dir, 18, 0.3, 30, 130, WIND, 0.5)
			AB.say(run.am, "DETROIT SMASH!")
		end)
		at(5.8, function(run)
			local m = mid(run)
			AB.hit(run, m, 3, AB.GOLD, nil)
			AB.flash(m, 110, AB.WHITE, 0.4)
			billboardRing(m, 20, 360, AB.WHITE, 12, 0.6)
			AB.clouds(m, 14, 180, 1.3)
			AB.sky(run, 0.3, nil, 0.45)
			AB.boom(run, "USSImpact", 1.1)
			task.delay(0.3, VFX.Shake, 0.5, 0.6)
		end)
		for i = 1, 11 do
			at(7.2 + i * 0.4, function(run)
				-- blow for blow: every one lands with a boom
				local m = (world(run, "am") + world(run, "afo")) / 2
				local d = dirTo(run, i % 2 == 1 and "am" or "afo", i % 2 == 1 and "afo" or "am")
				AB.hit(run, m, i % 4 == 0 and 1.6 or 1, i % 2 == 0 and AB.EVIL or AB.GOLD, d)
			end)
		end
		at(11.9, function(run)
			AB.hit(run, world(run, "afo"), 2, AB.GOLD, UP)
			AB.say(run.am, "UP YOU GO!")
		end)
		for i = 1, 3 do
			at(13 + i * 0.9, function(run)
				-- (Air Cannons thrown back over his shoulder in the chase)
				local from = world(run, "afo")
				local dir = dirTo(run, "afo", "am")
				shockDisc(from, dir, 6, 26, 0.4, WIND, 60)
				AB.boom(run, "AirBullet", 0.9)
			end)
		end
		at(15.5, function(run)
			-- SPRING-LIKE LIMBS: the tendrils take hold of him
			AB.say(run.afo, "Spring-like Limbs. Kinetic Boost. Enlarge.")
			AB.tendrils(run, VFX.PUP.tip(run.afo, "armR"), world(run, "am"), 7, 1.1)
			AB.arm(run, true)
			AB.sky(run, -0.1, Color3.fromRGB(236, 206, 216), 1.4)
		end)
		at(16.6, function(run)
			-- ...and hammers him down
			AB.hit(run, world(run, "am"), 2.6, AB.EVIL, -UP)
			AB.say(run.afo, "DOWN YOU GO.")
			AB.boom(run, "Wind", 1)
		end)
		at(17.25, function(run)
			AB.crater(run, world(run, "am") - UP * 6)
		end)
		at(17.6, function(run)
			AB.say(run.afo, "Stay down, symbol of peace.")
			AB.arm(run, false)
		end)
		at(18.3, function(run)
			-- up and flat out along the street
			local p = world(run, "am")
			AB.flash(p, 24, AB.GOLD, 0.25)
			billboardRing(p, 4, 60, AB.GOLD, 6, 0.3)
			run.sprint = true
			AB.boom(run, "Dash", 1)
		end)
		at(19.4, function(run)
			-- off the street into the sky
			run.sprint = false
			local p = world(run, "am") - UP * 6
			shockDisc(p, UP, 6, 70, 0.4, WIND)
			dustPuffs(p, 3, 8, Color3.fromRGB(196, 190, 182), 0.9, true)
			AB.boom(run, "Leap", 1.1)
		end)
		at(19.6, function(run)
			AB.say(run.am, "I AM HERE!", true)
			AB.flash(world(run, "am"), 70, AB.GOLD, 0.6)
			AB.sky(run, 0.14, Color3.fromRGB(255, 240, 200), 1)
			AB.boom(run, "IAmHere", 1.2)
		end)
		at(21.5, function(run)
			local fist = VFX.PUP.tip(run.am, "armR")
			local dir = dirTo(run, "am", "afo")
			for i = 0, 6 do
				task.delay(i * 0.05, shockDisc, fist, dir, 14, 50, 0.55, WIND, 180)
			end
			streaks(fist, dir, 30, 0.35, 44, 190, WIND, 0.6)
			AB.say(run.am, "TEXAS SMASH!")
			AB.boom(run, "DetroitImpact", 1.3)
			AB.boom(run, "Wind", 1)
		end)
		at(22.1, function(run)
			AB.hit(run, world(run, "afo"), 2.4, AB.GOLD, dirTo(run, "am", "afo"))
		end)
		at(24.4, function(run)
			-- RIVET STAB: black spikes out of his fingertips
			local from = VFX.PUP.tip(run.afo, "armR")
			local to = world(run, "am")
			run.spikes = {}
			for _ = 1, 7 do
				local aim = to + Vector3.new(rand(-24, 24), rand(-18, 18), rand(-20, 20)) - from
				local len = aim.Magnitude + 40
				local base = CFrame.lookAt(from, from + aim)
				local spike = newPart(Vector3.new(1.4, 1.4, 1), base, AB.DARK, Enum.Material.Metal)
				tween(spike, 0.25, { Size = Vector3.new(1.4, 1.4, len), CFrame = base * CFrame.new(0, 0, -len / 2) })
				cleanup(spike, 6)
				table.insert(run.spikes, spike)
			end
			AB.say(run.afo, "RIVET STAB.")
			AB.boom(run, "Rivet", 1.1)
		end)
		for n, t in { 25.6, 26.1 } do
			at(t, function(run)
				local fist = VFX.PUP.tip(run.am, n == 1 and "armL" or "armR")
				AB.hit(run, fist, n == 2 and 2.6 or 1.4, AB.GOLD, nil)
				if n == 2 then
					AB.say(run.am, "CAROLINA SMASH!")
					billboardRing(fist, 20, 260, AB.GOLD, 10, 0.5)
				end
				for i, spike in run.spikes or {} do
					if (i + n) % 2 == 0 and spike.Parent then
						for _ = 1, 4 do
							local shard = newPart(Vector3.new(1, 1, rand(4, 10)), spike.CFrame * CFrame.new(0, 0, rand(-spike.Size.Z / 2, spike.Size.Z / 2)), AB.DARK, Enum.Material.Metal)
							tween(shard, 0.9, { CFrame = shard.CFrame * CFrame.new(rand(-20, 20), rand(-40, -10), rand(-20, 20)) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), Transparency = 1 })
							cleanup(shard, 0.95)
						end
						spike:Destroy()
					end
				end
				AB.boom(run, "Shatter", 1)
			end)
		end
		at(26.5, function(run)
			AB.gate(run, world(run, "afo"), 0.6)
			run.afoAlpha = 0
		end)
		at(27.2, function(run)
			AB.gate(run, run.S * Vector3.new(80, 64, -52), 0.7)
			run.afoAlpha = 1
			AB.arm(run, true)
		end)
		at(27.8, function(run)
			AB.hit(run, world(run, "am"), 3, AB.EVIL, -UP)
			billboardRing(world(run, "am"), 20, 280, AB.EVIL, 9, 0.5)
			AB.clouds(world(run, "am"), 10, 150, 1.2)
			AB.boom(run, "BigExplosion", 1.2)
			task.delay(0.3, VFX.Shake, 0.5, 0.5)
		end)
		at(28.6, function(run)
			AB.arm(run, false)
		end)
		for i = 1, 6 do
			at(31.2 + i * 0.32, function(run)
				local m = (world(run, "am") + world(run, "afo")) / 2
				local d = dirTo(run, i % 2 == 1 and "am" or "afo", i % 2 == 1 and "afo" or "am")
				AB.hit(run, m, i == 6 and 2.2 or 1.3, i % 2 == 0 and AB.EVIL or AB.GOLD, d)
			end)
		end
		at(33.4, function(run)
			AB.say(run.afo, "Your era is over, All Might.")
		end)
		for i = 1, 3 do
			at(33.8 + i * 0.4, function(run)
				-- the barrage: one Air Cannon after another, and he rolls through them
				cannon(run, 0.7)
				if i == 1 then
					AB.say(run.afo, "AIR CANNON!")
				end
			end)
		end
		at(35.4, function(run)
			AB.arm(run, true)
			AB.sky(run, -0.12, Color3.fromRGB(230, 200, 214), 2)
		end)
		at(36.2, function(run)
			AB.say(run.am, "GO BEYOND!", true)
			run.glow = newPart(Vector3.one * 30, CFrame.new(world(run, "am")), AB.GOLD, Enum.Material.Neon, Enum.PartType.Ball)
			run.glow.Transparency = 0.7
			AB.boom(run, "USSCharge", 1.3)
		end)
		at(38.8, function(run)
			AB.say(run.am, "PLUS ULTRA!!!", true)
			AB.sky(run, 0.18, Color3.fromRGB(255, 236, 190), 1.2)
			AB.flash(world(run, "am"), 80, AB.GOLD, 0.5)
			AB.boom(run, "USSCharge", 1)
			task.delay(0.3, VFX.Shake, 0.3, 0.6)
		end)
		at(41.3, function(run)
			-- UNITED STATES OF SMASH: the frame goes white, then black and
			-- white, the clouds go out in a ring, and the shockwave reaches
			-- the street under you: it glows in a web of cracks
			local fist = VFX.PUP.tip(run.am, "armR")
			AB.say(run.am, "UNITED STATES OF SMASH!!!", true)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.3)
			task.delay(0.25, VFX.ImpactFrame, 0.12)
			AB.flash(fist, 200, AB.WHITE, 0.6)
			AB.flash(fist, 130, AB.GOLD, 0.8)
			for i = 0, 2 do
				task.delay(i * 0.12, billboardRing, fist, 30, 480 + i * 130, i == 1 and AB.GOLD or AB.WHITE, 12, 0.9)
			end
			local column = newPart(Vector3.new(720, 60, 60), CFrame.new(fist) * CFrame.Angles(0, 0, math.pi / 2), WIND, Enum.Material.ForceField, Enum.PartType.Cylinder)
			column.Transparency = 0.2
			tween(column, 1.5, { Size = Vector3.new(940, 220, 220), Transparency = 1 })
			cleanup(column, 1.55)
			AB.clouds(fist, 20, 340, 1.8)
			sparks(fist, 7, AB.WHITE, AB.GOLD, 44)
			AB.sky(run, 0.75, Color3.fromRGB(255, 246, 220), 1.4)
			AB.boom(run, "USSImpact", 1.4)
			AB.boom(run, "BigExplosion", 1.1)
			AB.boom(run, "DetroitImpact", 1.1)
			AB.boom(run, "Twister", 0.8)
			task.delay(0.3, VFX.Shake, 1, 1.3)
			task.delay(0.5, AB.lavaWeb, run.base, 44, 3.2)
			if run.glow then
				run.glow:Destroy()
				run.glow = nil
			end
		end)
		at(42.6, function(run)
			AB.arm(run, false)
		end)
		at(45, function(run)
			local p = world(run, "afo")
			AB.flash(p, 50, AB.WHITE, 0.5)
			billboardRing(p, 10, 90, AB.WHITE, 6, 0.5)
		end)
		at(46.4, function(run)
			AB.say(run.am, "NEXT... IT'S YOUR TURN.", true)
		end)
		table.sort(E, function(a, b)
			return a[1] < b[1]
		end)
		return E
	end

	-- the stage: over where you are, off the way you're looking
	function AB.anchor(run)
		local cam = workspace.CurrentCamera
		local focus = cam and cam.Focus.Position or Vector3.zero
		local look = cam and cam.CFrame.LookVector or Vector3.new(0, 0, -1)
		local flat = Vector3.new(look.X, 0, look.Z)
		flat = flat.Magnitude > 0.1 and flat.Unit or Vector3.new(0, 0, -1)
		local turn = CFrame.Angles(0, math.rad(run.side), 0)
		local away = turn:VectorToWorldSpace(flat)
		local center = focus + away * 360 + UP * 150
		run.base = focus
		run.S = CFrame.lookAt(center, center + away)
	end

	-- a point on the smooth curve through the keys (Catmull-Rom)
	function AB.curve(keys, i, u, slot)
		local p0 = keys[math.max(i - 1, 1)][slot]
		local p1 = keys[i][slot]
		local p2 = keys[math.min(i + 1, #keys)][slot]
		local p3 = keys[math.min(i + 2, #keys)][slot]
		local u2, u3 = u * u, u * u * u
		return 0.5 * ((2 * p1) + (-p0 + p2) * u + (2 * p0 - 5 * p1 + 4 * p2 - p3) * u2 + (-p0 + 3 * p1 - 3 * p2 + p3) * u3)
	end

	function AB.frame(run, dt)
		local PUP = VFX.PUP
		local t = os.clock() - run.t0
		local cam = workspace.CurrentCamera
		if cam and (cam.Focus.Position - run.base).Magnitude > 500 then
			AB.anchor(run) -- (they've gone somewhere else entirely: the fight goes with them)
		end
		local keys = run.keys
		while run.k < #keys - 1 and keys[run.k + 1][1] <= t do
			run.k += 1
		end
		local a, b = keys[run.k], keys[math.min(run.k + 1, #keys)]
		local u = b[1] > a[1] and math.clamp((t - a[1]) / (b[1] - a[1]), 0, 1) or 1
		local k = 1 - math.exp(-dt * 14)
		local amTo, afoTo = AB.curve(keys, run.k, u, 2), AB.curve(keys, run.k, u, 3)
		local lastAm, lastAfo = run.amAt, run.afoAt
		run.amAt = run.amAt:Lerp(amTo, k)
		run.afoAt = run.afoAt:Lerp(afoTo, k)
		-- (they move into the next key's pose over its last stretch)
		local key = (b[1] - t) < math.min(0.45, (b[1] - a[1]) * 0.6) and b or a
		local pk = 1 - math.exp(-dt * 16)
		-- (a new pose is overshot - past it, then back - the way a drawn
		-- swing is: anticipation's opposite, the follow-through)
		if key[4] ~= run.amKey then
			run.amKey, run.amFrom, run.amT0 = key[4], run.amPose, t
		end
		if key[5] ~= run.afoKey then
			run.afoKey, run.afoFrom, run.afoT0 = key[5], run.afoPose, t
		end
		local overAm = math.max(0, 1 - (t - (run.amT0 or t)) / 0.3)
		local overAfo = math.max(0, 1 - (t - (run.afoT0 or t)) / 0.3)
		run.amPose = PUP.blend(run.amPose, PUP.blend(run.amFrom or run.amPose, P[key[4]] or P.hover, 1 + 0.35 * overAm), pk)
		run.afoPose = PUP.blend(run.afoPose, PUP.blend(run.afoFrom or run.afoPose, P[key[5]] or P.smug, 1 + 0.35 * overAfo), pk)
		local amW, afoW = run.S * run.amAt, run.S * run.afoAt
		local toYou = run.S:VectorToWorldSpace(Vector3.new(0, 0, 1))
		-- facing: the other one while fighting, where he's going while flying
		local function facing(pos, other, vel, pose, you)
			local d
			if you then
				d = toYou
			elseif (pose == "fly" or pose == "flyFist" or pose == "sprint") and vel.Magnitude > 2 then
				d = vel
			else
				d = other - pos
			end
			d = Vector3.new(d.X, 0, d.Z)
			if d.Magnitude < 0.1 then
				d = toYou
			end
			return CFrame.lookAt(pos, pos + d.Unit)
		end
		local amVel = run.S:VectorToWorldSpace(run.amAt - lastAm)
		local afoVel = run.S:VectorToWorldSpace(run.afoAt - lastAfo)
		PUP.place(run.am, facing(amW, afoW, amVel, key[4], key[6]), run.amPose)
		PUP.place(run.afo, facing(afoW, amW, afoVel, key[5], false), run.afoPose)
		-- a fist too fast to draw leaves a smear on the frame
		run.fists = run.fists or {}
		for who, color in { [run.am] = AB.GOLD, [run.afo] = AB.EVIL } do
			local fists = run.fists[who] or {}
			run.fists[who] = fists
			for _, arm in { "armR", "armL" } do
				local tip = PUP.tip(who, arm)
				local prev = fists[arm]
				if prev and (tip - prev).Magnitude > 7 and (tip - prev).Magnitude < 60 then
					AB.smear(prev, tip, color, 3.2)
				end
				fists[arm] = tip
			end
		end
		-- flat out along the street: the dust and the streak behind him
		if run.sprint and t - (run.dust or 0) > 0.06 then
			run.dust = t
			dustPuffs(amW - UP * 6, 2.2, 2, Color3.fromRGB(196, 190, 182), 0.6, false)
			if amVel.Magnitude > 0.5 then
				local back = -amVel.Unit
				local line = newPart(Vector3.new(0.6, 0.6, 26), CFrame.lookAt(amW - UP * 3, amW - UP * 3 + back) * CFrame.new(0, 0, -13), AB.GOLD, Enum.Material.Neon)
				line.Transparency = 0.3
				tween(line, 0.3, { Transparency = 1, Size = Vector3.new(0.1, 0.1, 40) })
				cleanup(line, 0.32)
			end
		end
		run.alpha += math.clamp(run.afoAlpha - run.alpha, -dt * 5, dt * 5)
		PUP.fade(run.afo, run.alpha * run.out)
		PUP.fade(run.am, run.out)
		if run.glow then
			local pulse = 30 + math.sin(t * 14) * 4 + math.min(t - 36, 4) * 6
			run.glow.Size = Vector3.one * pulse
			run.glow.CFrame = CFrame.new(amW)
		end
		-- speed lines off whoever's really moving
		for who, v in { [run.am] = amVel, [run.afo] = afoVel } do
			if v.Magnitude / math.max(dt, 1 / 240) > 90 and rng:NextNumber() < 0.5 then
				local p = (who == run.am and amW or afoW) + Vector3.new(rand(-6, 6), rand(-6, 6), rand(-6, 6))
				local back = -v.Unit
				local line = newPart(Vector3.new(0.3, 0.3, 18), CFrame.lookAt(p, p + back) * CFrame.new(0, 0, -9), who == run.am and AB.GOLD or AB.EVIL, Enum.Material.Neon)
				tween(line, 0.25, { Transparency = 1, Size = Vector3.new(0.1, 0.1, 30) })
				cleanup(line, 0.3)
			end
		end
		-- the dark of his quirks, boiling off him
		if run.alpha > 0.5 and t - run.puff > 0.1 and t < 43 then
			run.puff = t
			local puff = newPart(Vector3.one * rand(3, 5.5), CFrame.new(afoW + Vector3.new(rand(-9, 9), rand(-12, 6), rand(-9, 9))), AB.DARK, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.45
			tween(puff, 0.6, { Size = puff.Size * 2, Transparency = 1, CFrame = puff.CFrame + UP * 8 })
			cleanup(puff, 0.65)
		end
		while run.e <= #run.events and run.events[run.e][1] <= t do
			task.spawn(run.events[run.e][2], run)
			run.e += 1
		end
		if t > 51.8 then
			run.out = math.max(0, run.out - dt * 1.4)
		end
		return t < (run.length or 53)
	end

	function AB.stop(run)
		if run.conn then
			run.conn:Disconnect()
		end
		run.am.model:Destroy()
		run.afo.model:Destroy()
		if run.glow then
			run.glow:Destroy()
		end
		if run.cc then
			run.cc:Destroy()
		end
		for _, spike in run.spikes or {} do
			spike:Destroy()
		end
		if AB.run == run then
			AB.run = nil
		end
	end

	function Effects.SkyBattle(_, data)
		if AB.run then
			AB.stop(AB.run)
		end
		local seed = tonumber(data.Seed) or 1
		local run = {
			t0 = os.clock(),
			side = (seed % 2 == 0 and 1 or -1) * (12 + seed % 18),
			keys = AB.keys(),
			events = AB.events(),
			k = 1,
			e = 1,
			alpha = 1,
			afoAlpha = 1,
			out = 1,
			puff = 0,
			length = tonumber(data.Length),
			am = AB.allMight(),
			afo = AB.allForOne(),
			amPose = P.fly,
			afoPose = P.smug,
		}
		AB.anchor(run)
		run.amAt, run.afoAt = run.keys[1][2], run.keys[1][3]
		AB.run = run
		run.conn = RunService.RenderStepped:Connect(function(dt)
			local ok, going = pcall(AB.frame, run, dt)
			if not ok then
				warn("sky battle:", going)
			end
			if not ok or not going then
				AB.stop(run)
			end
		end)
	end
end

---------------------------------------------------------------------------
-- IIDA'S PRANK (the ult's, in the air: LB + RB): "EVERYONE, PLEASE STAND
-- BACK!!" - a muffler out of his calf, lobbed tumbling at someone, sputtering
-- blue exhaust all the way. It's a nuke.
---------------------------------------------------------------------------
do
	local MF = { flying = setmetatable({}, { __mode = "k" }), CHROME = Color3.fromRGB(196, 202, 212), DARK = Color3.fromRGB(46, 48, 56) }
	POSES.MufflerPull = {
		Waist = { -34, -20, 0 }, Neck = { 20, 0, 0 },
		RightArm = { -8, 0, 12 }, RightElbow = 40, LeftArm = { 60, 0, 30 }, LeftElbow = 20,
		RightLeg = 60, RightKnee = 110, LeftLeg = -10, LeftKnee = 20,
	}

	-- the muffler: a chrome pipe with its dark exhaust tip (cf: its middle,
	-- the pipe along its look)
	function MF.build(cf)
		local pipe = newPart(Vector3.new(0.7, 0.7, 2.4), cf, MF.CHROME, Enum.Material.Metal)
		pipe.Name = "Muffler"
		local tip = newPart(Vector3.new(0.9, 0.9, 0.35), cf * CFrame.new(0, 0, -1.3), MF.DARK, Enum.Material.Metal)
		local hole = newPart(Vector3.new(0.5, 0.5, 0.05), cf * CFrame.new(0, 0, -1.49), Color3.new(0, 0, 0))
		local band = newPart(Vector3.new(0.78, 0.78, 0.22), cf * CFrame.new(0, 0, 0.6), MF.DARK, Enum.Material.Metal)
		local parts = { pipe, tip, hole, band }
		local offsets = { CFrame.new(), CFrame.new(0, 0, -1.3), CFrame.new(0, 0, -1.49), CFrame.new(0, 0, 0.6) }
		return function(to)
			for i, p in parts do
				p.CFrame = to * offsets[i]
			end
		end, parts
	end

	-- the pull (his own screen plays it as he presses; the server shows everyone)
	function Effects.MufflerNuke(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.MuteGait(char, 1)
		VFX.Pose(char, "MufflerPull", 0.3)
		exhaust(char, 0.35, 1.6)
		VFX.PlaySound("ReciproRev", root.Position, 1)
		-- out of his calf, into his hand
		local leg = limb(char, "RightLowerLeg", "Right Leg")
		local hand = limb(char, "RightHand", "Right Arm")
		if leg and hand then
			local place, parts = MF.build(leg.CFrame * CFrame.new(0, 0, leg.Size.Z / 2 + 0.5))
			local t0 = os.clock()
			local conn
			conn = RunService.RenderStepped:Connect(function()
				local t = os.clock() - t0
				if t > 0.34 or not char.Parent then
					conn:Disconnect()
					for _, p in parts do
						p:Destroy()
					end
					return
				end
				local k = math.clamp(t / 0.25, 0, 1)
				local from = leg.CFrame * CFrame.new(0, 0, leg.Size.Z / 2 + 0.5)
				local to = hand.CFrame * CFrame.new(0, -hand.Size.Y / 2, 0) * CFrame.Angles(math.rad(90), 0, 0)
				place(from:Lerp(to, k))
			end)
		end
		task.delay(0.3, function()
			if char.Parent then
				VFX.Pose(char, "Throw", 0.5)
			end
		end)
		-- the class rep's announcement
		local head = char:FindFirstChild("Head")
		if head then
			local bb = Instance.new("BillboardGui")
			bb.Size = UDim2.fromScale(9, 2.2)
			bb.StudsOffset = Vector3.new(0, 3.2, 0)
			bb.LightInfluence = 0
			bb.Adornee = head
			local label = Instance.new("TextLabel")
			label.Size = UDim2.fromScale(1, 1)
			label.BackgroundColor3 = Color3.new(1, 1, 1)
			label.BackgroundTransparency = 0.05
			label.TextScaled = true
			label.Font = Enum.Font.GothamBlack
			label.TextColor3 = Color3.fromRGB(30, 60, 140)
			label.Text = "EVERYONE, PLEASE STAND BACK!!"
			label.Parent = bb
			local corner = Instance.new("UICorner")
			corner.CornerRadius = UDim.new(0.3, 0)
			corner.Parent = label
			bb.Parent = VFX.Folder
			task.delay(2.2, function()
				bb:Destroy()
			end)
		end
		if isLocal then
			VFX.Hooks.Callout("MUFFLER... NUKE?!", Color3.fromRGB(110, 180, 255))
		end
	end

	-- lobbed: tumbling end over end, sputtering, homing in on them
	function Effects.MufflerThrow(char, data)
		local from = typeof(data.From) == "Vector3" and data.From
		if not from then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local spot = typeof(data.To) == "Vector3" and data.To or from
		local speed = math.max(tonumber(data.Speed) or 150, 1)
		local place, parts = MF.build(CFrame.new(from))
		local st = { done = false }
		MF.flying[char] = st
		VFX.PlaySound("BombThrow", from, 1)
		local stopTrail = addTrail(parts[1], EXHAUST, 0.35, 0.8)
		local p, spin, t0, last = from, 0, os.clock(), os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local now = os.clock()
			local dt = now - last
			last = now
			local goal = troot and troot.Parent and troot.CFrame.Position or spot
			local to = goal - p
			if st.done or now - t0 > 3.2 or to.Magnitude < 1 then
				conn:Disconnect()
				stopTrail(0)
				for _, part in parts do
					part:Destroy()
				end
				return
			end
			local step = math.min(speed * dt, to.Magnitude)
			p += to.Unit * step
			spin += dt * 14
			local cf = CFrame.lookAt(p, p + to.Unit) * CFrame.Angles(spin, 0, spin * 0.4)
			place(cf)
			-- (it sputters blue exhaust as it tumbles)
			if rng:NextNumber() < 0.6 then
				local puff = newPart(Vector3.one * rand(0.4, 0.9), cf * CFrame.new(0, 0, -1.5), rng:NextNumber() < 0.4 and EXHAUST_CORE or EXHAUST, Enum.Material.Neon, Enum.PartType.Ball)
				tween(puff, 0.25, { Size = Vector3.one * 0.1, Transparency = 0.7 })
				cleanup(puff, 0.27)
			end
		end)
	end

	-- ...it hits. It's a nuke.
	function Effects.MufflerBoom(char, data)
		local st = MF.flying[char]
		if st then
			st.done = true
			MF.flying[char] = nil
		end
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if pos and VFX.NukeDetonate then
			VFX.NukeDetonate(pos, {}, { Radius = tonumber(data.Radius) or 200, WaveSpeed = tonumber(data.WaveSpeed) or 480 })
		end
	end
end

---------------------------------------------------------------------------
-- DEKU DROPS IN (Config.DekuDrop). Every few minutes Deku - Full Cowl, the
-- Gamma costume - comes down out of the sky into the middle of the city,
-- flipping as he falls, and lands the superhero way: one knee, one fist
-- into the street, the street cratering round him. He stays down a beat,
-- gets up, looks round, crouches as the green lightning builds, and blasts
-- back up into the sky. The server makes the craters and blows anyone near
-- off their feet; this plays him on every screen.
---------------------------------------------------------------------------
do
	local DD = {
		SUIT = Color3.fromRGB(38, 96, 72),
		SUIT_DARK = Color3.fromRGB(26, 66, 50),
		LINE = Color3.fromRGB(20, 26, 26),
		SKIN = Color3.fromRGB(242, 204, 172),
		HAIR = Color3.fromRGB(28, 54, 40),
		HAIR_LIGHT = Color3.fromRGB(46, 88, 60),
		RED = Color3.fromRGB(204, 36, 40),
		WHITE = Color3.fromRGB(236, 236, 232),
		STEEL = Color3.fromRGB(96, 100, 110),
		BRACE = Color3.fromRGB(58, 60, 68),
		YELLOW = Color3.fromRGB(236, 196, 48),
		EYE = Color3.fromRGB(52, 150, 92),
		DUST = Color3.fromRGB(206, 198, 184),
		FLASH = Color3.fromRGB(246, 255, 252),
		SCALE = 1.3,
	}
	VFX.DD = DD
	local function PUP_blend(a, b, k)
		return VFX.PUP.blend(a, b, k)
	end
	local function PUP_fade(pp, alpha)
		VFX.PUP.fade(pp, alpha)
	end

	-- the poses (the puppet's: per limb { pitch, yaw, roll, bend }; head
	-- { pitch, yaw }; lean + back)
	DD.P = {
		stand = { armR = { 6, 0, 8, 14 }, armL = { 6, 0, 8, 14 }, legR = { 2, 0, 4, 4 }, legL = { -2, 0, 4, 4 }, head = { 0, 0 } },
		tuck = { armR = { 60, 0, 20, 120 }, armL = { 60, 0, 20, 120 }, legR = { 110, 0, 8, 130 }, legL = { 110, 0, 8, 130 }, head = { -20, 0 }, lean = -20 },
		brace = { armR = { 40, 0, 70, 20 }, armL = { 40, 0, 70, 20 }, legR = { 34, 0, 8, 44 }, legL = { 10, 0, 8, 24 }, head = { -14, 0 }, lean = -8 },
		-- the superhero landing: right foot planted, left knee down, the right
		-- fist driven into the street, the left arm flung back
		land = { armR = { 40, 6, 8, 6 }, armL = { -52, 0, 50, 36 }, legR = { 117, 0, 8, 85 }, legL = { 12, 0, 8, 70 }, head = { 22, 0 }, lean = -32 },
		getup = { armR = { 30, 0, 20, 40 }, armL = { -10, 0, 20, 30 }, legR = { 56, 0, 8, 70 }, legL = { 12, 0, 8, 40 }, head = { 8, 0 }, lean = -18 },
		fist = { armR = { 40, 10, 10, 130 }, armL = { 8, 0, 10, 20 }, legR = { 4, 0, 6, 6 }, legL = { -4, 0, 6, 6 }, head = { 6, 0 } },
		crouch = { armR = { -44, 0, 30, 24 }, armL = { -44, 0, 30, 24 }, legR = { 114, 0, 10, 110 }, legL = { 114, 0, 10, 110 }, head = { 14, 0 }, lean = -34 },
		launch = { armR = { -12, 0, 10, 10 }, armL = { -12, 0, 10, 10 }, legR = { -6, 0, 4, 4 }, legL = { 52, 0, 4, 100 }, head = { 26, 0 }, lean = 8 },
	}
	-- how high the middle of his torso is over the street in each (x scale):
	-- worked out so his feet (and his knee, landing) sit on the street
	DD.H = { stand = 3.05, land = 1.92, getup = 2.6, crouch = 1.91, fist = 3.05 }

	-- Deku in the Gamma costume: the dark green suit with its black lines,
	-- the hood down with its two long ears, the utility belt and pouches,
	-- the respirator on his hip, steel arm braces and white support gloves,
	-- white knee pads with yellow bolts, the red boots on iron soles - and
	-- the big mop of dark green curls, the freckles, the green eyes
	function DD.deku()
		local PUP = VFX.PUP
		local pp = PUP.new("Deku", DD.SCALE, Color3.fromRGB(12, 34, 22))
		pp.jointed = true
		local function P(key, size, at, color, material, shape)
			return PUP.part(pp, key, size, at, color, material, shape)
		end
		-- the torso
		P("torso", Vector3.new(2.1, 2, 1.05), CFrame.new(), DD.SUIT)
		for side = -1, 1, 2 do
			P("torso", Vector3.new(0.05, 2.02, 0.24), CFrame.new(side * 1.06, 0, 0), DD.LINE)
			P("torso", Vector3.new(0.12, 1.25, 0.05), CFrame.new(side * 0.42, 0.24, -0.53) * CFrame.Angles(0, 0, math.rad(side * 18)), DD.LINE)
			P("torso", Vector3.new(0.5, 0.32, 0.24), CFrame.new(side * 0.56, -0.7, -0.6), Color3.fromRGB(196, 168, 110))
		end
		P("torso", Vector3.new(2.14, 0.28, 1.1), CFrame.new(0, -0.84, 0), DD.STEEL, Enum.Material.Metal)
		P("torso", Vector3.new(0.34, 0.24, 0.06), CFrame.new(0, -0.84, -0.57), DD.YELLOW, Enum.Material.Metal)
		-- the respirator on his hip
		P("torso", Vector3.new(0.5, 0.36, 0.28), CFrame.new(0.74, -1.04, -0.42), DD.STEEL, Enum.Material.Metal)
		P("torso", Vector3.new(0.14, 0.22, 0.22), CFrame.new(0.74, -1.04, -0.6) * CFrame.Angles(0, math.rad(90), 0), DD.SUIT_DARK, nil, Enum.PartType.Cylinder)
		-- the collar, and the hood down his back with its two long ears
		P("torso", Vector3.new(1, 0.22, 0.95), CFrame.new(0, 1.02, -0.02), DD.SUIT_DARK)
		P("torso", Vector3.new(1.3, 0.52, 0.5), CFrame.new(0, 0.92, 0.52), DD.SUIT_DARK)
		for side = -1, 1, 2 do
			P("torso", Vector3.new(0.22, 1.1, 0.14), CFrame.new(side * 0.36, 0.9, 0.88) * CFrame.Angles(math.rad(-62), 0, math.rad(side * 14)), DD.SUIT_DARK)
		end
		-- the head
		P("head", Vector3.new(1.05, 1.1, 1.02), CFrame.new(0, 0.6, 0), DD.SKIN)
		for side = -1, 1, 2 do
			P("head", Vector3.new(0.28, 0.25, 0.04), CFrame.new(side * 0.24, 0.66, -0.52), DD.WHITE)
			P("head", Vector3.new(0.17, 0.21, 0.05), CFrame.new(side * 0.22, 0.65, -0.53), DD.EYE)
			P("head", Vector3.new(0.08, 0.1, 0.06), CFrame.new(side * 0.21, 0.66, -0.54), Color3.fromRGB(8, 20, 12))
			P("head", Vector3.new(0.3, 0.06, 0.04), CFrame.new(side * 0.24, 0.85, -0.52) * CFrame.Angles(0, 0, math.rad(side * -14)), DD.HAIR)
			for f = 0, 2 do
				P("head", Vector3.new(0.05, 0.05, 0.03), CFrame.new(side * (0.2 + f * 0.07), 0.47 + (f % 2) * 0.05, -0.515), Color3.fromRGB(170, 104, 82))
			end
		end
		P("head", Vector3.new(0.34, 0.06, 0.04), CFrame.new(0, 0.33, -0.52), Color3.fromRGB(120, 40, 40))
		-- the hair: a big dark-green mop of curls, and tufts over his forehead
		P("head", Vector3.new(1.18, 0.5, 1.16), CFrame.new(0, 1.12, 0.04), DD.HAIR)
		for i, c in {
			{ 0, 1.42, 0, 0.62 }, { 0.38, 1.3, -0.22, 0.52 }, { -0.38, 1.3, -0.22, 0.52 }, { 0.42, 1.28, 0.28, 0.54 }, { -0.42, 1.28, 0.28, 0.54 },
			{ 0, 1.3, 0.48, 0.56 }, { 0.58, 1.02, 0.12, 0.44 }, { -0.58, 1.02, 0.12, 0.44 }, { 0.2, 1.47, 0.26, 0.46 }, { -0.22, 1.45, -0.3, 0.44 },
			{ 0.3, 1.02, 0.5, 0.42 }, { -0.3, 1.02, 0.5, 0.42 }, { 0, 1.0, 0.58, 0.44 }, { 0.5, 1.2, -0.4, 0.34 }, { -0.5, 1.2, -0.4, 0.34 },
		} do
			P("head", Vector3.one * c[4], CFrame.new(c[1], c[2], c[3]), i % 3 == 0 and DD.HAIR_LIGHT or DD.HAIR, nil, Enum.PartType.Ball)
		end
		for k = -2, 2 do
			P("head", Vector3.new(0.22, 0.36, 0.14), CFrame.new(k * 0.2, 1.0, -0.52) * CFrame.Angles(math.rad(-20), 0, math.rad(k * 12)), k % 2 == 0 and DD.HAIR_LIGHT or DD.HAIR)
		end
		-- the arms: the suit with a black line down the outside, the steel
		-- braces with their red straps, white gloves
		for _, k in { { "armR", "foreR", 1 }, { "armL", "foreL", -1 } } do
			local side = k[3]
			P(k[1], Vector3.new(0.95, 1.05, 0.95), CFrame.new(0, -0.45, 0), DD.SUIT)
			P(k[1], Vector3.new(0.05, 1.05, 0.22), CFrame.new(side * 0.48, -0.45, 0), DD.LINE)
			P(k[1], Vector3.new(1, 0.32, 1), CFrame.new(0, 0.02, 0), DD.SUIT_DARK)
			P(k[2], Vector3.new(0.98, 0.72, 0.98), CFrame.new(0, -0.32, 0), DD.BRACE, Enum.Material.Metal)
			P(k[2], Vector3.new(1.02, 0.12, 1.02), CFrame.new(0, -0.1, 0), DD.RED)
			P(k[2], Vector3.new(1.02, 0.12, 1.02), CFrame.new(0, -0.55, 0), DD.RED)
			P(k[2], Vector3.new(0.86, 0.44, 0.86), CFrame.new(0, -0.9, 0), DD.WHITE)
		end
		-- the legs: the suit and its line, knee pads, red boots on iron soles
		for _, k in { { "legR", "shinR", 1 }, { "legL", "shinL", -1 } } do
			local side = k[3]
			P(k[1], Vector3.new(0.98, 1.05, 0.98), CFrame.new(0, -0.5, 0), DD.SUIT)
			P(k[1], Vector3.new(0.05, 1.05, 0.22), CFrame.new(side * 0.5, -0.5, 0), DD.LINE)
			P(k[2], Vector3.new(0.96, 0.55, 0.96), CFrame.new(0, -0.28, 0), DD.SUIT)
			P(k[2], Vector3.new(0.8, 0.44, 0.22), CFrame.new(0, -0.05, -0.5), DD.WHITE)
			for b = -1, 1, 2 do
				P(k[2], Vector3.new(0.1, 0.1, 0.06), CFrame.new(b * 0.24, -0.05, -0.62), DD.YELLOW, Enum.Material.Metal)
			end
			P(k[2], Vector3.new(1.02, 0.5, 1.12), CFrame.new(0, -0.72, -0.06), DD.RED)
			P(k[2], Vector3.new(1.06, 0.14, 1.2), CFrame.new(0, -0.98, -0.07), DD.STEEL, Enum.Material.Metal)
			P(k[2], Vector3.new(1.04, 0.1, 0.3), CFrame.new(0, -0.86, -0.56), DD.WHITE)
		end
		-- Full Cowl: a green glow round him, and a light on him
		local glow = Instance.new("Highlight")
		glow.FillColor = COWL_GREEN
		glow.FillTransparency = 0.85
		glow.OutlineColor = COWL_GREEN
		glow.OutlineTransparency = 0.4
		glow.DepthMode = Enum.HighlightDepthMode.Occluded
		glow.Adornee = pp.model
		glow.Parent = pp.model
		pp.glow = glow
		local light = Instance.new("PointLight")
		light.Color = COWL_GREEN
		light.Range = 16
		light.Brightness = 1.5
		light.Parent = pp.parts[1].part
		pp.light = light
		return pp
	end

	local function smooth(x)
		x = math.clamp(x, 0, 1)
		return x * x * x * (x * (x * 6 - 15) + 10)
	end
	-- green lightning crawling over him (more of it the more `k`)
	function DD.crackle(pp, k)
		if rng:NextNumber() > 0.35 + 0.6 * k then
			return
		end
		local p = pp.parts[rng:NextInteger(1, #pp.parts)].part
		local a = p.Position + rng:NextUnitVector() * 0.5 * DD.SCALE
		local DK = VFX.DK
		if DK and DK.arc then
			DK.arc(a, a + rng:NextUnitVector() * rand(1, 2.4) * DD.SCALE, rng:NextNumber() < 0.7 and COWL_GREEN or COWL_CORE, 0.07 + 0.05 * k)
		end
	end
	-- the street round him: chunks thrown up and out, dust, the crater
	function DD.crater(ground, size, up)
		rocks(ground, 2.2 * size, math.floor(26 * size))
		dustPuffs(ground, 3.4 * size, math.floor(14 * size), DD.DUST, 2.2, true)
		shockDisc(ground + UP * 0.3, UP, 4, 90 * size, 0.6, WIND, 10)
		billboardRing(ground + UP * 2, 6, 120 * size, DD.FLASH, 10, 0.45)
		groundMark(ground, 15 * size, Color3.fromRGB(46, 42, 38), 22)
		for _ = 1, math.floor(10 * size) do
			local a = rng:NextNumber(0, math.pi * 2)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local chunk = newPart(Vector3.new(rand(1.2, 3), rand(0.6, 1.4), rand(1.2, 3)) * size, CFrame.new(ground + out * rand(3, 8)) * CFrame.Angles(rand(0, 3), rand(0, 3), rand(0, 3)), Color3.fromRGB(128, 126, 122), Enum.Material.Concrete)
			local peak = ground + out * rand(8, 22) * size + UP * rand(8, 26) * (up or 1)
			local land = groundPoint(ground + out * rand(14, 34) * size + UP * 6)
			tween(chunk, 0.45, { CFrame = CFrame.new(peak) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(chunk, 0.5, { CFrame = CFrame.new(land) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.45)
			tween(chunk, 1, { Transparency = 1 }, nil, nil, 3)
			cleanup(chunk, 4.1)
		end
		local DK = VFX.DK
		if DK and DK.zig then
			for i = 1, 8 do
				local a = i / 8 * math.pi * 2 + rand(0, 0.4)
				DK.zig(ground + UP, ground + UP * 0.5 + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(12, 22) * size, i % 2 == 0 and COWL_GREEN or COWL_CORE, 0.3, 0.45, 1.2)
			end
		end
		local flash = newPart(Vector3.one * 6, CFrame.new(ground + UP * 2), DD.FLASH, Enum.Material.Neon, Enum.PartType.Ball)
		tween(flash, 0.3, { Size = Vector3.one * 44 * size, Transparency = 1 })
		cleanup(flash, 0.32)
		VFX.ShakeAt(ground, 5 * size, 320, 0.8)
		if nearCamera(ground, 160) then
			VFX.ImpactFrame(0.1)
		end
	end

	function DD.stop(run)
		if run.conn then
			run.conn:Disconnect()
		end
		if run.pp and run.pp.model.Parent then
			run.pp.model:Destroy()
		end
		if DD.run == run then
			DD.run = nil
		end
	end

	-- one frame of it, `t` seconds in
	function DD.step(run, t)
		local pp, s, ground, facing = run.pp, DD.SCALE, run.ground, run.facing
		local P, H = DD.P, DD.H
		local impact, jump = run.impact, run.jump
		local look = CFrame.lookAt(Vector3.zero, facing)
		local pos, pose, spin = nil, nil, 0
		local cowl = 0.3
		-- (the phases, latest first: whatever the timings, the launch and
		-- the crouch before it come when they're due)
		if t < impact then
			-- the fall: a long curve down, two front flips, out of them into
			-- the landing
			local u = t / impact
			local e = u ^ 1.7
			local land = ground + UP * H.land * s
			local ctrl = land + UP * 220 - facing * 30
			pos = run.from:Lerp(ctrl, e):Lerp(ctrl:Lerp(land, e), e)
			spin = -math.pi * 4 * smooth((u - 0.05) / 0.72)
			if u < 0.72 then
				pose = P.tuck
			elseif u < 0.9 then
				pose = PUP_blend(P.tuck, P.brace, smooth((u - 0.72) / 0.18))
			else
				pose = PUP_blend(P.brace, P.land, smooth((u - 0.9) / 0.1))
			end
			cowl = 0.5
		elseif t >= jump then
			-- the launch: gone up into the sky
			local k = math.clamp((t - jump) / 1.8, 0, 1)
			local rise = 760 * (1 - (1 - k) ^ 3)
			pose = PUP_blend(P.crouch, P.launch, smooth(k / 0.06))
			pos = ground + UP * (H.crouch * s + rise) + facing * 24 * k
			pose.twist = 200 * k * k
			cowl = 1
			PUP_fade(pp, 1 - smooth((k - 0.65) / 0.35))
		elseif t >= jump - 1.4 then
			-- the crouch, the lightning building, the street cracking
			local k = (t - (jump - 1.4)) / 1.4
			local c = smooth(k / 0.4)
			pose = PUP_blend(P.stand, P.crouch, c)
			local shake = k > 0.4 and 0.04 * k or 0
			pos = ground + UP * (H.stand + (H.crouch - H.stand) * c) * s + Vector3.new(rand(-shake, shake), rand(-shake, shake), rand(-shake, shake)) * s
			cowl = 0.4 + 0.6 * k
		elseif t < impact + 1 then
			-- down: the landing, a squash as it hits, held
			local k = (t - impact) / 0.35
			local dip = k < 1 and math.sin(k * math.pi) * 0.35 or 0
			pos = ground + UP * (H.land - dip) * s
			pose = P.land
			cowl = 0.6
		elseif t < impact + 2.2 then
			-- up: off the knee, straightening
			local k = (t - impact - 1) / 1.2
			local h
			if k < 0.5 then
				pose = PUP_blend(P.land, P.getup, smooth(k / 0.5))
				h = H.land + (H.getup - H.land) * smooth(k / 0.5)
			else
				pose = PUP_blend(P.getup, P.stand, smooth((k - 0.5) / 0.5))
				h = H.getup + (H.stand - H.getup) * smooth((k - 0.5) / 0.5)
			end
			pos = ground + UP * h * s
		else
			-- a look round (and a fist clenched at whatever he sees)
			local k = t - impact - 2.2
			local span = math.max(jump - 1.4 - impact - 2.2, 0.1)
			local yaw = 55 * math.sin(k / span * math.pi * 2) * (1 - smooth((k / span - 0.8) / 0.2))
			pose = table.clone(P.stand)
			if k / span > 0.55 then
				pose = PUP_blend(P.stand, P.fist, math.sin(math.clamp((k / span - 0.55) / 0.45, 0, 1) * math.pi))
			end
			pose.head = { 4, yaw }
			pose.twist = yaw * 0.18
			pos = ground + UP * H.stand * s
		end
		local cf = CFrame.new(pos) * look * CFrame.Angles(spin, 0, 0)
		VFX.PUP.place(pp, cf, pose)
		pp.glow.FillTransparency = 0.9 - 0.35 * cowl
		pp.light.Brightness = 1 + 3 * cowl
		DD.crackle(pp, cowl)
		run.last = pos
	end

	function Effects.DekuDrop(_, data)
		local ground = typeof(data.Pos) == "Vector3" and data.Pos
		if not ground then
			return
		end
		if DD.run then
			DD.stop(DD.run)
		end
		local seeded = Random.new(tonumber(data.Seed) or 1)
		local yaw = seeded:NextNumber(0, math.pi * 2)
		local facing = Vector3.new(math.cos(yaw), 0, math.sin(yaw))
		-- (he lands facing you, if you're anywhere near)
		local cam = workspace.CurrentCamera
		if cam then
			local off = cam.CFrame.Position - ground
			local flat = Vector3.new(off.X, 0, off.Z)
			if flat.Magnitude > 4 and flat.Magnitude < 400 then
				facing = flat.Unit
			end
		end
		local run = {
			pp = DD.deku(), t0 = os.clock(), ground = ground, facing = facing,
			impact = tonumber(data.Impact) or 2.4, jump = tonumber(data.Jump) or 7.4, length = tonumber(data.Length) or 11,
			from = ground - facing * 110 + UP * 420, done = {},
		}
		DD.run = run
		local AB = VFX.AB
		if AB and cam and (cam.CFrame.Position - ground).Magnitude > 140 then
			AB.banner("DEKU!!", "Coming down in the middle of the city")
		end
		if AB then
			AB.trail(run.pp, COWL_GREEN, COWL_CORE, 1.6)
		end
		VFX.PlaySound("DekuFall", ground + UP * 80, 1.2)
		landingMarker(ground, run.impact)
		local function once(key, at, fn)
			if not run.done[key] and os.clock() - run.t0 >= at then
				run.done[key] = true
				fn()
			end
		end
		run.conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - run.t0
			if t >= run.length or not run.pp.model.Parent then
				DD.stop(run)
				return
			end
			DD.step(run, t)
			-- the moments
			once("impact", run.impact, function()
				VFX.PlaySound("DekuImpact", ground, 1.5)
				DD.crater(ground, 1, 1)
			end)
			once("rise", run.impact + 1.2, function()
				dustPuffs(ground, 1.2, 5, DD.DUST, 1, true)
				VFX.PUP.say(run.pp, "Sorry! Coming through!", COWL_GREEN, Color3.fromRGB(10, 40, 24), 1.8, 240, 300)
			end)
			once("charge", run.jump - 1.4, function()
				VFX.PlaySound("CowlCharge", ground, 1.3)
				VFX.PUP.say(run.pp, "ONE FOR ALL: FULL COWL!", COWL_GREEN, Color3.fromRGB(10, 40, 24), 1.5, 280, 300)
				groundMark(ground, 7, Color3.fromRGB(40, 36, 32), 12)
			end)
			once("crack", run.jump - 0.6, function()
				groundMark(ground, 11, Color3.fromRGB(40, 36, 32), 12)
				rocks(ground, 0.8, 8)
			end)
			once("launch", run.jump, function()
				VFX.PlaySound("DekuLaunch", ground, 1.6)
				DD.crater(ground, 0.85, 1.6)
				local DK = VFX.DK
				if DK and DK.zig then
					for kk = 1, 2 do
						DK.zig(ground, ground + UP * 140, kk == 1 and COWL_GREEN or COWL_CORE, kk == 1 and 0.9 or 0.4, 0.55, 2.2)
					end
				end
				streaks(ground + UP * 4, UP, 24, 0.35, 30, 120, WIND, 0.6)
				if nearCamera(ground, 120) then
					VFX.Hooks.SpeedLines(0.7)
				end
				VFX.PUP.say(run.pp, "PLUS ULTRA!!", COWL_GREEN, Color3.fromRGB(10, 40, 24), 1.2, 300, 500)
			end)
		end)
	end
end

---------------------------------------------------------------------------
-- BLAZE: the fire model for Endeavor's Hellflame and Dabi's Blueflame, drawn
-- the way the anime draws it (Bones' fire in MHA): flat, cel-shaded tones
-- with hard edges - a deep shade outlining an orange body, a yellow tongue
-- inside that and a pale core at the root (Dabi's: navy, blue, cyan, white)
-- - sharp licking tips, blobs of flame tearing off the top and floating
-- away, dark cinders drifting round it, and the shapes changing on the
-- beat of hand-drawn frames (twelve a second) instead of melting smoothly.
--   TONGUES - each a nest of Beams, belly to point: the shade, the body,
--     the inner tongue and the core, each shorter than the one round it,
--     with a faint glow behind (the compositing glow the anime puts on).
--     A belly that bulges to one side, a waist, a whip of a tip that curls,
--     and a fork licking off the shoulder to a second point; the tongues
--     behind drawn a shade darker, so a fire reads as licks in front of
--     licks, not one flat cut-out.
--   FRAGMENTS - little flames that break off the tips and rise away, and
--     the lumps of smoke they leave when they burn out.
--   VOLUME - a soft glow of particles between the tongues, embers and
--     cinders, and the red haze the anime lays behind a big fire.
--   LIGHT - a flickering light.
-- One RenderStepped loop animates every live flame (skipped far away).
---------------------------------------------------------------------------
do
	local BLAZE = { live = {} }
	VFX.BLAZE = BLAZE
	local Z = {} -- (its helpers: one local, not twenty - the chunk has a register budget)
	Z.TEX = "rbxasset://textures/particles/fire_main.dds"
	Z.SMOKE_TEX = "rbxasset://textures/particles/smoke_main.dds"
	Z.SPARK_TEX = "rbxasset://textures/particles/sparkles_main.dds"
	Z.C3 = Color3.fromRGB
	local CK, NK, NS = ColorSequenceKeypoint.new, NumberSequenceKeypoint.new, NumberSequence.new
	Z.noise = math.noise

	-- heart (the pale core) > hot (the inner tongue) > body > edge (the
	-- shade round it) > tip, then soot and the cinders (fleck)
	BLAZE.PAL = {
		hell = {
			heart = Z.C3(255, 248, 206), hot = Z.C3(255, 214, 64), body = Z.C3(255, 140, 24), edge = Z.C3(226, 62, 14), tip = Z.C3(168, 28, 10),
			soot = Z.C3(46, 36, 34), fleck = Z.C3(34, 20, 18), light = Z.C3(255, 150, 60), ember = Z.C3(255, 214, 110), ember2 = Z.C3(255, 96, 20),
		},
		blue = {
			heart = Z.C3(232, 252, 255), hot = Z.C3(118, 232, 255), body = Z.C3(34, 138, 255), edge = Z.C3(26, 62, 214), tip = Z.C3(34, 20, 140),
			soot = Z.C3(18, 20, 34), fleck = Z.C3(14, 14, 30), light = Z.C3(90, 170, 255), ember = Z.C3(180, 240, 255), ember2 = Z.C3(60, 110, 255),
		},
		-- Prominence Burn: everything pushed hotter, towards white
		white = {
			heart = Z.C3(255, 255, 255), hot = Z.C3(255, 252, 226), body = Z.C3(255, 232, 150), edge = Z.C3(255, 150, 50), tip = Z.C3(214, 72, 18),
			soot = Z.C3(70, 60, 56), fleck = Z.C3(60, 40, 30), light = Z.C3(255, 214, 150), ember = Z.C3(255, 240, 180), ember2 = Z.C3(255, 150, 50),
		},
		-- ...and so hot it goes black and white: white fire inked in black
		mono = {
			heart = Z.C3(255, 255, 255), hot = Z.C3(255, 255, 255), body = Z.C3(244, 244, 244), edge = Z.C3(24, 24, 24), tip = Z.C3(0, 0, 0),
			soot = Z.C3(10, 10, 10), fleck = Z.C3(0, 0, 0), light = Z.C3(255, 255, 255), ember = Z.C3(255, 255, 255), ember2 = Z.C3(110, 110, 110),
		},
	}
	function Z.pal(p)
		return type(p) == "table" and p or BLAZE.PAL[p or "hell"] or BLAZE.PAL.hell
	end
	BLAZE.pal = Z.pal

	-- flat tones, hard edges: a colour holds, then snaps to the next (two
	-- keypoints a hair apart), the way cel paint does
	function Z.step2(a, b, at)
		return ColorSequence.new({ CK(0, a), CK(at, a), CK(math.min(at + 0.01, 1), b), CK(1, b) })
	end
	function Z.tongueColors(P)
		return {
			glow = ColorSequence.new(P.body, P.edge),
			shadeLo = ColorSequence.new(P.edge),
			shadeHi = Z.step2(P.edge, P.tip, 0.72),
			bodyLo = ColorSequence.new(P.body),
			bodyHi = ColorSequence.new(P.body),
			inner = ColorSequence.new(P.hot),
			core = ColorSequence.new(P.heart),
			-- (whole runs, for a jet: its layers are flat too)
			halo = ColorSequence.new(P.body, P.edge),
			shade = Z.step2(P.edge, P.tip, 0.8),
			body = ColorSequence.new(P.body),
			band = ColorSequence.new(P.hot),
			coreRun = ColorSequence.new(P.heart),
		}
	end
	Z.GLOW = NS({ NK(0, 0.84), NK(0.7, 0.9), NK(1, 1) })
	Z.SOLID = NS(0)
	Z.SHADE_HI = NS({ NK(0, 0), NK(0.9, 0), NK(1, 0.5) })
	Z.BODY_HI = NS({ NK(0, 0), NK(0.8, 0), NK(0.82, 1), NK(1, 1) })
	Z.INNER = NS({ NK(0, 0), NK(0.84, 0), NK(0.86, 1), NK(1, 1) })
	Z.CORE = NS({ NK(0, 0.04), NK(0.8, 0.04), NK(0.82, 1), NK(1, 1) })
	Z.FPS = 12 -- (drawings a second: fire animated on twos)
	-- (cel tones by depth: a tongue at the back is drawn a shade darker,
	-- so a flame reads as a stack of licks in front of each other)
	Z.colorCache = setmetatable({}, { __mode = "k" })
	function Z.shade(P, depth)
		if depth <= 0 then
			return P
		end
		local k = 0.38 * depth
		return {
			heart = P.heart:Lerp(P.hot, k), hot = P.hot:Lerp(P.body, k), body = P.body:Lerp(P.edge, k), edge = P.edge:Lerp(P.tip, k), tip = P.tip,
			soot = P.soot, fleck = P.fleck, light = P.light, ember = P.ember, ember2 = P.ember2,
		}
	end
	function Z.colorsFor(P, depth)
		depth = depth or 0
		local byDepth = Z.colorCache[P]
		if not byDepth then
			byDepth = {}
			Z.colorCache[P] = byDepth
		end
		local c = byDepth[depth]
		if not c then
			c = Z.tongueColors(Z.shade(P, depth))
			byDepth[depth] = c
		end
		return c
	end

	function Z.holder(cf)
		local h = newPart(Vector3.one * 0.2, cf, Color3.new(), nil, nil, folder)
		h.Transparency = 1
		h.Name = "Blaze"
		return h
	end
	function Z.attach(parent, cf)
		local a = Instance.new("Attachment")
		a.CFrame = cf
		a.Parent = parent
		return a
	end
	-- an ellipsoid (a Ball part is always round): a block with a sphere mesh
	function Z.egg(size, cf, color, parent)
		local q = newPart(size, cf, color, Enum.Material.Neon, nil, parent)
		local m = Instance.new("SpecialMesh")
		m.MeshType = Enum.MeshType.Sphere
		m.Parent = q
		return q
	end
	BLAZE.egg = Z.egg

	-- (a beam's curve handles run along its attachments' X axes: these point
	-- them up the flame, so CurveSize bends a tongue instead of twisting it)
	Z.AXIS_UP = CFrame.Angles(0, 0, math.pi / 2)
	function Z.beam(parent, a0, a1, color, trans, le, z, textured, bright)
		local b = Instance.new("Beam")
		b.Attachment0 = a0
		b.Attachment1 = a1
		if textured then
			b.Texture = Z.TEX
			b.TextureMode = Enum.TextureMode.Stretch
			b.TextureLength = 1
			b.TextureSpeed = 1.6
		end
		b.Color = color
		b.Transparency = trans
		b.LightEmission = le
		b.LightInfluence = 0
		b.FaceCamera = true
		b.Segments = 12
		b.ZOffset = z
		b.Brightness = bright or 1
		b.Parent = parent
		return b
	end

	-- A TONGUE on `f` (a flame): base offset `at` (in the flame's space,
	-- +Y = the way it burns), `h` tall, `w` wide, drawn `depth` back (0 = in
	-- front, 1 = at the back: a shade darker). The outer shape is three beams
	-- end to end - the belly (base to its widest, a fifth of the way up,
	-- bulging to one side), the waist (widest to the shoulder, two fifths
	-- up) and the tip (shoulder to a point, curling) - in the shade colour
	-- with the body inside it; a FORK licks off the shoulder to a second
	-- point (the anime's flames are never one spike); the inner tongue
	-- (a belly and a tip of its own, to 72% up) and the core (to 38%) are
	-- shorter flames inside those, so each tone is its own flame
	function Z.tongue(f, at, h, w, lean, depth, fork)
		depth = depth or 0
		local C = Z.colorsFor(f.P, depth)
		local function A(y)
			return Z.attach(f.holder, CFrame.new(at + Vector3.new(0, h * y, 0)) * Z.AXIS_UP)
		end
		local a0, aA, am, a1, ai, aim, ac = A(0), A(0.2), A(0.42), A(1), A(0.72), A(0.45), A(0.38)
		local t = {
			at = at, h = h, w = w, a0 = a0, aA = aA, am = am, a1 = a1, ai = ai, aim = aim, ac = ac, lean = lean or Vector3.zero,
			depth = depth, seed = rng:NextNumber(0, 1000), rate = rng:NextNumber(1.6, 2.6), lobe = rng:NextNumber(-1, 1),
		}
		-- (drawn in order, back to front, each tone a hair nearer the eye)
		local z = 0.5 - depth
		t.glow = Z.beam(f.holder, a0, a1, C.glow, Z.GLOW, 0.8, z - 0.15, true, 1.2)
		t.shadeA = Z.beam(f.holder, a0, aA, C.shadeLo, Z.SOLID, f.le, z, false, 1)
		t.shadeLo = Z.beam(f.holder, aA, am, C.shadeLo, Z.SOLID, f.le, z, false, 1)
		t.shadeHi = Z.beam(f.holder, am, a1, C.shadeHi, Z.SHADE_HI, f.le, z, false, 1)
		t.bodyA = Z.beam(f.holder, a0, aA, C.bodyLo, Z.SOLID, f.le, z + 0.15, false, 1)
		t.bodyLo = Z.beam(f.holder, aA, am, C.bodyLo, Z.SOLID, f.le, z + 0.15, false, 1)
		t.bodyHi = Z.beam(f.holder, am, a1, C.bodyHi, Z.BODY_HI, f.le, z + 0.15, false, 1)
		t.innerLo = Z.beam(f.holder, a0, aim, C.inner, Z.SOLID, f.le, z + 0.3, false, 1)
		t.innerHi = Z.beam(f.holder, aim, ai, C.inner, Z.INNER, f.le, z + 0.3, false, 1)
		t.core = Z.beam(f.holder, a0, ac, C.core, Z.CORE, f.le, z + 0.45, false, 1)
		t.shadeA.Name, t.bodyA.Name = "BlazeBelly", "BlazeBelly"
		if fork then
			t.af = A(0.8)
			t.forkSide = rng:NextNumber() < 0.5 and -1 or 1
			t.forkShade = Z.beam(f.holder, am, t.af, C.shadeHi, Z.SHADE_HI, f.le, z, false, 1)
			t.forkBody = Z.beam(f.holder, am, t.af, C.bodyHi, Z.BODY_HI, f.le, z + 0.15, false, 1)
			t.forkShade.Name, t.forkBody.Name = "BlazeFork", "BlazeFork"
		end
		table.insert(f.tongues, t)
		return t
	end

	-- FRAGMENTS: a blob of flame tears off a tip and floats away, shrinking
	-- (two beams - the shade round the body - on one shared anchor at the
	-- origin, so its attachments sit in the world), and when it's burnt out
	-- a PUFF is left where it was: a lump of dark smoke rolling up and
	-- thinning (the anime draws its smoke in lumps too). Stepped like the rest.
	BLAZE.frags = {}
	Z.FRAG_MAX = 120
	function Z.fragHolder()
		if not (BLAZE.fragHolder and BLAZE.fragHolder.Parent) then
			BLAZE.fragHolder = Z.holder(CFrame.new())
			BLAZE.fragHolder.Name = "BlazeFragments"
		end
		return BLAZE.fragHolder
	end
	function Z.fragment(f, pos, up, h, w)
		if #BLAZE.frags >= Z.FRAG_MAX then
			return
		end
		local C = Z.colorsFor(f.P, 0)
		local hold = Z.fragHolder()
		local a0 = Z.attach(hold, CFrame.new(pos))
		local a1 = Z.attach(hold, CFrame.new(pos + up * h))
		local shade = Z.beam(hold, a0, a1, C.shadeLo, Z.SOLID, f.le, 0.2, false, 1)
		local body = Z.beam(hold, a0, a1, C.bodyLo, Z.SOLID, f.le, 0.35, false, 1)
		shade.Name, body.Name = "BlazeFrag", "BlazeFrag"
		table.insert(BLAZE.frags, {
			P = f.P, a0 = a0, a1 = a1, shade = shade, body = body, pos = pos, up = up, h = h, w = w, lean = rng:NextNumber(-1, 1),
			vel = up * h * rng:NextNumber(5, 9) + rng:NextUnitVector() * w, born = os.clock(), life = rng:NextNumber(0.25, 0.45), puffs = f.puffs,
		})
	end
	function Z.puff(P, pos, up, size, speed)
		if #BLAZE.frags >= Z.FRAG_MAX then
			return
		end
		local q = newPart(Vector3.one * size, CFrame.new(pos), P.soot:Lerp(P.edge, 0.3), Enum.Material.SmoothPlastic, Enum.PartType.Ball, Z.fragHolder())
		q.Name = "BlazePuff"
		q.Transparency = 0.3
		table.insert(BLAZE.frags, {
			puff = q, pos = pos, up = up, size = size, born = os.clock(), life = rng:NextNumber(0.5, 0.9), spin = rng:NextNumber(-3, 3),
			vel = up * (speed or size * 3) + rng:NextUnitVector() * size * 0.6,
		})
	end
	BLAZE.puff = Z.puff
	function Z.stepFrag(q, now)
		local age = now - q.born
		local ta = math.floor(age * Z.FPS) / Z.FPS -- (moves on the drawing beat)
		if q.puff then
			if age > q.life then
				q.puff:Destroy()
				return false
			end
			local k = ta / q.life
			local sz = q.size * (0.6 + 0.5 * math.sin(k * math.pi * 0.8)) * (1 - k * 0.5)
			q.puff.Size = Vector3.one * math.max(sz, 0.05)
			q.puff.CFrame = CFrame.new(q.pos + q.vel * ta * (1 - k * 0.4)) * CFrame.Angles(0, q.spin * ta, q.spin * ta * 0.5)
			q.puff.Transparency = 0.3 + 0.7 * k * k
			return true
		end
		if age > q.life then
			q.a0:Destroy()
			q.a1:Destroy()
			q.shade:Destroy()
			q.body:Destroy()
			if q.puffs and rng:NextNumber() < 0.35 then
				Z.puff(q.P, q.pos + q.vel * q.life, q.up, q.w * 0.7, q.h * 3)
			end
			return false
		end
		local k = 1 - ta / q.life
		local at = q.pos + q.vel * ta
		local h = q.h * (0.4 + 0.6 * k)
		local side = q.up:Cross(Vector3.new(0, 0, 1))
		side = side.Magnitude > 1e-3 and side.Unit or Vector3.new(1, 0, 0)
		q.a0.Position = at
		q.a1.Position = at + q.up * h + side * q.lean * h * 0.3
		-- (a teardrop: fat at the bottom, to a point)
		q.shade.Width0, q.shade.Width1 = q.w * k, 0
		q.body.Width0, q.body.Width1 = q.w * 0.62 * k, 0
		q.shade.CurveSize0, q.body.CurveSize0 = h * 0.35, h * 0.3
		return true
	end

	-- the particles between the tongues
	function Z.volume(f, rate)
		local P, s = f.P, f.height
		local set = {}
		local function pe(props)
			local e = Instance.new("ParticleEmitter")
			for k, v in props do
				e[k] = v
			end
			e.Parent = f.holder
			table.insert(set, e)
			return e
		end
		local up = Vector3.new(0, 1, 0)
		set.body = pe({
			Name = "BlazeBody", Texture = Z.TEX, LightEmission = f.le, LightInfluence = 0, Brightness = 1.3,
			Color = ColorSequence.new({ CK(0, P.hot), CK(0.25, P.body), CK(0.65, P.edge), CK(1, P.tip) }),
			Size = NS({ NK(0, s * 0.22), NK(0.3, s * 0.36), NK(1, s * 0.06) }),
			Transparency = NS({ NK(0, 1), NK(0.1, 0.55), NK(0.6, 0.7), NK(1, 1) }),
			Squash = NS({ NK(0, 0.4), NK(1, 1) }),
			Lifetime = NumberRange.new(0.35, 0.6), Speed = NumberRange.new(s * 0.8, s * 1.5),
			Acceleration = up * s * 3, Drag = 2.2, EmissionDirection = Enum.NormalId.Top,
			Rotation = NumberRange.new(-20, 20), RotSpeed = NumberRange.new(-60, 60), SpreadAngle = Vector2.new(14, 14),
			Rate = 18 * rate, ZOffset = 0.5, LockedToPart = f.locked == true,
		})
		set.heart = pe({
			Name = "BlazeHeart", Texture = Z.TEX, LightEmission = 1, LightInfluence = 0, Brightness = 2,
			Color = ColorSequence.new(P.heart, P.hot),
			Size = NS({ NK(0, s * 0.14), NK(0.5, s * 0.18), NK(1, 0) }),
			Transparency = NS({ NK(0, 0.6), NK(0.2, 0.05), NK(1, 1) }),
			Lifetime = NumberRange.new(0.15, 0.3), Speed = NumberRange.new(s * 0.4, s * 0.9),
			Acceleration = up * s * 2, Drag = 2, EmissionDirection = Enum.NormalId.Top,
			Rotation = NumberRange.new(0, 360), SpreadAngle = Vector2.new(8, 8),
			Rate = 14 * rate, ZOffset = 1.5, LockedToPart = f.locked == true,
		})
		-- the red haze round a big fire (the compositing glow the anime lays
		-- behind Endeavor's flames), drifting up behind the tongues
		if s >= 5 and rate > 0 then
			set.haze = pe({
				Name = "BlazeHaze", Texture = Z.SMOKE_TEX, LightEmission = 0.35, LightInfluence = 0, Brightness = 1,
				Color = ColorSequence.new(P.edge, P.tip),
				Size = NS({ NK(0, s * 0.5), NK(0.5, s * 1), NK(1, s * 1.3) }),
				Transparency = NS({ NK(0, 1), NK(0.2, 0.72), NK(0.7, 0.86), NK(1, 1) }),
				Lifetime = NumberRange.new(0.6, 1), Speed = NumberRange.new(s * 0.6, s * 1.2),
				Acceleration = up * s * 1.5, Drag = 1.6, EmissionDirection = Enum.NormalId.Top,
				Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-30, 30), SpreadAngle = Vector2.new(30, 30),
				Rate = 5 * rate, ZOffset = -2, LockedToPart = f.locked == true,
			})
		end
		if f.smoke then
			set.soot = pe({
				Name = "BlazeSoot", Texture = Z.SMOKE_TEX, LightEmission = 0, LightInfluence = 0.4,
				Color = ColorSequence.new(P.soot, P.soot:Lerp(Color3.new(), 0.4)),
				Size = NS({ NK(0, s * 0.3), NK(1, s * 1.2) }),
				Transparency = NS({ NK(0, 1), NK(0.3, 0.74), NK(1, 1) }),
				Lifetime = NumberRange.new(1.2, 2.2), Speed = NumberRange.new(s * 0.9, s * 1.5),
				Acceleration = Vector3.new(0, s * 0.8, 0), Drag = 1.1, EmissionDirection = Enum.NormalId.Top,
				Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-25, 25), SpreadAngle = Vector2.new(22, 22),
				Rate = 3 * rate, ZOffset = -1,
			})
		end
		-- cinders: dark flecks drifting up round it (the anime's ash)
		if rate > 0 then
			set.flecks = pe({
				Name = "BlazeFlecks", Texture = Z.SMOKE_TEX, LightEmission = 0, LightInfluence = 0,
				Color = ColorSequence.new(P.fleck or P.soot),
				Size = NS({ NK(0, s * 0.05), NK(1, s * 0.02) }),
				Transparency = NS({ NK(0, 0.1), NK(0.8, 0.2), NK(1, 1) }),
				Lifetime = NumberRange.new(0.8, 1.4), Speed = NumberRange.new(s * 0.8, s * 1.6),
				Acceleration = Vector3.new(0, s * 0.6, 0), Drag = 1.2, EmissionDirection = Enum.NormalId.Top,
				Rotation = NumberRange.new(0, 360), RotSpeed = NumberRange.new(-200, 200), SpreadAngle = Vector2.new(50, 50),
				Rate = 3 * rate,
			})
		end
		set.embers = pe({
			Name = "BlazeEmbers", Texture = Z.SPARK_TEX, LightEmission = 1, LightInfluence = 0, Brightness = 2,
			Color = ColorSequence.new(P.ember, P.ember2),
			Size = NS({ NK(0, 0.2), NK(1, 0) }),
			Lifetime = NumberRange.new(0.7, 1.5), Speed = NumberRange.new(s * 1, s * 2.4),
			Acceleration = Vector3.new(0, s * 1.2, 0), Drag = 1.4, EmissionDirection = Enum.NormalId.Top,
			SpreadAngle = Vector2.new(40, 40), Rate = 6 * rate,
		})
		return set
	end

	-- A FLAME. spec:
	--   CF       - where it stands; it burns along the CFrame's UpVector
	--   Part, Offset - or: it rides on a part (Offset from its CFrame)
	--   Height, Width - the tallest tongue, and how wide the base spreads
	--   Pal      - "hell" | "blue" | "white" | a palette table
	--   Tongues  - how many (default by width)
	--   Volume   - particle rate multiplier (0: tongues only)
	--   Smoke, Heart (a neon heart at the base: off unless true), Light
	--   (range, 0 = none), Life (then it dies down), Frags (how often blobs
	--   tear off the tips: 1 = the usual, 0 = never),
	--   Grow     - seconds to rise up out of nothing
	--   Wind     - a world Vector3 every tip leans along (e.g. -velocity)
	--   Soft     - the body bands on the soft texture too (smaller flames)
	--   Forks    - false: no forked tips (they're on for flames 2.4+ tall)
	--   Puffs    - false: no lumps of smoke off the fragments (on for smoky
	--              flames and big ones)
	-- Returns f: f.kill(t) dies down over t seconds; f.level(k) scales it
	function BLAZE.flame(spec)
		local P = Z.pal(spec.Pal)
		local h = spec.Height or 4
		local w = spec.Width or h * 0.6
		local cf = spec.CF or (spec.Part and spec.Part.CFrame * (spec.Offset or CFrame.new())) or CFrame.new()
		local f = {
			P = P, height = h, width = w, tongues = {}, k = spec.Grow and 0 or 1, target = 1,
			part = spec.Part, offset = spec.Offset or CFrame.new(), cf = cf, wind = spec.Wind,
			le = spec.LightEmission or 0.05, soft = spec.Soft == true, smoke = spec.Smoke == true,
			born = os.clock(), grow = spec.Grow, spin = spec.Spin or 0, locked = spec.Part ~= nil,
			frags = spec.Frags or (spec.Soft and 0.35 or 1), phase = rng:NextNumber(0, 1),
			puffs = spec.Puffs ~= false and (spec.Smoke == true or h >= 5),
		}
		f.holder = Z.holder(cf)
		local n = spec.Tongues or math.clamp(math.floor(w / 0.9) + 2, 2, 10)
		-- the tallest in the middle, shorter ones round them, leaning out; the
		-- rest take turns in front, mid-way and at the back (a shade darker)
		local forks = spec.Forks ~= false and h >= 2.4
		for i = 1, n do
			local a = (i / n) * math.pi * 2 + rng:NextNumber(-0.4, 0.4)
			local r = i == 1 and 0 or w * 0.5 * math.sqrt(rng:NextNumber(0.25, 1))
			local at = Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
			local tall = h * (i == 1 and 1 or rng:NextNumber(0.5, 0.85))
			local tw = w * (i == 1 and 0.62 or rng:NextNumber(0.36, 0.52))
			local depth = i == 1 and 0 or (i % 3 == 2 and 0.5 or i % 3 == 0 and 1 or 0)
			Z.tongue(f, at, tall, tw, at * 0.35, depth, forks and (i == 1 or rng:NextNumber() < 0.7))
		end
		if (spec.Volume or 1) > 0 then
			f.fx = Z.volume(f, (spec.Volume or 1) * math.clamp(w / 2, 0.6, 3))
			f.holder.Size = Vector3.new(math.max(w * 0.7, 0.2), 0.2, math.max(w * 0.7, 0.2))
		end
		if spec.Heart == true then
			f.heart = Z.egg(Vector3.new(w * 0.55, h * 0.18, w * 0.55), cf * CFrame.new(0, h * 0.08, 0), P.heart)
			f.heart.Transparency = 0.25
			f.heart.Name = "BlazeHeart"
		end
		if (spec.Light or 1) ~= 0 then
			local l = Instance.new("PointLight")
			l.Color = P.light
			l.Range = math.min(spec.Light or h * 3, 60)
			l.Brightness = 2
			l.Shadows = false
			l.Parent = f.holder
			f.light, f.lightRange = l, l.Range
		end
		table.insert(BLAZE.live, f)
		function f.level(k)
			f.target = k
		end
		function f.kill(t)
			if f.dying then
				return
			end
			f.dying = os.clock()
			f.fade = math.max(t or 0.4, 0.05)
			f.target = 0
			for _, e in f.fx or {} do
				e.Enabled = false
			end
			task.delay(f.fade + 2.2, function()
				f.dead = true
				f.holder:Destroy()
				if f.heart then
					f.heart:Destroy()
				end
			end)
		end
		if spec.Life then
			task.delay(spec.Life, function()
				f.kill(spec.Fade or 0.5)
			end)
		end
		return f
	end

	-- one frame of a flame: follow its part, lick every tongue, flicker
	function Z.step(f, now, dt, camPos)
		if f.part then
			if not f.part.Parent then
				f.kill(0.2)
				f.part = nil
			else
				f.cf = f.part.CFrame * f.offset
				f.holder.CFrame = f.cf
			end
		end
		-- grow in / die down / level changes ease towards the target
		local ease = f.dying and (dt / f.fade) or (f.grow and dt / f.grow or dt * 8)
		if f.k < f.target then
			f.k = math.min(f.target, f.k + ease)
		elseif f.k > f.target then
			f.k = math.max(f.target, f.k - ease)
		end
		local k = f.k
		local far = camPos and (f.cf.Position - camPos).Magnitude > 260
		if f.heart then
			local pulse = 0.85 + 0.3 * Z.noise(now * 9, f.height, 0.5)
			f.heart.Size = Vector3.new(f.width * 0.55, f.height * 0.18, f.width * 0.55) * math.max(k * pulse, 0.01)
			f.heart.CFrame = f.cf * CFrame.new(0, f.height * 0.08 * k, 0)
			f.heart.Transparency = 1 - (1 - 0.25) * math.min(k, 1)
		end
		if f.light then
			f.light.Brightness = 2 * k * (0.75 + 0.5 * rng:NextNumber())
			f.light.Range = f.lightRange * (0.9 + 0.2 * rng:NextNumber())
		end
		if far and not f.dying then
			return
		end
		-- the shapes change on the drawing beat (twelve a second, each flame
		-- on its own phase), not every frame: that's the hand-drawn flicker
		local frame = math.floor(now * Z.FPS + f.phase)
		if frame == f.frame or (frame % 6 == 5 and f.frame == frame - 1) then
			return -- (every sixth drawing is held a beat longer: the timing breathes)
		end
		f.frame = frame
		local tnow = frame / Z.FPS
		-- (wind: a world vector, in the flame's own space - plus the rush of
		-- air past whatever it's riding on, so it streams back off a runner)
		local w = f.wind or Vector3.zero
		if f.part then
			w -= f.part.AssemblyLinearVelocity * 0.6
		end
		local wind = w.Magnitude > 0.1 and f.cf:VectorToObjectSpace(w) or Vector3.zero
		local fragOk = f.frags > 0 and k > 0.3 and not f.dying and #BLAZE.frags < Z.FRAG_MAX
		local Z0 = Vector3.new(0, 0, 1)
		local function frame3(p, dir)
			local sd = dir:Cross(Z0)
			sd = sd.Magnitude > 1e-3 and sd.Unit or Vector3.new(1, 0, 0)
			return CFrame.fromMatrix(p, dir, sd:Cross(dir))
		end
		for _, t in f.tongues do
			local s = t.seed
			local tt = tnow * t.rate
			-- flicker: taller, shorter, never quite still (bigger jumps than a
			-- smooth flame: each drawing is its own shape)
			local lick = 0.72 + 0.28 * Z.noise(tt * 1.7, s, 0.1) + 0.16 * Z.noise(tt * 6.1, s, 1.3)
			local hh = t.h * math.max(lick, 0.3) * k
			local ww = t.w * k * (0.88 + 0.24 * Z.noise(tt * 2.3, s, 7.5))
			local spin = f.spin ~= 0 and CFrame.Angles(0, tnow * f.spin, 0) or nil
			local base = spin and (spin * t.at) or t.at
			local lean = spin and spin * t.lean or t.lean
			local blow = wind * 0.035
			if blow.Magnitude > 0.9 then
				blow = blow.Unit * 0.9
			end
			-- the belly wanders a little, the tip a lot (and the wind takes it)
			local mid = base + Vector3.new(
				Z.noise(tt * 0.9, s, 2.1) * t.w * 0.3 + lean.X * 0.4 + blow.X * hh * 0.3,
				hh * 0.42,
				Z.noise(tt * 0.9, s, 3.7) * t.w * 0.3 + lean.Z * 0.4 + blow.Z * hh * 0.3
			)
			local tip = base + Vector3.new(
				Z.noise(tt * 1.4, s, 4.3) * t.w * 1.45 + lean.X + blow.X * hh,
				hh,
				Z.noise(tt * 1.4, s, 5.9) * t.w * 1.45 + lean.Z + blow.Z * hh
			)
			-- the belly's widest, a fifth of the way up, bulging out to one side
			local bel = base + (mid - base) * 0.45 + Vector3.new(t.lobe * t.w * 0.24 * (0.6 + 0.4 * Z.noise(tt, s, 8.8)), 0, 0)
			-- the join runs along the flame there, so the pieces meet smooth
			local along = (tip - base).Unit + (mid - base).Unit
			along = along.Magnitude > 1e-3 and along.Unit or Vector3.new(0, 1, 0)
			t.a0.CFrame = frame3(base, along)
			t.aA.CFrame = frame3(bel, ((mid - bel).Magnitude > 1e-3 and (mid - bel).Unit or along))
			t.am.CFrame = frame3(mid, along)
			-- the tip's handle points back down its lean: a lick that curls
			t.a1.CFrame = frame3(tip, (tip - mid).Unit)
			-- the inner tongue and the core: shorter flames inside, leaning with it
			local inTip = base + (mid - base) * 0.5 + (tip - base) * 0.45
			local inDir = (inTip - base).Magnitude > 1e-3 and (inTip - base).Unit or along
			local inMid = base + (inTip - base) * 0.6 + Vector3.new(t.lobe * t.w * 0.1, 0, 0)
			t.aim.CFrame = frame3(inMid, inDir)
			t.ai.CFrame = frame3(inTip, inDir)
			t.ac.CFrame = frame3(base + (inTip - base) * 0.52, inDir)
			-- the fork: off the shoulder, out to the side and up to a point of its own
			local fk
			if t.af then
				fk = mid + Vector3.new(
					t.forkSide * t.w * (0.9 + 0.5 * Z.noise(tt * 1.2, s, 9.1)) + blow.X * hh * 0.4,
					hh * (0.3 + 0.16 * Z.noise(tt * 1.5, s, 9.7)),
					blow.Z * hh * 0.4
				)
				t.af.CFrame = frame3(fk, (fk - mid).Unit)
				t.forkShade.CurveSize0, t.forkShade.CurveSize1 = hh * 0.1, hh * 0.12
				t.forkBody.CurveSize0, t.forkBody.CurveSize1 = hh * 0.1, hh * 0.12
				t.forkShade.Width0, t.forkShade.Width1 = ww * 0.72, 0
				t.forkBody.Width0, t.forkBody.Width1 = ww * 0.5, 0
			end
			-- curves: a fat round belly, then an S-curl up to the point
			local c0 = hh * 0.1
			local cA = hh * (0.12 + 0.06 * Z.noise(tt * 1.3, s, 5.2))
			local cm = hh * (0.16 + 0.08 * Z.noise(tt * 1.3, s, 5.2))
			local c1 = hh * (0.26 + 0.22 * Z.noise(tt * 1.1, s, 6.4))
			t.shadeA.CurveSize0, t.shadeA.CurveSize1 = c0, cA
			t.bodyA.CurveSize0, t.bodyA.CurveSize1 = c0, cA
			t.shadeLo.CurveSize0, t.shadeLo.CurveSize1 = cA, cm
			t.bodyLo.CurveSize0, t.bodyLo.CurveSize1 = cA, cm
			t.shadeHi.CurveSize0, t.shadeHi.CurveSize1 = cm * 1.4, c1
			t.bodyHi.CurveSize0, t.bodyHi.CurveSize1 = cm * 1.4, c1
			t.glow.CurveSize0, t.glow.CurveSize1 = hh * 0.3, c1
			t.innerLo.CurveSize0, t.innerLo.CurveSize1 = hh * 0.12, hh * 0.1
			t.innerHi.CurveSize0, t.innerHi.CurveSize1 = hh * 0.1, hh * 0.08
			t.core.CurveSize0, t.core.CurveSize1 = hh * 0.1, hh * 0.05
			-- widths: a lobed belly, fat a fifth of the way up, a waist at the
			-- shoulder, and a thin whip of a tip
			t.glow.Width0, t.glow.Width1 = ww * 1.5, ww * 0.4
			t.shadeA.Width0, t.shadeA.Width1 = ww * 0.95, ww * 1.6
			t.shadeLo.Width0, t.shadeLo.Width1 = ww * 1.6, ww * 1.15
			t.shadeHi.Width0, t.shadeHi.Width1 = ww * 1.15, 0
			t.bodyA.Width0, t.bodyA.Width1 = ww * 0.74, ww * 1.32
			t.bodyLo.Width0, t.bodyLo.Width1 = ww * 1.32, ww * 0.9
			t.bodyHi.Width0, t.bodyHi.Width1 = ww * 0.9, 0
			t.innerLo.Width0, t.innerLo.Width1 = ww * 0.5, ww * 0.78
			t.innerHi.Width0, t.innerHi.Width1 = ww * 0.78, 0
			t.core.Width0, t.core.Width1 = ww * 0.42, 0
			-- now and then a blob tears off the tip (or the fork's) and floats away
			if fragOk and rng:NextNumber() < 0.08 * f.frags then
				local from = (fk and rng:NextNumber() < 0.4) and fk or tip
				Z.fragment(f, f.cf * from, f.cf.UpVector, hh * rng:NextNumber(0.18, 0.3), ww * rng:NextNumber(0.35, 0.55))
			end
		end
	end
	BLAZE.step = Z.step

	RunService.RenderStepped:Connect(function(dt)
		local frags = BLAZE.frags
		if #frags > 0 then
			local fnow = os.clock()
			for i = #frags, 1, -1 do
				local ok, keep = pcall(Z.stepFrag, frags[i], fnow)
				if not ok or not keep then
					table.remove(frags, i)
				end
			end
		end
		local list = BLAZE.live
		if #list == 0 then
			return
		end
		local now = os.clock()
		local cam = workspace.CurrentCamera
		local camPos = cam and cam.CFrame.Position
		for i = #list, 1, -1 do
			local f = list[i]
			if f.dead then
				table.remove(list, i)
			else
				local ok = pcall(Z.step, f, now, dt, camPos)
				if not ok then
					f.dead = true
					table.remove(list, i)
				end
			end
		end
	end)

	-- BURST: a fireball blooms out of pos and rolls up into soot. scale ~
	-- its radius in studs. opts: Pal, Up (the way it rolls; default up),
	-- Tongues (how many lick out of it), NoScorch, Sound
	function BLAZE.burst(pos, scale, opts)
		opts = opts or {}
		local P = Z.pal(opts.Pal)
		local s = scale or 4
		local up = opts.Up or Vector3.new(0, 1, 0)
		-- shells: white heart, then hot, body and edge, each bigger and slower
		for i, spec in { { P.heart, 0.6, 0.1, 0.18 }, { P.hot, 1, 0.2, 0.28 }, { P.body, 1.35, 0.35, 0.4 }, { P.edge, 1.6, 0.55, 0.55 } } do
			local ball = newPart(Vector3.one * s * 0.3, CFrame.new(pos), spec[1], Enum.Material.Neon, Enum.PartType.Ball)
			ball.Transparency = spec[3]
			ball.Name = "BlazeShell"
			tween(ball, spec[4], { Size = Vector3.one * s * 2 * spec[2] }, Enum.EasingStyle.Quint)
			tween(ball, spec[4] * 1.4, { Transparency = 1, CFrame = CFrame.new(pos + up * s * 0.5 * i / 4) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, spec[4] * 0.5)
			cleanup(ball, spec[4] * 2 + 0.1)
		end
		-- SPIKES: the anime's burst is a star - flat wedges of flame stabbing
		-- out of it and snapping back, drawing by drawing
		local hold = Z.holder(CFrame.new(pos))
		local C = Z.colorsFor(P, 0)
		for i = 1, opts.Spikes or 12 do
			local d = (rng:NextUnitVector() + up * 0.5).Unit
			local a0 = Z.attach(hold, CFrame.new(d * s * 0.3))
			local a1 = Z.attach(hold, CFrame.new(d * s * 0.5))
			local sh = Z.beam(hold, a0, a1, C.shadeLo, Z.SOLID, 0.3, 0.2, false, 1)
			local bo = Z.beam(hold, a0, a1, C.bodyLo, Z.SOLID, 0.3, 0.35, false, 1)
			sh.Name, bo.Name = "BlazeSpike", "BlazeSpike"
			sh.Width0, sh.Width1 = s * 0.5, 0
			bo.Width0, bo.Width1 = s * 0.32, 0
			local reach = s * rng:NextNumber(1.8, 3)
			task.delay(i * 0.008, function()
				for step = 1, 5 do
					local kk = step / 5
					a1.CFrame = CFrame.new(d * (s * 0.5 + (reach - s * 0.5) * math.sin(kk * math.pi * 0.5)))
					local wk = step <= 3 and 1 or (5 - step) / 2
					sh.Width0, bo.Width0 = s * 0.5 * wk, s * 0.32 * wk
					task.wait(1 / Z.FPS)
				end
			end)
		end
		cleanup(hold, 0.7)
		-- gold cross sparkles round it, and lumps of smoke rolling up after
		local MG = VFX.MANGA
		if MG and MG.flare then
			for i = 1, math.clamp(math.floor(s * 0.8), 3, 8) do
				task.delay(i * 0.03, MG.flare, pos + rng:NextUnitVector() * s * rng:NextNumber(0.8, 1.6), P.hot, s * rng:NextNumber(0.5, 0.9), 0.35)
			end
		end
		if opts.Smoke ~= false then
			for i = 1, math.clamp(math.floor(s), 3, 7) do
				task.delay(0.15 + i * 0.05, Z.puff, P, pos + rng:NextUnitVector() * s * 0.5 + up * s * 0.4, up, s * rng:NextNumber(0.22, 0.4), s * 2)
			end
		end
		-- tongues lick out of it, and fall back
		local n = opts.Tongues or 8
		for i = 1, n do
			local d = (rng:NextUnitVector() + up * 0.8).Unit
			local cf = CFrame.lookAt(pos + d * s * 0.4, pos + d * s * 2) * CFrame.Angles(-math.pi / 2, 0, 0)
			local f = BLAZE.flame({ CF = cf, Pal = P, Height = s * rng:NextNumber(0.9, 1.5), Width = s * 0.45, Tongues = 2, Volume = 0, Heart = false, Light = 0, Grow = 0.08, Wind = up * 10 })
			task.delay(0.12 + 0.02 * i, function()
				f.kill(0.35)
			end)
		end
		-- the volume: one puff of every particle layer
		local h = Z.holder(CFrame.new(pos))
		h.Size = Vector3.one * s * 0.4
		local f = { P = P, height = s * 1.2, holder = h, smoke = opts.Smoke ~= false, le = 0.5 }
		local set = Z.volume(f, 0)
		set.body.Shape = Enum.ParticleEmitterShape.Sphere
		set.body.Speed = NumberRange.new(s * 1.5, s * 3)
		set.body.Drag = 4
		set.body:Emit(math.floor(10 + s * 2))
		set.heart:Emit(math.floor(6 + s))
		if set.soot then
			set.soot:Emit(math.floor(4 + s))
		end
		set.embers.SpreadAngle = Vector2.new(120, 120)
		set.embers:Emit(math.floor(10 + s * 2))
		local l = Instance.new("PointLight")
		l.Color = P.light
		l.Range = math.min(s * 6, 60)
		l.Brightness = 5
		l.Parent = h
		tween(l, 0.6, { Brightness = 0 })
		cleanup(h, 2.6)
		if not opts.NoScorch then
			BLAZE.scorch(pos, s * 0.9, P)
		end
	end

	-- SCORCH: a burn on the street - glowing at the edge, cooling to soot
	function BLAZE.scorch(pos, radius, p)
		local P = Z.pal(p)
		local hit = groundRay(pos + Vector3.new(0, 2, 0), 12)
		if not hit then
			return
		end
		local at = hit.Position
		local soot = newPart(Vector3.new(0.12, radius * 2, radius * 2), CFrame.new(at + Vector3.new(0, 0.05, 0)) * CFrame.Angles(0, 0, math.rad(90)), Color3.fromRGB(26, 22, 22), Enum.Material.Slate, Enum.PartType.Cylinder)
		soot.Name = "BlazeScorch"
		soot.Transparency = 0.15
		local glow = newPart(Vector3.new(0.14, radius * 1.5, radius * 1.5), CFrame.new(at + Vector3.new(0, 0.07, 0)) * CFrame.Angles(0, 0, math.rad(90)), P.body, Enum.Material.Neon, Enum.PartType.Cylinder)
		glow.Name = "BlazeScorch"
		glow.Transparency = 0.2
		tween(glow, 2.5, { Color = P.tip, Transparency = 1, Size = Vector3.new(0.14, radius * 0.6, radius * 0.6) })
		tween(soot, 3, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 6)
		cleanup(glow, 2.6)
		cleanup(soot, 9.1)
	end

	-- JET: a torrent of fire from `from` down `dir`, `length` long and `width`
	-- across at the far end. Rides on spec.Part (a hand) if given. The body
	-- is a bundle of long beams bending on noise with the texture streaming
	-- down them, fire rolls off it and up, and the far end billows.
	-- Returns j: j.aim(from, dir) re-points it; j.stop(t) ends it
	function BLAZE.jet(spec)
		local P = Z.pal(spec.Pal)
		local C = Z.colorsFor(P)
		local len, wid = spec.Length or 40, spec.Width or 8
		local j = { P = P, from = spec.From, dir = (spec.Dir or Vector3.new(0, 0, -1)).Unit, len = len, wid = wid, born = os.clock() }
		j.holder = Z.holder(CFrame.lookAt(j.from, j.from + j.dir))
		-- (along a jet the handles run down it - its attachments' X axes point
		-- down -Z - and tilting them off the line is what makes it snake)
		local ALONG = CFrame.Angles(0, math.pi / 2, 0)
		-- (flat tones like the flames: the shade, the body, the yellow band,
		-- the pale core - each narrower and stopping shorter - and a faint glow)
		local layers = {
			{ name = "halo", color = C.halo, t = NS({ NK(0, 0.62), NK(0.6, 0.7), NK(1, 1) }), le = 0.8, z = 0, tex = true, b = 1.2, wf = 1.5 },
			{ name = "shade", color = C.shade, t = NS({ NK(0, 0.25), NK(0.9, 0.25), NK(1, 0.8) }), le = 0.05, z = 1, tex = false, b = 1, wf = 1.05 },
			{ name = "body", color = C.body, t = NS({ NK(0, 0), NK(0.84, 0), NK(0.86, 1), NK(1, 1) }), le = 0.05, z = 2, tex = false, b = 1, wf = 0.85 },
			{ name = "band", color = C.band, t = NS({ NK(0, 0), NK(0.62, 0), NK(0.64, 1), NK(1, 1) }), le = 0.05, z = 3, tex = false, b = 1, wf = 0.5 },
			{ name = "core", color = C.coreRun, t = NS({ NK(0, 0), NK(0.36, 0), NK(0.38, 1), NK(1, 1) }), le = 0.1, z = 4, tex = false, b = 1, wf = 0.25 },
		}
		for i, L in layers do
			L.a0 = Z.attach(j.holder, ALONG)
			L.a1 = Z.attach(j.holder, CFrame.new(0, 0, -len) * ALONG)
			L.beam = Z.beam(j.holder, L.a0, L.a1, L.color, L.t, L.le, L.z, L.tex, L.b)
			L.beam.Segments = 24
			L.beam.TextureSpeed = 4
			L.seed = i * 17.3
		end
		j.layers = layers
		-- the fire that rolls off it: particles thrown down the jet
		local speed = len * 2.4
		local cone = math.deg(math.atan(wid / len)) * 0.8
		local pe = Instance.new("ParticleEmitter")
		pe.Name = "BlazeJet"
		pe.Texture = Z.TEX
		pe.Color = ColorSequence.new({ CK(0, P.heart), CK(0.15, P.hot), CK(0.4, P.body), CK(0.75, P.edge), CK(1, P.tip) })
		pe.LightEmission = 0.6
		pe.LightInfluence = 0
		pe.Brightness = 1.4
		pe.Size = NS({ NK(0, wid * 0.08), NK(0.35, wid * 0.35), NK(0.8, wid * 0.55), NK(1, wid * 0.2) })
		pe.Transparency = NS({ NK(0, 0.5), NK(0.1, 0.12), NK(0.7, 0.4), NK(1, 1) })
		pe.Lifetime = NumberRange.new(0.4, 0.55)
		pe.Speed = NumberRange.new(speed * 0.85, speed)
		pe.Drag = 2.4
		pe.Acceleration = Vector3.new(0, 16, 0)
		pe.Rotation = NumberRange.new(0, 360)
		pe.RotSpeed = NumberRange.new(-180, 180)
		pe.SpreadAngle = Vector2.new(cone, cone)
		pe.EmissionDirection = Enum.NormalId.Front
		pe.Rate = 110
		pe.ZOffset = 0.5
		pe.Parent = j.holder
		local soot = pe:Clone()
		soot.Name = "BlazeJetSoot"
		soot.Texture = Z.SMOKE_TEX
		soot.Color = ColorSequence.new(P.soot)
		soot.LightEmission = 0
		soot.LightInfluence = 0.4
		soot.Brightness = 1
		soot.Size = NS({ NK(0, wid * 0.2), NK(1, wid * 0.9) })
		soot.Transparency = NS({ NK(0, 1), NK(0.4, 0.6), NK(1, 1) })
		soot.Lifetime = NumberRange.new(0.9, 1.3)
		soot.Speed = NumberRange.new(speed * 0.55, speed * 0.7)
		soot.Rate = 18
		soot.ZOffset = -1
		soot.Parent = j.holder
		local embers = pe:Clone()
		embers.Name = "BlazeJetEmbers"
		embers.Texture = Z.SPARK_TEX
		embers.Color = ColorSequence.new(P.ember, P.ember2)
		embers.LightEmission = 1
		embers.Size = NS({ NK(0, 0.3), NK(1, 0) })
		embers.Transparency = NS(0)
		embers.Lifetime = NumberRange.new(0.5, 1)
		embers.SpreadAngle = Vector2.new(16, 16)
		embers.Rate = 36
		embers.Parent = j.holder
		j.fx = { pe, soot, embers }
		local l = Instance.new("PointLight")
		l.Color = P.light
		l.Range = math.min(len * 0.7, 60)
		l.Brightness = 3
		l.Parent = j.holder
		-- the far end billows: flames standing up where it gets to
		j.head = BLAZE.flame({ CF = CFrame.new(j.from + j.dir * len), Pal = P, Height = wid * 0.9, Width = wid * 0.8, Volume = 0.6, Light = 0, Grow = 0.15 })
		-- and fire rolls up off it all the way along (each one drifting out
		-- along the jet and round again, so it churns)
		j.rolls = {}
		for i = 1, spec.Rolls or 5 do
			table.insert(j.rolls, {
				at = i / ((spec.Rolls or 5) + 1),
				f = BLAZE.flame({ CF = CFrame.new(j.from), Pal = P, Height = wid * rng:NextNumber(0.5, 0.8), Width = wid * 0.5, Tongues = 3, Volume = 0, Heart = false, Light = 0, Grow = 0.1 }),
			})
		end
		function j.aim(from, dir)
			j.from = from
			j.dir = dir.Magnitude > 0.01 and dir.Unit or j.dir
		end
		function j.stop(t)
			if j.dead then
				return
			end
			j.dead = true
			t = t or 0.25
			for _, e in j.fx do
				e.Enabled = false
			end
			j.head.kill(0.4)
			for _, r in j.rolls do
				r.f.kill(0.3)
			end
			for _, L in layers do
				tween(L.beam, t, { Width0 = 0, Width1 = 0 })
			end
			tween(l, t, { Brightness = 0 })
			cleanup(j.holder, t + 1.4)
		end
		-- every frame: it reaches out (fast), each layer snakes on its own
		function j.frame(clock)
			local reach = j.len * math.min((clock - j.born) / 0.12, 1)
			local now = math.floor(clock * Z.FPS) / Z.FPS
			j.holder.CFrame = CFrame.lookAt(j.from, j.from + j.dir)
			for _, L in layers do
				local s = L.seed
				local amp = L.tex and 0.75 or 0.55
				local tilt0 = CFrame.Angles(Z.noise(now * 2.2, s, 1) * amp, Z.noise(now * 2.2, s, 2) * amp, 0)
				local tilt1 = CFrame.Angles(Z.noise(now * 2.6, s, 3) * amp, Z.noise(now * 2.6, s, 4) * amp, 0)
				L.a0.CFrame = tilt0 * ALONG
				L.a1.CFrame = CFrame.new(Z.noise(now * 3, s, 5) * j.wid * 0.28, Z.noise(now * 3, s, 6) * j.wid * 0.28, -reach) * tilt1 * ALONG
				L.beam.CurveSize0 = reach * 0.3
				L.beam.CurveSize1 = reach * 0.3
				L.beam.Width0 = j.wid * 0.1 * L.wf
				L.beam.Width1 = j.wid * L.wf * (0.9 + 0.2 * Z.noise(now * 6, s, 7))
			end
			j.head.cf = CFrame.new(j.from + j.dir * reach)
			j.head.holder.CFrame = j.head.cf
			for _, r in j.rolls do
				local a = (r.at + (clock - j.born) * 0.9) % 1
				local p = j.from + j.dir * reach * (0.15 + 0.85 * a) + Vector3.new(0, j.wid * 0.12 * a, 0)
				r.f.cf = CFrame.new(p)
				r.f.holder.CFrame = r.f.cf
				r.f.level(0.35 + 0.8 * a)
			end
		end
		task.spawn(function()
			while not j.dead and j.holder.Parent do
				j.frame(os.clock())
				task.wait()
			end
		end)
		if spec.Life then
			task.delay(spec.Life, function()
				j.stop(spec.Fade)
			end)
		end
		return j
	end

	-- PILLAR: a column of fire `height` tall and `radius` round, standing on
	-- `base` for `dur` seconds, swirling as it climbs
	function BLAZE.pillar(base, height, radius, p, dur, opts)
		opts = opts or {}
		local P = Z.pal(p)
		local flames = {}
		-- the core: two tall flames standing in each other
		table.insert(flames, BLAZE.flame({ CF = CFrame.new(base), Pal = P, Height = height, Width = radius * 2.2, Tongues = 6, Volume = 2, Light = height * 1.2, Grow = opts.Grow or 0.12, Spin = 1.5 }))
		table.insert(flames, BLAZE.flame({ CF = CFrame.new(base), Pal = P, Height = height * 0.7, Width = radius * 2.6, Tongues = 7, Volume = 0, Heart = false, Light = 0, Grow = (opts.Grow or 0.12) * 1.5, Spin = -2 }))
		-- round the foot: shorter flames leaning out
		local ring = opts.Ring or 6
		for i = 1, ring do
			local a = i / ring * math.pi * 2
			local at = base + Vector3.new(math.cos(a), 0, math.sin(a)) * radius * 0.9
			local lean = CFrame.lookAt(at, at + Vector3.new(math.cos(a), 0, math.sin(a))) * CFrame.Angles(math.rad(-70), 0, 0)
			table.insert(flames, BLAZE.flame({ CF = lean, Pal = P, Height = height * 0.28, Width = radius * 0.5, Tongues = 2, Volume = 0.3, Smoke = false, Heart = false, Light = 0, Grow = 0.1 }))
		end
		if not opts.NoScorch then
			BLAZE.scorch(base, radius * 1.3, P)
		end
		task.delay(dur or 1.5, function()
			for _, f in flames do
				f.kill(opts.Fade or 0.5)
			end
		end)
		return flames
	end

	-- THREAD: a thin white-hot line of flame from a to b (Hell Spider): a
	-- white core, a glow round it, a haze round that, quivering; little
	-- flames licking up off it (opts.Licks = false: none). Returns a handle:
	-- th.set(a, b) moves it (a sweeping thread), th.kill(t) fades it now
	function BLAZE.thread(a, b, p, width, life, opts)
		local P = Z.pal(p)
		width = width or 0.3
		life = life or 0.5
		local th = { a = a, b = b }
		local h = Z.holder(CFrame.new(a))
		local a0 = Z.attach(h, CFrame.Angles(0, math.pi / 2, 0))
		local a1 = Z.attach(h, CFrame.Angles(0, math.pi / 2, 0))
		local core = Z.beam(h, a0, a1, ColorSequence.new(P.heart), NS(0), 1, 3, false, 3)
		core.Width0, core.Width1 = width * 0.45, width * 0.35
		local glow = Z.beam(h, a0, a1, ColorSequence.new(P.hot, P.body), NS({ NK(0, 0.1), NK(1, 0.3) }), 0.7, 2, true, 1.6)
		glow.Width0, glow.Width1 = width * 1.6, width * 1.3
		local halo = Z.beam(h, a0, a1, ColorSequence.new(P.body, P.edge), NS({ NK(0, 0.55), NK(1, 0.7) }), 0.5, 1, true, 1.2)
		halo.Width0, halo.Width1 = width * 4, width * 3
		local beams = { core, glow, halo }
		for _, bm in beams do
			bm.Segments = 16
			bm.TextureSpeed = -3
		end
		function th.set(na, nb)
			th.a, th.b = na, nb
			local v = nb - na
			if v.Magnitude < 0.05 then
				return
			end
			h.CFrame = CFrame.lookAt(na, nb)
			a1.CFrame = CFrame.new(0, 0, -v.Magnitude) * CFrame.Angles(0, math.pi / 2, 0)
		end
		th.set(a, b)
		function th.kill(t)
			if th.dead then
				return
			end
			th.dead = true
			for _, bm in beams do
				tween(bm, t or 0.2, { Width0 = 0, Width1 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
			cleanup(h, (t or 0.2) + 0.1)
		end
		task.spawn(function()
			local t0, s = os.clock(), rng:NextNumber(0, 100)
			while os.clock() - t0 < life and h.Parent and not th.dead do
				local now = os.clock()
				local c = (th.b - th.a).Magnitude * 0.05
				for i, bm in beams do
					bm.CurveSize0 = c * Z.noise(now * 8, s, i)
					bm.CurveSize1 = c * Z.noise(now * 8, s, i + 5)
				end
				task.wait()
			end
			th.kill(0.2)
		end)
		-- little flames licking up off it
		if not (opts and opts.Licks == false) then
			local v = b - a
			local n = math.clamp(math.floor(v.Magnitude / 5), 1, 8)
			for i = 1, n do
				local at = a + v * ((i - 0.5) / n)
				local f = BLAZE.flame({ CF = CFrame.new(at), Pal = P, Height = width * rng:NextNumber(5, 8), Width = width * 3, Tongues = 2, Volume = 0.25, Smoke = false, Heart = false, Light = 0, Grow = 0.05 })
				task.delay(life * 0.8, function()
					f.kill(0.3)
				end)
			end
		end
		return th
	end

	-- FIST: a giant fist made of fire (Vanishing Fist), at cf (looking the
	-- way it punches), `s` = how many times a real fist. Built from blocks
	-- of flame - knuckles, fingers curled into the palm, the thumb across -
	-- with a white-hot inside, all of it trailing tongues back up the arm
	function BLAZE.fist(cf, s, p, life)
		local P = Z.pal(p)
		local model, hl = outlineModel(P.tip)
		hl.OutlineTransparency = 0.3
		local fist = { model = model, parts = {}, cf = cf }
		local parts = fist.parts
		local function blob(size, off, color, t, shape)
			-- (the layout is for a fist 1 across: scale where each piece sits too)
			local o = CFrame.new(off.Position * s) * (off - off.Position)
			local q = shape and newPart(size * s, cf * o, color, Enum.Material.Neon, shape, model) or Z.egg(size * s, cf * o, color, model)
			q.Transparency = t
			q.Name = "BlazeFist"
			table.insert(parts, { q, size * s, o })
			return q
		end
		-- the back of the hand and the palm, white-hot inside
		local palm = blob(Vector3.new(1, 0.9, 0.8), CFrame.new(0, 0, 0.35), P.body, 0.15, Enum.PartType.Block)
		blob(Vector3.new(0.8, 0.7, 0.6), CFrame.new(0, 0, 0.35), P.heart, 0.05, Enum.PartType.Block)
		-- four fingers curled into it: the knuckle row in front, the second
		-- joints under it
		for i = 0, 3 do
			local x = (i - 1.5) * 0.25
			blob(Vector3.new(0.26, 0.3, 0.42), CFrame.new(x, 0.26, -0.18), P.hot, 0.1)
			blob(Vector3.new(0.26, 0.3, 0.38), CFrame.new(x, -0.04, -0.2), P.body, 0.12)
		end
		-- the thumb across the front
		blob(Vector3.new(0.52, 0.22, 0.28), CFrame.new(0.1, -0.32, -0.16) * CFrame.Angles(0, 0, math.rad(12)), P.hot, 0.1)
		-- the wrist
		blob(Vector3.new(0.9, 0.7, 0.7), CFrame.new(0, 0, 1.05) * CFrame.Angles(0, math.pi / 2, 0), P.edge, 0.3, Enum.PartType.Cylinder)
		-- flames streaming back off it (riding on the palm: they go where it goes)
		fist.flames = {}
		for _ = 1, 7 do
			local off = Vector3.new(rng:NextNumber(-0.5, 0.5), rng:NextNumber(-0.4, 0.45), rng:NextNumber(-0.2, 0.7)) * s
			local rel = CFrame.new(off) * CFrame.Angles(math.pi / 2, 0, 0) -- (burning back, out of the wrist)
			local palmRel = CFrame.new(0, 0, 0.35 * s):Inverse() * rel
			table.insert(fist.flames, BLAZE.flame({ Part = palm, Offset = palmRel, Pal = P, Height = s * rng:NextNumber(1, 1.7), Width = s * 0.42, Tongues = 2, Volume = 0.35, Smoke = false, Heart = false, Light = 0, Grow = 0.06 }))
		end
		local l = Instance.new("PointLight")
		l.Color = P.light
		l.Range = math.min(s * 8, 60)
		l.Brightness = 4
		l.Parent = palm
		for _, q in parts do
			q[1].Size = q[2] * 0.4
			tween(q[1], 0.1, { Size = q[2] }, Enum.EasingStyle.Back)
		end
		-- move it (every piece keeps its place in the fist)
		function fist.move(ncf)
			fist.cf = ncf
			for _, q in parts do
				q[1].CFrame = ncf * q[3]
			end
		end
		function fist.kill(t)
			if fist.dead then
				return
			end
			fist.dead = true
			t = t or 0.25
			for _, q in parts do
				tween(q[1], t, { Transparency = 1, Size = q[2] * 1.3 })
			end
			for _, f in fist.flames do
				f.kill(t + 0.05)
			end
			tween(l, t, { Brightness = 0 })
			cleanup(model, t + 0.1)
		end
		if life then
			task.delay(life, function()
				fist.kill(0.25)
			end)
		end
		return fist
	end

	-- RING / WALL: flames standing along a path of points
	function BLAZE.line(points, height, p, dur, opts)
		opts = opts or {}
		local flames = {}
		for _, at in points do
			table.insert(flames, BLAZE.flame({ CF = CFrame.new(at), Pal = p, Height = height * rng:NextNumber(0.75, 1.1), Width = opts.Width or height * 0.45, Volume = opts.Volume or 0.5, Light = opts.Light or 0, Grow = opts.Grow or 0.2, Smoke = opts.Smoke }))
		end
		if dur then
			task.delay(dur, function()
				for _, f in flames do
					f.kill(opts.Fade or 0.6)
				end
			end)
		end
		return flames
	end
	function BLAZE.ring(center, radius, height, p, dur, opts)
		local pts = {}
		local n = math.clamp(math.floor(radius * 2 * math.pi / ((opts and opts.Spacing) or 3.2)), 6, 40)
		for i = 1, n do
			local a = i / n * math.pi * 2
			table.insert(pts, groundPoint(center + Vector3.new(math.cos(a) * radius, 2, math.sin(a) * radius)))
		end
		return BLAZE.line(pts, height, p, dur, opts)
	end

	-- ON A BODY: flames riding on a character's part (Offset from it) till
	-- the returned stop is called
	function BLAZE.onPart(part, offset, height, p, opts)
		opts = opts or {}
		local f = BLAZE.flame({
			Part = part, Offset = offset or CFrame.new(), Pal = p, Height = height, Width = opts.Width or height * 0.55,
			Tongues = opts.Tongues, Volume = opts.Volume or 0.6, Smoke = opts.Smoke, Heart = opts.Heart or false,
			Light = opts.Light or 0, Grow = opts.Grow or 0.2, Soft = opts.Soft, Wind = opts.Wind,
		})
		return f
	end
end

---------------------------------------------------------------------------
-- BLOOD (Config.Blood; the player's own BLOOD setting). JJS-style: a hard
-- hit sprays drops out of the far side of whoever took it - each one flies,
-- stretched along its path, and splats where it lands (on the street, up a
-- wall); a KO leaves a pool spreading under the body. Deku's broken arms
-- drip. Everything fades after a while, and there's a cap on how much.
---------------------------------------------------------------------------
do
	local BLOOD = { drops = {}, stains = {}, on = true }
	VFX.BLOOD = BLOOD
	local cfg = Config.Blood or {}
	BLOOD.COLOR = cfg.Color or Color3.fromRGB(168, 10, 20)
	BLOOD.DARK = cfg.DarkColor or Color3.fromRGB(104, 6, 12)

	function BLOOD.enabled()
		return BLOOD.on ~= false and cfg.Enabled ~= false
	end

	-- a flat stain: a main blot and a few flecks round it (lying on `normal`)
	function BLOOD.splat(pos, normal, size, life)
		if not BLOOD.enabled() then
			return
		end
		normal = (typeof(normal) == "Vector3" and normal.Magnitude > 0.1) and normal.Unit or UP
		size = size or 1
		life = life or (cfg.StainLife or 9)
		local ref = math.abs(normal.Y) < 0.9 and UP or Vector3.new(1, 0, 0)
		local x = normal:Cross(ref).Unit
		local base = CFrame.fromMatrix(pos + normal * 0.04, normal, x)
		local parts = {}
		for i = 1, 1 + math.random(2, 4) do
			local s = i == 1 and size or size * rand(0.15, 0.4)
			local off = i == 1 and Vector3.zero or Vector3.new(0, rand(-1, 1), rand(-1, 1)).Unit * size * rand(0.55, 1.1)
			local p = newPart(Vector3.new(0.05, s, s * rand(0.7, 1.3)), base * CFrame.new(off) * CFrame.Angles(rand(0, 6.28), 0, 0), i == 1 and BLOOD.COLOR or BLOOD.DARK, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
			p.Name = "Blood"
			p.Reflectance = 0.08
			if i == 1 then
				p.Size = Vector3.new(0.05, s * 0.4, s * 0.4)
				tween(p, 0.12, { Size = Vector3.new(0.05, s, s) })
			end
			table.insert(parts, p)
			tween(p, 2, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, life)
			cleanup(p, life + 2.1)
		end
		table.insert(BLOOD.stains, parts)
		-- (a cap: the oldest go first)
		while #BLOOD.stains > (cfg.MaxStains or 90) do
			for _, p in table.remove(BLOOD.stains, 1) do
				p:Destroy()
			end
		end
	end

	-- a pool spreading under a body (KO), glossy, dark at the edge
	function BLOOD.pool(pos, size)
		if not BLOOD.enabled() then
			return
		end
		local hit = groundRay(pos + UP * 2, 12)
		if not hit then
			return
		end
		local at = hit.Position + UP * 0.05
		size = size or 5
		local life = cfg.PoolLife or 14
		for i, spec in { { 1, BLOOD.DARK, 0 }, { 0.8, BLOOD.COLOR, 0.02 } } do
			local p = newPart(Vector3.new(0.06, 0.4, 0.4), CFrame.new(at + UP * spec[3]) * CFrame.Angles(0, rand(0, 6), math.rad(90)), spec[2], Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
			p.Name = "Blood"
			p.Reflectance = i == 2 and 0.18 or 0.05
			tween(p, 1.8, { Size = Vector3.new(0.06, size * spec[1], size * spec[1] * rand(0.8, 1.1)) }, Enum.EasingStyle.Quad)
			tween(p, 2.5, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, life)
			cleanup(p, life + 2.6)
		end
	end

	-- drops in flight: one loop moves them all, gravity pulling, each one
	-- raycasting ahead - where it lands, it splats
	function BLOOD.drop(pos, vel, size)
		if not BLOOD.enabled() or #BLOOD.drops > (cfg.MaxDrops or 160) then
			return
		end
		local s = size or rand(0.14, 0.3)
		local p = newPart(Vector3.new(s, s, s), CFrame.new(pos), BLOOD.COLOR, Enum.Material.SmoothPlastic)
		p.Name = "Blood"
		p.Reflectance = 0.1
		local m = Instance.new("SpecialMesh")
		m.MeshType = Enum.MeshType.Sphere
		m.Parent = p
		table.insert(BLOOD.drops, { part = p, pos = pos, vel = vel, size = s, born = os.clock() })
	end
	RunService.Heartbeat:Connect(function(dt)
		local list = BLOOD.drops
		if #list == 0 then
			BLOOD.lastStep = nil
			return
		end
		-- (real time between updates: a slow frame doesn't slow them down)
		local now = os.clock()
		dt = math.clamp(math.max(tonumber(dt) or 0, now - (BLOOD.lastStep or now)), 1 / 240, 0.05)
		BLOOD.lastStep = now
		rayParams.FilterDescendantsInstances = characterList()
		local g = Vector3.new(0, -(cfg.Gravity or 110), 0)
		for i = #list, 1, -1 do
			local d = list[i]
			local nv = d.vel + g * dt
			local step = (d.vel + nv) * 0.5 * dt
			local hit = step.Magnitude > 1e-4 and workspace:Raycast(d.pos, step, rayParams)
			if hit or os.clock() - d.born > 2 or not d.part.Parent then
				if hit then
					BLOOD.splat(hit.Position, hit.Normal, d.size * rand(2.8, 4.6))
				end
				d.part:Destroy()
				table.remove(list, i)
			else
				d.pos += step
				d.vel = nv
				-- stretched along the way it's going
				local speed = nv.Magnitude
				local stretch = math.clamp(1 + speed / 40, 1, 3)
				d.part.Size = Vector3.new(d.size, d.size, d.size * stretch)
				d.part.CFrame = speed > 0.5 and CFrame.lookAt(d.pos, d.pos + nv) or CFrame.new(d.pos)
			end
		end
	end)

	-- a spray: count drops out of pos, round `dir` (spread 0..1), at `speed`
	function BLOOD.spray(pos, dir, count, speed, spread)
		if not BLOOD.enabled() then
			return
		end
		dir = (typeof(dir) == "Vector3" and dir.Magnitude > 0.05) and dir.Unit or UP
		for _ = 1, count do
			local v = (dir + rng:NextUnitVector() * (spread or 0.5) + UP * 0.35).Unit * (speed or 30) * rand(0.5, 1.15)
			BLOOD.drop(pos + rng:NextUnitVector() * 0.3, v)
		end
	end

	-- a drip off a point on a part: n drops, one after another
	function BLOOD.drip(part, pos, n)
		if not BLOOD.enabled() then
			return
		end
		local rel = part.CFrame:PointToObjectSpace(pos)
		task.spawn(function()
			for _ = 1, n or 1 do
				if not part.Parent then
					return
				end
				BLOOD.drop(part.CFrame:PointToWorldSpace(rel), Vector3.new(rand(-1, 1), -2, rand(-1, 1)), rand(0.12, 0.2))
				task.wait(rand(0.25, 0.6))
			end
		end)
	end

	-- a hit: out of the far side of them, away from whoever hit them - more
	-- (and faster) the harder it was
	function BLOOD.hit(target, attackerChar, amount, heavy)
		if not BLOOD.enabled() or not target then
			return
		end
		if (amount or 0) < (cfg.MinDamage or 9) and not heavy then
			return
		end
		local root = target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local ar = attackerChar and attackerChar:FindFirstChild("HumanoidRootPart")
		local d = ar and (root.Position - ar.Position) or root.CFrame.LookVector * -1
		d = Vector3.new(d.X, 0, d.Z)
		d = d.Magnitude > 0.05 and d.Unit or Vector3.new(0, 0, 1)
		local n = math.clamp(math.floor((amount or 0) / 3), 3, heavy and 18 or 10)
		BLOOD.spray(root.Position + UP * 0.8 + d * 0.8, d, n, heavy and 38 or 26, 0.55)
		if heavy then
			VFX.PlaySound("BloodSpray", root.Position, 0.8)
		end
	end
end

---------------------------------------------------------------------------
-- ENDEAVOR (Hellflame) and DABI (Blueflame), on BLAZE: Hell Spider's
-- white-hot threads, Jet Burn's torrent, the Vanishing Fist, Hell's
-- Curtain, Prominence Burn; Cremation, Hell Minefield, the blue Hell
-- Spider, the Blue Wall, Jet Burn - and Endeavor's costume of fire
---------------------------------------------------------------------------
do
	local B = VFX.BLAZE
	local HF = { out = setmetatable({}, { __mode = "k" }), dashes = setmetatable({}, { __mode = "k" }), spots = setmetatable({}, { __mode = "k" }), auras = setmetatable({}, { __mode = "k" }), fists = {} }
	VFX.HF = HF
	local WHITE = Color3.new(1, 1, 1)

	-- ENDEAVOR's poses: a boxer's power, and the fire does the rest
	POSES.SpiderWind = { RightArm = { 150, 0, 40 }, RightElbow = 20, LeftArm = { 30, 0, 25 }, LeftElbow = 40, Waist = { 6, 28, 0 }, Neck = { 4, -18, 0 }, RightLeg = -12, LeftLeg = 16, LeftKnee = 18 }
	POSES.SpiderSweep = { RightArm = { 55, 0, -45 }, RightElbow = 4, LeftArm = { -20, 0, 30 }, LeftElbow = 30, Waist = { -14, -32, 0 }, Neck = { -6, 22, 0 }, RightLeg = 22, RightKnee = 30, LeftLeg = -18, LeftKnee = 14, Crouch = 0.3 }
	POSES.WebWind = { RightArm = { 150, 0, 40 }, LeftArm = { 150, 0, 40 }, RightElbow = 20, LeftElbow = 20, Waist = { 10, 0, 0 }, Neck = { 10, 0, 0 }, RightLeg = -10, LeftLeg = 12 }
	POSES.WebSweep = { RightArm = { 50, 0, -40 }, LeftArm = { 50, 0, -40 }, RightElbow = 4, LeftElbow = 4, Waist = { -20, 0, 0 }, Neck = { -8, 0, 0 }, RightLeg = 24, RightKnee = 36, LeftLeg = -20, LeftKnee = 20, Crouch = 0.45 }
	POSES.JetWind = { RightArm = { -55, 0, 15 }, RightElbow = 100, LeftArm = { 80, 0, -20 }, LeftElbow = 35, Waist = { -8, 36, 0 }, Neck = { -4, -24, 0 }, RightLeg = -20, LeftLeg = 30, LeftKnee = 36, RightKnee = 10, Crouch = 0.35 }
	POSES.JetPunch = { RightArm = { 92, 0, -2 }, RightElbow = 0, LeftArm = { -30, 0, 22 }, LeftElbow = 40, Waist = { -12, -26, 0 }, Neck = { -4, 20, 0 }, RightLeg = -32, LeftLeg = 36, LeftKnee = 42, Crouch = 0.4 }
	POSES.VanishDash = { RightArm = { -55, 0, 20 }, RightElbow = 95, LeftArm = { 40, 0, 20 }, LeftElbow = 60, Waist = { -32, 10, 0 }, Neck = { 22, 0, 0 }, RightLeg = 40, RightKnee = 60, LeftLeg = -30, LeftKnee = 40 }
	POSES.VanishPunch = { RightArm = { 96, 0, -6 }, RightElbow = 0, LeftArm = { -40, 0, 25 }, LeftElbow = 50, Waist = { -20, -34, 0 }, Neck = { -2, 24, 0 }, RightLeg = -36, LeftLeg = 42, LeftKnee = 52, Crouch = 0.55 }
	POSES.CurtainGather = { RightArm = { -60, 0, 25 }, LeftArm = { -60, 0, 25 }, RightElbow = 80, LeftElbow = 80, Waist = { 12, 0, 0 }, Neck = { 6, 0, 0 }, RightLeg = 18, RightKnee = 30, LeftLeg = -12, Crouch = 0.3 }
	POSES.CurtainThrow = { RightArm = { 92, 0, 38 }, LeftArm = { 92, 0, 38 }, RightElbow = 0, LeftElbow = 0, Waist = { -22, 0, 0 }, Neck = { -6, 0, 0 }, LeftLeg = 32, LeftKnee = 36, RightLeg = -22, Crouch = 0.35 }
	POSES.FlyFist = { RightArm = { 170, 0, 6 }, RightElbow = 0, LeftArm = { -25, 0, 25 }, LeftElbow = 30, Waist = { -18, 0, 0 }, Neck = { 12, 0, 0 }, RightLeg = -12, LeftLeg = 20, LeftKnee = 50, RightKnee = 20 }
	POSES.NovaCharge = { RightArm = { 60, 0, -40 }, RightElbow = 125, LeftArm = { 60, 0, -40 }, LeftElbow = 125, Waist = { -24, 0, 0 }, Neck = { -18, 0, 0 }, RightLeg = 20, RightKnee = 40, LeftLeg = -14, LeftKnee = 30, Crouch = 0.65 }
	POSES.NovaRelease = { RightArm = { 110, 0, 82 }, LeftArm = { 110, 0, 82 }, RightElbow = 8, LeftElbow = 8, Waist = { 20, 0, 0 }, Neck = { 28, 0, 0 }, RightLeg = -16, LeftLeg = 16, RightKnee = 10, LeftKnee = 10 }
	POSES.NumberOne = { RightArm = { 178, 0, 8 }, RightElbow = 6, LeftArm = { 20, 0, 25 }, LeftElbow = 60, Waist = { 8, 0, 0 }, Neck = { 18, 0, 0 }, RightLeg = -8, LeftLeg = 10 }
	POSES.SkyHold = { RightArm = { 90, 0, 35 }, RightElbow = 70, LeftArm = { 90, 0, 35 }, LeftElbow = 70, Waist = { 6, 0, 0 }, Neck = { 10, 0, 0 }, RightLeg = -10, LeftLeg = 20, LeftKnee = 40 }
	POSES.Overheat = { RightArm = { 40, 0, 20 }, RightElbow = 60, LeftArm = { 40, 0, 20 }, LeftElbow = 60, Waist = { -32, 0, 0 }, Neck = { -12, 0, 0 }, RightKnee = 30, LeftKnee = 30, Crouch = 0.5 }
	POSES.KO_Hellflame = POSES.JetPunch

	MOTIONS.HellSpider = { { pose = "SpiderWind", t = 0.14, hold = 0.12 }, { pose = "SpiderSweep", t = 0.22, hold = 0.25 }, recover = 0.3 }
	MOTIONS.HellSpiderWeb = { { pose = "WebWind", t = 0.18, hold = 0.15 }, { pose = "WebSweep", t = 0.24, hold = 0.35 }, recover = 0.35 }
	MOTIONS.JetBurn = { { pose = "JetWind", t = 0.14, hold = 0.08 }, { pose = "JetPunch", t = 0.06, hold = 0.72, style = SNAP }, recover = 0.3 }
	MOTIONS.VanishPunch = { { pose = "VanishPunch", t = 0.05, hold = 0.45, style = SNAP }, recover = 0.35 }
	MOTIONS.HellsCurtain = { { pose = "CurtainGather", t = 0.2, hold = 0.14 }, { pose = "CurtainThrow", t = 0.07, hold = 0.45, style = SNAP }, recover = 0.35 }
	MOTIONS.FistThrow = { { pose = "JetWind", t = 0.22, hold = 0.18 }, { pose = "JetPunch", t = 0.06, hold = 0.4, style = SNAP }, recover = 0.35 }
