	-- where a hand is (the end of the arm), and five points across it
	function HF.handCF(char, right)
		local arm = limb(char, right and "RightHand" or "LeftHand", right and "Right Arm" or "Left Arm")
		if not arm then
			local root = char:FindFirstChild("HumanoidRootPart")
			return root and root.CFrame or CFrame.new()
		end
		return arm.CFrame * CFrame.new(0, -arm.Size.Y / 2, 0)
	end
	function HF.tips(char, right, n)
		local cf = HF.handCF(char, right)
		local out = {}
		for i = 1, n do
			local x = ((i - 0.5) / n - 0.5) * 0.8
			table.insert(out, (cf * CFrame.new(x, -0.12, -0.05)).Position)
		end
		return out
	end
	-- which way a move goes: along the street; in the air he can aim it
	-- down (Air: the server's same clamp)
	function HF.aim(data, root)
		local d = flatten(data.Dir, root)
		if data.Air and typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 then
			d = (d + UP * math.clamp(data.Dir.Unit.Y, -0.85, 0.35)).Unit
		end
		return d
	end
	-- a flame in someone's hand while a move winds up (returns its stop)
	function HF.handFlame(char, right, height, pal)
		local arm = limb(char, right and "RightHand" or "LeftHand", right and "Right Arm" or "Left Arm")
		if not arm then
			return function() end
		end
		local f = B.flame({ Part = arm, Offset = CFrame.new(0, -arm.Size.Y / 2, 0), Pal = pal, Height = height, Width = height * 0.55, Tongues = 3, Volume = 0.8, Light = 10, Grow = 0.1 })
		return function(t)
			f.kill(t or 0.2)
		end
	end
	-- a glowing seam cut into the street, cooling
	function HF.cut(a, b, pal)
		local P = B.pal(pal)
		local v = b - a
		if v.Magnitude < 0.3 then
			return
		end
		local seg = newPart(Vector3.new(0.2, 0.1, v.Magnitude + 0.15), CFrame.lookAt((a + b) / 2 + UP * 0.04, b + UP * 0.04), P.hot, Enum.Material.Neon)
		seg.Name = "BlazeCut"
		tween(seg, 1.8, { Color = P.tip, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.5)
		cleanup(seg, 2.4)
	end

	-- THE SWEEP (Hell Spider): n threads out of one hand's fingertips, swept
	-- from up and to that side down across the other (time seconds), each
	-- one reaching `range` or the street - and cutting a glowing seam where
	-- it crosses it. Blocks till it's done.
	function HF.sweep(char, root, d, range, spread, n, right, pal, time, width)
		local threads, last = {}, {}
		local side = right and 1 or -1
		local across = d:Cross(UP)
		across = across.Magnitude > 1e-3 and across.Unit or Vector3.new(1, 0, 0)
		rayParams.FilterDescendantsInstances = characterList()
		local t0 = os.clock()
		while root.Parent do
			local a = math.min((os.clock() - t0) / time, 1)
			local yaw = math.rad(spread / 2) * side * (1 - 2 * a)
			local pitch = math.rad(12 - 30 * a)
			for i, tip in HF.tips(char, right, n) do
				local fan = yaw + math.rad((i - (n + 1) / 2) * 3.5) * side
				local dir = CFrame.fromAxisAngle(UP, fan) * (CFrame.fromAxisAngle(across, pitch) * d)
				local hit = workspace:Raycast(tip, dir * range, rayParams)
				local to = hit and hit.Position or tip + dir * range
				local th = threads[i]
				if not th then
					threads[i] = B.thread(tip, to, pal, width or 0.3, time + 0.5, { Licks = false })
				else
					th.set(tip, to)
				end
				if hit then
					if last[i] then
						HF.cut(last[i], hit.Position, pal)
					end
					last[i] = hit.Position
				else
					last[i] = nil
				end
			end
			if a >= 1 then
				break
			end
			task.wait()
		end
		-- the lines they leave light up along their length, then go out
		for _, th in threads do
			local v = th.b - th.a
			for k = 1, 3 do
				local at = th.a + v * (k / 4)
				local f = B.flame({ CF = CFrame.new(at), Pal = pal, Height = 1.6, Width = 0.9, Tongues = 2, Volume = 0.2, Heart = false, Light = 0, Grow = 0.05 })
				task.delay(0.35, function()
					f.kill(0.3)
				end)
			end
			task.delay(0.12, function()
				th.kill(0.25)
			end)
		end
	end

	-- his fingertips going white-hot while he winds up (for `time`)
	function HF.tipGlow(char, right, n, time, pal)
		local P = B.pal(pal)
		local dots = {}
		for i = 1, n do
			local g = newPart(Vector3.one * 0.32, CFrame.new(), P.heart, Enum.Material.Neon, Enum.PartType.Ball)
			g.Name = "SpiderTip"
			dots[i] = g
		end
		local t0 = os.clock()
		while os.clock() - t0 < time do
			local k = (os.clock() - t0) / time
			for i, p in HF.tips(char, right, n) do
				dots[i].CFrame = CFrame.new(p)
				dots[i].Size = Vector3.one * (0.2 + 0.25 * k)
			end
			task.wait()
		end
		for _, g in dots do
			g:Destroy()
		end
	end

	-- 1: HELL SPIDER
	function Effects.HellSpider(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "HellSpider")
		VFX.PlaySound("HellSpiderCharge", root.Position, 1)
		HF.tipGlow(char, true, 5, 0.26, "white")
		if not root.Parent then
			return
		end
		VFX.PlaySound("HellSpider", root.Position, 1)
		HF.sweep(char, root, d, ability.Range or 42, ability.Spread or 40, ability.Threads or 5, true, "white", 0.22)
	end
	-- ult 1: HELL SPIDER: WEB - both hands, crossed
	function Effects.HellSpiderWeb(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "HellSpiderWeb")
		VFX.PlaySound("HellSpiderCharge", root.Position, 1.2)
		task.spawn(HF.tipGlow, char, false, 5, 0.33, "white")
		HF.tipGlow(char, true, 5, 0.33, "white")
		if not root.Parent then
			return
		end
		VFX.PlaySound("HellSpider", root.Position, 1.3)
		local n = math.max(math.floor((ability.Threads or 10) / 2), 1)
		task.spawn(HF.sweep, char, root, d, ability.Range or 60, ability.Spread or 56, n, false, "white", 0.24, 0.36)
		HF.sweep(char, root, d, ability.Range or 60, ability.Spread or 56, n, true, "white", 0.24, 0.36)
		-- and the whole net goes up
		if root.Parent then
			local across = d:Cross(UP)
			for k = 1, 7 do
				local at = groundPoint(root.Position + d * (ability.Range or 60) * rand(0.25, 0.85) + across * rand(-1, 1) * (ability.Range or 60) * 0.35)
				task.delay(k * 0.03, function()
					B.burst(at + UP * 1.5, rand(2.5, 4), { Pal = "hell", Tongues = 5, Smoke = false })
				end)
			end
			VFX.PlaySound("FireBlast", root.Position + d * 25, 1)
			VFX.ShakeAt(root.Position + d * 25, 1.5, 90, 0.35)
		end
	end

	-- 2: JET BURN - the fist, and a torrent of fire off it
	function Effects.JetBurn(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "JetBurn")
		VFX.PlaySound("JetBurnCharge", root.Position, 1)
		local stop = HF.handFlame(char, true, 1.4, "hell")
		task.wait(0.2)
		stop(0.05)
		if not root.Parent then
			return
		end
		VFX.PlaySound("JetBurn", root.Position, 1)
		local len = ability.Range or 60
		local j = B.jet({ From = HF.handCF(char, true).Position, Dir = d, Length = len, Width = ability.Width or 10, Pal = "hell" })
		if isLocal then
			dash(root, -flatten(d, root) * 10, 0.2) -- (the kick of it)
		end
		local dur, t0, nextMark = ability.Duration or 0.7, os.clock(), 0
		while os.clock() - t0 < dur and root.Parent do
			j.aim(HF.handCF(char, true).Position + d * 0.6, d)
			if os.clock() > nextMark then
				nextMark = os.clock() + 0.12
				local at = groundPoint(root.Position + d * rand(len * 0.3, len * 0.95))
				if (at - root.Position).Magnitude < len then
					B.scorch(at, rand(2, 3.4), "hell")
				end
			end
			task.wait()
		end
		j.stop(0.3)
		VFX.ShakeAt(root.Position, 1.2, 60, 0.3)
	end

	-- 3: VANISHING FIST, part 1: his fire goes out, and he's on them
	function Effects.VanishingFist(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		local time = (ability.Range or 34) / (ability.Speed or 150)
		HF.out[char] = os.clock() + time + 0.3
		smokeBurst(root.Position, Color3.fromRGB(70, 66, 66), 1.4, 2.5, 0.6, 7)
		VFX.PlaySound("FlameOut", root.Position, 1)
		VFX.Pose(char, "VanishDash", time + 0.15)
		if isLocal then
			face(root, d)
			HF.dashes[char] = dash(root, d * (ability.Speed or 150), time)
		end
		local stopTrail = addTrail(root, Color3.fromRGB(80, 70, 70), 0.25, 2.2)
		task.delay(time + 0.05, function()
			stopTrail(0)
		end)
	end
	-- part 2 (the server: it landed, or went off at the end of the dash):
	-- all of it comes back at once, in the fist
	function Effects.VanishingFistHit(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		if HF.dashes[char] then
			HF.dashes[char]()
			HF.dashes[char] = nil
		end
		HF.out[char] = nil
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or flatten(root.CFrame.LookVector, root)
		local at = typeof(data.At) == "Vector3" and data.At or root.Position + d * 4
		VFX.Motion(char, "VanishPunch")
		B.fist(CFrame.lookAt(at - d * 1.5, at + d), 5.5, "hell", 0.45)
		B.burst(at + d * 2.5, 6, { Pal = "hell", Tongues = 10 })
		for k = 1, 4 do
			task.delay(0.04 * k, function()
				B.burst(at + d * (3 + k * 3.5), 3 + k * 0.8, { Pal = "hell", Tongues = 4, NoScorch = k < 4, Smoke = k == 4 })
			end)
		end
		shockDisc(at, d, 3, 30, 0.35, B.PAL.hell.hot, 10)
		billboardRing(at, 2, 26, WHITE, 7, 0.3)
		sparks(at, 1.6, WHITE, B.PAL.hell.body, 24)
		if nearCamera(at, 70) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.14)
			VFX.ImpactFrame(0.07)
		end
		VFX.PlaySound("VanishingFist", at, 1)
		VFX.ShakeAt(at, 2.4, 110, 0.4)
	end

	-- R: FLASHFIRE JET - flying on the flames out of his feet
	function Effects.FlashfireJet(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or root.CFrame.LookVector
		local flat = flatten(d, root)
		d = (flat + UP * math.clamp(d.Y, -0.6, 0.75)).Unit
		local time = ability.Time or 0.5
		local speed = ability.Speed or 115
		if isLocal then
			face(root, flat)
			dash(root, d * speed, time)
			task.delay(time, function()
				if root.Parent then
					root.AssemblyLinearVelocity = d * speed * 0.35 -- (carries on a little)
				end
			end)
		end
		VFX.Pose(char, "FlyFist", time + 0.1)
		VFX.PlaySound("FlashfireJet", root.Position, 1)
		local jets = {}
		for _, names in { { "RightFoot", "Right Leg" }, { "LeftFoot", "Left Leg" } } do
			local leg = limb(char, names[1], names[2])
			if leg then
				table.insert(jets, B.flame({ Part = leg, Offset = CFrame.new(0, -leg.Size.Y / 2, 0) * CFrame.Angles(math.pi, 0, 0), Pal = "hell", Height = 4, Width = 1.1, Tongues = 3, Volume = 1, Light = 12, Grow = 0.05 }))
			end
		end
		local stopTrail = addTrail(root, B.PAL.hell.body, 0.35, 2.6)
		task.wait(time)
		for _, f in jets do
			f.kill(0.25)
		end
		stopTrail(0)
	end

	-- 4: HELL'S CURTAIN - everything on one point between his fists, then
	-- thrown: a sheet of fire rolls out across the street and the far edge
	-- of it stays up as a wall
	function Effects.HellsCurtain(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "HellsCurtain")
		VFX.PlaySound("CurtainCharge", root.Position, 1)
		local core = B.flame({ CF = CFrame.new(root.Position + d * 1.2 + UP * 0.6), Pal = "white", Height = 2.6, Width = 1.6, Volume = 1, Grow = 0.25, Light = 14 })
		task.wait(0.34)
		core.kill(0.1)
		if not root.Parent then
			return
		end
		VFX.PlaySound("HellsCurtain", root.Position, 1)
		local width, range = ability.Width or 38, ability.Range or 24
		local across = d:Cross(UP).Unit
		local origin = root.Position
		local rows = 5
		for r = 1, rows do
			local dist = range * r / rows
			local span = width * (0.3 + 0.7 * r / rows)
			local pts = {}
			for i = -2, 2 do
				table.insert(pts, groundPoint(origin + d * dist + across * (i / 2) * span / 2 + UP * 2))
			end
			local last = r == rows
			B.line(pts, last and 8 or 5 + r, "hell", last and (ability.Duration or 4) or 0.4, { Width = span / 4, Volume = last and 0.7 or 0.3, Grow = 0.08, Light = last and 18 or 0 })
			task.wait(0.045)
		end
		VFX.ShakeAt(origin + d * range, 1.4, 90, 0.35)
	end

	-- THE FIST FLIES (ult: Vanishing Jet Burn, and Dabi's thrown Vanishing
	-- Fist): a fist of fire the size of a house, From -> To in Time; the
	-- server's FlameFistBoom says where it went off
	function Effects.FlameFistFly(_char, data)
		local from, to = data.From, data.To
		if typeof(from) ~= "Vector3" or typeof(to) ~= "Vector3" then
			return
		end
		local pal = data.Pal == "blue" and "blue" or "hell"
		local d = (to - from).Magnitude > 0.1 and (to - from).Unit or Vector3.new(0, 0, -1)
		local fist = B.fist(CFrame.lookAt(from, from + d), data.Scale or 8, pal)
		HF.fists[data.Id or 0] = fist
		VFX.PlaySound("FistFly", from, 1)
		local time = math.max(tonumber(data.Time) or 0.4, 0.05)
		local t0 = os.clock()
		while not fist.dead do
			local a = math.min((os.clock() - t0) / time, 1)
			local p = from:Lerp(to, a)
			fist.move(CFrame.lookAt(p, p + d) * CFrame.Angles(0, 0, a * 3))
			if a >= 1 then
				break
			end
			task.wait()
		end
		task.delay(0.3, function()
			fist.kill(0.2)
			HF.fists[data.Id or 0] = nil
		end)
	end
	function Effects.FlameFistBoom(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local pal = data.Pal == "blue" and "blue" or "hell"
		local fist = HF.fists[data.Id or 0]
		if fist then
			fist.kill(0.1)
			HF.fists[data.Id or 0] = nil
		end
		local r = tonumber(data.Radius) or 16
		B.burst(pos, r * 0.55, { Pal = pal, Tongues = 14 })
		B.pillar(groundPoint(pos + UP * 2), r * 1.6, r * 0.3, pal, 1.2, { Ring = 8 })
		B.ring(groundPoint(pos + UP * 2), r * 0.7, 5, pal, 1.4, { Spacing = 4.5, Volume = 0.3 })
		shockDisc(pos, UP, 3, r * 3, 0.4, B.PAL[pal].hot)
		billboardRing(pos, 3, r * 2.2, WHITE, 8, 0.35)
		sparks(pos, 2, WHITE, B.PAL[pal].body, 30)
		if nearCamera(pos, 120) then
			VFX.Hooks.Flash(B.PAL[pal].heart, 0.2)
		end
		VFX.PlaySound("FistBoom", pos, 1)
		VFX.ShakeAt(pos, 3, 180, 0.5)
	end
