	-- ult 3: PROMINENCE BURN - it builds in him (white-hot, the street
	-- glowing under him) and then everything comes out of his whole body
	function Effects.ProminenceNova(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		cinematicFor(char, "ProminenceNova", isLocal, (ability and ability.Name) or "PROMINENCE BURN", B.PAL.white.body)
		VFX.Motion(char, "ProminenceNova")
		VFX.PlaySound("ProminenceCharge", root.Position, 1)
		local glow = Instance.new("Highlight")
		glow.FillColor = B.PAL.white.hot
		glow.OutlineColor = WHITE
		glow.FillTransparency = 0.8
		glow.DepthMode = Enum.HighlightDepthMode.Occluded
		glow.Parent = char
		tween(glow, 0.7, { FillTransparency = 0.15 })
		local g = groundPoint(root.Position)
		local disc = newPart(Vector3.new(0.15, 2, 2), CFrame.new(g + UP * 0.06) * CFrame.Angles(0, 0, math.rad(90)), B.PAL.hell.body, Enum.Material.Neon, Enum.PartType.Cylinder)
		disc.Transparency = 0.2
		tween(disc, 0.7, { Size = Vector3.new(0.15, (ability and ability.Radius or 34) * 0.5, (ability and ability.Radius or 34) * 0.5), Color = B.PAL.white.heart })
		B.ring(g, 3.5, 5, "white", 0.75, { Spacing = 2.2, Volume = 0.6, Grow = 0.15 })
		VFX.ShakeAt(root.Position, 0.8, 80, 0.7)
		task.wait(0.7)
		tween(glow, 0.8, { FillTransparency = 1, OutlineTransparency = 1 })
		cleanup(glow, 0.85)
		tween(disc, 0.6, { Transparency = 1 })
		cleanup(disc, 0.65)
	end
	function Effects.ProminenceNovaBurst(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local r = tonumber(data.Radius) or 34
		local g = groundPoint(pos)
		-- so hot the world goes black and white: white fire inked in black
		local pal = HF.mono(pos, 1.1) and "mono" or "white"
		B.burst(pos + UP * 2, r * 0.45, { Pal = pal, Tongues = 16 })
		B.pillar(g, 80, 10, pal, 2.2, { Ring = 10, Grow = 0.1 })
		B.ring(g, r * 0.75, 7, pal == "mono" and "mono" or "hell", 2, { Spacing = 5, Volume = 0.4 })
		for k = 1, 3 do
			task.delay(k * 0.07, function()
				shockDisc(pos, UP, 4, r * 2.4 + k * 12, 0.45, k == 1 and WHITE or B.PAL.hell.hot)
				billboardRing(pos, 4, r * 2 + k * 10, k == 2 and B.PAL.hell.body or WHITE, 9, 0.4)
			end)
		end
		B.scorch(g, r * 0.7, "hell")
		if nearCamera(pos, 160) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 246, 220), 0.3)
			VFX.ImpactFrame(0.1)
		end
		VFX.PlaySound("Prominence", pos, 1.3)
		VFX.ShakeAt(pos, 3.5, 260, 0.7)
	end

