	-- his awakening: the column, and the No. 1 pose
	QUIRK_FX.Ult.Hellflame = function(char, root, g)
		VFX.Motion(char, "EndeavorUlt")
		B.pillar(g, 46, 6, "hell", 1.3, { Ring = 8 })
		B.burst(root.Position + UP * 2, 5, { Pal = "white", Tongues = 10, NoScorch = true })
		billboardRing(root.Position + UP, 3, 34, B.PAL.hell.body, 8, 0.4)
		HF.aura(char, "hell")
	end
	-- a dash on the flames out of his feet
	QUIRK_FX.Dash.Hellflame = function(char, _root, dir)
		for _, names in { { "RightFoot", "Right Leg" }, { "LeftFoot", "Left Leg" } } do
			local leg = limb(char, names[1], names[2])
			if leg then
				local f = B.flame({ Part = leg, Offset = CFrame.new(0, -leg.Size.Y / 2, 0) * CFrame.Angles(math.pi, 0, 0), Pal = "hell", Height = 2.6, Width = 0.9, Tongues = 2, Volume = 0.5, Light = 0, Grow = 0.04, Wind = -dir * 40 })
				task.delay(0.3, function()
					f.kill(0.2)
				end)
			end
		end
		legTrails(char, 0.25, B.PAL.hell.body)
	end
	-- his M1s: every punch flares; the 4th throws fire
	function VFX.HellflamePunch(char, count, finisher, fist, look)
		B.burst(fist + look * 0.6, finisher and 2.4 or 1.1, { Pal = char:GetAttribute("UltActive") and "white" or "hell", Tongues = finisher and 6 or 3, NoScorch = true, Smoke = false })
		if finisher or count == 4 then
			B.jet({ From = fist, Dir = look, Length = 14, Width = 4, Pal = "hell", Life = 0.22, Fade = 0.15, Rolls = 2 })
		end
		VFX.PlaySound(finisher and "FireBlast" or "FirePunch", fist, finisher and 1 or 0.6)
	end
	-- the finisher: the fist in their gut, and Jet Burn through them
	function HF.finisher(char, _target, troot, d, time)
		VFX.Motion(char, "JetBurn")
		task.wait(time * 0.3)
		if not troot.Parent then
			return
		end
		local j = B.jet({ From = HF.handCF(char, true).Position, Dir = d, Length = 30, Width = 7, Pal = "hell", Rolls = 3 })
		task.wait(time * 0.45)
		j.stop(0.25)
		if troot.Parent then
			B.burst(troot.Position, 4, { Pal = "white", Tongues = 8 })
			VFX.PlaySound("FireBlast", troot.Position, 1)
		end
	end
	function HF.burst(pos, _dir)
		B.pillar(groundPoint(pos + UP * 2), 30, 5, "hell", 1.2)
		B.burst(pos, 5, { Pal = "white", Tongues = 10 })
	end

	-- an ult's fire all over him (Endeavor: flames off his arms and back;
	-- Dabi: burning everywhere) while it's up
	function HF.aura(char, pal)
		if HF.auras[char] then
			return
		end
		local flames = {}
		HF.auras[char] = flames
		for _, spec in {
			{ "UpperTorso", "Torso", CFrame.new(0, 0.2, 0.3), 3.2, 1.6 },
			{ "RightUpperArm", "Right Arm", CFrame.new(0, 0, 0), 2.2, 0.9 },
			{ "LeftUpperArm", "Left Arm", CFrame.new(0, 0, 0), 2.2, 0.9 },
			{ "RightUpperLeg", "Right Leg", CFrame.new(0, 0, 0), 1.8, 0.8 },
			{ "LeftUpperLeg", "Left Leg", CFrame.new(0, 0, 0), 1.8, 0.8 },
		} do
			local part = limb(char, spec[1], spec[2])
			if part then
				table.insert(flames, B.flame({ Part = part, Offset = spec[3], Pal = pal, Height = spec[4], Width = spec[5], Tongues = 3, Volume = 0.6, Heart = false, Light = spec[1] == "UpperTorso" and 14 or 0, Grow = 0.4, Soft = true }))
			end
		end
		task.spawn(function()
			while char.Parent and char:GetAttribute("UltActive") do
				task.wait(0.3)
			end
			for _, f in flames do
				f.kill(0.5)
			end
			HF.auras[char] = nil
		end)
	end

	-- THE COSTUME OF FIRE: every FireSpot on anyone's look (Endeavor's
	-- beard, brows, shoulders, boots) is lit while they're near enough to
	-- see - out while his flames are out (Vanishing Fist) or you've hidden
	-- cosmetics - and burns higher in his ult
	task.spawn(function()
		while true do
			task.wait(0.35)
			local cam = workspace.CurrentCamera
			local camPos = cam and cam.CFrame.Position
			local seen = {}
			for _, plr in Players:GetPlayers() do
				local ch = plr.Character
				local gear = ch and ch:FindFirstChild("QuirkGear")
				local cos = gear and gear:FindFirstChild("Cosmetics")
				local root = ch and ch:FindFirstChild("HumanoidRootPart")
				if cos and root then
					local near = camPos == nil or (root.Position - camPos).Magnitude < 200
					local out = (HF.out[ch] or 0) > os.clock()
					local lvl = ch:GetAttribute("UltActive") and 1.45 or 1
					for _, a in cos:GetDescendants() do
						if a:IsA("Attachment") and a.Name == "FireSpot" then
							seen[a] = true
							local holder = a.Parent
							local okL, ltm = pcall(function()
								return holder.LocalTransparencyModifier
							end)
							local hidden = okL and type(ltm) == "number" and ltm > 0.5
							local want = near and not out and not hidden
							local f = HF.spots[a]
							if want and not f and holder then
								f = B.flame({
									Part = holder, Offset = a.CFrame, Pal = a:GetAttribute("Pal") or "hell",
									Height = a:GetAttribute("Height") or 1, Width = a:GetAttribute("Width") or 0.5,
									Tongues = a:GetAttribute("Tongues") or 2, Volume = 0.3, Heart = false, Light = 0, Grow = 0.2, Soft = true,
								})
								HF.spots[a] = f
							elseif f and not want then
								f.kill(0.12)
								HF.spots[a] = nil
								f = nil
							end
							if f then
								f.level(lvl)
							end
						end
					end
				end
			end
			for a, f in HF.spots do
				if not seen[a] then
					f.kill(0.2)
					HF.spots[a] = nil
				end
			end
		end
	end)

	-------------------------------------------------------------------------
	-- DABI
	-------------------------------------------------------------------------

	-- 1: CREMATION - a wave of blue fire off his palm
	function Effects.Cremation(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "Cremation")
		local stop = HF.handFlame(char, false, 1.2, "blue")
		task.wait(0.16)
		stop(0.05)
		if not root.Parent then
			return
		end
		VFX.PlaySound("Cremation", root.Position, 1)
		local j = B.jet({ From = HF.handCF(char, false).Position, Dir = d, Length = ability.Range or 40, Width = ability.Width or 12, Pal = "blue", Rolls = 6 })
		local t0 = os.clock()
		while os.clock() - t0 < 0.6 and root.Parent do
			j.aim(HF.handCF(char, false).Position + d * 0.6, d)
			task.wait()
		end
		j.stop(0.3)
	end
	-- the street where it went stays alight (the server says where)
	function Effects.CremationPatches(_char, data)
		for _, p in typeof(data.Points) == "table" and data.Points or {} do
			if typeof(p) == "Vector3" then
				local f = B.flame({ CF = CFrame.new(p), Pal = "blue", Height = rand(3, 4.5), Width = (tonumber(data.Radius) or 4) * 0.9, Tongues = 4, Volume = 0.6, Light = 10, Grow = 0.3 })
				B.scorch(p, (tonumber(data.Radius) or 4) * 0.9, "blue")
				task.delay(tonumber(data.Life) or 5, function()
					f.kill(0.6)
				end)
			end
		end
	end

	-- 2: HELL MINEFIELD - a hand on the street; the fire runs under it
	function Effects.HellMinefield(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "HellMinefield")
		VFX.PlaySound("Minefield", root.Position, 1)
		local P = B.PAL.blue
		-- where his palm is: a glow, and cracks running out ahead of him
		local g = groundPoint(root.Position + d * 2)
		local palm = newPart(Vector3.new(0.12, 4, 4), CFrame.new(g + UP * 0.06) * CFrame.Angles(0, 0, math.rad(90)), P.body, Enum.Material.Neon, Enum.PartType.Cylinder)
		palm.Transparency = 0.3
		tween(palm, 0.8, { Transparency = 1, Size = Vector3.new(0.12, 8, 8) })
		cleanup(palm, 0.85)
		local range = ability.Range or 46
		local target = typeof(data.Pos) == "Vector3" and data.Pos or root.Position + d * range
		local v = Vector3.new(target.X - g.X, 0, target.Z - g.Z)
		if v.Magnitude > range then
			v = v.Unit * range
		end
		for k = 1, 3 do
			local wob = d:Cross(UP) * (k - 2) * 1.2
			local prev = g
			for s = 1, 8 do
				local p = groundPoint(g + v * (s / 8) + wob * math.sin(s) + Vector3.new(rand(-0.6, 0.6), 2, rand(-0.6, 0.6)))
				task.delay(s * 0.04, function()
					HF.cut(prev, p, "blue")
					prev = p
				end)
			end
		end
	end
	-- each pillar, as it erupts
	function Effects.MinefieldErupt(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local r = tonumber(data.Radius) or 6.5
		B.pillar(pos, r * 3.4, r * 0.7, "blue", 0.85, { Ring = 5, Grow = 0.06 })
		rocks(pos, 1, 6)
		shockDisc(pos + UP * 0.5, UP, 2, r * 3, 0.3, B.PAL.blue.hot)
		VFX.PlaySound("MinefieldErupt", pos, 1)
		VFX.ShakeAt(pos, 1.2, 60, 0.25)
	end

	-- 3: HELL SPIDER (Dabi's): roaring streams, not threads
	function Effects.BlueSpider(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = HF.aim(data, root)
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "BlueSpider")
		task.wait(0.12)
		if not root.Parent then
			return
		end
		VFX.PlaySound("BlueSpider", root.Position, 1)
		local n = ability.Streams or 5
		local spread = math.rad(ability.Spread or 30)
		local jets = {}
		for i = 1, n do
			local a = (i - (n + 1) / 2) / math.max(n - 1, 1) * spread
			local dir = CFrame.fromAxisAngle(UP, a) * d
			jets[i] = { j = B.jet({ From = root.Position, Dir = dir, Length = ability.Range or 46, Width = 3, Pal = "blue", Rolls = 2 }), dir = dir }
		end
		local t0 = os.clock()
		while os.clock() - t0 < 0.55 and root.Parent do
			local tips = HF.tips(char, true, n)
			for i, s in jets do
				s.j.aim(tips[i] or root.Position, s.dir)
			end
			task.wait()
		end
		for _, s in jets do
			s.j.stop(0.25)
		end
	end

