		recoil = { armR = { 40, -30, 10, 90 }, armL = { 40, -30, 10, 80 }, legR = { -10, 0, 6, 20 }, legL = { 20, 0, 6, 30 }, head = { -14, 0 }, lean = -16, drop = 0.4 },
		shout = { armR = { 20, 0, 30, 40 }, armL = { 20, 0, 30, 40 }, legR = { -18, 0, 10, 16 }, legL = { 24, 0, 10, 26 }, head = { 16, 0 }, lean = 6, drop = 0.3 },
		windup = { armR = { -50, 0, 26, 70 }, armL = { 70, -10, 10, 30 }, legL = { 34, 0, 8, 60 }, legR = { -26, 0, 8, 24 }, head = { 0, -20 }, lean = -16, twist = 34, drop = 0.9 },
