	---------------------------------------------------------------- moving them
	local function ease(a, now)
		local k = math.clamp((now - a.t0) / a.dur, 0, 1)
		if a.ease == "out" then
			return 1 - (1 - k) ^ 3
		elseif a.ease == "in" then
			return k * k * k
		end
		return k * k * (3 - 2 * k)
	end
	function MEM.actor(pp, cf, pose)
		return { pp = pp, from = pose, to = pose, cfFrom = cf, cfTo = cf, t0 = 0, dur = 1, phase = math.random() * 6 }
	end
	function MEM.poseAt(a, now)
		local k = ease(a, now)
		local pose = PUP.blend(a.from, a.to, k)
		pose.drop = (a.from.drop or 0) + ((a.to.drop or 0) - (a.from.drop or 0)) * k
		return pose
	end
	function MEM.cfAt(a, now)
		return a.cfFrom:Lerp(a.cfTo, ease(a, now))
	end
	-- to a pose (and somewhere else) over dur seconds
	function MEM.to(a, pose, dur, cf, style)
		local now = os.clock()
		a.from, a.cfFrom = MEM.poseAt(a, now), MEM.cfAt(a, now)
		a.to, a.cfTo = pose, cf or a.cfTo
		a.t0, a.dur, a.ease = now, math.max(dur or 0.2, 0.01), style
		a.arc = nil
	end
	function MEM.draw(a, now)
		local pose, cf = MEM.poseAt(a, now), MEM.cfAt(a, now)
		if a.arc then
			local k = math.clamp((now - a.arc.t0) / a.arc.dur, 0, 1)
			cf = a.arc.from:Lerp(a.arc.to, k) + UP * a.arc.height * 4 * k * (1 - k)
			pose = k < 1 and MEM.P.flung or MEM.P.down
			if k >= 1 and not a.arc.landed then
				a.arc.landed = true
				dustPuffs(cf.Position, 1.6, 8, Color3.fromRGB(222, 206, 170), 1.2, true)
				VFX.PlaySound("MemoryThud", cf.Position, 1)
			end
		end
		local breath = a.arc and 0 or math.sin(now * 2.4 + a.phase) * 0.05
		PUP.place(a.pp, cf * CFrame.new(0, (3.05 - (pose.drop or 0) / SCALE) * SCALE + breath, 0), pose)
	end
	-- flung out of bounds (side: which way, along the stage's X)
	function MEM.fling(f, a, side)
		local now = os.clock()
		local from = MEM.cfAt(a, now)
		local to = f.S * CFrame.new(side * rand(42, 48), -3.2, rand(-6, 6)) * from.Rotation
		MEM.to(a, MEM.P.flung, 0.1)
		a.arc = { from = from, to = CFrame.new(to.Position) * from.Rotation, t0 = now, dur = 1.1, height = 9 }
	end

	---------------------------------------------------------------- the stadium, full
	-- a crowd in the stands (the empty bowl you walked into, as it was that day)
	function MEM.crowd(f)
		local S = CFrame.new(ARENA)
		local shirts = { Color3.fromRGB(214, 60, 60), Color3.fromRGB(60, 110, 210), Color3.fromRGB(240, 200, 60), Color3.fromRGB(80, 170, 100),
			Color3.fromRGB(240, 240, 240), Color3.fromRGB(40, 40, 50), Color3.fromRGB(230, 120, 170), Color3.fromRGB(250, 150, 60) }
		f.fans = {}
		for _ = 1, 150 do
			local a = rand(math.rad(14), math.rad(346))
			local i = rng:NextInteger(0, 9)
			local base = S * CFrame.Angles(0, a, 0) * CFrame.new(rand(-2, 2), 9 + i * 3.3, 106 + i * 6 + rand(-1.5, 1.5))
			local body = newPart(V(1.3, 1.8, 0.9), base * CFrame.new(0, 0.9, 0), shirts[rng:NextInteger(1, #shirts)], nil, nil, f.model)
			local head = newPart(V(0.9, 0.9, 0.9), base * CFrame.new(0, 2.25, 0), Color3.fromRGB(rng:NextInteger(200, 245), rng:NextInteger(160, 205), rng:NextInteger(130, 175)), nil, Enum.PartType.Ball, f.model)
			table.insert(f.fans, { body, base * CFrame.new(0, 0.9, 0), rand(0, 6) })
			table.insert(f.fans, { head, base * CFrame.new(0, 2.25, 0), 0 })
			f.fans[#f.fans][3] = f.fans[#f.fans - 1][3]
		end
	end
	function MEM.cheer(f, time)
		f.cheerUntil = os.clock() + (time or 2.5)
		VFX.PlaySound("MemoryCrowd", ARENA + UP * 30, 1)
	end

	-- Todoroki's ice: a glacier rushing across the stage (from, to: stage
	-- space) - it grows spike by spike
	function MEM.ice(f, from, to, height, width, time)
		local wave = Instance.new("Model")
		wave.Name = "Glacier"
		wave.Parent = f.model
		local S = f.S
		local a, b = S:PointToWorldSpace(from), S:PointToWorldSpace(to)
		local dir = (b - a).Unit
		local side = dir:Cross(UP).Unit
		local sheet = newPart(V(width * 0.9, 0.3, 0.1), CFrame.lookAt(a, b), ICE_MID, Enum.Material.Ice, nil, wave)
		sheet.Transparency = 0.15
		tween(sheet, time, { Size = V(width * 0.9, 0.3, (b - a).Magnitude), CFrame = CFrame.lookAt((a + b) / 2 + UP * 0.1, b + UP * 0.1) }, Enum.EasingStyle.Linear)
		local n = 10
		for i = 1, n do
			local at = a:Lerp(b, i / n) + side * rand(-width, width) * 0.4
			local tall = height * (0.45 + 0.55 * math.sin(i / n * math.pi * 0.8 + 0.3))
			local grow = makeSpike(wave, at, dir * rand(0.5, 0.9) + UP, tall, tall * 0.34, false)
			table.insert(f.grow, { set = grow, t0 = os.clock() + time * (i - 1) / n, dur = 0.16 })
		end
		task.delay(time * 0.5, iceFog, (a + b) / 2, width + 4, 1.4)
		VFX.PlaySound("MemoryIce", a, 1.1)
		VFX.ShakeAt(b, 1.2, 200, 0.4)
		return wave
	end
	-- smashed apart: every piece of it flung away from `from`
	function MEM.shatter(f, wave, from)
		if not wave or not wave.Parent then
			return
		end
		for _, p in wave:GetDescendants() do
			if p:IsA("BasePart") and p.Size.Magnitude > 0.4 then
				local away = (p.Position - from)
				away = V(away.X, 0, away.Z).Magnitude > 0.1 and V(away.X, 0, away.Z).Unit or V(0, 0, 1)
				for _ = 1, 2 do
					local s = math.clamp(p.Size.Magnitude * rand(0.12, 0.22), 0.4, 3)
					local chunk = newPart(V(s, s * rand(0.5, 1), s), p.CFrame * CFrame.Angles(rand(0, 3), rand(0, 3), rand(0, 3)), ICE_MID, Enum.Material.Ice, nil, f.model)
					chunk.Transparency = 0.1
					local fly = p.Position + away * rand(14, 34) + UP * rand(4, 16)
					tween(chunk, 0.6, { CFrame = CFrame.new(fly) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					tween(chunk, 0.5, { Transparency = 1 }, nil, nil, 0.5)
					cleanup(chunk, 1.1)
				end
			end
		end
		iceSparkles(from, 10, 0.8)
		wave:Destroy()
	end
	-- a flick of one finger: the air it throws smashes whatever's in front
	function MEM.flick(f, hand, finger)
		local tip = PUP.tip(f.deku.pp, hand)
		local dir = (f.S.RightVector * -1)
		shockDisc(tip, dir, 1.5, 16, 0.3, WIND, 22)
		shockDisc(tip + dir * 6, dir, 3, 26, 0.4, WIND, 26)
		streaks(tip, dir, 10, 1.4, 8, 42, WIND, 0.3)
		billboardRing(tip + dir * 3, 2, 22, WIND, 5, 0.3)
		VFX.PlaySound("MemoryShatter", tip, 1.1)
		VFX.ShakeAt(tip, 2.4, 200, 0.45)
		local fingers = f.deku.pp.fingers[hand]
		local p = fingers and fingers[finger]
		if p then
			p.Color = BRUISE
			sparks(p.Position, 0.5, Color3.new(1, 1, 1), BRUISE, 6)
		end
		for _, w in f.waves do
			MEM.shatter(f, w, tip)
		end
		f.waves = {}
	end
	-- frost creeping over his right side (on = there, false = melting off)
	function MEM.frost(f, on)
		local pp = f.todo.pp
		if on and not f.frost then
			f.frost = {}
			for _, spec in {
				{ "armR", V(1.05, 0.7, 1.05), CFrame.new(0, -0.3, 0) }, { "foreR", V(0.98, 0.5, 0.98), CFrame.new(0, -0.35, 0) },
				{ "torso", V(0.9, 1.2, 1.12), CFrame.new(0.66, 0.35, 0) }, { "head", V(0.4, 0.5, 1.06), CFrame.new(0.38, 0.62, 0) },
				{ "legR", V(1.02, 0.5, 1.02), CFrame.new(0, -0.3, 0) },
			} do
				local p = PUP.part(pp, spec[1], spec[2], spec[3], ICE_TOP, Enum.Material.Ice)
				p.Transparency = 1
				tween(p, 1.2, { Transparency = 0.3 })
				table.insert(f.frost, p)
			end
		elseif not on and f.frost then
			for _, p in f.frost do
				tween(p, 0.8, { Transparency = 1 })
				dustPuffs(p.Position, 0.6, 2, STEAM, 1.2, false)
			end
		end
	end
	-- Cementoss's walls: up out of the stage between them
	function MEM.walls(f)
		f.wallParts = {}
		for i, x in { -6, 0, 6 } do
			local at = f.S * CFrame.new(x, 0, 0)
			local w = newPart(V(2.4, 12, 18), at * CFrame.new(0, -6.2, 0), Color3.fromRGB(170, 170, 168), Enum.Material.Concrete, nil, f.model)
			tween(w, 0.35, { CFrame = at * CFrame.new(0, 6, 0) }, Enum.EasingStyle.Back, Enum.EasingDirection.Out, (i - 1) * 0.08)
			table.insert(f.wallParts, w)
		end
		dustPuffs(f.S.Position, 2, 10, Color3.fromRGB(200, 196, 190), 1.2, true)
		VFX.PlaySound("MemoryWalls", f.S.Position, 1.2)
		VFX.ShakeAt(f.S.Position, 1.6, 200, 0.5)
	end
	function MEM.breakWalls(f)
		for _, w in f.wallParts or {} do
			for _ = 1, 8 do
				local s = rand(1.2, 3)
				local chunk = newPart(V(s, s * rand(0.5, 1), s), w.CFrame * CFrame.new(rand(-1, 1), rand(-5, 5), rand(-8, 8)), w.Color, Enum.Material.Concrete, nil, f.model)
				local fly = chunk.Position + V(rand(-1, 1), 0, rand(-1, 1)).Unit * rand(10, 30) + UP * rand(8, 22)
				tween(chunk, 0.7, { CFrame = CFrame.new(fly) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				tween(chunk, 0.4, { Transparency = 1 }, nil, nil, 0.7)
				cleanup(chunk, 1.2)
			end
			w:Destroy()
		end
		f.wallParts = {}
		rocks(f.S.Position, 1.6, 12)
	end
	-- the end of it: the stage goes up in a cloud of steam
	function MEM.steam(f, at)
		toonExplosion(at, 4)
		shockDisc(at, UP, 6, 140, 0.7, WIND, 0)
		billboardRing(at, 8, 160, Color3.new(1, 1, 1), 12, 0.6)
		for _ = 1, 30 do
			local off = V(rand(-1, 1), rand(0, 0.6), rand(-1, 1)) * rand(4, 30)
			local puff = newPart(Vector3.one * rand(4, 8), CFrame.new(at + off), STEAM, nil, Enum.PartType.Ball, f.model)
			puff.Transparency = 0.1
			local big = rand(18, 34)
			tween(puff, rand(1.4, 2.4), { Size = Vector3.one * big, CFrame = CFrame.new(at + off * 2.2 + UP * rand(6, 20)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(puff, 2.5, { Transparency = 1 }, nil, nil, rand(2.5, 4))
			cleanup(puff, 7)
		end
		VFX.PlaySound("MemoryBlast", at, 1.3)
		VFX.Shake(4, 1.2)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.5)
	end

	---------------------------------------------------------------- the camera
	-- shots: { T, From = { pos, look }, To = { pos, look }, Fov = { a, b } } in
	-- the stage's space
	function MEM.camera(f, shots)
		local cam = workspace.CurrentCamera
		if not cam then
			return
		end
		f.shots, f.camT0 = shots, os.clock()
		f.camSaved = f.camSaved or { Fov = cam.FieldOfView }
		cam.CameraType = Enum.CameraType.Scriptable
		RunService:UnbindFromRenderStep("QuirkMemory")
		RunService:BindToRenderStep("QuirkMemory", Enum.RenderPriority.Camera.Value, function()
			if f.gone or not f.shots then
				return
			end
			local e = os.clock() - f.camT0
			local list, i = f.shots, 1
			while list[i + 1] and e >= list[i].T do
				e -= list[i].T
				i += 1
			end
			local shot = list[i]
			local k = math.clamp(e / shot.T, 0, 1)
			k = k * k * (3 - 2 * k)
			local to = shot.To or shot.From
			local S = f.S
			local pos = S:PointToWorldSpace(shot.From[1]):Lerp(S:PointToWorldSpace(to[1]), k)
			local look = S:PointToWorldSpace(shot.From[2]):Lerp(S:PointToWorldSpace(to[2]), k)
			cam.CFrame = CFrame.lookAt(pos, look)
			if shot.Fov then
				cam.FieldOfView = shot.Fov[1] + ((shot.Fov[2] or shot.Fov[1]) - shot.Fov[1]) * k
			end
		end)
	end
	function MEM.cameraOff()
		RunService:UnbindFromRenderStep("QuirkMemory")
	end
	MEM.OPEN = {
		{ T = 3.2, From = { V(0, 46, -150), V(0, 4, 0) }, To = { V(0, 20, -74), V(0, 4, 0) }, Fov = { 60, 52 } },
		{ T = 2.2, From = { V(27, 6.5, 6), V(-16, 4, 0) }, To = { V(24, 6, 4), V(-14, 4, 0) }, Fov = { 58, 58 } },
		{ T = 2.4, From = { V(0, 6, -40), V(0, 4, 0) }, To = { V(-6, 6, -36), V(0, 4, 0) }, Fov = { 62, 56 } },
		{ T = 1.8, From = { V(-8, 5.4, -9), V(-16, 5.6, 0) }, To = { V(-9.5, 5.2, -8), V(-16, 5.6, 0) }, Fov = { 46, 44 } },
		{ T = 3.2, From = { V(8, 5.2, -8), V(16, 5.4, 0) }, To = { V(9.4, 5, -6.4), V(16, 5.6, 0) }, Fov = { 50, 40 } },
		{ T = 2.8, From = { V(-4, 1.8, -16), V(-16, 7, 0) }, To = { V(-7, 2.2, -12), V(-16, 8, 0) }, Fov = { 62, 62 } },
		{ T = 4, From = { V(0, 9, -50), V(0, 5, 0) }, To = { V(0, 8, -42), V(0, 5, 0) }, Fov = { 58, 56 } },
	}

	---------------------------------------------------------------- the fight
	function MEM.step(f, dt)
		local now = os.clock()
		local me = Players.LocalPlayer
		if not me or me.Character ~= f.char or not f.char.Parent then
			MEM.stop(f)
			return
		end
		for i = #f.grow, 1, -1 do
			local g = f.grow[i]
			local k = math.clamp((now - g.t0) / g.dur, 0, 1)
			if now >= g.t0 then
				pcall(g.set, k)
			end
			if k >= 1 then
				table.remove(f.grow, i)
			end
		end
		MEM.draw(f.deku, now)
		MEM.draw(f.todo, now)
		-- the crowd on its feet
		if f.cheerUntil and now < f.cheerUntil + 0.3 then
			local parts, cfs = {}, {}
			local on = now < f.cheerUntil
			for i, fan in f.fans do
				parts[i] = fan[1]
				cfs[i] = fan[2] + UP * (on and math.max(0, math.sin(now * 11 + fan[3])) * 0.9 or 0)
			end
			pcall(function()
				workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
			end)
		end
		-- One For All crackling up his arm; the heat in Todoroki's hand
		if f.charging and now >= (f.nextBolt or 0) then
			f.nextBolt = now + 0.07
			bolt(PUP.tip(f.deku.pp, "armR"), 1.8, rng:NextNumber() < 0.6 and COWL_GREEN or Color3.fromRGB(255, 70, 70))
		end
		if f.burning and now >= (f.nextFlame or 0) then
			f.nextFlame = now + 0.22
			pcall(Flame.burst, PUP.tip(f.todo.pp, "armL"), 0.8, 4)
		end
		-- his breath, fogging in the cold
		if f.cold and now >= (f.nextBreath or 0) and f.todo.pp.head then
			f.nextBreath = now + 0.7
			local head = f.todo.pp.head
			local puff = newPart(Vector3.one * 0.5, head.CFrame * CFrame.new(0, -0.3, -0.9), STEAM, nil, Enum.PartType.Ball, f.model)
			puff.Transparency = 0.3
			tween(puff, 1.1, { Size = Vector3.one * 1.8, Transparency = 1, CFrame = head.CFrame * CFrame.new(0, 0.4, -2.2) })
			cleanup(puff, 1.2)
		end
	end

	-- step up onto the stage: this is how it went
	function Effects.MemoryFight(_, data)
		if MEM.live or type(data) ~= "table" or typeof(data.Stage) ~= "CFrame" then
			return
		end
		local ok, err = pcall(MEM.fight, data)
		if not ok then
			warn("[VFX] memory: " .. tostring(err))
			if MEM.live then
				MEM.stop(MEM.live)
			end
		end
	end

	function MEM.at(f, t, fn)
		task.delay(t, function()
			if f.gone then
				return
			end
			local ok, err = pcall(fn)
			if not ok then
				warn("[VFX] memory: " .. tostring(err))
			end
		end)
	end

	function MEM.fight(data)
		local me = Players.LocalPlayer
		local char = me and me.Character
		if not char or not workspace.CurrentCamera then
			return
		end
		local S = data.Stage
		local f = { S = S, char = char, hidden = {}, grow = {}, waves = {}, stops = {}, t0 = os.clock(), rival = type(data.Rival) == "table" and data.Rival or {} }
		f.model = Instance.new("Model")
		f.model.Name = "MemoryFight"
		f.model.Parent = folder
		MEM.live = f
		-- (your own cutscene, as far as everything else is concerned: your
		-- inputs are held, nobody else's cutscene takes the camera)
		VFX.CancelCinematic()
		cineActive, cineOwn = true, true
		-- you're not in this one: it's his
		for _, d in char:GetDescendants() do
			if (d:IsA("BasePart") or d:IsA("Decal")) and d.Transparency < 1 then
				f.hidden[d] = d.Transparency
				d.Transparency = 1
			end
		end
		local DEKU0 = S * CFrame.new(16, 0, 0) * CFrame.Angles(0, math.rad(90), 0)
		local TODO0 = S * CFrame.new(-16, 0, 0) * CFrame.Angles(0, math.rad(-90), 0)
		f.deku = MEM.actor(MEM.deku(f.model), DEKU0, MEM.P.guard)
		f.todo = MEM.actor(MEM.todoroki(f.model), TODO0, MEM.P.stand)
		MEM.crowd(f)
		MEM.draw(f.deku, os.clock())
		MEM.draw(f.todo, os.clock())
		f.conn = RunService.Heartbeat:Connect(function(dt)
			local ok, err = pcall(MEM.step, f, dt)
			if not ok then
				warn("[VFX] memory: " .. tostring(err))
				MEM.stop(f)
			end
		end)
		MEM.white(false, 0.9, Color3.fromRGB(255, 252, 244))
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.4)
		VFX.Hooks.Letterbox(true, "MIDORIYA vs TODOROKI", "U.A. SPORTS FESTIVAL - FINAL TOURNAMENT", COWL_GREEN)
		MEM.camera(f, MEM.OPEN)
		MEM.cheer(f, 3)
		local P, D, T = MEM.P, f.deku, f.todo
		MEM.at(f, 1.6, function()
			VFX.Hooks.Callout("START!!", Color3.fromRGB(255, 230, 120))
			VFX.PlaySound("Bell", nil, 1)
		end)
		-- the ice, and a finger to break it with
		MEM.at(f, 3.25, function()
			MEM.to(T, P.lift, 0.22)
		end)
		MEM.at(f, 3.5, function()
			MEM.to(T, P.stomp, 0.1, nil, "out")
			table.insert(f.waves, MEM.ice(f, V(-13, 0, 0), V(12, 0, 0), 9, 7, 0.45))
		end)
		MEM.at(f, 3.85, function()
			MEM.to(D, P.flick, 0.08, nil, "out")
		end)
		MEM.at(f, 3.95, function()
			MEM.flick(f, "armR", 1)
			VFX.Hooks.Callout("DELAWARE SMASH!!", Color3.fromRGB(255, 240, 150))
		end)
		MEM.at(f, 4.4, function()
			MEM.to(D, P.recoil, 0.3)
			MEM.to(T, P.stand, 0.5)
		end)
		MEM.at(f, 5.3, function()
			MEM.to(T, P.lift, 0.2)
		end)
		MEM.at(f, 5.5, function()
			MEM.to(T, P.stomp, 0.1, nil, "out")
			table.insert(f.waves, MEM.ice(f, V(-13, 0, 0), V(12, 0, 0), 13, 10, 0.4))
		end)
		MEM.at(f, 5.85, function()
			MEM.to(D, P.flickL, 0.08, nil, "out")
		end)
		MEM.at(f, 5.95, function()
			MEM.flick(f, "armL", 1)
			MEM.cheer(f, 1.6)
		end)
		MEM.at(f, 6.4, function()
			MEM.to(D, P.recoil, 0.3)
			MEM.say("Midoriya: (Two fingers... and he hasn't even broken a sweat.)", 2.4)
		end)
		-- Todoroki closes in on a ramp of ice; a broken finger sends him back
		MEM.at(f, 6.9, function()
			local run = f.S * CFrame.new(-5, 0, 0) * CFrame.Angles(0, math.rad(-90), 0)
			MEM.to(T, P.slide, 0.55, run, "out")
			local ramp = newPart(V(0.3, 1, 12), CFrame.new(), ICE_MID, Enum.Material.Ice, nil, f.model)
			ramp.CFrame = f.S * CFrame.new(-10.5, 0.2, 0) * CFrame.Angles(0, math.rad(90), 0)
			ramp.Size = V(3, 0.4, 12)
			ramp.Transparency = 0.2
			tween(ramp, 0.8, { Transparency = 1 }, nil, nil, 1.6)
			cleanup(ramp, 2.5)
			VFX.PlaySound("MemoryIce", ramp.Position, 0.8)
		end)
		MEM.at(f, 7.45, function()
			MEM.to(D, P.flick, 0.08, nil, "out")
		end)
		MEM.at(f, 7.55, function()
			MEM.flick(f, "armR", 2)
			MEM.to(T, P.slide, 0.5, TODO0, "out")
			MEM.say("...with a finger he's already broken?!", 2)
		end)
		-- his right side's freezing over; he won't touch his left
		MEM.at(f, 8.2, function()
			MEM.to(T, P.shiver, 0.5)
			MEM.to(D, P.recoil, 0.4)
			MEM.frost(f, true)
			f.cold = true
			MEM.say("Todoroki's right side is freezing over. He won't use his left.", 2.6)
		end)
		-- IT'S YOUR POWER
		MEM.at(f, 10, function()
			MEM.to(D, P.shout, 0.25, nil, "out")
			MEM.slam("EVERYONE'S GIVING IT EVERYTHING THEY'VE GOT!!", Color3.fromRGB(190, 255, 214), 44, 1.8)
			VFX.Shake(1.2, 0.5)
		end)
		MEM.at(f, 11.6, function()
			MEM.slam("IT'S YOUR POWER, ISN'T IT?!", Color3.fromRGB(255, 240, 150), 64, 1.8)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
			VFX.Hooks.SpeedLines(1.2)
			VFX.Shake(2.4, 0.6)
			MEM.cheer(f, 1)
		end)
		-- the fire
		MEM.at(f, 13.3, function()
			MEM.to(T, P.ignite, 0.35, nil, "out")
			f.cold = false
			MEM.frost(f, false)
			local base = (MEM.cfAt(T, os.clock()) * CFrame.new(-1.4 * SCALE, 0, 0)).Position
			pcall(Flame.column, base, 32, 4.5, 3.2)
			for _ = 1, 4 do
				pcall(Flame.burst, base + V(rand(-2, 2), rand(2, 8), rand(-2, 2)), 1.6, 12)
			end
			local arm = T.pp.hands.armL
			local ok, stop = pcall(Flame.attach, arm, 1.1, 0.8)
			if ok and stop then
				table.insert(f.stops, stop)
			end
			VFX.PlaySound("MemoryIgnite", base, 1.3)
			VFX.Hooks.Flash(HOT, 0.3)
			VFX.Shake(2.6, 0.8)
			MEM.cheer(f, 3)
		end)
		MEM.at(f, 14.3, function()
			MEM.say("Endeavor, in the stands: \"SHOTO!!\"", 1.8)
		end)
		MEM.at(f, 15.4, function()
			MEM.say("Todoroki: \"...You want to win, and you're helping your enemy?\"", 2.4)
		end)
		-- everything they've got
		MEM.at(f, 16.2, function()
			MEM.to(D, P.windup, 0.5)
			MEM.to(T, P.heat, 0.6)
			f.charging, f.burning = true, true
			VFX.PlaySound("MemoryCharge", f.S.Position, 1.2)
			table.insert(f.waves, MEM.ice(f, V(-19, 0, 5), V(-19, 0, -5), 10, 4, 0.5))
		end)
		MEM.at(f, 17.2, function()
			MEM.walls(f)
			MEM.say("Cementoss: \"That's enough!\"", 1.4)
		end)
		MEM.at(f, 18.4, function()
			MEM.to(D, P.smash, 0.1, nil, "out")
			MEM.breakWalls(f)
			for _, w in f.waves do
				MEM.shatter(f, w, f.S.Position)
			end
			f.waves = {}
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
		end)
		-- THE CLASH: his Smash against the heat - yours to push
		MEM.at(f, 18.55, function()
			MEM.cameraOff()
			local toTodo, toDeku = -f.S.RightVector, f.S.RightVector
			f.clash = VFX.CL.solo({
				GetA = function()
					return PUP.tip(D.pp, "armR") + toTodo * 0.8
				end,
				GetB = function()
					return PUP.tip(T.pp, "armL") + toDeku * 0.8
				end,
				AMove = "DetroitSmash", BMove = "Heatwave", AName = "MIDORIYA", BName = "TODOROKI",
				Time = tonumber(data.Time) or 9, Rate = tonumber(f.rival.Rate) or 3.3, Accuracy = tonumber(f.rival.Accuracy) or 0.8,
				OnEnd = function(result)
					if not f.gone then
						local ok, err = pcall(MEM.ending, f, result)
						if not ok then
							warn("[VFX] memory: " .. tostring(err))
							MEM.stop(f)
						end
					end
				end,
			})
			MEM.cheer(f, 9)
		end)
	end

	-- how it ended (result: "A" = Midoriya's Smash went through, "B" =
	-- Todoroki's heat, "Draw")
	function MEM.ending(f, result)
		f.charging, f.burning = false, false
		f.result = result
		local D, T, P = f.deku, f.todo, MEM.P
		local now = os.clock()
		local at = result == "A" and MEM.cfAt(T, now).Position or result == "B" and MEM.cfAt(D, now).Position or f.S.Position
		MEM.camera(f, { { T = 8, From = { V(0, 22, -90), V(0, 4, 0) }, To = { V(0, 30, -124), V(0, 6, 0) }, Fov = { 62, 56 } } })
		VFX.Hooks.Letterbox(true)
		MEM.steam(f, at + UP * 4)
		if result ~= "A" then
			MEM.fling(f, D, 1)
		end
		if result ~= "B" then
			MEM.fling(f, T, -1)
		end
		if result == "A" then
			MEM.to(D, P.spent, 0.6)
		elseif result == "B" then
			MEM.to(T, P.spent, 0.6)
		end
		-- (his hand's wrecked, either way)
		for _, p in D.pp.fingers.armR or {} do
			tween(p, 0.6, { Color = BRUISE })
		end
		if D.pp.hands.armR then
			tween(D.pp.hands.armR, 0.6, { Color = BRUISE })
		end
		for _, stop in f.stops do
			pcall(stop)
		end
		f.stops = {}
		local lines = {
			A = { "MIDORIYA WINS!!", "Midnight: \"Todoroki is out of bounds! Midoriya advances!\"", "That's not how it went - Todoroki won that day. But that day, he got his fire back." },
			B = { "TODOROKI WINS!!", "Midnight: \"Midoriya is out of bounds! Todoroki advances!\"", "He lost that day. And he gave Todoroki his fire back." },
			Draw = { "BOTH OUT!!", "Midnight: \"...Both of them - out of bounds?!\"", "In the memory, Todoroki stayed in. But that day, he got his fire back." },
		}
		local say = lines[result] or lines.Draw
		MEM.at(f, 2, function()
			VFX.Hooks.Callout(say[1], result == "A" and COWL_GREEN or result == "B" and HOT or Color3.fromRGB(255, 240, 180))
			MEM.say(say[2], 2.4)
			MEM.cheer(f, 2.5)
		end)
		MEM.at(f, 4.6, function()
			MEM.say(say[3], 3.4)
		end)
		MEM.at(f, 8.2, function()
			MEM.white(true, 0.8)
		end)
		MEM.at(f, 9.1, function()
			MEM.stop(f)
			MEM.white(false, 1.4)
			MEM.say("...the memory fades.", 2)
		end)
	end

	-- over: everything back the way it was
	function MEM.stop(f)
		if not f or f.gone then
			return
		end
		f.gone = true
		if MEM.live == f then
			MEM.live = nil
		end
		if f.conn then
			f.conn:Disconnect()
		end
		if f.clash and not f.clash.gone and VFX.CL then
			pcall(VFX.CL.cleanup, f.clash)
		end
		MEM.cameraOff()
		cineActive, cineOwn = false, false
		local cam = workspace.CurrentCamera
		if cam then
			cam.CameraType = Enum.CameraType.Custom
			if f.camSaved then
				cam.FieldOfView = f.camSaved.Fov
			end
			local me = Players.LocalPlayer and Players.LocalPlayer.Character
			local hum = me and me:FindFirstChildOfClass("Humanoid")
			if hum then
				cam.CameraSubject = hum
			end
		end
		VFX.Hooks.Letterbox(false)
		for d, t in f.hidden do
			if d.Parent then
				d.Transparency = t
			end
		end
		for _, stop in f.stops do
			pcall(stop)
		end
		if f.model then
			f.model:Destroy()
		end
	end
end)()


---------------------------------------------------------------------------
-- (round 60) CREATI (Momo Yaoyorozu): Creation. Whatever she makes comes out
-- of her skin in a soft pink-white glow and grows to full size: her weapons
-- (staff, sword, spear - the server builds the one in her hand), the tower
-- shield, cannons in iron and gold, matryoshka dolls painted red and gold
-- with flashbangs inside, the capture net and its catapult, the railgun.
---------------------------------------------------------------------------
do
	local YM = {
		GLOW = Color3.fromRGB(255, 176, 214),
		GLOW_HOT = Color3.fromRGB(255, 236, 246),
		STEEL = Color3.fromRGB(214, 218, 226),
		IRON = Color3.fromRGB(58, 60, 68),
		GOLD = Color3.fromRGB(255, 196, 70),
		RED = Color3.fromRGB(196, 32, 52),
		FACE = Color3.fromRGB(250, 232, 214),
		FLASH = Color3.fromRGB(255, 252, 236),
		RAIL = Color3.fromRGB(255, 226, 60),
		ROPE = Color3.fromRGB(232, 222, 196),
		dolls = setmetatable({}, { __mode = "k" }), -- [char] = { [i] = doll } in flight
		shields = setmetatable({}, { __mode = "k" }), -- [char] = the shield on her arm
		grand = setmetatable({}, { __mode = "k" }), -- [char] = the Grand Cannon out
		rails = setmetatable({}, { __mode = "k" }), -- [char] = the railgun on her shoulder
		catapults = setmetatable({}, { __mode = "k" }), -- [char] = the net's catapult
	}
	VFX.YM = YM
	YM.bashing = setmetatable({}, { __mode = "k" }) -- [char] = true while the shield bash runs

	-- a client-made part welded onto a body part (it moves with it)
	function YM.attach(to, part, offset)
		local w = Instance.new("Weld")
		w.Part0 = to
		w.Part1 = part
		w.C0 = offset or CFrame.new()
		w.Parent = part
		part.Anchored = false
		part.Massless = true
		part.CanCollide = false
		return w
	end

	-- the map only (people and effects don't stop a doll)
	function YM.mapParams()
		local rp = RaycastParams.new()
		rp.FilterType = Enum.RaycastFilterType.Exclude
		rp.FilterDescendantsInstances = characterList()
		return rp
	end

	-- something coming out of her skin: a pink-white bloom, sparkles, a ring
	function YM.glow(pos, size)
		size = size or 1
		local ball = newPart(Vector3.one * 0.4 * size, CFrame.new(pos), YM.GLOW, Enum.Material.Neon, Enum.PartType.Ball)
		ball.Transparency = 0.15
		tween(ball, 0.28, { Size = Vector3.one * 3.2 * size, Transparency = 1 })
		cleanup(ball, 0.32)
		sparks(pos, 0.4 * size, YM.GLOW_HOT, YM.GLOW, math.floor(5 * size) + 2)
		billboardRing(pos, 0.5 * size, 4.5 * size, YM.GLOW, 3, 0.28)
	end

	-- a set of parts grows out to full size, glowing, as it's made
	function YM.emerge(parts, time, holder)
		time = time or 0.28
		for _, p in parts do
			if p:IsA("BasePart") then
				local size, tr = p.Size, p.Transparency
				p.Size = size * 0.06
				p.Transparency = math.max(tr, 0.5)
				-- (round 62) welded on: it grows out from the grip, the far end last
				local w = p:FindFirstChildOfClass("Weld")
				local delay = w and math.clamp(math.abs(w.C0.Position.Z) / 7, 0, 1) * 0.16 or 0
				tween(p, time, { Size = size, Transparency = tr }, Enum.EasingStyle.Back, Enum.EasingDirection.Out, delay)
			end
		end
		if holder then
			local h = Instance.new("Highlight")
			h.Name = "CreationGlow"
			h.Adornee = holder
			h.FillColor = YM.GLOW
			h.FillTransparency = 0.15
			h.OutlineColor = YM.GLOW_HOT
			h.OutlineTransparency = 0
			h.DepthMode = Enum.HighlightDepthMode.Occluded
			h.Parent = holder
			tween(h, time + 0.35, { FillTransparency = 1, OutlineTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			cleanup(h, time + 0.4)
		end
	end

	-- a model of anchored parts moved as one: rig.set(cf) puts it at cf
	function YM.rig(name, base)
		local m = Instance.new("Model")
		m.Name = name
		m.Parent = folder
		local rig = { model = m, parts = {}, offsets = {}, base = base }
		function rig.add(size, offset, color, material, shape)
			local p = newPart(size, base * offset, color, material or Enum.Material.Metal, shape, m)
			table.insert(rig.parts, p)
			rig.offsets[p] = offset
			return p
		end
		function rig.set(cf)
			rig.base = cf
			for _, p in rig.parts do
				if p.Parent then
					p.CFrame = cf * rig.offsets[p]
				end
			end
		end
		function rig.fade(t, sparkle)
			for _, p in rig.parts do
				if p.Parent then
					tween(p, t, { Transparency = 1, Size = p.Size * 0.6 })
				end
			end
			if sparkle then
				sparks(rig.base.Position, sparkle, YM.GLOW_HOT, YM.GLOW, 8)
			end
			cleanup(m, t + 0.05)
		end
		return rig
	end

	-- a cannon on its carriage (cf: on the street, facing where it fires)
	function YM.cannon(cf, scale)
		local k = scale or 1
		local rig = YM.rig("CreatiCannon", cf)
		local ALONG = CFrame.Angles(0, math.rad(90), 0)
		rig.add(Vector3.new(1.6, 0.9, 3.2) * k, CFrame.new(0, 0.9 * k, 0.3 * k), Color3.fromRGB(96, 62, 40), Enum.Material.Wood) -- the carriage
		for _, x in { -1, 1 } do
			rig.add(Vector3.new(0.4, 2, 2) * k, CFrame.new(x * 1.05 * k, 1 * k, 0.6 * k), YM.IRON, Enum.Material.Metal, Enum.PartType.Cylinder)
			rig.add(Vector3.new(0.45, 1.2, 1.2) * k, CFrame.new(x * 1.08 * k, 1 * k, 0.6 * k), YM.GOLD, Enum.Material.Metal, Enum.PartType.Cylinder)
		end
		local barrel = rig.add(Vector3.new(4.2, 1.1, 1.1) * k, CFrame.new(0, 1.9 * k, -0.7 * k) * CFrame.Angles(math.rad(12), 0, 0) * ALONG, YM.IRON, Enum.Material.Metal, Enum.PartType.Cylinder)
		for _, z in { 0.4, -1.1, -2.6 } do
			rig.add(Vector3.new(0.28, 1.3, 1.3) * k, CFrame.new(0, 1.9 * k, -0.7 * k) * CFrame.Angles(math.rad(12), 0, 0) * CFrame.new(0, 0, z * k) * ALONG, YM.GOLD, Enum.Material.Metal, Enum.PartType.Cylinder)
		end
		rig.barrel = barrel
		function rig.muzzle()
			return (rig.base * CFrame.new(0, 1.9 * k, -0.7 * k) * CFrame.Angles(math.rad(12), 0, 0) * CFrame.new(0, 0, -2.3 * k)).Position
		end
		return rig
	end

	-- a matryoshka doll (red and gold, a pale face) - cf: its middle
	function YM.doll(cf, scale)
		local k = scale or 1
		local rig = YM.rig("Matryoshka", cf)
		rig.add(Vector3.new(1, 1.15, 1) * k, CFrame.new(0, -0.15 * k, 0), YM.RED, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
		rig.add(Vector3.new(0.78, 0.78, 0.78) * k, CFrame.new(0, 0.52 * k, 0), YM.RED, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
		rig.add(Vector3.new(0.5, 0.46, 0.1) * k, CFrame.new(0, 0.5 * k, -0.36 * k), YM.FACE, Enum.Material.SmoothPlastic)
		rig.add(Vector3.new(0.14, 1.04, 1.04) * k, CFrame.new(0, 0.12 * k, 0) * CFrame.Angles(0, 0, math.rad(90)), YM.GOLD, Enum.Material.Metal, Enum.PartType.Cylinder)
		rig.add(Vector3.new(0.34, 0.34, 0.1) * k, CFrame.new(0, -0.2 * k, -0.48 * k), YM.GOLD, Enum.Material.SmoothPlastic, Enum.PartType.Ball) -- (the painted flower)
		return rig
	end

	-- a flashbang goes off: the doll splits, a smaller doll tumbles out, and
	-- the flash - white, blinding, a bang
	function YM.flashbang(pos, dir)
		dir = typeof(dir) == "Vector3" and dir.Magnitude > 0.1 and dir.Unit or UP
		for _, side in { 1, -1 } do
			local half = newPart(Vector3.new(0.9, 0.5, 0.9), CFrame.new(pos + UP * side * 0.3), YM.RED, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			local to = pos + UP * side * rand(1.5, 2.5) + rng:NextUnitVector() * 1.5
			tween(half, 0.35, { CFrame = CFrame.new(to) * CFrame.Angles(rand(-3, 3), rand(-3, 3), 0), Transparency = 1 })
			cleanup(half, 0.4)
		end
		local inner = YM.doll(CFrame.new(pos), 0.35)
		task.delay(0.05, function()
			inner.fade(0.3)
		end)
		local core = newPart(Vector3.one * 1, CFrame.new(pos), YM.FLASH, Enum.Material.Neon, Enum.PartType.Ball)
		tween(core, 0.07, { Size = Vector3.one * 13 })
		tween(core, 0.28, { Size = Vector3.one * 15, Transparency = 1 }, nil, nil, 0.07)
		cleanup(core, 0.4)
		local light = Instance.new("PointLight")
		light.Color = YM.FLASH
		light.Brightness = 10
		light.Range = 34
		light.Parent = core
		billboardRing(pos, 2, 20, Color3.new(1, 1, 1), 0, 0.2, true)
		billboardRing(pos, 3, 24, YM.GOLD, 6, 0.3)
		sparks(pos, 0.9, Color3.new(1, 1, 1), YM.GOLD, 12)
		smokeBurst(pos, Color3.fromRGB(226, 222, 214), 3, 5, 1.1, 6)
		VFX.PlaySound("DollPop", pos, 1)
		VFX.PlaySound("Flashbang", pos, 1)
		VFX.ShakeAt(pos, 0.8, 40, 0.15)
	end

