	VFX.PV = PV
	local Lighting = game:GetService("Lighting")

	-- poses
	POSES.FlashCrouch = { Hips = { 0, 0, 0, 0, 0, 0 }, Crouch = 0.9, Waist = { -26, 10, 0 }, Neck = { 18, -8, 0 }, RightArm = { -30, 0, 30 }, LeftArm = { 40, 0, 20 }, RightLeg = { -20, 0, 10 }, LeftLeg = { 40, 0, 6 } }
