	POSES.LookBack = { Neck = { 4, 62, 0 }, Waist = { 0, 22, 0 }, RightArm = { 20, 0, 14 }, LeftArm = { 6, 0, 10 } }
	POSES.WhipCast = { RightArm = { 96, 0, 18 }, LeftArm = { 96, 0, 18 }, Waist = { -14, 0, 0 }, Neck = { -6, 0, 0 }, RightLeg = { -16, 0, 6 }, LeftLeg = { 22, 0, 4 }, Crouch = 0.3 }
	POSES.FloatAim = { RightArm = { 70, 0, -8 }, LeftArm = { -20, 0, 34 }, Waist = { -18, 0, 0 }, Neck = { -24, 0, 0 }, RightLeg = { 30, 0, 8 }, LeftLeg = { 8, 0, 6 } }
	POSES.DangerStance = { Crouch = 0.6, Waist = { -18, 20, 0 }, Neck = { -6, -16, 0 }, RightArm = { 50, 0, 40 }, LeftArm = { 84, 0, -10 }, RightLeg = { -22, 0, 10 }, LeftLeg = { 24, 0, 6 } }
	POSES.VestigeCall = { RightArm = { 176, 0, 8 }, LeftArm = { 30, 0, 30 }, Waist = { 10, 16, 0 }, Neck = { 26, 0, 0 }, RightLeg = { -14, 0, 8 }, LeftLeg = { 18, 0, 6 }, Crouch = 0.2 }
	POSES.VestigeSlam = { RightArm = { 40, 0, 6 }, LeftArm = { -30, 0, 40 }, Waist = { -34, 10, 0 }, Neck = { -10, 0, 0 }, RightLeg = { -24, 0, 8 }, LeftLeg = { 36, 0, 6 }, Crouch = 0.8 }
	POSES.Lariat = { RightArm = { 24, 0, 80 }, LeftArm = { -30, 0, 20 }, Waist = { -30, -24, 0 }, Neck = { -4, 20, 0 }, RightLeg = { -40, 0, 6 }, LeftLeg = { 46, 0, 4 }, Crouch = 0.3 }
	POSES.MeteorDive = { Hips = { -80, 0, 0 }, RightArm = { 170, 0, 6 }, LeftArm = { 40, 0, 40 }, Neck = { 40, 0, 0 }, RightLeg = { -10, 0, 8 }, LeftLeg = { 20, 0, 8 } }
	POSES.LookUp = { Neck = { 58, 0, 0 }, Waist = { 14, 0, 0 }, RightArm = { 30, 0, 18 }, LeftArm = { 26, 0, 16 } }
	POSES.USJPunchR = { RightArm = { 96, 0, -6 }, LeftArm = { 30, 0, 20 }, Waist = { -10, -30, 0 }, Neck = { -6, 24, 0 }, RightLeg = { -22, 0, 6 }, LeftLeg = { 30, 0, 4 }, Crouch = 0.35 }
	POSES.USJPunchL = { LeftArm = { 96, 0, -6 }, RightArm = { 30, 0, 20 }, Waist = { -10, 30, 0 }, Neck = { -6, -24, 0 }, RightLeg = { -22, 0, 6 }, LeftLeg = { 30, 0, 4 }, Crouch = 0.35 }

	PV.KICK = { { pose = "FlashKickWind", t = 0.06, hold = 0.04 }, { pose = "FlashKick", t = 0.05, hold = 0.35, style = SNAP }, recover = 0.3 }
	MOTIONS.FlashKick = PV.KICK
	MOTIONS.PrimeSpinKick = { { pose = "FlashKickWind", t = 0.07, hold = 0.02 }, { pose = "FlashKick", t = 0.06, hold = 0.3, style = SNAP }, recover = 0.3 }

	-- cinematics (in the TARGET's space: +Z is behind them, where he appears)
	SHOTS.FlashBehind = {
		-- (off to her side, so he shows over her shoulder - an R6 head is two studs wide)
		{ T = 0.52, From = { V(2.6, 1.8, -4.8), V(0, 1.7, 0) }, To = { V(3.0, 1.9, -3.4), V(0.4, 1.9, 2.2) }, Fov = { 46, 40 } },
		{ T = 0.46, Cut = true, From = { V(-3.2, 3.0, 8.6), V(0, 1.8, 0.8) }, To = { V(-2.7, 2.6, 7.5), V(0, 1.8, 0.8) }, Fov = { 50, 44 } },
		{ T = 0.62, Cut = true, From = { V(7.5, 1.4, 1.2), V(0, 1.6, 1) }, To = { V(10, 2.6, -5), V(0, 2, -12) }, Fov = { 58, 76 }, Style = Enum.EasingStyle.Quad },
	}
	SHOTS.MeteorLook = {
		{ T = 0.85, From = { V(1.4, 0.4, -2.6), V(0, 60, -6) }, To = { V(1.1, 0.5, -2.2), V(0, 90, -8) }, Fov = { 70, 58 } },
		-- (far, wide and low: the whole fall in frame, from the sky to the street)
		{ T = 0.9, Cut = true, From = { V(-50, 4, -56), V(0, 50, 2) }, To = { V(-54, 6, -60), V(0, 26, 0) }, Fov = { 72, 70 } },
	}
	SHOTS.USJ = {
		{ T = 0.5, From = { V(3.2, 2.2, -3.4), V(0, 2, -4.4) }, To = { V(2.6, 2, -2.8), V(0, 2, -4.4) }, Fov = { 55, 48 } },
		{ T = 0.5, Cut = true, From = { V(-3.6, 1.2, -6), V(0, 2.4, -2) }, To = { V(-3, 1.4, -5.4), V(0, 2.4, -2) }, Fov = { 60, 52 } },
		{ T = 0.5, Cut = true, From = { V(0, 3, -10), V(0, 2.6, 0) }, To = { V(0, 2.6, -8.4), V(0, 2.6, 0) }, Fov = { 50, 44 } },
		{ T = 1.0, Cut = true, From = { V(6, 1, 4), V(0, 4, -4) }, To = { V(8, 2, 6), V(0, 60, -6) }, Fov = { 60, 80 }, Style = Enum.EasingStyle.Quad },
	}
	SHOTS.VestigeDDS = {
		{ T = 0.6, From = { V(3.5, 1.4, -4.5), V(0, 2, 0) }, To = { V(2.8, 1.6, -3.6), V(0, 2, 0) }, Fov = { 50, 42 } },
		{ T = 0.9, Cut = true, From = { V(0, 6, 22), V(0, 5, 0) }, To = { V(0, 9, 30), V(0, 7, 0) }, Fov = { 60, 72 } },
		{ T = 1.2, Cut = true, From = { V(-26, 6, -12), V(0, 6, -40) }, To = { V(-38, 12, -20), V(0, 10, -90) }, Fov = { 70, 80 }, Style = Enum.EasingStyle.Quad },
	}
	SHOTS.FlashCut = {
		{ T = 0.3, From = { V(3, 1.8, -3.4), V(0, 1.5, 1.5) }, To = { V(2.3, 1.6, -2.8), V(0, 1.5, 1.5) }, Fov = { 52, 44 } },
	}

	-- gone (every screen): hidden until the server's "Vanished" comes off
	-- again (or it never comes on - the server didn't go along with it)
	function PV.hideWhile(char, maxTime)
		local token = (PV.hidden[char] or 0) + 1
		PV.hidden[char] = token
		local list = {}
		for _, d in char:GetDescendants() do
			if (d:IsA("BasePart") or d:IsA("Decal")) and d.LocalTransparencyModifier < 1 then
				d.LocalTransparencyModifier = 1
				table.insert(list, d)
			end
		end
		task.spawn(function()
			local t0, seen = os.clock(), false
			while PV.hidden[char] == token and char.Parent and os.clock() - t0 < (maxTime or 5) do
				local on = char:GetAttribute("Vanished") == true
				if on then
					seen = true
				elseif seen or os.clock() - t0 > 0.9 then
					break
				end
				task.wait()
			end
			if PV.hidden[char] == token then
				PV.hidden[char] = nil
				for _, d in list do
					if d.Parent then
						d.LocalTransparencyModifier = 0
					end
				end
			end
		end)
	end

	-- green lightning crackling in toward a point, and a flash where it meets
	function PV.gather(pos, color, time)
		local t0 = os.clock()
		while os.clock() - t0 < time do
			local k = (os.clock() - t0) / time
			local from = pos + rng:NextUnitVector() * (6 * (1 - k) + 1)
			local seg = newPart(Vector3.new(0.16, 0.16, (pos - from).Magnitude), CFrame.lookAt((from + pos) / 2, pos), color, Enum.Material.Neon)
			cleanup(seg, 0.06)
			bolt(pos, 2.5 * (1 - k) + 0.6, color)
			task.wait(0.03)
		end
		billboardRing(pos, 1, 10, PV.CORE, 6, 0.2)
		sparks(pos, 0.8, PV.CORE, color, 14)
	end

	-- the screen for the two of them: colour drains out while it plays
	function PV.drain(time, amount)
		local cc = Instance.new("ColorCorrectionEffect")
		cc.Name = "PrimeDrain"
		cc.Parent = Lighting
		tween(cc, 0.12, { Saturation = -(amount or 0.7), Contrast = 0.2 })
		task.delay(time, function()
			tween(cc, 0.25, { Saturation = 0, Contrast = 0 })
			cleanup(cc, 0.3)
		end)
	end

	-- the one who's here (the local player's character)
	local function me()
		return Players.LocalPlayer and Players.LocalPlayer.Character
	end

	-----------------------------------------------------------------------
	-- PRIME DEKU
	-----------------------------------------------------------------------

	-- 1: FLASH STEP - gone in a crack of green lightning
	function Effects.PrimeFlashStep(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		afterimage(char, PV.GREEN, 0.5)
		afterimage(char, PV.DARK, 0.25)
		local g = groundPoint(root.Position)
		dustPuffs(g, 1, 6, Color3.fromRGB(200, 196, 186), 0.7, true)
		shockDisc(g + UP * 0.3, UP, 2, 16, 0.25, PV.GREEN)
		streaks(root.Position, UP, 10, 1.5, 6, 10, PV.GREEN, 0.25)
		for _ = 1, 5 do
			bolt(root.Position, 4, PV.GREEN)
		end
		VFX.PlaySound("FlashStep", root.Position, 1)
		if isLocal then
			VFX.Hooks.Flash(PV.GREEN, 0.12)
		end
		PV.hideWhile(char, 4.5)
	end

	-- nobody in the ring: he lands in a shockwave
	function Effects.FlashAppear(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		PV.hidden[char] = nil
		for _, d in char:GetDescendants() do
			if d:IsA("BasePart") or d:IsA("Decal") then
				d.LocalTransparencyModifier = 0
			end
		end
		-- a bolt down out of nowhere
		local top = pos + UP * 30
		local prev = top
		for i = 1, 6 do
			local p = top:Lerp(pos, i / 6) + Vector3.new(rand(-1.5, 1.5), 0, rand(-1.5, 1.5)) * (i < 6 and 1 or 0)
			local seg = newPart(Vector3.new(0.4, 0.4, (p - prev).Magnitude), CFrame.lookAt((p + prev) / 2, p), PV.CORE, Enum.Material.Neon)
			tween(seg, 0.2, { Transparency = 1, Size = seg.Size * Vector3.new(0.2, 0.2, 1) })
			cleanup(seg, 0.25)
			prev = p
		end
		VFX.Pose(char, "FlashCrouch", 0.3)
		local r = tonumber(data.Radius) or 10
		shockDisc(pos + UP * 0.4, UP, 3, r * 2.4, 0.3, PV.GREEN)
		billboardRing(pos + UP * 2, 2, r * 2, PV.CORE, 8, 0.3)
		dustPuffs(pos, 1.2, 8, Color3.fromRGB(206, 198, 188), 0.9, true)
		sparks(pos + UP, 1, PV.CORE, PV.GREEN, 18)
		VFX.PlaySound("FlashAppear", pos, 1)
		VFX.ShakeAt(pos, 1.6, 60, 0.25)
	end

	-- someone in the ring: BEHIND them
	function Effects.FlashBehind(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not troot or not at then
			return
		end
		local look = typeof(data.Look) == "Vector3" and data.Look or troot.CFrame.LookVector
		local strike = tonumber(data.Strike) or 1.02
		local mine = me()
		if mine == char or mine == target then
			VFX.Cinematic(target, SHOTS.FlashBehind, { Title = data.Name or "FLASH STEP", Subtitle = "BEHIND YOU", Color = PV.GREEN, Own = mine == char, Face = troot.Position + look * 10 })
			PV.drain(strike + 0.05, 0.75)
		elseif mine then
			local mr = mine:FindFirstChild("HumanoidRootPart")
			if mr and (mr.Position - troot.Position).Magnitude < 55 then
				VFX.Cinematic(mine, witnessShots((mr.Position - troot.Position).Magnitude), { Title = data.Name or "FLASH STEP", Color = PV.GREEN, Face = troot.Position })
			end
		end
		VFX.Hitstop(target, strike - 0.05) -- (they're caught mid-step)
		VFX.PlaySound("FlashStep", at, 0.8)
		local t0 = os.clock()
		local function at_(t)
			local left = t - (os.clock() - t0)
			if left > 0 then
				task.wait(left)
			end
		end
		at_(0.1)
		PV.gather(at + UP * 0.5, PV.GREEN, 0.08)
		at_(0.19)
		if char.Parent then
			PV.hidden[char] = nil
			for _, d in char:GetDescendants() do
				if d:IsA("BasePart") or d:IsA("Decal") then
					d.LocalTransparencyModifier = 0
				end
			end
			VFX.Pose(char, "FlashCrouch", 0.4)
			afterimage(char, PV.GREEN, 0.3)
		end
		VFX.PlaySound("FlashAppear", at, 0.8)
		at_(0.48)
		if target.Parent then
			VFX.Pose(target, "LookBack", 0.7)
		end
		-- the leg comes up, lightning running down it...
		at_(0.58)
		if char.Parent then
			VFX.Pose(char, "FlashKickWind", strike - 0.5)
		end
		while os.clock() - t0 < strike - 0.06 and char.Parent do
			local foot = limb(char, "RightFoot", "Right Leg")
			if foot then
				bolt(foot.Position, 2, PV.GREEN)
				bolt(foot.Position, 1.2, PV.CORE)
			end
			task.wait(0.04)
		end
		-- ...and snaps round into them
		if char.Parent then
			VFX.Pose(char, "FlashKick", 0.45)
		end
	end

	-- the kick lands
	function Effects.FlashStrike(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
		local pos = troot and troot.Position or (typeof(data.Pos) == "Vector3" and data.Pos)
		if not pos then
			return
		end
		local mine = me()
		if mine == char or mine == target or nearCamera(pos, 70) then
			VFX.ImpactFrame(0.1)
			VFX.Hooks.Flash(PV.CORE, 0.25)
		end
		if mine == char then
			VFX.Hooks.Callout("SMASH!!", PV.GREEN)
		end
		shockDisc(pos, d, 2, 22, 0.3, PV.GREEN, 8)
		shockDisc(pos, d, 1, 14, 0.2, Color3.new(1, 1, 1), 4)
		billboardRing(pos, 2, 22, PV.CORE, 10, 0.3)
		streaks(pos, d, 26, 3, 14, 40, PV.GREEN, 0.4)
		streaks(pos, d, 14, 2, 10, 30, Color3.new(1, 1, 1), 0.3)
		sparks(pos, 1.6, PV.CORE, PV.GREEN, 40)
		for _ = 1, 8 do
			bolt(pos, 5, PV.GREEN)
		end
		VFX.PlaySound("FlashKick", pos, 1)
		VFX.PlaySound("Smash", pos, 0.9)
		VFX.ShakeAt(pos, 3, 110, 0.4)
		-- the wind following them down the street
		if troot then
			task.spawn(function()
				local t0 = os.clock()
				while os.clock() - t0 < 0.6 and troot.Parent do
					streaks(troot.Position, -d, 3, 1.5, 6, 8, PV.GREEN, 0.2)
					task.wait(0.05)
				end
			end)
		end
	end

	-- 2: BLACKWHIP REEL
	function Effects.BlackwhipReel(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "WhipCast", 0.7)
		VFX.PlaySound("Blackwhip", root.Position, 1)
		for _ = 1, 4 do
			bolt(root.Position + UP, 3, WHIP_GLOW)
		end
	end
	function Effects.BlackwhipReelCast(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local list = type(data.Targets) == "table" and data.Targets or {}
		local function hand(i)
			return function()
				return root.Parent and handPos(char, i % 2 == 0) or nil
			end
		end
		if #list == 0 then
			for i = 1, 6 do
				local a = math.rad((i - 3.5) / 2.5 * 25)
				local to = root.Position + (CFrame.fromAxisAngle(UP, a) * d) * 45 + UP * rand(-1, 3)
				VFX.whipRope(hand(i), function()
					return to
				end, 0.45, { Color = WHIP_DARK, OutlineColor = WHIP_GLOW, Wave = 1.4 })
			end
			return
		end
		for i, target in list do
			local tr = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
			if tr then
				for k = 0, 1 do
					VFX.whipRope(hand(i + k), function()
						return tr.Parent and tr.Position or nil
					end, 0.95, { Color = WHIP_DARK, OutlineColor = WHIP_GLOW, Wave = 1 + k * 0.6 })
				end
				task.delay(0.22, function()
					if tr.Parent then
						sparks(tr.Position, 0.7, WHIP_GLOW, PV.GREEN, 10)
						billboardRing(tr.Position, 1, 8, WHIP_GLOW, 5, 0.2)
					end
				end)
			end
		end
	end
	function Effects.BlackwhipReelKick(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		VFX.Motion(char, "PrimeSpinKick")
		local pos = root.Position + UP * 0.8
		moonArc(CFrame.lookAt(pos, pos + d) * CFrame.Angles(math.rad(90), 0, 0), 7, PV.GREEN, 330)
		shockDisc(pos, UP, 4, 34, 0.35, PV.GREEN)
		shockDisc(pos, UP, 2, 22, 0.25, Color3.new(1, 1, 1))
		for i = 1, 12 do
			local a = i / 12 * math.pi * 2
			streaks(pos, Vector3.new(math.cos(a), 0, math.sin(a)), 1, 0.5, 8, 22, PV.GREEN, 0.3)
		end
		VFX.PlaySound("Smash", pos, 1)
		VFX.ShakeAt(pos, 2.4, 90, 0.35)
	end

	-- 3: AIR FORCE STORM - up on Float, bullets down on the spot
	function Effects.AirForceStorm(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		VFX.Pose(char, "FloatAim", 1.4)
		VFX.PlaySound("CowlCharge", root.Position, 0.7)
		dustPuffs(groundPoint(root.Position), 0.8, 5, Color3.fromRGB(206, 198, 188), 0.7, true)
		shockDisc(root.Position, UP, 2, 12, 0.3, PV.GREEN)
		if isLocal then
			face(root, flatten(data.Dir, root))
			launch(root, hum, UP * ((ability.Lift or 14) * 3) + flatten(data.Dir, root) * 4)
			task.delay(0.25, function()
				if root.Parent then
					dash(root, Vector3.new(0, 1.5, 0), (ability.Shots or 12) * (ability.Gap or 0.07) + 0.3)
				end
			end)
		end
	end
	function Effects.AirForceShots(char, data)
		local root = charParts(char)
		if not root or type(data.Spots) ~= "table" then
			return
		end
		local gap = tonumber(data.Gap) or 0.07
		for i, at in data.Spots do
			if typeof(at) == "Vector3" then
				task.delay((i - 1) * gap, function()
					if not root.Parent then
						return
					end
					VFX.Pose(char, i % 2 == 0 and "PunchL" or "PunchR", 0.12)
					local from = handPos(char, i % 2 == 1)
					local bullet = newPart(Vector3.new(0.6, 0.6, 5), CFrame.lookAt(from, at), Color3.new(1, 1, 1), Enum.Material.Neon)
					tween(bullet, 0.09, { CFrame = CFrame.lookAt(at, at + (at - from).Unit) })
					cleanup(bullet, 0.1)
					shockDisc(from, (at - from).Unit, 0.5, 5, 0.12, WIND)
					task.delay(0.09, function()
						shockDisc(at + UP * 0.4, UP, 2, 14, 0.25, WIND)
						billboardRing(at + UP, 1, 9, PV.GREEN, 5, 0.2)
						dustPuffs(at, 0.6, 3, Color3.fromRGB(206, 198, 188), 0.6, false)
						if i % 3 == 0 then
							rocks(at, 0.6, 3)
						end
						VFX.PlaySound("AirBullet", at, 0.7)
					end)
				end)
			end
		end
	end

	-- R: DANGER SENSE
	function Effects.DangerCounter(char, _data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local window = (ability and ability.Window) or 1
		VFX.Pose(char, "DangerStance", window)
		VFX.PlaySound("CounterReady", root.Position, 0.9)
		local head = char:FindFirstChild("Head")
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < window and char:GetAttribute("Countering") ~= false and root.Parent do
				local c = head and head.Position or root.Position + UP * 1.5
				for _ = 1, 2 do
					local a = rand(0, math.pi * 2)
					local dir = Vector3.new(math.cos(a), rand(-0.2, 0.9), math.sin(a)).Unit
					local line = newPart(Vector3.new(0.1, 0.1, 1.4), CFrame.lookAt(c + dir * 1.2, c + dir * 3), PV.GREEN, Enum.Material.Neon)
					tween(line, 0.12, { CFrame = CFrame.lookAt(c + dir * 2.4, c + dir * 4), Transparency = 1 })
					cleanup(line, 0.14)
				end
				task.wait(0.06)
			end
		end)
	end
	function Effects.DangerFlash(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local from = typeof(data.From) == "Vector3" and data.From
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if from then
			for _ = 1, 4 do
				bolt(from + UP, 3, PV.GREEN)
			end
			afterimage(char, PV.GREEN, 0.35)
		end
		local mine = me()
		if target and (mine == char or mine == target) then
			local tr = target:FindFirstChild("HumanoidRootPart")
			if tr then
				VFX.Cinematic(target, SHOTS.FlashCut, { Title = "DANGER SENSE", Color = PV.GREEN, Own = mine == char, Face = tr.Position + (typeof(data.Look) == "Vector3" and data.Look or tr.CFrame.LookVector) * 10 })
			end
		end
		VFX.PlaySound("FlashStep", from or at, 0.9)
		task.wait(0.16)
		if at then
			PV.gather(at + UP * 0.5, PV.GREEN, 0.06)
		end
		if char.Parent then
			VFX.Motion(char, "FlashKick")
		end
		task.wait(0.1)
		if at then
			local d = typeof(data.Look) == "Vector3" and data.Look or UP
			shockDisc(at + d * 3 + UP, d, 2, 18, 0.25, PV.GREEN, 6)
			sparks(at + d * 3 + UP, 1.2, PV.CORE, PV.GREEN, 24)
			VFX.PlaySound("FlashKick", at, 1)
			VFX.ShakeAt(at, 2, 70, 0.3)
		end
	end

	-- a ghostly figure standing (one of the eight), faded in and out
	function PV.ghost(cf, color, life, scale)
		scale = scale or 1
		local m = Instance.new("Model")
		m.Name = "Vestige"
		m.Parent = folder
		local parts = {}
		local function p(size, off)
			local part = newPart(size * scale, cf * off, color, Enum.Material.ForceField, nil, m)
			part.Transparency = 1
			table.insert(parts, part)
		end
		p(Vector3.new(2, 2, 1), CFrame.new(0, 3, 0))
		p(Vector3.new(1.2, 1.2, 1.2), CFrame.new(0, 4.6 * scale, 0))
		p(Vector3.new(1, 2, 1), CFrame.new(1.5 * scale, 3, 0))
		p(Vector3.new(1, 2, 1), CFrame.new(-1.5 * scale, 3, 0))
		p(Vector3.new(1, 2, 1), CFrame.new(0.5 * scale, 1, 0))
		p(Vector3.new(1, 2, 1), CFrame.new(-0.5 * scale, 1, 0))
		for _, part in parts do
			tween(part, 0.35, { Transparency = 0.25 })
			tween(part, 0.4, { Transparency = 1 }, nil, nil, math.max(life - 0.4, 0.35))
		end
		cleanup(m, life + 0.1)
		return m
	end

	-- a colossal ghostly fist (palm, four fingers curled, the thumb over them)
	function PV.fist(cf, size, color)
		local m = Instance.new("Model")
		m.Name = "VestigeFist"
		m.Parent = folder
		local parts = {}
		local function p(sz, off)
			local part = newPart(sz * size, cf * CFrame.new(off.Position * size) * off.Rotation, color, Enum.Material.ForceField, nil, m)
			part.Transparency = 0.15
			table.insert(parts, { part = part, off = CFrame.new(off.Position * size) * off.Rotation })
		end
		p(Vector3.new(1, 0.9, 0.9), CFrame.new(0, 0, 0))
		for i = 0, 3 do
			p(Vector3.new(0.24, 0.3, 0.5), CFrame.new(-0.36 + i * 0.24, -0.52, -0.22))
		end
		p(Vector3.new(0.3, 0.26, 0.5), CFrame.new(-0.5, -0.2, -0.3) * CFrame.Angles(0, 0, math.rad(-30)))
		p(Vector3.new(0.9, 1.4, 0.85), CFrame.new(0, 1.1, 0.02))
		return {
			model = m,
			set = function(newCf)
				for _, e in parts do
					e.part.CFrame = newCf * e.off
				end
			end,
			gone = function(t)
				for _, e in parts do
					tween(e.part, t, { Transparency = 1, Size = e.part.Size * 1.3 })
				end
				cleanup(m, t + 0.05)
			end,
		}
	end

	-- 4: VESTIGE SMASH
	function Effects.VestigeSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local ult = char:GetAttribute("UltActive") == true
		local spot = aimGround(root, data, ult and 130 or (ability.Range or 95))
		local radius = ult and 30 or (ability.Radius or 22)
		local delay = ability.Delay or 0.85
		VFX.Pose(char, "VestigeCall", delay)
		VFX.PlaySound("VestigeCall", root.Position, 1)
		-- the ones before him, behind him
		local behind = CFrame.lookAt(root.Position, root.Position + d)
		for i = 1, ult and 8 or 4 do
			local side = (i % 2 == 0) and 1 or -1
			local row = math.ceil(i / 2)
			PV.ghost(behind * CFrame.new(side * row * 2.6, -3, row * 2.4), i % 2 == 0 and PV.GREEN or PV.SUN, delay + 0.8, 1.1)
		end
		landingMarker(spot, delay)
		local size = radius * 0.9
		local fist = PV.fist(CFrame.new(spot + UP * 110) * CFrame.Angles(math.rad(180), 0, 0), size, PV.SUN)
		local t0 = os.clock()
		while os.clock() - t0 < delay do
			local k = math.clamp((os.clock() - t0) / delay, 0, 1) ^ 2
			fist.set(CFrame.new(spot + UP * (110 * (1 - k) + size * 0.55)) * CFrame.Angles(math.rad(180), 0, 0))
			task.wait()
		end
		fist.set(CFrame.new(spot + UP * size * 0.55) * CFrame.Angles(math.rad(180), 0, 0))
		fist.gone(0.5)
		if char.Parent then
			VFX.Pose(char, "VestigeSlam", 0.4)
		end
		if nearCamera(spot, 160) then
			VFX.ImpactFrame(0.1)
			VFX.Hooks.Flash(PV.SUN, 0.3)
		end
		shockDisc(spot + UP * 0.5, UP, radius, radius * 4.5, 0.5, PV.SUN)
		shockDisc(spot + UP * 0.5, UP, radius * 0.6, radius * 3, 0.35, Color3.new(1, 1, 1))
		billboardRing(spot + UP * 3, 4, radius * 3, PV.GREEN, 12, 0.45)
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			dustPuffs(spot + Vector3.new(math.cos(a), 0, math.sin(a)) * radius * rand(0.6, 1.1), 2, 3, Color3.fromRGB(206, 196, 186), 1.4, true)
		end
		streaks(spot, UP, 30, radius * 0.5, 18, 70, PV.SUN, 0.5)
		rocks(spot, 2.8, 22)
		groundMark(spot, radius * 0.9, Color3.fromRGB(52, 46, 44), 8)
		VFX.PlaySound("USSImpact", spot, 1.2)
		VFX.ShakeAt(spot, 4, 220, 0.8)
	end

	-- ULT 2: FLASH STEP CHAIN
	function Effects.FlashStepChain(char)
		local root = charParts(char)
		if not root then
			return
		end
		afterimage(char, PV.GREEN, 0.4)
		for _ = 1, 6 do
			bolt(root.Position, 4, PV.GREEN)
		end
		VFX.PlaySound("FlashStep", root.Position, 1)
		PV.hideWhile(char, 4)
	end
	function Effects.FlashChainHit(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not tr or not at then
			return
		end
		local look = typeof(data.Look) == "Vector3" and data.Look or tr.CFrame.LookVector
		local mine = me()
		if mine == char or mine == target then
			VFX.CancelCinematic()
			VFX.Cinematic(target, SHOTS.FlashCut, { Title = "FLASH STEP " .. tostring(data.Index or 1) .. "/" .. tostring(data.Count or 1), Color = PV.GREEN, Own = mine == char, Face = tr.Position + look * 10 })
		end
		PV.gather(at + UP * 0.5, PV.GREEN, 0.05)
		-- a green afterimage of him kicking, there and gone
		if char.Parent then
			VFX.Pose(char, "FlashKick", 0.2)
			task.delay(0.04, function()
				if char.Parent then
					afterimage(char, PV.GREEN, 0.35)
				end
			end)
		end
		shockDisc(tr.Position, look, 1, 12, 0.2, PV.GREEN, 3)
		sparks(tr.Position, 0.9, PV.CORE, PV.GREEN, 14)
		VFX.PlaySound("FlashKick", tr.Position, 0.8)
		VFX.ShakeAt(tr.Position, 1.4, 60, 0.2)
	end
	function Effects.FlashChainEnd(char)
		local root = charParts(char)
		if not root then
			return
		end
		PV.hidden[char] = nil
		for _, d in char:GetDescendants() do
			if d:IsA("BasePart") or d:IsA("Decal") then
				d.LocalTransparencyModifier = 0
			end
		end
		VFX.Pose(char, "FlashCrouch", 0.4)
		shockDisc(root.Position, UP, 4, 40, 0.4, PV.GREEN)
		billboardRing(root.Position + UP, 3, 30, PV.CORE, 10, 0.35)
		for _ = 1, 10 do
			bolt(root.Position, 7, PV.GREEN)
		end
		if me() == char then
			VFX.Hooks.Callout("SMASH!!", PV.GREEN)
		end
		VFX.PlaySound("Smash", root.Position, 1)
		VFX.ShakeAt(root.Position, 3, 120, 0.4)
	end
	function Effects.FlashChainWhiff(char)
		local root = charParts(char)
		if root then
			for _ = 1, 3 do
				bolt(root.Position, 3, PV.GREEN)
			end
		end
	end

	-- ULT 3: 1,000,000%: DELAWARE DETROIT SMASH, the eight at his back
	function Effects.VestigeDDS(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.5, (ability.Charge or 1.5) + 0.3)
		end
		cinematicFor(char, "VestigeDDS", isLocal, ability.Name or "DELAWARE DETROIT SMASH", PV.GREEN)
		local charge = ability.Charge or 1.5
		VFX.Pose(char, "PunchCharge", charge)
		VFX.PlaySound("MillionCharge", root.Position, 1)
		local behind = CFrame.lookAt(root.Position, root.Position + d)
		for i = 1, 8 do
			local side = (i % 2 == 0) and 1 or -1
			local row = math.ceil(i / 2)
			task.delay(i * 0.09, function()
				PV.ghost(behind * CFrame.new(side * row * 2.8, -3, row * 3), i == 8 and PV.SUN or PV.GREEN, charge - i * 0.09 + 0.9, 1.15)
			end)
		end
		local t0 = os.clock()
		while os.clock() - t0 < charge and root.Parent do
			bolt(handPos(char, true), 2.4, PV.GREEN)
			bolt(root.Position + UP, 3.5, rng:NextNumber() < 0.5 and PV.SUN or PV.CORE)
			task.wait(0.05)
		end
		if not root.Parent then
			return
		end
		VFX.Pose(char, "PunchR", 0.8)
		if isLocal then
			VFX.Hooks.Callout("DELAWARE DETROIT SMASH!!", PV.SUN)
		end
		local origin = root.Position + d * 3 + UP
		if nearCamera(origin, 260) then
			VFX.ImpactFrame(0.14)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.45)
		end
		windBlast(origin, d, 3)
		for i = 1, 8 do
			task.delay(i * 0.04, function()
				shockDisc(origin, d, 10, 70, 0.7, i % 2 == 0 and PV.GREEN or WIND, 200)
			end)
		end
		streaks(origin, d, 60, 18, 24, 220, WIND, 0.8)
		streaks(origin, d, 30, 10, 20, 180, PV.GREEN, 0.7)
		local right = d:Cross(UP)
		for s = 12, 250, 16 do
			task.delay(s / 400, function()
				local p = groundPoint(origin + d * s + right * rand(-20, 20))
				dustPuffs(p, 2 + s / 90, 4, Color3.fromRGB(206, 196, 186), 1.4, true)
				if s % 32 == 12 then
					rocks(p, 2, 6)
				end
			end)
		end
		VFX.PlaySound("MillionSmash", origin, 1.2)
		VFX.ShakeAt(origin, 5, 320, 1)
	end

	-----------------------------------------------------------------------
	-- PRIME ALL MIGHT
	-----------------------------------------------------------------------

	-- 1: MISSOURI SMASH - his own machine carries him (the lariat)
	function Effects.MissouriSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		local t = ability.Time or 0.3
		VFX.Pose(char, "Lariat", t + 0.25)
		VFX.PlaySound("HeavySwing", root.Position, 1)
		if isLocal then
			face(root, d)
			task.delay(0.1, function()
				if root.Parent then
					dash(root, d * ((ability.Range or 60) / t), t)
				end
			end)
		end
		task.wait(0.1)
		local t0 = os.clock()
		while os.clock() - t0 < t and root.Parent do
			streaks(root.Position, -d, 3, 1.5, 7, 10, WIND, 0.2)
			shockDisc(root.Position + d * 3, d, 3, 8, 0.12, WIND)
			task.wait(0.04)
		end
	end
	function Effects.SonicBoom(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
		shockDisc(pos, d, 4, 34, 0.35, WIND, 10)
		shockDisc(pos, d, 2, 20, 0.25, Color3.new(1, 1, 1), 6)
		billboardRing(pos, 3, 26, Color3.new(1, 1, 1), 8, 0.3)
		dustPuffs(groundPoint(pos), 1.4, 8, Color3.fromRGB(206, 196, 186), 1, true)
		VFX.PlaySound("SonicBoom", pos, 1)
		VFX.ShakeAt(pos, 2.4, 100, 0.35)
	end

	-- 2: TEXAS SMASH: HURRICANE - a twister lying down the street
	function Effects.HurricaneSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local ult = char:GetAttribute("UltActive") == true
		local range = ult and 200 or (ability.Range or 140)
		local width = ult and 36 or (ability.Width or 26)
		local time = ult and 1.3 or (ability.Time or 1.1)
		VFX.Pose(char, "PunchCharge", 0.32)
		VFX.PlaySound("DetroitCharge", root.Position, 0.8)
		task.wait(0.3)
		if not root.Parent then
			return
		end
		VFX.Pose(char, "PunchR", 0.6)
		local origin = root.Position + d * 3 + UP * 2
		windBlast(origin, d, 2)
		shockDisc(origin, d, 6, 30, 0.4, WIND, 30)
		VFX.PlaySound("Twister", origin, 1)
		VFX.ShakeAt(origin, 2.5, 150, 0.6)
		local basis = CFrame.lookAt(origin, origin + d)
		local t0 = os.clock()
		local spin = 0
		while os.clock() - t0 < time do
			local k = math.min(1, (os.clock() - t0) / time + 0.25)
			spin += 0.9
			for _ = 1, 4 do
				local along = rand(4, range * k)
				local a = spin + rand(0, math.pi * 2)
				local r = width * 0.45 * rand(0.5, 1)
				local p = basis * CFrame.new(math.cos(a) * r, math.sin(a) * r * 0.7 + 2, -along)
				local tangent = (basis * CFrame.new(math.cos(a + 0.6) * r, math.sin(a + 0.6) * r * 0.7 + 2, -along - 4)).Position - p.Position
				local s = newPart(Vector3.new(0.3, 0.3, rand(4, 8)), CFrame.lookAt(p.Position, p.Position + tangent), WIND, Enum.Material.Neon)
				s.Transparency = 0.2
				tween(s, 0.25, { CFrame = CFrame.lookAt(p.Position + tangent * 1.4, p.Position + tangent * 2.4), Transparency = 1 })
				cleanup(s, 0.3)
			end
			if rng:NextNumber() < 0.5 then
				shockDisc((basis * CFrame.new(0, 2, -rand(8, range * k))).Position, d, width * 0.5, width * 0.9, 0.3, WIND)
				dustPuffs(groundPoint((basis * CFrame.new(rand(-width, width) * 0.4, 0, -rand(8, range * k))).Position), 1.4, 2, Color3.fromRGB(206, 196, 186), 1, true)
			end
			task.wait(0.05)
		end
	end

	-- 3: DETROIT SMASH: PRIME
	function Effects.PrimeDetroit(char, data, isLocal)
		task.spawn(Effects.DetroitSmash, char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		task.wait(0.4)
		if not root.Parent then
			return
		end
		local origin = root.Position + d * 3 + UP
		if nearCamera(origin, 140) then
			VFX.ImpactFrame(0.08)
		end
		for i = 1, 4 do
			task.delay(i * 0.05, function()
				shockDisc(origin, d, 14, 60, 0.6, i % 2 == 0 and PV.GOLD or WIND, 120)
			end)
		end
		streaks(origin, d, 40, 12, 18, 130, WIND, 0.6)
	end

	-- R: I AM HERE - up and out of sight
	function Effects.IAmHereLeap(char)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "FlashCrouch", 0.22)
		local g = groundPoint(root.Position)
		task.wait(0.2)
		VFX.Pose(char, "Skydive", 0.6)
		shockDisc(g + UP * 0.5, UP, 4, 40, 0.4, WIND)
		billboardRing(g + UP * 2, 3, 26, PV.GOLD, 8, 0.35)
		dustPuffs(g, 1.8, 10, Color3.fromRGB(206, 196, 186), 1.2, true)
		rocks(g, 1.6, 10)
		groundMark(g, 6, Color3.fromRGB(52, 46, 44), 5)
		streaks(g, UP, 24, 3, 20, 120, WIND, 0.5)
		VFX.PlaySound("ColoradoLeap", g, 1)
		VFX.ShakeAt(g, 2.5, 120, 0.4)
	end

	-- and down: the look up into the sun (for whoever's under it), then the fall
	function Effects.MeteorFall(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local look, fall = tonumber(data.Look) or 0, tonumber(data.Fall) or 0.42
		local mine = me()
		if tr and (mine == char or mine == target) then
			VFX.Cinematic(target, SHOTS.MeteorLook, { Title = "I AM HERE!", Color = PV.GOLD, Own = mine == char, Face = tr.Position + (typeof(data.Dir) == "Vector3" and -data.Dir or tr.CFrame.LookVector) * 10 })
			PV.drain(look, 0.5)
		end
		if tr then
			VFX.Hitstop(target, look)
			VFX.Pose(target, "LookUp", look + 0.2)
		end
		landingMarker(pos, look + fall)
		-- (round 76) "I AM HERE!", "HERE!" on the landing
		VFX.Voice("IAmHere", pos, look + fall)
		-- the glint in the sky: him, against the sun
		local fd = typeof(data.Dir) == "Vector3" and data.Dir or Vector3.new(0, 0, -1)
		local sun = newPart(Vector3.one * 0.1, CFrame.new(pos + UP * 104 - fd * 12), PV.SUN)
		sun.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(10, 10)
		bb.LightInfluence = 0
		bb.MaxDistance = 2000
		bb.Adornee = sun
		bb.Parent = sun
		local glow = Instance.new("Frame")
		glow.AnchorPoint = Vector2.new(0.5, 0.5)
		glow.Position = UDim2.fromScale(0.5, 0.5)
		glow.Size = UDim2.fromScale(0.3, 0.3)
		glow.BackgroundColor3 = PV.SUN
		glow.BorderSizePixel = 0
		glow.Parent = bb
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0.5, 0)
		corner.Parent = glow
		tween(glow, math.max(look, 0.2), { Size = UDim2.fromScale(1, 1) }, Enum.EasingStyle.Quad)
		tween(glow, 0.3, { BackgroundTransparency = 1 }, nil, nil, math.max(look, 0.2))
		cleanup(sun, math.max(look, 0.2) + 0.35)
		if look > 0 then
			VFX.PlaySound("Ringing", pos, 0.5)
		end
		task.wait(look)
		-- the fall: the air in front of him going white hot
		VFX.PlaySound("MeteorFall", pos, 1)
		VFX.Pose(char, "MeteorDive", fall + 0.1)
		local root = charParts(char)
		local t0 = os.clock()
		while os.clock() - t0 < fall and root and root.Parent do
			shockDisc(root.Position - UP * 3, -UP, 3, 8, 0.12, PV.SUN)
			streaks(root.Position, UP, 3, 1.5, 12, 16, WIND, 0.2)
			task.wait(0.04)
		end
		-- the landing
		VFX.Pose(char, "Land", 0.5)
		if mine == char or mine == target or nearCamera(pos, 160) then
			VFX.ImpactFrame(0.12)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.35)
		end
		shockDisc(pos + UP * 0.5, UP, 6, 110, 0.6, WIND)
		shockDisc(pos + UP * 0.5, UP, 4, 60, 0.4, PV.GOLD)
		billboardRing(pos + UP * 3, 4, 70, PV.SUN, 12, 0.45)
		for i = 1, 16 do
			local a = i / 16 * math.pi * 2
			dustPuffs(pos + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(8, 26), 2.4, 3, Color3.fromRGB(206, 196, 186), 1.6, true)
		end
		streaks(pos, UP, 36, 8, 22, 120, WIND, 0.6)
		rocks(pos, 3, 26)
		groundMark(pos, 16, Color3.fromRGB(52, 46, 44), 9)
		VFX.PlaySound("ColoradoImpact", pos, 1.2)
		VFX.PlaySound("MightUSSImpact", pos, 0.8)
		VFX.ShakeAt(pos, 4.5, 260, 0.9)
		if char.Parent then
			local line = Config.Voice and Config.Voice.IAmHere
			VFX.SpeechBubble(char, line and line.Bubble or "I AM HERE!", 1.6)
		end
	end

	-- 4: PLUS ULTRA (the USJ)
	function Effects.PlusUltraUSJ(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "Grab", 0.3)
		VFX.PlaySound("HeavySwing", root.Position, 0.8)
	end
	function Effects.USJWhiff(char)
		VFX.Pose(char, "PunchR", 0.3)
	end
	function Effects.USJRush(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local root = charParts(char)
		if not tr or not root then
			return
		end
		local hits, interval = tonumber(data.Hits) or 24, tonumber(data.Interval) or 0.05
		local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
		local mine = me()
		if mine == char or mine == target then
			VFX.Cinematic(char, SHOTS.USJ, { Title = "PLUS ULTRA!", Color = PV.GOLD, Own = mine == char, Face = root.Position + d * 10 })
		end
		if mine == char then
			VFX.Hooks.Callout("PLUS...", PV.GOLD)
		end
		task.wait(0.25)
		for i = 1, hits do
			if not root.Parent or not tr.Parent then
				return
			end
			VFX.Pose(char, i % 2 == 0 and "USJPunchL" or "USJPunchR", interval * 1.6)
			-- fists everywhere at once
			for _ = 1, 2 do
				local p = tr.Position + d * -1.2 + Vector3.new(rand(-1.4, 1.4), rand(-0.6, 2), rand(-1.4, 1.4))
				local fistGhost = newPart(Vector3.new(1.3, 1.3, 1.6), CFrame.lookAt(p - d * 2.5, p), PV.GOLD, Enum.Material.Neon)
				fistGhost.Transparency = 0.3
				tween(fistGhost, 0.08, { CFrame = CFrame.lookAt(p, p + d), Transparency = 1 })
				cleanup(fistGhost, 0.1)
			end
			sparks(tr.Position - d, 0.5, Color3.new(1, 1, 1), PV.GOLD, 5)
			if i % 3 == 0 then
				shockDisc(tr.Position - d, d, 1, 9, 0.15, WIND, 2)
				VFX.PlaySound("Hit", tr.Position, 0.7)
			end
			if i % 6 == 0 then
				VFX.ShakeAt(tr.Position, 1.2, 60, 0.12)
			end
			task.wait(interval)
		end
	end
	function Effects.USJFinish(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "FinishUppercut", 0.7)
		local pos = tr and tr.Position or root.Position + root.CFrame.LookVector * 4
		local mine = me()
		if mine == char then
			VFX.Hooks.Callout("ULTRAAAA!!", PV.GOLD)
		end
		if mine == char or mine == target or nearCamera(pos, 120) then
			VFX.ImpactFrame(0.14)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.4)
		end
		windBlast(pos, UP, 2.6)
		for i = 1, 5 do
			task.delay(i * 0.06, function()
				shockDisc(pos + UP * (i * 6), UP, 6, 40 + i * 10, 0.5, WIND)
			end)
		end
		shockDisc(pos + UP * 70, UP, 20, 180, 1.2, Color3.fromRGB(236, 240, 246))
		streaks(pos, UP, 40, 4, 24, 160, WIND, 0.7)
		billboardRing(pos, 3, 40, PV.GOLD, 10, 0.4)
		VFX.PlaySound("MightImpact", pos, 1.2)
		VFX.ShakeAt(pos, 4, 200, 0.7)
	end

	-- ULT 3: UNITED STATES OF SMASH (his own, bigger)
	function Effects.PrimeUSS(char, data, isLocal, ability)
		Effects.UnitedStatesSmash(char, data, isLocal, ability)
	end

