	POSES.StingyEyes = { RightArm = { 70, 0, -20 }, LeftArm = { 30, 0, 24 }, Waist = { -16, 8, 0 }, Neck = { -8, -6, 0 }, RightLeg = { -12, 0, 6 }, LeftLeg = { 16, 0, 4 } }
