		{ T = 0.3, From = { V(1.6, 1.9, -3.6), V(0, 1.7, 0) }, To = { V(1.2, 1.8, -2.9), V(0, 1.7, 0) }, Fov = { 46, 36 } },
		{ T = 0.45, Cut = true, From = { V(-5, 2.5, -9), V(0, 3, 1.5) }, To = { V(-8, 5, -16), V(0, 4, 1.5) }, Fov = { 60, 78 }, Style = Enum.EasingStyle.Quad },
