	SHOTS.RoadRoller = {
		{ T = 0.55, Follow = true, From = { V(3, -4, -8), "root" }, To = { V(5, -8, -14), "root" }, Fov = { 60, 74 } },
		{ T = 0.4, Cut = true, Follow = true, From = { V(-16, 8, -18), "root" }, To = { V(-18, 5, -20), "root" }, Fov = { 62, 66 } },
		{ T = 1.25, Cut = true, Follow = true, From = { V(6, 3, -6), "root" }, To = { V(5, 2.4, -4.6), "root" }, Fov = { 56, 46 } },
		{ T = 0.8, Cut = true, Follow = true, From = { V(0, -1.5, -7), "root" }, To = { V(0, -2.5, -9), "root" }, Fov = { 52, 64 } },
	}

	local function me()
		return Players.LocalPlayer and Players.LocalPlayer.Character
	end

	-- is the time he stopped still stopped? (his knives wait on it)
	function DV.stoppedBy(char)
		local s = char and DV.stops[char]
		return s ~= nil and not s.Done and os.clock() < s.Until + 1.5
	end

	-- the colour of stopped time on this screen
	function DV.grade(on)
		local cc = Lighting:FindFirstChild("TimeStopCC")
		if on then
			if not cc then
				cc = Instance.new("ColorCorrectionEffect")
				cc.Name = "TimeStopCC"
				cc.Parent = Lighting
			end
			cc.Enabled = true
			-- the negative first...
			tween(cc, 0.18, { TintColor = DV.NEG, Saturation = 0.4, Contrast = 0.9, Brightness = -0.08 })
			-- ...then the world goes grey and still
			task.delay(0.55, function()
				if cc.Parent then
					tween(cc, 0.4, { TintColor = Color3.fromRGB(236, 226, 206), Saturation = -0.88, Contrast = 0.2, Brightness = -0.04 })
				end
			end)
		elseif cc then
			tween(cc, 0.18, { TintColor = DV.NEG, Saturation = 0.3, Contrast = 0.7 })
			task.delay(0.2, function()
				if cc.Parent then
					tween(cc, 0.35, { TintColor = Color3.new(1, 1, 1), Saturation = 0, Contrast = 0, Brightness = 0 })
					cleanup(cc, 0.4)
				end
			end)
		end
	end

	-- a body's animation tracks held (or let go)
	function DV.holdTracks(model, on)
		local hum = model and model:FindFirstChildOfClass("Humanoid")
		local animator = hum and hum:FindFirstChildOfClass("Animator")
		if not animator then
			return
		end
		pcall(function()
			for _, track in animator:GetPlayingAnimationTracks() do
				track:AdjustSpeed(on and 0 or 1)
			end
		end)
	end

	-- R: ZA WARUDO! (the call, and The World throwing its arms wide)
	function Effects.ZaWarudo(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "ZaWarudo", 1.2)
		local st = CDV and CDV.act(char, "rage", 1.3)
		if st then
			CDV.shout(st, "ZA WARUDO!!", 9, 1.3)
		end
		VFX.SpeechBubble(char, (Config.Voice.ZaWarudo or {}).Bubble or "ZA WARUDO!", 1.4)
		VFX.Voice("ZaWarudo", root)
		VFX.PlaySound("ZaWarudo", root.Position, 1)
		if isLocal then
			VFX.Cinematic(char, SHOTS.ZaWarudo, { Title = "ZA WARUDO!", Color = DV.GOLD, Own = true })
		end
	end

	-- time stops
	function Effects.TimeStop(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local dur = tonumber(data.Duration) or 5
		local radius = tonumber(data.Radius) or 220
		local stop = { Until = os.clock() + dur, Frozen = type(data.Frozen) == "table" and data.Frozen or {}, Done = false }
		DV.stops[char] = stop
		local c = root.Position
		-- the sphere rolls out from him... and back
		local ball = newPart(Vector3.one * 2, CFrame.new(c), DV.NEG, Enum.Material.ForceField, Enum.PartType.Ball)
		ball.Transparency = 0.1
		tween(ball, 0.5, { Size = Vector3.one * math.min(radius * 2, 400) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(ball, 0.35, { Size = Vector3.one * 2, Transparency = 0.6 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.55)
		cleanup(ball, 0.95)
		local core = newPart(Vector3.one * 1, CFrame.new(c), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(core, 0.2, { Size = Vector3.one * 10, Transparency = 1 })
		cleanup(core, 0.25)
		billboardRing(c + UP * 2, 3, 60, DV.NEG, 12, 0.5)
		VFX.PlaySound("TimeStop", c, 1)
		-- this screen: inside it, or his
		local mine = me()
		local mr = mine and mine:FindFirstChild("HumanoidRootPart")
		local inside = mine == char or (mr ~= nil and (mr.Position - c).Magnitude <= radius)
		stop.Graded = inside
		if inside then
			DV.grade(true)
			VFX.Hooks.Callout(mine == char and "TIME HAS STOPPED" or "...TIME HAS STOPPED", DV.GOLD)
		end
		-- everyone caught, frozen mid-move
		for _, m in stop.Frozen do
			if typeof(m) == "Instance" and m.Parent then
				VFX.Hitstop(m, dur + 0.1)
				DV.holdTracks(m, true)
			end
		end
		-- the clock ticking; he counts the seconds
		task.spawn(function()
			local n = 0
			while not stop.Done and os.clock() < stop.Until do
				task.wait(1)
				if stop.Done or os.clock() > stop.Until + 0.05 then
					break
				end
				n += 1
				VFX.PlaySound("ClockTick", c, 0.9)
				if me() == char then
					VFX.Hooks.Callout(n == 1 and "1 SECOND HAS PASSED" or (n .. " SECONDS HAVE PASSED"), DV.GOLD)
				end
			end
		end)
	end

	-- ...and moves again
	function Effects.TimeResume(char, data)
		local stop = DV.stops[char]
		if stop then
			stop.Done = true
			DV.stops[char] = nil
		end
		local root = charParts(char)
		if root then
			VFX.SpeechBubble(char, (Config.Voice.TimeResume or {}).Bubble or "TOKI WA UGOKIDASU...", 1.6)
			VFX.Voice("TimeResume", root)
			VFX.PlaySound("TimeResume", root.Position, 1)
			shockDisc(root.Position, UP, 2, 60, 0.4, DV.NEG)
		end
		local still = false
		for _, s in DV.stops do
			if not s.Done and s.Graded then
				still = true
			end
		end
		if (not stop or stop.Graded) and not still then
			DV.grade(false)
		end
		for _, m in type(data.Frozen) == "table" and data.Frozen or (stop and stop.Frozen) or {} do
			if typeof(m) == "Instance" then
				DV.holdTracks(m, false)
				local list = DV.marks[m]
				DV.marks[m] = nil
				local tr = m:FindFirstChild("HumanoidRootPart")
				for _, p in list or {} do
					if p.Parent then
						sparks(p.Position, 0.7, Color3.new(1, 1, 1), DV.GOLD, 8)
						p:Destroy()
					end
				end
				if list and #list > 0 and tr then
					billboardRing(tr.Position, 2, 16, DV.GOLD, 8, 0.25)
					VFX.PlaySound("HeavyHit", tr.Position, 1)
				end
			end
		end
	end

	-- a hit on someone in stopped time: it hangs on them, gold, until it lands
	function Effects.TimeHit(_, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		if not tr then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or tr.Position + tr.CFrame.LookVector * 3
		local toward = from - tr.Position
		toward = toward.Magnitude > 0.1 and toward.Unit or tr.CFrame.LookVector
		local at = tr.Position + toward * 1.1 + Vector3.new(rand(-0.8, 0.8), rand(-0.6, 1.4), rand(-0.8, 0.8))
		local size = data.Heavy and 1.1 or 0.6
		local star = newPart(Vector3.new(size, size, 0.1), CFrame.lookAt(at, at + toward) * CFrame.Angles(0, 0, rand(0, 3)), DV.GOLD, Enum.Material.Neon)
		local star2 = newPart(Vector3.new(size * 0.4, size * 1.8, 0.08), star.CFrame * CFrame.Angles(0, 0, math.rad(45)), Color3.new(1, 1, 1), Enum.Material.Neon)
		cleanup(star, 14)
		cleanup(star2, 14)
		local list = DV.marks[target] or {}
		DV.marks[target] = list
		table.insert(list, star)
		table.insert(list, star2)
		VFX.PlaySound("Hit", at, 0.35)
	end
	function Effects.TimeHits(_, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		if tr then
			sparks(tr.Position, 1.2, Color3.new(1, 1, 1), DV.GOLD, 10 + math.min(tonumber(data.Count) or 1, 20) * 2)
			shockDisc(tr.Position, UP, 2, 14, 0.25, DV.GOLD)
		end
	end

	-- 1: MUDA MUDA MUDA! (the rush, Crazy Diamond's frame in gold)
	function Effects.MudaRush(char, data, isLocal, ability)
		VFX.Pose(char, "StandUser", 0.7)
		local root = charParts(char)
		if not root or not CDV then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local hits, interval = ability.Hits or 16, ability.Interval or 0.075
		if char:GetAttribute("UltActive") then
			hits, interval = 24, 0.06
		end
		local total = 0.15 + hits * interval
		local st = CDV.act(char, "barrage", total)
		if not st then
			return
		end
		CDV.shout(st, char:GetAttribute("UltActive") and "MUDA MUDA MUDA MUDA!!" or "MUDA MUDA MUDA!", 8, total)
		for k = 1, hits do
			task.delay(0.15 + (k - 1) * interval, function()
				if not root.Parent then
					return
				end
				VFX.PlaySound("Dora", root.Position, 0.55)
				if k % 2 == 0 then
					local front = root.Position + flatten(root.CFrame.LookVector, root) * 4.5 + UP * 0.8
					sparks(front + Vector3.new(rand(-1, 1), rand(-0.6, 1), rand(-1, 1)), 0.5, Color3.new(1, 1, 1), DV.GOLD, 5)
				end
				if k % 6 == 0 then
					CDV.shout(st, "MUDA!", 4, 0.4)
				end
			end)
		end
		task.wait(total)
		if not root.Parent then
			return
		end
		CDV.act(char, "punchR", 0.45)
		CDV.shout(st, "MUDA!!", 5, 0.8)
		local dd = flatten(root.CFrame.LookVector, root)
		local fist = root.Position + dd * 5 + UP
		VFX.PlaySound("DoraFinish", fist, 1)
		shockDisc(fist, dd, 2, 16, 0.3, WIND, 8)
		billboardRing(fist, 2, 18, DV.GOLD, 6, 0.3)
		streaks(fist, dd, 12, 2, 8, 22, WIND, 0.3)
		VFX.ShakeAt(fist, 2.4, 80, 0.3)
		if nearCamera(fist, 60) then
			VFX.ImpactFrame(0.08)
		end
	end

	-- 2: KNIVES
	function Effects.KnifeVolley(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "DaggerShot")
		if root then
			VFX.PlaySound("KnifeThrow", root.Position, 1)
		end
	end
	-- one knife: in stopped time it stops a few studs out and waits
	function Effects.DioKnife(char, data)
		local from, to = data.From, data.To
		local TWV = VFX.TW
		if typeof(from) ~= "Vector3" or typeof(to) ~= "Vector3" or not TWV then
			return
		end
		local v = to - from
		local dist = v.Magnitude
		if dist < 0.5 then
			return
		end
		local d = v.Unit
		local speed = tonumber(data.Speed) or 200
		local k = TWV.knife(CFrame.lookAt(from, to))
		task.spawn(function()
			local start = from
			if data.Stopped and DV.stoppedBy(char) then
				-- out a few studs, then it hangs there
				local stopAt = from + d * math.min(dist * 0.5, rand(3.5, 7))
				local t0 = os.clock()
				while os.clock() - t0 < 0.07 do
					k.set(CFrame.lookAt(from:Lerp(stopAt, (os.clock() - t0) / 0.07), to))
					task.wait()
				end
				k.set(CFrame.lookAt(stopAt, to))
				local held = os.clock()
				while DV.stoppedBy(char) and os.clock() - held < 12 do
					task.wait(0.05)
				end
				start = stopAt
			end
			local left = (to - start).Magnitude
			local time = math.clamp(left / speed, 0.04, 0.8)
			local t0 = os.clock()
			while os.clock() - t0 < time do
				local a = (os.clock() - t0) / time
				k.set(CFrame.lookAt(start:Lerp(to, a), to) * CFrame.Angles(0, 0, a * 20))
				task.wait()
			end
			k.set(CFrame.lookAt(to - d * 0.3, to))
			if typeof(data.Hit) == "Instance" then
				sparks(to, 0.5, Color3.new(1, 1, 1), DV.GOLD, 5)
				VFX.PlaySound("KnifeHit", to, 0.8)
				k.gone(0.1)
			else
				task.delay(1.2, k.gone, 0.3)
			end
		end)
	end

	-- ULT 2: KNIVES - NOWHERE TO RUN: a ring of them, hanging, then all in
	function Effects.KnifeRing(char, data, isLocal)
		Effects.KnifeVolley(char, data, isLocal)
	end
	function Effects.KnifeRingSet(char, data)
		local center = typeof(data.Pos) == "Vector3" and data.Pos
		local TWV = VFX.TW
		if not center or not TWV then
			return
		end
		local n, ring = tonumber(data.Count) or 20, tonumber(data.Ring) or 7
		local knives = {}
		for i = 1, n do
			local a = i / n * math.pi * 2
			local y = ({ 0.4, 1.8, -0.5 })[i % 3 + 1]
			local p = center + Vector3.new(math.cos(a) * ring, y, math.sin(a) * ring)
			task.delay(i * 0.012, function()
				local kn = TWV.knife(CFrame.lookAt(p, center + UP * y * 0.3))
				knives[i] = { k = kn, p = p }
				sparks(p, 0.2, Color3.new(1, 1, 1), DV.GOLD, 2)
			end)
		end
		VFX.PlaySound("KnifeThrow", center, 1)
		task.wait(n * 0.012 + 0.05)
		if data.Stopped and DV.stoppedBy(char) then
			local held = os.clock()
			while DV.stoppedBy(char) and os.clock() - held < 12 do
				task.wait(0.05)
			end
			task.wait(0.05)
		else
			task.wait(math.max((tonumber(data.Hang) or 0.7) - n * 0.012, 0.1))
		end
		for _, e in knives do
			local t0 = os.clock()
			task.spawn(function()
				while os.clock() - t0 < 0.12 do
					e.k.set(CFrame.lookAt(e.p:Lerp(center, (os.clock() - t0) / 0.12), center))
					task.wait()
				end
				e.k.gone(0.1)
			end)
		end
		task.wait(0.12)
		sparks(center, 1.4, Color3.new(1, 1, 1), DV.GOLD, 30)
		billboardRing(center, 2, 18, DV.GOLD, 8, 0.25)
		VFX.PlaySound("KnifeHit", center, 1.2)
		VFX.ShakeAt(center, 1.6, 60, 0.25)
	end

	-- 3: VAMPIRE
	function Effects.VampireDrain(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "VampireHold", 0.45)
	end
	function Effects.VampireGrab(char, data)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target
		if not root then
			return
		end
		if not target then
			VFX.Pose(char, "VampireHold", 0.3)
			return
		end
		local time = tonumber(data.Time) or 1.2
		VFX.Pose(char, "VampireHold", time + 0.2)
		VFX.Pose(target, "Stagger", time)
		VFX.PlaySound("Drain", root.Position, 1)
		local head = target:FindFirstChild("Head")
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent and target.Parent do
			local from = (head and head.Position) or root.Position
			local to = handPos(char, true)
			for _ = 1, 2 do
				local drop = newPart(Vector3.one * 0.3, CFrame.new(from + rng:NextUnitVector() * 0.6), DV.RED, Enum.Material.Neon, Enum.PartType.Ball)
				tween(drop, 0.22, { CFrame = CFrame.new(to), Size = Vector3.one * 0.12 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(drop, 0.24)
			end
			if rng:NextNumber() < 0.3 and VFX.BLOOD then
				VFX.BLOOD.spray(from, rng:NextUnitVector(), 3, 6, 0.4)
			end
			sparks(root.Position + UP, 0.3, DV.RED, DV.GOLD, 2)
			task.wait(0.08)
		end
	end

	-- 4: SPACE RIPPER STINGY EYES
	function DV.eyes(char)
		local head = char:FindFirstChild("Head")
		if not head then
			return nil
		end
		local cf = head.CFrame
		local s = head.Size
		return (cf * CFrame.new(-s.X * 0.18, s.Y * 0.08, -s.Z * 0.5)).Position, (cf * CFrame.new(s.X * 0.18, s.Y * 0.08, -s.Z * 0.5)).Position
	end
	function Effects.SpaceRipper(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "StingyEyes", 0.6)
		VFX.PlaySound("PlasmaCharge", root.Position, 0.6)
		local t0 = os.clock()
		while os.clock() - t0 < 0.3 and root.Parent do
			local a, b = DV.eyes(char)
			if a then
				for _, p in { a, b } do
					local glint = newPart(Vector3.one * 0.25, CFrame.new(p), Color3.fromRGB(220, 240, 255), Enum.Material.Neon, Enum.PartType.Ball)
					tween(glint, 0.06, { Size = Vector3.one * 0.5, Transparency = 1 })
					cleanup(glint, 0.08)
				end
			end
			task.wait(0.04)
		end
	end
	function Effects.SpaceRipperBeam(char, data)
		local to = typeof(data.To) == "Vector3" and data.To
		if not to then
			return
		end
		local a, b = DV.eyes(char)
		a = a or (typeof(data.From) == "Vector3" and data.From) or to
		b = b or a
		for i, from in { a, b } do
			local tip = to + (i == 1 and -1 or 1) * (to - from):Cross(UP).Unit * 0.25
			local len = (tip - from).Magnitude
			local beam = newPart(Vector3.new(0.22, 0.22, len), CFrame.lookAt((from + tip) / 2, tip), Color3.fromRGB(226, 244, 255), Enum.Material.Neon)
			tween(beam, 0.25, { Size = Vector3.new(0.04, 0.04, len), Transparency = 1 }, nil, nil, 0.08)
			cleanup(beam, 0.35)
			billboardRing(from, 0.3, 3, Color3.new(1, 1, 1), 3, 0.15)
		end
		sparks(to, 0.9, Color3.new(1, 1, 1), Color3.fromRGB(160, 210, 255), 16)
		shockDisc(to, (to - a).Unit, 1, 8, 0.2, Color3.fromRGB(200, 230, 255))
		VFX.PlaySound("EyeBeam", a, 1)
		VFX.ShakeAt(to, 1.2, 60, 0.2)
	end

	-- the road roller: a yellow body, the steel drum up front, the cab, the
	-- rear wheels (origin: the middle of it, on the street)
	function DV.roller(cf)
		local m = Instance.new("Model")
		m.Name = "RoadRoller"
		m.Parent = folder
		local parts = {}
		local function p(size, off, color, material, shape)
			local part = newPart(size, cf * off, color, material or Enum.Material.SmoothPlastic, shape, m)
			table.insert(parts, { part = part, off = off })
			return part
		end
		p(Vector3.new(9, 4, 10), CFrame.new(0, 3.6, 1.6), DV.YELLOW)
		p(Vector3.new(10.4, 6.2, 6.2), CFrame.new(0, 3.1, -5.2), DV.STEEL, Enum.Material.Metal, Enum.PartType.Cylinder)
		p(Vector3.new(10.8, 1, 1), CFrame.new(0, 3.1, -5.2), DV.BLACK, Enum.Material.Metal, Enum.PartType.Cylinder)
		p(Vector3.new(9.6, 1, 7.4), CFrame.new(0, 6.3, -4.2), DV.YELLOW)
		p(Vector3.new(6, 4.2, 5), CFrame.new(0, 7.7, 3.2), DV.YELLOW)
		p(Vector3.new(6.1, 2, 4.2), CFrame.new(0, 8.3, 3.2), DV.BLACK, Enum.Material.Glass)
		p(Vector3.new(6.6, 0.5, 5.6), CFrame.new(0, 10, 3.2), DV.BLACK)
		for side = -1, 1, 2 do
			p(Vector3.new(1.4, 5, 5), CFrame.new(side * 4.9, 2.5, 5.4), DV.BLACK, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		end
		p(Vector3.new(0.5, 3, 0.5), CFrame.new(2.6, 8.8, -0.6), DV.BLACK, Enum.Material.Metal)
		local plate = p(Vector3.new(0.2, 2.2, 7), CFrame.new(4.62, 3.8, 1.6), DV.YELLOW)
		local sg = Instance.new("SurfaceGui")
		sg.Face = Enum.NormalId.Right
		sg.CanvasSize = Vector2.new(560, 180)
		sg.LightInfluence = 0.3
		sg.Parent = plate
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.Font = Enum.Font.LuckiestGuy
		label.TextScaled = true
		label.Text = "ROAD ROLLER"
		label.TextColor3 = DV.BLACK
		label.Parent = sg
		local r = { model = m, parts = parts }
		function r.set(newCf)
			for _, e in parts do
				e.part.CFrame = newCf * e.off
			end
			r.cf = newCf
		end
		r.cf = cf
		return r
	end

	-- ULT 3: ROAD ROLLER DA!
	function Effects.RoadRoller(char)
		local root = charParts(char)
		if root then
			dustPuffs(groundPoint(root.Position), 1, 5, Color3.fromRGB(206, 198, 188), 0.7, true)
		end
	end
	function Effects.RoadRollerGo(char, data)
		local root = charParts(char)
		local spot = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not spot then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or Vector3.new(0, 0, -1)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local mine = me()
		if mine == char or mine == target then
			VFX.Cinematic(char, SHOTS.RoadRoller, { Title = "ROAD ROLLER DA!", Color = DV.GOLD, Own = mine == char })
		end
		VFX.Pose(char, "Wry", 0.9)
		local t0 = os.clock()
		local function at_(t)
			local left = t - (os.clock() - t0)
			if left > 0 then
				task.wait(left)
			end
		end
		at_(0.35)
		VFX.SpeechBubble(char, (Config.Voice.RoadRoller or {}).Bubble or "ROAD ROLLER DA!!", 1.4)
		VFX.Voice("RoadRoller", root)
		local rot = CFrame.lookAt(Vector3.zero, d)
		local roller = DV.roller(CFrame.new(spot + UP * 46) * rot * CFrame.Angles(math.rad(-20), 0, 0))
		DV.rollers[char] = roller
		at_(0.55)
		-- down, with him on it
		local from = roller.cf
		local land = CFrame.new(spot) * rot * CFrame.Angles(math.rad(-6), 0, math.rad(4))
		while os.clock() - t0 < 0.89 do
			local k = math.clamp((os.clock() - t0 - 0.55) / 0.34, 0, 1) ^ 1.8
			roller.set(from:Lerp(land, k))
			task.wait()
		end
		roller.set(land)
		shockDisc(spot + UP * 0.5, UP, 8, 60, 0.45, WIND)
		dustPuffs(spot, 2.6, 12, Color3.fromRGB(206, 196, 186), 1.4, true)
		rocks(spot, 2.4, 18)
		groundMark(spot, 9, Color3.fromRGB(52, 46, 44), 8)
		VFX.PlaySound("RoadRollerLand", spot, 1.2)
		VFX.ShakeAt(spot, 4, 200, 0.5)
		-- MUDA MUDA MUDA on it
		local st = CDV and CDV.act(char, "barrage", 1.25)
		if st then
			CDV.shout(st, "MUDA MUDA MUDA!!", 9, 1.25)
		end
		local hits = tonumber(data.Hits) or 10
		for i = 1, hits do
			if not root.Parent then
				break
			end
			VFX.Pose(char, i % 2 == 0 and "MudaDownL" or "MudaDownR", 0.1)
			local top = roller.cf * CFrame.new(rand(-3, 3), 6.4, rand(-6, 0))
			sparks(top.Position, 0.8, Color3.new(1, 1, 1), DV.GOLD, 8)
			roller.set(roller.cf * CFrame.new(0, -0.12, 0) * CFrame.Angles(math.rad(rand(-1, 1)), 0, math.rad(rand(-1, 1))))
			VFX.PlaySound("Dora", top.Position, 0.8)
			if i % 3 == 0 then
				VFX.PlaySound("MachineHit", top.Position, 0.7)
				VFX.ShakeAt(spot, 1.4, 90, 0.12)
			end
			task.wait(0.12)
		end
		if root.Parent then
			VFX.Pose(char, "Wry", 0.9)
			VFX.SpeechBubble(char, (Config.Voice.Wry or {}).Bubble or "WRYYYYYYY!!", 1.4)
			VFX.Voice("Wry", root)
		end
	end
	function Effects.RoadRollerBoom(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local roller = DV.rollers[char]
		DV.rollers[char] = nil
		if roller then
			for _, e in roller.parts do
				local part = e.part
				if part.Parent then
					part.Anchored = false
					part.CanCollide = false
					part.AssemblyLinearVelocity = rng:NextUnitVector() * rand(20, 50) + UP * rand(30, 70)
					part.AssemblyAngularVelocity = rng:NextUnitVector() * 8
					tween(part, 0.6, { Transparency = 1 }, nil, nil, 0.8)
				end
			end
			cleanup(roller.model, 1.5)
		end
		toonExplosion(pos + UP * 3, 3.2)
		shockDisc(pos + UP * 0.5, UP, 8, 90, 0.55, DV.GOLD)
		billboardRing(pos + UP * 4, 4, 50, Color3.new(1, 1, 1), 12, 0.4)
		if nearCamera(pos, 180) then
			VFX.ImpactFrame(0.12)
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 190), 0.4)
		end
		VFX.PlaySound("RoadRollerBoom", pos, 1.2)
		VFX.ShakeAt(pos, 5, 260, 0.9)
	end

	-- dashes and the awakening
	QUIRK_FX.Dash.TheWorld = function(char, root, dir)
		afterimage(char, DV.GOLD, 0.25)
		streaks(root.Position, -dir, 4, 1.2, 5, 8, DV.GOLD, 0.2)
	end
	QUIRK_FX.Ult.TheWorld = function(char, root, g)
		local st = CDV and CDV.act(char, "rage", 1.6)
		if st then
			CDV.shout(st, "WRYYYYYY!!", 9, 1.6)
		end
		VFX.Pose(char, "Wry", 1.2)
		shockDisc(g + UP * 0.5, UP, 4, 70, 0.55, DV.GOLD)
		billboardRing(root.Position + UP * 2, 3, 40, DV.NEG, 10, 0.45)
	end
end

---------------------------------------------------------------------------
-- (round 75) PRIME DEKU's FLASH STEP, slowed down and shot like the anime:
-- he GLITCHES out (the body flickering, a green and a magenta copy torn off
-- either side of him, scanlines through him) - and when he's behind her it
-- glitches him back in, slow: the camera walks round from the left of her
-- face to behind her shoulder where he's standing, cuts wide as the right
-- arm draws back with the lightning running up it, and the big punch
---------------------------------------------------------------------------
do
	local PV = VFX.PV
	PV.MAGENTA = Color3.fromRGB(255, 70, 210)
	PV.glitching = setmetatable({}, { __mode = "k" }) -- [char] = token

	function PV.me()
		return Players.LocalPlayer and Players.LocalPlayer.Character
	end
	function PV.setShown(char, shown)
		for _, d in char:GetDescendants() do
			if (d:IsA("BasePart") or d:IsA("Decal")) and d.Name ~= "HumanoidRootPart" then
				d.LocalTransparencyModifier = shown and 0 or 1
			end
		end
	end

	-- the big punch: drawn right back (chest turned away, eyes still on her),
	-- then thrown through - chest round, the arm dead straight
	POSES.PrimeBigPunchWind = {
		Crouch = 0.55, Waist = { -8, -40, 0 }, Neck = { -4, 32, 0 },
		RightArm = { -62, 0, 30 }, LeftArm = { 80, 0, -12 }, RightElbow = 110, LeftElbow = 20,
		RightLeg = { -30, 0, 10 }, LeftLeg = { 32, 0, 6 }, LeftKnee = 40,
	}
	POSES.PrimeBigPunch = {
		Crouch = 0.45, Waist = { -18, 44, 0 }, Neck = { -6, -34, 0 },
		RightArm = { 100, 0, -6 }, LeftArm = { -40, 0, 28 }, LeftElbow = 60,
		RightLeg = { -36, 0, 8 }, LeftLeg = { 42, 0, 4 }, LeftKnee = 50,
	}

	-- glitching: `mode` "out" (there less and less) or "in" (more and more);
	-- he's left shown at the end either way (the caller hides him)
	function PV.glitch(char, duration, mode)
		local root = charParts(char)
		if not root then
			return
		end
		local token = {}
		PV.glitching[char] = token
		local body = {}
		for _, name in { "Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg", "UpperTorso", "LowerTorso" } do
			local p = char:FindFirstChild(name)
			if p and p:IsA("BasePart") then
				table.insert(body, p)
			end
		end
		VFX.PlaySound("StaticCrackle", root.Position, 1)
		VFX.PlaySound("Blink", root.Position, 0.7)
		local t0 = os.clock()
		while os.clock() - t0 < duration and PV.glitching[char] == token and char.Parent do
			local k = (os.clock() - t0) / duration
			local there = mode == "out" and 1 - k or k
			PV.setShown(char, rng:NextNumber() < 0.2 + 0.65 * there)
			-- the colour split: a green copy torn off one way, magenta the other
			local right = root.CFrame.RightVector
			local shift = (0.25 + 0.7 * (1 - there)) * (rng:NextNumber() < 0.5 and -1 or 1)
			for _, p in body do
				for s, color in { PV.GREEN, PV.MAGENTA } do
					local g = newPart(p.Size * 1.02, p.CFrame + right * shift * (s == 1 and 1 or -1) + UP * rand(-0.12, 0.12), color, Enum.Material.Neon)
					g.Transparency = 0.5
					cleanup(g, 0.05)
				end
			end
			-- torn scanlines through him, slid sideways
			for _ = 1, 3 do
				local bar = newPart(Vector3.new(rand(1.5, 4.5), rand(0.08, 0.3), 1.3), root.CFrame * CFrame.new(rand(-1.4, 1.4), rand(-2.6, 1.8), 0), rng:NextNumber() < 0.5 and Color3.new(1, 1, 1) or PV.GREEN, Enum.Material.Neon)
				bar.Transparency = 0.2
				cleanup(bar, 0.04)
			end
			if rng:NextNumber() < 0.35 then
				bolt(root.Position, 2.5, PV.GREEN)
			end
			task.wait(0.035)
		end
		if PV.glitching[char] == token then
			PV.glitching[char] = nil
			PV.setShown(char, true)
		end
	end

	-- (target space: she's at the origin facing -Z; he appears 3.3 behind her
	-- at +Z, facing her back - so HIS left is -X.) From the left side of his
	-- face as he glitches in, round his left side to behind him, looking past
	-- his shoulder at her back - at an even pace (short Linear legs)
	function PV.orbitShots()
		local orbit = {}
		local steps, total = 6, 0.75
		local head = V(0, 1.2, 3.3) -- (crouched: his head's low)
		local function point(k)
			local phi = math.rad(50 + 155 * k)
			local r = 4.2 + 3 * k
			return head + V(-r * math.sin(phi), 0.1 + 2.4 * k, -r * math.cos(phi))
		end
		local function lookAt(k)
			local e = math.clamp((k - 0.35) / 0.65, 0, 1)
			e = e * e * (3 - 2 * e)
			return head:Lerp(V(0, 1.4, 0), e)
		end
		-- (on the left side of his face while he glitches in, easing in a little)
		table.insert(orbit, { T = 0.8, From = { point(0) + V(-0.5, 0, -0.4), lookAt(0) }, To = { point(0), lookAt(0) }, Fov = { 48, 46 } })
		for i = 1, steps do
			local a, b = (i - 1) / steps, i / steps
			table.insert(orbit, {
				T = total / steps, Style = Enum.EasingStyle.Linear,
				From = { point(a), lookAt(a) }, To = { point(b), lookAt(b) },
				Fov = { 46 + 6 * a, 46 + 6 * b },
			})
		end
		-- (holding over his shoulder: her back, his fist about to come past the camera)
		table.insert(orbit, { T = 0.1, From = { point(1), lookAt(1) }, To = { point(1) + V(0, -0.05, -0.2), lookAt(1) }, Fov = { 52, 51 } })
		-- wide, low, from his right as the arm draws back
		table.insert(orbit, { T = 0.45, Cut = true, From = { V(8.5, 1.2, 2.2), V(0, 1.9, 1.7) }, To = { V(7.6, 1.3, 2), V(0, 1.9, 1.7) }, Fov = { 56, 50 } })
		-- the punch: she's gone down the street
		table.insert(orbit, { T = 0.75, Cut = true, From = { V(16, 3.5, 5), V(0, 2, -4) }, To = { V(20, 6, -6), V(0, 3, -28) }, Fov = { 62, 76 }, Style = Enum.EasingStyle.Quad })
		return orbit
	end
	SHOTS.FlashBehind = PV.orbitShots()

	-- 1: FLASH STEP - he glitches out
	function Effects.PrimeFlashStep(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local g = groundPoint(root.Position)
		dustPuffs(g, 1, 6, Color3.fromRGB(200, 196, 186), 0.7, true)
		shockDisc(g + UP * 0.3, UP, 2, 16, 0.25, PV.GREEN)
		for _ = 1, 4 do
			bolt(root.Position, 4, PV.GREEN)
		end
		VFX.PlaySound("FlashStep", root.Position, 1)
		if isLocal then
			VFX.Hooks.Flash(PV.GREEN, 0.1)
		end
		PV.glitch(char, 0.24, "out")
		if PV.hidden[char] == nil and char.Parent then
			afterimage(char, PV.MAGENTA, 0.3)
			afterimage(char, PV.GREEN, 0.45)
			streaks(root.Position, UP, 10, 1.5, 6, 10, PV.GREEN, 0.25)
			PV.hideWhile(char, 4.5)
		end
	end

	-- nobody in the ring: the old landing, glitched in
	PV.landing = Effects.FlashAppear
	function Effects.FlashAppear(char, data)
		PV.landing(char, data)
		PV.glitch(char, 0.2, "in")
	end

	-- someone in the ring: BEHIND them, slow
	function Effects.FlashBehind(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not troot or not at then
			return
		end
		local look = typeof(data.Look) == "Vector3" and data.Look or troot.CFrame.LookVector
		local strike = tonumber(data.Strike) or 2.1
		local place = tonumber(data.Place) or 0.34
		-- (he stays gone till the glitch brings him back, whatever the server says)
		PV.hidden[char] = nil
		PV.glitching[char] = nil
		PV.setShown(char, false)
		local mine = PV.me()
		if mine == char or mine == target then
			VFX.Cinematic(target, SHOTS.FlashBehind, { Title = data.Name or "FLASH STEP", Subtitle = "BEHIND YOU", Color = PV.GREEN, Own = mine == char, Face = troot.Position + look * 10 })
			PV.drain(strike + 0.1, 0.8)
		elseif mine then
			local mr = mine:FindFirstChild("HumanoidRootPart")
			if mr and (mr.Position - troot.Position).Magnitude < 55 then
				VFX.Cinematic(mine, witnessShots((mr.Position - troot.Position).Magnitude), { Title = data.Name or "FLASH STEP", Color = PV.GREEN, Face = troot.Position })
			end
		end
		VFX.Hitstop(target, strike - 0.05) -- (she's caught mid-step)
		VFX.PlaySound("FlashStep", at, 0.8)
		local t0 = os.clock()
		local function at_(t)
			local left = t - (os.clock() - t0)
			if left > 0 then
				task.wait(left)
			end
		end
		-- static crackling where he's going to be
		at_(0.06)
		PV.gather(at + UP * 0.5, PV.GREEN, math.max(place - 0.1, 0.08))
		at_(place)
		if char.Parent then
			VFX.Pose(char, "FlashCrouch", 0.95)
			task.spawn(PV.glitch, char, 0.36, "in")
		end
		VFX.PlaySound("FlashAppear", at, 0.7)
		at_(place + 0.45)
		if target.Parent then
			VFX.Pose(target, "LookBack", strike - place)
		end
		-- he rises out of the crouch, the right arm drawing all the way back...
		at_(1.25)
		if char.Parent then
			VFX.Pose(char, "PrimeBigPunchWind", strike - 1.25)
			VFX.PlaySound("MuscleRumble", at, 0.7)
		end
		while os.clock() - t0 < strike - 0.06 and char.Parent do
			-- ...the lightning running up it into the fist, the air drawn in
			local hand = limb(char, "RightHand", "Right Arm")
			local shoulder = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
			if hand then
				local fist = hand.Position - hand.CFrame.UpVector * 0.8
				bolt(fist, 1.6, PV.GREEN)
				bolt(fist, 1, PV.CORE)
				if shoulder then
					bolt(shoulder.Position:Lerp(fist, rng:NextNumber()), 1.2, PV.GREEN)
				end
				local from = fist + rng:NextUnitVector() * rand(3, 6)
				streaks(from, (fist - from).Unit, 1, 0.5, 3, (fist - from).Magnitude, PV.CORE, 0.15)
			end
			task.wait(0.04)
		end
		-- ...and through her
		if char.Parent then
			VFX.Pose(char, "PrimeBigPunch", 0.6)
		end
	end

	-- the big punch lands
	PV.kickLands = Effects.FlashStrike
	function Effects.FlashStrike(char, data)
		PV.kickLands(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01 and data.Dir.Unit or UP
		local pos = troot and troot.Position or (typeof(data.Pos) == "Vector3" and data.Pos)
		if not pos then
			return
		end
		local mine = PV.me()
		if mine == char or mine == target then
			VFX.ImpactFrame(0.16)
		end
		-- a colossal fist of green light thrown on down the street after her
		local side = d:Cross(UP)
		side = side.Magnitude > 0.05 and side.Unit or Vector3.new(1, 0, 0)
		local f = PV.fist(CFrame.fromMatrix(pos - d * 2, side, -d), 4.5, PV.GREEN)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < 0.35 do
				local k = (os.clock() - t0) / 0.35
				f.set(CFrame.fromMatrix(pos + d * (40 * k), side, -d))
				task.wait()
			end
			f.gone(0.25)
		end)
		moonArc(CFrame.lookAt(pos, pos + d), 9, PV.GREEN, 300)
		shockDisc(pos, d, 4, 44, 0.45, PV.CORE, 18)
		billboardRing(pos, 4, 40, Color3.new(1, 1, 1), 12, 0.4)
		VFX.PlaySound("DetroitImpact", pos, 1)
		VFX.ShakeAt(pos, 4, 140, 0.55)
	end
end

-- (round 76) the longer charges for the voice lines: UNITED STATES OF
-- SMASH's fist stays cocked (and the camera stays on it) through "UNITED
-- STATES OF...", and Bakugo stays coiled in Explosive Speed's crouch through
-- "I'M THE FINAL BOSS, GOT IT?"
do
	local uss = Config.FindAbilityById and Config.FindAbilityById("UnitedStatesSmash")
	local extra = math.max(((uss and uss.ChargeTime) or 0.95) - 0.95, 0)
	if extra > 0 then
		local m = MOTIONS.UnitedStatesSmash
		m[1].hold += extra * 0.7
		m[2].hold += extra * 0.3
		local shots = SHOTS.UnitedStatesSmash
		shots[1].T += extra * 0.6
		shots[2].T += extra * 0.4
	end
	local es = Config.FindAbilityById and Config.FindAbilityById("ExplosiveSpeed")
	local more = math.max(((es and es.WindUp) or 0.7) - 0.7, 0)
	if more > 0 and MOTIONS.BlitzCrouch then
		MOTIONS.BlitzCrouch[2].hold += more
	end
end

---------------------------------------------------------------------------
-- (round 78) UNITED STATES OF SMASH, the way it went against All For One at
-- Kamino (anime ep. 49 / manga ch. 94): the left is a decoy that lands on
-- his face; the last embers of One For All go into the right arm while All
-- Might ducks low; the overhand right lands on the face - an impact frame,
-- everything stops - and it drives him down into the street. A twister
-- climbs out of the crater; All Might raises his fist.
-- Its beats come from the server: the press (UnitedStatesSmash: the lunge),
-- then USSWhiff (nobody caught) or USSCatch (caught: the build, then the
-- strike Build seconds later, frozen for Freeze), then USSSlam (the street).
-- R6 bodies play the keyframed clips (ReplicatedStorage.Animations:
-- MoveUSSLunge / Whiff / Build / Smash / Victory - open them in Studio's
-- Animation Editor or Moon Animator); anything else these motions.
---------------------------------------------------------------------------
do
	local USS = {
		lunges = setmetatable({}, { __mode = "k" }), -- [char] = the lunge going (its stop())
		caught = setmetatable({}, { __mode = "k" }), -- [char] = the catch going
	}
	VFX.USS = USS

	MOTIONS.USSLunge = {
		{ pose = { Waist = { -10, 25, 0 }, LeftArm = { -30, 0, 20 }, RightArm = { 30, 0, 20 }, RightLeg = -20, LeftLeg = 25, LeftKnee = 30 }, t = 0.1, hold = 0.06 },
		{ pose = { Waist = { -25, -35, 0 }, LeftArm = 95, RightArm = { -20, 0, 30 }, RightLeg = -40, LeftLeg = 45, LeftKnee = 40 }, t = 0.07, hold = 0.4, style = Enum.EasingStyle.Back },
		recover = 0.3,
	}
	MOTIONS.USSWhiff = {
		{ pose = { Waist = { -40, -30, 0 }, LeftArm = 70, RightArm = { -30, 0, 40 }, RightLeg = -45, LeftLeg = 55, LeftKnee = 50 }, t = 0.12, hold = 0.25 },
		recover = 0.35,
	}
	MOTIONS.USSBuild = {
		{ pose = { Waist = { -15, -45, 0 }, RightArm = { 160, 0, 35 }, RightElbow = 90, LeftArm = 92, RightLeg = -35, LeftLeg = 40, LeftKnee = 55, RightKnee = 35 }, t = 0.3, hold = 1.6 },
		recover = 0.2,
	}
	MOTIONS.USSSmash = {
		{ pose = { Waist = { -30, 40, 0 }, RightArm = 80, LeftArm = { -35, 0, 30 }, RightLeg = -40, LeftLeg = 50, LeftKnee = 45 }, t = 0.06, hold = 0.1, style = Enum.EasingStyle.Back },
		{ pose = { Waist = { -50, 35, 0 }, RightArm = 30, LeftArm = { -45, 0, 40 }, RightLeg = -50, LeftLeg = 65, LeftKnee = 80, RightKnee = 20 }, t = 0.08, hold = 0.5 },
		recover = 0.35,
	}
	MOTIONS.USSVictory = {
		{ pose = { RightArm = { 175, 0, 5 }, LeftArm = { 10, 0, 15 }, Waist = { 6, 6, 0 }, Neck = { 15, 0, 0 } }, t = 0.3, hold = 1.3, style = Enum.EasingStyle.Back },
		recover = 0.35,
	}

	-- the caster's cutscene, from the catch: the decoy landing, the embers
	-- pouring into his arm from low behind him, the fist on the face (the
	-- freeze), the street going, and the twister climbing out of it
	function USS.shots(build, freeze, slam)
		return {
			{ T = 0.55, From = { V(8, 1.5, -2.2), V(0, 1.2, -2.6) }, To = { V(7, 1.7, -2.4), V(0, 1.3, -2.6) }, Fov = { 48, 44 } },
			{ T = math.max(build - 0.55, 0.3), Cut = true, From = { V(3.2, -2.5, 4.5), V(0, 2.5, -4) }, To = { V(2.6, -2.8, 3.4), V(0, 3, -4) }, Fov = { 62, 54 } },
			{ T = freeze, Cut = true, From = { V(-6, 1.6, -3.2), V(0, 1.6, -4.2) }, To = { V(-5.6, 1.6, -3.3), V(0, 1.6, -4.2) }, Fov = { 34, 32 } },
			{ T = slam + 0.3, Cut = true, From = { V(16, 14, 6), V(0, -3, -5) }, To = { V(18, 18, 9), V(0, -3, -5) }, Fov = { 70, 74 } },
			{ T = 1.7, Cut = true, From = { V(-10, 4, 55), V(0, 15, -5) }, To = { V(-14, 40, 95), V(0, 90, -5) }, Fov = { 70, 78 }, Style = Enum.EasingStyle.Quad },
		}
	end
	SHOTS.USSCatch = USS.shots(2, 0.38, 0.12)

	-- The anime's impact frames: blown out white, stark black and white, a
	-- beat of red, then black and white held till the world moves again
	local frameToken = 0
	function USS.impactFrame(duration)
		frameToken += 1
		local token = frameToken
		local Lighting = game:GetService("Lighting")
		local cc = Lighting:FindFirstChild("USSImpactFrame")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "USSImpactFrame"
			cc.Parent = Lighting
		end
		cc.Saturation = -1
		cc.Enabled = true
		local steps = {
			{ 0.05, 0.55, 3, Color3.new(1, 1, 1) },
			{ 0.06, -0.3, 3.2, Color3.new(1, 1, 1) },
			{ 0.06, -0.05, 2.6, Color3.fromRGB(255, 70, 50) },
			{ math.max(duration - 0.17, 0.05), 0.08, 2.2, Color3.new(1, 1, 1) },
		}
		task.spawn(function()
			for _, step in steps do
				if frameToken ~= token then
					return
				end
				cc.Brightness, cc.Contrast, cc.TintColor = step[2], step[3], step[4]
				task.wait(step[1])
			end
			if frameToken == token then
				cc.Enabled = false
				cc.TintColor = Color3.new(1, 1, 1)
			end
		end)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
	end

	-- the dust wall the slam throws out: two-tone cel-shaded puffs rolling
	-- out in a ring
	function USS.dustWall(pos, radius)
		local model = Instance.new("Model")
		model.Name = "USSDust"
		model.Parent = folder
		local DARK, LIGHT = Color3.fromRGB(170, 156, 140), Color3.fromRGB(226, 218, 206)
		for i = 1, 22 do
			local a = i / 22 * math.pi * 2 + rand(-0.1, 0.1)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local size = rand(7, 12)
			celPuff(model, pos + out * 4 + UP * 2, pos + out * radius * rand(0.75, 1) + UP * size * 0.35, size, DARK, LIGHT, 0.45, rand(1.2, 1.8), rand(0, 0.06))
		end
		cleanup(model, 3)
	end

	-- the lunge's push (its own, named: a catch or a whiff stops it early)
	local function push(root, velocity, time)
		for _, old in root:GetChildren() do
			if old.Name == "USSLunge" then
				old:Destroy()
			end
		end
		local att = Instance.new("Attachment")
		att.Name = "USSLunge"
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Name = "USSLunge"
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 6000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.VectorVelocity = velocity
		lv.Parent = root
		cleanup(lv, time)
		cleanup(att, time)
		return function()
			lv:Destroy()
			att:Destroy()
		end
	end

	-- the press: the decoy left, lunging in (his own screen carries him; it
	-- stops short of a body rather than running through it)
	function Effects.UnitedStatesSmash(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("UnitedStatesSmash") or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "USSLunge")
		local lunge = {}
		USS.lunges[char] = lunge
		task.wait(ability.LungeStartup or 0.16)
		if USS.lunges[char] ~= lunge or not root.Parent then
			return
		end
		VFX.PlaySound("HeavySwing", root.Position, 1)
		afterimage(char, GOLD, 0.3)
		streaks(root.Position + UP, -d, 6, 1.6, 8, 14, WIND, 0.3)
		if isLocal and hum then
			local time = ability.LungeTime or 0.32
			local stop = push(root, d * ((ability.Lunge or 26) / math.max(time, 0.05)), time)
			lunge.stop = stop
			local t0 = os.clock()
			while os.clock() - t0 < time and USS.lunges[char] == lunge and root.Parent do
				if bodyAhead(root, d, 4.2) then
					stop()
					root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
					break
				end
				task.wait()
			end
		end
	end

	local function endLunge(char)
		local lunge = USS.lunges[char]
		USS.lunges[char] = nil
		if lunge and lunge.stop then
			lunge.stop()
		end
	end

	-- nobody caught: he over-reaches and stumbles out of it
	function Effects.USSWhiff(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		endLunge(char)
		local d = flatten(data.Dir, root)
		VFX.Motion(char, "USSWhiff")
		VFX.PlaySound("USSWhiff", root.Position, 1)
		dustPuffs(groundPoint(root.Position + d * 3), 1, 4, Color3.fromRGB(206, 196, 186), 0.8, true)
	end

	-- caught: the decoy lands on the face, then "UNITED STATES OF..." while the
	-- last embers pour into his right arm - and the strike, Build seconds on
	function Effects.USSCatch(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local ability = Config.FindAbilityById(data.Id or "UnitedStatesSmash") or {}
		local build = tonumber(data.Build) or ability.BuildTime or 2
		local freeze = tonumber(data.Freeze) or ability.FreezeTime or 0.38
		local slam = tonumber(data.Slam) or ability.SlamTime or 0.12
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local d = flatten(data.Dir, root)
		local me = Players.LocalPlayer
		local mine = me ~= nil and me.Character == char
		endLunge(char)
		if mine then
			face(root, d)
			root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
		end
		local catch = { target = target, at = os.clock() }
		USS.caught[char] = catch
		-- the decoy, on the face
		local hit = (troot and troot.Position or (root.Position + d * 4.6)) + UP * 1.4
		VFX.Hitstop(char, 0.1)
		if target then
			VFX.Hitstop(target, 0.1)
			VFX.Pose(target, "Stagger", build)
		end
		shockDisc(hit, -d, 1.5, 12, 0.22, WIND)
		billboardRing(hit, 2, 14, Color3.new(1, 1, 1), 6, 0.2)
		VFX.PlaySound("USSJab", hit, 1)
		VFX.ShakeAt(hit, 1.5, 120, 0.25)
		-- the camera: his cutscene; a witness cut for anyone close by
		SHOTS.USSCatch = USS.shots(build, freeze, slam)
		cinematicFor(char, "USSCatch", mine, ability.Name or "UNITED STATES OF SMASH", GOLD)
		if mine then
			VFX.Hooks.Dim(0.45, build + 0.05)
		end
		-- "UNITED STATES OF..." - "SMASH!!" lands on the punch
		VFX.Voice("MightUSS", root, build)
		VFX.PlaySound("USSCharge", root.Position, 0.8)
		if build > 1.4 then
			task.delay(build - 1.2, function()
				if root.Parent and USS.caught[char] == catch then
					VFX.PlaySound("USSCharge", root.Position, 0.8)
				end
			end)
		end
		-- he steps in under them, the right fist cocked high (held there)
		MOTIONS.USSBuild[1].hold = math.max(build - 0.36, 0.2)
		if not (Anim.MoveClips ~= false and VFX.Clip(char, "MoveUSSBuild", { holdFor = math.max(build - 0.56, 0), recover = 0.3 })) then
			VFX.Motion(char, "USSBuild")
		end
		-- the embers pour into the right arm; the air's drawn in to the fist
		local unswell = swell(char, { { "RightUpperArm", "Right Arm" }, { "RightLowerArm", "" }, { "RightHand", "" } }, GOLD, 1.35)
		task.spawn(function()
			local t1 = os.clock()
			while os.clock() - t1 < build and root.Parent and USS.caught[char] == catch do
				local k = (os.clock() - t1) / build
				local hand = handPos(char, true)
				bolt(hand, 2 + 2 * k, GOLD)
				bolt(hand, 1.5, Color3.new(1, 1, 1))
				if rng:NextNumber() < 0.35 + 0.4 * k then
					local from = hand + rng:NextUnitVector() * rand(10, 18)
					streaks(from, (hand - from).Unit, 1, 0.3, 4, (hand - from).Magnitude, WIND, 0.25)
				end
				if rng:NextNumber() < 0.2 then
					VFX.PlaySound("Spark", hand, 0.5)
				end
				task.wait(0.04)
			end
			unswell(0.4)
		end)
		-- the overhand right: swung just before it lands...
		task.delay(math.max(build - 0.06, 0), function()
			if USS.caught[char] == catch and root.Parent then
				VFX.Motion(char, "USSSmash")
			end
		end)
		-- ...and on the face: everything stops
		task.delay(build, function()
			if USS.caught[char] == catch and root.Parent then
				USS.strike(char, target, d, freeze, ability, mine)
			end
		end)
	end

	-- the overhand right on the face: the impact frame, and the world stops
	-- for `freeze` - the ult music drops out under it and comes back after
	function USS.strike(char, target, d, freeze, ability, mine)
		local root = charParts(char)
		if not root then
			return
		end
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local at = troot and (troot.Position + UP * 1.4) or (root.Position + d * 4.6 + UP * 2)
		VFX.Hitstop(char, freeze)
		if target then
			VFX.Hitstop(target, freeze)
		end
		if nearCamera(at, 260) then
			USS.impactFrame(freeze)
			if VFX.Hooks.DuckMusic then
				VFX.Hooks.DuckMusic(ability.MusicDuck or 0.15, 0.04, freeze + 0.15, 2.8)
			end
		end
		VFX.PlaySound("USSStrike", at, 1)
		local flash = newPart(Vector3.one * 2, CFrame.new(at), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(flash, 0.1, { Size = Vector3.one * 7, Transparency = 0.2 })
		task.delay(freeze, function()
			if flash.Parent then
				tween(flash, 0.15, { Size = Vector3.one * 11, Transparency = 1 })
			end
		end)
		cleanup(flash, freeze + 0.2)
		for i = 1, 3 do
			task.delay((i - 1) * 0.04, function()
				shockDisc(at, d, 2 + i, 18 + i * 10, 0.3 + i * 0.05, i == 2 and GOLD or WIND)
			end)
		end
		streaks(at, d, 14, 2.4, 10, 30, WIND, 0.35)
		VFX.ShakeAt(at, 3, 160, 0.4)
		if mine then
			VFX.Hooks.SpeedLines(freeze + 0.3)
		end
	end

	-- down through them into the street: the crater, the wind pressure
	-- rolling out, the twister climbing out of it - then the raised fist,
	-- and "You're next."
	function Effects.USSSlam(char, data)
		local root = charParts(char)
		local ability = Config.FindAbilityById(data.Id or "UnitedStatesSmash") or {}
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and groundPoint(root.Position))
		if not pos then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or Vector3.new(0, 0, -1)
		if root then
			USS.caught[char] = nil
		end
		if nearCamera(pos, 200) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.4)
		end
		windBlast(pos + UP * 3, (d - UP * 1.2).Unit, 2.4)
		for i = 1, 6 do
			task.delay(i * 0.05, function()
				shockDisc(pos + UP * (0.5 + i * 0.6), UP, 12, 150, 0.8, WIND)
			end)
		end
		shockDisc(pos + UP * 0.5, UP, 8, 95, 0.55, GOLD)
		billboardRing(pos + UP * 2, 4, 60, GOLD, 12, 0.45)
		USS.dustWall(pos, ability.WindRadius or 46)
		streaks(pos, UP, 50, 12, 22, 130, WIND, 0.6)
		rocks(pos, 3.5, 30)
		groundMark(pos, 26, Color3.fromRGB(52, 46, 44), 10)
		VFX.PlaySound("MightUSSImpact", pos, 1)
		VFX.ShakeAt(pos, 4, 260, 0.9)
		-- the wind pressure becomes a twister
		twister(pos, ability.TwisterTime or 6.5, ability.TwisterTopRadius or 110, ability.TwisterHeight or 300)
		if not root then
			return
		end
		task.delay(0.75, function()
			if root.Parent then
				VFX.Motion(char, "USSVictory")
			end
		end)
		task.delay(2.9, function()
			if root.Parent then
				VFX.Motion(char, "YoureNext")
				local me = Players.LocalPlayer
				if me and me.Character == char then
					VFX.Hooks.Callout("YOU'RE NEXT.", GOLD)
				end
			end
		end)
	end
end

return VFX
